def get_weak_setup_min_edge() -> float:
    """Post-AI WEAK_SETUP floor; defaults to dashboard edge threshold (keeps UI and execution aligned)."""
    raw = (os.getenv("WEAK_SETUP_MIN_EDGE") or "").strip()
    if raw:
        try:
            return float(raw)
        except ValueError:
            pass
    return get_edge_threshold()
