def nz(x, default=None):
    if x is None or (isinstance(x, float) and (math.isnan(x) or math.isinf(x))):
        if default is not None:
            return float(default)
        logger.debug(f"[NZ] value was None/inf/nan - propagating None [PIPELINE ENFORCEMENT]")
        return None
    return float(x)

def safe_float(x, default=None):
    try:
        if x in ("", None, "None", "nan", "NaN"):
            logger.debug(f"[SAFE FLOAT] input was empty/None - propagating None [PIPELINE ENFORCEMENT]")
            return None
        return float(x)
    except:
        logger.debug(f"[SAFE FLOAT] conversion failed - propagating None [PIPELINE ENFORCEMENT]")
        return None

def safe_num(x):
    if x is None:
        logger.debug("[SAFE NUM] input None - returning None [PIPELINE ENFORCEMENT]")
        return None
    try:
        return round(float(x), 2)
    except:
        logger.debug("[SAFE NUM] conversion failed - returning None [PIPELINE ENFORCEMENT]")
        return None

def _ascii_fold_csv_text(s: str) -> str:
    """Normalize common unicode in AI comments so Windows CSV writes stay safe."""
    repl = {
        "\u2192": "->", "\u2190": "<-", "\u2265": ">=", "\u2264": "<=",
        "\u2014": "-", "\u2013": "-", "\u2018": "'", "\u2019": "'",
        "\u201c": '"', "\u201d": '"',
    }
    out = s
    for src, dst in repl.items():
        out = out.replace(src, dst)
    return out


def _console_log_stream():
    """UTF-8 console stream on Windows so StreamHandler never hits cp1252 encode errors."""
    if sys.platform == "win32":
        # Do not construct another TextIOWrapper around sys.stdout.buffer.
        # When a recovery/test reloads this module, garbage-collecting the old
        # wrapper closes the shared underlying console buffer and all later
        # logging/prints fail with "I/O operation on closed file".
        try:
            reconfigure = getattr(sys.stdout, "reconfigure", None)
            if callable(reconfigure):
                reconfigure(encoding="utf-8", errors="replace", line_buffering=True)
        except Exception:
            pass
    return sys.stdout


def safe_csv_row(row: dict) -> dict:
    clean = {}
    for k, v in row.items():
        if isinstance(v, float):
            clean[k] = round(v, 6) if not math.isnan(v) else ""
        elif v is None:
            clean[k] = ""
        elif isinstance(v, str):
            clean[k] = _ascii_fold_csv_text(v)
        else:
            clean[k] = v
    return clean

def fmt(x, digits=2):
    try:
        if x is None:
            return "None"
        return f"{float(x):.{digits}f}"
    except:
        return "None"

def compute_r(entry, sl, exit_price):
    if entry <= 0 or sl <= 0 or exit_price <= 0:
        return 0.0
    risk = abs(entry - sl)
    reward = abs(exit_price - entry)
    return reward / risk if risk > 0 else 0.0

def compute_tp(entry, side, target_pct, leverage):
    move = (target_pct / 100.0) / leverage
    if side == "LONG":
        return entry * (1 + move)
    else:
        return entry * (1 - move)

def _feature_bundle(pos: dict, master: dict = None):
    master = master or {}
    features = copy.deepcopy(master.get("features") or pos.get("features") or {})
    context = copy.deepcopy(master.get("context") or pos.get("context") or {})
    return features, context

def _compute_momentum_metric(features: dict) -> float:
    ret_1m = abs(float(features.get("ret_1m") or 0))
    ret_5m = abs(float(features.get("ret_5m") or 0))
    velocity = abs(float(features.get("velocity") or 0))
    return round(min(max(ret_1m * 5000, ret_5m * 2000, velocity * 8000), 1.0), 6)

def _signed_momentum_components(features: dict) -> tuple:
    features = features or {}
    return (
        float(features.get("ret_1m") or 0),
        float(features.get("ret_5m") or 0),
        float(features.get("velocity") or 0),
    )

def _tape_bounce_against(direction: str, features: dict) -> bool:
    if not features or direction not in ("LONG", "SHORT"):
        return False
    r1, r5, vel = _signed_momentum_components(features)
    eps = MOMENTUM_ALIGN_EPS
    if direction == "SHORT":
        return r1 > eps and r5 >= -eps and vel >= -eps
    if direction == "LONG":
        return r1 < -eps and r5 <= eps and vel <= eps
    return False

def evaluate_momentum_alignment(direction: str, features: dict) -> tuple:
    if not features:
        return False, None
    if _tape_bounce_against(direction, features):
        return True, "MOMENTUM_BOUNCE_BLOCK"
    mom = _compute_momentum_metric(features)
    r1, r5, vel = _signed_momentum_components(features)
    eps = MOMENTUM_ALIGN_EPS
    if direction == "SHORT":
        if mom < MOMENTUM_FLAT_MAX and r1 > eps:
            return True, "MOMENTUM_FLAT_BOUNCE_SHORT"
        if r5 > eps and vel > eps:
            return True, "MOMENTUM_COUNTER_TREND_SHORT"
    elif direction == "LONG":
        if mom < MOMENTUM_FLAT_MAX and r1 < -eps:
            return True, "MOMENTUM_FLAT_BOUNCE_LONG"
        if r5 < -eps and vel < -eps:
            return True, "MOMENTUM_COUNTER_TREND_LONG"
    return False, None

def _trim_oversized_log(path: str, max_bytes: int):
    try:
        if max_bytes > 0 and os.path.exists(path) and os.path.getsize(path) > max_bytes:
            os.remove(path)
    except Exception:
        pass

def prune_aux_logs_on_startup():
    _trim_oversized_log("near_edge.log", NEAR_EDGE_LOG_MAX_BYTES)
    for path in (_AGENT_DEBUG_LOG, _AGENT_DEBUG_LOG_ALT):
        _trim_oversized_log(path, AGENT_DEBUG_LOG_MAX_BYTES)

RESEARCH_SESSION_FILE = "research_session.json"

def _wipe_csv_on_startup() -> bool:
    return os.getenv("WIPE_CSV_ON_STARTUP", "").strip().lower() in ("1", "true", "yes")

def _preserve_research_data() -> bool:
    return os.getenv("PRESERVE_RESEARCH_DATA", "").strip().lower() in ("1", "true", "yes")

def _load_research_session_meta() -> dict:
    try:
        if os.path.isfile(RESEARCH_SESSION_FILE):
            with open(RESEARCH_SESSION_FILE, encoding="utf-8") as f:
                return json.load(f)
    except Exception:
        pass
    return {}


def _infer_fresh_collection_start_ts():
    """Recover fresh-collection anchor from latest verified archive wipe."""
    archive_root = "research_archive"
    if not os.path.isdir(archive_root):
        return None
    best_ts = None
    for name in os.listdir(archive_root):
        meta_path = os.path.join(archive_root, name, "archive_meta.json")
        if not os.path.isfile(meta_path):
            continue
        try:
            with open(meta_path, encoding="utf-8") as f:
                meta = json.load(f)
            if meta.get("reason") != "fresh_collection_dashboard":
                continue
            archived = meta.get("archived_ts")
            if not archived:
                continue
            ts = datetime.fromisoformat(str(archived).replace("Z", "+00:00")).timestamp()
            best_ts = max(best_ts or 0.0, float(ts))
        except Exception:
            continue
    return best_ts


def _research_data_start_ts() -> float:
    """Analysis window start: fresh-collection anchor when ON, else current process start."""
    with state_lock:
        fcm = bool(state.get("fresh_collection_mode", False))
    if fcm:
        meta = _load_research_session_meta()
        raw = meta.get("fresh_collection_start_time")
        if raw is not None:
            try:
                return float(raw)
            except (TypeError, ValueError):
                pass
    return float(bot_start_time or 0.0)


def _write_research_session(start_ts: float, fresh_collection_reset: bool = False):
    with state_lock:
        fcm = bool(state.get("fresh_collection_mode", False))
    prev = _load_research_session_meta()
    fresh_start = None
    fresh_iso = None
    fresh_iso_utc = None
    if fcm:
        if fresh_collection_reset or not prev.get("fresh_collection_mode"):
            fresh_start = float(start_ts)
        elif prev.get("fresh_collection_start_time") is not None:
            fresh_start = float(prev.get("fresh_collection_start_time"))
        else:
            recovered = _infer_fresh_collection_start_ts()
            fresh_start = float(recovered if recovered is not None else start_ts)
        fresh_iso = _timestamp_to_melbourne_display(fresh_start)
        fresh_iso_utc = datetime.fromtimestamp(fresh_start, tz=timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")
    bot_start_mel = _timestamp_to_melbourne_display(start_ts)
    bot_start_utc = datetime.fromtimestamp(start_ts, tz=timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")
    payload = {
        "bot_version": EXECUTION_FIX_VERSION,
        "analyzer_sync_id": ANALYZER_SYNC_ID,
        "bot_start_time": start_ts,
        "bot_start_iso": bot_start_mel,
        "bot_start_iso_utc": bot_start_utc,
        "display_timezone": "Australia/Melbourne",
        "fresh_collection_mode": fcm,
        "fresh_collection_start_time": fresh_start,
        "fresh_collection_start_iso": fresh_iso,
        "fresh_collection_start_iso_utc": fresh_iso_utc,
        "cwd": os.getcwd(),
        "launcher": "15minu_bot.py",
        # V3.1 is the canonical research contract.  Keep the V2.2 writer
        # identity separately because it remains the compatibility/migration
        # source for the dual-write bridge.
        "collector_version": COLLECTOR_V31_VERSION,
        "legacy_collector_version": COLLECTOR_V22_VERSION,
    }
    # A normal process restart must keep the bound collector identity whether
    # or not Fresh Collection mode is on.  Rebuilding research_session.json
    # without these fields made V2/V3 mint a per-process epoch-v22-* alias
    # that never matched the identity cache, so inventory could not become
    # CURRENT.  Only a new, explicitly confirmed reset may replace them.
    if not fresh_collection_reset:
        for key in (
            "collector_v22_epoch_ts",
            "collector_v22_epoch_id",
            "legacy_collector_version",
        ):
            if prev.get(key) not in (None, ""):
                payload[key] = prev.get(key)
    if fresh_collection_reset and fresh_start is not None:
        cutoff = _utc_isoformat_ns(float(fresh_start))
        material = f"fresh_research_epoch_v1|SHOWCASE_FRESH_COLLECTION|{cutoff}"
        fresh_epoch_id = "epoch-" + hashlib.sha256(material.encode("utf-8")).hexdigest()[:24]
        payload["collector_v22_epoch_ts"] = float(fresh_start)
        payload["collector_v22_epoch_id"] = fresh_epoch_id
        payload["collector_version"] = COLLECTOR_V31_VERSION
        payload["legacy_collector_version"] = COLLECTOR_V22_VERSION
    with _collection_epoch_bind_lock:
        _write_research_session_payload(payload)
    _refresh_collection_epoch_identity_cache()


# Serializes every research_session.json writer so an epoch bind can never be
# lost to (or race) a concurrent session rewrite.
_collection_epoch_bind_lock = threading.RLock()


class CollectionEpochUnbound(RuntimeError):
    """research_session.json carries no bound collection epoch."""

    code = "INVENTORY_EPOCH_UNBOUND"

    def __init__(self, detail: str = ""):
        super().__init__(f"{self.code}{': ' + detail if detail else ''}")


def _write_research_session_payload(payload: dict) -> None:
    """Atomically replace research_session.json.

    Readers must never observe a truncated file: an empty read looks unbound
    and would let a collector bind a second epoch mid-run.
    """
    target = os.path.abspath(RESEARCH_SESSION_FILE)
    tmp = f"{target}.tmp-{os.getpid()}-{threading.get_ident()}"
    with open(tmp, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2)
        handle.flush()
        try:
            os.fsync(handle.fileno())
        except OSError:
            pass
    os.replace(tmp, target)


def _bound_collection_epoch_id() -> str:
    """The single persisted collection epoch, or "" when unbound.

    Manifest, identity cache, WAL/bundle identity, ACK/promotion and cleanup
    identities all read this.  It never derives a replacement id.
    """
    session = _load_research_session_meta() or {}
    return str(session.get("collector_v22_epoch_id") or "").strip()


def _require_bound_collection_epoch_id() -> str:
    epoch_id = _bound_collection_epoch_id()
    if not epoch_id:
        raise CollectionEpochUnbound("research_session.json has no collector_v22_epoch_id")
    return epoch_id


def _refresh_collection_epoch_identity_cache() -> None:
    refresh = globals().get("_prime_data_sync_identity_epoch_cache")
    if callable(refresh):
        try:
            refresh()
        except Exception as exc:
            logger.warning(f"[COLLECTOR_V22] identity cache refresh failed: {exc}")

def _should_wipe_research_on_startup() -> bool:
    """v96: never auto-wipe research data — archive via dashboard Fresh Collection or WIPE_CSV_ON_STARTUP=1."""
    if _preserve_research_data():
        return False
    return _wipe_csv_on_startup()

class ArchiveIntegrityError(Exception):
    """Archive copy failed hash verification — wipe must not proceed."""


def _file_sha256(path: str) -> str:
    import hashlib
    digest = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def archive_research_session(reason: str = "manual") -> str:
    """Copy current research artifacts into research_archive/session_NNN before intentional wipe."""
    os.makedirs(RESEARCH_ARCHIVE_DIR, exist_ok=True)
    sessions = [
        d for d in os.listdir(RESEARCH_ARCHIVE_DIR)
        if d.startswith("session_") and os.path.isdir(os.path.join(RESEARCH_ARCHIVE_DIR, d))
    ]
    nums = []
    for name in sessions:
        parts = name.split("_", 1)
        if len(parts) == 2 and parts[1].isdigit():
            nums.append(int(parts[1]))
    next_num = (max(nums) if nums else 0) + 1
    dest = os.path.join(RESEARCH_ARCHIVE_DIR, f"session_{next_num:03d}")
    os.makedirs(dest, exist_ok=True)
    copied = []
    verified = []
    total_src_bytes = 0
    total_dest_bytes = 0
    for path in all_research_wipe_paths():
        if path and os.path.isfile(path):
            try:
                src_size = os.path.getsize(path)
                src_hash = _file_sha256(path)
                dest_name = os.path.basename(path)
                dest_path = os.path.join(dest, dest_name)
                if os.path.exists(dest_path):
                    stem, ext = os.path.splitext(dest_name)
                    dest_name = f"{stem}_{len(copied)}{ext or ''}"
                    dest_path = os.path.join(dest, dest_name)
                shutil.copy2(path, dest_path)
                dest_size = os.path.getsize(dest_path)
                dest_hash = _file_sha256(dest_path)
                if dest_hash != src_hash:
                    raise ArchiveIntegrityError(
                        f"sha256 mismatch {path}: src={src_hash} dest={dest_hash}"
                    )
                copied.append(dest_name)
                verified.append({
                    "file": dest_name,
                    "source": os.path.basename(path),
                    "size": src_size,
                    "sha256": src_hash,
                })
                total_src_bytes += src_size
                total_dest_bytes += dest_size
            except ArchiveIntegrityError:
                raise
            except Exception as e:
                logger.error(f"[ARCHIVE] copy failed {path}: {e}")
                raise ArchiveIntegrityError(f"copy failed {path}: {e}") from e
    if verified and total_src_bytes != total_dest_bytes:
        raise ArchiveIntegrityError(
            f"total bytes mismatch src={total_src_bytes} dest={total_dest_bytes}"
        )
    meta = {
        "reason": reason,
        "archived_ts": utc_iso(),
        "bot_version": EXECUTION_FIX_VERSION,
        "analyzer_sync_id": ANALYZER_SYNC_ID,
        "files": copied,
        "file_integrity": verified,
        "integrity": {
            "verified": bool(verified),
            "method": "sha256",
            "file_count": len(verified),
            "total_bytes": total_dest_bytes,
        },
    }
    with open(os.path.join(dest, "archive_meta.json"), "w", encoding="utf-8") as f:
        json.dump(meta, f, indent=2)
    logger.warning(
        f"[ARCHIVE] Saved {len(copied)} file(s) ({total_dest_bytes} bytes, sha256 verified) to {dest} "
        f"reason={reason} [PIPELINE ENFORCEMENT]"
    )
    return dest


def create_research_archive_receipt(
    past_analysis: dict, reason: str, source_paths=None,
) -> str:
    """Preserve and verify the exact planned deletion set before a reset."""
    os.makedirs(RESEARCH_ARCHIVE_DIR, exist_ok=True)
    sessions = [
        name for name in os.listdir(RESEARCH_ARCHIVE_DIR)
        if name.startswith("session_")
        and os.path.isdir(os.path.join(RESEARCH_ARCHIVE_DIR, name))
    ]
    numbers = []
    for name in sessions:
        suffix = name.split("_", 1)[-1]
        if suffix.isdigit():
            numbers.append(int(suffix))
    destination = os.path.join(
        RESEARCH_ARCHIVE_DIR,
        f"session_{(max(numbers) if numbers else 0) + 1:03d}",
    )
    os.makedirs(destination, exist_ok=False)
    payload_dir = os.path.join(destination, "payload")
    os.makedirs(payload_dir, exist_ok=False)
    source_inventory = []
    for index, path in enumerate(sorted(set(source_paths or []))):
        if not path or not os.path.isfile(path):
            continue
        source_size = os.path.getsize(path)
        source_sha = _file_sha256(path)
        preserved_name = f"{index:06d}_{os.path.basename(path)}"
        preserved_path = os.path.join(payload_dir, preserved_name)
        shutil.copy2(path, preserved_path)
        preserved_size = os.path.getsize(preserved_path)
        preserved_sha = _file_sha256(preserved_path)
        if preserved_size != source_size or preserved_sha != source_sha:
            raise ArchiveIntegrityError(f"archive verification failed for {path}")
        source_inventory.append({
            "path": os.path.relpath(os.path.abspath(path), os.getcwd()).replace("\\", "/"),
            "bytes": source_size,
            "sha256": source_sha,
            "preserved_path": f"payload/{preserved_name}",
            "preserved_bytes": preserved_size,
            "preserved_sha256": preserved_sha,
        })
    total_bytes = sum(int(row["bytes"]) for row in source_inventory)
    meta = {
        "schema": "research_archive_receipt_v2",
        "reason": reason,
        "archived_ts": utc_iso(),
        "bot_version": EXECUTION_FIX_VERSION,
        "analyzer_sync_id": ANALYZER_SYNC_ID,
        "past_analysis_id": past_analysis.get("archive_id"),
        "analysis_generated_at": past_analysis.get("analysis_generated_at"),
        "source_inventory": source_inventory,
        "integrity": {
            "verified": True,
            "method": "exact deletion set copied and sha256 verified",
            "file_count": len(source_inventory),
            "total_source_bytes": total_bytes,
        },
        "compacted": False,
        "raw_payloads_retained": True,
    }
    with open(os.path.join(destination, "archive_meta.json"), "w", encoding="utf-8") as handle:
        json.dump(meta, handle, indent=2)
    with open(os.path.join(destination, "archive_compaction_receipt.json"), "w", encoding="utf-8") as handle:
        json.dump({
            "schema": "research_archive_compaction_v1",
            "compacted_at": meta["archived_ts"],
            "past_analysis_id": meta["past_analysis_id"],
            "deleted_files": None,
            "deleted_bytes": None,
            "deletion_verified": False,
            "raw_payloads_retained": True,
        }, handle, indent=2)
    return destination


def _load_verified_archive_inventory(archive_path: str) -> list:
    meta_path = os.path.join(archive_path, "archive_meta.json")
    with open(meta_path, "r", encoding="utf-8") as handle:
        meta = json.load(handle)
    if not (meta.get("integrity") or {}).get("verified"):
        raise ArchiveIntegrityError("archive inventory is not verified")
    inventory = list(meta.get("source_inventory") or [])
    for row in inventory:
        source = os.path.abspath(str(row.get("path") or ""))
        preserved = os.path.join(archive_path, str(row.get("preserved_path") or ""))
        if not os.path.isfile(source) or not os.path.isfile(preserved):
            raise ArchiveIntegrityError(f"archive source/payload missing: {row.get('path')}")
        expected_size = int(row.get("bytes") or -1)
        expected_sha = str(row.get("sha256") or "")
        if os.path.getsize(source) != expected_size or _file_sha256(source) != expected_sha:
            raise ArchiveIntegrityError(f"source changed after archive: {row.get('path')}")
        if os.path.getsize(preserved) != expected_size or _file_sha256(preserved) != expected_sha:
            raise ArchiveIntegrityError(f"preserved payload changed: {row.get('path')}")
    return inventory


def _finalize_archive_deletion_receipt(archive_path: str, inventory: list, deleted: list) -> dict:
    deleted_abs = {os.path.abspath(path) for path in deleted}
    expected_abs = {os.path.abspath(str(row["path"])) for row in inventory}
    if deleted_abs != expected_abs:
        raise ArchiveIntegrityError(
            f"deleted set mismatch expected={len(expected_abs)} actual={len(deleted_abs)}"
        )
    deleted_bytes = sum(int(row["bytes"]) for row in inventory)
    receipt_path = os.path.join(archive_path, "archive_compaction_receipt.json")
    with open(receipt_path, "r", encoding="utf-8") as handle:
        receipt = json.load(handle)
    receipt.update({
        "deleted_files": len(deleted_abs),
        "deleted_bytes": deleted_bytes,
        "deletion_verified": True,
        "raw_payloads_retained": True,
    })
    temporary = receipt_path + ".tmp"
    with open(temporary, "w", encoding="utf-8") as handle:
        json.dump(receipt, handle, indent=2)
    os.replace(temporary, receipt_path)
    return receipt

def _wipe_research_on_startup_if_needed():
    if not _should_wipe_research_on_startup():
        logger.info(
            "[STARTUP] Research data preserved (v96 default). "
            "Use dashboard Fresh Collection to archive+wipe, or WIPE_CSV_ON_STARTUP=1 [PIPELINE ENFORCEMENT]"
        )
        return
    planned = all_research_wipe_paths(include_validation_artifacts=True, include_legacy_logs=True)
    archive = create_research_archive_receipt(
        _seal_past_analysis_with_fallback(reason="startup_wipe_env"),
        reason="startup_wipe_env", source_paths=planned,
    )
    logger.warning("[STARTUP] WIPE_CSV_ON_STARTUP=1 - wiping research files after archive [PIPELINE ENFORCEMENT]")
    result = reset_all_research_files(archive_path=archive)
    if result.get("wipe_aborted") or result.get("errors"):
        raise ArchiveIntegrityError(f"startup wipe aborted: {result.get('errors')}")

def _log_credential_sources():
    """Log where API keys come from — Railway must use Admin Control, not synced research defaults."""
    on_railway = bool(os.getenv("RAILWAY_ENVIRONMENT") or os.getenv("RAILWAY_PROJECT_ID"))
    admin = os.getenv("CREDENTIALS_FROM", "").strip().lower() == "admin_control"
    ds_key = (os.getenv("DEEPSEEK_API_KEY") or "").strip()
    bx_ok = _private_api_keys_ok()
    ds_ok = bool(ds_key)
    ds_tail = ds_key[-4:] if len(ds_key) >= 4 else "none"
    bx_key = (os.getenv("BITFINEX_API_KEY") or "").strip()
    bx_tail = bx_key[-4:] if len(bx_key) >= 4 else "none"
    logger.info(
        f"[CREDENTIALS] railway={on_railway} admin_control={admin} "
        f"deepseek={'ok' if ds_ok else 'MISSING'}(…{ds_tail}) "
        f"bitfinex={'ok' if bx_ok else 'MISSING'}(…{bx_tail}) "
        f"[PIPELINE ENFORCEMENT]"
    )
    if on_railway and not ds_ok:
        logger.error(
            "[CREDENTIALS] Railway DEEPSEEK missing — save key at /admin/control and Push to Runtime "
            "(npm run push:showcase-bot) [PIPELINE ENFORCEMENT]"
        )
    if on_railway and not bx_ok:
        logger.error(
            "[CREDENTIALS] Railway Bitfinex keys missing — save at /admin/control and Push to Runtime "
            "[PIPELINE ENFORCEMENT]"
        )

def _private_api_keys_ok() -> bool:
    k = os.getenv("BITFINEX_API_KEY", "").strip()
    s = os.getenv("BITFINEX_API_SECRET", "").strip()
    return bool(k and len(k) >= 10 and s and len(s) >= 10)


def _direct_private_exchange_owner() -> bool:
    """Source bot owns private Bitfinex calls only outside relay paper mode."""
    return bool(_private_api_keys_ok() and not _force_paper_mode_active())


def _apply_env_live_gating() -> None:
    """Fail closed at process start, regardless of persisted or env intent.

    ``BITFINEX_LIVE_ENABLED`` is a deployment capability/request, not an arm
    latch. A restarted process has not yet proven a fresh WS session, indicator
    warm-up, exchange flatness, or the operator's current intent. Both live
    flags therefore start OFF and can only be set by an authenticated runtime
    arm request after ``can_open_live_entry(..., require_armed=False)`` passes.
    """
    force_paper = (os.getenv("FORCE_PAPER_MODE") or "").strip().lower() in ("1", "true", "yes", "on")
    raw = (os.getenv("BITFINEX_LIVE_ENABLED") or "").strip().lower()
    requested = raw in ("true", "1", "yes", "on")
    with state_lock:
        had_live_state = bool(
            state.get("bitfinex_live_enabled")
            or state.get("live_armed")
        )
        state["bitfinex_live_enabled"] = False
        state["live_armed"] = False
        state.pop("live_armed_at_ts", None)
        state["live_startup_requested"] = bool(requested and not force_paper)
        if force_paper:
            state["strategy_mode"] = "RESEARCH"
    if force_paper:
        logger.warning("[PAPER MODE] FORCE_PAPER_MODE active: live arming and Bitfinex execution disabled")
    elif requested:
        logger.warning(
            "[BITFINEX LIVE] startup live intent detected but not armed; "
            "fresh authenticated runtime approval is required [PIPELINE ENFORCEMENT]"
        )
    elif had_live_state:
        logger.warning(
            "[BITFINEX LIVE] discarded persisted live arm on process start "
            "[PIPELINE ENFORCEMENT]"
        )
    try:
        save_persistent_config()
    except Exception as exc:
        logger.warning(f"[BITFINEX LIVE] startup disarm persist failed: {exc}")

def _compute_volatility_metric(features: dict) -> float:
    return round(abs(float(features.get("candle_range") or features.get("volatility") or 0)), 6)

def _signal_age_bucket(age_sec: float) -> str:
    """Bucket signal→fill age for v104 fill-quality analytics."""
    m = float(age_sec or 0) / 60.0
    if m < 5:
        return "0-5m"
    if m < 15:
        return "5-15m"
    if m < 30:
        return "15-30m"
    if m < 60:
        return "30-60m"
    return "60m+"


def _compute_entry_delay_sec(pos: dict, master: dict = None) -> float:
    """Seconds from AI approve (signal_ts) to fill."""
    if pos.get("signal_age_sec") is not None:
        return round(float(pos.get("signal_age_sec")), 3)
    if pos.get("entry_delay_sec") is not None:
        return round(float(pos.get("entry_delay_sec")), 3)
    fill_ts = pos.get("entry_ts")
    signal_ts = None
    if master:
        signal_ts = master.get("timing", {}).get("signal_ts") or master.get("created_ts_ts")
    if signal_ts and fill_ts:
        return round(max(0.0, float(fill_ts) - float(signal_ts)), 3)
    return 0.0

def _resolve_fill_model(signal: dict, order: dict = None) -> str:
    """Pathway fill model for analyzer: LIMIT_TOUCH | AI_DIRECT | 5M_TRIGGER | *_CHASE."""
    order = order or {}
    path = str(signal.get("entry_path") or "")
    chased = int(order.get("limit_chase_count") or signal.get("limit_chase_count") or 0) > 0
    if path == "5M_TRIGGER" or signal.get("entry_mode") == ENTRY_MODE_5M_TRIGGER:
        return "5M_TRIGGER_CHASE" if chased else "5M_TRIGGER"
    if path in ("AI_DIRECT", "AI_DIRECT_FALLBACK_MICRO") or signal.get("entry_mode") == ENTRY_MODE_AI_DIRECT:
        return "AI_DIRECT_CHASE" if chased else "AI_DIRECT"
    if chased:
        return "LIMIT_CHASE"
    if order.get("fill_model"):
        return str(order["fill_model"])
    return "LIMIT_TOUCH"

def _build_open_position(order: dict, signal: dict, ai: dict = None) -> dict:
    ai = ai or {}
    entry = order.get("fill_price") or order.get("limit_price") or order.get("entry") or signal.get("signal_price") or state.get("price")
    direction = order.get("signal_dir") or signal.get("final_direction")
    signal_price = order.get("signal_price") or signal.get("signal_price") or entry
    fill_ts = time.time()
    order_created = signal.get("order_created_ts") or order.get("created_ts") or signal.get("created_ts_ts")
    signal_ts = (signal.get("timing") or {}).get("signal_ts") or signal.get("created_ts_ts")
    signal_age_sec = max(0.0, fill_ts - float(signal_ts)) if signal_ts else 0.0
    order_age_sec = max(0.0, fill_ts - float(order_created)) if order_created else 0.0
    entry_delay_sec = signal_age_sec
    features, context = _feature_bundle(signal, signal)
    with state_lock:
        entry_bid = float(state.get("bid") or 0)
        entry_ask = float(state.get("ask") or 0)
    entry_market_spread_usd = (
        max(0.0, entry_ask - entry_bid)
        if entry_bid > 0 and entry_ask > 0
        else None
    )
    entry_market_spread_bps = (
        (entry_market_spread_usd / ((entry_ask + entry_bid) / 2.0)) * 10000.0
        if entry_market_spread_usd is not None and (entry_ask + entry_bid) > 0
        else None
    )
    lineage_sources = (order, signal, ai)
    lineage = {}
    for key in (
        "genome_environment_id",
        "genome_market_id",
        "genome_decision_id",
        "genome_source_trade_id",
    ):
        value = next((source.get(key) for source in lineage_sources if source.get(key)), None)
        if value is not None:
            lineage[key] = value
    lineage.setdefault(
        "genome_source_trade_id",
        order.get("source_trade_id") or signal.get("source_trade_id") or order.get("trade_id") or signal.get("trade_id"),
    )
    return {
        **lineage,
        "trade_id": order.get("trade_id") or signal.get("trade_id"),
        "bitfinex_order_id": (
            order.get("bitfinex_order_id")
            or signal.get("bitfinex_order_id")
        ),
        "bitfinex_position_id": (
            order.get("bitfinex_position_id")
            or signal.get("bitfinex_position_id")
        ),
        "bitfinex_live_entry": bool(
            order.get("bitfinex_live_entry")
            or signal.get("bitfinex_live_entry")
            or order.get("bitfinex_order_id")
            or signal.get("bitfinex_order_id")
        ),
        "dir": direction,
        "entry": entry,
        "qty": order.get("qty") or signal.get("qty"),
        "research_chase_schedule": copy.deepcopy(
            order.get("research_chase_schedule") or signal.get("research_chase_schedule")
        ),
        "chase_schedule_authoritative": bool(
            order.get("chase_schedule_authoritative") or signal.get("chase_schedule_authoritative")
        ),
        "leverage": _state_leverage(),
        "entry_ts": fill_ts,
        # Preserve the source entity's birth watermark after a pending order
        # becomes a position. NEXT_FRESH_ONLY must compare the original signal
        # creation time, not the later fill time, or a pre-arm order that fills
        # after Start is incorrectly reported as a fresh source-only gap.
        "created_ts": signal_ts or order_created or fill_ts,
        "signal_created_ts": signal_ts or order.get("signal_created_ts"),
        "order_created_ts": order_created,
        "sl": entry * (1 - sl_price_pct(_state_leverage())) if direction == "LONG" else entry * (1 + sl_price_pct(_state_leverage())),
        "tp": compute_tp(entry, direction, TP_TARGET_PCT, _state_leverage()),
        "regime_birth": signal.get("regime", "UNKNOWN"),
        "strategy_birth": "SR",
        "conf": signal.get("ai_win_prob", ai.get("win_prob", 0)),
        "max_pnl_pct": 0.0,
        "tp_stage": 0,
        "entry_type": order.get("entry_type", "LIMIT"),
        "ai_win_prob": signal.get("ai_win_prob", ai.get("win_prob")),
        "ai_approved": (ai.get("decision") == "APPROVE" or signal.get("ai_decision") == "APPROVE"),
        "ai_source": signal.get("ai_source", ai.get("source", "UNKNOWN")),
        "signal_conf": signal.get("ai_win_prob", ai.get("win_prob", 0)),
        "signal_regime": signal.get("regime", "UNKNOWN"),
        "signal_price": signal_price,
        "be_activated": False,
        "protection_active": False,
        "tp_placed": False,
        "status": "OPEN",
        "maker_fees": 0.0,
        "taker_fees": 0.0,
        "funding_fees": 0.0,
        "entry_fee_type": "MAKER" if order.get("fee_type") == "MAKER" else "TAKER",
        "exit_fee_type": "UNKNOWN",
        "features": features,
        "context": context,
        "controls": copy.deepcopy(signal.get("controls") or {}),
        "decision": copy.deepcopy(signal.get("decision") or {}),
        # GS/B regime tiles: the signal-time regime / exit-profile decision
        # that selects the position's exit stack.
        "adaptive_entry_decision": copy.deepcopy(signal.get("adaptive_entry_decision") or {}),
        "edge_score_at_entry": signal.get("edge_score_at_entry"),
        "entry_delay_sec": round(entry_delay_sec, 3),
        "order_age_sec": round(order_age_sec, 3),
        "signal_age_sec": round(signal_age_sec, 3),
        "signal_age_bucket": _signal_age_bucket(signal_age_sec),
        "research_lane": signal.get("research_lane") or order.get("research_lane"),
        "research_model": signal.get("research_model") or order.get("research_model"),
        "shared_ai_call_id": (
            order.get("shared_ai_call_id")
            or signal.get("shared_ai_call_id")
            or (ai or {}).get("shared_ai_call_id")
            or signal.get("source_trade_id")
        ),
        "shared_ai_call_ts": (
            order.get("shared_ai_call_ts")
            or signal.get("shared_ai_call_ts")
            or (ai or {}).get("shared_ai_call_ts")
        ),
        "research_collection_mode": (
            "PAPER"
            if is_patient_chase_lane(
                signal.get("research_lane") or order.get("research_lane")
            )
            else "BENCHMARK_PAPER"
        ),
        "entry_slippage": round(abs(float(entry) - float(signal_price)), 6),
        "book_slippage_usd": round(float((order.get("fill_sim") or {}).get("slippage_usd") or order.get("book_slippage_usd") or 0), 4),
        # Preserve the immutable fill-time depth receipt for terminal economics.
        # ``book_slippage_usd`` alone cannot distinguish a measured zero from a
        # missing/empty book, so terminal qualification must inspect this
        # evidence before treating a value as known.
        "entry_fill_sim": copy.deepcopy(order.get("fill_sim") or {}),
        "entry_filled_qty": order.get("filled_qty") or order.get("qty"),
        "entry_levels_consumed": int((order.get("fill_sim") or {}).get("levels_consumed") or 0),
        "entry_partial_fill": bool(order.get("partial_fill")),
        "entry_sr_state": context.get("sr_state", "UNKNOWN"),
        "entry_dist_to_resistance": context.get("dist_to_resistance", 0.0),
        "entry_dist_to_support": context.get("dist_to_support", 0.0),
        **_fill_replay_3m_stamps(signal, context),
        "entry_bid": round(entry_bid, 2) if entry_bid > 0 else None,
        "entry_ask": round(entry_ask, 2) if entry_ask > 0 else None,
        "market_bid_ask_spread_usd_at_entry": (
            round(entry_market_spread_usd, 4)
            if entry_market_spread_usd is not None
            else None
        ),
        "market_bid_ask_spread_bps_at_entry": (
            round(entry_market_spread_bps, 4)
            if entry_market_spread_bps is not None
            else None
        ),
        "last_funding_accrual_ts": fill_ts,
        "funding_rate_at_entry": (state.get("funding") or {}).get("rate"),
        "funding_rate_pct_8h_at_entry": (state.get("funding") or {}).get("rate_pct_per_8h"),
        "funding_source_at_entry": (state.get("funding") or {}).get("source"),
        "bull_score_at_entry": signal.get("bull_score_at_entry") or (signal.get("ai_factors") or {}).get("bull_score", 0),
        "bear_score_at_entry": signal.get("bear_score_at_entry") or (signal.get("ai_factors") or {}).get("bear_score", 0),
        "ai_factors": copy.deepcopy(signal.get("ai_factors", {})),
        "entry_thesis": capture_entry_thesis(signal),
        "margin_usdt": float(signal.get("margin_usdt") or FIXED_MARGIN_USDT),
        "conviction_spread": signal.get("conviction_spread"),
        "spread_penalty_mult": signal.get("spread_penalty_mult", 1.0),
        "planned_limit_price": order.get("planned_limit_price"),
        "fill_tick_price": order.get("fill_price"),
        "trend_health_at_entry": copy.deepcopy(signal.get("trend_health_at_entry") or {}),
        "entry_mode": signal.get("entry_mode", ENTRY_MODE_PULLBACK),
        "ema_hybrid_base": signal.get("ema_hybrid_base"),
        "ema_hybrid_limit": signal.get("ema_hybrid_limit"),
        "ema_hybrid_offset_usd": signal.get("ema_hybrid_offset_usd"),
        "ema9_at_entry": signal.get("ema9_at_entry"),
        "ema21_at_entry": signal.get("ema21_at_entry"),
        "dist_to_ema_hybrid_pct": signal.get("dist_to_ema_hybrid_pct"),
        "entry_path": signal.get("entry_path"),
        "entry_reason": signal.get("entry_reason"),
        "entry_limit_policy": signal.get("entry_limit_policy"),
        "raw_policy_id": signal.get("raw_policy_id") or order.get("raw_policy_id"),
        "policy_id": signal.get("policy_id") or order.get("policy_id"),
        "paper_only": bool(signal.get("paper_only") or order.get("paper_only")),
        "relay_eligible": bool(signal.get("relay_eligible", order.get("relay_eligible", True))),
        "fill_model": order.get("fill_model") or _resolve_fill_model(signal, order),
        "limit_chase_count": int(order.get("limit_chase_count") or signal.get("limit_chase_count") or 0),
        "urgent_chase_tier": order.get("urgent_chase_tier") or signal.get("urgent_chase_tier"),
        "chase_3plus_activation_reason": signal.get("chase_3plus_activation_reason"),
        "chase_3plus_virtual_chase_at_activation": signal.get("chase_3plus_virtual_chase_at_activation"),
        "chase_3plus_signal_age_at_activation": signal.get("chase_3plus_signal_age_at_activation"),
        "chase_3plus_signal_distance_pct_at_activation": signal.get("chase_3plus_signal_distance_pct_at_activation"),
        "original_limit_price": order.get("original_limit_price") or order.get("planned_limit_price"),
        "last_chase_ts": order.get("last_chase_ts") or signal.get("last_chase_ts"),
        "exit_config": copy.deepcopy(signal.get("exit_config") or get_exit_config_for_lane(signal.get("research_lane"))),
        **(
            {"aug_touch_fill_shadow": copy.deepcopy(order["aug_touch_fill_shadow"])}
            if order.get("aug_touch_fill_shadow") else {}
        ),
    }

def compute_live_factor_scores(mc: dict):
    ms = mc.get("market_structure", {}) or {}
    ts = mc.get("trend_strength", {}) or {}
    mtf = mc.get("multi_tf", {}) or {}
    ema = mc.get("ema_alignment", {}) or {}
    struct = float(ms.get("structure_score") or 0)
    bull = bear = 3
    if struct > 0:
        bull += min(4, int(struct))
    elif struct < 0:
        bear += min(4, int(-struct))
    if float(ts.get("adx") or 0) >= 25:
        if struct > 0:
            bull += 1
        elif struct < 0:
            bear += 1
    agree = mtf.get("agreement", "")
    if agree == "BULL_ALIGNED":
        bull += 2
    elif agree == "BEAR_ALIGNED":
        bear += 2
    vwap_dist = float(ts.get("vwap_distance_pct") or 0)
    if vwap_dist > 0:
        bull += 1
    elif vwap_dist < 0:
        bear += 1
    ema_slope = float(ema.get("ema_fast_slope_pct") or 0)
    if ema_slope > 0:
        bull += 1
    elif ema_slope < 0:
        bear += 1
    return int(bull), int(bear)

def _utc_session_label(ts: float = None) -> str:
    dt = datetime.fromtimestamp(ts or time.time(), timezone.utc)
    h = dt.hour
    if h < 8:
        return "ASIA"
    if h < 16:
        return "EU"
    return "US"


def _candle_15m_elapsed_pct(ts: float = None) -> float:
    now = float(ts or time.time())
    elapsed = now % CANDLE_INTERVAL_SEC
    return round(elapsed / CANDLE_INTERVAL_SEC, 4)


def _funding_bucket(funding: dict) -> str:
    rate = float((funding or {}).get("rate_pct_per_8h") or (funding or {}).get("rate") or 0)
    if rate > 0.01:
        return "HIGH_POS"
    if rate < -0.01:
        return "HIGH_NEG"
    if rate > 0.001:
        return "LOW_POS"
    if rate < -0.001:
        return "LOW_NEG"
    return "NEUTRAL"


def _volatility_bucket(vol_metric: float) -> str:
    v = abs(float(vol_metric or 0))
    if v >= 0.015:
        return "HIGH"
    if v >= 0.008:
        return "MED"
    if v >= 0.003:
        return "LOW"
    return "FLAT"


def _adx_bucket(adx: float) -> str:
    a = float(adx or 0)
    if a >= 30:
        return "STRONG"
    if a >= 25:
        return "TREND"
    if a >= 18:
        return "MODERATE"
    if a >= 12:
        return "WEAK"
    return "LOW"


def _research_session_bucket(ts: float = None) -> str:
    """ASIA / LONDON / OVERLAP / NEW_YORK for v80 segmented research."""
    h = datetime.fromtimestamp(ts or time.time(), timezone.utc).hour
    if h < 8:
        return "ASIA"
    if h < 13:
        return "LONDON"
    if h < 16:
        return "OVERLAP"
    if h < 22:
        return "NEW_YORK"
    return "ASIA"


def _edge_score_bucket(edge: float) -> str:
    e = float(edge or 0)
    if e < 1.0:
        return "0.5-1.0"
    if e < 1.5:
        return "1.0-1.5"
    if e < 2.0:
        return "1.5-2.0"
    if e < 2.5:
        return "2.0-2.5"
    if e < 3.0:
        return "2.5-3.0"
    if e < 3.5:
        return "3.0-3.5"
    if e < 4.0:
        return "3.5-4.0"
    return "4.0+"


def _spread_bucket(spread: int) -> str:
    s = int(spread or 0)
    if s <= 1:
        return "0-1"
    if s == 2:
        return "2"
    if s == 3:
        return "3"
    if s == 4:
        return "4"
    return "5+"


def _sr_location_bucket(sr_state: str) -> str:
    s = str(sr_state or "").upper()
    if "SUPPORT" in s:
        return "NEAR_SUPPORT"
    if "RESISTANCE" in s:
        return "NEAR_RESISTANCE"
    return "MID_RANGE"


def _ai_probability_bucket(prob: float) -> str:
    p = float(prob or 0)
    if p < 50:
        return "45-50"
    if p < 55:
        return "50-55"
    if p < 60:
        return "55-60"
    if p < 65:
        return "60-65"
    return "65+"


def _compute_quality_components(
    edge: float, spread: int, structure_score, sr_state: str, adx: float, ai_prob: float,
) -> dict:
    """Research-only quality decomposition — not used for gating in v80."""
    edge_comp = min(1.0, max(0.0, float(edge or 0) / 4.0))
    spread_comp = min(1.0, max(0.0, float(spread or 0) / 5.0))
    struct = float(structure_score or 0)
    structure_comp = max(0.0, min(1.0, (struct + 2.0) / 4.0))
    loc = _sr_location_bucket(sr_state)
    location_comp = {"NEAR_SUPPORT": 0.85, "MID_RANGE": 0.55, "NEAR_RESISTANCE": 0.25}.get(loc, 0.5)
    adx_comp = min(1.0, max(0.0, float(adx or 0) / 30.0))
    ai_comp = min(1.0, max(0.0, float(ai_prob or 0) / 100.0))
    quality_score = round(
        0.20 * edge_comp + 0.30 * spread_comp + 0.20 * structure_comp
        + 0.15 * location_comp + 0.10 * adx_comp + 0.05 * ai_comp,
        4,
    )
    return {
        "edge_component": round(edge_comp, 4),
        "spread_component": round(spread_comp, 4),
        "structure_component": round(structure_comp, 4),
        "location_component": round(location_comp, 4),
        "adx_component": round(adx_comp, 4),
        "ai_component": round(ai_comp, 4),
        "quality_score": quality_score,
    }


def capture_research_buckets(signal: dict, ai: dict, edge_score: float, features: dict = None) -> dict:
    """Frozen bucket labels at APPROVE for v80 analyzer cohort reports."""
    features = features or signal.get("features") or {}
    direction = str(signal.get("final_direction") or ai.get("direction") or "LONG").upper()
    bull = int(ai.get("bull_score") or signal.get("bull_score_at_entry") or 0)
    bear = int(ai.get("bear_score") or signal.get("bear_score_at_entry") or 0)
    spread = bull - bear if direction == "LONG" else bear - bull
    sr_state = (
        features.get("sr_state")
        or (state.get("support_resistance") or {}).get("sr_state")
        or "UNKNOWN"
    )
    mc = signal.get("context", {}).get("market_context") or signal.get("market_context") or {}
    if not isinstance(mc, dict):
        mc = {}
    ms = mc.get("market_structure", {}) if isinstance(mc.get("market_structure"), dict) else {}
    ts_mc = mc.get("trend_strength", {}) if isinstance(mc.get("trend_strength"), dict) else {}
    adx = float(ts_mc.get("adx") or 0)
    ai_prob = float(ai.get("win_prob") or 0)
    edge_score = round(float(edge_score or 0), 2)
    now_ts = time.time()
    return {
        "edge_score_bucket": _edge_score_bucket(edge_score),
        "directional_spread_bucket": _spread_bucket(spread),
        "support_resistance_bucket": _sr_location_bucket(sr_state),
        "session_bucket": _research_session_bucket(now_ts),
        "ai_probability_bucket": _ai_probability_bucket(ai_prob),
        "directional_spread": spread,
        "edge_score": edge_score,
        "sr_state": sr_state,
        "structure_score": ms.get("structure_score"),
        "adx": adx,
        "ai_win_prob": ai_prob,
        "quality_components": _compute_quality_components(
            edge_score, spread, ms.get("structure_score"), sr_state, adx, ai_prob,
        ),
    }


def _research_session_context() -> dict:
    rc = state.setdefault("research_counters", {})
    return {
        "approve_index": int(rc.get("approve_index", 0)),
        "trades_since_last_loss": int(rc.get("trades_since_last_loss", 0)),
        "last_exit_reason": rc.get("last_exit_reason"),
        "last_trade_pnl_usd": rc.get("last_trade_pnl_usd"),
    }


def _bump_research_approve_index() -> int:
    rc = state.setdefault("research_counters", {})
    rc["approve_index"] = int(rc.get("approve_index", 0)) + 1
    return rc["approve_index"]


def _record_research_trade_close(net_pnl: float, exit_reason: str):
    rc = state.setdefault("research_counters", {})
    rc["last_exit_reason"] = exit_reason
    rc["last_trade_pnl_usd"] = round(float(net_pnl), 4)
    if net_pnl < 0:
        rc["trades_since_last_loss"] = 0
    else:
        rc["trades_since_last_loss"] = int(rc.get("trades_since_last_loss", 0)) + 1


def capture_entry_regime_snapshot(signal: dict, features: dict = None) -> dict:
    """Frozen regime/session context at APPROVE for segmented analyzer research."""
    features = features or signal.get("features") or {}
    ctx = signal.get("context") or {}
    mc = ctx.get("market_context") or signal.get("market_context") or state.get("market_context") or {}
    if not isinstance(mc, dict):
        mc = {}
    ts_mc = mc.get("trend_strength", {}) if isinstance(mc.get("trend_strength"), dict) else {}
    mtf = mc.get("multi_tf", {}) if isinstance(mc.get("multi_tf"), dict) else {}
    trends = mtf.get("trends") or {}
    sr = mc.get("sr_context", {}) if isinstance(mc.get("sr_context"), dict) else {}
    if not sr:
        sr_ctx = state.get("support_resistance") or {}
        sr = {
            "sr_state": sr_ctx.get("sr_state", "UNKNOWN"),
            "dist_to_resistance_pct": round(nz(sr_ctx.get("dist_to_resistance", 0)) * 100, 3),
            "dist_to_support_pct": round(nz(sr_ctx.get("dist_to_support", 0)) * 100, 3),
        }
    funding = copy.deepcopy(state.get("funding") or {})
    vol_metric = _compute_volatility_metric(features)
    adx = float(ts_mc.get("adx") or 0)
    now_ts = time.time()
    mtf_4h = str(trends.get("4h") or "").upper()
    return {
        "captured_ts": now_ts,
        "session_utc": _utc_session_label(now_ts),
        "candle_15m_elapsed_pct": _candle_15m_elapsed_pct(now_ts),
        "regime_label": signal.get("regime") or mc.get("regime_label") or state.get("regime", "UNKNOWN"),
        "strategy": signal.get("strategy") or state.get("strategy"),
        "sr_state": sr.get("sr_state", "UNKNOWN"),
        "dist_to_resistance_pct": sr.get("dist_to_resistance_pct"),
        "dist_to_support_pct": sr.get("dist_to_support_pct"),
        "adx": adx,
        "adx_bucket": _adx_bucket(adx),
        "volatility_metric": vol_metric,
        "volatility_bucket": _volatility_bucket(vol_metric),
        "mtf_4h": trends.get("4h"),
        "mtf_4h_ranging": mtf_4h in ("RANGING", "NEUTRAL", "MIXED", ""),
        "funding_rate": funding.get("rate"),
        "funding_rate_pct_8h": funding.get("rate_pct_per_8h"),
        "funding_source": funding.get("source"),
        "funding_bucket": _funding_bucket(funding),
        "session_context": _research_session_context(),
    }


