def capture_entry_gate_snapshot(signal: dict, ai: dict, edge_score: float, features: dict = None) -> dict:
    """Frozen gate metrics at APPROVE for analyzer MTF/chop sweet-spot sweeps."""
    direction = str(signal.get("final_direction") or ai.get("direction") or "LONG").upper()
    ctx = signal.get("context") or {}
    features = features or signal.get("features") or {}
    mc = ctx.get("market_context") or signal.get("market_context") or {}
    if not isinstance(mc, dict):
        mc = {}
    mtf = mc.get("multi_tf", {}) if isinstance(mc.get("multi_tf"), dict) else {}
    trends = mtf.get("trends") or {}
    ts = mc.get("trend_strength", {}) if isinstance(mc.get("trend_strength"), dict) else {}
    adx = float(ts.get("adx") or 0)
    mom = round(_compute_momentum_metric(features), 4)
    agreement = mtf.get("agreement") or ""
    bull = int(ai.get("bull_score") or signal.get("bull_score_at_entry") or 0)
    bear = int(ai.get("bear_score") or signal.get("bear_score_at_entry") or 0)
    spread = bull - bear if direction == "LONG" else bear - bull
    edge_score = round(float(edge_score or 0), 2)
    research_max = _sole_ai_research_mode() and is_research_data_collection()
    edge_pass = edge_score >= get_edge_threshold() - 1e-9
    spread_pass = spread >= 1
    edge_min = get_edge_threshold()
    chop_max = MOMENTUM_CHOP_BLOCK_ABOVE
    adx_min = RESEARCH_ADX_MIN if research_max else ADX_BLOCK_NEW_ENTRY
    spread_min = 1
    strict_adx_pass = adx >= ADX_BLOCK_NEW_ENTRY
    adx_pass = adx >= adx_min
    if direction == "LONG":
        mtf_pass_strict = agreement == "BULL_ALIGNED"
    elif direction == "SHORT":
        mtf_pass_strict = agreement == "BEAR_ALIGNED"
    else:
        mtf_pass_strict = True
    mtf_pass = True if RESEARCH_FREE_RUN_DISABLE_MTF_GATE else mtf_pass_strict
    chop_pass_strict = mom <= chop_max + 1e-9
    chop_pass = True if RESEARCH_FREE_RUN_DISABLE_CHOP_GATE else chop_pass_strict
    return {
        "direction": direction,
        "gate_mode": "FREE_RUN" if (
            RESEARCH_FREE_RUN_DISABLE_MTF_GATE or RESEARCH_FREE_RUN_DISABLE_CHOP_GATE
        ) else "STRICT",
        "free_run": {
            "mtf_disabled": RESEARCH_FREE_RUN_DISABLE_MTF_GATE,
            "chop_disabled": RESEARCH_FREE_RUN_DISABLE_CHOP_GATE,
            "momentum_align_disabled": RESEARCH_FREE_RUN_DISABLE_MOMENTUM_ALIGN,
        },
        "would_pass_strict": {
            "mtf": mtf_pass_strict,
            "chop": chop_pass_strict,
            "adx": adx_pass,
            "edge": edge_pass,
            "spread": spread_pass,
            "live_stack": adx_pass and chop_pass_strict and mtf_pass_strict and edge_pass and spread_pass,
        },
        "mom_metric": mom,
        "adx": adx,
        "edge_score": edge_score,
        "directional_spread": spread,
        "margins": {
            "adx_margin": round(adx - adx_min, 4),
            "chop_margin": round(chop_max - mom, 4),
            "edge_margin": round(edge_score - edge_min, 4),
            "spread_margin": int(spread - spread_min),
            "mtf_pass": bool(mtf_pass),
            "mtf_agreement": agreement,
            "live_stack_margin": round(
                min(adx - adx_min, chop_max - mom, edge_score - edge_min, spread - spread_min), 4
            ),
        },
        "chop_components": {
            "ret_1m": features.get("ret_1m"),
            "ret_5m": features.get("ret_5m"),
            "velocity": features.get("velocity"),
            "volume_ratio": features.get("volume_ratio"),
            "imbalance": features.get("imbalance"),
        },
        "multi_tf": {
            "agreement": agreement,
            "trends": trends,
            "mtf_15m": trends.get("15m"),
            "mtf_1h": trends.get("1h"),
            "mtf_4h": trends.get("4h"),
            "bull_tf_count": mtf.get("bull_tf_count"),
            "bear_tf_count": mtf.get("bear_tf_count"),
            "interpretation_note": mtf.get("interpretation_note"),
        },
        "thresholds": {
            "adx_min": adx_min,
            "chop_max": chop_max,
            "edge_min": edge_min,
            "spread_min": spread_min,
            "long_mtf_required": "BULL_ALIGNED",
            "short_mtf_required": "BEAR_ALIGNED",
        },
        "would_pass": {
            "adx": adx_pass,
            "chop": chop_pass,
            "mtf": mtf_pass,
            "edge": edge_pass,
            "spread": spread_pass,
            "live_stack": adx_pass and chop_pass and mtf_pass and edge_pass and spread_pass,
            "strict_stack": strict_adx_pass and chop_pass_strict and mtf_pass_strict and edge_pass and spread_pass,
        },
        "would_fail_mtf": not mtf_pass_strict,
        "would_fail_chop": not chop_pass_strict,
        "would_fail_adx": not strict_adx_pass,
        "would_fail_spread": not spread_pass,
        "research_adx_min": RESEARCH_ADX_MIN if research_max else None,
    }

def get_lane_ladder(research_lane: str = None):
    """Per-lane Scenario C profit-lock ladder — override if the lane declares one, else the global.

    Returns a tuple (ladder, ladder_label, profile_id). Lanes without a `ladder` override in
    COMBO_LANE_SPECS (e.g. adopted exchange rows) fall back to the shared global
    TRAIL_LADDER_SCENARIO_C. Used by the per-trade exit path (via get_exit_config_snapshot ->
    pos.exit_config.trail_ladder) and by the LAB simulation so an OFF tile is pre-flighted with
    its OWN ladder, not the global one.
    """
    override = get_lane_ladder_override(research_lane)
    if override:
        ladder, label, profile_id = override
        return list(ladder), label or SCENARIO_C_LADDER_LABEL, profile_id or SCENARIO_C_PROFILE_ID
    return list(TRAIL_LADDER_SCENARIO_C), SCENARIO_C_LADDER_LABEL, SCENARIO_C_PROFILE_ID


def get_exit_config_snapshot(research_lane: str = None) -> dict:
    """Active exit/thesis/ladder params — logged per trade for analyzer sweeps."""
    lane = str(research_lane or LEGACY_ADOPTION_LANE).upper()
    if lane in COMBO_EXECUTION_LANES:
        return _patient_chase_policy(lane).exit_config(ANALYZER_SYNC_ID)
    thesis_pct = THESIS_FAST_EXIT_UNREAL_PCT
    mfe_protect = THESIS_MFE_PROTECT_PCT
    ladder, _lane_ladder_label, profile_id = get_lane_ladder(lane)
    scenario_c = SCENARIO_C_EXIT_PROFILE
    pnl_min_peak = peak_never_loser_min_peak_for_lane(lane)
    pnl_floor = peak_never_loser_floor_for_lane(lane)
    return {
        "policy_snapshot_schema": "exit_policy_v1",
        "policy_source": "btc-conservative-agent",
        "policy_version": EXECUTION_FIX_VERSION,
        "analyzer_sync_id": ANALYZER_SYNC_ID,
        "hard_stop_margin_pct": -float(MAX_SL_MARGIN_PCT),
        "trail_ladder": ladder,
        "ladder_first_trigger_pct": ladder[0][0],
        "ladder_first_lock_pct": ladder[0][1],
        "exit_profile_id": profile_id,
        "peak_never_loser_min_peak": pnl_min_peak,
        "peak_never_loser_floor": pnl_floor,
        "thesis_fast_exit_unreal_pct": thesis_pct,
        "thesis_mfe_protect_pct": mfe_protect,
        "thesis_exit_if_above_unreal_pct": THESIS_EXIT_IF_ABOVE_UNREAL_PCT,
        "thesis_min_age_sec": THESIS_MIN_AGE_SEC,
        "thesis_score_flip_margin": THESIS_SCORE_FLIP_MARGIN,
        "thesis_early_decay_delta": THESIS_EARLY_DECAY_DELTA,
        "early_fail_pct_threshold": EARLY_FAIL_PCT_THRESHOLD,
        "type_a_first_candle_enabled": TYPE_A_FIRST_CANDLE_ENABLED,
        "type_a_early_fail_enabled": TYPE_A_EARLY_FAIL_ENABLED,
        "scenario_c_exit_profile": scenario_c,
        "type_a_stall_enabled": TYPE_A_STALL_ENABLED,
        "type_a_stall_min_age_sec": TYPE_A_STALL_MIN_AGE_SEC,
        "type_a_stall_min_candles": TYPE_A_STALL_MIN_CANDLES,
        "type_a_stall_max_mfe_pct": TYPE_A_STALL_MAX_MFE_PCT,
        "trend_weakening_enabled": TREND_WEAKENING_ENABLED,
        "spread_penalty_threshold": SPREAD_PENALTY_THRESHOLD,
        "spread_penalty_margin_mult": SPREAD_PENALTY_MARGIN_MULT,
    }


def get_exit_config_for_lane(research_lane: str) -> dict:
    return get_exit_config_snapshot(research_lane)


def get_profit_lock_floor(peak_pct: float, trail_ladder=None, peak_never_loser_min_peak: float = None, peak_never_loser_floor: float = None):
    ladder = trail_ladder or TRAIL_LADDER
    if peak_pct is None:
        return None
    min_peak = PEAK_NEVER_LOSER_MIN_PEAK if peak_never_loser_min_peak is None else peak_never_loser_min_peak
    floor_val = PEAK_NEVER_LOSER_FLOOR if peak_never_loser_floor is None else peak_never_loser_floor
    # A registered policy may arm peak-never-loser below its first ladder rung.
    # Without this branch the ladder guard would swallow the early protection.
    pnl_only = peak_pct < ladder[0][0]
    if pnl_only and peak_pct < min_peak:
        return None
    floor = None
    if not pnl_only:
        for trigger, lock in ladder:
            if peak_pct >= trigger:
                floor = lock
    if peak_pct >= min_peak:
        floor = max(floor or 0, floor_val)
    return floor

# Per-lane peak-never-loser resolver. Lane-aware callers should use these instead
# of bare module constants so each registered lane keeps its own exit profile.
def peak_never_loser_min_peak_for_lane(research_lane: str) -> float:
    lane = str(research_lane or "").upper()
    return PEAK_NEVER_LOSER_MIN_PEAK_BY_LANE.get(lane, PEAK_NEVER_LOSER_MIN_PEAK)

def peak_never_loser_floor_for_lane(research_lane: str) -> float:
    lane = str(research_lane or "").upper()
    return PEAK_NEVER_LOSER_FLOOR_BY_LANE.get(lane, PEAK_NEVER_LOSER_FLOOR)

def compute_trend_health(direction_hint: str = None) -> dict:
    """v83: BULL / BULL_WEAKENING / BEAR / BEAR_WEAKENING / MIXED from live scores + tape."""
    with state_lock:
        mc = copy.deepcopy(state.get("market_context") or {})
        fs = copy.deepcopy(state.get("feature_snapshot") or {})
        hist = list(state.get("trend_health_history") or [])
    bull, bear = compute_live_factor_scores(mc)
    ms = mc.get("market_structure", {}) or {}
    mtf = mc.get("multi_tf", {}) or {}
    struct_score = float(ms.get("structure_score") or 0)
    agreement = str(mtf.get("agreement") or "")
    vel = float(fs.get("velocity") or 0)
    vol_ratio = float(fs.get("volume_ratio") or 0)
    delta = float(fs.get("delta") or 0)
    direction_hint = str(direction_hint or "").upper()
    if agreement == "BULL_ALIGNED" or struct_score >= 2:
        base = "BULL"
    elif agreement == "BEAR_ALIGNED" or struct_score <= -2:
        base = "BEAR"
    else:
        base = "MIXED"
    if direction_hint == "LONG" and base == "MIXED":
        base = "BULL"
    elif direction_hint == "SHORT" and base == "MIXED":
        base = "BEAR"
    weaken = 0
    if base == "BULL":
        if vel < -MOMENTUM_ALIGN_EPS:
            weaken += 1
        if delta < TYPE_A_STALL_WEAK_DELTA:
            weaken += 1
        if vol_ratio < TYPE_A_STALL_WEAK_VOLUME_RATIO:
            weaken += 1
        if len(hist) >= 1:
            prev = hist[-1]
            if bull < int(prev.get("bull_score", bull)) - 1:
                weaken += 1
            if bear > int(prev.get("bear_score", bear)) + 1:
                weaken += 1
    elif base == "BEAR":
        if vel > MOMENTUM_ALIGN_EPS:
            weaken += 1
        if delta > -TYPE_A_STALL_WEAK_DELTA:
            weaken += 1
        if vol_ratio < TYPE_A_STALL_WEAK_VOLUME_RATIO:
            weaken += 1
        if len(hist) >= 1:
            prev = hist[-1]
            if bear < int(prev.get("bear_score", bear)) - 1:
                weaken += 1
            if bull > int(prev.get("bull_score", bull)) + 1:
                weaken += 1
    trend_state = base
    if TREND_WEAKENING_ENABLED and weaken >= TREND_WEAKENING_MIN_SIGNALS:
        if base == "BULL":
            trend_state = "BULL_WEAKENING"
        elif base == "BEAR":
            trend_state = "BEAR_WEAKENING"
    result = {
        "trend_state": trend_state,
        "trend_health": trend_state,
        "base_state": base,
        "bull_score": bull,
        "bear_score": bear,
        "weaken_signals": weaken,
        "structure_score": struct_score,
        "mtf_agreement": agreement,
        "velocity": vel,
        "volume_ratio": vol_ratio,
        "delta": delta,
        "ts": time.time(),
    }
    with state_lock:
        state["trend_health"] = result
        hist.append(result)
        state["trend_health_history"] = hist[-TREND_HEALTH_HISTORY_MAX:]
        if trend_state.endswith("_WEAKENING"):
            key = f"trend_weakening_count_{trend_state.lower()}"
            state[key] = int(state.get(key) or 0) + 1
        state["trend_health_last_diag"] = copy.deepcopy(result)
    return result

def _position_trail_ladder(pos: dict):
    exit_cfg = pos.get("exit_config") or {}
    return exit_cfg.get("trail_ladder") or TRAIL_LADDER


def _effective_profit_lock_floor(pos: dict, peak_pct: float):
    exit_cfg = pos.get("exit_config") or {}
    # Use the per-lane peak_never_loser values baked into the position's exit_config
    # at entry time so independent tiles can coexist safely.
    min_peak = _buf_float(exit_cfg.get("peak_never_loser_min_peak"), PEAK_NEVER_LOSER_MIN_PEAK)
    floor_val = _buf_float(exit_cfg.get("peak_never_loser_floor"), PEAK_NEVER_LOSER_FLOOR)
    floor = get_profit_lock_floor(
        peak_pct,
        _position_trail_ladder(pos),
        peak_never_loser_min_peak=min_peak,
        peak_never_loser_floor=floor_val,
    )
    if floor is None:
        return None
    tighten = 0.0
    spread = int(pos.get("conviction_spread") or 0)
    direction = str(pos.get("dir") or "").upper()
    health = state.get("trend_health") or {}
    if spread_context_penalty_active(spread, direction, health=health):
        tighten += SPREAD_PENALTY_LOCK_TIGHTEN_PCT
    ts = str(health.get("trend_state") or "")
    if TREND_WEAKENING_ENABLED:
        if direction == "LONG" and ts == "BULL_WEAKENING":
            tighten += TREND_WEAKENING_LOCK_TIGHTEN_PCT
        elif direction == "SHORT" and ts == "BEAR_WEAKENING":
            tighten += TREND_WEAKENING_LOCK_TIGHTEN_PCT
    if tighten > 0:
        floor = min(float(peak_pct) - 0.5, float(floor) + tighten)
    return floor

def _type_a_stall_weak_tape(direction: str, fs: dict) -> bool:
    vol_ratio = float(fs.get("volume_ratio") or 0)
    delta = float(fs.get("delta") or 0)
    vel = float(fs.get("velocity") or 0)
    if vol_ratio >= TYPE_A_STALL_WEAK_VOLUME_RATIO:
        return False
    if direction == "LONG":
        return delta <= TYPE_A_STALL_WEAK_DELTA or vel < 0
    if direction == "SHORT":
        return delta >= -TYPE_A_STALL_WEAK_DELTA or vel > 0
    return False

def check_type_a_first_candle_exit(pos: dict, unreal_pct: float, now: float) -> bool:
    """Exit after first candle when tape is weak and trade never developed."""
    if not TYPE_A_FIRST_CANDLE_ENABLED:
        return False
    entry_ts = float(pos.get("entry_ts") or 0)
    if entry_ts <= 0:
        return False
    cur_candle = int((now - entry_ts) // CANDLE_INTERVAL_SEC) + 1
    if cur_candle != 1:
        return False
    if pos.get("_type_a_first_candle_checked"):
        return False
    peak = float(pos.get("max_pnl_pct") or 0)
    if peak >= RUNNER_BREATHE_MIN_PEAK_PCT:
        return False
    mae = float(pos.get("max_drawdown") or 0)
    if peak >= TYPE_A_FIRST_CANDLE_MAX_MFE_PCT:
        return False
    if mae > -TYPE_A_FIRST_CANDLE_MIN_MAE_PCT:
        return False
    direction = str(pos.get("dir") or "").upper()
    fs = state.get("feature_snapshot") or {}
    if not _type_a_stall_weak_tape(direction, fs):
        return False
    pos["_type_a_first_candle_checked"] = True
    logger.info(
        f"[EXIT TRIGGER] EARLY_TYPE_A trade_id={pos.get('trade_id')} candle=1 "
        f"peak={peak:.1f}% mae={mae:.1f}% unreal={unreal_pct:.1f}% "
        f"vol_ratio={fs.get('volume_ratio')} delta={fs.get('delta')} vel={fs.get('velocity')} "
        f"[PIPELINE ENFORCEMENT]"
    )
    close_position(pos, "EARLY_TYPE_A")
    return True


def check_type_a_early_fail_exit(pos: dict, unreal_pct: float, now: float) -> bool:
    """Exit Type-A failures after 3 candles: low MFE, high MAE, weakening trend."""
    if not TYPE_A_EARLY_FAIL_ENABLED:
        return False
    entry_ts = float(pos.get("entry_ts") or 0)
    if entry_ts <= 0:
        return False
    cur_candle = int((now - entry_ts) // CANDLE_INTERVAL_SEC) + 1
    if cur_candle < TYPE_A_EARLY_FAIL_MIN_CANDLES:
        return False
    if pos.get("_type_a_early_fail_checked"):
        return False
    peak = float(pos.get("max_pnl_pct") or 0)
    mae = float(pos.get("max_drawdown") or 0)
    if peak >= TYPE_A_EARLY_FAIL_MAX_MFE_PCT:
        return False
    if mae > -TYPE_A_EARLY_FAIL_MIN_MAE_PCT:
        return False
    direction = str(pos.get("dir") or "").upper()
    health = compute_trend_health(direction)
    ts = str(health.get("trend_state") or "")
    weakening = (
        (direction == "LONG" and ts == "BULL_WEAKENING")
        or (direction == "SHORT" and ts == "BEAR_WEAKENING")
    )
    if not weakening:
        return False
    pos["_type_a_early_fail_checked"] = True
    logger.info(
        f"[EXIT TRIGGER] TYPE_A_EARLY_FAIL trade_id={pos.get('trade_id')} candle={cur_candle} "
        f"peak={peak:.1f}% mae={mae:.1f}% trend={ts} unreal={unreal_pct:.1f}% "
        f"[PIPELINE ENFORCEMENT]"
    )
    close_position(pos, "TYPE_A_EARLY_FAIL")
    return True


def check_type_a_stall_exit(pos: dict, unreal_pct: float, now: float) -> bool:
    if not TYPE_A_STALL_ENABLED:
        return False
    peak = float(pos.get("max_pnl_pct") or 0)
    if peak >= TRAIL_LADDER[0][0]:
        return False
    entry_ts = float(pos.get("entry_ts") or 0)
    if entry_ts <= 0:
        return False
    age_sec = now - entry_ts
    if age_sec < TYPE_A_STALL_MIN_AGE_SEC:
        return False
    if peak >= TYPE_A_STALL_MAX_MFE_PCT:
        return False
    direction = str(pos.get("dir") or "").upper()
    fs = state.get("feature_snapshot") or {}
    if unreal_pct < 0:
        stall_reason = "unreal_negative"
    elif _type_a_stall_weak_tape(direction, fs):
        stall_reason = "weak_tape"
    else:
        return False
    cur_candle = int(age_sec // CANDLE_INTERVAL_SEC) + 1
    logger.info(
        f"[EXIT TRIGGER] TYPE_A_STALL trade_id={pos.get('trade_id')} reason={stall_reason} "
        f"age_min={age_sec/60:.1f} candle={cur_candle} peak={peak:.1f}% unreal={unreal_pct:.1f}% "
        f"vol_ratio={fs.get('volume_ratio')} delta={fs.get('delta')} vel={fs.get('velocity')} "
        f"[PIPELINE ENFORCEMENT]"
    )
    close_position(pos, "TYPE_A_STALL")
    return True

def _in_post_fill_grace(pos: dict, now: float) -> bool:
    entry_ts = float(pos.get("entry_ts") or 0)
    if entry_ts <= 0:
        return False
    return (now - entry_ts) < POST_FILL_GRACE_SEC

def check_trend_weakening_exit(pos: dict, unreal_pct: float, now: float) -> bool:
    if not TREND_WEAKENING_ENABLED:
        return False
    if _in_post_fill_grace(pos, now):
        return False
    peak = float(pos.get("max_pnl_pct") or 0)
    if peak >= TRAIL_LADDER[0][0]:
        return False
    health = state.get("trend_health") or {}
    ts = str(health.get("trend_state") or "")
    direction = str(pos.get("dir") or "").upper()
    if direction == "LONG" and ts != "BULL_WEAKENING":
        return False
    if direction == "SHORT" and ts != "BEAR_WEAKENING":
        return False
    entry_ts = float(pos.get("entry_ts") or 0)
    cur_candle = int((now - entry_ts) // CANDLE_INTERVAL_SEC) + 1 if entry_ts > 0 else 0
    if cur_candle < 1:
        return False
    if unreal_pct > TREND_WEAKENING_SCRATCH_UNREAL_PCT:
        return False
    logger.info(
        f"[EXIT TRIGGER] TREND_WEAKENING trade_id={pos.get('trade_id')} state={ts} "
        f"peak={peak:.1f}% unreal={unreal_pct:.1f}% weaken={health.get('weaken_signals')} "
        f"[PIPELINE ENFORCEMENT]"
    )
    close_position(pos, "TREND_WEAKENING")
    return True

def unrealized_margin_pct(pos: dict, price: float = None) -> float:
    entry = pos.get("entry", 0)
    mark = price if price is not None and price > 0 else get_mark_price(pos.get("dir"))
    if entry <= 0 or mark <= 0:
        return 0.0
    dir_factor = 1 if pos.get("dir") == "LONG" else -1
    price_move = ((mark - entry) / entry) * dir_factor
    return price_move * pos.get("leverage", DEFAULT_RESEARCH_LEVERAGE) * 100


def _check_phase_margin_stop(pos: dict, unreal_pct: float, age_sec: float) -> bool:
    """Phase-aware margin stop: thesis -12% during window, hard -30% after.

    Thesis window = THESIS_MIN_AGE_SEC (5 minutes) from entry. During the window
    the -12% thesis stop is armed immediately with no MFE bypass. After the
    window expires only the final -MAX_SL_MARGIN_PCT hard stop applies.
    """
    if age_sec < THESIS_MIN_AGE_SEC:
        if unreal_pct <= THESIS_FAST_EXIT_UNREAL_PCT:
            logger.info(
                f"[THESIS_FAST_CUT] trade_id={pos.get('trade_id')} dir={pos.get('dir')} "
                f"unreal={unreal_pct:.1f}% age={age_sec/60:.1f}m "
                f"thesis_window={THESIS_MIN_AGE_SEC/60:.0f}m [PIPELINE ENFORCEMENT]"
            )
            close_position(pos, "THESIS_FAST_CUT")
            return True
        return False
    if unreal_pct <= -MAX_SL_MARGIN_PCT:
        logger.info(
            f"[EXIT TRIGGER] HARD_STOP trade_id={pos.get('trade_id')} dir={pos.get('dir')} "
            f"unreal={unreal_pct:.1f}% age={age_sec/60:.1f}m cap=-{MAX_SL_MARGIN_PCT:.1f}% "
            f"[PIPELINE ENFORCEMENT]"
        )
        close_position(pos, "STOP_LOSS")
        return True
    return False

def check_thesis_invalidation(pos: dict, price: float) -> bool:
    if not THESIS_INVALIDATION_ENABLED:
        return False
    thesis = pos.get("entry_thesis") or {}
    if not thesis:
        return False
    unreal_pct = unrealized_margin_pct(pos, price)
    age_sec = time.time() - pos.get("entry_ts", 0)
    peak = pos.get("max_pnl_pct", 0.0)
    # Per-lane peak-never-loser comes from the position's registered exit_config.
    pos_exit_cfg = pos.get("exit_config") or {}
    lock_floor = get_profit_lock_floor(
        peak,
        _position_trail_ladder(pos),
        peak_never_loser_min_peak=_buf_float(pos_exit_cfg.get("peak_never_loser_min_peak"), PEAK_NEVER_LOSER_MIN_PEAK),
        peak_never_loser_floor=_buf_float(pos_exit_cfg.get("peak_never_loser_floor"), PEAK_NEVER_LOSER_FLOOR),
    )
    if lock_floor is not None and unreal_pct > lock_floor:
        return False
    if unreal_pct > THESIS_EXIT_IF_ABOVE_UNREAL_PCT:
        return False
    if peak >= TRAIL_LADDER[0][0]:
        return False
    if age_sec < THESIS_MIN_AGE_SEC:
        return False
    update_market_context()
    with state_lock:
        mc = copy.deepcopy(state.get("market_context", {}))
    ms = mc.get("market_structure", {}) or {}
    mtf = mc.get("multi_tf", {}) or {}
    cur_bull, cur_bear = compute_live_factor_scores(mc)
    entry_bull = int(thesis.get("bull_score", 0))
    entry_bear = int(thesis.get("bear_score", 0))
    entry_mtf = thesis.get("mtf_agreement")
    cur_mtf = mtf.get("agreement")
    entry_struct = thesis.get("structure_score")
    cur_struct = ms.get("structure_score")
    direction = pos.get("dir")
    flip = False
    m = THESIS_SCORE_FLIP_MARGIN
    decay = THESIS_EARLY_DECAY_DELTA
    entry_mtf_mixed = entry_mtf in ("MIXED", None, "")
    if direction == "LONG":
        if cur_bear >= cur_bull + m:
            flip = True
        elif cur_bull <= entry_bull - decay and cur_bear >= entry_bear + decay:
            flip = True
        elif cur_bull <= entry_bull - m and cur_bear >= entry_bear + m:
            flip = True
        if not entry_mtf_mixed and entry_mtf == "BULL_ALIGNED" and cur_mtf in ("BEAR_ALIGNED", "CONFLICTED"):
            flip = True
        if entry_struct is not None and cur_struct is not None and cur_struct <= -2 and entry_struct >= 2:
            flip = True
    elif direction == "SHORT":
        if cur_bull >= cur_bear + m:
            flip = True
        elif cur_bear <= entry_bear - decay and cur_bull >= entry_bull + decay:
            flip = True
        elif cur_bear <= entry_bear - m and cur_bull >= entry_bull + m:
            flip = True
        if not entry_mtf_mixed and entry_mtf == "BEAR_ALIGNED" and cur_mtf in ("BULL_ALIGNED", "CONFLICTED"):
            flip = True
        if entry_struct is not None and cur_struct is not None and cur_struct >= 2 and entry_struct <= -2:
            flip = True
    if flip:
        logger.info(
            f"[THESIS_INVALIDATED] trade_id={pos.get('trade_id')} dir={direction} "
            f"unreal={unreal_pct:.1f}% age={age_sec/60:.1f}m "
            f"entry bull/bear={entry_bull}/{entry_bear} live={cur_bull}/{cur_bear} "
            f"mtf {entry_mtf}->{cur_mtf} struct {entry_struct}->{cur_struct} "
            f"[PIPELINE ENFORCEMENT]"
        )
        _emit_genome_execution_event("THESIS_CHANGED", {
            "trade_id": pos.get("trade_id"),
            "direction": direction,
            "thesis_state": "INVALIDATED",
            "entry_bull": entry_bull,
            "entry_bear": entry_bear,
            "live_bull": cur_bull,
            "live_bear": cur_bear,
            "mtf_from": entry_mtf,
            "mtf_to": cur_mtf,
            "research_lane": pos.get("research_lane"),
        })
        close_position(pos, "THESIS_INVALIDATED")
        return True
    return False

def count_directional_exposure(direction: str, lane: str = None) -> int:
    direction = direction.upper()
    lane_key = str(lane).upper() if lane else None
    with trade_lock:
        positions = open_positions
        orders = pending_orders
        if lane_key:
            positions = [p for p in positions if p.get("research_lane") == lane_key]
            orders = [o for o in orders if o.get("research_lane") == lane_key]
        open_n = sum(1 for p in positions if p.get("dir") == direction)
        pending_n = sum(
            1 for o in orders
            if o.get("status") == "PENDING"
            and _normalize_order_side_to_dir(o.get("side") or o.get("signal_dir")) == direction
        )
    return open_n + pending_n

def is_clustered_entry(direction: str, price: float, lane: str = None) -> bool:
    if price is None or price <= 0:
        return False
    lane_only = lane if (_sole_ai_research_mode() and lane) else None
    with trade_lock:
        for p in open_positions:
            if lane_only and p.get("research_lane") != lane_only:
                continue
            if p.get("dir") == direction:
                entry = p.get("entry", 0)
                if entry > 0 and abs(price - entry) / entry < CLUSTER_MIN_DIST_PCT:
                    return True
        for o in pending_orders:
            if o.get("status") != "PENDING":
                continue
            if lane_only and o.get("research_lane") != lane_only:
                continue
            side = (o.get("side") or o.get("signal_dir", "")).upper()
            if side != direction:
                continue
            ref = o.get("limit_price") or o.get("signal_price") or 0
            if ref > 0 and abs(price - ref) / ref < CLUSTER_MIN_DIST_PCT:
                return True
    return False

def evaluate_entry_location_filter(direction: str, ctx: dict, ai: dict):
    dist_sup = nz(ctx.get("dist_to_support"))
    if dist_sup <= 0:
        with state_lock:
            dist_sup = nz(state.get("support_resistance", {}).get("dist_to_support", 1))
    mc = ctx.get("market_context") or {}
    ms = mc.get("market_structure", {}) or {}
    struct = float(ms.get("structure_score") or 0)
    mtf = (mc.get("multi_tf") or {}).get("agreement")
    bull = int(ai.get("bull_score", 0) or 0)
    bear = int(ai.get("bear_score", 0) or 0)

    if direction == "LONG":
        if struct <= -3:
            if is_research_data_collection() and AI_RESEARCH_MODE_ENABLED:
                return False, "LONG_BEAR_STRUCTURE_WARN"
            return True, "LONG_BLOCKED_BEAR_STRUCTURE"
        if dist_sup < LONG_NEAR_SUPPORT_MAX_DIST:
            if bull >= bear + LONG_NEAR_SUPPORT_MIN_BULL_SPREAD and mtf == "BULL_ALIGNED":
                return False, None
            return True, "LONG_BLOCKED_NEAR_SUPPORT_WEAK"

    if direction == "SHORT" and BLOCK_SHORT_NEAR_SUPPORT and dist_sup < SHORT_NEAR_SUPPORT_MAX_DIST:
        if (
            bear >= bull + SHORT_NEAR_SUPPORT_MIN_BEAR_SPREAD
            and mtf == "BEAR_ALIGNED"
            and struct <= SHORT_NEAR_SUPPORT_MIN_STRUCT
        ):
            return False, None
        return True, "SHORT_BLOCKED_NEAR_SUPPORT_WEAK"

    return False, None

def compute_directional_spread(direction: str, ai: dict) -> int:
    """Return conviction spread on the legacy 0-10 dashboard scale.

    The shared direction-only prompt emits LONG/SHORT scores on a 0-100
    scale.  Older callers emitted bull/bear scores on a 0-10 scale.  Normalize
    the new score gap by ten so existing spread gates (2, 3-5, 5+) retain
    their original meaning instead of silently receiving zero.
    """
    ai = ai or {}
    factors = ai.get("factors") if isinstance(ai.get("factors"), dict) else {}
    long_score = int(ai.get("long_score") or factors.get("long_score") or 0)
    short_score = int(ai.get("short_score") or factors.get("short_score") or 0)
    if long_score > 0 or short_score > 0:
        raw_gap = (
            long_score - short_score
            if str(direction or "").upper() == "LONG"
            else short_score - long_score
        )
        sign = -1 if raw_gap < 0 else 1
        return sign * (abs(raw_gap) // 10)
    bull = int(ai.get("bull_score") or factors.get("bull_score") or 0)
    bear = int(ai.get("bear_score") or factors.get("bear_score") or 0)
    if direction == "LONG":
        return bull - bear
    return bear - bull

def conviction_size_multiplier(spread: int) -> float:
    if spread >= CONVICTION_SPREAD_FULL:
        return 1.0
    if spread >= CONVICTION_SPREAD_HALF:
        return 0.5
    if spread >= CONVICTION_SPREAD_QUARTER:
        return 0.25
    return 0.0

def spread_penalty_margin_mult(spread: int) -> float:
    """v83: soft penalty for wide conviction spread (≥5) — margin scale, not hard block."""
    if not SPREAD_PENALTY_ENABLED:
        return 1.0
    if int(spread or 0) >= SPREAD_PENALTY_THRESHOLD:
        return SPREAD_PENALTY_MARGIN_MULT
    return 1.0

def spread_penalty_active(spread: int) -> bool:
    return SPREAD_PENALTY_ENABLED and int(spread or 0) >= SPREAD_PENALTY_THRESHOLD

def spread_context_penalty_active(
    spread: int, direction: str, signal: dict = None, health: dict = None
) -> bool:
    """Wide spread penalty only in bad location / weakening trend — not mid-range alone."""
    spread = int(spread or 0)
    if not SPREAD_PENALTY_ENABLED or spread < SPREAD_PENALTY_THRESHOLD:
        return False
    signal = signal or {}
    health = health or {}
    direction = str(direction or "").upper()
    if signal.get("entry_reason") == "MICRO_SR_CONFIRMED":
        return spread >= 7
    struct = float(
        (signal.get("micro_structure_eval") or {}).get("structure_score")
        or health.get("structure_score")
        or 0
    )
    ts = str(health.get("trend_state") or health.get("trend_health") or "")
    if ts.endswith("_WEAKENING"):
        return True
    if direction == "SHORT" and struct <= -4:
        return True
    if direction == "LONG" and struct >= 4:
        return True
    return spread >= 6

def get_regime_risk_profile() -> dict:
    with state_lock:
        regime = str(state.get("regime", "RANGE")).upper()
        sr_state = str((state.get("support_resistance") or {}).get("sr_state", "")).upper()
        mc = state.get("market_context") or {}
    adx = float((mc.get("trend_strength") or {}).get("adx") or 0)
    if regime == "RANGE" or "COMPRESSION" in sr_state:
        return {"max_active": 2, "max_long": 2, "max_short": 2, "size_mult": 0.5, "label": "RANGE"}
    if adx >= 25 and regime in ("BULL", "BEAR"):
        return {"max_active": 4, "max_long": 3, "max_short": 3, "size_mult": 1.0, "label": "TREND_STRONG"}
    return {"max_active": 4, "max_long": 3, "max_short": 3, "size_mult": 1.0, "label": "TREND"}

def compute_reference_scaled_margin(direction: str, ai: dict, ctx: dict) -> dict:
    """Legacy risk-sized margin (pre-v79) — logged for analyzer size sweep, not used live when FLAT_MARGIN_EVERY_TRADE."""
    spread = compute_directional_spread(direction, ai)
    conv = conviction_size_multiplier(spread)
    mc = ctx.get("market_context") or {}
    adx = float((mc.get("trend_strength") or {}).get("adx") or 0)
    adx_mult = ADX_HALF_SIZE_MULT if adx < ADX_HALF_SIZE_BELOW else 1.0
    regime_prof = get_regime_risk_profile()
    scaled = round(FIXED_MARGIN_USDT * conv * adx_mult * regime_prof["size_mult"], 4)
    scaled = max(FIXED_MARGIN_USDT * 0.1, min(scaled, FIXED_MARGIN_USDT))
    return {
        "directional_spread": spread,
        "conviction_mult": conv,
        "adx_mult": adx_mult,
        "regime_mult": regime_prof.get("size_mult"),
        "regime_label": regime_prof.get("label"),
        "adx": adx,
        "reference_scaled_margin_usdt": scaled,
        "live_flat_margin_usdt": FIXED_MARGIN_USDT if FLAT_MARGIN_EVERY_TRADE else scaled,
    }


def resolve_entry_margin_usdt(direction: str, ai: dict, ctx: dict):
    spread = compute_directional_spread(direction, ai)
    conv = conviction_size_multiplier(spread)
    research_max = _sole_ai_research_mode() and is_research_data_collection()
    research_sim = is_research_data_collection() and not state.get("live_armed")
    if conv <= 0:
        if research_max or research_sim:
            return float(FIXED_MARGIN_USDT), f"WOULD_FAIL_SPREAD_{spread}"
        return None, f"CONVICTION_SPREAD_LOW_{spread}"
    mc = ctx.get("market_context") or {}
    adx = float((mc.get("trend_strength") or {}).get("adx") or 0)
    if GOLDEN_STACK_ADX_BLOCK_LOW <= adx < GOLDEN_STACK_ADX_BLOCK_HIGH:
        if not (research_sim or research_max):
            return None, f"ADX_BAND_{adx:.1f}"
    elif adx < ADX_BLOCK_NEW_ENTRY:
        if research_max or research_sim:
            pass
        else:
            return None, f"ADX_NO_ENTRY_{adx:.1f}"
    sig_stub = {"micro_structure_eval": (ctx.get("market_context") or {}).get("market_structure")}
    health = state.get("trend_health") or {}
    ctx_penalty = spread_context_penalty_active(spread, direction, signal=sig_stub, health=health)
    penalty_mult = SPREAD_PENALTY_MARGIN_MULT if ctx_penalty else 1.0
    if FLAT_MARGIN_EVERY_TRADE:
        margin = round(float(FIXED_MARGIN_USDT) * penalty_mult, 4)
        if ctx_penalty:
            return margin, None
        return float(FIXED_MARGIN_USDT), None
    adx_mult = ADX_HALF_SIZE_MULT if adx < ADX_HALF_SIZE_BELOW else 1.0
    regime_prof = get_regime_risk_profile()
    margin = round(FIXED_MARGIN_USDT * conv * adx_mult * regime_prof["size_mult"], 4)
    margin = max(FIXED_MARGIN_USDT * 0.1, min(margin, FIXED_MARGIN_USDT))
    return margin, None

def evaluate_overextension_gate(direction: str, struct_score: float, sole: bool = False) -> dict:
    """Overextended structure — require micro confirm; log-only block in sole research."""
    struct_score = float(struct_score or 0)
    direction = str(direction or "").upper()
    over = (
        (direction == "LONG" and struct_score > OVEREXTENSION_STRUCT_THRESHOLD)
        or (direction == "SHORT" and struct_score < -OVEREXTENSION_STRUCT_THRESHOLD)
    )
    if not over:
        return {"overextended": False, "require_micro_confirm": False, "would_block": False}
    return {
        "overextended": True,
        "require_micro_confirm": True,
        "would_block": not sole,
        "reason": f"OVEREXTENSION_STRUCT_{struct_score:.1f}",
        "structure_score": struct_score,
    }


def compute_trade_quality_score(signal: dict, ctx: dict, ai: dict, features: dict = None) -> dict:
    """Lightweight quality score for research logging — not a hard gate in sole mode."""
    direction = str(signal.get("final_direction") or ai.get("direction") or "LONG").upper()
    features = features or signal.get("features") or {}
    mc = (ctx or signal.get("context") or {}).get("market_context") or state.get("market_context") or {}
    ms = (mc.get("market_structure") or {}) if isinstance(mc.get("market_structure"), dict) else {}
    struct = float(ms.get("structure_score") or 0)
    structure_comp = max(0.0, min(100.0, (struct + 10.0) / 20.0 * 100.0))
    micro_confirmed = bool(signal.get("micro_structure_confirmed"))
    entry_reason = str(signal.get("entry_reason") or "")
    if entry_reason == "MICRO_SR_CONFIRMED" or micro_confirmed:
        micro_sr_comp = 100.0
    elif entry_reason in ("EMA_ARMED_AWAIT_MICRO", "OVEREXT_AWAIT_MICRO"):
        micro_sr_comp = 55.0
    else:
        micro_sr_comp = 35.0
    health = signal.get("trend_health_at_entry") or signal.get("trend_health") or {}
    if isinstance(health, dict):
        ts = str(health.get("trend_state") or health.get("trend_health") or "MIXED")
    else:
        ts = str(health or "MIXED")
    trend_map = {
        "BULL": 100.0, "BEAR": 100.0,
        "BULL_WEAKENING": 40.0, "BEAR_WEAKENING": 40.0,
        "MIXED": 55.0,
    }
    trend_comp = trend_map.get(ts, 55.0)
    bull = int(ai.get("bull_score") or signal.get("bull_score_at_entry") or 0)
    bear = int(ai.get("bear_score") or signal.get("bear_score_at_entry") or 0)
    spread = bull - bear if direction == "LONG" else bear - bull
    spread_comp = max(0.0, min(100.0, float(spread) / 7.0 * 100.0))
    edge_score = float(signal.get("edge_score_at_entry") or signal.get("edge_score") or 0)
    edge_comp = max(0.0, min(100.0, edge_score / 6.0 * 100.0))
    quality_score = round(
        0.30 * structure_comp + 0.25 * micro_sr_comp + 0.20 * trend_comp
        + 0.15 * spread_comp + 0.10 * edge_comp,
        2,
    )
    return {
        "quality_score": quality_score,
        "structure_component": round(structure_comp, 2),
        "micro_sr_component": round(micro_sr_comp, 2),
        "trend_health_component": round(trend_comp, 2),
        "spread_component": round(spread_comp, 2),
        "edge_component": round(edge_comp, 2),
        "trend_health_state": ts,
    }


def evaluate_entry_quality_filter(direction: str, ctx: dict, ai: dict, features: dict = None):
    mc = ctx.get("market_context") or {}
    mtf = (mc.get("multi_tf", {}) or {}).get("agreement", "")
    if not RESEARCH_FREE_RUN_DISABLE_MTF_GATE:
        if direction == "LONG" and mtf != "BULL_ALIGNED":
            return True, f"LONG_REQUIRES_BULL_MTF_{mtf or 'UNKNOWN'}"
        if direction == "SHORT":
            if mtf == "BULL_ALIGNED":
                return True, "SHORT_BLOCKED_BULL_MTF"
            if mtf not in ("BEAR_ALIGNED",):
                return True, f"SHORT_REQUIRES_BEAR_MTF_{mtf or 'UNKNOWN'}"
    features = features or ctx.get("features") or {}
    if not RESEARCH_FREE_RUN_DISABLE_MOMENTUM_ALIGN:
        blocked, reason = evaluate_momentum_alignment(direction, features)
        if blocked:
            return True, reason
    mc = ctx.get("market_context") or {}
    ms = mc.get("market_structure") or {}
    struct_score = float(ms.get("structure_score") or 0)
    over = evaluate_overextension_gate(direction, struct_score, sole=_sole_ai_research_mode())
    if over.get("would_block"):
        return True, over.get("reason")
    return False, None

def evaluate_evidence_entry_filter(
    direction: str, ctx: dict, ai: dict, features: dict, edge_score: float
) -> tuple:
    """Evidence gate retained for non-Edge momentum/chop checks."""
    features = features or ctx.get("features") or {}
    if not RESEARCH_FREE_RUN_DISABLE_CHOP_GATE:
        mom = _compute_momentum_metric(features)
        if direction in ("LONG", "SHORT") and mom > MOMENTUM_CHOP_BLOCK_ABOVE:
            return True, f"{direction}_MOMENTUM_CHOP_{mom:.2f}"
    return False, None

def research_ai_temperature() -> float:
    """Research lanes use temp=0 for reproducible cross-lane comparison."""
    if is_research_data_collection():
        return RESEARCH_AI_TEMPERATURE
    return LEGACY_AI_TEMPERATURE

def research_config_for_dashboard() -> dict:
    return {
        "temperature": RESEARCH_AI_TEMPERATURE,
        "legacy_temperature": LEGACY_AI_TEMPERATURE,
        "candle_interval_sec": CANDLE_INTERVAL_SEC,
        "replay_model_version": REPLAY_MODEL_VERSION,
        "replay_approve_threshold": REPLAY_MODEL_APPROVE_THRESHOLD,
        "ai_input_log_file": AI_INPUT_LOG_FILE,
        "lane_labels": RESEARCH_LANE_LABELS,
        "retired_tile_lanes": sorted(RETIRED_TILE_LANES),
    }

def legacy_adoption_lane_enabled() -> bool:
    """Persisted mode flag for adopted/legacy rows; no route can change it."""
    with state_lock:
        return bool(state.get("continuous_ai_research_enabled", LEGACY_ADOPTION_LANE_DEFAULT_ENABLED))


def shared_research_ai_observation_enabled() -> bool:
    """Research observation cadence is independent of paper-order toggles."""
    return bool(_sole_ai_research_mode() and AI_RESEARCH_MODE_ENABLED)

def research_lane_enabled_map() -> dict:
    with state_lock:
        stored = state.get("research_lane_enabled") or {}
        merged = dict(_RESEARCH_LANE_TOGGLE_DEFAULTS)
        for lane, val in stored.items():
            if lane in merged:
                merged[lane] = bool(val)
        return merged

def is_research_lane_enabled(lane: str) -> bool:
    lane = str(lane or "").upper()
    if is_research_lane_retired(lane):
        return False
    if lane == LEGACY_ADOPTION_LANE:
        return legacy_adoption_lane_enabled()
    if is_ai_scan_lane(lane):
        return shared_research_ai_observation_enabled()
    if is_combo_execution_lane(lane):
        return bool(research_lane_enabled_map().get(lane, False))
    # Unknown and historical lane names fail closed.  This prevents old persisted
    # flags or new call sites from producing competing paper records or orders.
    return False


def lane_orders_allowed(lane: str = None) -> bool:
    """Pathway Lab toggle — OFF means no new/chased limit orders for this lane."""
    lane = str(lane or RESEARCH_LANE_AI_SCAN).upper()
    if is_ai_scan_lane(lane):
        return False
    if is_shadow_only_lane(lane):
        return False
    if lane_blocks_live_orders(lane):
        return False
    return is_research_lane_enabled(lane)


def suspend_lane_trading(lane: str, reason: str = "LANE_TOGGLE_OFF") -> dict:
    """Cancel pending limits and block awaiting promotions for a disabled lane."""
    lane = str(lane or LEGACY_ADOPTION_LANE).upper()
    # Exchange cancellation must happen while the local pending rows still
    # carry their Bitfinex order ids. Removing local rows first loses the only
    # deterministic cancellation handle and can orphan a live resting order.
    bx_cancelled = _cancel_bitfinex_orders_for_lane(lane, reason=reason)
    cancelled_pending = [
        row.get("trade_id")
        for row in bx_cancelled.get("cancelled", [])
        if row.get("trade_id")
    ]
    expired_awaiting = []
    failed_live_ids = {
        str(row.get("trade_id") or "")
        for row in bx_cancelled.get("failed", [])
    }
    confirmed_ids = {str(tid) for tid in cancelled_pending}
    now = time.time()
    with trade_lock:
        for tid in confirmed_ids:
            sig = (trades_map.get(tid) or {}).get("signal_ref") or {}
            if isinstance(sig, dict):
                sig["status"] = "BLOCKED"
                sig["outcome"] = reason
                sig["exit_reason"] = reason
        for tid in failed_live_ids:
            sig = (trades_map.get(tid) or {}).get("signal_ref") or {}
            if isinstance(sig, dict):
                sig["status"] = "CANCEL_PENDING_LIVE"
                sig["cancel_pending_reason"] = reason
        for entry in trades_map.values():
            sig = entry.get("signal_ref") or {}
            if not isinstance(sig, dict) or _normalize_lane_key(sig) != lane:
                continue
            if str(sig.get("trade_id") or "") in failed_live_ids:
                # Do not make the signal terminal while its live exchange order
                # is still resting or cancellation is unconfirmed.
                continue
            if is_terminal_signal(sig):
                continue
            st = sig.get("status")
            if st in ("FILLED", "OPEN", "CLOSED", "COMPLETE"):
                continue
            if st in (
                SIGNAL_STATUS_AWAITING_MICRO,
                SIGNAL_STATUS_AWAITING_5M,
                SIGNAL_STATUS_AWAITING_MIN_AGE,
                SIGNAL_STATUS_AWAITING_CHASE_3PLUS,
                SIGNAL_STATUS_AWAITING_DASHBOARD_CHASE,
                "ORDERED",
                "ACTIVE",
                "PENDING",
            ):
                sig["status"] = "BLOCKED"
                sig["outcome"] = reason
                sig["exit_reason"] = reason
                sig["expires_ts"] = now - 1
                expired_awaiting.append(sig.get("trade_id"))
    if cancelled_pending or expired_awaiting:
        logger.info(
            f"[LANE SUSPEND] lane={lane} reason={reason} "
            f"cancelled_pending={len(cancelled_pending)} expired_awaiting={len(expired_awaiting)} "
            f"[PIPELINE ENFORCEMENT]"
        )
        pipeline_state_sync()
    return {
        "lane": lane,
        "reason": reason,
        "cancelled_pending": cancelled_pending,
        "expired_awaiting": expired_awaiting,
        "bitfinex_cancelled": bx_cancelled.get("cancelled", []),
        "bitfinex_failed": bx_cancelled.get("failed", []),
        "open_positions_remaining": bx_cancelled.get("open_positions_remaining", 0),
    }


def _cancel_bitfinex_orders_for_lane(lane: str, reason: str = "LANE_TOGGLE_OFF") -> dict:
    """Cancel outstanding pending entries for a lane (Pt 4a toggle contract).

    Local paper orders finalize immediately. Live exchange orders finalize only
    after the private cancellation confirms. Exits for filled positions are not
    cancelled here and continue to be managed until flat.
    """
    out = {"cancelled": [], "failed": [], "open_positions_remaining": 0}
    lane_u = str(lane or "").upper()
    with trade_lock:
        candidates = [
            row for row in pending_orders
            if isinstance(row, dict)
            and _normalize_lane_key(row) == lane_u
            and str(row.get("status") or "").upper()
            in ("PENDING", "CANCEL_PENDING_LIVE")
        ]
        out["open_positions_remaining"] = sum(
            1 for p in open_positions
            if _normalize_lane_key(p) == lane_u
            and p.get("status") in ("FILLED", "OPEN")
        )
    for order in candidates:
        oid = str(order.get("bitfinex_order_id") or "")
        tid = str(order.get("trade_id") or "")
        outcome = _cancel_pending_order_confirmed(
            order,
            reason,
            record_expired=False,
            expire_signal=False,
        )
        if outcome.get("finalized"):
            out["cancelled"].append({"trade_id": tid, "exchange_order_id": oid})
        else:
            out["failed"].append({
                "trade_id": tid,
                "exchange_order_id": oid,
                "reason": outcome.get("failure_reason") or "CANCEL_FAILED",
            })
    if out["cancelled"] or out["failed"]:
        logger.warning(
            f"[BITFINEX CANCEL LANE] lane={lane_u} reason={reason} "
            f"cancelled={len(out['cancelled'])} failed={len(out['failed'])} "
            f"open_positions_remaining={out['open_positions_remaining']} "
            "[PIPELINE ENFORCEMENT]"
        )
    return out


def research_lane_label(lane: str) -> str:
    return RESEARCH_LANE_LABELS.get(lane, lane or "Unknown")

def get_pathway_lane_status(lane: str) -> str:
    return PATHWAY_LANE_STATUS.get(str(lane or "").upper(), "ACTIVE")

def is_research_lane_retired(lane: str) -> bool:
    lane = str(lane or "").upper()
    return lane not in {
        RESEARCH_LANE_AI_SCAN,
        LEGACY_ADOPTION_LANE,
        *COMBO_EXECUTION_LANES,
    }


def lane_blocks_live_orders(lane: str) -> bool:
    """Hard block retired, benchmark, shadow and relay-ineligible lanes."""
    lane = str(lane or "").upper()
    if lane == LEGACY_ADOPTION_LANE:
        return True
    if is_shadow_only_lane(lane):
        return True
    status = get_pathway_lane_status(lane)
    if status in ("RETIRED", "DATA_RETIRED", "BENCHMARK"):
        return True
    return False


# ---------------------------------------------------------------------------
# Pt 1 (toggle contract): centralized execution-mode resolver.
#
# Returns one of four modes; this is the SINGLE source of truth that every
# entry, chase, cancel, close, and dashboard banner MUST consult:
#
#   LAB_SHADOW  -- Tile OFF (or retired): no new orders of any kind.
#                  LAB shadows + counterfactuals still collected for research.
#                  Already-filled positions are still managed to exit.
#   PAPER       -- Tile ON: local paper limit orders. Platform-relay lanes
#                  remain PAPER even when the separate relay is ON; signed
#                  lifecycle events are their only live-money route.
#   LIVE        -- Legacy non-relay lane using the source bot's direct
#                  Bitfinex executor. Current operator-visible production
#                  lanes are not allowed to use this route.
#   EXIT_ONLY   -- Special mode set after Bitfinex ON->OFF with open exposure:
#                  no new entries, but exits for filled positions continue.
#
# WARNING: callers MUST NOT re-derive execution mode by reading
# `is_research_lane_enabled` + `bitfinex_live_enabled` separately. Always go
# through this resolver.
# ---------------------------------------------------------------------------

EXEC_MODE_LAB_SHADOW = "LAB_SHADOW"
EXEC_MODE_PAPER = "PAPER"
EXEC_MODE_LIVE = "LIVE"
EXEC_MODE_EXIT_ONLY = "EXIT_ONLY"

# Per-lane override: lanes forced into EXIT_ONLY (e.g. after Bitfinex disarm
# with open exposure). Keyed by uppercase lane id; values are timestamps.
_exit_only_until: dict = {}


def mark_lane_exit_only(lane: str, reason: str = "BITFINEX_DISARMED") -> None:
    """Force a lane into EXIT_ONLY mode (no new entries, exits continue).

    Used when Bitfinex is disarmed while the lane has open filled positions.
    Cleared automatically when the lane toggle goes OFF and back ON, or when
    `clear_lane_exit_only()` is called explicitly.
    """
    lane = str(lane or "").upper()
    if not lane:
        return
    _exit_only_until[lane] = time.time()
    with state_lock:
        persisted = {
            str(item).upper()
            for item in (state.get("exit_only_lanes") or [])
            if str(item).strip()
        }
        persisted.add(lane)
        state["exit_only_lanes"] = sorted(persisted)
        save_persistent_config()
    logger.warning(
        f"[EXEC_MODE] {lane} -> EXIT_ONLY reason={reason} [PIPELINE ENFORCEMENT]"
    )


def clear_lane_exit_only(lane: str) -> bool:
    """Remove EXIT_ONLY marker. Returns True if a marker was present."""
    lane = str(lane or "").upper()
    removed = bool(_exit_only_until.pop(lane, None))
    with state_lock:
        persisted = {
            str(item).upper()
            for item in (state.get("exit_only_lanes") or [])
            if str(item).strip()
        }
        if lane in persisted:
            persisted.remove(lane)
            state["exit_only_lanes"] = sorted(persisted)
            save_persistent_config()
            removed = True
    return removed


def lane_is_exit_only(lane: str) -> bool:
    lane = str(lane or "").upper()
    if lane in _exit_only_until:
        return True
    with state_lock:
        return lane in {
            str(item).upper()
            for item in (state.get("exit_only_lanes") or [])
        }


def execution_mode_for_lane(lane: str = None) -> str:
    """Single source of truth for what a lane is allowed to do right now.

    Fail-closed: any unknown lane, missing data, or retired lane returns
    LAB_SHADOW (safest mode -- no new orders).
    """
    # Fail-closed for None/empty: do NOT default to AI_SCAN here, because
    # a caller that forgot to pass a lane must never silently place orders.
    if not lane or not str(lane).strip():
        return EXEC_MODE_LAB_SHADOW
    lane = str(lane).strip().upper()

    # EXIT_ONLY takes precedence (set after Bitfinex disarm w/ open exposure)
    if lane_is_exit_only(lane):
        return EXEC_MODE_EXIT_ONLY

    # Retired / historical benchmark / unknown -> no orders ever.
    # LEGACY_ADOPTION_LANE keeps its persisted mode so adopted exchange
    # exposure is managed exactly as before the tile retirement.
    if is_research_lane_retired(lane):
        return EXEC_MODE_LAB_SHADOW
    status = get_pathway_lane_status(lane)
    if lane != LEGACY_ADOPTION_LANE and status in (
        "RETIRED", "DATA_RETIRED", "BENCHMARK"
    ):
        return EXEC_MODE_LAB_SHADOW

    # Tile OFF -> LAB shadow only
    if not is_research_lane_enabled(lane):
        return EXEC_MODE_LAB_SHADOW

    # Shadow-only / shadow-collecting lanes never place orders
    if is_shadow_only_lane(lane):
        return EXEC_MODE_LAB_SHADOW

    # Every platform-relay lane is always a LOCAL paper source. It must never
    # use the bot's legacy direct-Bitfinex executor. When the separate platform
    # relay is ON, its signed local order lifecycle is copied by the platform
    # allowlist. This makes the contract unambiguous:
    #
    #   tile ON  -> global local pending/open lifecycle
    #   relay ON -> that lifecycle may be copied to Bitfinex
    #
    # Keeping these lanes PAPER here also prevents the legacy source executor
    # and the platform relay from submitting the same trade twice.
    if lane in PLATFORM_RELAY_ELIGIBLE_LANES:
        return EXEC_MODE_PAPER

    # This candidate owns a complete local paper lifecycle but can never enter
    # either live-money route.  Keep the invariant independent of the global
    # Bitfinex switch so arming another lane cannot promote it accidentally.
    if lane in PAPER_ONLY_RESEARCH_LANES:
        return EXEC_MODE_PAPER

    # Tile ON. Now decide PAPER vs LIVE based on Bitfinex state.
    # Bitfinex arming is global (env-gated + relay-controlled); dashboard
    # does not have a separate Bitfinex toggle per the toggle contract.
    try:
        import bitfinex_live_executor as bx
        bitfinex_on = bx.is_enabled(state)
    except Exception:
        bitfinex_on = False

    if not bitfinex_on:
        return EXEC_MODE_PAPER

    # Bitfinex ON -- still subject to keys + DDollar + execution gates.
    # Those gates are evaluated at submit time; here we just say LIVE.
    return EXEC_MODE_LIVE


def lane_can_place_new_entry(lane: str) -> bool:
    """True iff execution_mode_for_lane allows NEW entry orders (PAPER or LIVE).

    LAB_SHADOW and EXIT_ONLY both block new entries.
    """
    mode = execution_mode_for_lane(lane)
    return mode in (EXEC_MODE_PAPER, EXEC_MODE_LIVE)


def lane_is_live(lane: str) -> bool:
    """True iff this lane currently routes entries to Bitfinex."""
    return execution_mode_for_lane(lane) == EXEC_MODE_LIVE


def _note_ddollar_gate_error(exc) -> None:
    logger.error(f"[DDOLLAR GATE] evaluation failed; entry blocked: {type(exc).__name__}: {exc}")
    try:
        import bitfinex_live_executor as bx
        bx.record_ddollar_gate_error(exc)
    except Exception:
        pass


def lane_execution_block_reason(lane: str) -> str | None:
    """Return a human-readable reason when entries are blocked, else None.

    Used by the dashboard banner and by submit paths to surface WHY a live
    order was refused (toggle off, bitfinex disarmed, gate failed, etc.).
    """
    lane = str(lane or "").upper()
    mode = execution_mode_for_lane(lane)
    if mode == EXEC_MODE_PAPER:
        return None  # paper entries are allowed; not blocked
    if mode == EXEC_MODE_LIVE:
        # Live mode is allowed in principle; sub-gates (keys/DDollar/health)
        # are evaluated at submit time. Surface them here for visibility.
        if not _private_api_keys_ok():
            return "BITFINEX_KEYS_MISSING"
        try:
            import bitfinex_live_executor as bx
            allowed, reason = bx._ddollar_gate_ok_for_entry()
            if not allowed:
                return f"DDOLLAR_GATE_BLOCKED ({reason})"
        except Exception as exc:
            _note_ddollar_gate_error(exc)
            return "DDOLLAR_GATE_BLOCKED (DDOLLAR_GATE_ERROR)"
        return None
    if mode == EXEC_MODE_EXIT_ONLY:
        return "EXIT_ONLY (bitfinex disarmed with open exposure)"
    # LAB_SHADOW
    status = get_pathway_lane_status(lane)
    if is_research_lane_retired(lane) or (
        lane != LEGACY_ADOPTION_LANE
        and status in ("RETIRED", "DATA_RETIRED", "BENCHMARK")
    ):
        return "LANE_RETIRED"
    if not is_research_lane_enabled(lane):
        return "TILE_OFF"
    if is_shadow_only_lane(lane):
        return "SHADOW_ONLY_LANE"
    return "TILE_OFF"



def guard_retired_lane_execution(lane: str, context: str, trade_id: str = None) -> bool:
    """Block order paths on retired, benchmark, and shadow-collecting lanes."""
    lane = str(lane or "").upper()
    if not lane_blocks_live_orders(lane):
        return True
    try:
        from pathway_lab_validation import log_retired_lane_violation
        log_retired_lane_violation(lane, context, trade_id=trade_id)
    except Exception:
        pass
    logger.error(
        f"[RETIRED_LANE_VIOLATION] lane={lane} context={context} trade_id={trade_id} "
        f"— order blocked [PIPELINE ENFORCEMENT]"
    )
    return False


def is_data_retired_lane(lane: str) -> bool:
    return get_pathway_lane_status(lane) == "DATA_RETIRED"


def lane_pipeline_allowed(lane: str = None) -> bool:
    lane = str(lane or RESEARCH_LANE_AI_SCAN).upper()
    if is_ai_scan_lane(lane):
        return shared_research_ai_observation_enabled()
    if lane_blocks_live_orders(lane):
        return False
    if is_research_lane_retired(lane):
        return False
    if is_combo_execution_lane(lane):
        return is_research_lane_enabled(lane)
    if lane == LEGACY_ADOPTION_LANE:
        return legacy_adoption_lane_enabled()
    return False

def get_lane_lock(lane: str):
    return _lane_locks.get(lane, process_lock)

def _lane_pipeline_running(lane: str) -> bool:
    with state_lock:
        return (state.get("lane_pipeline_stage") or {}).get(lane) == "RUNNING"

def _set_lane_pipeline_stage(lane: str, stage: str):
    with state_lock:
        stages = state.setdefault("lane_pipeline_stage", {})
        stages[lane] = stage

def apply_research_lane_tags(signal: dict, lane: str):
    signal["research_lane"] = lane
    signal["research_model"] = research_lane_label(lane)

def csv_lane_meta(signal: dict = None) -> dict:
    lane = (signal or {}).get("research_lane")
    return {
        "research_lane": lane,
        "research_model": (signal or {}).get("research_model") or research_lane_label(lane),
        "shared_ai_call_id": (signal or {}).get("shared_ai_call_id"),
        "shared_ai_call_ts": (signal or {}).get("shared_ai_call_ts"),
        "research_schema": "shared_direction_two_lane_v1",
        "research_collection_id": _collector_v22_epoch_id(),
    }

def _signal_lane_from_ref(signal_ref: dict) -> str:
    if not signal_ref:
        return ""
    return signal_ref.get("research_lane") or ""

def get_active_signal_count(lane: str = None):
    purge_dead_pending_orders()
    reconcile_stale_signals()
    with trade_lock:
        pending = [o for o in pending_orders if o.get("status") == "PENDING"]
        if lane:
            pending = [o for o in pending if o.get("research_lane") == lane]
        pending_count = len(pending)
        positions = open_positions
        if lane:
            positions = [p for p in open_positions if p.get("research_lane") == lane]
        open_count = len(positions)
        list_len = len(pending_orders)
        awaiting = []
        for entry in trades_map.values():
            sig = entry.get("signal_ref") or {}
            if not isinstance(sig, dict) or is_terminal_signal(sig):
                continue
            st = sig.get("status")
            if st not in (SIGNAL_STATUS_AWAITING_MICRO, SIGNAL_STATUS_AWAITING_5M, SIGNAL_STATUS_AWAITING_MIN_AGE, SIGNAL_STATUS_AWAITING_CHASE_3PLUS, SIGNAL_STATUS_AWAITING_DASHBOARD_CHASE):
                continue
            sig_lane = sig.get("research_lane")
            if lane and sig_lane != lane:
                continue
            awaiting.append(sig)
        pending_ids = {o.get("trade_id") for o in pending if o.get("trade_id")}
        open_ids = {p.get("trade_id") for p in positions if p.get("trade_id")}
        counted_ids = pending_ids | open_ids
        for entry in trades_map.values():
            sig = entry.get("signal_ref") or {}
            if not isinstance(sig, dict) or is_terminal_signal(sig):
                continue
            tid = sig.get("trade_id")
            if not tid or tid in counted_ids:
                continue
            if lane and sig.get("research_lane") != lane:
                continue
            if sig.get("status") in ("ORDERED", "ACTIVE", "PENDING"):
                awaiting.append(sig)
                counted_ids.add(tid)
        awaiting_count = len(awaiting)
        active = pending_count + open_count + awaiting_count
        exposure = [{"trade_id": o.get("trade_id"), "kind": "pending", "status": o.get("status"), "lane": o.get("research_lane")} for o in pending]
        exposure += [{"trade_id": p.get("trade_id"), "kind": "open", "lane": p.get("research_lane")} for p in positions]
        exposure += [{"trade_id": s.get("trade_id"), "kind": "awaiting", "status": s.get("status"), "lane": s.get("research_lane")} for s in awaiting]
        stale_map = len([
            s for s in trades_map.values()
            if (s.get("signal_ref") or {}).get("status") in ("ORDERED", "ACTIVE", "PENDING", SIGNAL_STATUS_AWAITING_MICRO, SIGNAL_STATUS_AWAITING_5M, SIGNAL_STATUS_AWAITING_MIN_AGE, SIGNAL_STATUS_AWAITING_CHASE_3PLUS, SIGNAL_STATUS_AWAITING_DASHBOARD_CHASE)
            and (s.get("signal_ref") or {}).get("trade_id") not in {e.get("trade_id") for e in exposure}
        ])
    _agent_dbg("H1", "get_active_signal_count", "counted", {"active": active, "lane": lane, "pending_pending_status": pending_count, "pending_list_len": list_len, "open_positions": open_count, "stale_map_orphans": stale_map, "exposure": exposure})
    if active == 0 and (pending_count + open_count) == 0:
        logger.debug(f"[EXECUTION FIX {EXECUTION_FIX_VERSION}] exposure_count=0 pending=0 positions=0 lane={lane}")
    return active

def research_isolation_enabled() -> bool:
    """Pathway Lab: each lane owns capacity/cooldown/rearm — no cross-lane contamination."""
    if not is_research_data_collection():
        return False
    with state_lock:
        if "research_isolation_mode" in state:
            return bool(state.get("research_isolation_mode"))
    return RESEARCH_ISOLATION_MODE


def get_lane_max_active_signals(lane: str = None) -> int:
    """Registry tiles own their capacity; other lanes use the dashboard pool."""
    tile_cap = tile_max_active_signals(lane)
    return tile_cap if tile_cap else get_effective_max_active_signals()


def ensure_lane_signal_capacity(lane: str) -> bool:
    """Per-tile slots for registry tiles; global pool for every other lane."""
    tile_cap = tile_max_active_signals(lane)
    if not tile_cap:
        return ensure_signal_capacity()
    return not _is_at_signal_capacity(tile_cap, lane=str(lane).upper())


def _normalize_lane_key(lane_or_obj) -> str:
    if isinstance(lane_or_obj, dict):
        return str(lane_or_obj.get("research_lane") or LEGACY_ADOPTION_LANE).upper()
    return str(lane_or_obj or LEGACY_ADOPTION_LANE).upper()


def _ensure_lane_bucket(lane: str) -> str:
    lane = _normalize_lane_key(lane)
    if lane not in lane_open_positions:
        lane_open_positions[lane] = []
        lane_pending_orders[lane] = []
    return lane


LANE_MEMORY_CHECK_INTERVAL_SEC = 600
_last_lane_memory_check_ts = 0.0
_PATHWAY_STARTUP_SNAPSHOT = {}
_pathway_receipt_lock = threading.RLock()


def _pathway_receipt_identity() -> dict:
    """Identity binding shared by every current runtime pathway receipt."""
    return {
        "source_git_rev": _runtime_git_rev(),
        "bot_version": EXECUTION_FIX_VERSION,
        "fresh_epoch_id": _collector_v22_epoch_id(),
        "tile_registry_signature": active_tile_registry_signature(),
        "analyzer_sync_id": COMBO_ANALYZER_SYNC_ID,
    }


def _publish_pathway_receipt(name: str, payload: dict) -> bool:
    """Atomically publish one receipt under BOT_DATA_DIR/runtime only.

    A volume-root copy shares the inventory basename with the same file under
    runtime and raises CheckpointError "conflicting inventory row".
    """
    root = _data_sync_runtime_root()
    root.mkdir(parents=True, exist_ok=True)
    target = root / Path(name).name
    return _atomic_file_replace(
        str(target),
        lambda handle: json.dump(payload, handle, indent=2, sort_keys=True),
        _pathway_receipt_lock,
        label="PATHWAY RECEIPT",
    )


def publish_startup_pathway_receipts() -> dict:
    from pathway_lab_validation import build_startup_contract_receipts
    receipts = build_startup_contract_receipts(
        _pathway_receipt_identity(),
        research_spawn_lanes=tuple(RESEARCH_SPAWN_LANES),
        ai_scan_orders_allowed=lane_orders_allowed(RESEARCH_LANE_AI_SCAN),
    )
    return {
        name: _publish_pathway_receipt(name, payload)
        for name, payload in receipts.items()
    }


def capture_pathway_startup_snapshot() -> dict:
    """Immutable startup contract for runtime drift detection."""
    global _PATHWAY_STARTUP_SNAPSHOT
    _PATHWAY_STARTUP_SNAPSHOT = {
        "captured_at": utc_iso(),
        "bot_version": EXECUTION_FIX_VERSION,
        "pathway_lane_status": dict(PATHWAY_LANE_STATUS),
        "combo_execution_lanes": tuple(COMBO_EXECUTION_LANES),
        "ai_direct_research_lanes": sorted(AI_DIRECT_RESEARCH_LANES),
    }
    return dict(_PATHWAY_STARTUP_SNAPSHOT)


def validate_lane_memory() -> dict:
    """Periodic: retired lanes must have zero pending/open; buckets bounded."""
    retired = [
        ln for ln, st in PATHWAY_LANE_STATUS.items()
        if st in ("RETIRED", "DATA_RETIRED")
    ]
    reconcile_lane_position_registry()
    pending_counts = {ln: len(get_lane_pending_orders(ln)) for ln in LANE_TRACKING_LANES}
    open_counts = {ln: len(get_lane_open_positions(ln)) for ln in LANE_TRACKING_LANES}
    try:
        from pathway_lab_validation import validate_lane_memory_runtime
        payload = validate_lane_memory_runtime(
            pending_counts, open_counts, tuple(retired),
            identity=_pathway_receipt_identity(),
        )
    except Exception as exc:
        payload = {
            **_pathway_receipt_identity(),
            "schema": "lane_memory_validation_v3",
            "generated_at": utc_iso(),
            "verdict": "ERROR",
            "error": str(exc),
        }
    verdict = payload.get("verdict")
    if verdict == "CRITICAL":
        logger.critical(
            f"[LANE MEMORY] CRITICAL — {payload.get('critical_issues')} [PIPELINE ENFORCEMENT]"
        )
    elif verdict == "WARN":
        logger.warning(
            f"[LANE MEMORY] WARN — {payload.get('warn_issues')} [PIPELINE ENFORCEMENT]"
        )
    _publish_pathway_receipt("lane_memory_validation.json", payload)
    if verdict == "CRITICAL":
        _publish_pathway_receipt("lane_memory_violation.json", payload)
    else:
        _publish_pathway_receipt("lane_memory_violation.json", {
            **_pathway_receipt_identity(),
            "schema": "lane_memory_violation_v1",
            "generated_at": utc_iso(),
            "active": False,
            "verdict": None,
            "detail": "No active lane-memory violation; see lane_memory_validation.json",
        })
    return payload


def validate_runtime_pathway_integrity() -> dict:
    """Every 10 min: detect runtime drift from startup pathway contract."""
    if not _PATHWAY_STARTUP_SNAPSHOT:
        return {"verdict": "SKIPPED", "detail": "startup snapshot not captured"}
    try:
        from pathway_lab_validation import validate_runtime_pathway_integrity as _validate
        payload = _validate(
            startup_snapshot=_PATHWAY_STARTUP_SNAPSHOT,
            current_pathway_lane_status=dict(PATHWAY_LANE_STATUS),
            current_combo_execution_lanes=tuple(COMBO_EXECUTION_LANES),
            ai_direct_research_lanes=AI_DIRECT_RESEARCH_LANES,
            research_spawn_lanes=tuple(RESEARCH_SPAWN_LANES),
            ai_scan_orders_allowed=lane_orders_allowed(RESEARCH_LANE_AI_SCAN),
            identity=_pathway_receipt_identity(),
        )
    except Exception as exc:
        payload = {
            **_pathway_receipt_identity(),
            "schema": "runtime_pathway_integrity_v2",
            "generated_at": utc_iso(),
            "verdict": "ERROR",
            "error": str(exc),
        }
    verdict = payload.get("verdict")
    if verdict == "CRITICAL":
        logger.critical(
            f"[PATHWAY INTEGRITY] CRITICAL — {payload.get('critical_issues')} [PIPELINE ENFORCEMENT]"
        )
    elif verdict == "WARN":
        logger.warning(
            f"[PATHWAY INTEGRITY] WARN — {payload.get('issues')} [PIPELINE ENFORCEMENT]"
        )
    _publish_pathway_receipt("runtime_pathway_integrity.json", payload)
    return payload


def apply_pathway_safety_block(lm_payload: dict, ri_payload: dict) -> None:
    """Block pipeline when any runtime pathway check is CRITICAL."""
    critical = (
        (lm_payload or {}).get("verdict") == "CRITICAL"
        or (ri_payload or {}).get("verdict") == "CRITICAL"
    )
    with state_lock:
        if critical:
            state["system_ready"] = False
            state["pathway_safety_block"] = True
            reasons = []
            if (lm_payload or {}).get("verdict") == "CRITICAL":
                reasons.append("lane_memory")
            if (ri_payload or {}).get("verdict") == "CRITICAL":
                reasons.append("runtime_integrity")
            state["pathway_safety_reason"] = "+".join(reasons) or "pathway_critical"
        else:
            state["pathway_safety_block"] = False
            state.pop("pathway_safety_reason", None)


def reconcile_lane_position_registry():
    """Rebuild lane-owned lists from global exposure (startup / state sync)."""
    if not research_isolation_enabled():
        return
    for ln in list(lane_open_positions.keys()):
        lane_open_positions[ln] = []
        lane_pending_orders[ln] = []
    with trade_lock:
        for o in pending_orders:
            if isinstance(o, dict) and o.get("status") == "PENDING":
                ln = _ensure_lane_bucket(o)
                if o not in lane_pending_orders[ln]:
                    lane_pending_orders[ln].append(o)
        for p in open_positions:
            if isinstance(p, dict):
                ln = _ensure_lane_bucket(p)
                if p not in lane_open_positions[ln]:
                    lane_open_positions[ln].append(p)


_pending_order_evidence_worker = None
_pending_order_evidence_worker_lock = threading.Lock()


def _write_pending_order_evidence(job: dict) -> None:
    payload = job.get("payload") or {}
    order = payload.get("order") or {}
    master_signal = payload.get("signal") or {}
    preentry_barrier = globals().get("_preentry_evidence_barrier")
    if callable(preentry_barrier):
        preentry_barrier(order, master_signal)
    collector_bridge = globals().get("_promote_collector_v22_registered_order")
    if callable(collector_bridge):
        collector_bridge(order, master_signal)
    if payload.get("is_paper_entry"):
        identity_receipt = dual_write_paper_order_intent(
            order, master_signal,
            epoch_id=_collector_v22_epoch_id(), data_dir=os.getcwd(),
        )
        for key in (
            "epoch_id", "opportunity_id", "policy_signature", "policy_epoch_id",
            "schedule_id", "fill_id", "tape_id",
        ):
            if identity_receipt.get(key):
                order[key] = identity_receipt[key]
    _emit_genome_execution_event("LIMIT_CREATED", {
        "trade_id": order.get("trade_id"),
        "limit_price": order.get("limit_price") or order.get("price"),
        "direction": order.get("dir") or order.get("direction"),
        "research_lane": order.get("research_lane"),
        "evidence_source_ts": job.get("source_ts"),
        "evidence_enqueued_ts": job.get("enqueued_ts"),
    })


def _get_pending_order_evidence_worker():
    global _pending_order_evidence_worker
    with _pending_order_evidence_worker_lock:
        if _pending_order_evidence_worker is None:
            _pending_order_evidence_worker = BoundedEvidenceWorker(
                _write_pending_order_evidence,
                max_queue=256,
                max_retries=2,
                name="pending-order-evidence",
                on_dead_letter=lambda row: logger.error(
                    f"[ORDER EVIDENCE] dead-letter key={row.get('key')} "
                    f"reason={row.get('reason')} attempt={row.get('attempt')} "
                    f"source_ts={row.get('source_ts')} error={row.get('error')} "
                    "[PIPELINE ENFORCEMENT]"
                ),
            )
        return _pending_order_evidence_worker


def _shutdown_pending_order_evidence_worker(timeout: float = 5.0) -> bool:
    worker = _pending_order_evidence_worker
    return True if worker is None else worker.shutdown(drain_timeout=timeout)


# Optional post-AI studies are deliberately isolated from the authoritative AI
# decision path.  A replay writer or research ledger may be degraded without
# preventing the next scheduled AI opportunity from being recorded.
_post_ai_evidence_workers = {}
_post_ai_evidence_workers_lock = threading.Lock()
# Optional evidence hooks can legitimately spend ~14s in the research-gate
# and filesystem validation path. Keep a finite ceiling so healthy hooks do
# not become false timeout gaps while a genuinely wedged hook still fails
# explicitly and cannot block the cadence owner forever.
POST_AI_EVIDENCE_HANDLER_TIMEOUT_SEC = 30.0
_post_ai_evidence_status = {
    "submitted": 0,
    "rejected": 0,
    "completed": 0,
    "last_submit_ts": 0.0,
    "last_complete_ts": 0.0,
    "last_completed_hook": None,
    "last_gap": None,
}


def _record_post_ai_evidence_gap(hook: str, reason: str, key: str, detail: str = "") -> None:
    receipt = {
        "schema": "post_ai_evidence_gap_v1",
        "ts": utc_iso(),
        "hook": str(hook),
        "reason": str(reason),
        "key": str(key),
        "detail": str(detail or "")[:500],
        "collector_version": COLLECTOR_VERSION,
        "git_rev": _runtime_git_rev(),
    }
    with state_lock:
        _post_ai_evidence_status["last_gap"] = copy.deepcopy(receipt)
    logger.error(
        "[POST_AI_EVIDENCE_GAP] hook=%s reason=%s key=%s detail=%s "
        "[PIPELINE ENFORCEMENT]",
        hook, reason, key, receipt["detail"],
    )


def _run_post_ai_evidence_hook(job: dict) -> None:
    payload = job.get("payload") or {}
    hook = str(payload.get("hook") or "")
    ctx = payload.get("ctx") or {}
    ai_result = payload.get("ai_result") or {}
    research_lane = str(payload.get("research_lane") or "")
    if hook == "reversal_study":
        started = start_reversal_study_replay(ctx, ai_result, research_lane)
        if started is False:
            _record_post_ai_evidence_gap(hook, "REPLAY_LOCK_TIMEOUT", job.get("key"))
    elif hook == "ai_reason":
        log_ai_reason_research(ctx, ai_result, research_lane)
    elif hook == "ai_shadow_challengers":
        _run_ai_shadow_challengers(ctx, ai_result)
    else:
        raise ValueError(f"unknown post-AI evidence hook: {hook}")
    with state_lock:
        _post_ai_evidence_status["completed"] += 1
        _post_ai_evidence_status["last_complete_ts"] = time.time()
        _post_ai_evidence_status["last_completed_hook"] = hook
        scheduled_ai_cycle_state["last_completed_hook"] = hook


def _post_ai_dead_letter(hook: str, row: dict) -> None:
    error = str(row.get("error") or "")
    reason = str(row.get("reason") or "DEAD_LETTER")
    if "evidence handler exceeded" in error:
        reason = "HOOK_TIMEOUT"
    _record_post_ai_evidence_gap(
        hook,
        reason,
        str(row.get("key") or ""),
        error,
    )


def _get_post_ai_evidence_worker(hook: str):
    with _post_ai_evidence_workers_lock:
        worker = _post_ai_evidence_workers.get(hook)
        if worker is None:
            worker = BoundedEvidenceWorker(
                _run_post_ai_evidence_hook,
                max_queue=64,
                max_retries=0,
                name=f"post-ai-{hook}",
                handler_timeout_sec=POST_AI_EVIDENCE_HANDLER_TIMEOUT_SEC,
                on_dead_letter=lambda row, _hook=hook: _post_ai_dead_letter(_hook, row),
            )
            _post_ai_evidence_workers[hook] = worker
        return worker


def enqueue_post_ai_research_hooks(ctx: dict, ai_result: dict, research_lane: str) -> dict:
    trade_id = str(ai_result.get("trade_id") or ctx.get("trade_id") or uuid.uuid4().hex)
    accepted = {}
    with state_lock:
        scheduled_ai_cycle_state.update({
            "stage": "POST_AI_ENQUEUE",
            "stage_started_ts": time.time(),
        })
    for hook in ("reversal_study", "ai_reason", "ai_shadow_challengers"):
        key = f"{hook}:{trade_id}"
        queued = _get_post_ai_evidence_worker(hook).submit(
            key,
            {
                "hook": hook,
                "ctx": ctx,
                "ai_result": ai_result,
                "research_lane": research_lane,
            },
            source_ts=time.time(),
        )
        accepted[hook] = bool(queued)
        with state_lock:
            _post_ai_evidence_status["submitted"] += int(bool(queued))
            _post_ai_evidence_status["rejected"] += int(not queued)
            _post_ai_evidence_status["last_submit_ts"] = time.time()
        if not queued:
            _record_post_ai_evidence_gap(hook, "QUEUE_REJECTED", key)
    with state_lock:
        scheduled_ai_cycle_state["last_completed_hook"] = "post_ai_hooks_enqueued"
    return accepted


def post_ai_evidence_health_snapshot() -> dict:
    with state_lock:
        snapshot = copy.deepcopy(_post_ai_evidence_status)
    with _post_ai_evidence_workers_lock:
        snapshot["workers"] = {
            hook: worker.snapshot() for hook, worker in _post_ai_evidence_workers.items()
        }
    return snapshot


def _shutdown_post_ai_evidence_workers(timeout: float = 2.0) -> bool:
    with _post_ai_evidence_workers_lock:
        workers = list(_post_ai_evidence_workers.values())
    return all(worker.shutdown(drain_timeout=timeout) for worker in workers)


def _paper_action_market_refs(order: dict) -> tuple:
    evidence = order.get("source_order_market_evidence") or {}
    if not isinstance(evidence, dict):
        evidence = {}
    return (
        order.get("book_ref") or evidence.get("book_ref"),
        order.get("tape_ref") or evidence.get("tape_ref") or order.get("tape_id"),
    )


def _append_paper_action_receipt(
    order: dict,
    signal: dict | None,
    *,
    action_generation: int,
    action_type: str,
    policy_due_ts: float,
    eligibility_ts: float,
    dispatch_start_ts: float,
    acknowledgement_ts: float,
    fill_ts: float | None = None,
    fill_price: float | None = None,
    filled_qty: float | None = None,
) -> dict | None:
    """Record an observed paper action without claiming unsupported latency."""
    book_ref, tape_ref = _paper_action_market_refs(order)
    return append_action_timing_receipt(
        order,
        signal if isinstance(signal, dict) else None,
        action_generation=action_generation,
        action_type=action_type,
        policy_due_ts=policy_due_ts,
        eligibility_ts=eligibility_ts,
        dispatch_start_ts=dispatch_start_ts,
        acknowledgement_ts=acknowledgement_ts,
        fill_ts=fill_ts,
        fill_price=fill_price,
        filled_qty=filled_qty,
        remaining_qty=(
            order.get("remaining_qty")
            if order.get("remaining_qty") is not None
            else order.get("qty")
        ),
        limit_price=order.get("limit_price"),
        book_ref=book_ref,
        tape_ref=tape_ref,
        non_intentional_delay={
            "classification": "UNKNOWN",
            "cause": "UNSUPPORTED_RUNTIME_DELAY_ATTRIBUTION",
        },
    )


def _stable_pending_signal_copy(signal: dict, attempts: int = 3) -> dict:
    """Snapshot a shared signal without propagating a transient writer race."""
    last_error = None
    for attempt in range(max(1, int(attempts))):
        try:
            return copy.deepcopy(signal) if isinstance(signal, dict) else {}
        except RuntimeError as exc:
            if "changed size during iteration" not in str(exc).lower():
                raise
            last_error = exc
            if attempt + 1 < max(1, int(attempts)):
                time.sleep(0)
    raise RuntimeError("pending signal remained mutable during snapshot") from last_error


def lane_register_pending_order(order: dict):
    """Dual-write once: global pending_orders + lane-owned bucket.

    Parallel promotion loops can reach this registry for the same signal. The
    trade ID is the idempotency key; object equality is not sufficient because
    each path constructs a fresh order dict with slightly different timestamps.
    """
    if not order:
        return False
    ln = _ensure_lane_bucket(order)
    # Prefer globals() so isolated characterization tests that exec() this
    # function without the coordination helpers still exercise idempotency.
    blocked_fn = globals().get("executable_live_copy_entries_blocked")
    blocked, block_reason, coord = blocked_fn() if callable(blocked_fn) else (False, "", "")
    if blocked and str(ln or "").upper() == "CONTINUOUS" and not order.get("coordination_shadow"):
        # Keep research/shadow labelled rows; block new live-copy executable book.
        logger.warning(
            f"[LIVE-COPY-COORD] blocking new CONTINUOUS pending "
            f"trade={order.get('trade_id')} state={coord} reason={block_reason} "
            "[PIPELINE ENFORCEMENT]"
        )
        order["status"] = "BLOCKED"
        order["outcome"] = LIVE_RELAY_COORDINATION_REASON
        order["coordination_state"] = coord
        return False
    tid = str(order.get("trade_id") or "")
    with trade_lock:
        # The canonical trade ID is a once-only lifecycle identity.  A delayed
        # promotion thread must not recreate an order after cleanup expired it,
        # after fill handoff began, or after it became an open/closed trade.
        handoff_ids = globals().get("fill_handoff_trade_ids") or set()
        position_rows = globals().get("open_positions") or []
        trade_rows = globals().get("trades") or []
        expired_rows = globals().get("expired_orders") or []
        retired = bool(tid) and (
            tid in handoff_ids
            or any(
                isinstance(row, dict) and str(row.get("trade_id") or "") == tid
                for row in position_rows
            )
            or any(
                isinstance(row, dict) and str(row.get("trade_id") or "") == tid
                for row in trade_rows
            )
            or any(
                isinstance(row, dict) and str(row.get("trade_id") or "") == tid
                for row in expired_rows
            )
        )
        if retired:
            order["registration_suppressed_reason"] = "RETIRED_LIFECYCLE"
            logger.warning(
                f"[ORDER IDEMPOTENCY] retired lifecycle registration suppressed "
                f"trade_id={tid} lane={ln} [PIPELINE ENFORCEMENT]"
            )
            return False
        existing = next(
            (
                row
                for row in pending_orders
                if isinstance(row, dict)
                and tid
                and str(row.get("trade_id") or "") == tid
                and str(row.get("status") or "").upper() in ("PENDING", "FILLED")
            ),
            None,
        )
        if existing is not None:
            existing_lane = _ensure_lane_bucket(existing)
            existing_bucket = lane_pending_orders[existing_lane]
            if existing not in existing_bucket:
                existing_bucket.append(existing)
            logger.warning(
                f"[ORDER IDEMPOTENCY] duplicate pending registration suppressed "
                f"trade_id={tid} lane={ln} [PIPELINE ENFORCEMENT]"
            )
            return False
        pending_orders.append(order)
        lst = lane_pending_orders[ln]
        if order not in lst:
            lst.append(order)
    trades_store = globals().get("trades_map") or {}
    master_signal = trades_store.get(tid, {}).get("signal_ref") if tid else None
    try:
        snapshot_fn = globals().get("_stable_pending_signal_copy", copy.deepcopy)
        signal_snapshot = (
            snapshot_fn(master_signal) if isinstance(master_signal, dict) else {}
        )
    except RuntimeError as exc:
        # A hot shared signal must not kill the position manager.  The pending
        # order is already canonical; continue with its lane-local fields and
        # explicitly omit the unstable enrichment instead of publishing a
        # torn cross-lane snapshot.
        logger.warning(
            f"[ORDER EVIDENCE] signal snapshot deferred trade_id={tid} error={exc} "
            "[PIPELINE ENFORCEMENT]"
        )
        signal_snapshot = {}
    schedule_initializer = globals().get("initialize_research_order_schedule")
    if callable(schedule_initializer):
        schedule_initializer(
            order,
            signal_snapshot,
            now=float(order.get("created_ts") or time.time()),
            registered=True,
        )
    hydrate = globals().get("_sync_canonical_source_pending_order")
    store = globals().get("_canonical_source_order_market_evidence")
    if callable(hydrate) and isinstance(store, dict):
        hydrate(
            store,
            order,
            chase_acked=False,
            observed_ts=order.get("last_chase_ts") or order.get("created_ts"),
        )
    is_paper_entry = not bool(order.get("bitfinex_order_id") or order.get("bitfinex_live_entry")) and str(order.get("entry_type") or "").upper() not in {"POSTONLY_TP", "REDUCE_ONLY", "EXIT"}
    if is_paper_entry:
        # Freeze the signed paper-policy identity at the atomic order boundary.
        # Later entry helpers and relay-capability checks may enrich mutable
        # state, but must never mint a second signature for this episode.
        frozen_identity = paper_policy_identity_for_sources(
            _collector_v22_epoch_id(),
            order,
            signal_snapshot,
        )
        order.update(copy.deepcopy(frozen_identity))
        capture_helper = globals().get("_capture_runtime_quantity_constraints")
        constraint_capture = (
            capture_helper(requested_qty=order.get("qty")) if callable(capture_helper) else {
                "supported": False, "receipt": None,
                "reasons": ["VENUE_QUANTITY_CONSTRAINT_CAPTURE_HELPER_UNAVAILABLE"],
            }
        )
        order["signed_quantity_constraints"] = copy.deepcopy(
            constraint_capture.get("receipt")
        )
        order["quantity_constraints_status"] = copy.deepcopy(constraint_capture)
        captured_receipt = constraint_capture.get("receipt")
        order["market_microstructure_symbol"] = (
            globals().get("BITFINEX_WS_SYMBOL")
            or (captured_receipt.get("symbol") if isinstance(captured_receipt, dict) else None)
        )
        # ``master_signal`` is shared by every research lane spawned from one
        # AI call.  A lane-scoped paper identity belongs to its order and
        # position only; writing it back here lets the next lane inherit the
        # wrong policy signature.
        registered_ts = time.time()
        dispatch_ts = float(order.pop("_initial_dispatch_start_ts", registered_ts))
        receipt_writer = globals().get("_append_paper_action_receipt")
        if callable(receipt_writer):
            receipt_writer(
                order,
                signal_snapshot,
                action_generation=0,
                action_type="INITIAL_SUBMIT",
                policy_due_ts=float(order.get("created_ts") or dispatch_ts),
                eligibility_ts=float(order.get("created_ts") or dispatch_ts),
                dispatch_start_ts=dispatch_ts,
                acknowledgement_ts=registered_ts,
            )
    source_ts = float(order.get("created_ts") or time.time())
    evidence_key = f"pending-order:{tid}"
    queued = _get_pending_order_evidence_worker().submit(
        evidence_key,
        {
            "order": copy.deepcopy(order),
            "signal": signal_snapshot,
            "is_paper_entry": is_paper_entry,
        },
        source_ts=source_ts,
    )
    if not queued:
        logger.warning(
            f"[ORDER EVIDENCE] queue full/stopped enqueue trade_id={tid} "
            f"source_ts={source_ts} [PIPELINE ENFORCEMENT]"
        )
    persist = globals().get("save_paper_lifecycle")
    if callable(persist):
        persist(reason="pending_registered")
    return True


def lane_unregister_pending_order(order: dict):
    if not order:
        return
    ln = _normalize_lane_key(order)
    with trade_lock:
        if order in pending_orders:
            pending_orders.remove(order)
        lst = lane_pending_orders.get(ln, [])
        if order in lst:
            lst.remove(order)
    persist = globals().get("save_paper_lifecycle")
    if callable(persist):
        persist(reason="pending_unregistered")


def lane_register_open_position(pos: dict):
    if not pos:
        return
    ln = _ensure_lane_bucket(pos)
    with trade_lock:
        if pos not in open_positions:
            open_positions.append(pos)
        lst = lane_open_positions[ln]
        if pos not in lst:
            lst.append(pos)
    persist = globals().get("save_paper_lifecycle")
    if callable(persist):
        persist(reason="position_registered")


