def update_lane_pnl_ledger(lane: str, event: str, net_pnl_usd: float = 0.0, direction: str = None):
    """Per-lane equity curve stats — independent attribution for Pathway Lab."""
    ln = _normalize_lane_key(lane)
    with state_lock:
        ledger = state.setdefault("lane_pnl_ledger", {})
        bucket = ledger.setdefault(ln, {
            "lane": ln,
            "net_pnl_usd": 0.0,
            "gross_wins_usd": 0.0,
            "gross_losses_usd": 0.0,
            "wins": 0,
            "losses": 0,
            "closes": 0,
            "long_closes": 0,
            "short_closes": 0,
            "long_pnl_usd": 0.0,
            "short_pnl_usd": 0.0,
            "equity_usd": float(STARTING_BALANCE),
        })
        if event == "CLOSE":
            bucket["closes"] = int(bucket.get("closes", 0)) + 1
            bucket["net_pnl_usd"] = round(float(bucket.get("net_pnl_usd", 0)) + float(net_pnl_usd or 0), 2)
            bucket["equity_usd"] = round(float(STARTING_BALANCE) + bucket["net_pnl_usd"], 2)
            if net_pnl_usd > 0:
                bucket["wins"] = int(bucket.get("wins", 0)) + 1
                bucket["gross_wins_usd"] = round(float(bucket.get("gross_wins_usd", 0)) + net_pnl_usd, 2)
            elif net_pnl_usd < 0:
                bucket["losses"] = int(bucket.get("losses", 0)) + 1
                bucket["gross_losses_usd"] = round(float(bucket.get("gross_losses_usd", 0)) + net_pnl_usd, 2)
            d = str(direction or "").upper()
            if d == "LONG":
                bucket["long_closes"] = int(bucket.get("long_closes", 0)) + 1
                bucket["long_pnl_usd"] = round(float(bucket.get("long_pnl_usd", 0)) + net_pnl_usd, 2)
            elif d == "SHORT":
                bucket["short_closes"] = int(bucket.get("short_closes", 0)) + 1
                bucket["short_pnl_usd"] = round(float(bucket.get("short_pnl_usd", 0)) + net_pnl_usd, 2)
        try:
            with open(LANE_PNL_LEDGER_FILE, "w", encoding="utf-8") as f:
                json.dump(
                    {"schema": "lane_pnl_ledger_v1", "ts": utc_iso(), "lanes": ledger},
                    f,
                    indent=2,
                )
            _LEDGER_WRITES.success("lane_pnl")
        except Exception as exc:
            _LEDGER_WRITES.failure("lane_pnl", exc)
            logger.error(f"[LEDGER] lane_pnl write failed: {type(exc).__name__}: {exc}")



def _trade_row_net_pnl_usd(row) -> float:
    """Canonical realized PnL of one closed trade row (0.0 is a real value)."""
    for key in ("net_pnl_usd", "net", "pnl"):
        value = row.get(key)
        if value in (None, ""):
            continue
        try:
            return float(value)
        except (TypeError, ValueError):
            return 0.0
    return 0.0


def _derive_lane_pnl_ledger_from_trades(session_trades) -> dict:
    """Rebuild per-lane PnL ledger from a session trades list.

    Safety net for the incremental `update_lane_pnl_ledger` path: any close
    that fails to call the increment (e.g. exception path, race, restart
    forgetting to replay) would otherwise leave the dashboard tile frozen
    under-counting real PnL. The dashboard snapshot now overlays the
    authoritative `trades` list each refresh, so deriving the ledger from
    that same list guarantees the tile matches the trades table.

    Shape matches `state["lane_pnl_ledger"]` produced by
    `update_lane_pnl_ledger`. Input rows are the in-memory trade dicts.
    """
    ledger: dict = {}
    for row in session_trades or []:
        if not isinstance(row, dict):
            continue
        lane = _normalize_lane_key(row.get("research_lane") or "")
        if not lane:
            continue
        pnl = _trade_row_net_pnl_usd(row)
        bucket = ledger.setdefault(lane, {
            "lane": lane,
            "net_pnl_usd": 0.0,
            "gross_wins_usd": 0.0,
            "gross_losses_usd": 0.0,
            "wins": 0,
            "losses": 0,
            "closes": 0,
            "long_closes": 0,
            "short_closes": 0,
            "long_pnl_usd": 0.0,
            "short_pnl_usd": 0.0,
            "equity_usd": float(STARTING_BALANCE),
        })
        bucket["closes"] = int(bucket.get("closes", 0)) + 1
        bucket["net_pnl_usd"] = round(float(bucket.get("net_pnl_usd", 0)) + pnl, 2)
        bucket["equity_usd"] = round(float(STARTING_BALANCE) + bucket["net_pnl_usd"], 2)
        if pnl > 0:
            bucket["wins"] = int(bucket.get("wins", 0)) + 1
            bucket["gross_wins_usd"] = round(float(bucket.get("gross_wins_usd", 0)) + pnl, 2)
        elif pnl < 0:
            bucket["losses"] = int(bucket.get("losses", 0)) + 1
            bucket["gross_losses_usd"] = round(float(bucket.get("gross_losses_usd", 0)) + pnl, 2)
        d = str(row.get("final_direction") or row.get("dir") or "").upper()
        if d == "LONG":
            bucket["long_closes"] = int(bucket.get("long_closes", 0)) + 1
            bucket["long_pnl_usd"] = round(float(bucket.get("long_pnl_usd", 0)) + pnl, 2)
        elif d == "SHORT":
            bucket["short_closes"] = int(bucket.get("short_closes", 0)) + 1
            bucket["short_pnl_usd"] = round(float(bucket.get("short_pnl_usd", 0)) + pnl, 2)
    return ledger


