def _http_get_with_retry(url: str, params=None, timeout: float = 30, label: str = "HTTP", max_attempts: int = 5):
    """Resilient GET: retries timeouts, connection drops, and HTTP 429."""
    last_err = None
    for attempt in range(max_attempts):
        try:
            resp = _bitfinex_http_session.get(url, params=params, timeout=timeout)
            if resp.status_code == 429:
                _RATE_LIMITS.hit("bitfinex_rest", label)
                wait = min(2 ** attempt, 30)
                logger.warning(f"[{label}] HTTP 429 rate limit - retry {attempt + 1}/{max_attempts} in {wait}s")
                time.sleep(wait)
                continue
            resp.raise_for_status()
            return resp
        except (requests.Timeout, requests.ConnectionError) as e:
            last_err = e
            wait = min(2 ** attempt, 15)
            logger.warning(f"[{label}] network error ({e}) - retry {attempt + 1}/{max_attempts} in {wait}s")
            time.sleep(wait)
        except requests.RequestException as e:
            last_err = e
            if attempt + 1 >= max_attempts:
                raise
            wait = min(2 ** attempt, 15)
            logger.warning(f"[{label}] request error ({e}) - retry {attempt + 1}/{max_attempts} in {wait}s")
            time.sleep(wait)
    raise last_err or RuntimeError(f"{label} failed after {max_attempts} attempts")


def _exchange_call_with_retry(fn, label: str = "EXCHANGE", max_attempts: int = 5):
    """Wrap ccxt calls: rate limits, timeouts, and transient network failures."""
    last_err = None
    for attempt in range(max_attempts):
        try:
            return fn()
        except ccxt.RateLimitExceeded as e:
            _RATE_LIMITS.hit("bitfinex_ccxt", label)
            last_err = e
            wait = min(2 ** attempt, 30)
            logger.warning(f"[{label}] ccxt rate limit - retry {attempt + 1}/{max_attempts} in {wait}s")
            time.sleep(wait)
        except (ccxt.NetworkError, ccxt.RequestTimeout, ccxt.ExchangeNotAvailable) as e:
            last_err = e
            wait = min(2 ** attempt, 15)
            logger.warning(f"[{label}] ccxt network ({e}) - retry {attempt + 1}/{max_attempts} in {wait}s")
            time.sleep(wait)
        except ccxt.ExchangeError as e:
            msg = str(e).lower()
            # The platform relay and paper owner may perform authenticated
            # reads with the same Bitfinex key.  Their nonce generators share
            # the same timestamp scale but cannot share an in-process lock, so
            # a read can lose a same-millisecond race and receive ``nonce:
            # small``.  Treat only that explicit response as transient.  The
            # retry allocates a fresh timestamp-scaled nonce; other exchange
            # errors continue to fail closed immediately.
            if "nonce: small" in msg and attempt + 1 < max_attempts:
                last_err = e
                wait = min(0.05 * (attempt + 1), 0.25)
                logger.warning(
                    f"[{label}] Bitfinex nonce race - retry "
                    f"{attempt + 1}/{max_attempts} in {wait:.2f}s"
                )
                time.sleep(wait)
                continue
            if "429" in msg or "rate" in msg:
                _RATE_LIMITS.hit("bitfinex_ccxt", label)
                last_err = e
                wait = min(2 ** attempt, 30)
                logger.warning(f"[{label}] exchange rate limit - retry {attempt + 1}/{max_attempts} in {wait}s")
                time.sleep(wait)
                continue
            raise
    raise last_err or RuntimeError(f"{label} failed after {max_attempts} attempts")


def fetch_bitfinex_ohlcv(timeframe: str = "15m", limit: int = 250) -> list:
    """Bitfinex REST candles (ccxt OHLCV for perps can return stale rows)."""
    key = f"trade:{timeframe}:{BITFINEX_WS_SYMBOL}"
    url = f"{BITFINEX_REST_BASE}/candles/{key}/hist"
    resp = _http_get_with_retry(url, params={"limit": limit}, timeout=30, label="OHLCV")
    rows = resp.json() or []
    candles = []
    for row in reversed(rows):
        ts, o, c, h, l, v = row[0], float(row[1]), float(row[2]), float(row[3]), float(row[4]), float(row[5])
        candles.append([ts, o, h, l, c, v])
    return candles

def synthetic_funding_rate_8h():
    """Fallback 8h rate from premium (price vs EMA200) + orderflow when API unavailable."""
    with state_lock:
        price = nz(state.get("price"))
        ema200 = nz(state.get("ema_status", {}).get("ema200"))
        imbalance = nz(orderflow.get("imbalance", 0))
        delta = nz(orderflow.get("delta", 0))
    if price <= 0 or ema200 <= 0:
        return 0.0
    premium = (price - ema200) / ema200
    rate = (premium * 0.15) + (imbalance * 0.00005) + (0.00002 if delta > 0 else -0.00002 if delta < 0 else 0)
    return max(-FUNDING_RATE_CAP_PER_8H, min(FUNDING_RATE_CAP_PER_8H, rate))

def _effective_funding_rate_8h(current_funding: float, next_accrued: float) -> float:
    """Bitfinex: CURRENT_FUNDING is the live 8h rate; if zero, use next-period accrual."""
    cur = float(current_funding or 0.0)
    if abs(cur) >= 1e-12:
        return max(-FUNDING_RATE_CAP_PER_8H, min(FUNDING_RATE_CAP_PER_8H, cur))
    acc = float(next_accrued or 0.0)
    if abs(acc) >= 1e-12:
        return max(-FUNDING_RATE_CAP_PER_8H, min(FUNDING_RATE_CAP_PER_8H, acc))
    return 0.0

def fetch_bitfinex_ticker_rest(symbol: str = BITFINEX_WS_SYMBOL) -> dict:
    """Bitfinex v2 ticker: BID, ASK, LAST (and daily stats)."""
    url = f"{BITFINEX_REST_BASE}/ticker/{symbol}"
    resp = _http_get_with_retry(url, timeout=10, label="TICKER")
    data = resp.json()
    if isinstance(data, list) and len(data) > 6:
        bid = float(data[0])
        ask = float(data[2])
        last = float(data[6])
        return {
            "bid": bid,
            "ask": ask,
            "last": last,
            "spread_usd": round(ask - bid, 2),
            "spread_pct": round((ask - bid) / bid * 100.0, 5) if bid > 0 else 0.0,
        }
    raise ValueError(f"unexpected ticker response: {data!r}")


def fetch_bitfinex_last_price_rest(symbol: str = BITFINEX_WS_SYMBOL) -> float:
    """Latest trade price from Bitfinex REST ticker (dashboard fallback when WS stale)."""
    return fetch_bitfinex_ticker_rest(symbol)["last"]


def _fetch_bitfinex_ticker_rest_hot() -> dict:
    """One bounded ticker attempt using an isolated HTTP session.

    The hot readiness loop must not inherit the five-attempt retry/backoff
    budget or share a requests.Session with unrelated REST workers.  A failed
    attempt leaves the strict REST freshness gate closed; the next scheduled
    attempt can recover without blocking OHLCV maintenance.
    """
    url = f"{BITFINEX_REST_BASE}/ticker/{BITFINEX_WS_SYMBOL}"
    with requests.Session() as session:
        session.headers.update({"User-Agent": "btc-research-bot/1.0"})
        response = session.get(
            url,
            timeout=(BBO_HOT_CONNECT_TIMEOUT_SEC, BBO_HOT_READ_TIMEOUT_SEC),
        )
        response.raise_for_status()
        data = response.json()
    if not isinstance(data, list) or len(data) <= 6:
        raise ValueError(f"unexpected ticker response: {data!r}")
    bid, ask, last = float(data[0]), float(data[2]), float(data[6])
    if bid <= 0 or ask <= 0 or last <= 0 or ask < bid:
        raise ValueError("invalid ticker bid/ask/last")
    return {
        "bid": bid,
        "ask": ask,
        "last": last,
        "spread_usd": round(ask - bid, 2),
        "spread_pct": round((ask - bid) / bid * 100.0, 5),
    }


def refresh_bbo_state(force: bool = False):
    """Bounded, coalesced BBO refresh; never hold its claim across network I/O."""
    global _last_bbo_refresh_ts, _bbo_refresh_claim_token, _bbo_refresh_claim_started_ts
    now = time.time()
    if not force and (now - _last_bbo_refresh_ts) < BBO_REFRESH_SEC:
        return True
    token = uuid.uuid4().hex
    if not _bbo_refresh_lock.acquire(blocking=False):
        return False
    try:
        now = time.time()
        if not force and (now - _last_bbo_refresh_ts) < BBO_REFRESH_SEC:
            return True
        claim_age = (
            now - float(_bbo_refresh_claim_started_ts or 0)
            if _bbo_refresh_claim_token
            else 0.0
        )
        if _bbo_refresh_claim_token and claim_age <= BBO_REFRESH_CLAIM_TTL_SEC:
            return False
        if _bbo_refresh_claim_token:
            with state_lock:
                state["bbo_refresh_stale_claims"] = int(
                    state.get("bbo_refresh_stale_claims") or 0
                ) + 1
        _bbo_refresh_claim_token = token
        _bbo_refresh_claim_started_ts = now
        with state_lock:
            state["bbo_refresh_last_attempt_ts"] = now
            state["bbo_refresh_inflight"] = True
            state["bbo_refresh_inflight_age_sec"] = 0.0
    finally:
        _bbo_refresh_lock.release()

    request_started_at = time.time()
    try:
        ticker = _fetch_bitfinex_ticker_rest_hot()
        completed_at = time.time()
        duration_sec = max(0.0, completed_at - request_started_at)
        with _bbo_refresh_lock:
            if _bbo_refresh_claim_token != token:
                return False
            with state_lock:
                state["bid"] = ticker["bid"]
                state["ask"] = ticker["ask"]
                state["spread_usd"] = ticker["spread_usd"]
                state["spread_pct"] = ticker["spread_pct"]
                state["bbo_ts"] = completed_at
                state["rest_last_tick"] = completed_at
                state["last_trade_price"] = ticker["last"]
                state["rest_price"] = ticker["last"]
                state["rest_price_ts"] = completed_at
                state["bbo_refresh_last_success_ts"] = completed_at
                state["bbo_refresh_last_duration_sec"] = duration_sec
                state["bbo_refresh_max_duration_sec"] = max(
                    float(state.get("bbo_refresh_max_duration_sec") or 0),
                    duration_sec,
                )
                state["bbo_refresh_last_error"] = None
                state["bbo_refresh_consecutive_failures"] = 0
                ws_age = completed_at - float(state.get("ws_last_tick") or 0)
                if ws_age > WS_ENTRY_FRESH_SEC:
                    state["ws_ready"] = False
                    state["last_ready_ts"] = 0
                    state["system_ready"] = False
            _last_bbo_refresh_ts = completed_at
        return True
    except Exception as exc:
        failed_at = time.time()
        duration_sec = max(0.0, failed_at - request_started_at)
        with state_lock:
            state["bbo_refresh_last_error"] = f"{type(exc).__name__}: {exc}"[:240]
            state["bbo_refresh_last_failure_ts"] = failed_at
            state["bbo_refresh_last_duration_sec"] = duration_sec
            state["bbo_refresh_max_duration_sec"] = max(
                float(state.get("bbo_refresh_max_duration_sec") or 0),
                duration_sec,
            )
            state["bbo_refresh_total_failures"] = int(
                state.get("bbo_refresh_total_failures") or 0
            ) + 1
            state["bbo_refresh_consecutive_failures"] = int(
                state.get("bbo_refresh_consecutive_failures") or 0
            ) + 1
        logger.warning(f"[BBO] bounded refresh failed: {exc} [PIPELINE ENFORCEMENT]")
        return False
    finally:
        with _bbo_refresh_lock:
            if _bbo_refresh_claim_token == token:
                _bbo_refresh_claim_token = None
                _bbo_refresh_claim_started_ts = 0.0
                with state_lock:
                    state["bbo_refresh_inflight"] = False
                    state["bbo_refresh_inflight_age_sec"] = 0.0


def fetch_bitfinex_book_rest(symbol: str = BITFINEX_WS_SYMBOL, precision: str = "P0") -> dict:
    """Bitfinex v2 book: rows are [PRICE, COUNT, AMOUNT]; amount>0 bid, amount<0 ask."""
    url = f"{BITFINEX_REST_BASE}/book/{symbol}/{precision}"
    resp = _http_get_with_retry(url, timeout=12, label="BOOK")
    rows = resp.json()
    if not isinstance(rows, list):
        raise ValueError(f"unexpected book response: {rows!r}")
    bids, asks = [], []
    for row in rows:
        if not isinstance(row, (list, tuple)) or len(row) < 3:
            continue
        price = float(row[0])
        count = int(row[1])
        amount = float(row[2])
        if amount > 0:
            bids.append([price, count, amount])
        elif amount < 0:
            asks.append([price, count, abs(amount)])
    bids.sort(key=lambda x: -x[0])
    asks.sort(key=lambda x: x[0])
    # Cap depth — top-of-book is all sim fills ever walk; storing the full raw
    # P0 book (1000+ levels) wastes CPU and memory under the state_lock.
    if MAX_BOOK_LEVELS > 0:
        bids = bids[:MAX_BOOK_LEVELS]
        asks = asks[:MAX_BOOK_LEVELS]
    return {"bids": bids, "asks": asks, "level_count": len(bids) + len(asks)}


def _fetch_bitfinex_book_rest_hot() -> dict:
    """One bounded depth attempt isolated from unrelated REST sessions."""
    url = f"{BITFINEX_REST_BASE}/book/{BITFINEX_WS_SYMBOL}/P0"
    with requests.Session() as session:
        session.headers.update({"User-Agent": "btc-research-bot/1.0"})
        response = session.get(
            url,
            timeout=(BOOK_HOT_CONNECT_TIMEOUT_SEC, BOOK_HOT_READ_TIMEOUT_SEC),
        )
        response.raise_for_status()
        rows = response.json()
    if not isinstance(rows, list):
        raise ValueError(f"unexpected book response: {rows!r}")
    bids, asks = [], []
    for row in rows:
        if not isinstance(row, (list, tuple)) or len(row) < 3:
            continue
        price = float(row[0])
        count = int(row[1])
        amount = float(row[2])
        if amount > 0:
            bids.append([price, count, amount])
        elif amount < 0:
            asks.append([price, count, abs(amount)])
    bids.sort(key=lambda level: -level[0])
    asks.sort(key=lambda level: level[0])
    if MAX_BOOK_LEVELS > 0:
        bids = bids[:MAX_BOOK_LEVELS]
        asks = asks[:MAX_BOOK_LEVELS]
    if not bids or not asks:
        raise ValueError("order book missing bid or ask depth")
    return {"bids": bids, "asks": asks, "level_count": len(bids) + len(asks)}


def refresh_order_book_state(force: bool = False):
    """Cache Bitfinex order book for depth-aware sim fills (refreshed with BBO cadence).

    ``force=True`` coalesces to ``BOOK_FORCE_MIN_SEC`` so multiple hot loops
    (pending orders, positions, dashboard, stale-book path) demanding a refresh
    at the same time only trigger ONE REST fetch, not one per caller. That
    coalescing is what keeps the Flask HTTP thread from being CPU-starved.
    """
    global _last_book_refresh_ts, _book_refresh_claim_token, _book_refresh_claim_started_ts
    now = time.time()
    min_interval = BOOK_FORCE_MIN_SEC if force else BOOK_REFRESH_SEC
    if (now - _last_book_refresh_ts) < min_interval:
        return True
    token = uuid.uuid4().hex
    if not _book_refresh_lock.acquire(blocking=False):
        return False
    try:
        now = time.time()
        min_interval = BOOK_FORCE_MIN_SEC if force else BOOK_REFRESH_SEC
        if (now - _last_book_refresh_ts) < min_interval:
            return True
        claim_age = (
            now - float(_book_refresh_claim_started_ts or 0)
            if _book_refresh_claim_token
            else 0.0
        )
        if _book_refresh_claim_token and claim_age <= BOOK_REFRESH_CLAIM_TTL_SEC:
            return False
        if _book_refresh_claim_token:
            with state_lock:
                state["book_refresh_stale_claims"] = int(
                    state.get("book_refresh_stale_claims") or 0
                ) + 1
        _book_refresh_claim_token = token
        _book_refresh_claim_started_ts = now
        with state_lock:
            state["book_refresh_last_attempt_ts"] = now
            state["book_refresh_inflight"] = True
    finally:
        _book_refresh_lock.release()

    try:
        book = _fetch_bitfinex_book_rest_hot()
        completed_at = time.time()
        with _book_refresh_lock:
            if _book_refresh_claim_token != token:
                return False
            with state_lock:
                state["order_book"] = book
                state["book_ts"] = completed_at
                bids = book.get("bids") or []
                asks = book.get("asks") or []
                state["bid_size_btc"] = round(float(bids[0][2]), 6) if bids else None
                state["ask_size_btc"] = round(float(asks[0][2]), 6) if asks else None
                state["book_refresh_last_success_ts"] = completed_at
                state["book_refresh_last_error"] = None
                state["book_refresh_consecutive_failures"] = 0
            _last_book_refresh_ts = completed_at
        return True
    except Exception as exc:
        with state_lock:
            state["book_refresh_last_error"] = f"{type(exc).__name__}: {exc}"[:240]
            state["book_refresh_consecutive_failures"] = int(
                state.get("book_refresh_consecutive_failures") or 0
            ) + 1
        logger.warning(f"[BOOK] bounded refresh failed: {exc} [PIPELINE ENFORCEMENT]")
        return False
    finally:
        with _book_refresh_lock:
            if _book_refresh_claim_token == token:
                _book_refresh_claim_token = None
                _book_refresh_claim_started_ts = 0.0
                with state_lock:
                    state["book_refresh_inflight"] = False


def simulate_market_fill(side: str, qty_btc: float) -> dict:
    """Walk cached book for taker fill: buy consumes asks, sell consumes bids."""
    side = str(side or "").lower()
    qty_btc = float(qty_btc or 0)
    empty = {
        "avg_price": 0.0,
        "filled_qty": 0.0,
        "slippage_usd": 0.0,
        "fully_filled": False,
        "levels_consumed": 0,
        "partial_fill": False,
        "best_price": 0.0,
        "unfilled_qty": qty_btc,
    }
    if qty_btc <= 0:
        return dict(empty, fully_filled=True, unfilled_qty=0.0)
    with state_lock:
        book_age = time.time() - float(state.get("book_ts") or 0)
    refresh_order_book_state(force=book_age > BOOK_STALE_SEC)
    with state_lock:
        book = state.get("order_book") or {}
        bid = float(state.get("bid") or 0)
        ask = float(state.get("ask") or 0)
        last = float(state.get("price") or 0)
    if side == "buy":
        levels = book.get("asks") or []
        best = float(levels[0][0]) if levels else ask
    elif side == "sell":
        levels = book.get("bids") or []
        best = float(levels[0][0]) if levels else bid
    else:
        return dict(empty, fully_filled=True, unfilled_qty=0.0)
    if not levels:
        px = best if best > 0 else last
        if px <= 0:
            return empty
        logger.debug(f"[BOOK] no cached levels side={side} - BBO fallback px={px} [PIPELINE ENFORCEMENT]")
        return {
            "avg_price": round(px, 2),
            "filled_qty": round(qty_btc, 8),
            "slippage_usd": 0.0,
            "fully_filled": True,
            "levels_consumed": 0,
            "partial_fill": False,
            "best_price": round(px, 2),
            "unfilled_qty": 0.0,
            "book_empty": True,
        }
    remaining = qty_btc
    cost = 0.0
    filled = 0.0
    levels_consumed = 0
    for price, _count, size in levels:
        if remaining <= 1e-12:
            break
        take = min(remaining, float(size))
        cost += take * float(price)
        filled += take
        remaining -= take
        levels_consumed += 1
    if filled <= 0:
        px = best if best > 0 else last
        return {
            "avg_price": round(px, 2),
            "filled_qty": 0.0,
            "slippage_usd": 0.0,
            "fully_filled": False,
            "levels_consumed": 0,
            "partial_fill": False,
            "best_price": round(px, 2),
            "unfilled_qty": round(qty_btc, 8),
        }
    avg_price = cost / filled
    slip_per_btc = (avg_price - best) if side == "buy" else (best - avg_price)
    slippage_usd = max(0.0, slip_per_btc * filled)
    fully_filled = remaining <= 1e-9
    partial_fill = not fully_filled and filled > 0
    if partial_fill:
        logger.warning(
            f"[BOOK] partial fill side={side} req={qty_btc:.6f} filled={filled:.6f} "
            f"levels={levels_consumed} vwap={avg_price:.2f} [PIPELINE ENFORCEMENT]"
        )
    elif levels_consumed > 1 or slippage_usd > 0.01:
        logger.info(
            f"[BOOK] depth fill side={side} qty={qty_btc:.6f} vwap={avg_price:.2f} "
            f"best={best:.2f} slip=${slippage_usd:.4f} levels={levels_consumed} [PIPELINE ENFORCEMENT]"
        )
    return {
        "avg_price": round(avg_price, 2),
        "filled_qty": round(filled, 8),
        "slippage_usd": round(slippage_usd, 4),
        "fully_filled": fully_filled,
        "levels_consumed": levels_consumed,
        "partial_fill": partial_fill,
        "best_price": round(best, 2),
        "unfilled_qty": round(remaining, 8) if partial_fill else 0.0,
    }


def simulate_marketable_limit_fill(
    side: str,
    qty_btc: float,
    limit_price: float,
    levels,
    *,
    book_observed_ts=None,
) -> dict:
    """Walk only book levels executable at the order's hard limit.

    A marketable limit is not an unrestricted market order.  Consuming levels
    beyond the limit and then clipping the reported VWAP fabricates both price
    and quantity.  This pure walk preserves honest partial/no-fill evidence and
    keeps the stored slippage arithmetic tied to the exact consumed levels.
    """
    side = str(side or "").lower()
    qty_btc = float(qty_btc or 0)
    limit_price = float(limit_price or 0)
    empty = {
        "avg_price": 0.0,
        "filled_qty": 0.0,
        "slippage_usd": 0.0,
        "fully_filled": qty_btc <= 0,
        "levels_consumed": 0,
        "partial_fill": False,
        "best_price": 0.0,
        "unfilled_qty": max(0.0, qty_btc),
        "book_observed_ts": book_observed_ts,
        "book_source": "CACHED_ORDER_BOOK",
        "consumed_levels": [],
        "evidence_status": "UNKNOWN",
        "unknown_reason": None,
    }
    if side not in ("buy", "sell") or qty_btc <= 0 or limit_price <= 0:
        empty["unknown_reason"] = "INVALID_LIMIT_FILL_REQUEST"
        return empty
    normalized = []
    for raw in levels or []:
        try:
            price = float(raw[0])
            size = float(raw[2])
        except (TypeError, ValueError, IndexError):
            continue
        if price <= 0 or size <= 0:
            continue
        normalized.append((price, size))
    if not normalized:
        empty["unknown_reason"] = "ORDER_BOOK_DEPTH_MISSING"
        return empty
    best = normalized[0][0]
    empty["best_price"] = round(best, 2)
    eligible = [
        (price, size) for price, size in normalized
        if (side == "buy" and price <= limit_price)
        or (side == "sell" and price >= limit_price)
    ]
    if not eligible:
        empty.update(evidence_status="COMPLETE", unknown_reason=None)
        return empty
    remaining = qty_btc
    notional = 0.0
    filled = 0.0
    consumed = []
    for price, size in eligible:
        if remaining <= 1e-12:
            break
        take = min(remaining, size)
        notional += take * price
        filled += take
        remaining -= take
        consumed.append({"price": price, "quantity_btc": take})
    if filled <= 0:
        empty["unknown_reason"] = "ELIGIBLE_DEPTH_NOT_CONSUMABLE"
        return empty
    avg_price = notional / filled
    slip_per_btc = (avg_price - best) if side == "buy" else (best - avg_price)
    fully_filled = remaining <= 1e-9
    return {
        "avg_price": round(avg_price, 2),
        "filled_qty": round(filled, 8),
        "slippage_usd": round(max(0.0, slip_per_btc * filled), 4),
        "fully_filled": fully_filled,
        "levels_consumed": len(consumed),
        "partial_fill": bool(filled > 0 and not fully_filled),
        "best_price": round(best, 2),
        "unfilled_qty": round(max(0.0, remaining), 8),
        "book_observed_ts": book_observed_ts,
        "book_source": "CACHED_ORDER_BOOK",
        "consumed_levels": consumed,
        "evidence_status": "COMPLETE",
        "unknown_reason": None,
    }


def get_mark_price(direction: str, fallback: float = None) -> float:
    """Realistic mark for PnL/exits: LONG marks at bid (sellable), SHORT at ask (cover buy)."""
    direction = str(direction or "").upper()
    with state_lock:
        bid = float(state.get("bid") or 0)
        ask = float(state.get("ask") or 0)
        last = float(fallback if fallback is not None else (state.get("price") or 0))
    if direction == "LONG" and bid > 0:
        return bid
    if direction == "SHORT" and ask > 0:
        return ask
    return last if last > 0 else 0.0


def get_executable_mark_price(pos: dict, fallback: float = None) -> float:
    """Depth-weighted exit VWAP for open positions; BBO mark when book empty."""
    direction = str((pos or {}).get("dir") or "").upper()
    qty = float((pos or {}).get("qty") or 0)
    if qty > 0 and direction in ("LONG", "SHORT"):
        exit_side = "sell" if direction == "LONG" else "buy"
        sim = simulate_market_fill(exit_side, qty)
        vwap = float(sim.get("avg_price") or 0)
        if vwap > 0:
            return vwap
    return get_mark_price(direction, fallback=fallback)


def resolve_sim_fill_with_depth(order: dict) -> dict:
    """Depth-aware market fill; every limit fill respects its hard price."""
    limit = float(order.get("limit_price") or 0)
    side = str(order.get("side") or "").lower()
    qty = float(order.get("qty") or 0)
    refresh_bbo_state()
    refresh_order_book_state()
    with state_lock:
        bid = float(state.get("bid") or 0)
        ask = float(state.get("ask") or 0)
        last = float(state.get("price") or limit or 0)
        book = copy.deepcopy(state.get("order_book") or {})
        book_observed_ts = state.get("book_ts")
    is_market_order = order.get("entry_type") in ("SIM_MARKET", "MARKET")
    crossed_limit = (
        (side == "buy" and ask > 0 and limit >= ask)
        or (side == "sell" and bid > 0 and limit <= bid)
    )
    if is_market_order and qty > 0:
        sim = simulate_market_fill(side, qty)
        fill_px = sim["avg_price"]
        filled_qty = sim["filled_qty"]
        if filled_qty <= 0:
            fill_px = ask if side == "buy" else bid
            filled_qty = qty
            sim = dict(sim, avg_price=round(fill_px, 2), filled_qty=qty, fully_filled=True, partial_fill=False)
        return {"fill_price": fill_px, "filled_qty": filled_qty, "is_taker": True, **sim}
    if crossed_limit and limit > 0:
        # A newly marketable LIMIT can be a taker, but it can never execute at
        # a worse price than its limit.  Walking the unrestricted market book
        # here previously produced impossible fills (for example a SHORT sell
        # below its sell limit) and broke paper-to-Bitfinex lifecycle fidelity.
        levels = book.get("asks") if side == "buy" else book.get("bids")
        sim = simulate_marketable_limit_fill(
            side, qty, limit, levels or [], book_observed_ts=book_observed_ts,
        )
        fill_px = float(sim.get("avg_price") or 0)
        filled_qty = float(sim.get("filled_qty") or 0)
        return {
            "fill_price": fill_px,
            "filled_qty": filled_qty,
            "is_taker": True,
            "avg_price": fill_px,
            "best_price": sim.get("best_price"),
            "slippage_usd": float(sim.get("slippage_usd") or 0),
            "fully_filled": bool(sim.get("fully_filled", False)),
            "partial_fill": bool(sim.get("partial_fill", False)),
            "levels_consumed": int(sim.get("levels_consumed") or 0),
            "unfilled_qty": float(sim.get("unfilled_qty") or 0),
            "book_observed_ts": sim.get("book_observed_ts"),
            "book_source": sim.get("book_source"),
            "consumed_levels": copy.deepcopy(sim.get("consumed_levels") or []),
            "evidence_status": sim.get("evidence_status"),
            "unknown_reason": sim.get("unknown_reason"),
        }
    fill_px = round(limit, 2) if limit > 0 else last
    return {
        "fill_price": fill_px,
        "filled_qty": qty,
        "is_taker": False,
        "avg_price": fill_px,
        "best_price": fill_px,
        "slippage_usd": 0.0,
        "fully_filled": True,
        "partial_fill": False,
        "levels_consumed": 0,
        "unfilled_qty": 0.0,
    }


def resolve_sim_fill_price(order: dict) -> float:
    """Sim fill: depth-aware taker VWAP when crossing spread; else maker at limit."""
    # Evidence-only: freeze the requested ticket size before a partial paper
    # fill narrows ``qty`` to the actually opened position.
    order.setdefault("requested_qty", order.get("qty"))
    result = resolve_sim_fill_with_depth(order)
    order["fill_sim"] = {k: v for k, v in result.items() if k not in ("fill_price", "filled_qty")}
    order["filled_qty"] = result.get("filled_qty")
    order["remaining_qty"] = result.get("unfilled_qty")
    if result.get("partial_fill"):
        order["partial_fill"] = True
        order["qty"] = result["filled_qty"]
        residual = float(result.get("unfilled_qty") or 0.0)
        order["residual_cancelled_qty"] = residual
        order["residual_disposition"] = "CANCELLED_AFTER_PARTIAL_SIM_FILL"
        order["residual_cancelled_ts"] = time.time()
        order["fill_sim"]["unfilled_disposition"] = (
            "CANCELLED_AFTER_PARTIAL_SIM_FILL"
        )
    elif result.get("is_taker") and result.get("slippage_usd"):
        order["book_slippage_usd"] = result["slippage_usd"]
    return result["fill_price"]


_TRIGGER_CONSISTENT_EXIT_REASONS = frozenset({
    "PROFIT_LOCK_LADDER",
    "THESIS_FAST_CUT",
    "THESIS_INVALIDATED",
    # Registry-owned family policies are evaluated from the fresh side-correct
    # tick in _apply_position_exits.  Booking a second, independently refreshed
    # book walk after the trigger can turn a 30% paper hard stop into a much
    # larger reported loss and make the dashboard exit disagree with its PnL.
    "PHYSICAL_HARD_STOP_30PCT",
    "INITIAL_ATR_STOP",
    "PROFIT_PROTECTION_STOP",
    "BREAKEVEN_LOCK",
    "PATH_END_120M",
})
# Registry policies name their hard stop and time exit from their own limits.
_HARD_STOP_REASON = re.compile(r"PHYSICAL_HARD_STOP_\d+(\.\d+)?PCT")
_TIME_EXIT_REASON = re.compile(r"PATH_END_\d+M")


def _is_trigger_consistent_exit_reason(reason) -> bool:
    reason = str(reason or "").upper()
    return (
        reason in _TRIGGER_CONSISTENT_EXIT_REASONS
        or bool(_HARD_STOP_REASON.fullmatch(reason))
        or bool(_TIME_EXIT_REASON.fullmatch(reason))
        # GS/B regime exit stacks (gs_regime_exit_stack) book the trigger tick
        # or, for a maker take-profit, the resting target itself.
        or reason.startswith("GS_")
    )


def resolve_sim_exit_price(pos: dict, exit_is_maker: bool, exit_reason: str) -> tuple:
    """Exit price: ladder/thesis book the trigger; maker only for explicit TP limit hits."""
    qty = float(pos.get("qty") or 0)
    direction = str(pos.get("dir") or "").upper()
    fallback = get_mark_price(direction, fallback=state.get("price", pos.get("entry", 0)))
    trigger = float(pos.get("_exit_eval_price") or 0)
    if _is_trigger_consistent_exit_reason(exit_reason):
        # Do not walk the book to a far-better VWAP than the side-correct
        # trigger that actually fired the rule (the old STOP_LOSS mismatch).
        px = trigger if trigger > 0 else fallback
        if px <= 0:
            px = float(pos.get("entry") or 0)
        sim = {
            "avg_price": round(px, 2),
            "filled_qty": qty,
            "fully_filled": True,
            "source": "exit_trigger_side_correct",
            "trigger_price": round(trigger, 2) if trigger > 0 else None,
        }
        return round(px, 2), sim
    refresh_bbo_state()
    refresh_order_book_state()
    fallback = get_mark_price(direction, fallback=state.get("price", pos.get("entry", 0)))
    if exit_is_maker:
        tp_px = float(pos.get("tp") or 0)
        if tp_px > 0 and exit_reason in ("TAKE_PROFIT", "TP_HIT"):
            return tp_px, None
        return fallback, None
    exit_side = "sell" if direction == "LONG" else "buy"
    sim = simulate_market_fill(exit_side, qty)
    px = sim["avg_price"] if sim.get("avg_price", 0) > 0 else fallback
    return px, sim


_last_dashboard_rest_refresh_ts = 0.0
DASHBOARD_REST_MIN_INTERVAL_SEC = 12.0


def refresh_dashboard_market_snapshot(force: bool = False):
    """Refresh a display/risk REST quote without mutating strategy WS truth."""
    global _last_dashboard_rest_refresh_ts
    now = time.time()
    with state_lock:
        price_ts = state.get("price_ts") or 0
        ws_tick = state.get("ws_last_tick") or 0
    ref_ts = max(price_ts, ws_tick)
    age = (now - ref_ts) if ref_ts else 9999.0
    threshold = 5.0 if force else 10.0
    if age < threshold:
        refresh_bbo_state(force=force)
        refresh_order_book_state(force=force)
        return
    if now - _last_dashboard_rest_refresh_ts < DASHBOARD_REST_MIN_INTERVAL_SEC:
        return
    try:
        refresh_bbo_state(force=True)
        refresh_order_book_state(force=True)
        rest_price = fetch_bitfinex_last_price_rest()
        _last_dashboard_rest_refresh_ts = now
        if rest_price and rest_price > 0:
            with state_lock:
                state["rest_price"] = rest_price
                state["rest_price_ts"] = now
                state["rest_last_tick"] = now
                state["price_seq"] = int(state.get("price_seq") or 0) + 1
                diag = state.setdefault("diag", {})
                diag["ws_status"] = "STALE" if age >= STALE_HARD_SEC else "REST_FALLBACK"
            sync_dashboard_branding()
            logger.debug(
                f"[DASHBOARD] REST price refresh {fmt(rest_price)} feed_age={age:.0f}s [PIPELINE ENFORCEMENT]"
            )
    except Exception as e:
        logger.debug(f"[DASHBOARD] REST price refresh failed: {e} [PIPELINE ENFORCEMENT]")


def fetch_bitfinex_deriv_funding_rest(symbol: str = BITFINEX_WS_SYMBOL) -> dict:
    """Live perp funding from Bitfinex GET /v2/status/deriv?keys=... (public, no API key)."""
    url = f"{BITFINEX_REST_BASE}/status/deriv"
    resp = _http_get_with_retry(url, params={"keys": symbol}, timeout=12, label="FUNDING")
    payload = resp.json()
    if not payload or not isinstance(payload, list):
        raise ValueError("empty deriv status response")
    row = payload[0]
    if not isinstance(row, (list, tuple)) or len(row) < 13:
        raise ValueError(f"unexpected deriv status row len={len(row) if isinstance(row, (list, tuple)) else 'n/a'}")
    current = row[_DERIV_STATUS_CURRENT_FUNDING]
    next_accrued = row[_DERIV_STATUS_NEXT_FUNDING_ACCRUED]
    rate = _effective_funding_rate_8h(current, next_accrued)
    next_ms = row[_DERIV_STATUS_NEXT_FUNDING_MTS]
    next_ts = float(next_ms) / 1000.0 if next_ms else None
    mark = row[_DERIV_STATUS_MARK_PRICE] if len(row) > _DERIV_STATUS_MARK_PRICE else None
    spot = row[_DERIV_STATUS_SPOT_PRICE] if len(row) > _DERIV_STATUS_SPOT_PRICE else None
    oi = row[_DERIV_STATUS_OPEN_INTEREST] if len(row) > _DERIV_STATUS_OPEN_INTEREST else None
    return {
        "rate": rate,
        "current_funding": float(current or 0.0),
        "next_funding_accrued": float(next_accrued or 0.0),
        "next_funding_step": int(row[_DERIV_STATUS_NEXT_FUNDING_STEP] or 0),
        "next_time": next_ts,
        "mark_price": float(mark) if mark is not None else None,
        "index_price": float(spot) if spot is not None else None,
        "open_interest": float(oi) if oi is not None else None,
        "clamp_min": float(row[_DERIV_STATUS_CLAMP_MIN]) if len(row) > _DERIV_STATUS_CLAMP_MIN and row[_DERIV_STATUS_CLAMP_MIN] is not None else None,
        "clamp_max": float(row[_DERIV_STATUS_CLAMP_MAX]) if len(row) > _DERIV_STATUS_CLAMP_MAX and row[_DERIV_STATUS_CLAMP_MAX] is not None else None,
        "source": "BITFINEX_DERIV_STATUS",
    }

def refresh_funding_state(force: bool = False):
    """Pull live Bitfinex perp funding; update state['funding'] for sim + AI."""
    global _last_funding_refresh_ts
    if not FUNDING_SIMULATION_ENABLED:
        return
    now = time.time()
    if not force and now - _last_funding_refresh_ts < FUNDING_REFRESH_SEC:
        return
    rate = None
    next_ts = None
    mark = None
    index = None
    source = "SYNTHETIC"
    meta = {}
    try:
        meta = fetch_bitfinex_deriv_funding_rest(BITFINEX_WS_SYMBOL)
        rate = meta.get("rate")
        next_ts = meta.get("next_time")
        mark = meta.get("mark_price")
        index = meta.get("index_price")
        source = meta.get("source", "BITFINEX_DERIV_STATUS")
    except Exception as e:
        logger.warning(f"[FUNDING] Bitfinex deriv status failed: {e} - trying ccxt [PIPELINE ENFORCEMENT]")
        try:
            fr = get_bitfinex_public().fetch_funding_rate(SYMBOL_CCXT)
            rate = fr.get("fundingRate")
            if rate is None:
                rate = fr.get("nextFundingRate")
            next_ms = fr.get("nextFundingTimestamp") or fr.get("fundingTimestamp")
            if next_ms:
                next_ts = float(next_ms) / 1000.0
            mark = fr.get("markPrice")
            index = fr.get("indexPrice")
            source = "BITFINEX_CCXT"
        except Exception as e2:
            logger.warning(f"[FUNDING] ccxt funding failed: {e2} - using synthetic [PIPELINE ENFORCEMENT]")
    if rate is None:
        rate = synthetic_funding_rate_8h()
        source = "SYNTHETIC"
    else:
        rate = float(rate)
    if next_ts is None or next_ts < now:
        next_ts = now + FUNDING_INTERVAL_HOURS * 3600
    with state_lock:
        state["funding"] = {
            "rate": rate,
            "rate_pct_per_8h": round(rate * 100, 5),
            "next_time": next_ts,
            "next_time_iso": datetime.fromtimestamp(next_ts, tz=timezone.utc).isoformat(),
            "mark_price": mark,
            "index_price": index,
            "interval_hours": FUNDING_INTERVAL_HOURS,
            "source": source,
            "longs_pay": rate > 0,
            "shorts_receive_when_positive": rate > 0,
            "updated_ts": now,
            "current_funding": meta.get("current_funding"),
            "next_funding_accrued": meta.get("next_funding_accrued"),
            "next_funding_step": meta.get("next_funding_step"),
            "open_interest": meta.get("open_interest"),
            "clamp_min": meta.get("clamp_min"),
            "clamp_max": meta.get("clamp_max"),
            "symbol": BITFINEX_WS_SYMBOL,
        }
    _last_funding_refresh_ts = now
    logger.info(
        f"[FUNDING] {source} rate_8h={rate*100:.5f}% current={meta.get('current_funding')} "
        f"next_accrued={meta.get('next_funding_accrued')} next_settlement="
        f"{datetime.fromtimestamp(next_ts, tz=timezone.utc).isoformat()} longs_pay={rate > 0} "
        f"[PIPELINE ENFORCEMENT]"
    )
    if rate > 0:
        with trade_lock:
            short_n = sum(
                1 for p in open_positions
                if p.get("dir") == "SHORT" and p.get("status") == "OPEN"
            )
        if short_n:
            logger.info(
                f"[FUNDING MONITOR] positive rate with {short_n} open SHORT(s) - favorable carry (monitor only) "
                f"[PIPELINE ENFORCEMENT]"
            )

def funding_cost_for_position(pos: dict, rate_8h: float, hours: float) -> float:
    """
    USD funding cashflow for holding `hours` at `rate_8h` (per 8h period).
    Positive = cost to trader; negative = rebate.
    LONG pays when rate > 0; SHORT receives when rate > 0.
    """
    notional = nz(pos.get("entry")) * nz(pos.get("qty"))
    if notional <= 0 or hours <= 0:
        return 0.0
    dir_sign = 1.0 if pos.get("dir") == "LONG" else -1.0
    return dir_sign * notional * rate_8h * (hours / FUNDING_INTERVAL_HOURS)

def funding_side_label(rate_8h: float, direction: str) -> str:
    if abs(float(rate_8h or 0)) < 1e-12:
        return "NEUTRAL"
    if direction == "LONG":
        return "LONG_PAYS" if rate_8h > 0 else "LONG_RECEIVES"
    return "SHORT_RECEIVES" if rate_8h > 0 else "SHORT_PAYS"

def projected_funding_to_next_settlement(pos: dict, funding: dict = None) -> float:
    """USD funding until next Bitfinex settlement (uses live rate from state)."""
    if funding is None:
        with state_lock:
            funding = copy.deepcopy(state.get("funding") or {})
    next_ts = float(funding.get("next_time") or 0)
    if next_ts <= 0:
        return 0.0
    hours = max(0.0, (next_ts - time.time()) / 3600.0)
    return funding_cost_for_position(pos, float(funding.get("rate") or 0.0), hours)

def accrue_position_funding(pos: dict, now: float = None, *, refresh: bool = True):
    if not FUNDING_SIMULATION_ENABLED:
        return
    if now is None:
        now = time.time()
    if refresh:
        refresh_funding_state()
    with state_lock:
        rate = state.get("funding", {}).get("rate", 0.0)
    last = pos.get("last_funding_accrual_ts") or pos.get("entry_ts") or now
    dt_hours = max(0.0, (now - last) / 3600.0)
    if dt_hours <= 0:
        return
    payment = funding_cost_for_position(pos, rate, dt_hours)
    pos["funding_fees"] = pos.get("funding_fees", 0.0) + payment
    pos["last_funding_accrual_ts"] = now

def process_funding_accrual():
    if not FUNDING_SIMULATION_ENABLED:
        return
    now = time.time()
    refresh_funding_state()
    with trade_lock:
        for pos in list(open_positions):
            if pos.get("status") != "OPEN":
                continue
            accrue_position_funding(pos, now, refresh=False)

def get_funding_snapshot_for_ai():
    refresh_funding_state()
    with state_lock:
        f = copy.deepcopy(state.get("funding", {}))
    rate = f.get("rate", 0.0)
    f["interpretation"] = (
        "LONGS_PAY_SHORTS" if rate > 0 else "SHORTS_PAY_LONGS" if rate < 0 else "NEUTRAL"
    )
    f["favors_short_when_positive"] = rate > 0
    f["favors_long_when_negative"] = rate < 0
    return f

# --- Phase A: balanced market context (structure, MTF, EMA facts, trend strength) ---
MTF_REFRESH_SEC = 300
MTF_5M_REFRESH_SEC = 60
MTF_1M_REFRESH_SEC = 15
STRUCTURE_PIVOT_BARS = 2
_mtf_cache = {"1h": {"ts": 0.0, "candles": []}, "4h": {"ts": 0.0, "candles": []}}
_last_market_context_ts = 0.0

def _pct_diff(a, b):
    if a is None or b is None or b == 0:
        return 0.0
    return round((a - b) / b * 100, 4)

def extract_pivot_swings(candles, left=STRUCTURE_PIVOT_BARS, right=STRUCTURE_PIVOT_BARS):
    if not candles or len(candles) < left + right + 3:
        return []
    swings = []
    for i in range(left, len(candles) - right):
        window = candles[i - left : i + right + 1]
        hi = candles[i][2]
        lo = candles[i][3]
        if hi >= max(c[2] for c in window):
            swings.append({"type": "high", "price": hi, "idx": i})
        if lo <= min(c[3] for c in window):
            swings.append({"type": "low", "price": lo, "idx": i})
    swings.sort(key=lambda x: x["idx"])
    deduped = []
    for s in swings:
        if deduped and deduped[-1]["idx"] == s["idx"]:
            continue
        deduped.append(s)
    return deduped

def label_swing_sequence(swings, max_labels=6):
    highs = [s for s in swings if s["type"] == "high"]
    lows = [s for s in swings if s["type"] == "low"]
    labels = []
    for seq, tag_up, tag_down, tag_eq in (
        (highs, "HH", "LH", "EH"),
        (lows, "HL", "LL", "EL"),
    ):
        for i in range(1, len(seq)):
            prev, curr = seq[i - 1], seq[i]
            if curr["price"] > prev["price"]:
                labels.append(tag_up)
            elif curr["price"] < prev["price"]:
                labels.append(tag_down)
            else:
                labels.append(tag_eq)
    labels = labels[-max_labels:]
    score_map = {"HH": 2, "HL": 1, "LH": -1, "LL": -2, "EH": 0, "EL": 0}
    score = sum(score_map.get(l, 0) for l in labels)
    return labels, score


def last_swing_pair_labels(swings) -> dict:
    """Latest swing-high label and latest swing-low label, judged separately.

    ``label_swing_sequence`` lists every high label before every low label, so
    its last two entries are both low labels whenever two lows exist; a pattern
    check on that tail can never see LH or HH. Two-sided flags come from here.
    """
    out = {}
    for kind, up, down, eq in (("high", "HH", "LH", "EH"), ("low", "HL", "LL", "EL")):
        seq = [s["price"] for s in swings if s["type"] == kind][-2:]
        if len(seq) < 2:
            out[kind] = None
        else:
            out[kind] = up if seq[1] > seq[0] else (down if seq[1] < seq[0] else eq)
    last_high, last_low = out["high"], out["low"]
    return {
        "last_high_label": last_high,
        "last_low_label": last_low,
        "higher_high": last_high == "HH",
        "lower_high": last_high == "LH",
        "higher_low": last_low == "HL",
        "lower_low": last_low == "LL",
        "hh_hl_sequence_active": last_high == "HH" and last_low == "HL",
        "lh_ll_sequence_active": last_high == "LH" and last_low == "LL",
    }


def compute_market_structure(candles):
    swings = extract_pivot_swings(candles[-96:] if len(candles) > 96 else candles)
    labels, score = label_swing_sequence(swings, max_labels=6)
    if score >= 3:
        bias = "BULLISH_STRUCTURE"
    elif score <= -3:
        bias = "BEARISH_STRUCTURE"
    elif score > 0:
        bias = "LEAN_BULL"
    elif score < 0:
        bias = "LEAN_BEAR"
    else:
        bias = "MIXED"
    last_highs = [s["price"] for s in swings if s["type"] == "high"][-2:]
    last_lows = [s["price"] for s in swings if s["type"] == "low"][-2:]
    return {
        "swing_labels_last": labels,
        "structure_score": score,
        "structure_bias": bias,
        **last_swing_pair_labels(swings),
        "last_swing_high": last_highs[-1] if last_highs else None,
        "last_swing_low": last_lows[-1] if last_lows else None,
        "pivot_count": len(swings),
    }

def _entry_ema9_ema21() -> tuple:
    with state_lock:
        es = state.get("ema_status") or {}
    return float(es.get("ema9") or 0), float(es.get("ema21") or 0)

def compute_ema_hybrid_base(direction: str, price: float, ema9: float, ema21: float):
    """LONG: max(ema9, ema21) below price. SHORT: min(ema9, ema21) above price."""
    if not price or price <= 0:
        return None
    direction = str(direction or "").upper()
    if direction == "LONG":
        cands = [e for e in (ema9, ema21) if e > 0 and e < price]
        return max(cands) if cands else None
    if direction == "SHORT":
        cands = [e for e in (ema9, ema21) if e > 0 and e > price]
        return min(cands) if cands else None
    return None

def apply_ema_hybrid_entry_offset(direction: str, hybrid_base: float) -> float:
    """LONG: +$offset (higher bid, closer fill). SHORT: -$offset (lower offer, closer fill)."""
    off = float(EMA_HYBRID_ENTRY_OFFSET_USD)
    direction = str(direction or "").upper()
    if direction == "LONG":
        return float(hybrid_base) + off
    if direction == "SHORT":
        return float(hybrid_base) - off
    return float(hybrid_base)

def _micro_structure_market_snapshot() -> dict:
    update_market_context()
    with state_lock:
        mc = copy.deepcopy(state.get("market_context") or {})
        candles = copy.deepcopy(latest_candles)
    ms = mc.get("market_structure") or {}
    if (not ms.get("last_swing_high") or not ms.get("last_swing_low")) and candles:
        ms = compute_market_structure(candles)
    return ms


def build_micro_sr_levels(candles=None, max_pivots: int = None) -> dict:
    """Detect last N swing pivots and derive micro support / resistance levels."""
    max_pivots = int(max_pivots or MICRO_SR_PIVOT_LOOKBACK)
    if candles is None:
        with state_lock:
            candles = copy.deepcopy(latest_candles) or []
    window = candles[-96:] if len(candles) > 96 else candles
    swings = extract_pivot_swings(window)
    highs = [s for s in swings if s["type"] == "high"][-max_pivots:]
    lows = [s for s in swings if s["type"] == "low"][-max_pivots:]
    labels, score = label_swing_sequence(swings, max_labels=8)
    if score >= 3:
        bias = "BULLISH_STRUCTURE"
    elif score <= -3:
        bias = "BEARISH_STRUCTURE"
    elif score > 0:
        bias = "LEAN_BULL"
    elif score < 0:
        bias = "LEAN_BEAR"
    else:
        bias = "MIXED"
    micro_support = float(lows[-1]["price"]) if lows else None
    micro_resistance = float(highs[-1]["price"]) if highs else None
    pair = last_swing_pair_labels(swings)
    return {
        "micro_support": micro_support,
        "micro_resistance": micro_resistance,
        "prior_support": float(lows[-2]["price"]) if len(lows) >= 2 else None,
        "prior_resistance": float(highs[-2]["price"]) if len(highs) >= 2 else None,
        "pivot_count": len(swings),
        "swing_labels_last": labels,
        "structure_score": score,
        "structure_bias": bias,
        **pair,
        "last_swing_low": micro_support,
        "last_swing_high": micro_resistance,
    }


def build_micro_sr_levels_5m(candles=None, max_pivots: int = None) -> dict:
    """5m pivot micro S/R — uses Bitfinex 5m OHLC, not WS tick buffer."""
    if candles is None:
        candles = fetch_mtf_candles("5m", limit=200)
    return build_micro_sr_levels(candles=candles, max_pivots=max_pivots)


def evaluate_5m_structure_confirm(direction: str, price: float, ms_5m: dict = None) -> dict:
    """5m execution trigger: LONG=higher_low, SHORT=lower_high at 5m pivot level."""
    direction = str(direction or "").upper()
    price = float(price or 0)
    if ms_5m is None:
        ms_5m = build_micro_sr_levels_5m()
    micro_support = ms_5m.get("micro_support")
    micro_resistance = ms_5m.get("micro_resistance")
    pattern_ok = False
    micro_level = None
    if direction == "LONG":
        pattern_ok = bool(ms_5m.get("higher_low"))
        micro_level = micro_support
    elif direction == "SHORT":
        pattern_ok = bool(ms_5m.get("lower_high"))
        micro_level = micro_resistance
    confirmed = bool(pattern_ok and micro_level)
    return {
        "confirmed": confirmed,
        "pattern_ok": pattern_ok,
        "micro_support": micro_support,
        "micro_resistance": micro_resistance,
        "micro_sr_level": micro_level,
        "higher_low": ms_5m.get("higher_low"),
        "lower_high": ms_5m.get("lower_high"),
        "structure_score": ms_5m.get("structure_score"),
        "pivot_count": ms_5m.get("pivot_count"),
    }


def _ema_zone_reached(direction: str, price: float, ema9: float, ema21: float) -> tuple:
    """EMA zone arms setup when price is near the EMA hybrid reference."""
    hybrid_base = compute_ema_hybrid_base(direction, price, ema9, ema21)
    if hybrid_base is None or price <= 0:
        return False, None
    dist_pct = abs(price - hybrid_base) / price
    return dist_pct <= MICRO_SR_EMA_ZONE_PCT, hybrid_base


def _micro_sr_rejection(
    direction: str, price: float, micro_support: float, micro_resistance: float, near_pct: float
) -> bool:
    """Price rejecting off micro support (long) or micro resistance (short)."""
    direction = str(direction or "").upper()
    price = float(price or 0)
    if price <= 0:
        return False
    if direction == "LONG" and micro_support:
        ms = float(micro_support)
        near = abs(price - ms) / price <= near_pct * 2
        return price >= ms and (near or price > ms * (1 + near_pct * 0.5))
    if direction == "SHORT" and micro_resistance:
        mr = float(micro_resistance)
        near = abs(price - mr) / price <= near_pct * 2
        return price <= mr and (near or price < mr * (1 - near_pct * 0.5))
    return False


def evaluate_micro_structure_confirm(
    direction: str, price: float, limit_price: float = None, ms: dict = None
) -> dict:
    """Pivot-based micro S/R confirmation: HL/LH + intact swing + rejection at micro level."""
    direction = str(direction or "").upper()
    price = float(price or 0)
    if ms is None:
        ms = build_micro_sr_levels()
    struct_score = float(ms.get("structure_score") or 0)
    micro_support = ms.get("micro_support")
    micro_resistance = ms.get("micro_resistance")
    near_pct = MICRO_SR_NEAR_PCT
    bias_ok = pattern_ok = swing_intact = rejects = near_sr = False
    micro_level = None

    if direction == "LONG":
        bias_ok = (
            struct_score > 0
            or ms.get("hh_hl_sequence_active")
            or ms.get("structure_bias") in ("BULLISH_STRUCTURE", "LEAN_BULL")
        )
        pattern_ok = bool(ms.get("higher_low"))
        micro_level = micro_support
        if micro_support and price > 0:
            swing_intact = price >= float(micro_support) * (1 - near_pct)
        rejects = _micro_sr_rejection(direction, price, micro_support, None, near_pct)
        ref = float(limit_price) if limit_price is not None else price
        if micro_level and ref > 0 and price > 0:
            near_sr = abs(ref - float(micro_level)) / price <= near_pct * 3
    elif direction == "SHORT":
        bias_ok = (
            struct_score < 0
            or ms.get("lh_ll_sequence_active")
            or ms.get("structure_bias") in ("BEARISH_STRUCTURE", "LEAN_BEAR")
        )
        pattern_ok = bool(ms.get("lower_high"))
        micro_level = micro_resistance
        if micro_resistance and price > 0:
            swing_intact = price <= float(micro_resistance) * (1 + near_pct)
        rejects = _micro_sr_rejection(direction, price, None, micro_resistance, near_pct)
        ref = float(limit_price) if limit_price is not None else price
        if micro_level and ref > 0 and price > 0:
            near_sr = abs(ref - float(micro_level)) / price <= near_pct * 3

    confirmed = bool(bias_ok and pattern_ok and swing_intact and rejects and near_sr and micro_level)
    return {
        "confirmed": confirmed,
        "bias_ok": bias_ok,
        "pattern_ok": pattern_ok,
        "swing_intact": swing_intact,
        "rejects_micro_sr": rejects,
        "near_micro_sr": near_sr,
        "micro_sr_level": micro_level,
        "micro_support": micro_support,
        "micro_resistance": micro_resistance,
        "pivot_count": ms.get("pivot_count"),
        "structure_score": struct_score,
        "higher_low": ms.get("higher_low"),
        "lower_high": ms.get("lower_high"),
    }


def compute_ema_hybrid_entry(signal: dict) -> dict:
    """v84.1: EMA9/EMA21 hybrid limit reference only — not the primary entry trigger."""
    direction = str(signal.get("final_direction") or "").upper()
    price = float(signal.get("signal_price") or state.get("price") or 0)
    ema9, ema21 = _entry_ema9_ema21()
    hybrid_base = compute_ema_hybrid_base(direction, price, ema9, ema21)
    limit_price = None
    if hybrid_base is not None:
        limit_price = apply_ema_hybrid_entry_offset(direction, hybrid_base)
        if direction == "SHORT" and limit_price <= price:
            hybrid_base = None
            limit_price = None
        elif direction == "LONG" and limit_price >= price:
            hybrid_base = None
            limit_price = None
    dist_pct = (
        round(abs(price - limit_price) / price * 100, 4)
        if limit_price is not None and price > 0
        else None
    )
    signal["ema_hybrid_base"] = hybrid_base
    signal["ema_hybrid_limit"] = limit_price
    signal["ema_hybrid_offset_usd"] = EMA_HYBRID_ENTRY_OFFSET_USD
    signal["ema9_at_entry"] = ema9
    signal["ema21_at_entry"] = ema21
    signal["dist_to_ema_hybrid_pct"] = dist_pct
    return {
        "ema_hybrid_base": hybrid_base,
        "ema_hybrid_limit": limit_price,
        "dist_to_ema_hybrid_pct": dist_pct,
    }


def load_historically_profitable_patterns() -> dict:
    """Closed-loop reject research — injected into AI context."""
    path = PROFITABLE_REJECT_FEATURES_FILE
    if not os.path.isfile(path):
        return {}
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        return data.get("historically_profitable_patterns") or data
    except Exception:
        return {}


def compute_research_quality_score(ctx: dict, features: dict = None) -> float:
    """Research-mode AI gate — micro structure + quality, not edge threshold."""
    features = features or {}
    price = float(ctx.get("price") or state.get("price") or 0)
    ms = build_micro_sr_levels()
    hint = str(ctx.get("regime") or "LONG")
    micro_eval = evaluate_micro_structure_confirm("LONG" if "BULL" in hint else "SHORT", price, None, ms)
    upgrade = ctx.get("ai_input_upgrade") or {}
    qcomp = upgrade.get("quality_score_components") or {}
    micro_sr = float(qcomp.get("micro_sr_component") or (100 if micro_eval.get("confirmed") else 40))
    mc = ctx.get("market_context") or state.get("market_context") or {}
    struct = float((mc.get("market_structure") or {}).get("structure_score") or 0)
    structure_comp = max(0.0, min(100.0, (struct + 10.0) / 20.0 * 100.0))
    sweep_bonus = 25.0 if upgrade.get("liquidity_sweep_high") or upgrade.get("liquidity_sweep_low") else 0.0
    return round(0.50 * micro_sr + 0.35 * structure_comp + 0.15 * sweep_bonus, 1)


def resolve_ai_planner_limit(
    direction: str, price: float, trade_planner: dict, ms: dict, micro_eval: dict
) -> tuple:
    """AI entry zone primary; micro S/R validates/clips limit inside zone."""
    plan = trade_planner or {}
    try:
        zlo = float(plan.get("entry_zone_low"))
        zhi = float(plan.get("entry_zone_high"))
    except (TypeError, ValueError):
        return None, None
    if zhi <= zlo or price <= 0 or direction not in ("LONG", "SHORT"):
        return None, None
    limit = zlo + (zhi - zlo) * 0.5
    micro_support = ms.get("micro_support")
    micro_resistance = ms.get("micro_resistance")
    if direction == "LONG":
        if micro_support:
            ms_lim = float(micro_support) + MICRO_SR_ENTRY_BUFFER_USD
            if zlo <= ms_lim <= zhi:
                limit = ms_lim
        limit = min(limit, price)
        if limit >= price:
            limit = price * (1 - float(state.get("pullback_threshold", 0.001)))
    else:
        if micro_resistance:
            ms_lim = float(micro_resistance) - MICRO_SR_ENTRY_BUFFER_USD
            if zlo <= ms_lim <= zhi:
                limit = ms_lim
        limit = max(limit, price)
        if limit <= price:
            limit = price * (1 + float(state.get("pullback_threshold", 0.001)))
    return float(limit), "AI_ZONE_MICRO_VALIDATED"


def continuous_ai_direct_entry_enabled() -> bool:
    """Place the AI-suggested limit immediately (no AWAITING_MICRO)."""
    # The persisted legacy mode flag gates the direct-entry preference; it
    # must never resurrect orders after the saved choice is OFF.
    if not legacy_adoption_lane_enabled():
        return False
    with state_lock:
        if "continuous_ai_direct_entry_enabled" in state:
            return bool(state.get("continuous_ai_direct_entry_enabled"))
    return os.getenv("CONTINUOUS_AI_DIRECT_ENTRY", "1").lower() not in ("0", "false", "no")


def fills_first_continuous_enabled(signal: dict = None) -> bool:
    """Immediate limit + no min-age/micro/5m queues on combo direct lanes."""
    if not is_research_data_collection():
        return False
    lane = str((signal or {}).get("research_lane", RESEARCH_LANE_AI_SCAN)).upper()
    if is_immediate_entry_lane(lane):
        return True
    return lane in AI_DIRECT_RESEARCH_LANES


def resolve_local_structural_limit(
    direction: str,
    price: float,
    market_structure: dict = None,
    support_resistance: dict = None,
) -> tuple:
    """Return the deterministic 0.1% maker limit plus advisory micro S/R levels.

    Danish decision 3 (2026-08-01): the Continuous-lane executable anchor is
    always a deterministic offset from the signal/reference price::

        LONG  = price * (1 - DETERMINISTIC_ENTRY_OFFSET_PCT)   # default 0.999
        SHORT = price * (1 + DETERMINISTIC_ENTRY_OFFSET_PCT)   # default 1.001

    Micro support/resistance, EMA hybrid, AI-planner zone and 5m-trigger prices
    may still be displayed on the dashboard as research/advisory fields, but
    they MUST NOT silently replace this anchor for the production lane. The
    earlier behaviour anchored the limit to the nearest valid local S/R level
    (``micro_sr_structural_limit_v1``); that was reverted because the AI supplies
    direction only, so the anchor price must be deterministic and reproducible.

    Returns ``(limit, source, advisory)`` where ``advisory`` carries the
    observed micro S/R levels (``micro_support``/``micro_resistance`` plus the
    legacy ``local_support_limit``/``local_resistance_limit`` and their
    availability) so dashboards/tests can still surface them as research fields.
    """
    direction = str(direction or "").upper()
    price = float(price or 0)
    if price <= 0 or direction not in ("LONG", "SHORT"):
        return None, "INVALID_DIRECTION_OR_PRICE", {}

    ms = market_structure if isinstance(market_structure, dict) else build_micro_sr_levels()
    if support_resistance is None:
        with state_lock:
            support_resistance = copy.deepcopy(state.get("support_resistance") or {})
    sr = support_resistance if isinstance(support_resistance, dict) else {}

    offset = DETERMINISTIC_ENTRY_OFFSET_PCT
    if direction == "LONG":
        limit = round(price * (1 - offset), 2)
        source = "DETERMINISTIC_LONG_OFFSET"
    else:
        limit = round(price * (1 + offset), 2)
        source = "DETERMINISTIC_SHORT_OFFSET"

    # --- Advisory only: nearest valid local S/R (research display field) -------
    # Computed for transparency but never returned as the executable limit.
    advisory = dict(ms) if isinstance(ms, dict) else {}
    advisory.setdefault("micro_support", ms.get("micro_support"))
    advisory.setdefault("micro_resistance", ms.get("micro_resistance"))
    advisory.setdefault("prior_support", ms.get("prior_support"))
    advisory.setdefault("prior_resistance", ms.get("prior_resistance"))
    advisory["local_support_available"] = False
    advisory["local_resistance_available"] = False
    advisory["local_support_limit"] = None
    advisory["local_resistance_limit"] = None
    advisory["local_support_out_of_range"] = False
    advisory["local_resistance_out_of_range"] = False

    if direction == "LONG":
        raw_levels = (
            ms.get("micro_support"),
            ms.get("last_swing_low"),
            ms.get("prior_support"),
            sr.get("swing_low"),
            sr.get("s1"),
            sr.get("s2"),
        )
        candidates = []
        for raw in raw_levels:
            try:
                level = float(raw) + MICRO_SR_ENTRY_BUFFER_USD
            except (TypeError, ValueError):
                continue
            if 0 < level < price:
                candidates.append(level)
        if candidates:
            advisory["local_support_limit"] = max(candidates)
            advisory["local_support_available"] = True
            support_distance = (price - advisory["local_support_limit"]) / price
            advisory["local_support_out_of_range"] = support_distance > AI_DIRECT_MAX_DIST_PCT
        else:
            advisory["local_support_available"] = False
    else:
        raw_levels = (
            ms.get("micro_resistance"),
            ms.get("last_swing_high"),
            ms.get("prior_resistance"),
            sr.get("swing_high"),
            sr.get("r1"),
            sr.get("r2"),
        )
        candidates = []
        for raw in raw_levels:
            try:
                level = float(raw) - MICRO_SR_ENTRY_BUFFER_USD
            except (TypeError, ValueError):
                continue
            if level > price:
                candidates.append(level)
        if candidates:
            advisory["local_resistance_limit"] = min(candidates)
            advisory["local_resistance_available"] = True
            resistance_distance = (advisory["local_resistance_limit"] - price) / price
            advisory["local_resistance_out_of_range"] = resistance_distance > AI_DIRECT_MAX_DIST_PCT
        else:
            advisory["local_resistance_available"] = False

    return limit, source, advisory


def resolve_ai_direct_limit(
    direction: str,
    price: float,
    trade_planner: dict,
    market_structure: dict = None,
    support_resistance: dict = None,
) -> tuple:
    """Resolve direction-only executable anchor — deterministic 0.1% offset.

    Returns ``(limit, source)`` for backward compatibility with existing
    callers/tests. The deterministic anchor is always available when direction
    + price are valid, so this no longer fails closed on missing micro S/R.
    ``resolve_local_structural_limit`` is the canonical 3-tuple entrypoint.
    """
    _ = trade_planner  # retained only for old call/schema compatibility
    limit, source, _advisory = resolve_local_structural_limit(
        direction,
        price,
        market_structure=market_structure,
        support_resistance=support_resistance,
    )
    return limit, source


def compute_continuous_ai_direct_entry(signal: dict) -> dict:
    """Shared direction lane — deterministic 0.1% anchor, then exact virtual chase.

    Danish decision 3 (2026-08-01): the executable maker limit is the
    deterministic 0.1% offset from the signal/reference price. Micro S/R
    levels remain visible on the dashboard as research/advisory fields but
    never replace this anchor.
    """
    direction = str(signal.get("final_direction") or "").upper()
    price = float(signal.get("signal_price") or state.get("price") or 0)
    trade_planner = signal.get("trade_planner") or (signal.get("ai_output") or {}).get("trade_planner") or {}
    market_structure = build_micro_sr_levels()
    limit_price, entry_reason, advisory = resolve_local_structural_limit(
        direction,
        price,
        market_structure=market_structure,
    )
    signal["entry_limit_policy"] = DETERMINISTIC_ENTRY_POLICY_VERSION
    signal["structural_entry_valid"] = limit_price is not None
    # Advisory / research display fields — never the executable anchor.
    signal["micro_support"] = market_structure.get("micro_support")
    signal["micro_resistance"] = market_structure.get("micro_resistance")
    signal["prior_support"] = market_structure.get("prior_support")
    signal["prior_resistance"] = market_structure.get("prior_resistance")
    signal["pivot_count"] = market_structure.get("pivot_count")
    signal["advisory_local_support_limit"] = advisory.get("local_support_limit")
    signal["advisory_local_resistance_limit"] = advisory.get("local_resistance_limit")
    signal["advisory_local_support_available"] = bool(advisory.get("local_support_available"))
    signal["advisory_local_resistance_available"] = bool(advisory.get("local_resistance_available"))
    # Deterministic anchor fields (the actual executable price).
    signal["deterministic_entry_offset_pct"] = DETERMINISTIC_ENTRY_OFFSET_PCT
    if price > 0:
        signal["deterministic_initial_limit"] = round(
            price * (1 - DETERMINISTIC_ENTRY_OFFSET_PCT) if direction == "LONG"
            else price * (1 + DETERMINISTIC_ENTRY_OFFSET_PCT) if direction == "SHORT"
            else price, 2
        )
    else:
        signal["deterministic_initial_limit"] = None
    if limit_price is None:
        signal["entry_mode"] = ENTRY_MODE_AI_DIRECT
        signal["entry_reason"] = entry_reason
        signal["entry_path"] = "DETERMINISTIC_LIMIT_BLOCKED"
        signal["ai_direct_limit"] = None
        signal["micro_sr_limit"] = None
        signal["await_micro_confirm"] = False
        signal["micro_structure_confirmed"] = False
        signal["order_placed"] = False
        logger.warning(
            f"[DETERMINISTIC ENTRY] blocked trade_id={signal.get('trade_id', '?')} "
            f"dir={direction} market={fmt(price)} reason={entry_reason} "
            f"support={fmt(signal.get('micro_support'))} "
            f"resistance={fmt(signal.get('micro_resistance'))} "
            f"[PIPELINE ENFORCEMENT]"
        )
        return {
            "entry_mode": ENTRY_MODE_AI_DIRECT,
            "entry_reason": entry_reason,
            "entry_path": "DETERMINISTIC_LIMIT_BLOCKED",
            "ai_direct_limit": None,
            "await_micro_confirm": False,
        }
    signal["entry_mode"] = ENTRY_MODE_AI_DIRECT
    signal["entry_reason"] = entry_reason
    signal["entry_path"] = "AI_DIRECT"
    signal["ai_direct_limit"] = limit_price
    # NOTE: ai_planner_limit / micro_sr_limit are kept for schema/back-compat
    # with older snapshots and dashboards. They equal the deterministic anchor
    # so historical readers keep working, but the canonical anchor is
    # ``ai_direct_limit`` / ``deterministic_initial_limit`` under the
    # ``deterministic_0.1pct_offset_v1`` policy.
    signal["ai_planner_limit"] = limit_price
    signal["micro_sr_limit"] = limit_price
    signal["ai_entry_zone_low"] = trade_planner.get("entry_zone_low")
    signal["ai_entry_zone_high"] = trade_planner.get("entry_zone_high")
    signal["await_micro_confirm"] = False
    signal["micro_structure_confirmed"] = True
    signal["order_placed"] = False
    trade_id = signal.get("trade_id", "?")
    logger.info(
        f"[DETERMINISTIC ENTRY] trade_id={trade_id} dir={direction} limit={fmt(limit_price)} "
        f"offset={DETERMINISTIC_ENTRY_OFFSET_PCT * 100:.2f}% "
        f"support={fmt(signal.get('micro_support'))} "
        f"resistance={fmt(signal.get('micro_resistance'))} market={fmt(price)} "
        f"policy={DETERMINISTIC_ENTRY_POLICY_VERSION} path=AI_DIRECT [PIPELINE ENFORCEMENT]"
    )
    return {
        "entry_mode": ENTRY_MODE_AI_DIRECT,
        "entry_reason": entry_reason,
        "entry_path": "AI_DIRECT",
        "ai_direct_limit": limit_price,
        "await_micro_confirm": False,
    }


def compute_family_tile_entry(signal: dict, features: dict = None) -> dict:
    """Thin lifecycle adapter over the registry-selected family policy.

    ``signal["features"]`` is the frozen global snapshot from
    atomic_freeze_signal and never holds lane enrichment, so the spawn
    features carrying the signal-time adaptive decision must be passed
    explicitly; without them every adaptive order fails closed as
    DECISION_MISSING.
    """
    direction = str(signal.get("final_direction") or "").upper()
    price = float(signal.get("signal_price") or state.get("price") or 0)
    lane = str(signal.get("research_lane") or "").upper()
    policy = _patient_chase_policy(lane)
    lane_features = features or {}
    features = signal.get("features") or lane_features
    if getattr(policy, "ADAPTIVE_ENTRY", False):
        signal.update(policy.adaptive_entry_fields(
            direction, price, lane_features.get("adaptive_entry_decision"),
        ))
        if signal.get("structural_entry_valid"):
            price = float(signal["planned_limit_price"])
    else:
        signal.update(policy.entry_fields(direction, price))
    # This remains the canonical local-paper lifecycle even when a separate
    # platform relay is capable of copying a newly signed intent.
    signal["paper_only"] = True
    signal["relay_eligible"] = lane in PLATFORM_RELAY_ELIGIBLE_LANES
    if lane in COMBO_EXECUTION_LANES:
        atr_abs = _buf_float(signal.get("atr14_3m") or features.get("atr14_3m"), 0.0)
        if atr_abs <= 0:
            atr_pct = _buf_float(signal.get("atr14_pct_3m") or features.get("atr14_pct_3m"), 0.0)
            atr_abs = price * atr_pct / 100.0
        equity = _buf_float(state.get("equity") or state.get("account_balance"), 0.0)
        leverage = max(1.0, _buf_float(state.get("leverage"), DEFAULT_RESEARCH_LEVERAGE))
        sizing = policy.account_risk_quantity(
            equity_usd=equity, entry_price=price, atr_abs=atr_abs, leverage=leverage
        )
        signal["requested_qty"] = float(sizing["quantity"])
        signal["margin_usdt"] = float(sizing["quantity"]) * price / leverage if price > 0 else 0.0
        signal["requested_margin_usd"] = signal["margin_usdt"]
        signal["requested_notional_usd"] = float(sizing["quantity"]) * price
        signal["account_risk_budget_usd"] = float(sizing["risk_budget_usd"])
        signal["sizing_atr_abs"] = atr_abs
        signal["sizing_capped_by"] = sizing["capped_by"]
        signal["sizing_fail_closed"] = float(sizing["quantity"]) <= 0
    signal["entry_mode"] = ENTRY_MODE_AI_DIRECT
    return {
        "entry_mode": ENTRY_MODE_AI_DIRECT,
        "entry_reason": signal["entry_reason"],
        "entry_path": signal["entry_path"],
        "ai_direct_limit": signal.get("ai_direct_limit"),
        "await_micro_confirm": False,
    }


def compute_micro_sr_entry(signal: dict) -> dict:
    """v101: AI planner zone primary; micro S/R validates; EMA secondary confirmation only."""
    direction = str(signal.get("final_direction") or "").upper()
    price = float(signal.get("signal_price") or state.get("price") or 0)
    ema9, ema21 = _entry_ema9_ema21()
    ema_ctx = compute_ema_hybrid_entry(signal)
    hybrid_base = ema_ctx.get("ema_hybrid_base")
    ema_zone_ok, _ = _ema_zone_reached(direction, price, ema9, ema21)

    ms = build_micro_sr_levels()
    struct_score = float(ms.get("structure_score") or 0)
    micro_support = ms.get("micro_support")
    micro_resistance = ms.get("micro_resistance")
    sole = _sole_ai_research_mode()
    overext = evaluate_overextension_gate(direction, struct_score, sole=sole)

    limit_price = None
    micro_level = None
    entry_reason = "PULLBACK_FALLBACK"
    entry_mode = ENTRY_MODE_PULLBACK
    await_micro_confirm = False

    if direction == "LONG" and micro_support:
        micro_level = micro_support
        limit_price = float(micro_support) + MICRO_SR_ENTRY_BUFFER_USD
        if limit_price >= price:
            limit_price = None
    elif direction == "SHORT" and micro_resistance:
        micro_level = micro_resistance
        limit_price = float(micro_resistance) - MICRO_SR_ENTRY_BUFFER_USD
        if limit_price <= price:
            limit_price = None

    micro_eval = evaluate_micro_structure_confirm(direction, price, limit_price, ms)
    dist_to_micro = (
        round(abs(price - float(micro_level)) / price * 100, 4)
        if micro_level and price > 0
        else None
    )

    trade_planner = signal.get("trade_planner") or (signal.get("ai_output") or {}).get("trade_planner")
    ai_limit, ai_reason = resolve_ai_planner_limit(direction, price, trade_planner, ms, micro_eval)
    if ai_limit is not None:
        entry_mode = ENTRY_MODE_AI_PLANNER
        limit_price = ai_limit
        entry_reason = ai_reason or "AI_PLANNER_ZONE"
        signal["ai_entry_zone_low"] = trade_planner.get("entry_zone_low")
        signal["ai_entry_zone_high"] = trade_planner.get("entry_zone_high")
        signal["ai_planner_limit"] = ai_limit
        await_micro_confirm = not micro_eval.get("confirmed")
        signal["ema_secondary_confirm"] = bool(ema_zone_ok)
    elif micro_eval.get("confirmed") and micro_level and limit_price and not overext.get("require_micro_confirm"):
        entry_mode = ENTRY_MODE_MICRO_SR
        entry_reason = "MICRO_SR_CONFIRMED"
    elif micro_level and limit_price:
        entry_mode = ENTRY_MODE_MICRO_SR if micro_eval.get("confirmed") else ENTRY_MODE_PULLBACK
        entry_reason = "MICRO_SR_AWAIT" if not micro_eval.get("confirmed") else "MICRO_SR_CONFIRMED"
        await_micro_confirm = not micro_eval.get("confirmed")
        signal["ema_secondary_confirm"] = bool(ema_zone_ok)
        if overext.get("require_micro_confirm"):
            await_micro_confirm = True
            entry_reason = "OVEREXT_AWAIT_MICRO"
            if overext.get("would_block"):
                signal["overextension_would_block"] = overext.get("reason")
            else:
                signal["overextension_research"] = overext.get("reason")
    elif hybrid_base is not None and ema_zone_ok:
        entry_mode = ENTRY_MODE_EMA_HYBRID
        entry_reason = "EMA_SECONDARY_AWAIT_MICRO"
        await_micro_confirm = True

    signal["entry_mode"] = entry_mode
    signal["entry_reason"] = entry_reason
    signal["entry_path"] = signal.get("entry_path") or "MICRO_SR"
    signal["micro_support"] = micro_support
    signal["micro_resistance"] = micro_resistance
    signal["micro_sr_limit"] = limit_price
    signal["micro_sr_level"] = micro_level
    signal["pivot_count"] = ms.get("pivot_count")
    signal["dist_to_micro_sr_pct"] = dist_to_micro
    signal["ema_zone_reached"] = ema_zone_ok
    signal["micro_structure_confirmed"] = bool(micro_eval.get("confirmed"))
    signal["micro_structure_eval"] = micro_eval
    signal["await_micro_confirm"] = await_micro_confirm
    signal["higher_low_detected"] = bool(ms.get("higher_low"))
    signal["lower_high_detected"] = bool(ms.get("lower_high"))
    trade_id = signal.get("trade_id")
    if entry_mode == ENTRY_MODE_AI_PLANNER:
        logger.info(
            f"[AI PLANNER] trade_id={trade_id} dir={direction} reason={entry_reason} "
            f"zone={fmt(signal.get('ai_entry_zone_low'))}-{fmt(signal.get('ai_entry_zone_high'))} "
            f"limit={fmt(limit_price)} ema_secondary={signal.get('ema_secondary_confirm')} "
            f"micro_confirmed={micro_eval.get('confirmed')} [PIPELINE ENFORCEMENT]"
        )
    elif entry_mode == ENTRY_MODE_MICRO_SR:
        logger.info(
            f"[MICRO SR] trade_id={trade_id} dir={direction} reason={entry_reason} "
            f"limit={fmt(limit_price)} support={fmt(micro_support)} resist={fmt(micro_resistance)} "
            f"pivots={ms.get('pivot_count')} dist_micro={dist_to_micro}% struct={struct_score:.1f} "
            f"[PIPELINE ENFORCEMENT]"
        )
    elif entry_mode == ENTRY_MODE_EMA_HYBRID:
        logger.info(
            f"[MICRO SR] trade_id={trade_id} dir={direction} armed reason={entry_reason} "
            f"await_micro={await_micro_confirm} ema_zone={ema_zone_ok} "
            f"micro_limit={fmt(limit_price)} confirmed={micro_eval.get('confirmed')} "
            f"[PIPELINE ENFORCEMENT]"
        )
    else:
        logger.info(
            f"[MICRO SR] trade_id={trade_id} dir={direction} fallback={ENTRY_MODE_PULLBACK} "
            f"ema_zone={ema_zone_ok} pivots={ms.get('pivot_count')} [PIPELINE ENFORCEMENT]"
        )
    return {
        "entry_mode": entry_mode,
        "entry_reason": entry_reason,
        "micro_sr_limit": limit_price,
        "micro_support": micro_support,
        "micro_resistance": micro_resistance,
        "dist_to_micro_sr_pct": dist_to_micro,
        "micro_structure_confirmed": bool(micro_eval.get("confirmed")),
        "await_micro_confirm": await_micro_confirm,
    }


compute_micro_structure_entry = compute_micro_sr_entry
compute_shadow_micro_sr_entry = compute_micro_sr_entry

def resolve_entry_limit_price(signal: dict) -> tuple:
    """Return (limit_price, entry_mode) — micro S/R level, EMA armed, or pullback %."""
    direction = str(signal.get("final_direction") or "").upper()
    signal_price = float(signal.get("signal_price") or state.get("price") or 0)
    entry_mode = signal.get("entry_mode")
    if entry_mode == ENTRY_MODE_AI_DIRECT:
        if signal.get("ai_direct_limit") is not None:
            return float(signal["ai_direct_limit"]), ENTRY_MODE_AI_DIRECT
        # A direction-only shared lane is never allowed to fall through to the
        # legacy percentage pullback. Zero is fail-closed and is rejected by the
        # order path if a caller somehow bypasses the dashboard gate.
        return 0.0, ENTRY_MODE_AI_DIRECT
    pullback_pct = float(signal.get("pullback_pct", state.get("pullback_threshold", 0.001)))
    if direction == "LONG":
        pullback_limit = signal_price * (1 - pullback_pct)
    elif direction == "SHORT":
        pullback_limit = signal_price * (1 + pullback_pct)
    else:
        pullback_limit = signal_price
    signal["planned_pullback_limit"] = pullback_limit
    if entry_mode == ENTRY_MODE_5M_TRIGGER and signal.get("micro_sr_limit") is not None:
        return float(signal["micro_sr_limit"]), ENTRY_MODE_5M_TRIGGER
    if entry_mode == ENTRY_MODE_AI_PLANNER and signal.get("ai_planner_limit") is not None:
        return float(signal["ai_planner_limit"]), ENTRY_MODE_AI_PLANNER
    micro_limit = signal.get("micro_sr_limit")
    if entry_mode == ENTRY_MODE_MICRO_SR and micro_limit is not None:
        return float(micro_limit), ENTRY_MODE_MICRO_SR
    if entry_mode == ENTRY_MODE_EMA_HYBRID and micro_limit is not None:
        return float(micro_limit), ENTRY_MODE_EMA_HYBRID
    ema_limit = signal.get("ema_hybrid_limit")
    if entry_mode == ENTRY_MODE_EMA_HYBRID and ema_limit is not None:
        return float(ema_limit), ENTRY_MODE_EMA_HYBRID
    return float(pullback_limit), ENTRY_MODE_PULLBACK

def tf_trend_from_candles(candles):
    if not candles or len(candles) < 30:
        return "UNKNOWN"
    closes = [c[4] for c in candles]
    ema9 = ema(closes, EMA_FAST)
    ema21 = ema(closes, EMA_SLOW)
    close = closes[-1]
    if ema9 is None or ema21 is None:
        return "UNKNOWN"
    if close > ema9 > ema21:
        return "BULLISH"
    if close < ema9 < ema21:
        return "BEARISH"
    if close > ema9 and ema9 > ema21:
        return "LEAN_BULL"
    if close < ema9 and ema9 < ema21:
        return "LEAN_BEAR"
    return "RANGING"

def fetch_mtf_candles(timeframe: str, limit: int = 120):
    global _mtf_cache
    now = time.time()
    bucket = _mtf_cache.get(timeframe, {"ts": 0.0, "candles": []})
    if timeframe == "5m":
        refresh_sec = MTF_5M_REFRESH_SEC
    elif timeframe == "1m":
        refresh_sec = MTF_1M_REFRESH_SEC
    else:
        refresh_sec = MTF_REFRESH_SEC
    if bucket["candles"] and now - bucket["ts"] < refresh_sec:
        return bucket["candles"]
    try:
        candles = fetch_bitfinex_ohlcv(timeframe, limit=limit)
        if candles:
            _mtf_cache[timeframe] = {"ts": now, "candles": candles}
            return candles
    except Exception as e:
        logger.warning(f"[MTF] fetch {timeframe} failed: {e} [PIPELINE ENFORCEMENT]")
    return bucket.get("candles") or []

def compute_multi_tf_trend(candles_15m):
    m15 = tf_trend_from_candles(candles_15m)
    m1h = tf_trend_from_candles(fetch_mtf_candles("1h"))
    m4h = tf_trend_from_candles(fetch_mtf_candles("4h"))
    trends = {"15m": m15, "1h": m1h, "4h": m4h}
    bull = sum(1 for t in trends.values() if t in ("BULLISH", "LEAN_BULL"))
    bear = sum(1 for t in trends.values() if t in ("BEARISH", "LEAN_BEAR"))
    if bull >= 2 and bear == 0:
        agreement = "BULL_ALIGNED"
    elif bear >= 2 and bull == 0:
        agreement = "BEAR_ALIGNED"
    elif bull >= 1 and bear >= 1:
        agreement = "CONFLICTED"
    else:
        agreement = "MIXED"
    note = ""
    if m15 in ("BEARISH", "LEAN_BEAR") and m1h in ("BULLISH", "LEAN_BULL") and m4h in ("BULLISH", "LEAN_BULL"):
        note = "15m pullback inside higher-TF bull trend"
    elif m15 in ("BULLISH", "LEAN_BULL") and m1h in ("BEARISH", "LEAN_BEAR") and m4h in ("BEARISH", "LEAN_BEAR"):
        note = "15m bounce inside higher-TF bear trend"
    return {"trends": trends, "bull_tf_count": bull, "bear_tf_count": bear, "agreement": agreement, "interpretation_note": note}

def compute_vwap_distance_pct(candles, price):
    if not candles or price is None or price <= 0:
        return 0.0
    slice_c = candles[-48:]
    vol_sum = 0.0
    pv_sum = 0.0
    for c in slice_c:
        v = float(c[5]) if len(c) > 5 else 0.0
        if v <= 0:
            continue
        tp = (c[2] + c[3] + c[4]) / 3.0
        pv_sum += tp * v
        vol_sum += v
    if vol_sum <= 0:
        return 0.0
    vwap = pv_sum / vol_sum
    return round((price - vwap) / vwap * 100, 4)

def compute_adx(candles, period=14):
    if len(candles) < period + 2:
        return None
    trs, plus_dm, minus_dm = [], [], []
    for i in range(1, len(candles)):
        h, l, pc = candles[i][2], candles[i][3], candles[i - 1][4]
        ph, pl = candles[i - 1][2], candles[i - 1][3]
        up_move = h - ph
        down_move = pl - l
        plus_dm.append(up_move if up_move > down_move and up_move > 0 else 0.0)
        minus_dm.append(down_move if down_move > up_move and down_move > 0 else 0.0)
        trs.append(max(h - l, abs(h - pc), abs(l - pc)))
    if len(trs) < period:
        return None

    def wilder_smooth(vals):
        s = sum(vals[:period])
        out = [s]
        for v in vals[period:]:
            s = s - (s / period) + v
            out.append(s)
        return out

    atr_s = wilder_smooth(trs)
    pdm_s = wilder_smooth(plus_dm)
    mdm_s = wilder_smooth(minus_dm)
    dx_vals = []
    for atr, pdm, mdm in zip(atr_s, pdm_s, mdm_s):
        if atr <= 0:
            dx_vals.append(0.0)
            continue
        pdi = 100 * pdm / atr
        mdi = 100 * mdm / atr
        denom = pdi + mdi
        dx_vals.append(abs(pdi - mdi) / denom * 100 if denom > 0 else 0.0)
    if len(dx_vals) < period:
        return None
    adx_seed = sum(dx_vals[:period]) / period
    adx = adx_seed
    for dx in dx_vals[period:]:
        adx = (adx * (period - 1) + dx) / period
    return round(adx, 2)

def compute_ema_alignment_facts(price, ema_status, candles):
    ema9 = nz(ema_status.get("ema9"))
    ema21 = nz(ema_status.get("ema21"))
    ema200 = nz(ema_status.get("ema200"))
    closes = [c[4] for c in candles] if candles else []
    ema21_prev = ema(closes[:-3], EMA_SLOW) if len(closes) > EMA_SLOW + 3 else None
    ema9_prev = ema(closes[:-3], EMA_FAST) if len(closes) > EMA_FAST + 3 else None
    slope21 = _pct_diff(ema21, ema21_prev) if ema21_prev else nz(ema_status.get("ema21_slope_pct"), 0)
    slope9 = _pct_diff(ema9, ema9_prev) if ema9_prev else nz(ema_status.get("ema9_slope_pct"), 0)
    return {
        "price_vs_ema9_pct": _pct_diff(price, ema9),
        "price_vs_ema21_pct": _pct_diff(price, ema21),
        "price_vs_ema200_pct": _pct_diff(price, ema200),
        "ema9_above_ema21": bool(ema9 and ema21 and ema9 > ema21),
        "ema21_above_ema200": bool(ema21 and ema200 and ema21 > ema200),
        "stack_bull": bool(ema9 and ema21 and ema200 and ema9 > ema21 > ema200),
        "stack_bear": bool(ema9 and ema21 and ema200 and ema9 < ema21 < ema200),
        "ema9_slope_pct": round(slope9, 4),
        "ema21_slope_pct": round(slope21, 4),
        "ema_spread_pct": round(nz(ema_status.get("ema_spread", 0)) * 100, 4),
    }

def compute_trend_strength(candles, price, structure_score, mtf):
    adx = compute_adx(candles)
    vwap_dist = compute_vwap_distance_pct(candles, price)
    mtf_bonus = 0
    if mtf.get("agreement") == "BULL_ALIGNED":
        mtf_bonus = 2
    elif mtf.get("agreement") == "BEAR_ALIGNED":
        mtf_bonus = -2
    trend_score = int(max(-10, min(10, structure_score + mtf_bonus + (1 if (adx or 0) >= 25 else 0))))
    trending = (adx or 0) >= 25
    return {
        "adx": adx,
        "trend_score": trend_score,
        "vwap_distance_pct": vwap_dist,
        "trending_market_adx_25_plus": trending,
        "mean_reversion_risk": not trending and abs(vwap_dist) > 0.5,
    }

def update_market_context(force: bool = False):
    global _last_market_context_ts
    now = time.time()
    if not force and now - _last_market_context_ts < 15:
        return
    with state_lock:
        candles = copy.deepcopy(latest_candles)
        price = state.get("price")
        ema_status = copy.deepcopy(state.get("ema_status", {}))
        regime = state.get("regime", "UNKNOWN")
        sr = copy.deepcopy(state.get("support_resistance", {}))
    if len(candles) < 30 or not price or price <= 0:
        return
    structure = compute_market_structure(candles)
    mtf = compute_multi_tf_trend(candles)
    ema_alignment = compute_ema_alignment_facts(price, ema_status, candles)
    trend_strength = compute_trend_strength(candles, price, structure.get("structure_score", 0), mtf)
    ctx = {
        "updated_ts": now,
        "market_structure": structure,
        "multi_tf": mtf,
        "ema_alignment": ema_alignment,
        "trend_strength": trend_strength,
        "regime_label": regime,
        "sr_context": {
            "sr_state": sr.get("sr_state", "UNKNOWN"),
            "dist_to_resistance_pct": round(nz(sr.get("dist_to_resistance", 0)) * 100, 3),
            "dist_to_support_pct": round(nz(sr.get("dist_to_support", 0)) * 100, 3),
            "role": "LOCATION_CONTEXT_ONLY",
        },
    }
    with state_lock:
        state["market_context"] = ctx
    _last_market_context_ts = now
    health = compute_trend_health()
    logger.info(
        f"[MARKET_CTX] structure_score={structure.get('structure_score')} bias={structure.get('structure_bias')} "
        f"mtf={mtf.get('trends')} adx={trend_strength.get('adx')} trend_score={trend_strength.get('trend_score')} "
        f"trend_health={health.get('trend_state')} [PIPELINE ENFORCEMENT]"
    )

def get_market_context_for_ai():
    update_market_context()
    with state_lock:
        return copy.deepcopy(state.get("market_context", {}))

