# ---------------------------------------------------------------------------
# Section 1 of Tile 2 static integrity repair.
#
# `_runtime_git_rev` exposes the running commit so /health and /api/state can
# unambiguously report which exact source revision produced this process. The
# bot process is long-lived and is sometimes restarted by a different checkout
# than the working tree HEAD, so we read the resolved revision lazily and
# cache it. Failure to read git (e.g. bare deployments) degrades to "unknown"
# rather than crashing the bot.
# ---------------------------------------------------------------------------
_RUNTIME_GIT_REV_CACHE = {"value": None}


def _read_git_revision_without_cli(start_dir: str) -> str:
    """Read HEAD directly when the bot service account cannot execute git.

    The home-stack launcher can start Python with a narrower PATH than the
    interactive shell.  In that case ``git rev-parse`` fails even though the
    checkout and its .git metadata are present.  Walking upward and reading
    HEAD keeps the runtime identity available without making git a runtime
    dependency.
    """
    current = os.path.abspath(start_dir)
    while True:
        git_dir = os.path.join(current, ".git")
        if os.path.isdir(git_dir):
            try:
                with open(os.path.join(git_dir, "HEAD"), encoding="utf-8") as handle:
                    head = handle.read().strip()
                if head.startswith("ref:"):
                    ref_name = head.split(":", 1)[1].strip().replace("/", os.sep)
                    ref_path = os.path.join(git_dir, ref_name)
                    if os.path.isfile(ref_path):
                        with open(ref_path, encoding="utf-8") as handle:
                            return handle.read().strip()
                    packed_path = os.path.join(git_dir, "packed-refs")
                    if os.path.isfile(packed_path):
                        with open(packed_path, encoding="utf-8") as packed:
                            wanted = head.split(":", 1)[1].strip()
                            for line in packed:
                                line = line.strip()
                                if not line or line.startswith(("#", "^")):
                                    continue
                                sha, _, name = line.partition(" ")
                                if name == wanted:
                                    return sha.strip()
                    return ""
                return head
            except Exception:
                return ""
        parent = os.path.dirname(current)
        if parent == current:
            return ""
        current = parent


def _runtime_git_rev() -> str:
    """Return the short git SHA this process was started from, or 'unknown'.

    Cached after first successful read. Best-effort: uses deployment metadata,
    the git CLI, then direct .git metadata.  An unsuccessful probe is not
    cached so a transient startup PATH/filesystem race can recover. Never
    raises.
    """
    if _RUNTIME_GIT_REV_CACHE["value"]:
        return _RUNTIME_GIT_REV_CACHE["value"]
    rev = ""
    try:
        for env_name in (
            "SOURCE_GIT_REV",
            "GIT_COMMIT",
            "GITHUB_SHA",
            "RAILWAY_GIT_COMMIT_SHA",
        ):
            candidate = str(os.getenv(env_name) or "").strip()
            if len(candidate) >= 7 and all(ch in "0123456789abcdefABCDEF" for ch in candidate):
                rev = candidate
                break
    except Exception:
        rev = ""
    try:
        import subprocess
        here = os.path.dirname(os.path.abspath(__file__))
        if not rev:
            out = subprocess.run(
                ["git", "rev-parse", "HEAD"],
                cwd=here,
                capture_output=True,
                text=True,
                timeout=4,
            )
            if out.returncode == 0:
                rev = (out.stdout or "").strip()
        if not rev:
            rev = _read_git_revision_without_cli(here)
    except Exception:
        try:
            here = os.path.dirname(os.path.abspath(__file__))
            rev = _read_git_revision_without_cli(here)
        except Exception:
            rev = ""
    if rev:
        rev = rev[:12]
        _RUNTIME_GIT_REV_CACHE["value"] = rev
        return rev
    return "unknown"


_RUNTIME_GIT_REV_EXACT_CACHE = {"value": ""}


def _runtime_git_rev_exact() -> str:
    """Return the exact 40-character deployment revision for internal fences."""
    cached = str(_RUNTIME_GIT_REV_EXACT_CACHE.get("value") or "").lower()
    if re.fullmatch(r"[0-9a-f]{40}", cached):
        return cached
    candidates = [
        str(os.getenv(name) or "").strip().lower()
        for name in ("SOURCE_GIT_REV", "GIT_COMMIT", "GITHUB_SHA", "RAILWAY_GIT_COMMIT_SHA")
    ]
    try:
        here = os.path.dirname(os.path.abspath(__file__))
        completed = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=here, capture_output=True,
            text=True, timeout=4,
        )
        if completed.returncode == 0:
            candidates.append(str(completed.stdout or "").strip().lower())
    except Exception:
        pass
    for candidate in candidates:
        if re.fullmatch(r"[0-9a-f]{40}", candidate):
            _RUNTIME_GIT_REV_EXACT_CACHE["value"] = candidate
            return candidate
    return "unknown"






def invert_signal_active() -> bool:
    """Current operator treatment for new signals; frozen default remains OFF."""
    try:
        with state_lock:
            return bool(state.get("invert_signal", False))
    except Exception:
        return False


def apply_invert_direction(raw_direction, invert_on=None):
    """Return the executed side for a new signal without mutating old tickets."""
    direction = str(raw_direction or "").upper()
    active = invert_signal_active() if invert_on is None else bool(invert_on)
    if active and direction == "LONG":
        return "SHORT", True
    if active and direction == "SHORT":
        return "LONG", True
    return direction, False


def stamp_signal_policy_identity(signal: dict, *, raw_direction, executed_direction, invert_on: bool) -> dict:
    """Freeze direction/treatment identity on a newly created signal ticket."""
    if not isinstance(signal, dict):
        return {}
    control_cell = dict(CONTROL_CELL)
    control_cell["invert_on"] = bool(invert_on)
    identity = build_policy_identity(
        epoch_id=_collector_v22_epoch_id(), control_cell=control_cell, invert_on=bool(invert_on),
    )
    signal.update({
        "ai_direction_raw": str(raw_direction or "").upper(),
        "raw_direction": str(raw_direction or "").upper(),
        "final_direction": str(executed_direction or "").upper(),
        "executed_direction": str(executed_direction or "").upper(),
        "direction": str(executed_direction or "").upper(),
        "invert_on": bool(invert_on),
        "invert_signal": bool(invert_on),
        "base_policy_id": identity["base_policy_id"],
        "policy_signature": identity["policy_signature"],
        "policy_epoch_id": identity["policy_epoch_id"],
        "policy_identity": identity,
    })
    return identity


def _shadow_policy_identity(*, research_lane, policy_version, exit_config, invert_on: bool) -> dict:
    """Freeze the exact lane policy that generated a shadow observation."""
    control_cell = dict(CONTROL_CELL)
    control_cell["invert_on"] = bool(invert_on)
    base = build_policy_identity(
        epoch_id=_collector_v22_epoch_id(),
        control_cell=control_cell,
        invert_on=bool(invert_on),
    )
    lane = str(research_lane or "UNKNOWN").upper()
    version = str(
        policy_version
        or "UNVERSIONED"
    )
    policy_spec = {
        "schema": "shadow_policy_spec_v1",
        "research_lane": lane,
        "policy_version": version,
        "invert_on": bool(invert_on),
        "control_policy_signature": base["policy_signature"],
        "exit_config": copy.deepcopy(exit_config),
    }
    material = json.dumps(policy_spec, sort_keys=True, separators=(",", ":"), default=str)
    signature = "shadow-policy-" + hashlib.sha256(material.encode("utf-8")).hexdigest()[:24]
    epoch_id = str(base["collection_epoch_id"])
    policy_epoch_id = "shadow-policy-epoch-" + hashlib.sha256(
        f"{epoch_id}|{signature}".encode("utf-8")
    ).hexdigest()[:24]
    return {
        "schema": "shadow_policy_identity_v1",
        "collection_epoch_id": epoch_id,
        "base_policy_id": base["base_policy_id"],
        "control_policy_signature": base["policy_signature"],
        "policy_signature": signature,
        "policy_epoch_id": policy_epoch_id,
        "policy_spec": policy_spec,
    }


def csv_research_meta(signal: dict = None) -> dict:
    """Columns written to research CSVs for analyzer version/exchange verification."""
    invert_on = False
    if signal:
        invert_on = _coerce_invert_on(signal)
    else:
        try:
            invert_on = invert_signal_active()
        except Exception:
            invert_on = False
    meta = {
        "exchange": BOT_EXCHANGE,
        "data_symbol": SYMBOL,
        "bot_version": EXECUTION_FIX_VERSION,
        "fee_profile": EXCHANGE_FEE_PROFILE,
        "analyzer_sync_id": ANALYZER_SYNC_ID,
        "invert_on": bool(invert_on),
        "invert_signal": bool(invert_on),
    }
    if signal:
        meta.update(csv_lane_meta(signal))
    return meta


def _coerce_invert_on(*sources) -> bool:
    """Ticket-time invert flag. Invert is an experimental factor, not a hidden mutation."""
    for src in sources:
        if not isinstance(src, dict):
            continue
        for key in ("invert_on", "invert_signal"):
            if src.get(key) is not None:
                return bool(src.get(key))
        controls = src.get("controls")
        if isinstance(controls, dict) and controls.get("invert_signal") is not None:
            return bool(controls.get("invert_signal"))
        entry = src.get("entry_controls")
        if isinstance(entry, dict) and entry.get("invert_signal") is not None:
            return bool(entry.get("invert_signal"))
    try:
        with state_lock:
            return invert_signal_active()
    except Exception:
        return False
