def get_edge_threshold():
    with state_lock:
        return round(float(state["edge_threshold"]), 1)

def get_edge_threshold_max():
    """Optional upper cap; None = no max (min-only gate)."""
    with state_lock:
        raw = state.get("edge_threshold_max")
    if raw is None or raw == "":
        return None
    try:
        return round(float(raw), 1)
    except (TypeError, ValueError):
        return None

def _edge_range_label() -> str:
    lo = get_edge_threshold()
    hi = get_edge_threshold_max()
    if hi is None:
        return f">={lo:.1f}"
    return f"{lo:.1f}–{hi:.1f}"

def edge_range_allows(edge_score: float) -> tuple:
    """Compatibility field for research rows; Edge never gates runtime work."""
    float(edge_score)
    return True, "EDGE_IN_RANGE"

def get_dynamic_flat_momentum_floor(base: float = None) -> float:
    """
    Flat-momentum extra bar scales with dashboard edge:
    edge 2.0 → no flat penalty (experiment mode); edge 4.0+ → full FLAT_MOMENTUM_EDGE_FLOOR.
    """
    base = round(float(base if base is not None else get_edge_threshold()), 1)
    if base <= FLAT_MOMENTUM_FLOOR_LOW_EDGE:
        return base
    if base >= FLAT_MOMENTUM_FLOOR_HIGH_EDGE:
        return round(FLAT_MOMENTUM_EDGE_FLOOR, 1)
    span = FLAT_MOMENTUM_FLOOR_HIGH_EDGE - FLAT_MOMENTUM_FLOOR_LOW_EDGE
    t = (base - FLAT_MOMENTUM_FLOOR_LOW_EDGE) / span
    return round(FLAT_MOMENTUM_FLOOR_LOW_EDGE + t * (FLAT_MOMENTUM_EDGE_FLOOR - FLAT_MOMENTUM_FLOOR_LOW_EDGE), 1)

_relay_push_state = {
    "seq": 0,
    "last_ts": 0.0,
    "last_event": None,
    "last_ok": None,
    "last_error": None,
    "last_latency_ms": None,
    "last_platform_received_at": None,
}
_relay_push_history = deque(maxlen=20)
_relay_push_history_lock = threading.Lock()
_partial_reduction_drain_lock = threading.Lock()
_relay_http_session = requests.Session()
_relay_http_adapter = requests.adapters.HTTPAdapter(
    pool_connections=4,
    pool_maxsize=8,
    max_retries=0,
    pool_block=False,
)
_relay_http_session.mount("https://", _relay_http_adapter)
_relay_http_session.mount("http://", _relay_http_adapter)
_relay_event_outbox = None  # initialized with the canonical lifecycle lock below
_relay_event_drain_lock = threading.Lock()
# RELAY_STACK_MODE=research_only (fly.toml while paper-only research): no relay
# HTTP delivery, no relay-state pusher/background refresher, stale-owner state
# reported as INFO. Boot-time constant; see relay_stack_mode.py.
RELAY_STACK_RESEARCH_ONLY = _relay_stack_mode.research_only()


def _platform_relay_keepalive_url() -> str:
    """Return a health-only URL on the exact relay origin."""
    raw = (os.getenv("SHOWCASE_RELAY_WEBHOOK_URL") or "").strip()
    try:
        parsed = urlsplit(raw)
    except Exception:
        return ""
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        return ""
    return f"{parsed.scheme}://{parsed.netloc}/api/health"


def _platform_relay_connection_keepalive_loop():
    """Event-driven relay drain with a bounded local crash-recovery tick."""
    while not shutdown_event.is_set():
        if globals().get("RELAY_STACK_RESEARCH_ONLY", False):
            # Local observation only: the guard still sees the pending index
            # (and any retirement it owns); delivery is refused below, so no
            # relay HTTP call, ACK or rewrite happens while research-only.
            _drain_relay_event_outbox_once()
            shutdown_event.wait(_relay_stack_mode.RESEARCH_ONLY_OUTBOX_OBSERVE_SEC)
            continue
        _drain_relay_event_outbox_once()
        _drain_partial_reduction_outbox_once()
        # Enqueue wakes this lane immediately. The timeout is only bounded
        # crash/missed-wake recovery and performs no idle HTTP/DB call itself.
        delay = 1.0 if _relay_event_outbox.pending_count() else 30.0
        _relay_event_outbox.consume_wake(delay)


def _relay_delivery_lag_ms(source_ts, platform_received_at):
    try:
        source_dt = datetime.fromisoformat(str(source_ts).replace("Z", "+00:00"))
        platform_dt = datetime.fromisoformat(
            str(platform_received_at).replace("Z", "+00:00")
        )
        return round((platform_dt - source_dt).total_seconds() * 1000, 1)
    except (TypeError, ValueError):
        return None


def _record_relay_delivery(
    event,
    trade_id,
    source_ts,
    *,
    ok,
    http_latency_ms,
    platform_received_at=None,
    error=None,
):
    row = {
        "event": str(event),
        "trade_id": str(trade_id) if trade_id else None,
        "source_event_at": source_ts,
        "platform_received_at": platform_received_at,
        "source_to_platform_ms": _relay_delivery_lag_ms(
            source_ts, platform_received_at
        ),
        "http_round_trip_ms": round(float(http_latency_ms), 1),
        "delivery_completed_at": utc_iso(),
        "ok": bool(ok),
        "error": str(error)[:240] if error else None,
    }
    with _relay_push_history_lock:
        _relay_push_history.append(row)


def _relay_response_has_durable_receipt(response_payload, expected_payload=None) -> bool:
    """Validate an event-specific DB receipt, never an entry-only side effect."""
    if not isinstance(response_payload, dict) or not isinstance(expected_payload, dict):
        return False
    ack = response_payload.get("durable_ack")
    if not isinstance(ack, dict):
        return False
    return bool(
        response_payload.get("persisted") is True
        and ack.get("event_id") == expected_payload.get("event_id")
        and ack.get("event_type") == expected_payload.get("event")
        and ack.get("trade_id") == expected_payload.get("trade_id")
        and ack.get("event_seq") == expected_payload.get("event_seq")
        and ack.get("payload_sha256")
        == RelayEventOutbox.payload_sha256(expected_payload)
        and ack.get("signal_cycle_event_id")
        and ack.get("platform_received_at")
    )


def _relay_delivery_history_snapshot(limit=10):
    with _relay_push_history_lock:
        return list(_relay_push_history)[-max(1, int(limit)):]


def _commit_marketable_relay_payload(payload: dict) -> bool:
    """Idempotently apply a durable marketable reprice before source ACK."""
    if not payload.get("marketable_fallback"):
        return True
    trade_id = str(payload.get("trade_id") or "")
    event_id = str(payload.get("event_id") or "")
    new_limit = float(payload.get("limit_price") or 0)
    sequence = int(payload.get("event_seq") or 0)
    with trade_lock:
        order = next((row for row in pending_orders if str(row.get("trade_id") or "") == trade_id), None)
        if not order or order.get("status") != "PENDING" or new_limit <= 0:
            return False
        if order.get("marketable_fallback"):
            return bool(
                abs(float(order.get("limit_price") or 0) - new_limit) < 0.005
                and int(order.get("limit_chase_count") or 0) == sequence
            )
        if order.get("marketable_fallback_inflight") != event_id:
            return False
        order.pop("marketable_fallback_inflight", None)
        signal = trades_map.get(trade_id, {}).get("signal_ref")
        order.update({
            "limit_price": new_limit,
            "limit_chase_count": sequence,
            "last_chase_ts": time.time(),
            "marketable_fallback": True,
            "relay_settle_not_before_ts": datetime.fromisoformat(
                str(payload.get("relay_settle_not_before_ts")).replace("Z", "+00:00")
            ).timestamp(),
            "relay_event_durable_ack": True,
            "relay_event_ack_at_ts": time.time(),
            "marketable_fallback_depth_qty": payload.get("marketable_fallback_depth_qty"),
        })
        order["fill_model"] = _resolve_fill_model(signal, order)
        if isinstance(signal, dict):
            for key in (
                "limit_price", "limit_chase_count", "last_chase_ts",
                "marketable_fallback", "relay_settle_not_before_ts",
                "relay_event_durable_ack", "relay_event_ack_at_ts",
            ):
                signal[key] = order.get(key)
            signal["submitted_order_event_seq"] = sequence
            signal["submitted_order_limit_price"] = new_limit
        return True


def _deliver_relay_outbox_record(record: dict, commit_before_ack=None) -> bool:
    """POST one already-durable event and remove it only on an exact DB ACK."""
    if globals().get("RELAY_STACK_RESEARCH_ONLY", False):
        # Withheld, not failed: the durable event stays pending and unchanged.
        _relay_push_state["research_only_withheld_total"] = int(
            _relay_push_state.get("research_only_withheld_total") or 0
        ) + 1
        return False
    payload = record.get("payload") or {}
    event_id = str(record.get("event_id") or "")
    url = (os.getenv("SHOWCASE_RELAY_WEBHOOK_URL") or "").strip()
    webhook_secret = (os.getenv("SHOWCASE_WEBHOOK_SECRET") or "").strip()
    if not url or not webhook_secret:
        _relay_event_outbox.fail(event_id, "relay URL or HMAC secret missing")
        return False
    body = RelayEventOutbox.canonical_body(payload)
    signature = hmac.new(webhook_secret.encode("utf-8"), body, hashlib.sha256).hexdigest()
    headers = {
        "Content-Type": "application/json", "Accept": "application/json",
        "X-Showcase-Signature": f"sha256={signature}",
    }
    legacy_secret = (os.getenv("BOT_CONTROL_SECRET") or "").strip()
    if legacy_secret:
        headers["X-Bot-Control-Secret"] = legacy_secret
    started = time.perf_counter()
    try:
        response = _relay_http_session.post(url, data=body, headers=headers, timeout=8.0)
        response.raise_for_status()
        receipt = response.json() if response.content else {}
        if not _relay_response_has_durable_receipt(receipt, payload):
            raise RuntimeError("relay durable receipt identity mismatch")
        ack_state = None
        if payload.get("marketable_fallback"):
            commit_before_ack = lambda: _commit_marketable_relay_payload(payload)
        if callable(commit_before_ack):
            with paper_lifecycle_file_lock:
                if commit_before_ack() is not True:
                    raise RuntimeError("relay source finalization rejected")
                ack_state = _build_paper_lifecycle_payload(
                    reason=f"relay_ack:{payload.get('event')}"
                )
                acknowledged = _relay_event_outbox.acknowledge(
                    event_id, receipt, state_payload=ack_state
                )
        else:
            acknowledged = _relay_event_outbox.acknowledge(event_id, receipt)
        if not acknowledged:
            raise RuntimeError("relay outbox acknowledgement mismatch")
        _relay_push_state.update({
            "seq": int(_relay_push_state.get("seq") or 0) + 1,
            "last_ts": time.time(), "last_event": payload.get("event"),
            "last_ok": True, "last_error": None,
            "last_latency_ms": round((time.perf_counter() - started) * 1000, 1),
            "last_platform_received_at": (receipt.get("durable_ack") or {}).get("platform_received_at"),
        })
        return True
    except Exception as exc:
        _relay_event_outbox.fail(event_id, exc)
        _relay_push_state.update({
            "last_ts": time.time(), "last_event": payload.get("event"),
            "last_ok": False, "last_error": str(exc)[:240],
            "last_latency_ms": round((time.perf_counter() - started) * 1000, 1),
        })
        return False


def _relay_outbox_data_epoch() -> dict | None:
    """Active clean data epoch for relay-outbox retirement; None (retire nothing) when undeclared."""
    try:
        return _data_epoch.active_manifest()
    except Exception:
        return None


def _drain_relay_event_outbox_once(event_id: str | None = None, commit_before_ack=None) -> dict:
    if not _relay_event_drain_lock.acquire(blocking=False):
        return {"attempted": 0, "acked": 0, "busy": True}
    try:
        with state_lock:
            armed = bool(state.get("live_armed") or state.get("bitfinex_live_enabled"))
            armed_at = state.get("live_armed_at_ts")
        # The OS singleton, not an HTTP 401 or a guessed identity, proves
        # which process may issue current-owner events. Missing proof
        # withholds delivery; it does not rewrite, ACK or discard history.
        # The owner filter applies in every mode: arming or leaving
        # FORCE_PAPER_MODE must never re-open delivery of historical events.
        owner_id = BOT_INSTANCE_ID if is_active_dashboard_owner() else None
        # Observe first: it quarantines held events and, while disarmed, retires
        # pre-epoch stale-owner ones (append-only relay_outbox_retired.jsonl), so
        # the scheduler counts below never report them as stale again.
        _relay_delivery_guard.observe(
            _relay_event_outbox.pending_index(), owner_id=owner_id, armed=armed,
            armed_at_ts=armed_at, last_ack_ts=_relay_event_outbox.last_ack_unix(),
            epoch=_relay_outbox_data_epoch(),
        )
        plan = _relay_event_outbox.delivery_plan(
            limit=100, enforce_owner=True, active_owner_id=owner_id,
            event_id=event_id, retired_event_ids=_relay_delivery_guard.retired_event_ids(),
        )
        rows = plan.pop("records")
        _relay_push_state["delivery_scheduler"] = plan
        rows = _relay_delivery_guard.filter_deliverable(
            rows, owner_id=owner_id, armed=armed, armed_at_ts=armed_at,
        )
        acked = sum(
            1 for row in rows
            if _deliver_relay_outbox_record(row, commit_before_ack=commit_before_ack)
        )
        return {"attempted": len(rows), "acked": acked, "busy": False}
    finally:
        _relay_event_drain_lock.release()

