def ensure_signal_registered(signal: dict):
    if not signal or not signal.get("trade_id"):
        return
    with trade_lock:
        trades_map[signal["trade_id"]] = {"signal_ref": signal}
        logger.info(f"[SIGNAL REGISTERED] trade_id={signal['trade_id']} [PIPELINE ENFORCEMENT]")
    with state_lock:
        if "signals" not in state["signal_info"]:
            state["signal_info"]["signals"] = []
        state["signal_info"]["signals"].append(signal)
        state["signal_info"]["active"] = True
        state["signal_info"]["count"] += 1

def validate_ai_features(ctx):
    required = ["velocity", "volume_ratio", "delta", "imbalance"]
    for k in required:
        if k not in ctx:
            return False, f"MISSING_{k}"
        if ctx[k] is None:
            return False, f"NONE_{k}"
    if all(abs(ctx[k]) < 1e-5 for k in required):
        return False, "ALL_ZERO"
    return True, "OK"

def update_data_quality(features: dict) -> float:
    try:
        valid = 0
        total = 6
        if abs(features.get("delta", 0)) > 0: valid += 1
        if abs(features.get("delta_change", 0)) > 0: valid += 1
        if abs(features.get("imbalance", 0)) > 0: valid += 1
        if abs(features.get("velocity", 0)) > 0: valid += 1
        if features.get("volume", 0) > 0: valid += 1
        if features.get("volume_ratio", 0) > 0: valid += 1
        score = valid / total
        if abs(features.get("delta", 0)) > 10 or features.get("volume_ratio", 0) > 1:
            score += 0.1
        return min(score, 1.0)
    except Exception as e:
        logger.error(f"[DATA QUALITY ERROR] {e} [PIPELINE ENFORCEMENT]")
        return 0.0

def update_feature_snapshot():
    try:
        if len(delta_buffer) >= 2:
            delta_change = delta_buffer[-1] - delta_buffer[-2]
        else:
            delta_change = 0.0
        if delta_change == 0 and len(delta_buffer) > 3:
            delta_change = delta_buffer[-1] - delta_buffer[-3]
        if len(price_buffer) >= 2:
            prev = price_buffer[-2]
            velocity = (price_buffer[-1] - prev) / prev if prev != 0 else 0.0
        else:
            velocity = 0.0
        if abs(velocity) < 1e-5 and len(price_buffer) > 3:
            prev = price_buffer[-3]
            velocity = (price_buffer[-1] - prev) / prev if prev != 0 else 0.0
        vol_mean = np.mean(volume_buffer) if len(volume_buffer) > 0 else 0
        state["feature_snapshot"] = {
            "velocity": float(velocity),
            "volume": float(volume_buffer[-1]) if len(volume_buffer) > 0 else 0,
            "volume_ratio": compute_volume_ratio(),
            "delta": float(delta_buffer[-1]) if len(delta_buffer) > 0 else 0,
            "imbalance": float(imbalance_buffer[-1]) if len(imbalance_buffer) > 0 else 0,
            "delta_change": float(delta_change)
        }
        data_quality = update_data_quality(state["feature_snapshot"])
        with state_lock:
            state["data_quality"] = data_quality
            state["data_quality_ts"] = time.time()
        if state.get("debug_enabled"):
            logger.debug(f"[FEATURES] {state['feature_snapshot']}")
            logger.debug(f"[DATA QUALITY] {data_quality:.3f}")
    except Exception as e:
        logger.error(f"[FEATURE SNAPSHOT ERROR] {e} [PIPELINE ENFORCEMENT]")

def sanitize_features(f):
    for k in f:
        if f[k] is None:
            f[k] = 0.0
    if f.get("delta") == 0 and len(delta_buffer) > 0:
        f["delta"] = delta_buffer[-1]
    if f.get("volume") == 0 and len(volume_buffer) > 0:
        f["volume"] = volume_buffer[-1]
    return f

def update_orderflow(trade):
    try:
        size = float(trade.get('v', trade.get('q', 0)))
        side = trade.get('S', trade.get('side', '')).lower()
        # Captured before the update so delta - prev_delta is this trade's signed
        # volume (delta_change); taking it afterwards pinned delta_change at 0.
        orderflow["prev_delta"] = orderflow.get("delta", 0.0)
        if side == "buy":
            orderflow["buy_volume"] += size
        elif side == "sell":
            orderflow["sell_volume"] += size
        orderflow["delta"] = orderflow["buy_volume"] - orderflow["sell_volume"]
        total = orderflow["buy_volume"] + orderflow["sell_volume"]
        orderflow["imbalance"] = abs(orderflow["delta"]) / total if total > 0 else 0
        orderflow["last_update"] = time.time()
    except Exception as e:
        logger.error(f"[ORDERFLOW ERROR] {e} [PIPELINE ENFORCEMENT]")

def _trend_health_interpretation(trend_state: str, health: dict) -> str:
    ts = str(trend_state or "").upper()
    if ts == "BULL_WEAKENING":
        return "Bullish but weakening"
    if ts == "BEAR_WEAKENING":
        return "Bearish but weakening"
    if ts == "BULL":
        return "Bullish and intact"
    if ts == "BEAR":
        return "Bearish and intact"
    return "Mixed / no clear trend health"


def _bull_bear_score_changes_15m() -> dict:
    with state_lock:
        hist = list(state.get("trend_health_history") or [])
    if not hist:
        return {"bull_score_change_15m": 0, "bear_score_change_15m": 0}
    now = time.time()
    target_ts = now - 900.0
    baseline = None
    for entry in hist:
        if float(entry.get("ts") or 0) <= target_ts:
            baseline = entry
    if baseline is None and len(hist) >= 2:
        baseline = hist[0]
    current = hist[-1]
    if baseline is None:
        return {"bull_score_change_15m": 0, "bear_score_change_15m": 0}
    bull_now = int(current.get("bull_score") or 0)
    bear_now = int(current.get("bear_score") or 0)
    bull_then = int(baseline.get("bull_score") or bull_now)
    bear_then = int(baseline.get("bear_score") or bear_now)
    return {
        "bull_score_change_15m": bull_now - bull_then,
        "bear_score_change_15m": bear_now - bear_then,
    }


def _record_regime_cycle(regime: str, trend_state: str) -> None:
    with state_lock:
        hist = list(state.get("regime_cycle_history") or [])
        hist.append({
            "ts": time.time(),
            "regime": str(regime or "UNKNOWN"),
            "trend_state": str(trend_state or "MIXED"),
        })
        state["regime_cycle_history"] = hist[-120:]


def _regime_memory_snapshot() -> dict:
    with state_lock:
        hist = list(state.get("regime_cycle_history") or [])
    now = time.time()
    last_hour = [h for h in hist if now - float(h.get("ts") or 0) <= 3600.0]
    changes = 0
    prev_regime = None
    for entry in last_hour:
        regime = entry.get("regime")
        if prev_regime is not None and regime != prev_regime:
            changes += 1
        prev_regime = regime
    last_3 = hist[-3:]
    return {
        "regime_changes_60m": changes,
        "trend_state_last_3_cycles": [h.get("trend_state") for h in last_3],
        "last_3_regimes": [h.get("regime") for h in last_3],
        "last_3_signals": [
            "bull" if str(h.get("trend_state") or "").startswith("BULL") else (
                "bear" if str(h.get("trend_state") or "").startswith("BEAR") else "mixed"
            )
            for h in last_3
        ],
    }


def classify_market_regime(health: dict, ctx: dict, ms: dict, regime_mem: dict) -> str:
    ts = str(health.get("trend_state") or "")
    mc = ctx.get("market_context") or {}
    adx = float((mc.get("trend_strength") or {}).get("adx") or 0)
    vol_ratio = float(ctx.get("volume_ratio") or 0)
    struct = abs(float(ms.get("structure_score") or 0))
    churn = int(regime_mem.get("regime_changes_60m") or 0)
    if ts.endswith("_WEAKENING"):
        return "WEAKENING"
    if churn >= 3:
        return "TRANSITION"
    if adx < 18 and struct < 2:
        return "RANGE"
    if vol_ratio < 0.4:
        return "COMPRESSION"
    if vol_ratio > 1.5 and struct >= 3:
        return "EXPANSION"
    if ts in ("BULL", "BEAR") and adx >= 20:
        return "TRENDING"
    return "TRANSITION"


def update_market_regime_tracker(health: dict, ctx: dict, ms: dict, regime_mem: dict) -> dict:
    label = classify_market_regime(health, ctx, ms, regime_mem)
    now = time.time()
    with state_lock:
        tracker = copy.deepcopy(state.get("market_regime_tracker") or {})
        prev = tracker.get("current")
        since = float(tracker.get("since_ts") or now)
        history = list(tracker.get("history") or [])
        if prev != label:
            if prev:
                history.append({
                    "regime": prev,
                    "duration_sec": round(now - since, 1),
                    "ended_ts": now,
                })
            tracker["current"] = label
            tracker["since_ts"] = now
            since = now
        tracker["duration_sec"] = round(now - since, 1)
        tracker["history"] = history[-40:]
        state["market_regime_tracker"] = tracker
    return tracker


def _entry_distance_metrics(price: float, ms: dict, ctx: dict, candles=None) -> dict:
    price = float(price or 0)
    if candles is None:
        with state_lock:
            candles = copy.deepcopy(latest_candles) or []
    window = candles[-12:] if len(candles) >= 12 else list(candles or [])
    metrics = {
        "distance_from_last_impulse_pct": None,
        "distance_from_last_pullback_pct": None,
        "distance_from_micro_sr_pct": None,
        "distance_from_ema_pct": None,
    }
    if price <= 0:
        return metrics
    ema9 = float(ctx.get("ema9") or 0)
    if ema9 > 0:
        metrics["distance_from_ema_pct"] = round(abs(price - ema9) / price * 100, 4)
    micro_support = ms.get("micro_support")
    micro_resistance = ms.get("micro_resistance")
    micro_ref = micro_support or micro_resistance
    if micro_ref:
        metrics["distance_from_micro_sr_pct"] = round(abs(price - float(micro_ref)) / price * 100, 4)
    if window:
        impulse_high = max(float(c[2]) for c in window)
        impulse_low = min(float(c[3]) for c in window)
        impulse_range = max(impulse_high - impulse_low, 1e-9)
        metrics["distance_from_last_impulse_pct"] = round(
            abs(impulse_high - price) / impulse_range * 100, 4
        )
        metrics["distance_from_last_pullback_pct"] = round(
            abs(price - impulse_low) / impulse_range * 100, 4
        )
    return metrics


def compute_entry_stage(price: float, ms: dict, ctx: dict) -> tuple:
    price = float(price or 0)
    if price <= 0:
        return "MID", {}
    metrics = _entry_distance_metrics(price, ms, ctx)
    struct = abs(float(ms.get("structure_score") or 0))
    ret_5m = abs(float(ctx.get("ret_5m") or 0))
    dist_impulse = metrics.get("distance_from_last_impulse_pct")
    dist_pullback = metrics.get("distance_from_last_pullback_pct")
    dist_micro = metrics.get("distance_from_micro_sr_pct")
    dist_ema = metrics.get("distance_from_ema_pct")
    near_pullback = dist_pullback is not None and dist_pullback <= 25.0
    near_micro = dist_micro is not None and dist_micro <= 0.35
    near_ema = dist_ema is not None and dist_ema <= 0.45
    chasing = (
        dist_impulse is not None
        and dist_impulse <= 12.0
        and struct >= 3
    ) or (struct >= 5 and ret_5m > 0.002)
    if near_pullback or near_micro or near_ema:
        stage = "EARLY"
    elif chasing:
        stage = "LATE"
    else:
        stage = "MID"
    meta = {
        **metrics,
        "structure_extension": round(struct, 2),
        "ret_5m_abs": round(ret_5m, 6),
    }
    return stage, meta


def detect_liquidity_sweep(candles=None, price: float = None, ms: dict = None, ctx: dict = None) -> dict:
    if candles is None:
        with state_lock:
            candles = copy.deepcopy(latest_candles) or []
    recent = candles[-8:] if len(candles) >= 8 else list(candles or [])
    result = {
        "liquidity_sweep_high": False,
        "liquidity_sweep_low": False,
        "sweep_high_volume_spike": False,
        "sweep_low_volume_spike": False,
        "sweep_engine": "v95_wick_reclaim_volume",
    }
    if not recent:
        return result
    ms = ms or {}
    price = float(price if price is not None else recent[-1][4])
    prior_high = ms.get("prior_resistance") or ms.get("last_swing_high") or ms.get("micro_resistance")
    prior_low = ms.get("prior_support") or ms.get("last_swing_low") or ms.get("micro_support")
    vols = [float(c[5]) if len(c) > 5 else float(ctx.get("volume") or 0) for c in recent]
    avg_vol = sum(vols) / max(len(vols), 1)
    vol_spike = max(avg_vol * 1.35, 1e-12)
    for c in recent:
        hi = float(c[2])
        lo = float(c[3])
        cl = float(c[4])
        vol = float(c[5]) if len(c) > 5 else avg_vol
        if prior_high:
            level = float(prior_high)
            if hi > level and cl < level and vol >= vol_spike:
                result["liquidity_sweep_high"] = True
                result["sweep_high_volume_spike"] = True
        if prior_low:
            level = float(prior_low)
            if lo < level and cl > level and vol >= vol_spike:
                result["liquidity_sweep_low"] = True
                result["sweep_low_volume_spike"] = True
    if not result["liquidity_sweep_high"] and prior_high:
        level = float(prior_high)
        max_hi = max(float(c[2]) for c in recent)
        if max_hi > level * 1.0002 and price < level:
            result["liquidity_sweep_high"] = True
    if not result["liquidity_sweep_low"] and prior_low:
        level = float(prior_low)
        min_lo = min(float(c[3]) for c in recent)
        if min_lo < level * 0.9998 and price > level:
            result["liquidity_sweep_low"] = True
    return result


def compute_reversal_risk_score(health: dict, ctx: dict, ms: dict, micro_eval: dict, score_changes: dict) -> int:
    risk = 0.0
    ts = str(health.get("trend_state") or "")
    weaken = int(health.get("weaken_signals") or 0)
    vol_ratio = float(ctx.get("volume_ratio") or 0)
    vel = float(ctx.get("velocity") or 0)
    mc = ctx.get("market_context") or {}
    struct = float((mc.get("market_structure") or {}).get("structure_score") or ms.get("structure_score") or 0)
    if ts.endswith("_WEAKENING"):
        risk += 20
    risk += weaken * 8
    if vol_ratio < 0.5:
        risk += 10
    if ts.startswith("BULL") and vel < 0:
        risk += 12
    elif ts.startswith("BEAR") and vel > 0:
        risk += 12
    if int(score_changes.get("bull_score_change_15m") or 0) < -1:
        risk += 8
    if int(score_changes.get("bear_score_change_15m") or 0) > 1:
        risk += 8
    if abs(struct) >= 6:
        risk += 10
    if micro_eval.get("rejects_micro_sr"):
        risk += 15
    if ms.get("lower_high") and ts.startswith("BULL"):
        risk += 10
    if ms.get("higher_low") and ts.startswith("BEAR"):
        risk += 10
    return int(min(100, round(risk)))


def compute_ai_quality_components_from_ctx(ctx: dict, health: dict, micro_eval: dict, ms: dict) -> dict:
    mc = ctx.get("market_context") or {}
    ms_mc = mc.get("market_structure") or {}
    struct = float(ms_mc.get("structure_score") or ms.get("structure_score") or 0)
    structure_comp = max(0.0, min(100.0, (struct + 10.0) / 20.0 * 100.0))
    if micro_eval.get("confirmed"):
        micro_sr_comp = 100.0
    elif micro_eval.get("bias_ok") or micro_eval.get("pattern_ok"):
        micro_sr_comp = 55.0
    else:
        micro_sr_comp = 35.0
    ts = str(health.get("trend_state") or "MIXED")
    trend_map = {
        "BULL": 100.0, "BEAR": 100.0,
        "BULL_WEAKENING": 40.0, "BEAR_WEAKENING": 40.0,
        "MIXED": 55.0,
    }
    trend_comp = trend_map.get(ts, 55.0)
    bull = int(health.get("bull_score") or 0)
    bear = int(health.get("bear_score") or 0)
    spread = abs(bull - bear)
    spread_comp = max(0.0, min(100.0, float(spread) / 7.0 * 100.0))
    edge_score = float(ctx.get("edge_score") or 0)
    edge_comp = max(0.0, min(100.0, edge_score / 6.0 * 100.0))
    quality_score = round(
        0.30 * structure_comp + 0.25 * micro_sr_comp + 0.20 * trend_comp
        + 0.15 * spread_comp + 0.10 * edge_comp,
        2,
    )
    return {
        "quality_score": quality_score,
        "structure_component": round(structure_comp, 2),
        "micro_sr_component": round(micro_sr_comp, 2),
        "trend_health_component": round(trend_comp, 2),
        "spread_component": round(spread_comp, 2),
        "edge_component": round(edge_comp, 2),
        "trend_health_state": ts,
    }


def compute_market_structure_shift(mc: dict, health: dict) -> str:
    """Classify short-horizon structure shift for AI (not a hard gate)."""
    mc = mc or {}
    health = health or {}
    ms = mc.get("market_structure") or {}
    struct = float(ms.get("structure_score") or 0)
    agreement = str((mc.get("multi_tf") or {}).get("agreement") or "")
    trend = str(health.get("trend_state") or "")
    if struct > 2 and agreement == "BULL_ALIGNED":
        return "BULL_CONTINUATION"
    if struct < -2 and agreement == "BEAR_ALIGNED":
        return "BEAR_CONTINUATION"
    if "BULL" in trend and trend.endswith("_WEAKENING"):
        return "BULL_TO_BEAR_SHIFT"
    if "BEAR" in trend and trend.endswith("_WEAKENING"):
        if struct <= -2:
            return "BEAR_CONTINUATION"
        return "BEAR_TO_BULL_SHIFT"
    if agreement == "CONFLICTED":
        return "BEAR_TO_BULL_SHIFT" if struct > 0 else "BULL_TO_BEAR_SHIFT"
    return "BULL_CONTINUATION" if struct >= 0 else "BEAR_CONTINUATION"


def enrich_ai_context_upgrade(ctx: dict) -> dict:
    """v94: Add trend health, entry timing, micro-SR, reversal risk, sweeps, quality, regime memory."""
    if not isinstance(ctx, dict):
        return ctx
    price = float(ctx.get("price") or 0)
    regime = str(ctx.get("regime") or "UNKNOWN")
    health = compute_trend_health()
    score_changes = _bull_bear_score_changes_15m()
    ms = build_micro_sr_levels()
    base = str(health.get("base_state") or "MIXED")
    struct_hint = float(health.get("structure_score") or (ms.get("structure_score") or 0))
    if base == "BULL":
        hint_dir = "LONG"
    elif base == "BEAR":
        hint_dir = "SHORT"
    elif struct_hint < 0:
        hint_dir = "SHORT"
    elif struct_hint > 0:
        hint_dir = "LONG"
    else:
        hint_dir = "LONG"
    micro_eval = evaluate_micro_structure_confirm(hint_dir, price, None, ms)
    entry_stage, entry_meta = compute_entry_stage(price, ms, ctx)
    sweeps = detect_liquidity_sweep(None, price, ms, ctx)
    reversal_risk = compute_reversal_risk_score(health, ctx, ms, micro_eval, score_changes)
    quality = compute_ai_quality_components_from_ctx(ctx, health, micro_eval, ms)
    trend_state = str(health.get("trend_state") or "MIXED")
    _record_regime_cycle(regime, trend_state)
    regime_mem = _regime_memory_snapshot()
    # update_market_regime_tracker mutates state["market_regime_tracker"] as a
    # side effect; keep the call but the tracker dict no longer flows into AI
    # context (Stage 1 Fix #2 removed that surface to kill regime anchoring).
    update_market_regime_tracker(health, ctx, ms, regime_mem)
    mc = ctx.get("market_context") or state.get("market_context") or {}
    market_structure_shift = compute_market_structure_shift(mc, health)
    reversal_probability = int(reversal_risk)
    dist_micro_support = None
    dist_micro_resistance = None
    if price > 0 and ms.get("micro_support"):
        dist_micro_support = round(abs(price - float(ms["micro_support"])) / price, 6)
    if price > 0 and ms.get("micro_resistance"):
        dist_micro_resistance = round(abs(price - float(ms["micro_resistance"])) / price, 6)
    upgrade = {
        "trend_health_state": trend_state,
        "weaken_signals": int(health.get("weaken_signals") or 0),
        "bull_score_change_15m": int(score_changes.get("bull_score_change_15m") or 0),
        "bear_score_change_15m": int(score_changes.get("bear_score_change_15m") or 0),
        "entry_stage": entry_stage,
        "micro_structure_confirmed": bool(micro_eval.get("confirmed")),
        "higher_low_detected": bool(ms.get("higher_low")),
        "lower_high_detected": bool(ms.get("lower_high")),
        "pivot_count": int(ms.get("pivot_count") or 0),
        "distance_to_micro_support": dist_micro_support,
        "distance_to_micro_resistance": dist_micro_resistance,
        "reversal_risk_score": reversal_risk,
        "reversal_probability": reversal_probability,
        "reversal_risk_note": "Higher score = more reversal risk (not approval probability)",
        # Stage 1 Fix #2: removed regime_ema200 and regime_trend_health. The
        # raw `regime` field stays in ctx (one mention) and trend_health
        # remains the full object below; these two redundant regime labels
        # were anchored on by the AI and suppressed weighting of structure.
        "market_structure_shift": market_structure_shift,
        "micro_support": ms.get("micro_support"),
        "micro_resistance": ms.get("micro_resistance"),
        "mtf_informational_only": bool(is_research_data_collection() and not MTF_BLOCKING_RESEARCH),
        "liquidity_sweep_high": bool(sweeps.get("liquidity_sweep_high")),
        "liquidity_sweep_low": bool(sweeps.get("liquidity_sweep_low")),
        "quality_score_components": {
            "structure_component": quality.get("structure_component"),
            "micro_sr_component": quality.get("micro_sr_component"),
            "trend_component": quality.get("trend_health_component"),
            "spread_component": quality.get("spread_component"),
            "edge_component": quality.get("edge_component"),
            "quality_score": quality.get("quality_score"),
        },
        "regime_change_count_60m": int(regime_mem.get("regime_changes_60m") or 0),
        # Stage 1 Fix #2: removed trend_state_last_3_cycles, last_3_regimes,
        # last_3_signals. These three list-style regime labels plus the two
        # above and market_regime_tracker below made 9 redundant BULL/BEAR
        # cues in AI context; the model anchored on them and ignored
        # market_structure_shift. regime_mem itself is unchanged (still used
        # by classify_market_regime / update_market_regime_tracker).
        "entry_timing": entry_meta,
        "trend_health_detail": {
            # Stage 1 Fix #2: dropped base_state sub-field; it duplicates the
            # raw `regime` field and trend_health_state. Keep bull_score /
            # bear_score / interpretation as structure/order-flow evidence.
            "bull_score": health.get("bull_score"),
            "bear_score": health.get("bear_score"),
            "interpretation": _trend_health_interpretation(trend_state, health),
        },
        "micro_structure": {
            "micro_support": ms.get("micro_support"),
            "micro_resistance": ms.get("micro_resistance"),
            "structure_bias": ms.get("structure_bias"),
            "rejects_micro_sr": bool(micro_eval.get("rejects_micro_sr")),
            "near_micro_sr": bool(micro_eval.get("near_micro_sr")),
        },
        # Stage 1 Fix #2: removed market_regime_tracker sub-dict. The legacy
        # log_ai_reason_outcome / log_trade_lifecycle readers use
        # upgrade.get("market_regime_tracker") or {} (graceful), and
        # log_trade_lifecycle falls back to ctx.get("market_regime_tracker")
        # which is no longer set either - both will report market_regime=None,
        # which is honest given the AI no longer sees this signal either.
        "edge_research_telemetry_only": EDGE_RESEARCH_TELEMETRY_ONLY,
        "historically_profitable_patterns": load_historically_profitable_patterns(),
    }
    ctx["trend_health"] = health
    ctx["historically_profitable_patterns"] = upgrade["historically_profitable_patterns"]
    ctx["ai_input_upgrade"] = upgrade
    ctx["trend_health_state"] = upgrade["trend_health_state"]
    ctx["weaken_signals"] = upgrade["weaken_signals"]
    ctx["bull_score_change_15m"] = upgrade["bull_score_change_15m"]
    ctx["bear_score_change_15m"] = upgrade["bear_score_change_15m"]
    ctx["entry_stage"] = upgrade["entry_stage"]
    ctx["micro_structure_confirmed"] = upgrade["micro_structure_confirmed"]
    ctx["higher_low_detected"] = upgrade["higher_low_detected"]
    ctx["lower_high_detected"] = upgrade["lower_high_detected"]
    ctx["pivot_count"] = upgrade["pivot_count"]
    ctx["distance_to_micro_support"] = upgrade["distance_to_micro_support"]
    ctx["distance_to_micro_resistance"] = upgrade["distance_to_micro_resistance"]
    ctx["reversal_risk_score"] = upgrade["reversal_risk_score"]
    ctx["reversal_probability"] = upgrade["reversal_probability"]
    ctx["market_structure_shift"] = upgrade["market_structure_shift"]
    ctx["micro_support"] = upgrade["micro_support"]
    ctx["micro_resistance"] = upgrade["micro_resistance"]
    ctx["mtf_informational_only"] = upgrade["mtf_informational_only"]
    ctx["liquidity_sweep_high"] = upgrade["liquidity_sweep_high"]
    ctx["liquidity_sweep_low"] = upgrade["liquidity_sweep_low"]
    ctx["quality_score_components"] = upgrade["quality_score_components"]
    ctx["regime_change_count_60m"] = upgrade["regime_change_count_60m"]
    # Stage 1 Fix #2: removed ctx["trend_state_last_3_cycles"] / ctx["last_3_signals"]
    # / ctx["market_regime_tracker"] mirror assignments to match the upgrade
    # dict slimming above.
    ctx["edge_research_telemetry_only"] = EDGE_RESEARCH_TELEMETRY_ONLY
    return ctx


def _finite_positive_sr_value(value) -> bool:
    """Return whether one S/R swing is a finite positive numeric scalar."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return False
    try:
        numeric = float(value)
    except (OverflowError, TypeError, ValueError):
        return False
    return bool(math.isfinite(numeric) and numeric > 0)


def _sr_swing_pair_ready(support_resistance) -> bool:
    """Non-mutating structural predicate shared by readiness and AI context."""
    if not isinstance(support_resistance, dict):
        return False
    swing_high = support_resistance.get("swing_high")
    swing_low = support_resistance.get("swing_low")
    return bool(
        _finite_positive_sr_value(swing_high)
        and _finite_positive_sr_value(swing_low)
        and float(swing_high) > float(swing_low)
    )


def _sr_swing_prerequisite_failures(support_resistance) -> list:
    """Classify missing and invalid S/R inputs without changing source state."""
    if support_resistance is None:
        support_resistance = {}
    if not isinstance(support_resistance, dict):
        return ["SR_STRUCTURE_INVALID"]
    swing_high = support_resistance.get("swing_high")
    swing_low = support_resistance.get("swing_low")
    failures = []
    high_missing = swing_high is None or (
        not isinstance(swing_high, bool)
        and isinstance(swing_high, (int, float)) and swing_high == 0
    )
    low_missing = swing_low is None or (
        not isinstance(swing_low, bool)
        and isinstance(swing_low, (int, float)) and swing_low == 0
    )
    high_valid = _finite_positive_sr_value(swing_high)
    low_valid = _finite_positive_sr_value(swing_low)
    if high_missing:
        failures.append("SR_SWING_HIGH_MISSING")
    elif not high_valid:
        failures.append("SR_SWING_HIGH_INVALID")
    if low_missing:
        failures.append("SR_SWING_LOW_MISSING")
    elif not low_valid:
        failures.append("SR_SWING_LOW_INVALID")
    if high_valid and low_valid and float(swing_high) <= float(swing_low):
        failures.append("SR_SWING_RANGE_INVALID")
    return failures


def _bounded_ctx_failure_scalar(value, *, max_text: int = 64, numeric_only: bool = False):
    """Project one JSON-safe bounded scalar for diagnostic evidence only."""
    if value is None:
        return None
    if numeric_only and (isinstance(value, bool) or not isinstance(value, (int, float))):
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        try:
            if not math.isfinite(float(value)) or len(str(value)) > 64:
                return None
        except (OverflowError, TypeError, ValueError):
            return None
        return value
    if isinstance(value, str):
        return value[:max(0, min(int(max_text), 256))]
    return None


def _ctx_fail_prerequisite_detail(state_snapshot: dict) -> dict:
    """Return only observed S/R prerequisites that made pure context unavailable."""
    raw_sr = state_snapshot.get("support_resistance")
    sr = raw_sr if isinstance(raw_sr, dict) else {}
    return {
        "prerequisite_failures": _sr_swing_prerequisite_failures(raw_sr),
        "sr_swing_high": _bounded_ctx_failure_scalar(
            sr.get("swing_high"), numeric_only=True,
        ),
        "sr_swing_low": _bounded_ctx_failure_scalar(
            sr.get("swing_low"), numeric_only=True,
        ),
        "sr_state": _bounded_ctx_failure_scalar(sr.get("sr_state"), max_text=64),
        "sr_timestamp": _bounded_ctx_failure_scalar(sr.get("ts"), max_text=64),
    }


def build_pure_ai_context(state_snapshot, buffers, failure_detail=None):
    raw_sr = state_snapshot.get("support_resistance")
    if not _sr_swing_pair_ready(raw_sr):
        if isinstance(failure_detail, dict):
            failure_detail.clear()
            failure_detail.update(_ctx_fail_prerequisite_detail(state_snapshot))
        logger.warning("[SR VALIDATION] Invalid SR data - skipping AI [PIPELINE ENFORCEMENT]")
        return None
    sr = raw_sr
    tape = _ai_shadow_tape_features()
    ctx = {
        "price": nz(state_snapshot.get("price")),
        "recent_high": nz(sr.get("swing_high")),
        "recent_low": nz(sr.get("swing_low")),
        "dist_to_resistance": nz(sr.get("dist_to_resistance")),
        "dist_to_support": nz(sr.get("dist_to_support")),
        "ema9": nz(state_snapshot.get("ema_status", {}).get("ema9")),
        "ema21": nz(state_snapshot.get("ema_status", {}).get("ema21")),
        "ema200": nz(state_snapshot.get("ema_status", {}).get("ema200")),
        "ema_slope": (nz(state_snapshot.get("ema_status", {}).get("ema9")) - nz(state_snapshot.get("ema_status", {}).get("ema21"))) / nz(state_snapshot.get("ema_status", {}).get("ema21")) if nz(state_snapshot.get("ema_status", {}).get("ema21")) != 0 else 0.0,
        # Fractional returns from the Bitfinex 1 s tape (same source as the
        # prompt's ret_*_bp); 0 only when the tape has no such window yet.
        "ret_1m": nz(tape.get("ret_1m"), 0.0),
        "ret_5m": nz(tape.get("ret_5m"), 0.0),
        "velocity": get_aggregated(velocity_buffer),
        "volume": get_aggregated(volume_buffer),
        "avg_volume": get_aggregated(volume_buffer),
        "volume_ratio": compute_volume_ratio(),
        "delta": get_aggregated(delta_buffer),
        "delta_change": get_aggregated(delta_change_buffer),
        "imbalance": get_aggregated(imbalance_buffer),
        "candle_range": get_aggregated(candle_range_buffer),
        "wick_ratio": get_aggregated(wick_ratio_buffer),
        "body_ratio": get_aggregated(body_ratio_buffer),
        "edge_score": state.get("last_edge", 0.0),
        "edge_threshold": get_edge_threshold(),
        "regime": state_snapshot.get("regime", "UNKNOWN"),
        "sr_state": sr.get("sr_state", "UNKNOWN"),
        "sr_bias": sr.get("sr_bias", "UNKNOWN"),
        "data_quality": state_snapshot.get("data_quality", 0.0),
        "funding": get_funding_snapshot_for_ai(),
        "market_context": get_market_context_for_ai(),
    }
    ctx = sanitize_features(ctx)
    ctx = enrich_ai_context_upgrade(ctx)
    ctx = _stamp_3m_exhaustion_for_ai(ctx)
    return sanitize_ai_inputs(ctx)


def _record_ctx_fail_unavailable_coverage(raw_context: dict, failure_detail: dict) -> dict:
    """Persist a bounded no-call receipt; never create a research opportunity."""
    from research.scan_counterfactual_unavailable import build_scan_counterfactual_unavailable

    observed_at = time.time()
    receipt = build_scan_counterfactual_unavailable(
        context=raw_context,
        reason_code="CONTEXT_UNAVAILABLE",
        observed_at_ts=observed_at,
        source_revision=_runtime_git_rev_exact(),
        epoch_id=_collector_v22_epoch_id(),
    )
    try:
        readiness = _runtime_readiness_components(observed_at)
    except Exception:
        readiness = {}
    receipt.update({
        "context_failure_schema": "pure_ai_context_prerequisite_failure_v1",
        "prerequisite_failures": list(
            (failure_detail or {}).get("prerequisite_failures") or []
        )[:2],
        "sr_swing_high": (failure_detail or {}).get("sr_swing_high"),
        "sr_swing_low": (failure_detail or {}).get("sr_swing_low"),
        "sr_state": (failure_detail or {}).get("sr_state"),
        "sr_timestamp": (failure_detail or {}).get("sr_timestamp"),
        "candle_count": len(latest_candles),
        "buffer_counts": {
            "price": len(price_buffer),
            "volume": len(volume_buffer),
            "delta": len(delta_buffer),
            "imbalance": len(imbalance_buffer),
            "candle_range": len(candle_range_buffer),
            "wick_ratio": len(wick_ratio_buffer),
            "body_ratio": len(body_ratio_buffer),
        },
        "readiness": {
            "system_ready": bool(readiness.get("system_ready")),
            "structural_prerequisites_ready": bool(
                readiness.get("structural_prerequisites_ready")
            ),
            "sr_ready": bool(readiness.get("sr_ready")),
            "buffers_ready": bool(readiness.get("buffers_ready")),
            "candle_ready": bool(readiness.get("candle_ready")),
            "ema_ready": bool(readiness.get("ema_ready")),
            "ohlcv_ready": bool(readiness.get("ohlcv_ready")),
            "readiness_reasons": [
                str(reason)[:64]
                for reason in (readiness.get("readiness_reasons") or [])[:16]
            ],
        },
    })
    try:
        accepted = _safe_append_jsonl(
            AI_INPUT_LOG_FILE, receipt, label="AI_INPUT",
        ) is True
    except Exception:
        accepted = False
    if not accepted:
        logger.warning("[RESEARCH] CTX_FAIL_COVERAGE_WRITE_FAILED")
    return {
        "receipt": receipt,
        "write_status": "ACCEPTED" if accepted else "FAILED",
    }


def _build_pure_ai_context_with_evidence(state_snapshot, buffers, raw_context):
    failure_detail = {}
    ctx = build_pure_ai_context(
        state_snapshot, buffers, failure_detail=failure_detail,
    )
    if ctx is not None:
        return ctx, None
    return None, _record_ctx_fail_unavailable_coverage(
        raw_context, failure_detail,
    )


def build_shared_direction_prompt_context(ctx: dict) -> dict:
    """Build the compact, timestamped raw/derived payload used by the AI.

    The durable collector retains the full context.  The model receives only
    causal decision inputs, with raw observations separated from derived
    labels so repeated labels cannot overpower the underlying measurements.
    """
    source = ctx or {}
    mc = source.get("market_context") or {}
    cycle = source.get("cycle_3m_universe") or source.get("exhaustion_3m") or {}
    upgrade = source.get("ai_input_upgrade") or {}
    tape = source.get("tape_features") or {}
    funding = source.get("funding") or {}
    # The 3m universe block keys its oscillator and bucket as stoch_rsi_k/_d and
    # cycle_bucket (start of the forming bar = close of the last closed bar).
    closed_3m_ts = (
        cycle.get("closed_3m_ts") or cycle.get("cycle_bucket")
        or cycle.get("candle_ts") or cycle.get("bucket_ts")
    )
    raw = {
        "price": source.get("price"),
        "closed_3m_ts": closed_3m_ts,
        "closed_3m_age_s": (
            round(time.time() - float(closed_3m_ts), 1) if closed_3m_ts is not None else None
        ),
        "rsi_3m": cycle.get("rsi_3m") or cycle.get("rsi14_3m"),
        "stoch_rsi_k_3m": cycle.get("stoch_rsi_k_3m", cycle.get("stoch_rsi_k")),
        "stoch_rsi_d_3m": cycle.get("stoch_rsi_d_3m", cycle.get("stoch_rsi_d")),
        "atr14_pct_3m": cycle.get("atr14_pct_3m"),
        "donchian_loc_3m": cycle.get("donchian_loc_3m"),
        "bb_width_3m": cycle.get("bb_width_3m"),
        "ret_1m_bp": tape.get("ret_1m_bp"),
        "ret_5m_bp": tape.get("ret_5m_bp"),
        "ret_15m_bp": tape.get("ret_15m_bp"),
        "tape_age_s": tape.get("tape_age_s"),
        "ema9": source.get("ema9"),
        "ema21": source.get("ema21"),
        "ema200": source.get("ema200"),
        "ema_alignment": mc.get("ema_alignment") or {},
        "multi_tf": mc.get("multi_tf") or {},
        "adx": (mc.get("trend_strength") or {}).get("adx") or source.get("adx"),
        "delta": source.get("delta"),
        "imbalance": source.get("imbalance"),
        "volume_ratio": source.get("volume_ratio"),
        "velocity": source.get("velocity"),
        "dist_to_support": source.get("dist_to_support"),
        "dist_to_resistance": source.get("dist_to_resistance"),
        "sr_bias": source.get("sr_bias"),
    }
    derived = {
        "market_structure": mc.get("market_structure") or {},
        "market_structure_shift": upgrade.get("market_structure_shift") or source.get("market_structure_shift"),
        "trend_health_state": upgrade.get("trend_health_state") or source.get("trend_health_state"),
        "micro_structure_confirmed": upgrade.get("micro_structure_confirmed", source.get("micro_structure_confirmed")),
        "higher_low_detected": upgrade.get("higher_low_detected", source.get("higher_low_detected")),
        "lower_high_detected": upgrade.get("lower_high_detected", source.get("lower_high_detected")),
        "reversal_risk_score": upgrade.get("reversal_risk_score", source.get("reversal_risk_score")),
    }
    conflicts = [
        reason for reason in (
            weak_countertrend_conflict(source, "LONG"),
            weak_countertrend_conflict(source, "SHORT"),
        ) if reason and reason != "NO_EXECUTABLE_DIRECTION"
    ]
    rate = funding.get("rate")
    mark, index = funding.get("mark_price"), funding.get("index_price")
    derivatives = {
        "funding_bp_8h": round(float(rate) * 1e4, 4) if rate is not None else None,
        "funding_sign_note": "positive = longs pay shorts",
        "funding_source": funding.get("source"),
        "minutes_to_funding": (
            round((float(funding["next_time"]) - time.time()) / 60.0, 1)
            if funding.get("next_time") else None
        ),
        "basis_bp": (
            round((float(mark) - float(index)) / float(index) * 1e4, 3)
            if mark and index else None
        ),
        "open_interest": funding.get("open_interest"),
    }
    return sanitize_ai_inputs({
        "schema": SHARED_DIRECTION_PROMPT_SCHEMA,
        "as_of_utc": utc_iso(),
        "shared_ai_call_id": source.get("trade_id"),
        "data_quality": source.get("data_quality"),
        "raw": raw,
        "derivatives": derivatives,
        "derived": derived,
        "contraindications": conflicts,
    })


def _fill_replay_3m_stamps(signal=None, context=None) -> dict:
    """Freeze fill-time 3m ATR / Donchian / S-R so offline TPs do not chase ATR."""
    ctx = context or (signal or {}).get("context") or {}
    univ = {}
    if isinstance(ctx, dict):
        univ = ctx.get("cycle_3m_universe") or ctx.get("exhaustion_3m") or {}
        if not isinstance(univ, dict) or not univ:
            if ctx.get("atr14_pct_3m") is not None or ctx.get("donchian_high_3m") is not None:
                univ = ctx
    if not isinstance(univ, dict) or not univ:
        try:
            with state_lock:
                univ = dict(state.get("last_cycle_3m_universe") or {})
        except Exception:
            univ = {}
    sr = {}
    try:
        with state_lock:
            sr = dict(state.get("support_resistance") or {})
    except Exception:
        sr = {}
    atr_pct = univ.get("atr14_pct_3m")
    return {
        "atr14_pct_3m": atr_pct,
        "atr14_3m": univ.get("atr14"),
        "donchian_high_3m": univ.get("donchian_high_3m"),
        "donchian_low_3m": univ.get("donchian_low_3m"),
        "donchian_loc_3m": univ.get("donchian_loc_3m"),
        "bb_width_3m": univ.get("bb_width_3m"),
        "support_price": univ.get("support_price") or sr.get("swing_low") or sr.get("s1"),
        "resistance_price": univ.get("resistance_price") or sr.get("swing_high") or sr.get("r1"),
        "cycle_3m_universe_tag": CYCLE_3M_UNIVERSE_TAG,
        "path_replay_tag": PATH_REPLAY_POLICY_TAG,
    }


