def _collector_cached_candles_1m(limit: int = 2000) -> list:
    """Return a bounded causal candle snapshot without network I/O.

    Collector persistence runs on the scheduled AI owner.  Calling the shared
    REST session from that path can wait behind another HTTP worker and wedge
    the entire three-minute cadence even though the AI request already
    completed.  The dedicated OHLCV worker owns refreshes; collector writes
    consume only its last published in-memory snapshot and truthfully retain a
    partial horizon when the cache has not matured yet.
    """
    requested = max(0, int(limit or 0))
    bucket = _mtf_cache.get("1m") or {}
    cached = bucket.get("candles") or []
    if not cached:
        # latest_candles is a 15m execution cache, not a 1m source. Borrowing
        # it silently corrupts resampled research horizons and indicators.
        # Preserve the missing-data signal; never fetch on this owner path.
        return []
    rows = list(cached)
    return rows[-requested:] if requested else rows


_collector_tape_store_obj = None
_collector_tape_store_lock = threading.Lock()
COLLECTOR_TAPE_REFRESH_MAX_LINES = max(
    1000, int(os.getenv("COLLECTOR_TAPE_REFRESH_MAX_LINES", "40000")),
)
COLLECTOR_TAPE_LIVE_LAG_SEC = 90.0
COLLECTOR_PATH_PRE_SIGNAL_SEC = float(MAX_ENTRY_WINDOW_SEC) + 60.0
COLLECTOR_PATH_POST_SIGNAL_SEC = float(MAX_ENTRY_WINDOW_SEC + MAX_HOLD_PERIOD_SEC) + 120.0


def _collector_tape_store():
    global _collector_tape_store_obj
    with _collector_tape_store_lock:
        if _collector_tape_store_obj is None:
            _collector_tape_store_obj = TapeMinuteBarStore(
                os.path.dirname(os.path.abspath(MICROSTRUCTURE_TAPE_FILE)),
            )
        return _collector_tape_store_obj


def _collector_path_candles_1m(signal_ts: float, *, now: float = None) -> tuple:
    """Maturation path: 1s-tape minute bars first, exchange cache fills gaps.

    Returns ``(candles, path_source)``.  ``path_source.window_state`` tells
    the collector whether the tape could decide the window; a retryable state
    keeps the event pending instead of finalizing an empty path.
    """
    now = time.time() if now is None else float(now)
    start = float(signal_ts) - COLLECTOR_PATH_PRE_SIGNAL_SEC
    end = float(signal_ts) + COLLECTOR_PATH_POST_SIGNAL_SEC
    store = _collector_tape_store()
    tape = store.candles(start, end)
    decide_end = min(end, now - COLLECTOR_TAPE_LIVE_LAG_SEC)
    window_state = store.window_state(start, decide_end)
    merged, counts = merge_path_candles(tape, _collector_cached_candles_1m(limit=2000))
    return merged, {
        "source": TAPE_MINUTE_BAR_SOURCE,
        "fallback": "EXCHANGE_1M_CACHE",
        "window_state": window_state,
        "window_start_ts": start,
        "window_end_ts": end,
        "tape_latest_bucket_ts": store.latest_ts,
        **counts,
        **collector_maturation_lag_fields(end, now=now),
    }


def collector_maturation_lag_fields(window_end_ts: float, *, now: float) -> dict:
    """Honest provenance for rows matured long after their window closed.

    The path is rebuilt from the same retained 1s tape either way; the label
    only records that maturation ran late (e.g. a stalled worker backlog).
    """
    decidable_ts = float(window_end_ts) + float(COLLECTOR_TAPE_LIVE_LAG_SEC)
    lag = round(max(0.0, float(now) - decidable_ts), 1)
    late = lag > COLLECTOR_LATE_MATURATION_SEC
    return {
        "matured_ts": round(float(now), 3),
        "maturation_lag_sec": lag,
        "late_backfill": late,
        "late_backfill_reason": "MATURED_LATE_FROM_RETAINED_TAPE" if late else None,
    }


_entry_grid_anchor_by_call = collections.OrderedDict()
_entry_grid_anchor_lock = threading.Lock()
ENTRY_GRID_ANCHOR_CACHE_MAX = 4096
ENTRY_GRID_ANCHOR_MAX_SKEW_SEC = 900.0


def _resolve_entry_grid_anchor(source: dict, *, signal_ts: float, signal_price: float,
                               direction: str) -> dict:
    """One hypothetical-entry anchor per (shared AI call, direction).

    The first tile of a call that reaches the collector fixes the anchor;
    later tiles reuse it so their 300-child grids are byte-identical and the
    multiverse stream stores the grid once.  The anchor is persisted in each
    pending payload, so restarts never re-anchor a call.
    """
    direction_u = str(direction or "SHORT").upper()
    saved = source.get("entry_grid_anchor") if isinstance(source, dict) else None
    call = str((source or {}).get("shared_ai_call_id") or "").strip()
    if entry_grid_anchor_is_valid(saved) and str(saved.get("direction")) == direction_u:
        if call:
            with _entry_grid_anchor_lock:
                _entry_grid_anchor_by_call.setdefault((call, direction_u), dict(saved))
        return dict(saved)
    if not call:
        return make_entry_grid_anchor(
            shared_ai_call_id=None, signal_ts=signal_ts, signal_price=signal_price,
            direction=direction_u, ttl_sec=float(CONTROL_TTL_SEC),
        )
    key = (call, direction_u)
    with _entry_grid_anchor_lock:
        known = _entry_grid_anchor_by_call.get(key)
        if known and abs(float(known["signal_ts"]) - float(signal_ts)) <= ENTRY_GRID_ANCHOR_MAX_SKEW_SEC:
            _entry_grid_anchor_by_call.move_to_end(key)
            return dict(known)
        raw_call_ts = (source or {}).get("shared_ai_call_ts")
        try:
            call_ts = float(raw_call_ts)
        except (TypeError, ValueError):
            try:
                call_ts = datetime.fromisoformat(str(raw_call_ts).replace("Z", "+00:00")).timestamp()
            except (TypeError, ValueError):
                call_ts = None
        anchor_ts = (
            call_ts if call_ts and abs(call_ts - float(signal_ts)) <= ENTRY_GRID_ANCHOR_MAX_SKEW_SEC
            else float(signal_ts)
        )
        anchor = make_entry_grid_anchor(
            shared_ai_call_id=call, signal_ts=anchor_ts, signal_price=signal_price,
            direction=direction_u, ttl_sec=float(CONTROL_TTL_SEC),
        )
        _entry_grid_anchor_by_call[key] = anchor
        while len(_entry_grid_anchor_by_call) > ENTRY_GRID_ANCHOR_CACHE_MAX:
            _entry_grid_anchor_by_call.popitem(last=False)
        return dict(anchor)


_entry_grid_written_digests = collections.OrderedDict()
ENTRY_GRID_WRITTEN_DIGESTS_MAX = 8192


def _append_order_multiverse_row(record: dict, obs: str) -> None:
    """Write the call grid once to the sidecar, then the tile row with a ref."""
    compact = dict(record)
    compact["event"] = obs
    compact["lifecycle"] = obs
    row, grid = split_entry_grid(compact)
    if grid is not None:
        digest = grid["grid_sha256"]
        if digest not in _entry_grid_written_digests:
            if not _safe_append_jsonl(ORDER_MULTIVERSE_ENTRY_GRID_FILE, grid, label="ORDER_MULTIVERSE_GRID"):
                # Never publish a reference without its grid.
                row = compact
            else:
                _entry_grid_written_digests[digest] = True
                while len(_entry_grid_written_digests) > ENTRY_GRID_WRITTEN_DIGESTS_MAX:
                    _entry_grid_written_digests.popitem(last=False)
    _safe_append_jsonl(ORDER_MULTIVERSE_FILE, row, label="ORDER_MULTIVERSE")


COLLECTION_HEALTH_WINDOW_SEC = 3600.0
COLLECTION_EMPTY_PATH_ALARM_RATE = 0.20
COLLECTION_EMPTY_PATH_ALARM_MIN_ROWS = 5
COLLECTION_TOUCH_GRID_ALARM_COVERAGE = 0.90
COLLECTION_TOUCH_GRID_ALARM_MIN_CALLS = 3
_collection_stats_lock = threading.Lock()
_collection_counters = collections.Counter()
_collection_multiverse_recent = deque(maxlen=4096)
_collection_touch_grid_recent = deque(maxlen=2048)


def _collector_collection_stat(name: str, amount: int = 1) -> None:
    with _collection_stats_lock:
        _collection_counters[name] += int(amount)


def _collector_record_multiverse_write(record: dict, obs: str) -> None:
    tape = record.get("canonical_tape") if isinstance(record.get("canonical_tape"), dict) else {}
    coverage = tape.get("coverage") if isinstance(tape.get("coverage"), dict) else {}
    never_recorded = coverage.get("reason") == "PATH_SOURCE_NEVER_RECORDED"
    empty = not tape.get("path_1m")
    path_source = tape.get("path_source") if isinstance(tape.get("path_source"), dict) else {}
    late = bool(path_source.get("late_backfill"))
    with _collection_stats_lock:
        _collection_counters["multiverse_written"] += 1
        _collection_counters[f"multiverse_obs_{obs or 'UNKNOWN'}"] += 1
        if late:
            _collection_counters["multiverse_written_late_backfill"] += 1
        if never_recorded:
            # Pre-tape backlog finalized as DATA_ERROR; not a live-path defect.
            _collection_counters["multiverse_written_source_never_recorded"] += 1
            return
        if empty:
            _collection_counters["multiverse_written_empty_path"] += 1
        _collection_multiverse_recent.append((time.time(), bool(empty), str(obs or ""), late))


def _collector_record_touch_grid_call(*, armed: bool, ai_executes: bool) -> None:
    with _collection_stats_lock:
        _collection_counters["touch_grid_eligible_calls"] += 1
        if armed:
            _collection_counters["touch_grid_armed_calls"] += 1
            if not ai_executes:
                _collection_counters["touch_grid_armed_ai_rejected_calls"] += 1
        _collection_touch_grid_recent.append((time.time(), bool(armed), bool(ai_executes)))


def research_collection_health(now: float = None) -> dict:
    """Lock-light multiverse/touch-grid collection health for /health and status."""
    now = time.time() if now is None else float(now)
    floor = now - COLLECTION_HEALTH_WINDOW_SEC
    with _collection_stats_lock:
        counters = dict(_collection_counters)
        recent = [row for row in _collection_multiverse_recent if row[0] >= floor]
        grid_recent = [row for row in _collection_touch_grid_recent if row[0] >= floor]
    written_1h = len(recent)
    empty_1h = sum(1 for row in recent if row[1])
    insufficient_1h = sum(1 for row in recent if row[2] == "INSUFFICIENT_PATH")
    late_1h = sum(1 for row in recent if len(row) > 3 and row[3])
    empty_rate = (empty_1h / written_1h) if written_1h else None
    eligible_1h = len(grid_recent)
    armed_1h = sum(1 for row in grid_recent if row[1])
    coverage = (armed_1h / eligible_1h) if eligible_1h else None
    store = _collector_tape_store_obj
    tape = store.status(now) if store is not None else {"initial_scan_complete": False}
    pending = len(_order_multiverse_pending_src)
    alarms = []
    if written_1h >= COLLECTION_EMPTY_PATH_ALARM_MIN_ROWS and empty_rate is not None \
            and empty_rate > COLLECTION_EMPTY_PATH_ALARM_RATE:
        alarms.append("MULTIVERSE_EMPTY_PATH_RATE_HIGH")
    tape_age = tape.get("latest_bucket_age_sec")
    refreshed = tape.get("last_refresh_ts")
    refresh_age = None if not refreshed else round(max(0.0, now - float(refreshed)), 1)
    tape = dict(tape, last_refresh_age_sec=refresh_age)
    # Only a freshly re-read index proves the tape itself is stale; an old
    # index means its owner is not refreshing it (worker stall, below).
    if (
        pending and tape.get("initial_scan_complete")
        and refresh_age is not None and refresh_age <= COLLECTOR_TAPE_REFRESH_FRESH_SEC
        and (tape_age is None or tape_age > 300)
    ):
        alarms.append("MULTIVERSE_TAPE_SOURCE_UNAVAILABLE")
    worker = _collector_maturation_worker_status
    last_pass = worker.get("last_pass_ts") or worker.get("started_ts")
    if pending and (not worker.get("alive") or (last_pass and now - float(last_pass) > 300)):
        alarms.append("COLLECTOR_MATURATION_WORKER_STALLED")
    oldest_overdue = float(worker.get("last_oldest_overdue_ts") or 0)
    oldest_overdue_age = (
        round(max(0.0, now - oldest_overdue), 1) if pending and oldest_overdue else None
    )
    if oldest_overdue_age is not None \
            and oldest_overdue_age > COLLECTOR_FINALIZABLE_BACKLOG_ALARM_SEC:
        alarms.append("COLLECTOR_MATURATION_FINALIZABLE_BACKLOG")
    for status in (worker, _collector_v3_reconcile_status):
        restarted = float(status.get("last_restart_ts") or 0)
        if restarted and now - restarted <= COLLECTOR_WORKER_RESTART_ALARM_SEC:
            alarms.append("COLLECTOR_MATURATION_WORKER_RESTARTED")
            break
    if eligible_1h >= COLLECTION_TOUCH_GRID_ALARM_MIN_CALLS and coverage is not None \
            and coverage < COLLECTION_TOUCH_GRID_ALARM_COVERAGE:
        alarms.append("TOUCH_GRID_COVERAGE_LOW")
    runtime_failures = {}
    try:
        # A deliberately disabled relay (RELAY_STACK_MODE=research_only) cannot
        # drain its outbox; its stale-owner state is INFO on /health, not ALARM.
        if not globals().get("RELAY_STACK_RESEARCH_ONLY", False) and _relay_delivery_guard.stale_owner_alarm(now):
            alarms.append("RELAY_OUTBOX_STALE_OWNER_PENDING")
    except Exception as exc:
        runtime_failures["relay_guard_error"] = type(exc).__name__
    if globals().get("_collector_v22_seal_degraded"):
        alarms.append("COLLECTOR_V22_SEAL_DEGRADED")
        runtime_failures["collector_v22_seal_degraded"] = dict(_collector_v22_seal_degraded)
    try:
        # Windowed so a single past failure does not latch the alarm until restart.
        ledger_recent = _LEDGER_WRITES.recent_failure_keys(COLLECTION_HEALTH_WINDOW_SEC, now)
        # Hooks whose function is absent from execution_funnel are reported, not
        # alarmed: they have never recorded, so alarming would latch permanently.
        missing_hook = ("ImportError: cannot import name",)
        funnel_recent = _FUNNEL_HOOK_FAILURES.recent_failure_keys(
            COLLECTION_HEALTH_WINDOW_SEC, now, exclude_error_prefixes=missing_hook,
        )
        runtime_failures.update({
            "ledger_write_failures_recent": ledger_recent,
            "ledger_write_failures_total": _LEDGER_WRITES.failures_total(),
            "execution_funnel_hook_failures_recent": funnel_recent,
            "execution_funnel_hook_failures_total": _FUNNEL_HOOK_FAILURES.failures_total(),
            "execution_funnel_hooks_unavailable": _FUNNEL_HOOK_FAILURES.keys_with_error_prefix(missing_hook),
        })
        if ledger_recent:
            alarms.append("LEDGER_WRITE_FAILURES")
        if funnel_recent:
            alarms.append("EXECUTION_FUNNEL_HOOK_FAILURES")
    except Exception as exc:
        runtime_failures["failure_counter_error"] = type(exc).__name__
    return {
        "schema": "research_collection_health_v1",
        "runtime_failures": runtime_failures,
        "window_sec": COLLECTION_HEALTH_WINDOW_SEC,
        "status": "ALARM" if alarms else "OK",
        "alarms": alarms,
        "multiverse": {
            "pending": pending,
            "overdue": worker.get("last_overdue"),
            "oldest_overdue_age_sec": oldest_overdue_age,
            "overdue_alarm_sec": COLLECTOR_FINALIZABLE_BACKLOG_ALARM_SEC,
            "written_since_boot": counters.get("multiverse_written", 0),
            "written_empty_path_since_boot": counters.get("multiverse_written_empty_path", 0),
            "written_source_never_recorded_since_boot": counters.get(
                "multiverse_written_source_never_recorded", 0,
            ),
            "source_unavailable_retries_since_boot": counters.get("source_unavailable_retries", 0),
            "rejected_written_since_boot": counters.get("rejected_opportunity_written", 0),
            "superseded_rejected_provisionals_since_boot": counters.get(
                "superseded_rejected_provisionals", 0,
            ),
            "written_1h": written_1h,
            "empty_path_1h": empty_1h,
            "insufficient_path_1h": insufficient_1h,
            "empty_path_rate_1h": None if empty_rate is None else round(empty_rate, 4),
            "empty_path_alarm_rate": COLLECTION_EMPTY_PATH_ALARM_RATE,
            "maturation_worker": dict(_collector_maturation_worker_status),
            "v3_reconcile_worker": dict(_collector_v3_reconcile_status),
            "late_backfill_written_since_boot": counters.get("multiverse_written_late_backfill", 0),
            "late_backfill_1h": late_1h,
            "late_maturation_threshold_sec": COLLECTOR_LATE_MATURATION_SEC,
        },
        "touch_grid": {
            "eligible_calls_since_boot": counters.get("touch_grid_eligible_calls", 0),
            "armed_calls_since_boot": counters.get("touch_grid_armed_calls", 0),
            "armed_ai_rejected_calls_since_boot": counters.get("touch_grid_armed_ai_rejected_calls", 0),
            "eligible_calls_1h": eligible_1h,
            "armed_calls_1h": armed_1h,
            "coverage_1h": None if coverage is None else round(coverage, 4),
            "coverage_alarm_floor": COLLECTION_TOUCH_GRID_ALARM_COVERAGE,
        },
        "tape_source": tape,
    }


def _collector_epoch_serialized(fn):
    """Serialize collector writes with the official fresh-epoch boundary."""
    @functools.wraps(fn)
    def wrapped(*args, **kwargs):
        with _collector_epoch_lock:
            return fn(*args, **kwargs)
    return wrapped


def _execution_trade_is_terminal(trade_id: str) -> bool:
    """Return execution truth without consulting provisional collector state.

    Collector maturation can race a paper close.  Once execution has recorded
    a terminal trade, an older rejection/provisional reference must never
    downgrade it back to WAITING_ENTRY_WINDOW.
    """
    tid = str(trade_id or "")
    if not tid:
        return False
    if tid in _execution_terminal_trade_ids:
        return True
    # Do not acquire trade_lock from the collector serialization lock: close
    # commits can take the inverse path.  CPython list/dict reference snapshots
    # are sufficient here because this is a monotonic terminal predicate.
    master = (trades_map.get(tid) or {}).get("signal_ref") or {}
    terminal = bool(isinstance(master, dict) and is_terminal_signal(master))
    if not terminal:
        terminal = any(
            isinstance(row, dict) and str(row.get("trade_id") or "") == tid
            for row in list(trades)
        )
    if terminal:
        _execution_terminal_trade_ids.add(tid)
    return terminal
# v2.2: dense 1s path_replay off Fly volume by default (~309 KB/filled event saved).
COLLECTOR_V22_PATH_REPLAY_1S = os.getenv("COLLECTOR_V22_PATH_REPLAY_1S", "").strip().lower() in ("1", "true", "yes")


def _collector_feature_snapshot(source, *, signal_ts):
    """Freeze causal signal-time features; never rebuild them at maturation."""
    src = source if isinstance(source, dict) else {}
    existing = src.get("research_feature_snapshot")
    if isinstance(existing, dict) and existing:
        return dict(existing)
    with state_lock:
        cycle = dict(state.get("last_cycle_3m_universe") or {})
        market_context = dict(state.get("market_context") or {})
    selected = {}
    for key in (
        "entry_features", "ai_input_upgrade", "market_context", "funding", "order_book",
        "edge_score", "edge_score_at_entry", "session_bucket", "regime", "entry_regime",
        "shared_ai_call_id", "raw_direction", "executed_direction", "final_direction",
    ):
        value = src.get(key)
        if value is not None:
            selected[key] = value
    return {
        "schema": "research_feature_snapshot_v1",
        "captured_for_signal_ts": float(signal_ts),
        "cycle_3m_universe": cycle,
        "market_context": selected.get("market_context") or market_context,
        "source_features": selected,
        "point_in_time": True,
        "maturation_rebuild_forbidden": True,
    }


def _merge_collector_v22_provisionals(*, reason: str) -> int:
    """Self-heal from the journal without monopolising the epoch lock."""
    epoch_id = _collector_v22_epoch_id()
    restored = 0
    for event_id, source in load_provisional_events(
        epoch_id=epoch_id, data_dir=str(_data_sync_runtime_root()),
    ).items():
        # A fresh-epoch boundary invalidates the loaded snapshot.  Check it at
        # each short mutation boundary instead of holding the epoch lock while
        # reading and validating the whole durable journal.
        with _collector_epoch_lock:
            if _collector_v22_epoch_id() != epoch_id:
                return restored
        if event_already_written(event_id, data_dir=str(_data_sync_runtime_root())):
            # Reconcile a crash after final commit but before journal cleanup.
            with _collector_epoch_lock:
                if _collector_v22_epoch_id() != epoch_id:
                    return restored
                remove_provisional_event(event_id, data_dir=str(_data_sync_runtime_root()))
                _order_multiverse_written.add(event_id)
            continue
        with _collector_epoch_lock:
            if event_id in _order_multiverse_pending_src:
                continue
            recovered = dict(source)
            recovered["trade_id"] = event_id
            _order_multiverse_pending_src[event_id] = recovered
            _order_multiverse_state[event_id] = str(
                recovered.get("observation_status") or "RESTORED_PROVISIONAL"
            )
            restored += 1
        time.sleep(0)
    if restored:
        logger.info(
            f"[COLLECTOR_V22] recovered provisional_events={restored} epoch_id={epoch_id} "
            f"reason={reason} "
            f"[PIPELINE ENFORCEMENT]"
        )
    return restored


def _merge_collector_v22_provisionals_guarded(*, reason: str) -> int:
    """Merge, but degrade (never crash) on an invalid legacy v22 seal index.

    Only V22_SEAL_* integrity errors are absorbed. The provisional journal and
    the seal receipts are left untouched for the guarded offline repair
    (workflow ``repair-v22-seals-offline-*``); a later successful merge clears
    the degraded state. Any other error still propagates.
    """
    global _collector_v22_seal_degraded
    try:
        restored = _merge_collector_v22_provisionals(reason=reason)
    except RuntimeError as exc:
        if not str(exc).startswith("V22_SEAL_"):
            raise
        now = time.time()
        previous = _collector_v22_seal_degraded or {}
        _collector_v22_seal_degraded = {
            "error": str(exc)[:200],
            "reason": reason,
            "since_ts": previous.get("since_ts") or now,
            "last_ts": now,
            "occurrences": int(previous.get("occurrences") or 0) + 1,
            "repair": "repair-v22-seals-offline-plan, then -execute",
        }
        logger.critical(
            f"[COLLECTOR_V22] seal index invalid ({exc}); provisional merge skipped, "
            f"journal kept, bot continues degraded reason={reason} [PIPELINE ENFORCEMENT]"
        )
        return 0
    if _collector_v22_seal_degraded:
        logger.info("[COLLECTOR_V22] seal index valid again; degraded state cleared [PIPELINE ENFORCEMENT]")
        _collector_v22_seal_degraded = {}
    return restored


def _schedule_collector_v22_provisional_merge(*, reason: str, now: float) -> bool:
    """Run periodic durable reconciliation on a low-priority daemon."""
    global _collector_v22_merge_inflight, _collector_v22_last_merge
    with _collector_v22_merge_guard:
        if _collector_v22_merge_inflight:
            return False
        _collector_v22_merge_inflight = True
        _collector_v22_last_merge = float(now)

    def worker():
        global _collector_v22_merge_inflight, _collector_v22_last_merge
        try:
            _merge_collector_v22_provisionals_guarded(reason=reason)
            compact = globals().get("_compact_evidence_handoff_journals")
            if callable(compact):
                compact()  # cheap stat unless >=16 MiB or 24 h since the last compaction
        finally:
            with _collector_v22_merge_guard:
                _collector_v22_last_merge = time.time()
                _collector_v22_merge_inflight = False

    threading.Thread(
        target=worker,
        name="collector-v22-provisional-merge",
        daemon=True,
    ).start()
    return True


def _restore_collector_v22_provisionals() -> int:
    """Startup recovery; bounded polls repeat this merge as a safety net."""
    global _collector_v22_last_merge
    restored = (globals().get("_merge_collector_v22_provisionals_guarded")
                or (lambda reason: _merge_collector_v22_provisionals()))(reason="STARTUP")
    _collector_v22_last_merge = time.time()
    compact = globals().get("_compact_evidence_handoff_journals")
    if callable(compact):
        # Before replay: a multi-GB journal made every boot re-read history.
        compact()
    preentry_replay = globals().get("_replay_preentry_evidence_handoffs")
    if callable(preentry_replay):
        preentry_replay()
    replay = globals().get("_replay_cancellation_evidence_handoffs")
    if callable(replay):
        replay()
    fill_replay = globals().get("_replay_fill_evidence_handoffs")
    if callable(fill_replay):
        fill_replay()
    return restored


def _collector_v22_epoch_id() -> str:
    """The bound collection epoch; binds one durably if the session is unbound.

    Never returns a per-process alias: any id handed to a collector is first
    persisted to research_session.json, so every identity observes it.
    """
    bound = _bound_collection_epoch_id()
    if bound:
        return bound
    return _ensure_collector_v22_epoch()


def _collector_source_in_current_epoch(source: dict) -> bool:
    """Reject an old causal source that races a completed fresh reset."""
    if not isinstance(source, dict):
        return False
    cutoff = (_load_research_session_meta() or {}).get("fresh_collection_start_time")
    if cutoff in (None, "", 0, 0.0):
        return True
    raw = (
        source.get("created_ts_ts")
        or source.get("created_ts")
        or source.get("signal_ts")
        or source.get("snapshot_ts")
    )
    try:
        return float(raw) >= float(cutoff)
    except (TypeError, ValueError):
        try:
            parsed = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
            return parsed.timestamp() >= float(cutoff)
        except (TypeError, ValueError):
            return False


def _reset_collector_epoch_state(reset_anchor: float) -> str:
    """Bind and atomically clear V2/V3 recovery state for a fresh epoch."""
    global _order_multiverse_last_poll, _compressed_shadow_recovery_attempted
    global _collector_v22_last_merge, _order_multiverse_maturation_cursor
    global _order_multiverse_ready_sweep_batch, _order_multiverse_ready_sweep_started_ts
    with state_lock:
        state["fresh_collection_mode"] = True
    _write_research_session(float(reset_anchor), fresh_collection_reset=True)
    fresh_epoch_id = _collector_v22_epoch_id()
    with _collector_epoch_lock:
        reset_provisional_events(epoch_id=fresh_epoch_id)
        with replay_lock:
            replay_buffers.clear()
        with _cycle_3m_bucket_lock:
            _cycle_3m_written_buckets.clear()
            _cycle_3m_inflight_buckets.clear()
        _touch_grid_book.clear()
        with _compressed_shadow_lock:
            _compressed_shadow_chase_book.clear()
            _compressed_shadow_seen_call_ids.clear()
            _compressed_shadow_recovery_attempted = True
        _discovery_touch_grid_seen_call_ids.clear()
        _order_multiverse_state.clear()
        _order_multiverse_pending_src.clear()
        _order_multiverse_path_complete.clear()
        _order_multiverse_post_ttl_done.clear()
        _order_multiverse_written.clear()
        # The grid sidecar is wiped with the epoch; a remembered digest would
        # publish a reference to a grid that no longer exists.
        _entry_grid_written_digests.clear()
        with _entry_grid_anchor_lock:
            _entry_grid_anchor_by_call.clear()
        _order_multiverse_last_poll = 0.0
        _collector_v22_last_merge = 0.0
        _order_multiverse_maturation_cursor = 0
        _order_multiverse_ready_sweep_batch = 0
        _order_multiverse_ready_sweep_started_ts = 0.0
    return fresh_epoch_id


def _ensure_collector_v22_epoch() -> str:
    """Durably bind an epoch-v22-* when research_session.json has none.

    An explicit Fresh Collection reset remains the only way to replace a bound
    epoch.  A write failure raises instead of returning an unpersisted id.
    """
    with _collection_epoch_bind_lock:
        meta = dict(_load_research_session_meta() or {})
        bound = str(meta.get("collector_v22_epoch_id") or "").strip()
        if bound:
            return bound
        try:
            anchor = float(meta.get("collector_v22_epoch_ts") or 0.0)
        except (TypeError, ValueError):
            anchor = 0.0
        if anchor <= 0:
            anchor = time.time()
        material = f"collector_v22_epoch|{COLLECTOR_V22_VERSION}|{anchor:.6f}"
        epoch_id = "epoch-v22-" + hashlib.sha256(material.encode("utf-8")).hexdigest()[:20]
        meta["collector_v22_epoch_ts"] = anchor
        meta["collector_v22_epoch_id"] = epoch_id
        meta["collector_version"] = COLLECTOR_V31_VERSION
        meta["legacy_collector_version"] = COLLECTOR_V22_VERSION
        try:
            _write_research_session_payload(meta)
        except OSError as exc:
            logger.error(f"[COLLECTOR_V22] epoch bind failed: {exc} [PIPELINE ENFORCEMENT]")
            raise CollectionEpochUnbound(f"bind write failed: {exc}") from exc
    logger.warning(f"[COLLECTOR_V22] bound collection epoch {epoch_id} [PIPELINE ENFORCEMENT]")
    _refresh_collection_epoch_identity_cache()
    return epoch_id


def _arm_chase_offset_touch_grid(signal: dict):
    """Paper path-touch grid at 0.01–0.30%. Does not change live 0.1% orig."""
    if not isinstance(signal, dict):
        return
    if is_patient_chase_lane(signal.get("research_lane")):
        # Family tiles keep their exact paper anchors. Discovery grid is armed
        # once per shared AI call via `_arm_shared_discovery_touch_grid`.
        return
    try:
        price = float(
            signal.get("signal_price_at_approve")
            or signal.get("signal_price")
            or signal.get("price")
            or 0
        )
        if price <= 0:
            return
        tid = str(signal.get("trade_id") or "")
        if not tid:
            return
        direction = signal.get("final_direction") or signal.get("direction") or "SHORT"
        ts = float(signal.get("created_ts_ts") or signal.get("snapshot_ts") or time.time())
        ttl = float(signal.get("expires_ts") or 0)
        ttl_sec = max(60.0, ttl - ts) if ttl > ts else 1800.0
        rows = arm_touch_grid_rows(
            trade_id=tid,
            direction=direction,
            signal_price=price,
            signal_ts=ts,
            ttl_sec=ttl_sec,
            live_offset_pct=DETERMINISTIC_ENTRY_OFFSET_PCT * 100.0,
            invert_on=_coerce_invert_on(signal),
        )
        for row in rows:
            _safe_append_jsonl(CHASE_OFFSET_TOUCH_GRID_FILE, row, label="TOUCH_GRID")
        _touch_grid_book[tid] = new_grid_state(rows)
        logger.info(
            f"[TOUCH GRID] armed trade_id={tid} offsets=0.01-0.30 live_orig="
            f"{DETERMINISTIC_ENTRY_OFFSET_PCT * 100:.2f}% paper_only [PIPELINE ENFORCEMENT]"
        )
    except Exception as exc:
        logger.warning(f"[TOUCH GRID] arm failed: {exc} [PIPELINE ENFORCEMENT]")


def _shadow_stage_direction_revalidation(shadow: dict, now: float) -> tuple[str, str]:
    """Reuse the current fill-time direction semantics without enabling execution."""
    with state_lock:
        latest_ai = copy.deepcopy(state.get("last_ai") or {})
        latest_ai_ts = float(state.get("last_ai_ts") or 0)
        current_context = copy.deepcopy(
            state.get("last_ai_context") or state.get("last_cycle_3m_universe") or {}
        )
    # The shadow mirrors the tile chase cohort, so recheck it under the same
    # admission rule the registry tiles use.
    if any(_lane_uses_score_led_admission(lane) for lane in ACTIVE_TILE_REGISTRY):
        latest_ai = _fill_revalidation_ai_views(latest_ai)["score_led"]
    signal_ts = float(shadow.get("signal_ts") or 0)
    if latest_ai_ts <= signal_ts:
        return "NOT_REVALIDATED", "NO_NEWER_AI_DECISION"
    if now - latest_ai_ts > get_effective_ai_cooldown_sec() + 120:
        return "NOT_REVALIDATED", "LATEST_AI_DECISION_STALE"
    direction = str(shadow.get("direction") or "").upper()
    conflict = weak_countertrend_conflict(current_context, direction)
    if conflict and conflict != "NO_EXECUTABLE_DIRECTION":
        return "INVALID", f"FILL_REVALIDATION_{conflict}"
    current = str(
        latest_ai.get("direction") or latest_ai.get("candidate_direction") or ""
    ).upper()
    decision = str(latest_ai.get("decision") or "").upper()
    if current not in ("LONG", "SHORT") or decision in (
        "REJECT", "SOFT_REJECT", "NO_TRADE", "CONFLICTED",
    ):
        return "INVALID", "FILL_REVALIDATION_NO_TRADE"
    if current != direction:
        return "INVALID", f"FILL_REVALIDATION_REVERSED_{direction}_TO_{current}"
    return "VALID", f"FILL_REVALIDATION_SAME_{direction}"


def _recover_compressed_shadow_chases_once(now: float = None) -> None:
    """Load active and terminal shared-call owners before any new arm."""
    global _compressed_shadow_recovery_attempted
    # This book has its own lock.  Collector maturation can legitimately hold
    # the fresh-epoch serialization lock while rebuilding terminal evidence;
    # making the three-minute AI owner wait behind that work starved the AI
    # cadence and caused a healthy, flat paper process to self-restart.
    with _compressed_shadow_lock:
        if _compressed_shadow_recovery_attempted:
            return
        durable_rows = []
        for candidate in (CHASE_OFFSET_TOUCH_GRID_FILE + ".1", CHASE_OFFSET_TOUCH_GRID_FILE):
            try:
                with open(candidate, "r", encoding="utf-8") as handle:
                    for line in handle:
                        try:
                            row = json.loads(line)
                        except (TypeError, ValueError):
                            continue
                        if row.get("schema") == "compressed_chase_shadow_v1":
                            durable_rows.append(row)
                            call_id = str(row.get("shared_ai_call_id") or "").strip()
                            if call_id:
                                _compressed_shadow_seen_call_ids.add(call_id)
            except OSError:
                continue
        for tid, recovered in recover_compressed_shadow_states(
            durable_rows, now_ts=float(now or time.time()),
        ).items():
            _compressed_shadow_chase_book.setdefault(tid, recovered)
        _compressed_shadow_recovery_attempted = True


def _poll_chase_offset_touch_grid(price: float, bid=None, ask=None, bid_qty=None, ask_qty=None):
    if price is None or float(price) <= 0:
        return
    now = time.time()
    dead = []
    if _touch_grid_book:
        for tid, grid in list(_touch_grid_book.items()):
            try:
                if now > float(grid.get("expires_ts") or 0):
                    dead.append(tid)
                    continue
                for row in poll_grid_state(
                    grid,
                    now_ts=now,
                    last=float(price),
                    high=float(price),
                    low=float(price),
                    bid=None if not bid else float(bid),
                    ask=None if not ask else float(ask),
                    bid_qty=None if not bid_qty else float(bid_qty),
                    ask_qty=None if not ask_qty else float(ask_qty),
                ):
                    _safe_append_jsonl(CHASE_OFFSET_TOUCH_GRID_FILE, row, label="TOUCH_GRID")
            except Exception as exc:
                logger.warning(f"[TOUCH GRID] poll failed trade_id={tid}: {exc} [PIPELINE ENFORCEMENT]")
        for tid in dead:
            _touch_grid_book.pop(tid, None)
    _recover_compressed_shadow_chases_once(now)
    shadow_dead = []
    shadow_rows = []
    with _compressed_shadow_lock:
        for tid, shadow in list(_compressed_shadow_chase_book.items()):
            try:
                revalidation, revalidation_reason = _shadow_stage_direction_revalidation(shadow, now)
                shadow_rows.extend(poll_compressed_shadow_chase(
                    shadow, now_ts=now, last=float(price),
                    bid=None if not bid else float(bid),
                    ask=None if not ask else float(ask), bbo_fresh=bool(bid and ask),
                    direction_revalidation_result=revalidation,
                    direction_revalidation_reason=revalidation_reason,
                ))
                if shadow.get("terminal_emitted"):
                    shadow_dead.append(tid)
            except Exception as exc:
                logger.warning(
                    f"[SHADOW CHASE] poll failed trade_id={tid}: {exc} [PIPELINE ENFORCEMENT]"
                )
        for tid in shadow_dead:
            _compressed_shadow_chase_book.pop(tid, None)
        for tid, tracker in list(_shadow_chase_bucket_book.items()):
            try:
                shadow = _compressed_shadow_chase_book.get(tid) or {}
                seen = shadow.get("seen_stage_indexes") or ()
                shadow_rows.extend(shadow_chase_buckets.observe(
                    tracker, now_ts=now,
                    bid=None if not bid else float(bid),
                    ask=None if not ask else float(ask),
                    last=float(price),
                    stage_index=max(seen) if seen else None,
                    virtual_limit_price=shadow.get("virtual_limit_price"),
                ))
                if tracker.get("closed"):
                    _shadow_chase_bucket_book.pop(tid, None)
            except Exception as exc:
                _shadow_chase_bucket_book.pop(tid, None)
                logger.warning(
                    f"[SHADOW CHASE BUCKET] observe failed trade_id={tid}: {exc} [PIPELINE ENFORCEMENT]"
                )
    # Disk validation, rotation and fsync are deliberately outside the
    # ownership lock so an AI arm is never queued behind research I/O.
    for row in shadow_rows:
        _safe_append_jsonl(CHASE_OFFSET_TOUCH_GRID_FILE, row, label="SHADOW_CHASE")
    _note_shadow_chase_bucket_records(shadow_rows)
    _maybe_complete_pending_order_multiverse()


COLLECTOR_MATURATION_WORKER_INTERVAL_SEC = max(
    5.0, float(os.getenv("COLLECTOR_MATURATION_WORKER_INTERVAL_SEC", "15")),
)
COLLECTOR_MATURATION_WORKER_BUDGET_SEC = max(
    0.5, float(os.getenv("COLLECTOR_MATURATION_WORKER_BUDGET_SEC", "2.5")),
)
COLLECTOR_MATURATION_WORKER_MAX_BATCH = max(
    COLLECTOR_MATURATION_MAX_BATCH_SIZE,
    int(os.getenv("COLLECTOR_MATURATION_WORKER_MAX_BATCH", "400")),
)
COLLECTOR_MATURATION_WORKER_BACKLOG_INTERVAL_SEC = min(
    COLLECTOR_MATURATION_WORKER_INTERVAL_SEC,
    max(2.0, float(os.getenv("COLLECTOR_MATURATION_WORKER_BACKLOG_INTERVAL_SEC", "5"))),
)
COLLECTOR_V3_TERMINAL_RECONCILE_INTERVAL_SEC = max(
    60.0, float(os.getenv("COLLECTOR_V3_TERMINAL_RECONCILE_INTERVAL_SEC", "900")),
)
COLLECTOR_MATURATION_ITEM_YIELD_SEC = 0.01
# A maturation row whose path window became decidable more than this long
# before it was written is labelled a late backfill from the retained tape.
COLLECTOR_LATE_MATURATION_SEC = max(
    600.0, float(os.getenv("COLLECTOR_LATE_MATURATION_SEC", "3600")),
)
COLLECTOR_WORKER_RESTART_ALARM_SEC = 3600.0
COLLECTOR_WORKER_RESTART_MIN_INTERVAL_SEC = 30.0
COLLECTOR_TAPE_REFRESH_FRESH_SEC = 120.0
# A finalizable row older than this means order-multiverse entry-grid
# evidence is accumulating faster than maturation writes it.
COLLECTOR_FINALIZABLE_BACKLOG_ALARM_SEC = max(
    300.0, float(os.getenv("COLLECTOR_FINALIZABLE_BACKLOG_ALARM_SEC", "1800")),
)
COLLECTOR_WAITING_OBSERVATIONS = frozenset({
    OBS_PENDING, OBS_WAITING_120M, OBS_WAITING_ENTRY_WINDOW,
})


def _collector_earliest_finalize_ts(candidate: dict) -> float:
    """Earliest time collector_v22 can return a terminal observation.

    Mirrors ``build_research_event``: no terminal status before the signal's
    entry window closes, nor before a live fill's hold window closes.
    """
    try:
        signal_ts = float(candidate.get("created_ts_ts") or 0)
    except (TypeError, ValueError):
        signal_ts = 0.0
    earliest = signal_ts + float(MAX_ENTRY_WINDOW_SEC) if signal_ts > 0 else 0.0
    try:
        fill_ts = float(candidate.get("live_fill_ts") or 0)
    except (TypeError, ValueError):
        fill_ts = 0.0
    if fill_ts > 0:
        earliest = max(earliest, fill_ts + float(MAX_HOLD_PERIOD_SEC))
    return earliest


def _collector_overdue_finalize_ts(candidate: dict) -> float:
    """Time after which a healthy tape must yield a terminal observation."""
    earliest = _collector_earliest_finalize_ts(candidate)
    try:
        signal_ts = float(candidate.get("created_ts_ts") or 0)
    except (TypeError, ValueError):
        signal_ts = 0.0
    if signal_ts <= 0:
        return earliest
    return max(earliest, signal_ts + float(MAX_ENTRY_WINDOW_SEC + MAX_HOLD_PERIOD_SEC))


_collector_maturation_worker_status = {"alive": False, "restarts": 0}
_collector_v3_reconcile_status = {"alive": False, "restarts": 0, "runs": 0}
_collector_v3_reconcile_cursor: dict = {}
_collector_worker_threads: dict = {}
_collector_worker_threads_lock = threading.Lock()
_order_multiverse_maturation_attempts: dict = {}


def _collector_worker_phase(status: dict, phase: str) -> None:
    status["phase"] = phase
    status["phase_started_ts"] = time.time()


def collector_maturation_worker_loop():
    """Low-priority owner for tape refresh and multiverse maturation.

    Runs off the tick/order thread with a per-pass wall budget and a yield
    between items, so a backlog drain can never starve order handling, the
    AI cadence or the segment shipper.  Exceptions are contained here:
    ``safe_thread`` treats an escaped exception as a trading-thread crash.
    Full-history V2->V3 reconciliation runs on its own thread so it can
    never hold this pass (or the tape index refresh) for minutes.
    """
    status = _collector_maturation_worker_status
    status.update({"alive": True, "started_ts": time.time(), "exit_error": None})
    try:
        store = _collector_tape_store()
        while not shutdown_event.is_set():
            pass_started = time.time()
            try:
                warming = not store.initial_scan_complete
                _collector_worker_phase(status, "TAPE_REFRESH")
                refresh = store.refresh(
                    max_lines=COLLECTOR_TAPE_REFRESH_MAX_LINES * (5 if warming else 1),
                    pause=lambda: time.sleep(COLLECTOR_MATURATION_ITEM_YIELD_SEC),
                )
                status["last_tape_refresh"] = refresh
                # Until the tape family is indexed every window reads as
                # SOURCE_NOT_READY; sweeping then only rewrites the journal.
                if store.initial_scan_complete:
                    _collector_worker_phase(status, "MATURATION")
                    _maybe_complete_pending_order_multiverse(from_worker=True)
                status["last_error"] = None
            except Exception as exc:
                status["last_error"] = f"{type(exc).__name__}: {exc}"
                logger.warning(f"[COLLECTOR_MATURATION] worker pass failed: {exc} [PIPELINE ENFORCEMENT]")
            status["last_pass_ts"] = time.time()
            status["last_pass_sec"] = round(time.time() - pass_started, 3)
            backlog = bool(status.get("last_budget_exhausted"))
            _collector_worker_phase(status, "IDLE")
            shutdown_event.wait(
                COLLECTOR_MATURATION_WORKER_BACKLOG_INTERVAL_SEC if backlog
                else COLLECTOR_MATURATION_WORKER_INTERVAL_SEC
            )
    except BaseException as exc:
        status["exit_error"] = f"{type(exc).__name__}: {exc}"[:300]
        logger.error(
            f"[COLLECTOR_MATURATION] worker exited: {status['exit_error']} [PIPELINE ENFORCEMENT]"
        )
        raise
    finally:
        # The tick-thread fallback resumes if this owner ever exits; the
        # supervisor restarts it and raises COLLECTOR_MATURATION_WORKER_RESTARTED.
        status["alive"] = False
        status["exited_ts"] = time.time()


def _run_v3_terminal_reconcile(now: float = None, *, pause=None) -> None:
    """Incremental V2->V3 terminal reconciliation (one bounded poll)."""
    global _v3_terminal_reconcile_last_v22_size, _v3_terminal_reconcile_last_ts
    now = time.time() if now is None else float(now)
    if now - _v3_terminal_reconcile_last_ts < COLLECTOR_V3_TERMINAL_RECONCILE_INTERVAL_SEC:
        return
    _v3_terminal_reconcile_last_ts = now
    status = _collector_v3_reconcile_status
    try:
        v3_data_dir = os.getcwd()
        v22_size = research_event_generation_stat_signature(v3_data_dir)
        if v22_size == _v3_terminal_reconcile_last_v22_size:
            return
        from research_v3_bridge import reconcile_terminal_v22_into_v3
        epoch_id = _collector_v22_epoch_id()
        started = time.time()
        status.update({"last_started_ts": started})
        _collector_worker_phase(status, "RECONCILING")
        receipt = reconcile_terminal_v22_into_v3(
            data_dir=v3_data_dir,
            epoch_id=epoch_id,
            cursor=_collector_v3_reconcile_cursor,
            row_lock=_collector_epoch_lock,
            still_current=lambda: _collector_v22_epoch_id() == epoch_id,
            pause=pause,
        )
        status.update({
            "runs": int(status.get("runs") or 0) + 1,
            "last_finished_ts": time.time(),
            "last_duration_sec": round(time.time() - started, 3),
            "last_scanned": receipt.get("scanned"),
            "last_skipped_bytes": receipt.get("skipped_bytes"),
            "last_backfilled": receipt.get("backfilled"),
            "last_passed": bool(receipt.get("passed")),
            "last_error": None if receipt.get("passed") else str(receipt.get("errors"))[:300],
        })
        if receipt.get("passed"):
            _v3_terminal_reconcile_last_v22_size = v22_size
            if receipt.get("backfilled"):
                logger.warning(
                    "[COLLECTOR_V3] reconciled terminal V2 rows "
                    f"backfilled={receipt.get('backfilled')} "
                    f"already_present={receipt.get('already_present')}"
                )
        else:
            logger.error(
                "[COLLECTOR_V3] terminal reconciliation failed "
                f"errors={receipt.get('errors')} [PIPELINE ENFORCEMENT]"
            )
    except Exception as exc:
        status["last_error"] = f"{type(exc).__name__}: {exc}"[:300]
        logger.error(
            f"[COLLECTOR_V3] terminal reconciliation error: {exc} "
            "[PIPELINE ENFORCEMENT]"
        )
    finally:
        _collector_worker_phase(status, "IDLE")


def collector_v3_reconcile_loop():
    """Own the V2->V3 terminal reconciliation off the maturation worker."""
    status = _collector_v3_reconcile_status
    status.update({"alive": True, "started_ts": time.time(), "exit_error": None})
    try:
        while not shutdown_event.is_set():
            _run_v3_terminal_reconcile(pause=lambda: time.sleep(COLLECTOR_MATURATION_ITEM_YIELD_SEC))
            status["last_poll_ts"] = time.time()
            shutdown_event.wait(COLLECTOR_MATURATION_WORKER_INTERVAL_SEC)
    except BaseException as exc:
        status["exit_error"] = f"{type(exc).__name__}: {exc}"[:300]
        logger.error(f"[COLLECTOR_V3] reconcile worker exited: {status['exit_error']} [PIPELINE ENFORCEMENT]")
        raise
    finally:
        status["alive"] = False
        status["exited_ts"] = time.time()


_COLLECTOR_WORKERS = {
    "collector-maturation": (collector_maturation_worker_loop, _collector_maturation_worker_status),
    "collector-v3-reconcile": (collector_v3_reconcile_loop, _collector_v3_reconcile_status),
}


def _start_collector_worker(name: str) -> threading.Thread:
    target, _status = _COLLECTOR_WORKERS[name]
    thread = threading.Thread(target=target, name=name, daemon=True)
    with _collector_worker_threads_lock:
        _collector_worker_threads[name] = thread
    thread.start()
    return thread


def supervise_collector_workers(now: float = None) -> list:
    """Restart a dead collector worker; a live-but-blocked one only alarms.

    Python threads cannot be killed, so a blocked owner is surfaced through
    COLLECTOR_MATURATION_WORKER_STALLED (with its phase) instead.
    """
    if shutdown_event.is_set():
        return []
    now = time.time() if now is None else float(now)
    restarted = []
    for name, (_target, status) in _COLLECTOR_WORKERS.items():
        with _collector_worker_threads_lock:
            thread = _collector_worker_threads.get(name)
        if thread is None or thread.is_alive():
            continue
        if now - float(status.get("last_restart_ts") or 0) < COLLECTOR_WORKER_RESTART_MIN_INTERVAL_SEC:
            continue
        status["restarts"] = int(status.get("restarts") or 0) + 1
        status["last_restart_ts"] = now
        status["last_restart_reason"] = status.get("exit_error") or "THREAD_EXITED"
        logger.error(
            f"[COLLECTOR_SUPERVISOR] {name} was dead ({status['last_restart_reason']}); "
            f"restarting (restarts={status['restarts']}) [PIPELINE ENFORCEMENT]"
        )
        _start_collector_worker(name)
        restarted.append(name)
    return restarted


def _maybe_complete_pending_order_multiverse(*, from_worker: bool = False):
    global _order_multiverse_last_poll
    global _collector_v22_last_merge, _order_multiverse_maturation_cursor
    global _order_multiverse_ready_sweep_batch, _order_multiverse_ready_sweep_started_ts
    if not from_worker and _collector_maturation_worker_status.get("alive"):
        return
    now = time.time()
    # The worker paces itself (backlog cadence); only the tick fallback polls.
    if not from_worker and now - _order_multiverse_last_poll < 60.0 - 0.5:
        return
    _order_multiverse_last_poll = now
    # Periodic reconciliation remains complete even when only one in-memory
    # provisional was lost, but it runs outside this price/order worker and
    # takes the epoch lock only for one short map mutation at a time.
    if now - _collector_v22_last_merge >= COLLECTOR_PROVISIONAL_REMERGE_INTERVAL_SEC:
        _schedule_collector_v22_provisional_merge(reason="MATURATION_POLL", now=now)
    pending_snapshot = dict(_order_multiverse_pending_src)
    pending_ids = sorted(pending_snapshot)
    ready_ids = []
    waiting_ids = []
    finalizable_since = {}
    overdue_since = {}
    for pending_id in pending_ids:
        candidate = pending_snapshot.get(pending_id) or {}
        expires = float(candidate.get("expires_ts") or 0)
        closed = str(candidate.get("status") or "").upper() in (
            "CLOSED", "FILLED", "EXPIRED", "CANCELLED", "COMPLETE",
        )
        earliest_final = _collector_earliest_finalize_ts(candidate)
        if (
            (
                closed
                or bool(candidate.get("path_complete"))
                or (expires > 0 and now >= expires + float(POST_TTL_LOOKAHEAD_SEC))
            )
            and now >= earliest_final
        ):
            ready_ids.append(pending_id)
            finalizable_since[pending_id] = earliest_final
            overdue = _collector_overdue_finalize_ts(candidate)
            if now >= overdue:
                overdue_since[pending_id] = overdue
        else:
            waiting_ids.append(pending_id)
    # Mature evidence is processed oldest-first.  The adaptive component keeps
    # a terminal backlog on a bounded sweep trajectory, while the hard cap and
    # per-item lock release prevent a burst from monopolising the AI owner.
    required_ready_batch = math.ceil(
        len(ready_ids) / float(COLLECTOR_MATURATION_TARGET_SWEEP_MIN)
    )
    if not ready_ids:
        _order_multiverse_ready_sweep_batch = 0
        _order_multiverse_ready_sweep_started_ts = 0.0
    else:
        if not _order_multiverse_ready_sweep_started_ts:
            _order_multiverse_ready_sweep_started_ts = now
        _order_multiverse_ready_sweep_batch = max(
            _order_multiverse_ready_sweep_batch,
            COLLECTOR_MATURATION_BATCH_SIZE,
            required_ready_batch,
        )
    count = min(
        COLLECTOR_MATURATION_MAX_BATCH_SIZE,
        max(COLLECTOR_MATURATION_BATCH_SIZE, _order_multiverse_ready_sweep_batch),
    )
    if from_worker:
        # The wall budget, not the item count, bounds a worker pass.
        count = min(COLLECTOR_MATURATION_WORKER_MAX_BATCH, max(count, len(ready_ids) + COLLECTOR_MATURATION_BATCH_SIZE))
    # Fewest attempts first: a mature row that keeps failing to finalize must
    # not hold the head of every pass ahead of rows that would.  Attempts are
    # counted only once a row can finalize; a row still inside its entry/hold
    # window cannot fail, and charging it there starves it behind newer rows.
    attempts = _order_multiverse_maturation_attempts
    for stale_id in [key for key in attempts if key not in pending_snapshot]:
        attempts.pop(stale_id, None)
    ready_ids.sort(
        key=lambda pending_id: (
            attempts.get(pending_id, 0),
            float((pending_snapshot.get(pending_id) or {}).get("expires_ts") or 0),
        )
    )
    selected_ids = ready_ids[:count]
    remaining = count - len(selected_ids)
    if remaining > 0 and waiting_ids:
        start = _order_multiverse_maturation_cursor % len(waiting_ids)
        selected_ids.extend(
            waiting_ids[(start + index) % len(waiting_ids)]
            for index in range(min(remaining, len(waiting_ids)))
        )
        _order_multiverse_maturation_cursor = (
            start + min(remaining, len(waiting_ids))
        ) % len(waiting_ids)
    elif waiting_ids:
        _order_multiverse_maturation_cursor %= len(waiting_ids)
    else:
        _order_multiverse_maturation_cursor = 0
    oldest_created = min(
        (
            float((row or {}).get("created_ts_ts") or 0)
            for row in pending_snapshot.values()
            if float((row or {}).get("created_ts_ts") or 0) > 0
        ),
        default=0.0,
    )
    oldest_overdue = min(overdue_since.values(), default=0.0)
    with state_lock:
        state["collector_maturation"] = {
            "status": "ACTIVE" if pending_ids else "IDLE",
            "pending": len(pending_ids),
            "terminal_ready": len(ready_ids),
            "overdue": len(overdue_since),
            "oldest_overdue_age_sec": (
                max(0.0, now - oldest_overdue) if overdue_since else None
            ),
            "selected": len(selected_ids),
            "base_batch_size": COLLECTOR_MATURATION_BATCH_SIZE,
            "effective_batch_size": count,
            "max_batch_size": COLLECTOR_MATURATION_MAX_BATCH_SIZE,
            "target_sweep_minutes": COLLECTOR_MATURATION_TARGET_SWEEP_MIN,
            "estimated_ready_sweep_minutes": (
                math.ceil(len(ready_ids) / float(max(1, count)))
            ),
            "ready_sweep_started_ts": _order_multiverse_ready_sweep_started_ts or None,
            "target_status": (
                "TARGET_UNACHIEVABLE_MAX_BATCH"
                if len(ready_ids)
                > COLLECTOR_MATURATION_MAX_BATCH_SIZE
                * COLLECTOR_MATURATION_TARGET_SWEEP_MIN
                else "ON_TARGET"
            ),
            "oldest_pending_age_sec": max(0.0, now - oldest_created) if oldest_created else None,
            "last_poll_ts": now,
            "last_journal_merge_ts": _collector_v22_last_merge,
            "owner": "MATURATION_WORKER" if from_worker else "TICK_THREAD",
            "worker_interval_sec": COLLECTOR_MATURATION_WORKER_INTERVAL_SEC if from_worker else None,
            "worker_budget_sec": COLLECTOR_MATURATION_WORKER_BUDGET_SEC if from_worker else None,
        }
    budget_deadline = (
        time.monotonic() + COLLECTOR_MATURATION_WORKER_BUDGET_SEC if from_worker else None
    )
    processed = 0
    for pending_id in selected_ids:
        if budget_deadline is not None and time.monotonic() >= budget_deadline:
            break
        src = _order_multiverse_pending_src.get(pending_id)
        if not isinstance(src, dict):
            continue
        processed += 1
        if pending_id in finalizable_since:
            attempts[pending_id] = attempts.get(pending_id, 0) + 1
        if src.get("collector_rejected"):
            persist_rejected_opportunity(
                src,
                ai=src.get("collector_ai") if isinstance(src.get("collector_ai"), dict) else None,
                reason=str(src.get("collector_reject_reason") or "REJECTED"),
                would_block_only=bool(src.get("collector_would_block_only")),
            )
            time.sleep(COLLECTOR_MATURATION_ITEM_YIELD_SEC if from_worker else 0)
            continue
        expires = float(src.get("expires_ts") or 0)
        ttl_done = expires > 0 and now >= expires
        post_ttl_done = expires > 0 and now >= (expires + float(POST_TTL_LOOKAHEAD_SEC))
        closed = str(src.get("status") or "").upper() in (
            "CLOSED", "FILLED", "EXPIRED", "CANCELLED", "COMPLETE",
        )
        # Keep collecting after TTL so a later 0.10% touch (e.g. t=37m) is
        # labeled alternative_entry_fill without lookahead into the 30m order.
        record = _sync_order_multiverse(
            src,
            path_complete=bool(post_ttl_done or closed or src.get("path_complete")),
        )
        if (
            pending_id in finalizable_since
            and isinstance(record, dict)
            and str(record.get("observation_status") or "") in COLLECTOR_WAITING_OBSERVATIONS
        ):
            # Still legitimately inside its path window: not a failed attempt.
            attempts[pending_id] = max(0, attempts.get(pending_id, 1) - 1)
        time.sleep(COLLECTOR_MATURATION_ITEM_YIELD_SEC if from_worker else 0)
    if from_worker:
        _collector_maturation_worker_status.update({
            "last_selected": len(selected_ids),
            "last_processed": processed,
            "last_terminal_ready": len(ready_ids),
            "last_overdue": len(overdue_since),
            "last_oldest_overdue_ts": oldest_overdue or None,
            "last_budget_exhausted": processed < len(selected_ids),
        })
    # V2 is the durable migration source.  A rollout or crash between the V2
    # append and V3 dual-write must not leave an eternal provisional V3 row.
    # The dedicated reconcile thread owns this; inline is only the fallback
    # while that owner is down (the supervisor restarts it).
    if not _collector_v3_reconcile_status.get("alive"):
        _run_v3_terminal_reconcile(now)


def _collector_frozen_signal_ref(source: dict, trade_id: str):
    """Prefer the original recovery reference; conflicting identities fail closed."""
    previous = _order_multiverse_pending_src.get(trade_id)
    saved = previous.get("research_signal_snapshot_ref") if isinstance(previous, dict) else None
    incoming = source.get("research_signal_snapshot_ref")
    if saved is not None and incoming is not None and saved != incoming:
        raise ValueError("SIGNAL_SNAPSHOT_REFERENCE_CONFLICT")
    return saved if saved is not None else incoming


@_collector_epoch_serialized
def _sync_order_multiverse(source: dict, *, path_complete: bool = False):
    """v2.2: write-once immutable research event per event_id (~210 KB)."""
    if not isinstance(source, dict):
        return None
    preentry_barrier = globals().get("_preentry_evidence_barrier")
    if callable(preentry_barrier):
        preentry_barrier(source)
    if not _collector_source_in_current_epoch(source):
        logger.warning(
            "[COLLECTOR_V22] stale pre-reset source refused during maturation "
            f"trade_id={source.get('trade_id')} epoch_id={_collector_v22_epoch_id()} "
            "[PIPELINE ENFORCEMENT]"
        )
        return None
    if storage_blocks_new_events() and not event_already_written(
        str(source.get("trade_id") or source.get("canonical_trade_id") or ""),
        data_dir=str(_data_sync_runtime_root()),
    ):
        logger.warning("[COLLECTOR_V22] STORAGE_PRESSURE — skipping new research event [PIPELINE ENFORCEMENT]")
        return None
    try:
        tid = paper_multiverse_trade_id(
            source.get("trade_id"),
            source.get("canonical_trade_id"),
            source.get("source_trade_id"),
            source.get("source_order_trade_id"),
        )
        if not tid:
            return None
        if tid in _order_multiverse_written:
            return None
        if _execution_trade_is_terminal(tid):
            # Execution truth wins over a stale rejected/provisional object.
            # Force this pass to mature the existing evidence as terminal;
            # never publish another WAITING_ENTRY_WINDOW for a closed ID.
            source = dict(source)
            source["status"] = "CLOSED"
            source["ticket_closed"] = True
            path_complete = True
        prev = _order_multiverse_state.get(tid)
        if prev in TERMINAL_LIFECYCLES and tid in _order_multiverse_written:
            return None
        price = float(
            source.get("signal_price_at_approve")
            or source.get("signal_price")
            or source.get("price")
            or 0
        )
        if price <= 0:
            return None
        direction = source.get("final_direction") or source.get("signal_dir") or source.get("dir") or "SHORT"
        ts = float(source.get("created_ts_ts") or source.get("created_ts") or source.get("signal_ts") or 0)
        if ts <= 0:
            ts = float(source.get("snapshot_ts") or time.time())
        ttl = float(source.get("expires_ts") or 0)
        ttl_sec = max(60.0, ttl - ts) if ttl > ts else 1800.0
        invert_on = _coerce_invert_on(source)
        feature_snapshot = _collector_feature_snapshot(source, signal_ts=ts)
        live_fill_ts = source.get("live_fill_ts") or source.get("fill_ts") or source.get("entry_ts")
        live_fill_price = (
            source.get("live_fill_price")
            or source.get("fill_price")
            or source.get("entry")
            or source.get("entry_price")
        )
        status_u = str(source.get("status") or source.get("outcome") or "").upper()
        ticket_closed = status_u in (
            "CLOSED", "EXPIRED", "CANCELLED", "COMPLETE", "TTL_EXPIRED", "SIGNAL_TTL_EXPIRED",
        ) or bool(source.get("ticket_closed"))
        if live_fill_ts:
            try:
                live_fill_ts = float(live_fill_ts)
            except (TypeError, ValueError):
                live_fill_ts = None
        if live_fill_price:
            try:
                live_fill_price = float(live_fill_price)
            except (TypeError, ValueError):
                live_fill_price = None
            if live_fill_price is not None and live_fill_price <= 0:
                live_fill_price = None
        candles_1m, path_source = _collector_path_candles_1m(ts)
        grid_anchor = _resolve_entry_grid_anchor(
            source, signal_ts=ts, signal_price=price, direction=direction,
        )
        ticks_1s = []
        replay_complete = bool(path_complete or ticket_closed)
        with replay_lock:
            buf = replay_buffers.get(tid) or {}
            start = float(buf.get("start_ts") or ts)
            if COLLECTOR_V22_PATH_REPLAY_1S:
                for tick in buf.get("ticks") or []:
                    t = float(tick.get("t") or 0)
                    if 0 < t < 1e11:
                        t = start + t
                    ticks_1s.append({
                        "t": t,
                        "price": tick.get("price"),
                        "best_bid": tick.get("best_bid"),
                        "best_ask": tick.get("best_ask"),
                        "unreal_pct": tick.get("unreal_pct"),
                    })
            if buf.get("post_exit") and buf.get("closed"):
                replay_complete = True
            if buf.get("virtual_fill_t") is not None and live_fill_ts is None:
                live_fill_ts = start + float(buf.get("virtual_fill_t") or 0)
                live_fill_price = live_fill_price or buf.get("virtual_entry")
        with state_lock:
            univ = dict(state.get("last_cycle_3m_universe") or {})
        rsi_at_signal = univ.get("rsi14") or univ.get("rsi_3m") or source.get("rsi14")
        would_block = univ.get("would_block_short")
        would_block_reason = univ.get("would_block_reason")
        tree = build_decision_tree_v22(
            reason=source.get("exact_reason"),
            rsi=rsi_at_signal,
            rsi_threshold=30.0,
            adx=univ.get("adx14"),
            atr=univ.get("atr14_pct_3m"),
            would_block=would_block,
            would_block_reason=would_block_reason,
            short_circuit=True,
        )
        record = build_research_event(
            trade_id=tid,
            epoch_id=_collector_v22_epoch_id(),
            signal_price=price,
            signal_ts=ts,
            direction=direction,
            candles_1m=candles_1m,
            ticks_1s=ticks_1s or None,
            live_orig=DETERMINISTIC_ENTRY_OFFSET_PCT * 100.0,
            ttl_sec=ttl_sec,
            live_fill_ts=live_fill_ts,
            live_fill_price=live_fill_price,
            ticket_closed=ticket_closed,
            path_complete=replay_complete,
            submitted=True,
            rejected=False,
            decision_tree=tree,
            rsi_at_signal=rsi_at_signal,
            would_block=would_block,
            would_block_reason=would_block_reason,
            atr14_pct=univ.get("atr14_pct_3m") or source.get("atr14_pct_3m"),
            invert_on=invert_on,
            include_ticks_1s=COLLECTOR_V22_PATH_REPLAY_1S,
            symbol=source.get("symbol") or source.get("pair") or "BTCUSD",
            shared_ai_call_id=source.get("shared_ai_call_id"),
            feature_snapshot=feature_snapshot,
            evaluation_ts=time.time(),
            requested_qty=source.get("qty"),
            market_microstructure_symbol=BITFINEX_WS_SYMBOL,
            signed_quantity_constraints=source.get("signed_quantity_constraints"),
            chase_schedule=source.get("research_chase_schedule") or source.get("chase_schedule"),
            chase_schedule_authoritative=bool(source.get("chase_schedule_authoritative")),
            frozen_signal_snapshot_ref=_collector_frozen_signal_ref(source, tid),
            snapshot_data_dir=str(_data_sync_runtime_root()),
            path_source=path_source,
            entry_grid_anchor=grid_anchor,
        )
        from collector_signal_snapshot import freeze_signal_snapshot
        record["research_signal_snapshot_ref"] = freeze_signal_snapshot(
            record, data_dir=_data_sync_runtime_root(), captured_at=time.time(),
        )
        obs = str(record.get("observation_status") or "")
        keep_collecting = not terminal_observation(obs)
        pending_payload = {
            "trade_id": tid,
            "signal_price_at_approve": price,
            "signal_price": price,
            "created_ts_ts": ts,
            "expires_ts": ts + ttl_sec,
            "final_direction": direction,
            "raw_direction": source.get("raw_direction") or (
                "SHORT" if invert_on and direction == "LONG"
                else "LONG" if invert_on and direction == "SHORT"
                else direction
            ),
            "invert_on": invert_on,
            "live_fill_ts": live_fill_ts,
            "live_fill_price": live_fill_price,
            "status": "CLOSED" if ticket_closed else ("FILLED" if live_fill_ts else "PENDING"),
            "ticket_closed": ticket_closed,
            "path_complete": replay_complete,
            "symbol": source.get("symbol") or source.get("pair") or "BTCUSD",
            "shared_ai_call_id": source.get("shared_ai_call_id"),
            "qty": source.get("qty"),
            "signed_quantity_constraints": copy.deepcopy(source.get("signed_quantity_constraints")),
            "quantity_constraints_status": copy.deepcopy(source.get("quantity_constraints_status")),
            "research_chase_schedule": source.get("research_chase_schedule") or source.get("chase_schedule"),
            "chase_schedule_authoritative": bool(source.get("chase_schedule_authoritative")),
            "research_feature_snapshot": copy.deepcopy(record["feature_snapshot_at_signal"]),
            "research_signal_snapshot_ref": record["research_signal_snapshot_ref"],
            "shared_ai_call_ts": source.get("shared_ai_call_ts"),
            "entry_grid_anchor": grid_anchor,
        }
        if keep_collecting:
            previous_payload = _order_multiverse_pending_src.get(tid)
            _order_multiverse_pending_src[tid] = pending_payload
            _order_multiverse_state[tid] = obs or "PENDING"
            pending_payload["observation_status"] = obs or "PENDING"
            if obs == OBS_SOURCE_UNAVAILABLE:
                _collector_collection_stat("source_unavailable_retries")
            # The journal is one fsynced JSON document; rewriting it for an
            # unchanged payload on every maturation pass is pure I/O.
            if previous_payload != pending_payload:
                upsert_provisional_event(tid, pending_payload, epoch_id=_collector_v22_epoch_id(),
                                         data_dir=str(_data_sync_runtime_root()))
            return record
        _order_multiverse_pending_src.pop(tid, None)
        written, reason = write_research_event_once(record, data_dir=str(_data_sync_runtime_root()))
        if written:
            remove_provisional_event(tid, data_dir=str(_data_sync_runtime_root()))
            _order_multiverse_written.add(tid)
            _append_order_multiverse_row(record, obs)
            _collector_record_multiverse_write(record, obs)
            logger.info(
                f"[COLLECTOR_V22] write-once event_id={tid} obs={obs} bytes~{reason} "
                f"[PIPELINE ENFORCEMENT]"
            )
        _order_multiverse_state[tid] = obs
        _order_multiverse_path_complete[tid] = obs in ("COMPLETE", "PATH_COMPLETE")
        _order_multiverse_post_ttl_done[tid] = obs == "FUNNEL_COMPLETE"
        return record
    except Exception as exc:
        logger.warning(f"[COLLECTOR_V22] sync failed: {exc} [PIPELINE ENFORCEMENT]")
        return None


def _promote_collector_v22_registered_order(order: dict, signal: dict = None):
    """Replace a provisional reject envelope once a real paper order exists.

    Research free-run records can truthfully retain a would-block decision and
    still proceed to a real paper order.  The earlier rejected provisional is
    not authoritative for execution after registration: leaving it in place
    discards the exact order quantity and authoritative chase intervals at
    maturation.  Rebuild through the normal accepted collector path so its
    bounded durable payload remains the single restart source of truth.
    """
    if not isinstance(order, dict):
        return None
    tid = str(order.get("trade_id") or "")
    if not tid or str(order.get("status") or "").upper() != "PENDING":
        return None
    existing = _order_multiverse_pending_src.get(tid)
    source = dict(existing) if isinstance(existing, dict) else {}
    original_rejected = bool(source.get("collector_rejected"))
    original_reason = source.get("collector_reject_reason")
    if isinstance(signal, dict):
        for key, value in signal.items():
            source.setdefault(key, value)
    source.update(order)
    source["trade_id"] = tid
    source["status"] = "PENDING"
    source["collector_rejected"] = False
    source.pop("collector_ai", None)
    source.pop("collector_reject_reason", None)
    source.pop("collector_would_block_only", None)
    if original_rejected:
        source["collector_original_would_block"] = True
        source["collector_original_would_block_reason"] = original_reason
    result = _sync_order_multiverse(source, path_complete=False)
    logger.info(
        f"[COLLECTOR_V22] registered paper order promoted provisional "
        f"trade_id={tid} qty={order.get('qty')} "
        f"schedule_authoritative={bool(order.get('chase_schedule_authoritative'))} "
        f"[PIPELINE ENFORCEMENT]"
    )
    return result


def _terminal_schedule_receipt_durable(receipt: dict) -> bool:
    """Return true only for a canonical terminal append or exact duplicate."""
    if not isinstance(receipt, dict):
        return False
    write = receipt.get("write")
    if not isinstance(write, dict):
        return False
    if write.get("blocked") is True or write.get("deferred") is True:
        return False
    return bool(write.get("written") is True or write.get("duplicate") is True)


@_collector_epoch_serialized
def _refresh_collector_v22_registered_order_evidence(
    order: dict, signal: dict = None, *, lifecycle_final: bool = False,
    expected_epoch_id: str = None, require_terminal_receipt: bool = False,
):
    """Persist the latest authoritative order schedule after every mutation."""
    if expected_epoch_id is not None and _collector_v22_epoch_id() != str(expected_epoch_id):
        return False
    if not isinstance(order, dict):
        return False
    preentry_barrier = globals().get("_preentry_evidence_barrier")
    if callable(preentry_barrier):
        preentry_barrier(order, signal)
    tid = str(order.get("trade_id") or "")
    source = _order_multiverse_pending_src.get(tid)
    if not tid or not isinstance(source, dict) or source.get("collector_rejected"):
        return False
    schedule = order.get("research_chase_schedule")
    if schedule is None and isinstance(signal, dict):
        schedule = signal.get("research_chase_schedule")
    signal_authoritative = bool(
        signal.get("chase_schedule_authoritative") if isinstance(signal, dict) else False
    )
    if not isinstance(schedule, dict) or not bool(
        order.get("chase_schedule_authoritative") or signal_authoritative
    ):
        return False
    refreshed = dict(source)
    refreshed["qty"] = order.get("qty", refreshed.get("qty"))
    refreshed["signed_quantity_constraints"] = copy.deepcopy(
        order.get("signed_quantity_constraints", refreshed.get("signed_quantity_constraints"))
    )
    refreshed["quantity_constraints_status"] = copy.deepcopy(
        order.get("quantity_constraints_status", refreshed.get("quantity_constraints_status"))
    )
    refreshed["status"] = order.get("status", refreshed.get("status"))
    refreshed["limit_price"] = order.get("limit_price", refreshed.get("limit_price"))
    refreshed["limit_chase_count"] = order.get(
        "limit_chase_count", refreshed.get("limit_chase_count")
    )
    refreshed["last_chase_ts"] = order.get("last_chase_ts", refreshed.get("last_chase_ts"))
    refreshed["fill_ts"] = order.get("fill_ts", refreshed.get("fill_ts"))
    refreshed["fill_price"] = order.get("fill_price", refreshed.get("fill_price"))
    if isinstance(order.get("fill_time_revalidation"), dict):
        refreshed["fill_time_revalidation"] = copy.deepcopy(order["fill_time_revalidation"])
    refreshed["research_chase_schedule"] = copy.deepcopy(schedule)
    refreshed["chase_schedule_authoritative"] = True
    _order_multiverse_pending_src[tid] = refreshed
    upsert_provisional_event(tid, refreshed, epoch_id=_collector_v22_epoch_id(),
                             data_dir=str(_data_sync_runtime_root()))
    # V3 submit receipts are immutable. Once the existing recorder closes the
    # schedule, append its final exact version for conservative replay. This is
    # evidence-only and cannot affect order execution.
    terminal_fields_present = bool(
        schedule.get("terminal_ts") is not None and schedule.get("terminal_reason")
    )
    if lifecycle_final is True and require_terminal_receipt and not terminal_fields_present:
        return False
    if lifecycle_final is True and terminal_fields_present:
        try:
            terminal_receipt = dual_write_terminal_paper_schedule(
                order,
                signal if isinstance(signal, dict) else {},
                epoch_id=_collector_v22_epoch_id(), data_dir=os.getcwd(),
                lifecycle_final=True,
            )
            if require_terminal_receipt and not _terminal_schedule_receipt_durable(terminal_receipt):
                return False
        except Exception as exc:
            # Evidence capture is deliberately fail-isolated: an absent causal
            # owner remains UNKNOWN and must never interrupt a fill/cancel.
            logger.warning(
                f"[COLLECTOR_V3] terminal schedule evidence unavailable: {exc} "
                "[EVIDENCE ONLY]"
            )
            if require_terminal_receipt:
                return False
    return True


def _cancellation_evidence_handoff_path() -> str:
    return os.path.join(
        str(_data_sync_runtime_root()), "cancellation_evidence_handoffs.jsonl"
    )


def _append_cancellation_evidence_handoff(row: dict) -> bool:
    """Append a tiny handoff record without shared research-gate locks/rotation.

    This journal is deliberately separate from the general JSONL writer: the
    cancellation caller must not wait behind collector validation, rotation, or
    the research write barrier.  The append is serialized only against other
    handoff rows and is fsynced before the bounded evidence worker is notified.
    """
    return _append_durable_handoff_row(
        _cancellation_evidence_handoff_path(), row,
        _cancellation_evidence_handoff_lock, "cancellation",
    )


def _append_durable_handoff_row(path: str, row: dict, lock, label: str) -> bool:
    encoded = json.dumps(row, default=str, separators=(",", ":")).encode("utf-8") + b"\n"
    try:
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        with lock:
            # A process crash can leave an incomplete final JSONL row.  Fence
            # the next append with a newline so the partial forensic bytes stay
            # isolated and the new durable receipt remains independently
            # replayable.  Never rewrite or discard the torn bytes here.
            fence = b""
            try:
                probe_fd = os.open(path, os.O_RDONLY)
            except FileNotFoundError:
                probe_fd = None
            if probe_fd is not None:
                try:
                    if os.lseek(probe_fd, 0, os.SEEK_END) > 0:
                        os.lseek(probe_fd, -1, os.SEEK_END)
                        if os.read(probe_fd, 1) != b"\n":
                            fence = b"\n"
                finally:
                    os.close(probe_fd)
            fd = os.open(path, os.O_CREAT | os.O_APPEND | os.O_WRONLY, 0o600)
            try:
                # ``os.write`` is allowed to perform a short write.  Do not
                # fsync a truncated JSONL row and then report it durable.
                for chunk in (fence, encoded):
                    view = memoryview(chunk)
                    offset = 0
                    while offset < len(view):
                        written = os.write(fd, view[offset:])
                        if written <= 0:
                            raise OSError(f"{label} evidence journal short write")
                        offset += written
                os.fsync(fd)
            finally:
                os.close(fd)
        return True
    except (OSError, TypeError, ValueError) as exc:
        logger.error(
            f"[COLLECTOR_V22] {label} evidence handoff append failed: {exc} "
            "[EVIDENCE GAP]"
        )
        return False


def _write_cancellation_evidence_handoff(job: dict) -> None:
    """Reconcile one journal row; the bounded worker owns retry/back-pressure."""
    receipt = copy.deepcopy((job.get("payload") or {}).get("receipt") or {})
    receipt_id = str(receipt.get("receipt_id") or "")
    expected_epoch_id = str(receipt.get("collector_epoch_id") or "")
    if not receipt_id or not expected_epoch_id:
        raise ValueError("cancellation evidence receipt identity is incomplete")
    if _collector_v22_epoch_id() != expected_epoch_id:
        if not _append_cancellation_evidence_handoff({
            "schema": "cancellation_evidence_handoff_result_v1",
            "receipt_id": receipt_id,
            "collector_epoch_id": expected_epoch_id,
            "trade_id": str(receipt.get("trade_id") or ""),
            "status": "EPOCH_MISMATCH_PRESERVED",
            "completed_at": utc_iso(),
            "lifecycle_final": bool(receipt.get("lifecycle_final")),
        }):
            raise OSError("could not durably append epoch-mismatch result")
        return
    refreshed = _refresh_collector_v22_registered_order_evidence(
        copy.deepcopy(receipt.get("order_snapshot") or {}),
        copy.deepcopy(receipt.get("signal_snapshot") or {}),
        lifecycle_final=bool(receipt.get("lifecycle_final")),
        expected_epoch_id=expected_epoch_id,
        require_terminal_receipt=True,
    )
    if not refreshed:
        raise RuntimeError("collector refresh did not apply; handoff remains pending")
    if not _append_cancellation_evidence_handoff({
        "schema": "cancellation_evidence_handoff_result_v1",
        "receipt_id": receipt_id,
        "collector_epoch_id": expected_epoch_id,
        "trade_id": str(receipt.get("trade_id") or ""),
        "status": "APPLIED",
        "completed_at": utc_iso(),
        "lifecycle_final": bool(receipt.get("lifecycle_final")),
    }):
        raise OSError("could not durably append applied result")


def _cancellation_evidence_dead_letter(row: dict) -> None:
    # Leave the pending row without a terminal result so a restart can replay it.
    # This callback is observability only and never changes execution authority.
    logger.error(
        f"[COLLECTOR_V22] cancellation evidence handoff deferred "
        f"key={row.get('key')} reason={row.get('reason')} "
        f"error={row.get('error')} [EVIDENCE GAP]"
    )


def _get_cancellation_evidence_worker():
    global _cancellation_evidence_worker
    with _cancellation_evidence_worker_lock:
        if _cancellation_evidence_reset_fence or _fresh_collection_lock.locked():
            return None
        if _cancellation_evidence_worker is not None:
            existing = _cancellation_evidence_worker.snapshot()
            if (not existing.get("accepting")
                    and not existing.get("timed_out_handler_alive")):
                _cancellation_evidence_worker = None
        if _cancellation_evidence_worker is None:
            _cancellation_evidence_worker = BoundedEvidenceWorker(
                _write_cancellation_evidence_handoff,
                max_queue=128,
                max_retries=1,
                handler_timeout_sec=10.0,
                name="cancellation-evidence",
                on_dead_letter=_cancellation_evidence_dead_letter,
            )
        return _cancellation_evidence_worker


def _shutdown_cancellation_evidence_worker(timeout: float = 5.0) -> bool:
    global _cancellation_evidence_worker
    worker = _cancellation_evidence_worker
    if worker is None:
        return True
    drained = worker.shutdown(drain_timeout=timeout)
    snapshot = worker.snapshot()
    if not drained or snapshot.get("timed_out_handler_alive"):
        return False
    with _cancellation_evidence_worker_lock:
        if _cancellation_evidence_worker is worker:
            _cancellation_evidence_worker = None
    return True


def _dispatch_cancellation_evidence_handoff(receipt: dict) -> bool:
    """Queue one durable handoff without blocking the scheduler owner."""
    receipt_id = str(receipt.get("receipt_id") or "")
    if not receipt_id:
        return False
    worker = _get_cancellation_evidence_worker()
    if worker is None:
        logger.warning(
            f"[COLLECTOR_V22] cancellation evidence dispatch fenced during reset "
            f"receipt_id={receipt_id} [EVIDENCE GAP]"
        )
        return False
    return bool(worker.submit(
        receipt_id,
        {"receipt": copy.deepcopy(receipt)},
        source_ts=time.time(),
    ))


def _replay_cancellation_evidence_handoffs() -> int:
    """Replay append-first handoffs left pending by an interrupted process."""
    path = _cancellation_evidence_handoff_path()
    if not os.path.exists(path):
        return 0
    pending = {}
    terminal = set()
    try:
        with open(path, "r", encoding="utf-8") as handle:
            for line in handle:
                try:
                    row = json.loads(line)
                except (TypeError, ValueError):
                    continue
                receipt_id = str(row.get("receipt_id") or "")
                if not receipt_id:
                    continue
                if row.get("schema") == "cancellation_evidence_handoff_pending_v1":
                    remember = globals().get("_remember_cancellation_handoff")
                    if callable(remember):
                        remember(receipt_id, (
                            f"final:{row.get('collector_epoch_id')}:{row.get('trade_id')}"
                            if row.get("lifecycle_final") and row.get("trade_id") else None
                        ))
                    if len(receipt_id) != 64 or not row.get("collector_epoch_id"):
                        logger.error(
                            f"[COLLECTOR_V22] malformed cancellation handoff identity "
                            f"receipt_id={receipt_id!r} [EVIDENCE GAP]"
                        )
                        continue
                    pending.setdefault(receipt_id, row)
                elif row.get("schema") == "cancellation_evidence_handoff_result_v1":
                    status = str(row.get("status") or "")
                    if status in {"APPLIED", "EPOCH_MISMATCH_PRESERVED"}:
                        terminal.add(receipt_id)
                else:
                    logger.error(
                        f"[COLLECTOR_V22] unknown cancellation handoff schema "
                        f"receipt_id={receipt_id!r} [EVIDENCE GAP]"
                    )
    except OSError as exc:
        logger.warning(f"[COLLECTOR_V22] cancellation evidence replay unavailable: {exc}")
        return 0
    dispatched = 0
    for receipt_id, receipt in pending.items():
        if receipt_id not in terminal and _dispatch_cancellation_evidence_handoff(receipt):
            dispatched += 1
    return dispatched


def _enqueue_cancellation_evidence_handoff(
    order: dict, signal: dict = None, *, lifecycle_final: bool = True,
) -> bool:
    """Durably bind cancellation evidence before asynchronous collector work."""
    epoch_id = _collector_v22_epoch_id()
    order_snapshot = copy.deepcopy(order if isinstance(order, dict) else {})
    signal_snapshot = copy.deepcopy(signal if isinstance(signal, dict) else {})
    identity = {
        "collector_epoch_id": epoch_id,
        "trade_id": str(order_snapshot.get("trade_id") or ""),
        "cancel_confirmed_ts": order_snapshot.get("cancel_confirmed_ts"),
        "cancel_confirmed_reason": order_snapshot.get("cancel_confirmed_reason"),
    }
    receipt_id = hashlib.sha256(
        json.dumps(identity, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
    ).hexdigest()
    receipt = {
        "schema": "cancellation_evidence_handoff_pending_v1",
        "receipt_id": receipt_id,
        "collector_epoch_id": epoch_id,
        "trade_id": identity["trade_id"],
        "created_at": utc_iso(),
        "lifecycle_final": bool(lifecycle_final),
        "order_snapshot": order_snapshot,
        "signal_snapshot": signal_snapshot,
    }
    seen = globals().get("_cancellation_handoff_seen")
    once_key = (
        f"final:{epoch_id}:{identity['trade_id']}" if lifecycle_final and identity["trade_id"] else None
    )
    if seen is not None:
        with _cancellation_evidence_handoff_lock:
            if receipt_id in seen or (once_key and once_key in seen):
                # Already journaled (concurrent pause paths / repeated finalizer):
                # the durable receipt exists, so this is not an evidence gap.
                _cancellation_handoff_seen_stats["duplicates_skipped"] += 1
                return True
            # Reserve before the append so a concurrent caller cannot journal it too.
            for key in (receipt_id, once_key):
                if key:
                    seen[key] = None
    if not _append_cancellation_evidence_handoff(receipt):
        if seen is not None:
            with _cancellation_evidence_handoff_lock:
                for key in (receipt_id, once_key):
                    if key:
                        seen.pop(key, None)
        return False
    if seen is not None:
        _remember_cancellation_handoff(receipt_id, once_key)  # LRU order + bound
    return _dispatch_cancellation_evidence_handoff(receipt)


# Receipt ids (and per-trade final-cancellation keys) already journaled to
# cancellation_evidence_handoffs.jsonl, so each cancellation is written once.
# Bounded; seeded from the journal by the startup replay.
CANCELLATION_HANDOFF_SEEN_MAX = 100_000
_cancellation_handoff_seen: "collections.OrderedDict[str, None]" = collections.OrderedDict()
_cancellation_handoff_seen_stats = {"duplicates_skipped": 0}


def _remember_cancellation_handoff(receipt_id: str, once_key: str | None = None) -> None:
    with _cancellation_evidence_handoff_lock:
        for key in (receipt_id, once_key):
            if key:
                _cancellation_handoff_seen[key] = None
                _cancellation_handoff_seen.move_to_end(key)
        while len(_cancellation_handoff_seen) > CANCELLATION_HANDOFF_SEEN_MAX:
            _cancellation_handoff_seen.popitem(last=False)


FILL_EVIDENCE_IDENTITY_KEYS = (
    "epoch_id", "opportunity_id", "policy_signature", "policy_epoch_id",
    "schedule_id", "fill_id", "tape_id",
)


def _fill_evidence_handoff_path() -> str:
    return os.path.join(
        str(_data_sync_runtime_root()), "fill_evidence_handoffs.jsonl"
    )


def _append_fill_evidence_handoff(row: dict) -> bool:
    return _append_durable_handoff_row(
        _fill_evidence_handoff_path(), row, _fill_evidence_handoff_lock, "fill",
    )


def _write_fill_evidence_handoff(job: dict) -> None:
    """Apply one fill's post-open evidence exactly once per receipt.

    Each step is idempotent (record_id ledgers, write-once multiverse,
    set-valued snapshot patch, whole-file positions snapshot) or guarded by
    the per-receipt step set, so a retry or restart replay never duplicates.
    """
    receipt = copy.deepcopy((job.get("payload") or {}).get("receipt") or {})
    receipt_id = str(receipt.get("receipt_id") or "")
    expected_epoch_id = str(receipt.get("collector_epoch_id") or "")
    trade_id = str(receipt.get("trade_id") or "")
    if not receipt_id or not expected_epoch_id or not trade_id:
        raise ValueError("fill evidence receipt identity is incomplete")
    preentry_barrier = globals().get("_preentry_evidence_barrier")
    if callable(preentry_barrier):
        preentry_barrier(receipt, receipt.get("order_snapshot"), receipt.get("signal_snapshot"))
    if _collector_v22_epoch_id() != expected_epoch_id:
        if not _append_fill_evidence_handoff({
            "schema": "fill_evidence_handoff_result_v1",
            "receipt_id": receipt_id,
            "collector_epoch_id": expected_epoch_id,
            "trade_id": trade_id,
            "status": "EPOCH_MISMATCH_PRESERVED",
            "completed_at": utc_iso(),
        }):
            raise OSError("could not durably append epoch-mismatch result")
        _fill_evidence_steps_done.pop(receipt_id, None)
        return
    order = receipt.get("order_snapshot") or {}
    signal = receipt.get("signal_snapshot") or {}
    position = receipt.get("position_snapshot") or {}
    fill_snapshot = receipt.get("fill_snapshot") or None
    fill_commit_ts = float(receipt.get("fill_commit_ts") or 0) or time.time()
    fill_px = float(receipt.get("fill_price") or 0)
    done = _fill_evidence_steps_done.setdefault(receipt_id, set())
    required_failures = []

    def step(name, fn, *, required=False):
        if name in done:
            return
        try:
            fn()
        except Exception as exc:
            logger.error(
                f"[FILL EVIDENCE] {name} failed trade_id={trade_id} error={exc} "
                "[EVIDENCE GAP]"
            )
            if required:
                required_failures.append(name)
                return
        done.add(name)

    step("action_receipt", lambda: _append_paper_action_receipt(
        order,
        signal,
        action_generation=int(order.get("limit_chase_count") or 0) + 1,
        action_type="FILL_PROMOTED",
        policy_due_ts=fill_commit_ts,
        eligibility_ts=fill_commit_ts,
        dispatch_start_ts=fill_commit_ts,
        acknowledgement_ts=fill_commit_ts,
        fill_ts=fill_commit_ts,
        fill_price=order.get("fill_price") or order.get("limit_price"),
        filled_qty=order.get("filled_qty") or order.get("qty"),
    ))

    def v3_fill():
        fill_identity_receipt = dual_write_paper_fill(
            order, signal, position,
            epoch_id=expected_epoch_id,
            data_dir=str(receipt.get("data_dir") or os.getcwd()),
        )
        identity = {
            key: fill_identity_receipt[key]
            for key in FILL_EVIDENCE_IDENTITY_KEYS
            if fill_identity_receipt.get(key)
        }
        if identity:
            with trade_lock:
                for row in open_positions:
                    if isinstance(row, dict) and str(row.get("trade_id") or "") == trade_id:
                        row.update(identity)

    step("v3_fill", v3_fill, required=True)
    collector_refresh = globals().get("_refresh_collector_v22_registered_order_evidence")
    if callable(collector_refresh):
        step("collector_refresh", lambda: collector_refresh(
            order, signal or None,
            lifecycle_final=True,
            expected_epoch_id=expected_epoch_id,
        ))
    if fill_px > 0:
        step("signal_snapshot", lambda: patch_signal_snapshot_outcome(
            trade_id, executed=True, block_reason=None, fill_price=fill_px,
            fill_dynamics=receipt.get("fill_dynamics"),
        ))
    step("persist_signal", lambda: persist_signal(fill_snapshot, "FILLED"))
    step("multiverse", lambda: _sync_order_multiverse(
        fill_snapshot or signal or order, path_complete=False,
    ))
    step("save_positions", save_positions)
    if required_failures:
        raise RuntimeError(
            f"fill evidence incomplete steps={required_failures}; handoff remains pending"
        )
    if not _append_fill_evidence_handoff({
        "schema": "fill_evidence_handoff_result_v1",
        "receipt_id": receipt_id,
        "collector_epoch_id": expected_epoch_id,
        "trade_id": trade_id,
        "status": "APPLIED",
        "completed_at": utc_iso(),
        "steps": sorted(done),
    }):
        raise OSError("could not durably append applied result")
    _fill_evidence_steps_done.pop(receipt_id, None)


def _fill_evidence_dead_letter(row: dict) -> None:
    # The pending journal row has no terminal result, so restart replays it.
    logger.error(
        f"[FILL EVIDENCE] handoff deferred key={row.get('key')} "
        f"reason={row.get('reason')} error={row.get('error')} [EVIDENCE GAP]"
    )


def _get_fill_evidence_worker():
    global _fill_evidence_worker
    with _fill_evidence_worker_lock:
        if _cancellation_evidence_reset_fence or _fresh_collection_lock.locked():
            return None
        if _fill_evidence_worker is not None:
            existing = _fill_evidence_worker.snapshot()
            if (not existing.get("accepting")
                    and not existing.get("timed_out_handler_alive")):
                _fill_evidence_worker = None
        if _fill_evidence_worker is None:
            _fill_evidence_worker = BoundedEvidenceWorker(
                _write_fill_evidence_handoff,
                max_queue=256,
                max_retries=2,
                handler_timeout_sec=120.0,
                name="fill-evidence",
                on_dead_letter=_fill_evidence_dead_letter,
            )
        return _fill_evidence_worker


def _shutdown_fill_evidence_worker(timeout: float = 5.0) -> bool:
    global _fill_evidence_worker
    worker = _fill_evidence_worker
    if worker is None:
        return True
    drained = worker.shutdown(drain_timeout=timeout)
    snapshot = worker.snapshot()
    if not drained or snapshot.get("timed_out_handler_alive"):
        return False
    with _fill_evidence_worker_lock:
        if _fill_evidence_worker is worker:
            _fill_evidence_worker = None
    return True


def _dispatch_fill_evidence_handoff(receipt: dict) -> bool:
    receipt_id = str(receipt.get("receipt_id") or "")
    if not receipt_id:
        return False
    worker = _get_fill_evidence_worker()
    if worker is None:
        logger.warning(
            f"[FILL EVIDENCE] dispatch fenced during reset receipt_id={receipt_id} "
            "[EVIDENCE GAP]"
        )
        return False
    return bool(worker.submit(
        receipt_id,
        {"receipt": receipt},
        source_ts=float(receipt.get("fill_commit_ts") or time.time()),
    ))


def _replay_fill_evidence_handoffs() -> int:
    """Replay append-first fill handoffs left pending by an interrupted process."""
    path = _fill_evidence_handoff_path()
    if not os.path.exists(path):
        return 0
    pending = {}
    terminal = set()
    try:
        with open(path, "r", encoding="utf-8") as handle:
            for line in handle:
                try:
                    row = json.loads(line)
                except (TypeError, ValueError):
                    continue
                receipt_id = str(row.get("receipt_id") or "")
                if not receipt_id:
                    continue
                if row.get("schema") == "fill_evidence_handoff_pending_v1":
                    if len(receipt_id) != 64 or not row.get("collector_epoch_id"):
                        continue
                    pending.setdefault(receipt_id, row)
                elif (
                    row.get("schema") == "fill_evidence_handoff_result_v1"
                    and row.get("status") in {"APPLIED", "EPOCH_MISMATCH_PRESERVED"}
                ):
                    terminal.add(receipt_id)
    except OSError as exc:
        logger.warning(f"[FILL EVIDENCE] replay unavailable: {exc}")
        return 0
    dispatched = 0
    for receipt_id, receipt in pending.items():
        if receipt_id not in terminal and _dispatch_fill_evidence_handoff(receipt):
            dispatched += 1
    return dispatched


def _enqueue_fill_evidence_handoff(
    order: dict, signal: dict, pos: dict, fill_snapshot,
    *, fill_commit_ts: float, fill_px, fill_dynamics=None,
) -> bool:
    """Durably bind a committed fill's evidence, then hand it to the worker.

    Runs on the fill thread after POSITION_OPENED: it must never raise and
    must never wait on research-gate locks, ledgers, or the snapshot file.
    """
    trade_id = str((pos or {}).get("trade_id") or (order or {}).get("trade_id") or "")
    try:
        epoch_id = _collector_v22_epoch_id()
        identity = {
            "collector_epoch_id": epoch_id,
            "trade_id": trade_id,
            "event": "POSITION_OPENED",
            "fill_commit_ts": fill_commit_ts,
        }
        receipt_id = hashlib.sha256(
            json.dumps(identity, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
        ).hexdigest()
        receipt = {
            "schema": "fill_evidence_handoff_pending_v1",
            "receipt_id": receipt_id,
            "collector_epoch_id": epoch_id,
            "trade_id": trade_id,
            "created_at": utc_iso(),
            "data_dir": os.getcwd(),
            "fill_commit_ts": fill_commit_ts,
            "fill_price": fill_px,
            "fill_dynamics": copy.deepcopy(fill_dynamics),
            "order_snapshot": _stable_pending_signal_copy(order),
            "signal_snapshot": _stable_pending_signal_copy(signal),
            "position_snapshot": _stable_pending_signal_copy(pos),
            "fill_snapshot": _stable_pending_signal_copy(fill_snapshot),
        }
    except Exception as exc:
        logger.error(
            f"[FILL EVIDENCE] receipt build failed trade_id={trade_id} error={exc} "
            "[EVIDENCE GAP]"
        )
        return False
    if not _append_fill_evidence_handoff(receipt):
        logger.error(
            f"[FILL EVIDENCE] journal append failed; dispatching without restart "
            f"replay trade_id={trade_id} [EVIDENCE GAP]"
        )
    try:
        return _dispatch_fill_evidence_handoff(receipt)
    except Exception as exc:
        logger.error(
            f"[FILL EVIDENCE] dispatch failed trade_id={trade_id} error={exc} "
            "[EVIDENCE GAP]"
        )
        return False


# Submit-first pre-entry evidence for the cross-venue signal-clock tiles. The
# research rows written between a trigger and its paper order (V3 lane decision,
# provisional multiverse event, duplicate-intent audit) are fsync'd to a
# journal before the order, then materialized by one worker. Any writer of later
# evidence for the same call/trade first drains every earlier pending receipt
# (FIFO prefix) under the collector lock, so a terminal or lifecycle row can
# never precede its provisional rows. A failed, stale or backlogged queue turns
# deferral off and the synchronous fail-closed path is used again.
PREENTRY_EVIDENCE_DEFERRAL_ENABLED = os.getenv("PREENTRY_EVIDENCE_DEFERRAL", "1").strip() == "1"
PREENTRY_EVIDENCE_PENDING_SCHEMA = "pre_entry_evidence_handoff_pending_v1"
PREENTRY_EVIDENCE_RESULT_SCHEMA = "pre_entry_evidence_handoff_result_v1"
PREENTRY_EVIDENCE_KINDS = ("V3_LANE_DECISION", "MULTIVERSE_PROVISIONAL", "DUPLICATE_INTENT_AUDIT")
PREENTRY_EVIDENCE_MAX_PENDING = 32
PREENTRY_EVIDENCE_MAX_PENDING_AGE_SEC = 30.0
PREENTRY_EVIDENCE_FAILURE_COOLDOWN_SEC = 600.0
PREENTRY_EVIDENCE_MAX_ATTEMPTS = 3
PREENTRY_EVIDENCE_BARRIER_TIMEOUT_SEC = 10.0
PREENTRY_EVIDENCE_COMPACT_BYTES = 8 * 1024 * 1024
_preentry_evidence_lock = threading.Lock()
_preentry_evidence_journal_lock = threading.Lock()
_preentry_evidence_tls = threading.local()
_preentry_evidence_pending = collections.OrderedDict()
_preentry_evidence_seq = 0
_preentry_evidence_worker = None
_preentry_evidence_status = {
    "enqueued": 0, "applied": 0, "epoch_preserved": 0, "failures": 0, "dead": 0,
    "journal_failures": 0, "barrier_drains": 0, "barrier_timeouts": 0, "replayed": 0,
    "compactions": 0, "sync_fallbacks": 0, "last_failure_ts": 0.0, "last_error": None,
    "last_apply_lag_s": None, "max_apply_lag_s": 0.0,
}


def _preentry_evidence_journal_path() -> str:
    return os.path.join(str(_data_sync_runtime_root()), "pre_entry_evidence_handoffs.jsonl")


def _preentry_evidence_count(key: str, amount=1) -> None:
    with _preentry_evidence_lock:
        _preentry_evidence_status[key] = _preentry_evidence_status.get(key, 0) + amount


def _preentry_evidence_failed(error: str) -> None:
    with _preentry_evidence_lock:
        _preentry_evidence_status["failures"] += 1
        _preentry_evidence_status["last_failure_ts"] = time.time()
        _preentry_evidence_status["last_error"] = str(error)[:240]


def _preentry_evidence_ready() -> bool:
    """Deferral is allowed only while the queue is healthy and keeping up."""
    if not PREENTRY_EVIDENCE_DEFERRAL_ENABLED or _cancellation_evidence_reset_fence:
        return False
    now = time.time()
    with _preentry_evidence_lock:
        status = _preentry_evidence_status
        if now - float(status["last_failure_ts"] or 0.0) < PREENTRY_EVIDENCE_FAILURE_COOLDOWN_SEC:
            return False
        if len(_preentry_evidence_pending) >= PREENTRY_EVIDENCE_MAX_PENDING:
            return False
        oldest = next(iter(_preentry_evidence_pending.values()), None)
    return not oldest or now - float(oldest.get("enqueued_ts") or now) <= PREENTRY_EVIDENCE_MAX_PENDING_AGE_SEC


def _preentry_evidence_deferrable(lane) -> bool:
    return bool(is_evaluator_clock_lane(str(lane or "").upper()) and _preentry_evidence_ready())


def _preentry_evidence_keys(*sources) -> set:
    keys = set()
    for source in sources:
        if isinstance(source, dict):
            for field in ("shared_ai_call_id", "trade_id"):
                value = str(source.get(field) or "")
                if value:
                    keys.add(value)
    return keys


def _get_preentry_evidence_worker():
    global _preentry_evidence_worker
    with _preentry_evidence_lock:
        if _preentry_evidence_worker is None:
            _preentry_evidence_worker = BoundedEvidenceWorker(
                lambda job: _drain_preentry_evidence(through=job["key"]),
                max_queue=256,
                max_retries=0,
                name="pre-entry-evidence",
            )
        return _preentry_evidence_worker


def _shutdown_preentry_evidence_worker(timeout: float = 5.0) -> bool:
    global _preentry_evidence_worker
    worker = _preentry_evidence_worker
    if worker is None:
        return True
    drained = worker.shutdown(drain_timeout=timeout)
    if drained:
        with _preentry_evidence_lock:
            if _preentry_evidence_worker is worker:
                _preentry_evidence_worker = None
    return drained


def _enqueue_preentry_evidence(kind: str, keys, payload: dict, *, lane: str) -> bool:
    """fsync one receipt, then hand it to the worker; False means write synchronously."""
    global _preentry_evidence_seq
    if kind not in PREENTRY_EVIDENCE_KINDS:
        raise ValueError(f"unknown pre-entry evidence kind {kind}")
    try:
        epoch_id = _collector_v22_epoch_id()
        with _preentry_evidence_lock:
            _preentry_evidence_seq += 1
            seq = _preentry_evidence_seq
        now = time.time()
        identity = {"collector_epoch_id": epoch_id, "kind": kind, "keys": sorted(keys),
                    "enqueued_ts": now, "pid": os.getpid(), "seq": seq}
        receipt = {
            "schema": PREENTRY_EVIDENCE_PENDING_SCHEMA,
            "receipt_id": hashlib.sha256(
                json.dumps(identity, sort_keys=True, separators=(",", ":")).encode("utf-8")
            ).hexdigest(),
            "collector_epoch_id": epoch_id,
            "kind": kind,
            "research_lane": str(lane or "").upper(),
            "keys": sorted(keys),
            "seq": seq,
            "enqueued_ts": now,
            "created_at": utc_iso(),
            "payload": payload,
        }
    except Exception as exc:
        logger.error(f"[PRE-ENTRY EVIDENCE] receipt build failed kind={kind} error={exc} [PIPELINE ENFORCEMENT]")
        _preentry_evidence_count("sync_fallbacks")
        return False
    if not _append_durable_handoff_row(
        _preentry_evidence_journal_path(), receipt, _preentry_evidence_journal_lock, "pre-entry",
    ):
        _preentry_evidence_count("journal_failures")
        _preentry_evidence_failed("journal append failed")
        _preentry_evidence_count("sync_fallbacks")
        return False
    with _preentry_evidence_lock:
        _preentry_evidence_pending[receipt["receipt_id"]] = receipt
        _preentry_evidence_status["enqueued"] += 1
    try:
        _get_preentry_evidence_worker().submit(receipt["receipt_id"], {}, source_ts=now)
    except Exception as exc:
        # Durable and pending: the next barrier or restart replay applies it.
        logger.error(f"[PRE-ENTRY EVIDENCE] dispatch failed kind={kind} error={exc} [EVIDENCE GAP]")
    return True


def _apply_preentry_receipt(receipt: dict) -> bool:
    """Materialize one receipt; the caller holds the collector epoch lock."""
    receipt_id = receipt["receipt_id"]
    payload = receipt.get("payload") or {}
    kind = receipt.get("kind")
    if _collector_v22_epoch_id() != receipt.get("collector_epoch_id"):
        status, ok = "EPOCH_MISMATCH_PRESERVED", True
    else:
        _preentry_evidence_tls.applying = True
        try:
            if kind == "V3_LANE_DECISION":
                ok = bool(_write_v3_shared_lane_decision(
                    payload["lane"], payload["ai"], payload["ctx"], payload["features"],
                    **payload["decision"],
                ))
            elif kind == "MULTIVERSE_PROVISIONAL":
                _sync_order_multiverse(payload["signal"], path_complete=False)
                ok = True
            elif kind == "DUPLICATE_INTENT_AUDIT":
                ok = bool(_safe_append_jsonl(
                    DUPLICATE_INTENT_AUDIT_FILE, payload["row"], label="DUPLICATE_INTENT_AUDIT",
                ))
            else:
                ok = False
        except Exception as exc:
            logger.error(f"[PRE-ENTRY EVIDENCE] {kind} failed receipt={receipt_id[:12]} error={exc} [EVIDENCE GAP]")
            ok = False
        finally:
            _preentry_evidence_tls.applying = False
        status = "APPLIED"
    if not ok:
        receipt["attempts"] = int(receipt.get("attempts") or 0) + 1
        _preentry_evidence_failed(f"{kind} not durable")
        if receipt["attempts"] < PREENTRY_EVIDENCE_MAX_ATTEMPTS:
            return False
        # Terminal for replay: applying it later could land after the trade's
        # terminal rows. The payload stays in the journal and the V3 writer has
        # already dead-lettered the pre-entry evidence failure.
        logger.error(f"[PRE-ENTRY EVIDENCE] {kind} dead receipt={receipt_id[:12]} keys={receipt.get('keys')} [EVIDENCE GAP]")
        _append_durable_handoff_row(_preentry_evidence_journal_path(), {
            "schema": PREENTRY_EVIDENCE_RESULT_SCHEMA, "receipt_id": receipt_id, "kind": kind,
            "status": "DEAD_LETTERED", "attempts": receipt["attempts"], "completed_at": utc_iso(),
        }, _preentry_evidence_journal_lock, "pre-entry")
        with _preentry_evidence_lock:
            _preentry_evidence_pending.pop(receipt_id, None)
            _preentry_evidence_status["dead"] += 1
        return False
    if not _append_durable_handoff_row(_preentry_evidence_journal_path(), {
        "schema": PREENTRY_EVIDENCE_RESULT_SCHEMA, "receipt_id": receipt_id, "kind": kind,
        "status": status, "completed_at": utc_iso(),
    }, _preentry_evidence_journal_lock, "pre-entry"):
        _preentry_evidence_count("journal_failures")
        _preentry_evidence_failed("result append failed")
    lag = round(time.time() - float(receipt.get("enqueued_ts") or time.time()), 3)
    with _preentry_evidence_lock:
        _preentry_evidence_pending.pop(receipt_id, None)
        _preentry_evidence_status["applied" if status == "APPLIED" else "epoch_preserved"] += 1
        _preentry_evidence_status["last_apply_lag_s"] = lag
        _preentry_evidence_status["max_apply_lag_s"] = max(_preentry_evidence_status["max_apply_lag_s"], lag)
    return True


def _compact_preentry_evidence_journal() -> None:
    path = _preentry_evidence_journal_path()
    with _preentry_evidence_journal_lock:
        if _preentry_evidence_pending or _preentry_evidence_status["dead"]:
            return
        try:
            if os.path.getsize(path) <= PREENTRY_EVIDENCE_COMPACT_BYTES:
                return
            os.replace(path, path + ".1")
        except OSError:
            return
    _preentry_evidence_count("compactions")


def _quiesce_preentry_evidence(timeout: float = 5.0) -> bool:
    """Stop the worker and apply every pending receipt (fresh-collection reset)."""
    if not _shutdown_preentry_evidence_worker(timeout=timeout):
        return False
    return _drain_preentry_evidence(through=next(reversed(_preentry_evidence_pending), None), timeout=timeout)


def _drain_preentry_evidence(*, keys=(), through: str = None, timeout: float = None) -> bool:
    """Apply every pending receipt up to the last one matching ``keys``/``through``."""
    if not _preentry_evidence_pending or getattr(_preentry_evidence_tls, "applying", False):
        return True
    wait = PREENTRY_EVIDENCE_BARRIER_TIMEOUT_SEC if timeout is None else timeout
    if not _collector_epoch_lock.acquire(timeout=wait):
        _preentry_evidence_count("barrier_timeouts")
        _preentry_evidence_failed("barrier timeout")
        logger.error(f"[PRE-ENTRY EVIDENCE] barrier timeout keys={sorted(keys)} [EVIDENCE GAP]")
        return False
    try:
        with _preentry_evidence_lock:
            ordered = list(_preentry_evidence_pending.values())
        wanted = set(keys)
        last = -1
        for index, receipt in enumerate(ordered):
            if receipt["receipt_id"] == through or wanted.intersection(receipt.get("keys") or ()):
                last = index
        ok = True
        for receipt in ordered[:last + 1]:
            with _preentry_evidence_lock:
                still_pending = receipt["receipt_id"] in _preentry_evidence_pending
            if still_pending:
                ok = _apply_preentry_receipt(receipt) and ok
    finally:
        _collector_epoch_lock.release()
    _compact_preentry_evidence_journal()
    return ok


def _preentry_evidence_barrier(*sources) -> bool:
    """Called before any later evidence write for a call/trade; no-op when idle."""
    if not _preentry_evidence_pending:
        return True
    keys = _preentry_evidence_keys(*sources)
    if not keys:
        return True
    with _preentry_evidence_lock:
        matched = any(keys.intersection(r.get("keys") or ()) for r in _preentry_evidence_pending.values())
    if not matched:
        return True
    _preentry_evidence_count("barrier_drains")
    return _drain_preentry_evidence(keys=keys)


def _replay_preentry_evidence_handoffs() -> int:
    """Re-queue receipts an interrupted process journaled but never applied."""
    path = _preentry_evidence_journal_path()
    pending, terminal = collections.OrderedDict(), set()
    for candidate in (path + ".1", path):
        if not os.path.exists(candidate):
            continue
        try:
            with open(candidate, "r", encoding="utf-8") as handle:
                for line in handle:
                    try:
                        row = json.loads(line)
                    except (TypeError, ValueError):
                        continue
                    receipt_id = str(row.get("receipt_id") or "")
                    if len(receipt_id) != 64:
                        continue
                    if row.get("schema") == PREENTRY_EVIDENCE_PENDING_SCHEMA and row.get("kind") in PREENTRY_EVIDENCE_KINDS:
                        pending.setdefault(receipt_id, row)
                    elif row.get("schema") == PREENTRY_EVIDENCE_RESULT_SCHEMA:
                        terminal.add(receipt_id)
        except OSError as exc:
            logger.warning(f"[PRE-ENTRY EVIDENCE] replay unavailable: {exc}")
            return 0
    replay = [row for receipt_id, row in pending.items() if receipt_id not in terminal]
    replay.sort(key=lambda row: (float(row.get("enqueued_ts") or 0.0), int(row.get("seq") or 0)))
    with _preentry_evidence_lock:
        for row in replay:
            _preentry_evidence_pending.setdefault(row["receipt_id"], row)
        _preentry_evidence_status["replayed"] += len(replay)
    if replay:
        _drain_preentry_evidence(through=replay[-1]["receipt_id"])
    return len(replay)


def preentry_evidence_snapshot() -> dict:
    now = time.time()
    with _preentry_evidence_lock:
        status = dict(_preentry_evidence_status)
        pending = len(_preentry_evidence_pending)
        oldest = next(iter(_preentry_evidence_pending.values()), None)
    oldest_age = round(now - float(oldest.get("enqueued_ts") or now), 3) if oldest else None
    if not PREENTRY_EVIDENCE_DEFERRAL_ENABLED:
        health = "DISABLED"
    elif status["dead"] or status["barrier_timeouts"]:
        health = "DEGRADED"
    elif not _preentry_evidence_ready():
        health = "SYNC_FALLBACK"
    else:
        health = "OK"
    return {
        "schema": "pre_entry_evidence_queue_v1", "health": health, "pending": pending,
        "oldest_pending_age_s": oldest_age, **status,
    }


@_collector_epoch_serialized
def persist_rejected_opportunity(signal: dict, ai: dict = None, reason: str = "REJECTED", *, would_block_only: bool = False):
    """First-class rejected/WOULD_BLOCK candidate. Not a live veto."""
    if not isinstance(signal, dict):
        return None
    if not _collector_source_in_current_epoch(signal):
        logger.warning(
            "[COLLECTOR_V22] stale pre-reset rejected source refused "
            f"trade_id={signal.get('trade_id')} [PIPELINE ENFORCEMENT]"
        )
        return None
    try:
        tid = str(signal.get("trade_id") or "")
        if not tid:
            return None
        if _execution_trade_is_terminal(tid):
            # The terminal execution ledger supersedes the rejected recovery
            # source.  Left pending, it re-enters every sweep oldest-first and
            # the journal re-merge restores it, starving mature rows behind it.
            pending = _order_multiverse_pending_src.get(tid)
            superseded = isinstance(pending, dict) and bool(pending.get("collector_rejected"))
            if superseded:
                _order_multiverse_pending_src.pop(tid, None)
                _order_multiverse_state.pop(tid, None)
                remove_provisional_event(tid, data_dir=str(_data_sync_runtime_root()))
                _collector_collection_stat("superseded_rejected_provisionals")
            logger.info(
                f"[COLLECTOR_V22] terminal execution suppresses stale rejected provisional "
                f"trade_id={tid} released={superseded} [PIPELINE ENFORCEMENT]"
            )
            return None
        price = float(
            signal.get("signal_price_at_approve")
            or signal.get("signal_price")
            or signal.get("price")
            or 0
        )
        if price <= 0:
            with state_lock:
                price = float(state.get("price") or 0)
        if price <= 0:
            return None
        ts = float(signal.get("created_ts_ts") or signal.get("created_ts") or signal.get("signal_ts") or 0)
        if ts <= 0:
            ts = float(signal.get("snapshot_ts") or time.time())
        direction = signal.get("final_direction") or (ai or {}).get("direction") or "SHORT"
        candles_1m, path_source = _collector_path_candles_1m(ts)
        grid_anchor = _resolve_entry_grid_anchor(
            signal, signal_ts=ts, signal_price=price, direction=direction,
        )
        with state_lock:
            univ = dict(state.get("last_cycle_3m_universe") or {})
        feature_snapshot = _collector_feature_snapshot(signal, signal_ts=ts)
        rsi_at_signal = univ.get("rsi14") or univ.get("rsi_3m")
        would_block = univ.get("would_block_short")
        would_block_reason = univ.get("would_block_reason") or (None if not would_block_only else reason)
        tree = build_decision_tree_v22(
            reason=reason,
            hard_reject=not would_block_only,
            rsi=rsi_at_signal,
            rsi_threshold=30.0,
            adx=univ.get("adx14"),
            atr=univ.get("atr14_pct_3m"),
            would_block=would_block or would_block_only,
            would_block_reason=would_block_reason or reason,
            edge=signal.get("edge_score_at_entry"),
            approval=(ai or {}).get("decision"),
            short_circuit=not would_block_only,
        )
        if storage_blocks_new_events():
            logger.warning("[COLLECTOR_V22] STORAGE_PRESSURE — skipping rejected capture [PIPELINE ENFORCEMENT]")
            return None
        tid = str(signal.get("trade_id") or "")
        if tid in _order_multiverse_written:
            return None
        record = build_research_event(
            trade_id=tid,
            epoch_id=_collector_v22_epoch_id(),
            signal_price=price,
            signal_ts=ts,
            direction=direction,
            candles_1m=candles_1m,
            ttl_sec=1800.0,
            submitted=False,
            rejected=True,
            decision_tree=tree,
            rsi_at_signal=rsi_at_signal,
            would_block=would_block or would_block_only,
            would_block_reason=would_block_reason or reason,
            exact_reason=reason,
            atr14_pct=univ.get("atr14_pct_3m"),
            symbol=signal.get("symbol") or signal.get("pair") or "BTCUSD",
            shared_ai_call_id=signal.get("shared_ai_call_id"),
            feature_snapshot=feature_snapshot,
            evaluation_ts=time.time(),
            requested_qty=signal.get("qty"),
            market_microstructure_symbol=BITFINEX_WS_SYMBOL,
            signed_quantity_constraints=signal.get("signed_quantity_constraints"),
            chase_schedule=signal.get("research_chase_schedule") or signal.get("chase_schedule"),
            chase_schedule_authoritative=bool(signal.get("chase_schedule_authoritative")),
            frozen_signal_snapshot_ref=_collector_frozen_signal_ref(signal, tid),
            snapshot_data_dir=str(_data_sync_runtime_root()),
            path_source=path_source,
            entry_grid_anchor=grid_anchor,
        )
        from collector_signal_snapshot import freeze_signal_snapshot
        record["research_signal_snapshot_ref"] = freeze_signal_snapshot(
            record, data_dir=_data_sync_runtime_root(), captured_at=time.time(),
        )
        if would_block_only:
            record["would_block_only"] = True
            record["hard_reject"] = False
        else:
            record["hard_reject"] = True
            record["would_block_only"] = False
        obs = str(record.get("observation_status") or "")
        if not terminal_observation(obs):
            # Keep the recovery payload JSON-only and bounded.  These are the
            # causal fields required to rebuild the same rejected envelope;
            # arbitrary runtime references from ``signal`` do not belong in
            # durable collector state.
            pending_payload = {
                "trade_id": tid,
                "signal_price_at_approve": price,
                "created_ts_ts": ts,
                "expires_ts": ts + 1800.0,
                "final_direction": direction,
                "raw_direction": signal.get("raw_direction") or (
                    "SHORT" if _coerce_invert_on(signal) and direction == "LONG"
                    else "LONG" if _coerce_invert_on(signal) and direction == "SHORT"
                    else direction
                ),
                "invert_on": _coerce_invert_on(signal),
                "edge_score_at_entry": signal.get("edge_score_at_entry"),
                "status": "REJECTED",
                "collector_rejected": True,
                "collector_reject_reason": reason,
                "collector_would_block_only": bool(would_block_only),
                "research_feature_snapshot": copy.deepcopy(record["feature_snapshot_at_signal"]),
                "research_signal_snapshot_ref": record["research_signal_snapshot_ref"],
                "collector_ai": dict(ai or {}),
                "qty": signal.get("qty"),
                "signed_quantity_constraints": copy.deepcopy(signal.get("signed_quantity_constraints")),
                "quantity_constraints_status": copy.deepcopy(signal.get("quantity_constraints_status")),
                "research_chase_schedule": signal.get("research_chase_schedule") or signal.get("chase_schedule"),
                "chase_schedule_authoritative": bool(signal.get("chase_schedule_authoritative")),
                "shared_ai_call_id": signal.get("shared_ai_call_id"),
                "shared_ai_call_ts": signal.get("shared_ai_call_ts"),
                "entry_grid_anchor": grid_anchor,
            }
            previous_payload = _order_multiverse_pending_src.get(tid)
            _order_multiverse_pending_src[tid] = pending_payload
            _order_multiverse_state[tid] = obs
            pending_payload["observation_status"] = obs
            if obs == OBS_SOURCE_UNAVAILABLE:
                _collector_collection_stat("source_unavailable_retries")
            if previous_payload != pending_payload:
                upsert_provisional_event(tid, pending_payload, epoch_id=_collector_v22_epoch_id(),
                                         data_dir=str(_data_sync_runtime_root()))
                logger.info(
                    f"[COLLECTOR_V22] REJECTED provisional trade_id={tid} obs={obs}; awaiting complete tape "
                    f"[PIPELINE ENFORCEMENT]"
                )
            return record
        written, _reason = write_research_event_once(record, data_dir=str(_data_sync_runtime_root()))
        if written:
            _order_multiverse_pending_src.pop(tid, None)
            remove_provisional_event(tid, data_dir=str(_data_sync_runtime_root()))
            _order_multiverse_written.add(tid)
            _collector_collection_stat("rejected_opportunity_written")
            _safe_append_jsonl(OPPORTUNITY_CAPTURE_FILE, record, label="OPPORTUNITY_CAPTURE")
        logger.info(
            f"[COLLECTOR_V22] {record.get('primary_outcome')} trade_id={tid} reason={reason} "
            f"written={written} [PIPELINE ENFORCEMENT]"
        )
        return record
    except Exception as exc:
        logger.warning(f"[OPPORTUNITY CAPTURE] persist failed: {exc} [PIPELINE ENFORCEMENT]")
        return None


def _cycle_3m_flow_and_sr():
    with state_lock:
        sr = dict(state.get("support_resistance") or {})
        paused = bool(state.get("execution_paused"))
        pause_reason = state.get("execution_reason") or ""
        manual = bool(state.get("manual_admin_pause"))
    try:
        delta = get_aggregated(delta_buffer)
    except Exception:
        delta = None
    try:
        imbalance = get_aggregated(imbalance_buffer)
    except Exception:
        imbalance = None
    return {
        "delta_3m": delta,
        "imbalance_3m": imbalance,
        "dist_to_support": sr.get("dist_to_support"),
        "dist_to_resistance": sr.get("dist_to_resistance"),
        "support_price": sr.get("swing_low") or sr.get("s1"),
        "resistance_price": sr.get("swing_high") or sr.get("r1"),
        "paused": paused,
        "pause_reason": pause_reason,
        "manual_pause": manual,
    }


def _record_cycle_3m_universe(
    *,
    outcome: str = "SKIPPED",
    skip_reason: str = None,
    decision: str = None,
    trade_id: str = None,
    direction: str = None,
    candles_1m=None,
    structure_score=None,
):
    """Append one taken-or-skipped 3m universe row. Log-only; never a veto."""
    bucket = cycle_bucket_3m()
    outcome_u = str(outcome or "SKIPPED").upper()
    reservation = (bucket, outcome_u)
    # Six family lanes can enter this recorder concurrently. Reserve only the
    # tiny per-bucket decision here; market calculations and durable writes
    # remain outside both this lock and the collector epoch lock.
    with _cycle_3m_bucket_lock:
        prev = _cycle_3m_written_buckets.get(bucket)
        if prev == "TAKEN":
            return None
        if prev == "SKIPPED" and outcome_u == "SKIPPED" and not decision:
            return None
        if reservation in _cycle_3m_inflight_buckets:
            return None
        _cycle_3m_inflight_buckets.add(reservation)
    try:
        extra = _cycle_3m_flow_and_sr()
        if candles_1m is None:
            # Collector persistence is part of the synchronous post-entry
            # path.  It must never wait on Bitfinex REST retries: snapshot the
            # independently maintained OHLCV cache and report missing source
            # evidence truthfully instead.
            candles_1m = _collector_cached_candles_1m(limit=200)
        candles_1m = list(candles_1m or [])
        snap = compute_3m_universe_snapshot(
            candles_1m,
            dist_to_support=extra.get("dist_to_support"),
            dist_to_resistance=extra.get("dist_to_resistance"),
            structure_score=structure_score,
            delta_3m=extra.get("delta_3m"),
            imbalance_3m=extra.get("imbalance_3m"),
            support_price=extra.get("support_price"),
            resistance_price=extra.get("resistance_price"),
            ts=time.time(),
            cycle_outcome=outcome_u,
            skip_reason=skip_reason,
            decision=decision,
            trade_id=trade_id,
            direction=direction,
        )
        captured_ts = time.time()
        last_source_ts = candle_ts_sec(candles_1m[-1]) if candles_1m else None
        source_age_sec = (
            None if last_source_ts is None else captured_ts - float(last_source_ts)
        )
        source_available = bool(candles_1m) and last_source_ts is not None
        source_fresh = bool(
            source_available
            and 0.0 <= source_age_sec <= float(CANDLE_STALE_SEC)
        )
        evidence_status = (
            "AVAILABLE" if source_fresh
            else "SOURCE_STALE" if source_available
            else "SOURCE_UNAVAILABLE"
        )
        snap.update({
            "evidence_status": evidence_status,
            "calculation_status": "COMPUTED" if source_fresh else "UNKNOWN",
            "source_row_count": len(candles_1m),
            "source_last_candle_ts": last_source_ts,
            "source_age_sec": source_age_sec,
            "source_freshness_limit_sec": float(CANDLE_STALE_SEC),
            "source_unavailable_reason": (
                None if source_fresh
                else "CACHED_1M_SOURCE_STALE" if source_available
                else "CACHED_1M_SOURCE_UNAVAILABLE"
            ),
        })
        if not source_fresh:
            # ``False`` would look like an observed negative conclusion even
            # though no market bars existed.  Preserve the three-state truth.
            snap["would_block_short"] = None
            snap["would_block_reason"] = evidence_status
        _safe_append_jsonl(CYCLE_3M_UNIVERSE_FILE, snap, label="CYCLE_3M_UNIVERSE")
        with _cycle_3m_bucket_lock:
            if _cycle_3m_written_buckets.get(bucket) != "TAKEN" or outcome_u == "TAKEN":
                _cycle_3m_written_buckets[bucket] = outcome_u
            if len(_cycle_3m_written_buckets) > 12:
                oldest = min(_cycle_3m_written_buckets)
                _cycle_3m_written_buckets.pop(oldest, None)
        with state_lock:
            state["last_cycle_3m_universe"] = copy.deepcopy(snap)
        logger.info(
            f"[CYCLE 3M UNIVERSE] {snap.get('line')} bucket={bucket} "
            f"tag={CYCLE_3M_UNIVERSE_TAG} path_tag={PATH_REPLAY_POLICY_TAG} "
            f"[PIPELINE ENFORCEMENT]"
        )
        return snap
    except Exception as exc:
        logger.warning(f"[CYCLE 3M UNIVERSE] record failed: {exc} [PIPELINE ENFORCEMENT]")
        return None
    finally:
        with _cycle_3m_bucket_lock:
            _cycle_3m_inflight_buckets.discard(reservation)


def _maybe_record_heartbeat_cycle_3m():
    extra = _cycle_3m_flow_and_sr()
    reason = None
    if extra.get("manual_pause"):
        reason = "MANUAL_PAUSE"
    elif extra.get("paused"):
        reason = extra.get("pause_reason") or "EXECUTION_PAUSED"
    _record_cycle_3m_universe(outcome="SKIPPED", skip_reason=reason or "HEARTBEAT_CYCLE")


def _stamp_3m_exhaustion_for_ai(ctx: dict) -> dict:
    """Cycle-aligned 3m RSI/Stoch/ADX/ATR/Donchian. Log + payload only; never a hard veto."""
    if not isinstance(ctx, dict):
        return ctx
    try:
        candles_1m = fetch_mtf_candles("1m", limit=200)
        ms = ctx.get("market_context") or {}
        structure = (ms.get("market_structure") or {}) if isinstance(ms, dict) else {}
        extra = _cycle_3m_flow_and_sr()
        snap = compute_3m_universe_snapshot(
            candles_1m or [],
            dist_to_support=ctx.get("dist_to_support") or ctx.get("distance_to_micro_support") or extra.get("dist_to_support"),
            dist_to_resistance=ctx.get("dist_to_resistance") or ctx.get("distance_to_micro_resistance") or extra.get("dist_to_resistance"),
            structure_score=structure.get("structure_score"),
            delta_3m=ctx.get("delta") if ctx.get("delta") is not None else extra.get("delta_3m"),
            imbalance_3m=ctx.get("imbalance") if ctx.get("imbalance") is not None else extra.get("imbalance_3m"),
            support_price=extra.get("support_price"),
            resistance_price=extra.get("resistance_price"),
            ts=time.time(),
            cycle_outcome="CYCLE",
        )
        snap["policy_tag"] = MTF_EXHAUSTION_LOG_V1
        ctx["exhaustion_3m"] = snap
        ctx["cycle_3m_universe"] = snap
        ctx["exhaustion_3m_line"] = snap.get("exhaustion_line") or snap.get("line")
        with state_lock:
            state["last_cycle_3m_universe"] = copy.deepcopy(snap)
        logger.info(
            f"[3M EXHAUSTION] {snap.get('exhaustion_line')} tag={MTF_EXHAUSTION_LOG_V1} "
            f"hard_veto=false path_tag={PATH_REPLAY_POLICY_TAG} "
            f"universe={CYCLE_3M_UNIVERSE_TAG} [PIPELINE ENFORCEMENT]"
        )
    except Exception as exc:
        logger.warning(f"[3M EXHAUSTION] stamp failed: {exc} [PIPELINE ENFORCEMENT]")
        ctx["exhaustion_3m"] = {
            "status": "UNAVAILABLE",
            "bar": "3m",
            "source": "bitfinex_1m_resampled_to_3m",
            "hard_veto": False,
            "policy_tag": MTF_EXHAUSTION_LOG_V1,
        }
        ctx["cycle_3m_universe"] = dict(ctx["exhaustion_3m"])
        ctx["cycle_3m_universe"]["schema"] = CYCLE_3M_UNIVERSE_SCHEMA
        ctx["cycle_3m_universe"]["policy_tag"] = CYCLE_3M_UNIVERSE_TAG
    return ctx

def _structure_allows_bear_continuation(market_context: dict) -> bool:
    mc = market_context or {}
    ms = mc.get("market_structure", {})
    mtf = mc.get("multi_tf", {})
    struct_score = float(ms.get("structure_score") or 0)
    if ms.get("lh_ll_sequence_active"):
        return True
    if struct_score <= -2:
        return True
    if mtf.get("agreement") == "BEAR_ALIGNED":
        return True
    return False


def _structure_allows_bull_continuation(market_context: dict) -> bool:
    mc = market_context or {}
    ms = mc.get("market_structure", {})
    mtf = mc.get("multi_tf", {})
    struct_score = float(ms.get("structure_score") or 0)
    if ms.get("hh_hl_sequence_active"):
        return True
    if struct_score >= 2:
        return True
    if mtf.get("agreement") == "BULL_ALIGNED":
        return True
    return False


def _ai_confirms_sr_continuation(direction: str, ai: dict, market_context: dict) -> bool:
    """AI already receives SR context; APPROVE + factor scores can confirm continuation at S/R."""
    if not ai or str(ai.get("decision", "")).upper() != "APPROVE":
        return False
    bull = int(ai.get("bull_score", 0) or 0)
    bear = int(ai.get("bear_score", 0) or 0)
    mc = market_context or {}
    ms = mc.get("market_structure", {})
    struct_score = float(ms.get("structure_score") or 0)
    mtf_agree = (mc.get("multi_tf") or {}).get("agreement", "MIXED")
    if direction == "SHORT":
        return (
            bear >= bull + MIN_FACTOR_SCORE_MARGIN
            and (mtf_agree == "BEAR_ALIGNED" or struct_score <= SHORT_NEAR_SUPPORT_MIN_STRUCT)
        )
    if direction == "LONG":
        return (
            bull >= bear + MIN_FACTOR_SCORE_MARGIN
            and (mtf_agree == "BULL_ALIGNED" or struct_score >= 2)
        )
    return False


def evaluate_sr_direction_filter(direction: str, sr_state: str, market_context: dict = None, ai: dict = None):
    """
    Phase B soft S/R filter. SOFT mode blocks fade trades at S/R only when structure + MTF oppose;
    strong continuation (and AI factor confirmation after SR-aware APPROVE) is allowed.
    Returns (blocked: bool, reason: str|None).
    """
    if SR_FILTER_MODE == "OFF":
        return False, None
    if direction not in ("LONG", "SHORT"):
        return False, None
    mc = market_context or {}
    ms = mc.get("market_structure", {})
    mtf = mc.get("multi_tf", {})
    struct_score = float(ms.get("structure_score") or 0)
    mtf_agree = mtf.get("agreement", "MIXED")

    if direction == "LONG" and sr_state == "NEAR_RESISTANCE":
        if SR_FILTER_MODE == "HARD" or (BLOCK_LONG_NEAR_RESISTANCE and SR_FILTER_MODE != "SOFT"):
            return True, "LONG_BLOCKED_NEAR_RESISTANCE"
        if _structure_allows_bull_continuation(mc) or _ai_confirms_sr_continuation("LONG", ai, mc):
            return False, "SR_SOFT_ALLOW_BULL_CONTINUATION"
        if struct_score <= -2 and mtf_agree == "BEAR_ALIGNED":
            if is_research_data_collection() and not MTF_BLOCKING_RESEARCH:
                return False, "MTF_BEAR_WARN_NEAR_RESISTANCE"
            return True, "LONG_BLOCKED_NEAR_RESISTANCE"
        if BLOCK_LONG_NEAR_RESISTANCE and not (is_research_data_collection() and not MTF_BLOCKING_RESEARCH):
            return True, "LONG_BLOCKED_NEAR_RESISTANCE"
        return False, None

    if direction == "SHORT" and sr_state == "NEAR_SUPPORT":
        if SR_FILTER_MODE == "HARD":
            return True, "SHORT_BLOCKED_NEAR_SUPPORT"
        if _structure_allows_bear_continuation(mc):
            return False, "SR_SOFT_ALLOW_BEAR_CONTINUATION"
        if _ai_confirms_sr_continuation("SHORT", ai, mc):
            return False, "SR_SOFT_ALLOW_AI_FACTOR_CONTINUATION"
        if struct_score >= 2 and mtf_agree == "BULL_ALIGNED":
            if is_research_data_collection() and not MTF_BLOCKING_RESEARCH:
                return False, "MTF_BULL_WARN_NEAR_SUPPORT"
            return True, "SHORT_BLOCKED_NEAR_SUPPORT"
        if BLOCK_SHORT_NEAR_SUPPORT:
            return True, "SHORT_BLOCKED_NEAR_SUPPORT_WEAK"
        return False, None

    return False, None

def extract_ai_json_blob(text: str) -> dict:
    """Primary JSON block from AI response (markdown fence or inline object)."""
    if not text:
        return {}
    jstart = text.find("```json")
    if jstart >= 0:
        brace = text.find("{", jstart)
        jend = text.find("```", brace + 1)
        chunk = text[brace:jend if jend > brace else len(text)]
        try:
            blob = json.loads(chunk.strip().rstrip("`"))
            return blob if isinstance(blob, dict) else {}
        except Exception:
            pass
    brace = text.find("{")
    while brace >= 0:
        try:
            candidate = json.loads(text[brace:text.find("}", brace) + 1])
            if isinstance(candidate, dict) and (
                "long_score" in candidate
                or "short_score" in candidate
                or "bull_score" in candidate
                or "reasons_for_trade" in candidate
                or "confidence" in candidate
            ):
                return candidate
        except Exception:
            pass
        brace = text.find("{", brace + 1)
    return {}


def derive_research_decision_tier(win_prob: int, long_score: int, short_score: int, direction: str) -> str:
    """Derive execution tier from directional separation, never AI confidence."""
    direction = str(direction or "").upper()
    if direction not in ("LONG", "SHORT"):
        return "REJECT"
    long_score = int(long_score or 0)
    short_score = int(short_score or 0)
    if direction == "LONG":
        gap = long_score - short_score
    else:
        gap = short_score - long_score
    if gap < 5:
        return "REJECT"
    if gap >= 15:
        return "STRONG_APPROVE"
    if gap >= 10:
        return "APPROVE"
    return "SOFT_APPROVE"


def derive_candidate_direction(long_score: int, short_score: int, raw_direction: str = "") -> str:
    """Return a deterministic side, or NO_TRADE when evidence is tied/abstained."""
    try:
        long_value = int(long_score or 0)
    except (TypeError, ValueError):
        long_value = 0
    try:
        short_value = int(short_score or 0)
    except (TypeError, ValueError):
        short_value = 0
    if long_value > short_value:
        return "LONG"
    if short_value > long_value:
        return "SHORT"
    return "NO_TRADE"


def evidence_win_prob(ai_result: Optional[dict]):
    """Win probability for evidence rows: null unless the model actually emitted one.

    ``parse_ai_response_fields`` keeps a placeholder 0 for gating code when the
    prompt does not request a win probability; logging that 0 as a forecast is wrong.
    """
    if not isinstance(ai_result, dict) or ai_result.get("win_prob_status") != "EMITTED":
        return None
    return ai_result.get("win_prob")


def parse_ai_response_fields(text: str) -> dict:
    """Parse one shared call and derive its candidate side from directional scores."""
    json_blob = extract_ai_json_blob(text)
    factors = parse_ai_factor_block(text)

    # Stage 1 Fix #1: when AI returned zero / sub-threshold scores, force REJECT
    # and DO NOT fall through to derive_candidate_direction (which defaults LONG)
    # or derive_research_decision_tier (which would compute a meaningless gap on
    # zeros). This keeps the continuous_shared_direction_gap_v1 policy honest.
    zero_score_reject = bool(factors.get("zero_score_reject"))

    dir_match = re.search(r"Direction:\s*(LONG|SHORT|NO_TRADE|CONFLICTED)", text, re.IGNORECASE)
    raw_direction = dir_match.group(1).upper() if dir_match else None
    if raw_direction not in ("LONG", "SHORT"):
        jd = json_blob.get("direction") or json_blob.get("preferred_direction") or factors.get("preferred_direction")
        if jd:
            raw_direction = str(jd).upper()
    if raw_direction == "CONFLICTED":
        raw_direction = "NO_TRADE"
    if raw_direction not in ("LONG", "SHORT", "NO_TRADE"):
        raw_direction = "NO_TRADE"
    long_score = int(factors.get("long_score") or 0)
    short_score = int(factors.get("short_score") or 0)
    score_direction_mismatch = (
        (raw_direction == "LONG" and short_score > long_score)
        or (raw_direction == "SHORT" and long_score > short_score)
    )
    score_tie = long_score == short_score
    explicit_abstain = raw_direction == "NO_TRADE"
    if zero_score_reject or explicit_abstain or score_direction_mismatch or score_tie:
        # Preserve raw_direction for telemetry but do not derive a candidate
        # side from inert zeros. direction stays NO_TRADE so no lane can spawn.
        direction = "NO_TRADE"
    else:
        direction = derive_candidate_direction(
            factors.get("long_score", 0),
            factors.get("short_score", 0),
            raw_direction,
        )

    match = re.search(r"Win probability:\s*(\d+)", text)
    win_prob = int(match.group(1)) if match else 0
    if win_prob <= 0:
        conf_json = re.search(r'"confidence"\s*:\s*(\d+)', text)
        conf_line = re.search(r"Confidence:\s*(\d+)", text, re.IGNORECASE)
        fallback = int(conf_json.group(1)) if conf_json else (int(conf_line.group(1)) if conf_line else 0)
        if 0 < fallback <= 100:
            win_prob = fallback
    if win_prob <= 0 and json_blob.get("confidence") is not None:
        try:
            win_prob = int(json_blob.get("confidence") or 0)
        except (TypeError, ValueError):
            win_prob = 0

    decision_match = re.search(
        r"Decision:\s*(STRONG_APPROVE|SOFT_APPROVE|SOFT_REJECT|APPROVE|REJECT)",
        text,
        re.IGNORECASE,
    )
    decision = decision_match.group(1).upper() if decision_match else None
    if not decision:
        jd = json_blob.get("decision")
        if jd:
            decision = str(jd).upper()
    parsed_from_json = False
    if zero_score_reject or explicit_abstain or score_direction_mismatch or score_tie:
        # Hard override: bypass derive_research_decision_tier so the gap policy
        # never operates on the inert zeros. Reason is propagated via comment
        # so downstream tranche logs capture the root cause.
        decision = "REJECT"
        parsed_from_json = True
    elif is_research_data_collection() and AI_RESEARCH_MODE_ENABLED:
        decision = derive_research_decision_tier(
            win_prob,
            factors.get("long_score", 0),
            factors.get("short_score", 0),
            direction,
        )
        parsed_from_json = True
    elif not decision:
        decision = "REJECT"

    override_match = re.search(r"Override:\s*(YES|NO)", text, re.IGNORECASE)
    override = override_match.group(1).upper() == "YES" if override_match else False

    return {
        "direction": direction,
        "candidate_direction": direction,
        "raw_direction": raw_direction,
        "win_prob": max(0, min(100, int(win_prob or 0))),
        "win_prob_status": "EMITTED" if int(win_prob or 0) > 0 else "NOT_REQUESTED_BY_PROMPT",
        "confidence_requested": False,
        "decision": decision,
        "override": override,
        "factors": factors,
        "json_blob": json_blob,
        "parsed_decision_from_json": parsed_from_json,
        "zero_score_reject": zero_score_reject,
        "explicit_abstain": explicit_abstain,
        "score_direction_mismatch": score_direction_mismatch,
        "score_tie": score_tie,
    }


def ai_commit_flags(ai_result: dict) -> dict:
    """Commit/abstain facts of one shared call (decision-snapshot telemetry, logged on every call).

    Committed = explicit LONG/SHORT, scores agree with that side, and the score
    gap is at least ``AI_COMMIT_MIN_SCORE_GAP``.
    """
    ai_result = ai_result or {}
    raw = str(ai_result.get("raw_direction") or "").upper()
    try:
        long_s = float(ai_result.get("long_score"))
        short_s = float(ai_result.get("short_score"))
    except (TypeError, ValueError):
        long_s = short_s = None
    gap = abs(long_s - short_s) if long_s is not None else None
    score_side = None if gap is None or gap == 0 else ("LONG" if long_s > short_s else "SHORT")
    abstain = raw not in ("LONG", "SHORT")
    mismatch = (not abstain) and score_side is not None and raw != score_side
    committed = (not abstain and not mismatch and not ai_result.get("ai_error")
                 and gap is not None and gap >= AI_COMMIT_MIN_SCORE_GAP)
    return {
        "explicit_abstain": abstain,
        "score_direction_mismatch": mismatch,
        "score_tie": gap == 0,
        "score_gap": gap,
        "ai_committed": bool(committed),
        "commit_rule": f"EXPLICIT_RAW_SIDE_EQUALS_SCORE_LED_AND_GAP_GE_{AI_COMMIT_MIN_SCORE_GAP:g}",
    }


def parse_ai_trade_planner(text: str, json_blob: dict = None) -> dict:
    """Extract trade-planner fields from AI JSON block (entry zone, MFE/MAE expectations)."""
    plan = {
        "entry_zone_low": None,
        "entry_zone_high": None,
        "limit_price": None,
        "entry_limit": None,
        "expected_mfe": None,
        "expected_mae": None,
        "reversal_probability": None,
        "exit_style": None,
        "confidence": None,
    }
    blob = json_blob
    if blob is None and text:
        jstart = text.find("```json")
        if jstart >= 0:
            brace = text.find("{", jstart)
            jend = text.find("```", brace + 1)
            chunk = text[brace:jend if jend > brace else len(text)]
            try:
                blob = json.loads(chunk.strip().rstrip("`"))
            except Exception:
                blob = None
    if isinstance(blob, dict):
        plan["entry_zone_low"] = blob.get("entry_zone_low")
        plan["entry_zone_high"] = blob.get("entry_zone_high")
        plan["limit_price"] = blob.get("limit_price") or blob.get("entry_limit")
        plan["entry_limit"] = blob.get("entry_limit") or blob.get("limit_price")
        plan["expected_mfe"] = blob.get("expected_mfe")
        plan["expected_mae"] = blob.get("expected_mae")
        plan["reversal_probability"] = blob.get("reversal_probability")
        plan["exit_style"] = blob.get("exit_style")
        plan["confidence"] = blob.get("confidence")
    return plan


def parse_ai_factor_block(text: str) -> dict:
    """Extract Phase C bull/bear scores and reason lists from AI response."""
    factors = {
        "reasons_for": [],
        "reasons_against": [],
        "bull_score": 0,
        "bear_score": 0,
        "long_score": 0,
        "short_score": 0,
        "preferred_direction": None,
        "factor_parse_ok": False,
        # Stage 1 Fix #1: flagged when AI returns scores summing < 50, i.e. the
        # model is not committed to either side. parse_ai_response_fields honors
        # this BEFORE derive_candidate_direction / derive_research_decision_tier
        # so the continuous_shared_direction_gap_v1 policy never sees inert zeros.
        "zero_score_reject": False,
    }
    if not text:
        return factors
    json_blob = None
    jstart = text.find("```json")
    if jstart >= 0:
        brace = text.find("{", jstart)
        jend = text.find("```", brace + 1)
        chunk = text[brace:jend if jend > brace else len(text)]
        try:
            json_blob = json.loads(chunk.strip().rstrip("`"))
        except Exception:
            json_blob = None
    if json_blob is None:
        brace = text.find("{")
        while brace >= 0:
            try:
                candidate = json.loads(text[brace:text.find("}", brace) + 1])
                if isinstance(candidate, dict) and (
                    "long_score" in candidate
                    or "short_score" in candidate
                    or "bull_score" in candidate
                    or "reasons_for_trade" in candidate
                ):
                    json_blob = candidate
                    break
            except Exception:
                pass
            brace = text.find("{", brace + 1)
    if isinstance(json_blob, dict):
        reason = json_blob.get("reason")
        factors["reasons_for"] = json_blob.get("reasons_for_trade") or json_blob.get("reasons_for") or ([reason] if reason else [])
        factors["reasons_against"] = json_blob.get("reasons_against_trade") or json_blob.get("reasons_against") or []
        def safe_score(name):
            try:
                value = int(float(json_blob.get(name, 0) or 0))
            except (TypeError, ValueError):
                factors["score_parse_error"] = f"INVALID_{name.upper()}"
                return 0
            if value < 0 or value > 100:
                factors["score_parse_error"] = f"OUT_OF_RANGE_{name.upper()}"
                return 0
            return value
        factors["bull_score"] = safe_score("bull_score")
        factors["bear_score"] = safe_score("bear_score")
        factors["long_score"] = safe_score("long_score")
        factors["short_score"] = safe_score("short_score")
        if factors["long_score"] <= 0 and factors["bull_score"] > 0:
            factors["long_score"] = factors["bull_score"] * 10
        if factors["short_score"] <= 0 and factors["bear_score"] > 0:
            factors["short_score"] = factors["bear_score"] * 10
        pref = json_blob.get("preferred_direction") or json_blob.get("direction")
        if pref:
            factors["preferred_direction"] = str(pref).upper()
        factors["factor_parse_ok"] = True
        _apply_zero_score_reject_check(factors)
        if factors.get("score_parse_error"):
            factors["zero_score_reject"] = True
        return factors
    bull_m = re.search(r"Bull\s*score:\s*(\d+)", text, re.IGNORECASE)
    bear_m = re.search(r"Bear\s*score:\s*(\d+)", text, re.IGNORECASE)
    if bull_m:
        factors["bull_score"] = int(bull_m.group(1))
    if bear_m:
        factors["bear_score"] = int(bear_m.group(1))
    long_m = re.search(r"Long\s*score:\s*(\d+)", text, re.IGNORECASE)
    short_m = re.search(r"Short\s*score:\s*(\d+)", text, re.IGNORECASE)
    if long_m:
        factors["long_score"] = int(long_m.group(1))
    if short_m:
        factors["short_score"] = int(short_m.group(1))
    if factors["long_score"] <= 0 and factors["bull_score"] > 0:
        factors["long_score"] = factors["bull_score"] * 10
    if factors["short_score"] <= 0 and factors["bear_score"] > 0:
        factors["short_score"] = factors["bear_score"] * 10
    if re.search(r"reasons?_for", text, re.IGNORECASE):
        block = re.search(r"reasons?_for(?:_trade)?[:\s]+(.*?)(?:reasons?_against|Bull\s*score|$)", text, re.IGNORECASE | re.DOTALL)
        if block:
            factors["reasons_for"] = [ln.strip("- ").strip() for ln in block.group(1).splitlines() if ln.strip() and not ln.strip().startswith("reasons")]
    if re.search(r"reasons?_against", text, re.IGNORECASE):
        block = re.search(r"reasons?_against(?:_trade)?[:\s]+(.*?)(?:Bull\s*score|Direction:|$)", text, re.IGNORECASE | re.DOTALL)
        if block:
            factors["reasons_against"] = [ln.strip("- ").strip() for ln in block.group(1).splitlines() if ln.strip() and not ln.strip().lower().startswith("bull")]
    factors["factor_parse_ok"] = (factors["bull_score"] > 0 or factors["bear_score"] > 0 or len(factors["reasons_for"]) > 0)

    _apply_zero_score_reject_check(factors)
    return factors


def _apply_zero_score_reject_check(factors: dict) -> None:
    """Stage 1 Fix #1: flag inert AI score payloads in-place.

    DeepSeek was observed returning long_score=0, short_score=0 on 100% of
    calls, making the continuous_shared_direction_gap_v1 gap policy inert
    and letting direction fall through to derive_candidate_direction() which
    defaults to LONG. A meaningful directional call must have at least one
    side > 50 (the higher side is the picked direction); if both are < 50
    the model is not committed. parse_ai_response_fields honors this flag
    BEFORE derive_candidate_direction / derive_research_decision_tier run.
    """
    if factors.get("factor_parse_ok") and (int(factors.get("long_score") or 0) + int(factors.get("short_score") or 0)) < 50:
        factors["zero_score_reject"] = True
        logger.warning(
            f"[AI_FACTOR_BLOCK] AI_RETURNED_ZERO_SCORES long_score={factors.get('long_score')} "
            f"short_score={factors.get('short_score')} sum<50 - forcing REJECT before gap policy "
            f"[PIPELINE ENFORCEMENT]"
        )

def ai_decision_should_execute(ai: dict) -> bool:
    """True when AI tier maps to real limit-order execution."""
    if not ai or ai.get("ai_error"):
        return False
    tier = str(ai.get("execution_tier") or ai.get("research_soft") or ai.get("decision") or "").upper()
    if tier in AI_EXECUTE_TIERS:
        return True
    return bool(ai.get("approved")) and str(ai.get("decision", "")).upper() == "APPROVE"


def normalize_research_ai_decision(ai_result: dict) -> dict:
    """Research 5-tier AI: STRONG_APPROVE/APPROVE/SOFT_APPROVE execute; SOFT_REJECT/REJECT shadow."""
    if not (is_research_data_collection() and AI_RESEARCH_MODE_ENABLED):
        return ai_result
    dec = str(ai_result.get("decision", "")).upper()
    ai_result["raw_decision"] = dec
    if dec in AI_EXECUTE_TIERS:
        ai_result["pre_gate_decision"] = dec
        ai_result["decision"] = "APPROVE"
        ai_result["approved"] = True
        ai_result["research_soft"] = dec
        ai_result["execution_tier"] = dec
    elif dec == "SOFT_REJECT":
        ai_result["decision"] = "REJECT"
        ai_result["approved"] = False
        ai_result["research_soft"] = "SOFT_REJECT"
        ai_result["execution_tier"] = "SOFT_REJECT"
    elif dec == "REJECT":
        ai_result["approved"] = False
        ai_result["execution_tier"] = "REJECT"
    return ai_result


def apply_phase_c_factor_gate(ai_result: dict) -> dict:
    """Reject APPROVE when declared direction conflicts with bull/bear scores."""
    if is_research_data_collection() and AI_RESEARCH_MODE_ENABLED:
        return ai_result
    if not PHASE_C_FACTOR_GATE_ENABLED:
        return ai_result
    direction = ai_result.get("direction")
    factors = ai_result.get("factors") or {}
    bull = int(factors.get("bull_score", 0) or 0)
    bear = int(factors.get("bear_score", 0) or 0)
    margin = MIN_FACTOR_SCORE_MARGIN
    if ai_result.get("decision") != "APPROVE" or direction in (None, "NO_TRADE"):
        return ai_result
    gate_reason = None
    if direction == "LONG" and bull < bear + margin:
        gate_reason = f"FACTOR_GATE_LONG bull={bull} bear={bear}"
    elif direction == "SHORT" and bear < bull + margin:
        gate_reason = f"FACTOR_GATE_SHORT bull={bull} bear={bear}"
    if gate_reason:
        logger.warning(f"[PHASE-C] {gate_reason} - overriding APPROVE to REJECT [PIPELINE ENFORCEMENT]")
        ai_result["decision"] = "REJECT"
        ai_result["approved"] = False
        ai_result["factor_gate"] = gate_reason
        ai_result["pre_gate_decision"] = "APPROVE"
    return ai_result


def apply_trend_hierarchy_gate(ctx: dict, ai_result: dict) -> dict:
    """Research: downgrade weak counter-trend APPROVEs to SOFT_REJECT (shadow study, no live fill)."""
    if not (is_research_data_collection() and AI_RESEARCH_MODE_ENABLED):
        return ai_result
    if ai_result.get("ai_error"):
        return ai_result
    tier = str(ai_result.get("execution_tier") or ai_result.get("research_soft") or ai_result.get("decision") or "").upper()
    if tier not in AI_EXECUTE_TIERS:
        return ai_result
    direction = str(ai_result.get("direction") or "").upper()
    if direction not in ("LONG", "SHORT"):
        return ai_result

    mc = ctx.get("market_context") or {}
    mtf = mc.get("multi_tf") or {}
    ms = mc.get("market_structure") or {}
    ts = mc.get("trend_strength") or {}
    adx = float(ts.get("adx") or ctx.get("adx") or 0)
    mtf_agree = str(mtf.get("agreement") or "").upper()
    struct_bias = str(ms.get("bias") or ms.get("structure_bias") or "").upper()
    struct_score = float(ms.get("structure_score") or 0)
    ema_stack = str((mc.get("ema_alignment") or {}).get("stack") or "").upper()

    factors = ai_result.get("factors") or {}
    long_s = int(factors.get("long_score") or ai_result.get("long_score") or 0)
    short_s = int(factors.get("short_score") or ai_result.get("short_score") or 0)
    if long_s <= 0 and short_s <= 0:
        bull = int(factors.get("bull_score") or ai_result.get("bull_score") or 0)
        bear = int(factors.get("bear_score") or ai_result.get("bear_score") or 0)
        long_s = bull * 10
        short_s = bear * 10

    bear_continuation = (
        mtf_agree == "BEAR_ALIGNED"
        and ("BEAR" in struct_bias or struct_score <= -2)
        and ("BEAR" in ema_stack or ema_stack in ("BEARISH", "BEAR"))
        and adx >= 25
    )
    bull_continuation = (
        mtf_agree == "BULL_ALIGNED"
        and ("BULL" in struct_bias or struct_score >= 2)
        and ("BULL" in ema_stack or ema_stack in ("BULLISH", "BULL"))
        and adx >= 25
    )

    struct_shift = str(ctx.get("market_structure_shift") or "").upper()
    higher_low = bool(ctx.get("higher_low_detected"))
    lower_high = bool(ctx.get("lower_high_detected"))
    sr_bias = str(ctx.get("sr_bias") or "").upper()

    gate = None
    if direction == "LONG" and bear_continuation:
        weak_reversal = higher_low and "BULL" not in struct_shift and "REVERSAL" not in struct_shift
        if long_s < short_s + 10 or weak_reversal or (sr_bias == "SHORT_PREFERRED" and long_s < short_s + 5):
            gate = (
                f"TREND_HIERARCHY_COUNTER_TREND_LONG long={long_s} short={short_s} "
                f"adx={adx:.0f} mtf={mtf_agree} struct={struct_bias}"
            )
    elif direction == "SHORT" and bull_continuation:
        weak_reversal = lower_high and "BEAR" not in struct_shift and "REVERSAL" not in struct_shift
        if short_s < long_s + 10 or weak_reversal or (sr_bias == "LONG_PREFERRED" and short_s < long_s + 5):
            gate = (
                f"TREND_HIERARCHY_COUNTER_TREND_SHORT long={long_s} short={short_s} "
                f"adx={adx:.0f} mtf={mtf_agree} struct={struct_bias}"
            )

    if gate:
        logger.warning(
            f"[TREND_HIERARCHY] {gate} - downgrade to SOFT_REJECT (shadow study) [PIPELINE ENFORCEMENT]"
        )
        ai_result["pre_trend_hierarchy_decision"] = ai_result.get("decision")
        ai_result["trend_hierarchy_gate"] = gate
        ai_result["decision"] = "SOFT_REJECT"
        ai_result["approved"] = False
        ai_result["research_soft"] = "SOFT_REJECT"
        ai_result["execution_tier"] = "SOFT_REJECT"
    return ai_result


def apply_structure_agreement_gate(ctx: dict, ai_result: dict) -> dict:
    """Stage 1 Fix #3: hard reject when AI direction fights confirmed market structure.

    Blocks the empirically worst loss pattern (14 of 20 recent LONG calls were
    against BEAR_CONTINUATION structure). Unlike apply_trend_hierarchy_gate
    (which only downgrades weak counter-trend APPROVEs to SOFT_REJECT for
    shadow study), this gate fires regardless of trend-continuation context
    and forces a hard REJECT so no lane can spawn an order against structure.
    Honored only for execute-tier verdicts; shadow data collection still flows.
    """
    if not (is_research_data_collection() and AI_RESEARCH_MODE_ENABLED):
        return ai_result
    if ai_result.get("ai_error"):
        return ai_result
    tier = str(ai_result.get("execution_tier") or ai_result.get("research_soft") or ai_result.get("decision") or "").upper()
    if tier not in AI_EXECUTE_TIERS:
        return ai_result
    direction = str(ai_result.get("direction") or "").upper()
    if direction not in ("LONG", "SHORT"):
        return ai_result

    upgrade = ctx.get("ai_input_upgrade") or {}
    structure_shift = str(upgrade.get("market_structure_shift") or ctx.get("market_structure_shift") or "").upper()
    market_ctx = ctx.get("market_context") or {}
    market_struct = market_ctx.get("market_structure") or {}
    structure_score = float(market_struct.get("structure_score") or 0)

    gate = None
    if direction == "LONG" and ("BEAR" in structure_shift or structure_score <= -2):
        gate = (
            f"AI_LONG_VS_BEAR_STRUCTURE shift={structure_shift} "
            f"structure_score={structure_score}"
        )
    elif direction == "SHORT" and ("BULL" in structure_shift or structure_score >= 2):
        gate = (
            f"AI_SHORT_VS_BULL_STRUCTURE shift={structure_shift} "
            f"structure_score={structure_score}"
        )

    if gate:
        logger.warning(
            f"[STRUCTURE_AGREEMENT] {gate} - hard REJECT (no lane spawn) [PIPELINE ENFORCEMENT]"
        )
        ai_result["pre_structure_agreement_decision"] = ai_result.get("decision")
        ai_result["structure_agreement_gate"] = gate
        ai_result["decision"] = "REJECT"
        ai_result["approved"] = False
        ai_result["research_soft"] = "REJECT"
        ai_result["execution_tier"] = "REJECT"
    return ai_result


def weak_countertrend_conflict(ctx: dict, direction: str) -> str:
    """Return a low-ADX contradiction code, otherwise an empty string."""
    direction = str(direction or "").upper()
    if direction not in ("LONG", "SHORT"):
        return "NO_EXECUTABLE_DIRECTION"
    mc = ctx.get("market_context") or {}
    trend = mc.get("trend_strength") or {}
    ema = mc.get("ema_alignment") or {}
    structure = mc.get("market_structure") or {}
    mtf = mc.get("multi_tf") or {}
    upgrade = ctx.get("ai_input_upgrade") or {}
    try:
        adx = float(trend.get("adx") or ctx.get("adx") or 0)
    except (TypeError, ValueError):
        adx = 0.0
    if adx >= 20:
        return ""
    stack = str(ema.get("stack") or "").upper()
    ema_bull = bool(ema.get("stack_bull")) or stack in ("BULL", "BULLISH")
    ema_bear = bool(ema.get("stack_bear")) or stack in ("BEAR", "BEARISH")
    structure_score = float(structure.get("structure_score") or 0)
    agreement = str(mtf.get("agreement") or "").upper()
    sr_bias = str(ctx.get("sr_bias") or "").upper()
    micro_confirmed = bool(upgrade.get("micro_structure_confirmed", ctx.get("micro_structure_confirmed")))
    higher_low = bool(upgrade.get("higher_low_detected", ctx.get("higher_low_detected")))
    lower_high = bool(upgrade.get("lower_high_detected", ctx.get("lower_high_detected")))
    if direction == "SHORT":
        conflicts = ema_bull or structure_score >= 2 or sr_bias == "LONG_PREFERRED" or higher_low
        confirmed = agreement == "BEAR_ALIGNED" and (ema_bear or structure_score <= -2) and micro_confirmed
        if conflicts and not confirmed:
            return f"WEAK_COUNTERTREND_SHORT_ADX_{adx:.1f}"
    else:
        conflicts = ema_bear or structure_score <= -2 or sr_bias == "SHORT_PREFERRED" or lower_high
        confirmed = agreement == "BULL_ALIGNED" and (ema_bull or structure_score >= 2) and micro_confirmed
        if conflicts and not confirmed:
            return f"WEAK_COUNTERTREND_LONG_ADX_{adx:.1f}"
    return ""


def apply_weak_countertrend_gate(ctx: dict, ai_result: dict) -> dict:
    """Fail closed on weak countertrend entries while preserving shadow evidence."""
    if ai_result.get("ai_error"):
        return ai_result
    tier = str(ai_result.get("execution_tier") or ai_result.get("research_soft") or ai_result.get("decision") or "").upper()
    if tier not in AI_EXECUTE_TIERS:
        return ai_result
    reason = weak_countertrend_conflict(ctx, ai_result.get("direction"))
    if reason:
        ai_result["pre_weak_countertrend_decision"] = ai_result.get("decision")
        ai_result["weak_countertrend_gate"] = reason
        ai_result["decision"] = "REJECT"
        ai_result["approved"] = False
        ai_result["research_soft"] = "REJECT"
        ai_result["execution_tier"] = "REJECT"
        logger.warning(f"[WEAK COUNTERTREND] {reason} - hard REJECT [PIPELINE ENFORCEMENT]")
    return ai_result


def double_confirm_ai(original_ai, ctx):
    try:
        logger.info("[DOUBLE AI] Starting confirmation [PIPELINE ENFORCEMENT]")
        confirm_prompt = f"""Original decision: Direction={original_ai.get('direction')} WinProb={original_ai.get('win_prob')} Decision={original_ai.get('decision')}
Context: {json.dumps(ctx, indent=2)}
Verify if still correct. Return same format."""
        text, _latency = call_deepseek_api(
            [{"role": "user", "content": confirm_prompt}],
            temperature=0.3,
            purpose="trading_confirmation",
        )
        dir_match = re.search(r"Direction:\s*(LONG|SHORT|NO_TRADE)", text, re.IGNORECASE)
        direction = dir_match.group(1).upper() if dir_match else original_ai.get("direction")
        match = re.search(r"Win probability:\s*(\d+)", text)
        win_prob = int(match.group(1)) if match else original_ai.get("win_prob")
        decision_match = re.search(r"Decision:\s*(APPROVE|REJECT)", text, re.IGNORECASE)
        decision = decision_match.group(1).upper() if decision_match else original_ai.get("decision")
        if decision != original_ai.get("decision"):
            logger.warning(f"[AI CONFLICT] Original {original_ai.get('decision')} vs Confirm {decision} - safer REJECT [PIPELINE ENFORCEMENT]")
            return {"win_prob": min(original_ai.get("win_prob",0), win_prob), "direction": "NO_TRADE", "decision": "REJECT", "override": False, "comment": text, "ai_error": False, "factors": {}, "source": "DOUBLE_CONFIRM", "approved": False}
        return original_ai
    except Exception as e:
        logger.error(f"[DOUBLE AI] Failed: {e} - using original [PIPELINE ENFORCEMENT]")
        return original_ai

def _format_melbourne_hm(ts_str: str) -> str:
    """UTC ISO or epoch string → `2026-06-24 18:37:55 AEST` (matches Agent Hub @dcf/utils)."""
    if not ts_str or ts_str == "-":
        return "-"
    s = str(ts_str).strip()
    if s.endswith("Melbourne") or " AEST" in s or " AEDT" in s:
        return s
    try:
        if isinstance(ts_str, (int, float)) or (s.replace(".", "", 1).isdigit() and len(s) <= 12):
            dt = datetime.fromtimestamp(float(s), tz=timezone.utc)
        else:
            ts = s.replace("Z", "+00:00")
            if "+" not in ts and ts.count(":") >= 2:
                ts = ts + "+00:00"
            dt = datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
        mel = dt.astimezone(ZoneInfo("Australia/Melbourne"))
        abbrev = mel.strftime("%Z")
        return mel.strftime(f"%Y-%m-%d %H:%M:%S {abbrev}")
    except Exception:
        return s

def _session_ai_history(in_memory: list, limit: int = 50) -> list:
    """Return in-memory AI history rows from current bot session only."""
    session_start = bot_start_time or 0.0
    filtered = []
    for row in in_memory or []:
        ts = parse_ts(row.get("time") or row.get("ts") or "")
        if ts >= session_start - 1.0:
            filtered.append(row)
    return filtered[-limit:]

def _research_gates_breakdown(signal, ai, edge_score) -> dict:
    """Frozen gate flags for approved_but_rejected.jsonl."""
    feat = signal.get("features") or {}
    gates = capture_entry_gate_snapshot(signal, ai, edge_score, feat)
    gs = signal.get("golden_stack_eval") or {}
    return {
        "entry_gates": gates,
        "golden_stack_eval": gs,
        "would_fail_mtf": gates.get("would_fail_mtf"),
        "would_fail_chop": gates.get("would_fail_chop"),
        "would_fail_adx": gates.get("would_fail_adx"),
        "would_fail_spread": gates.get("would_fail_spread"),
        "would_fail": gs.get("would_fail") or golden_stack_would_fail_list(gs),
    }


def increment_pipeline_funnel(counter: str, n: int = 1):
    """In-memory session funnel counters for dashboard diagnostics."""
    with state_lock:
        fc = state.setdefault("pipeline_funnel_counters", {})
        fc[counter] = int(fc.get(counter, 0)) + int(n)


def log_lane_opportunity_event(
    lane: str,
    event: str,
    trade_id: str = None,
    direction: str = None,
    ai_prob: float = None,
    edge_score: float = None,
    block_reason: str = None,
    shadow_pnl: float = None,
    details: dict = None,
):
    """Per-lane opportunity capture — APPROVE → ORDER → FILL attribution for Pathway Lab."""
    try:
        lane = str(lane or LEGACY_ADOPTION_LANE).upper()
        row = {
            "schema": "lane_opportunity_v1",
            "ts": utc_iso(),
            "lane": lane,
            "event": event,
            "trade_id": trade_id,
            "direction": direction,
            "ai_prob": ai_prob,
            "edge_score": edge_score,
            "block_reason": block_reason,
            "shadow_pnl_usd": shadow_pnl,
            "details": copy.deepcopy(details or {}),
            "bot_version": EXECUTION_FIX_VERSION,
            "analyzer_sync_id": ANALYZER_SYNC_ID,
        }
        with state_lock:
            lc = state.setdefault("lane_opportunity_counters", {})
            bucket = lc.setdefault(lane, {
                "approves": 0, "orders": 0, "fills": 0, "closes": 0,
                "approve_not_traded": 0, "blocks": 0,
            })
            if event == "APPROVE":
                bucket["approves"] = int(bucket.get("approves", 0)) + 1
            elif event == "ORDER_SUBMITTED":
                bucket["orders"] = int(bucket.get("orders", 0)) + 1
            elif event == "FILLED":
                bucket["fills"] = int(bucket.get("fills", 0)) + 1
            elif event == "CLOSED":
                bucket["closes"] = int(bucket.get("closes", 0)) + 1
            elif event == "APPROVE_NOT_TRADED":
                bucket["approve_not_traded"] = int(bucket.get("approve_not_traded", 0)) + 1
            elif event in ("EXECUTION_BLOCK", "WOULD_BLOCK"):
                bucket["blocks"] = int(bucket.get("blocks", 0)) + 1
            elif event in ("LANE_DISABLED", "SPAWN_SKIPPED"):
                bucket["spawn_skipped"] = int(bucket.get("spawn_skipped", 0)) + 1
        rotate_log(LANE_OPPORTUNITY_CAPTURE_FILE)
        _safe_append_jsonl(LANE_OPPORTUNITY_CAPTURE_FILE, row, label="LANE_OPPORTUNITY")

    except Exception as e:
        logger.error(f"[LANE_OPPORTUNITY] log failed: {e}")






















