def capture_near_miss_on_approve(signal, ai, edge_score, ctx):
    """On APPROVE, log when edge/ADX/spread are within near-miss margins."""
    if not (_sole_ai_research_mode() and is_research_data_collection()):
        return
    direction = str(signal.get("final_direction") or ai.get("direction") or "LONG").upper()
    edge_score = float(edge_score or 0)
    eff_thr = float(signal.get("effective_threshold_at_entry") or get_edge_threshold())
    edge_margin = edge_score - eff_thr
    if 0 <= edge_margin < 0.1:
        log_near_miss(signal, ai, "edge", edge_margin, edge_score)
    mc = (ctx or signal.get("context") or {}).get("market_context") or {}
    adx = float((mc.get("trend_strength") or {}).get("adx") or 0)
    adx_margin = adx - RESEARCH_ADX_MIN
    if 0 <= adx_margin < 1.0:
        log_near_miss(signal, ai, "adx", adx_margin, edge_score)
    spread = compute_directional_spread(direction, ai)
    spread_margin = spread - 1
    if 0 <= spread_margin < 1:
        log_near_miss(signal, ai, "spread", spread_margin, edge_score)


HORIZON_OUTCOME_SECS = {
    "1m": 60,
    "2m": 120,
    "3m": 180,
    "5m": 300,
    "10m": 600,
    "15m": 900,
    "20m": 1200,
    "30m": 1800,
    "45m": 2700,
    "60m": 3600,
    "90m": 5400,
    "120m": 7200,
}


def compute_horizon_outcomes_from_replay(buf: dict) -> dict:
    """MFE/MAE and fixed-horizon outcome % from replay ticks where computable."""
    ticks = sorted(buf.get("ticks", []), key=lambda x: x.get("seq", 0))
    start_price = _buf_float(buf.get("start_price"), 0)
    direction = str(buf.get("direction") or "LONG").upper()
    if not ticks or start_price <= 0:
        return {}
    dir_factor = 1 if direction == "LONG" else -1
    leverage = _buf_int(buf.get("leverage"), _replay_leverage_default())
    mfe = 0.0
    mae = 0.0
    horizons = {}
    for tick in ticks:
        t = _buf_float(tick.get("t"), 0)
        p = _buf_float(tick.get("price"), 0)
        if p <= 0:
            continue
        unreal = tick.get("unreal_pct")
        if unreal is None:
            unreal = ((p - start_price) / start_price) * dir_factor * leverage * 100
        else:
            unreal = _buf_float(unreal, 0)
        mfe = max(mfe, unreal)
        mae = min(mae, unreal)
        for label, sec in HORIZON_OUTCOME_SECS.items():
            key = f"outcome_{label}_pct"
            if key not in horizons and t >= sec:
                horizons[key] = round(unreal, 4)
    # A horizon without a tick at or beyond its boundary is UNKNOWN. Never
    # substitute the last observed value, which fabricates future evidence.
    for label in HORIZON_OUTCOME_SECS:
        horizons.setdefault(f"outcome_{label}_pct", None)
    return {"mfe_pct": round(mfe, 4), "mae_pct": round(mae, 4), **horizons}


def start_reversal_study_replay(ctx: dict, ai: dict, research_lane: str):
    """Track reversal_risk_score vs 30m MFE/MAE for offline validation."""
    if not is_research_data_collection():
        return True
    upgrade = ctx.get("ai_input_upgrade") or {}
    reversal_risk = upgrade.get("reversal_risk_score") or ctx.get("reversal_risk_score")
    if reversal_risk is None:
        return True
    trade_id = ai.get("trade_id") or ctx.get("trade_id")
    price = float(ctx.get("price") or state.get("price") or 0)
    if not trade_id or price <= 0:
        return True
    direction = str(ai.get("direction") or "LONG").upper()
    if direction not in ("LONG", "SHORT"):
        direction = "LONG"
    study_id = f"rev-{trade_id}"
    row = {
        "schema": "reversal_study_v1",
        "ts": utc_iso(),
        "study_id": study_id,
        "trade_id": trade_id,
        "reversal_risk": int(reversal_risk),
        "entry_stage": upgrade.get("entry_stage") or ctx.get("entry_stage"),
        "trend_health_state": upgrade.get("trend_health_state") or ctx.get("trend_health_state"),
        "research_lane": research_lane,
        "direction": direction,
        "price": price,
        "bot_version": EXECUTION_FIX_VERSION,
    }
    if not _safe_append_jsonl(REVERSAL_STUDY_FILE, row, label="REVERSAL_STUDY"):
        return False
    started = start_replay_buffer(
        study_id,
        price,
        lane="reversal_study",
        direction=direction,
        leverage=int(state.get("leverage", DEFAULT_RESEARCH_LEVERAGE)),
        margin_usdt=float(FIXED_MARGIN_USDT),
        reversal_risk=int(reversal_risk),
        source_trade_id=trade_id,
        research_lane=research_lane,
        entry_stage=upgrade.get("entry_stage") or ctx.get("entry_stage"),
        trend_health_state=upgrade.get("trend_health_state") or ctx.get("trend_health_state"),
    )
    if not started:
        return False
    log_reversal_research(
        study_id,
        {
            "source_trade_id": trade_id,
            "reversal_risk": int(reversal_risk),
            "direction": direction,
            "research_lane": research_lane,
            "entry_stage": upgrade.get("entry_stage"),
            "trend_health_state": upgrade.get("trend_health_state"),
        },
        {},
        phase="start",
    )
    return True


def log_reversal_research(study_id: str, buf: dict, horizons: dict, phase: str = "outcome"):
    """Dedicated reversal dataset: risk score vs 15m/30m/60m MFE/MAE."""
    mfe = horizons.get("mfe_pct")
    mae = horizons.get("mae_pct")
    o15 = horizons.get("outcome_15m_pct")
    o30 = horizons.get("outcome_30m_pct")
    o60 = horizons.get("outcome_1h_pct") or horizons.get("outcome_60m_pct")
    ref = o30 if o30 is not None else o15
    result = "WIN" if ref is not None and float(ref) > 0 else "LOSS"
    row = {
        "schema": "reversal_study_v2",
        "phase": phase,
        "ts": utc_iso(),
        "study_id": study_id,
        "trade_id": buf.get("source_trade_id"),
        "reversal_risk": buf.get("reversal_risk"),
        "future_mfe_15m": o15,
        "future_mfe_30m": o30,
        "future_mfe_60m": o60,
        "future_mae_15m": mae if o15 is not None else None,
        "future_mae_30m": mae,
        "future_mae_60m": mae,
        "mfe_pct": mfe,
        "mae_pct": mae,
        "result": result,
        "outcome": result,
        "direction": buf.get("direction"),
        "research_lane": buf.get("research_lane"),
        "entry_stage": buf.get("entry_stage"),
        "trend_health_state": buf.get("trend_health_state"),
        "horizons": horizons,
        "bot_version": EXECUTION_FIX_VERSION,
        "analyzer_sync_id": ANALYZER_SYNC_ID,
    }
    if _safe_append_jsonl(REVERSAL_STUDY_FILE, row, label="REVERSAL_RESEARCH"):
        logger.info(
            f"[REVERSAL_STUDY] {phase} study_id={study_id} risk={buf.get('reversal_risk')} "
            f"15m={o15} 30m={o30} 60m={o60} result={result} [PIPELINE ENFORCEMENT]"
        )


def finalize_reversal_study(study_id: str, buf: dict):
    horizons = compute_horizon_outcomes_from_replay(buf)
    log_reversal_research(study_id, buf, horizons, phase="outcome")
    close_replay_buffer(study_id)


