def start_soft_reject_shadow_replay(ctx, ai, edge_score, research_lane, block_tag):
    """AI REJECT: shadow replay buffer for outcome collection without extra API calls."""
    if not (_sole_ai_research_mode() and is_research_data_collection()):
        return
    trade_id = ai.get("trade_id") or ctx.get("trade_id")
    price = float(ctx.get("price") or state.get("price") or 0)
    if not trade_id or price <= 0:
        return
    direction = str(ai.get("direction") or "NO_TRADE").upper()
    if direction not in ("LONG", "SHORT"):
        direction = "LONG"
    lev = int(state.get("leverage", DEFAULT_RESEARCH_LEVERAGE))
    shadow_reason = f"SOFT_REJECT:{block_tag}"
    row = {
        "schema": "soft_reject_shadow_v1",
        "ts": utc_iso(),
        "signal_id": trade_id,
        "trade_id": trade_id,
        "direction": direction,
        "edge_score": round(float(edge_score or 0), 2),
        "ai_prob": ai.get("win_prob"),
        "block_reason": shadow_reason,
        "ai_decision": ai.get("decision"),
        "research_lane": research_lane,
        "research_model": research_lane_label(research_lane),
        "bot_version": EXECUTION_FIX_VERSION,
        "analyzer_sync_id": ANALYZER_SYNC_ID,
    }
    try:
        _safe_append_jsonl(SOFT_REJECT_SHADOW_FILE, row, label="SOFT_REJECT")
    except Exception as e:
        logger.error(f"[SOFT_REJECT] log failed: {e}")
    start_replay_buffer(
        trade_id,
        price,
        lane="shadow",
        direction=direction,
        leverage=lev,
        margin_usdt=float(FIXED_MARGIN_USDT),
        pullback_pct=float(state.get("pullback_threshold", 0.001)),
        early_fail_enabled=bool(state.get("early_fail_enabled", True)),
        exit_config=get_exit_config_for_lane(research_lane),
        ai_win_prob=ai.get("win_prob"),
        edge_score=round(float(edge_score or 0), 1),
        block_reason=shadow_reason,
    )
    defer_shadow_research(trade_id, shadow_reason)
    append_replay_tick(trade_id, price, None)
    logger.info(
        f"[SOFT_REJECT] shadow replay started trade_id={trade_id} tag={block_tag} "
        f"[PIPELINE ENFORCEMENT]"
    )


def _research_log_would_block(signal, ai, reason, edge_score=None):
    """Log gate that would have blocked in v80; continue in v93 sole-AI max-collection mode."""
    tag = f"WOULD_BLOCK_{reason}"
    log_blocked_signal(signal, ai, tag)
    log_approved_but_rejected(signal, ai, reason, edge_score)
    log_pipeline_event(
        "POST_AI", "WOULD_BLOCK", tag,
        signal.get("trade_id") if signal else None,
        edge_score if edge_score is not None else (signal or {}).get("edge_score_at_entry", 0),
        force=True,
    )
    trade_id = (signal or {}).get("trade_id")
    if trade_id and (ai or {}).get("decision") == "APPROVE":
        defer_shadow_research(trade_id, tag)
        persist_rejected_opportunity(signal, ai, reason, would_block_only=True)
        log_lane_opportunity_event(
            (signal or {}).get("research_lane"),
            "WOULD_BLOCK",
            trade_id,
            (signal or {}).get("final_direction") or (ai or {}).get("direction"),
            (ai or {}).get("win_prob"),
            edge_score,
            reason,
        )

def _shared_ai_call_id(ai_result: dict = None, ctx: dict = None) -> str:
    return str(
        (ai_result or {}).get("shared_ai_call_id")
        or (ctx or {}).get("shared_ai_call_id")
        or (ai_result or {}).get("trade_id")
        or (ctx or {}).get("trade_id")
        or ""
    )


def _record_compressed_shadow_arm_result(
    call_id: str,
    status: str,
    reason: str,
    *,
    direction: str = "",
    trade_id: str = "",
    epoch_id: str = "",
) -> bool:
    """Durably explain why one shared-call shadow schedule did or did not arm.

    This receipt is evidence-only.  It is deliberately a different schema from
    ``compressed_chase_shadow_v1`` so analyzers cannot mistake an arm attempt
    for a price-path observation or executable fill.
    """
    shared_call = str(call_id or "").strip()
    if not shared_call:
        return False
    return _safe_append_jsonl(
        CHASE_OFFSET_TOUCH_GRID_FILE,
        {
            "schema": "compressed_chase_arm_receipt_v1",
            "ts": utc_iso(),
            "shared_ai_call_id": shared_call,
            "trade_id": str(trade_id or "") or None,
            "epoch_id": str(epoch_id or "") or None,
            "direction": str(direction or "").upper() or None,
            "status": str(status or "UNKNOWN").upper(),
            "reason": str(reason or "UNKNOWN"),
            "shadow_only": True,
            "places_order": False,
        },
        label="SHADOW_CHASE_ARM_RECEIPT",
    )


def _discovery_touch_grid_admission(ai: dict) -> tuple:
    """(basis_ai, basis) for a tile-eligible call, else (None, None).

    A call is tile-eligible when the raw AI verdict executes or the
    score-led research admission turns it into a tile APPROVE.  The raw
    verdict is kept as a logged field; it no longer gates discovery.
    """
    if ai_decision_should_execute(ai):
        return ai, "AI_APPROVE"
    lane_ai, admission = _effective_score_led_family_ai(ai)
    if admission.get("applied") and ai_decision_should_execute(lane_ai):
        return lane_ai, "SCORE_LED_ADMISSION"
    return None, None


def _arm_shared_discovery_touch_grid(ctx: dict, ai: dict) -> bool:
    """Arm one shadow-only 0.01–0.30% touch grid per tile-eligible AI call.

    Family tiles skip the per-lane grid so their paper anchors stay pure.
    Discovery still needs the full offset grid joined by ``shared_ai_call_id``.
    Never places paper or live orders.
    """
    basis_ai, admission_basis = _discovery_touch_grid_admission(ai)
    if basis_ai is None:
        return False
    call_id = _shared_ai_call_id(ai_result=ai, ctx=ctx).strip()
    if call_id and call_id in _discovery_touch_grid_seen_call_ids:
        return False
    raw_ai_executes = admission_basis == "AI_APPROVE"
    raw_direction = str(
        (basis_ai or {}).get("candidate_direction")
        or (basis_ai or {}).get("direction")
        or (basis_ai or {}).get("raw_direction")
        or ""
    ).upper()
    if not call_id or raw_direction not in ("LONG", "SHORT"):
        _collector_record_touch_grid_call(armed=False, ai_executes=raw_ai_executes)
        return False
    direction = raw_direction
    if invert_signal_active():
        direction = "SHORT" if raw_direction == "LONG" else "LONG"
    raw_ts = (ai or {}).get("shared_ai_call_ts") or (ctx or {}).get("shared_ai_call_ts")
    try:
        signal_ts = datetime.fromisoformat(str(raw_ts).replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        signal_ts = time.time()
    signal_price = float(
        (ctx or {}).get("price")
        or ((ctx or {}).get("market_context") or {}).get("price")
        or state.get("rest_price")
        or state.get("last_trade_price")
        or state.get("price")
        or 0
    )
    if signal_price <= 0:
        _collector_record_touch_grid_call(armed=False, ai_executes=raw_ai_executes)
        return False
    trade_id = "discovery-grid-" + hashlib.sha256(
        f"{call_id}|discovery_touch_grid_v1".encode("utf-8")
    ).hexdigest()[:20]
    ttl_sec = 1800.0
    rows = arm_touch_grid_rows(
        trade_id=trade_id,
        direction=direction,
        signal_price=signal_price,
        signal_ts=signal_ts,
        ttl_sec=ttl_sec,
        # No tile paper anchor is claimed as live_orig for discovery rows.
        live_offset_pct=-1.0,
        invert_on=invert_signal_active(),
    )
    for row in rows:
        row["places_live_order"] = False
        row["discovery_shadow_only"] = True
        row["shared_ai_call_id"] = call_id
        row["ai_decision"] = str((ai or {}).get("decision") or "UNKNOWN").upper()
        row["ai_verdict_executes"] = raw_ai_executes
        row["tile_admission_basis"] = admission_basis
        row["note"] = "discovery path-touch only; no paper/live order"
        _safe_append_jsonl(CHASE_OFFSET_TOUCH_GRID_FILE, row, label="TOUCH_GRID")
    _touch_grid_book[trade_id] = new_grid_state(rows)
    _discovery_touch_grid_seen_call_ids.add(call_id)
    _collector_record_touch_grid_call(armed=True, ai_executes=raw_ai_executes)
    logger.info(
        f"[TOUCH GRID] discovery armed shared_ai_call_id={call_id} "
        f"trade_id={trade_id} offsets=0.01-0.30 shadow_only basis={admission_basis} "
        f"[PIPELINE ENFORCEMENT]"
    )
    return True


def _arm_shared_compressed_shadow_chase(ctx: dict, ai: dict) -> bool:
    """Arm one non-executable compressed schedule per executable AI call."""
    if not ai_decision_should_execute(ai):
        return False
    call_id = _shared_ai_call_id(ai_result=ai, ctx=ctx).strip()
    raw_direction = str(
        (ai or {}).get("candidate_direction")
        or (ai or {}).get("direction")
        or (ai or {}).get("raw_direction")
        or ""
    ).upper()
    if not call_id:
        return False
    if raw_direction not in ("LONG", "SHORT"):
        _record_compressed_shadow_arm_result(
            call_id, "UNSUPPORTED", "MISSING_OR_INVALID_DIRECTION",
            direction=raw_direction,
        )
        return False
    direction = raw_direction
    if invert_signal_active():
        direction = "SHORT" if raw_direction == "LONG" else "LONG"
    raw_ts = (ai or {}).get("shared_ai_call_ts") or (ctx or {}).get("shared_ai_call_ts")
    try:
        signal_ts = datetime.fromisoformat(str(raw_ts).replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        signal_ts = time.time()
    _recover_compressed_shadow_chases_once(signal_ts)
    with state_lock:
        bid = float(state.get("bid") or 0) or None
        ask = float(state.get("ask") or 0) or None
        last = float(state.get("rest_price") or state.get("last_trade_price") or 0) or None
    signal_price = float(
        last
        or (ctx or {}).get("price")
        or ((ctx or {}).get("market_context") or {}).get("price")
        or 0
    )
    if signal_price <= 0:
        _record_compressed_shadow_arm_result(
            call_id, "UNSUPPORTED", "MISSING_SIGNAL_PRICE", direction=direction,
        )
        return False
    episode_id = "episode-" + hashlib.sha256(
        f"shared:{call_id}".encode("utf-8")
    ).hexdigest()[:20]
    opportunity_id = f"opportunity:{episode_id}"
    trade_id = "compressed-shadow-" + hashlib.sha256(
        f"{call_id}|{COMPRESSED_SHADOW_POLICY_SIGNATURE}".encode("utf-8")
    ).hexdigest()[:20]
    leverage = float(_state_leverage())
    initial_limit = orig_limit_price(
        signal_price, direction, COMPRESSED_SHADOW_INITIAL_OFFSET_PCT,
    )
    requested_qty = (FIXED_MARGIN_USDT * leverage) / initial_limit
    maker_fee, taker_fee = get_trading_fee_rates()
    epoch_id = _collector_v22_epoch_id()
    capture_helper = globals().get("_capture_runtime_quantity_constraints")
    quantity_constraints_status = (
        capture_helper(requested_qty=requested_qty) if callable(capture_helper) else {
            "supported": False, "receipt": None,
            "reasons": ["VENUE_QUANTITY_CONSTRAINT_CAPTURE_HELPER_UNAVAILABLE"],
        }
    )
    with _compressed_shadow_lock:
        duplicate_shared_call = call_id in _compressed_shadow_seen_call_ids
        # Reserve the shared call while its durable stage-zero row is written.
        if not duplicate_shared_call:
            _compressed_shadow_seen_call_ids.add(call_id)
    if duplicate_shared_call:
        _record_compressed_shadow_arm_result(
            call_id, "SKIPPED", "DUPLICATE_SHARED_CALL",
            direction=direction, trade_id=trade_id, epoch_id=epoch_id,
        )
        return False
    try:
        shadow_state, stage_zero = arm_compressed_shadow_chase(
            trade_id=trade_id,
            direction=direction,
            signal_price=signal_price,
            signal_ts=signal_ts,
            initial_limit_price=initial_limit,
            shared_ai_call_id=call_id,
            opportunity_id=opportunity_id,
            episode_id=episode_id,
            epoch_id=epoch_id,
            event_id=call_id,
            bid=bid,
            ask=ask,
            last=last or signal_price,
            bbo_fresh=_fresh_rest_entry_quote_ready(),
            requested_qty=requested_qty,
            requested_margin_usd=FIXED_MARGIN_USDT,
            leverage=leverage,
            fee_profile=EXCHANGE_FEE_PROFILE,
            entry_fee_rate=maker_fee,
            exit_fee_rate=taker_fee,
            signed_quantity_constraints=quantity_constraints_status.get("receipt"),
            quantity_constraints_status=quantity_constraints_status,
            event_source_revision=_runtime_git_rev(),
            event_config_signature=active_tile_registry_signature(),
        )
        durable = _safe_append_jsonl(
            CHASE_OFFSET_TOUCH_GRID_FILE, stage_zero, label="SHADOW_CHASE",
        )
    except Exception as exc:
        with _compressed_shadow_lock:
            _compressed_shadow_seen_call_ids.discard(call_id)
        _record_compressed_shadow_arm_result(
            call_id, "UNSUPPORTED", f"ARM_EXCEPTION:{type(exc).__name__}",
            direction=direction, trade_id=trade_id, epoch_id=epoch_id,
        )
        raise
    with _compressed_shadow_lock:
        current_epoch_id = _collector_v22_epoch_id()
        arm_failure_reason = (
            "STAGE_ZERO_APPEND_FAILED" if not durable
            else "EPOCH_CHANGED_DURING_ARM" if current_epoch_id != epoch_id
            else None
        )
        if arm_failure_reason:
            _compressed_shadow_seen_call_ids.discard(call_id)
        else:
            _compressed_shadow_chase_book[trade_id] = shadow_state
            _shadow_chase_bucket_book[trade_id] = shadow_chase_buckets.new_tracker(shadow_state)
    if arm_failure_reason:
        _record_compressed_shadow_arm_result(
            call_id, "UNSUPPORTED", arm_failure_reason,
            direction=direction, trade_id=trade_id, epoch_id=epoch_id,
        )
        return False
    _record_compressed_shadow_arm_result(
        call_id, "ARMED", "STAGE_ZERO_DURABLE",
        direction=direction, trade_id=trade_id, epoch_id=epoch_id,
    )
    logger.info(
        f"[SHADOW CHASE] armed shared_call={call_id} trade_id={trade_id} "
        "schedule=0,1,2,4,7,10m expiry=13m shadow_only "
        "[PIPELINE ENFORCEMENT]"
    )
    return True


def _v3_lane_policy_material(lane: str) -> dict:
    """Build the one policy material used by verdict and later resolution rows."""
    spec = dict(COMBO_LANE_SPECS.get(lane) or {})
    entry_limit_policy = spec.get("combo_key")
    entry_offset_fraction = (
        round(float(spec.get("entry_offset_pct")) / 100.0, 10)
        if spec.get("entry_offset_pct") is not None else None
    )
    # The signed paper identity must use the executable relay allow-list.
    # Hashing the configured flag at decision time and the executable flag at
    # order time minted two policy signatures for one causal episode.
    relay_eligible = lane in PLATFORM_RELAY_ELIGIBLE_LANES
    material = {
        "policy_id": spec.get("raw_policy_id") or lane,
        "raw_policy_id": spec.get("raw_policy_id") or lane,
        "deterministic_entry_offset_pct": entry_offset_fraction,
        "entry_limit_policy": entry_limit_policy,
        # The lane's declared entry TTL (also carried by its research chase schedule, which
        # order-intent / execution rows hash). Hashing the global SIGNAL_TTL_SEC here minted a
        # second policy signature per episode for the 3s taker tiles (POLICY_IDENTITY_CONTAMINATION).
        "entry_ttl_sec": float(spec.get("entry_ttl_sec") or SIGNAL_TTL_SEC),
        "exit_config": get_exit_config_for_lane(lane),
        # Every lane decision produced here describes the canonical LOCAL
        # paper lifecycle. Relay eligibility is a separate capability: an
        # authenticated platform may later copy an eligible local lifecycle,
        # but that must never rewrite the source evidence as a live event.
        # Conflating these fields produced rows with paper_only=false
        # while policy_execution_scope remained PAPER_RESEARCH_ONLY,
        # making provenance look mixed/contaminated.
        "paper_only": True,
        "relay_eligible": relay_eligible,
        "admission_treatment": spec.get("admission_treatment") or "AI_FILTERED_V1",
    }
    base_control = dict(CONTROL_CELL)
    base_control["invert_on"] = bool(invert_signal_active())
    base_identity = build_policy_identity(
        epoch_id=_collector_v22_epoch_id(), control_cell=base_control,
        invert_on=bool(base_control["invert_on"]),
    )
    material["policy_signature"] = base_identity["policy_signature"]
    material["policy_epoch_id"] = base_identity["policy_epoch_id"]
    return material


def _append_v3_lane_entry_resolution(
    source: dict, lane: str, resolution: str, reason: str,
) -> None:
    """Best-effort append; never changes execution and never fabricates PnL."""
    if not source or not _shared_ai_call_id(ctx=source):
        return
    preentry_barrier = globals().get("_preentry_evidence_barrier")
    if callable(preentry_barrier):
        preentry_barrier(source)
    try:
        dual_write_lane_entry_resolution(
            source, lane=lane, entry_resolution=resolution, exact_reason=reason,
            epoch_id=_collector_v22_epoch_id(), data_dir=os.getcwd(),
            lane_policy=_v3_lane_policy_material(lane),
        )
    except Exception as exc:
        logger.error(
            f"[COLLECTOR_V3] lane entry resolution write failed lane={lane} "
            f"resolution={resolution} reason={reason} error={exc} "
            "[PIPELINE ENFORCEMENT]"
        )


def _v3_record_preorder_terminal_if_needed(
    source: dict, master: dict, row: dict, reason: str,
) -> bool:
    """Close only a pre-order expectation; an expired submitted order is not NO_ORDER."""
    reason_upper = str(reason or "").upper()
    had_submitted_order = bool(
        source.get("order_placed") is True
        or source.get("submitted_order_trade_id")
        or master.get("order_placed") is True
        or master.get("submitted_order_trade_id")
    )
    lane = str(row.get("research_lane") or "")
    if (
        reason_upper not in {
            "SIGNAL_TTL_EXPIRED",
            "TTL_EXPIRED",
            "DUPLICATE_LIMIT_PRICE",
            "VIRTUAL_TOUCH_BEFORE_SELECTED_ENTRY",
            "STALE_NO_EXPOSURE",
            "RUNTIME_RESTART_SIGNAL_TTL_EXPIRED",
        }
        or had_submitted_order or not lane
    ):
        return False
    _append_v3_lane_entry_resolution(
        {**(master or {}), **(source or {}), **(row or {})},
        lane, "NO_ORDER", reason_upper,
    )
    return True


def _write_v3_shared_lane_decision(
    lane: str,
    ai: dict,
    ctx: dict,
    features: dict,
    *,
    policy_decision: str,
    execution_disposition: str,
    exact_reason: str,
) -> bool:
    """Write the lane verdict even when it correctly creates no order."""
    call_id = _shared_ai_call_id(ai_result=ai, ctx=ctx)
    if not call_id:
        logger.error(
            f"[COLLECTOR_V3] lane decision missing shared identity lane={lane} "
            "[PIPELINE ENFORCEMENT]"
        )
        return
    call_ts = (ai or {}).get("shared_ai_call_ts") or (ctx or {}).get("shared_ai_call_ts")
    try:
        signal_ts = datetime.fromisoformat(str(call_ts).replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        signal_ts = float((ctx or {}).get("created_ts_ts") or time.time())
    raw_direction = str(
        (ai or {}).get("raw_direction")
        or (ai or {}).get("candidate_direction")
        or (ai or {}).get("direction")
        or "UNKNOWN"
    ).upper()
    effective_research_direction = str(
        (ai or {}).get("effective_research_direction") or raw_direction
    ).upper()
    executed_direction = effective_research_direction
    if invert_signal_active():
        if effective_research_direction == "LONG":
            executed_direction = "SHORT"
        elif effective_research_direction == "SHORT":
            executed_direction = "LONG"
    lane_policy = _v3_lane_policy_material(lane)
    factors = (ai or {}).get("factors") or {}
    long_score = (ai or {}).get("long_score", factors.get("long_score"))
    short_score = (ai or {}).get("short_score", factors.get("short_score"))
    try:
        numeric_long_score = float(long_score)
        numeric_short_score = float(short_score)
        score_gap = (
            abs(numeric_long_score - numeric_short_score)
            if math.isfinite(numeric_long_score) and math.isfinite(numeric_short_score)
            else None
        )
    except (OverflowError, TypeError, ValueError):
        score_gap = None
    try:
        source = {
                "trade_id": call_id,
                "shared_ai_call_id": call_id,
                "shared_ai_call_ts_epoch": signal_ts,
                "symbol": (ctx or {}).get("symbol") or (ctx or {}).get("pair") or SYMBOL,
                "raw_direction": raw_direction,
                "executed_direction": executed_direction,
                "raw_ai_decision": (ai or {}).get("raw_decision") or (ai or {}).get("decision"),
                "long_score": long_score,
                "short_score": short_score,
                "score_gap": score_gap,
                "feature_snapshot_at_signal": copy.deepcopy(features or {}),
                "research_baseline_context_declaration": copy.deepcopy((ai or {}).get("research_baseline_context_declaration")),
                "research_baseline_context_status": copy.deepcopy((ai or {}).get("research_baseline_context_status")),
                "research_timing_config": copy.deepcopy((ai or {}).get("research_timing_config")),
                "research_timing_config_sha256": (ai or {}).get("research_timing_config_sha256"),
                "original_context_signal_ts": copy.deepcopy((ai or {}).get("original_context_signal_ts")),
                "ai_requested_model": (ai or {}).get("deepseek_model"),
                "ai_served_model": (ai or {}).get("deepseek_served_model"),
                "ai_system_fingerprint": (ai or {}).get("deepseek_system_fingerprint"),
            }
        if (ai or {}).get("effective_research_admission") is not None:
            source.update({
                "effective_research_direction": effective_research_direction,
                "effective_research_admission": copy.deepcopy(
                    (ai or {}).get("effective_research_admission")
                ),
                "effective_research_admission_policy_id": (
                    (ai or {}).get("effective_research_admission_policy_id")
                ),
            })
        failure_source = {**source, **lane_policy}
        receipt = dual_write_lane_decision(
            source,
            lane=lane,
            policy_decision=policy_decision,
            execution_disposition=execution_disposition,
            exact_reason=exact_reason,
            epoch_id=_collector_v22_epoch_id(),
            data_dir=os.getcwd(),
            lane_policy=lane_policy,
        )
        verification = receipt.get("store_verification") or {}
        feature_writes = [
            row for row in receipt.get("writes", [])
            if row.get("ledger") == "pre_entry_features"
        ]
        verified = bool(verification.get("passed") and len(feature_writes) == 1)
        if not verified:
            logger.error(
                f"[COLLECTOR_V3] pre-entry scoped verification failed lane={lane} "
                f"call_id={call_id} [PIPELINE ENFORCEMENT]"
            )
            try:
                write_pre_entry_evidence_failure(
                    failure_source, lane=lane, epoch_id=_collector_v22_epoch_id(),
                    data_dir=os.getcwd(), failure_class="ScopedVerificationFailed",
                )
            except Exception as dead_letter_exc:
                logger.error(
                    f"[COLLECTOR_V3] pre-entry dead-letter failed lane={lane} "
                    f"call_id={call_id} error={type(dead_letter_exc).__name__} "
                    "[PIPELINE ENFORCEMENT]"
                )
        return verified
    except Exception as exc:
        logger.error(
            f"[COLLECTOR_V3] lane decision write failed lane={lane} call_id={call_id} "
            f"error={exc} [PIPELINE ENFORCEMENT]"
        )
        try:
            write_pre_entry_evidence_failure(
                failure_source if "failure_source" in locals() else {
                    "trade_id": call_id,
                    "shared_ai_call_id": call_id,
                    "shared_ai_call_ts_epoch": signal_ts,
                    "raw_direction": raw_direction,
                },
                lane=lane, epoch_id=_collector_v22_epoch_id(), data_dir=os.getcwd(),
                failure_class=type(exc).__name__,
            )
        except Exception as dead_letter_exc:
            logger.error(
                f"[COLLECTOR_V3] pre-entry dead-letter failed lane={lane} "
                f"call_id={call_id} error={type(dead_letter_exc).__name__} "
                "[PIPELINE ENFORCEMENT]"
            )
        return False












def _stamp_shared_ai_lane_verdict(
    call_id: str,
    lane: str,
    accepted: bool,
    reason: str,
    score=None,
    policy_version: str = None,
    effective_direction: str = None,
    admission_policy_id: str = None,
) -> None:
    """Attach one independent post-AI lane verdict and increment it once."""
    call_id = str(call_id or "")
    lane = str(lane or "").upper()
    if not call_id or lane not in DASHBOARD_PRIMARY_LANES:
        return
    verdict = {
        "ok": bool(accepted),
        "accepted": bool(accepted),
        "reason": str(reason or ("ACCEPT" if accepted else "REJECT")),
        "block_reason": None if accepted else str(reason or "REJECT"),
        "score": score,
        "policy_version": policy_version,
        "effective_direction": effective_direction,
        "admission_policy_id": admission_policy_id,
        "stamped_at": time.time(),
    }
    with state_lock:
        counters = state.setdefault("shared_ai_lane_counters", {})
        bucket = counters.setdefault(
            lane,
            {"evaluated": 0, "accepted": 0, "rejected": 0, "reasons": {}},
        )
        counted = bucket.setdefault("_counted_call_ids", [])
        if call_id not in counted:
            bucket["evaluated"] = int(bucket.get("evaluated", 0)) + 1
            outcome_key = "accepted" if accepted else "rejected"
            bucket[outcome_key] = int(bucket.get(outcome_key, 0)) + 1
            reasons = bucket.setdefault("reasons", {})
            reason_key = verdict["reason"]
            reasons[reason_key] = int(reasons.get(reason_key, 0)) + 1
            counted.append(call_id)
            del counted[:-500]
        for row in reversed(state.get("ai_history") or []):
            if str(row.get("shared_ai_call_id") or row.get("trade_id") or "") == call_id:
                row.setdefault("lane_verdicts", {})[lane] = verdict
                state["ai_history_updated"] = time.time()
                break


def _append_ai_history_row(ai_result: dict) -> None:
    """Keep exactly one dashboard row for each actual shared AI API call."""
    now_iso = utc_iso()
    call_id = _shared_ai_call_id(ai_result=ai_result)
    call_ts = str(
        ai_result.get("shared_ai_call_ts")
        or ai_result.get("ai_call_ts")
        or ai_result.get("completed_at")
        or now_iso
    )
    # Carry the canonical call identity/time into every downstream lane. A
    # lane may write its replay record seconds later, but that is not another
    # model request and must never be displayed as one.
    ai_result["shared_ai_call_id"] = call_id
    ai_result["shared_ai_call_ts"] = call_ts
    factors = ai_result.get("factors") or {}
    row = {
        "time": call_ts,
        "melbourne_time": _format_melbourne_hm(call_ts),
        "session_ts": bot_start_time,
        "trade_id": ai_result.get("trade_id"),
        "shared_ai_call_id": call_id,
        "ai_direction_raw": ai_result.get("raw_direction") or ai_result.get("direction"),
        "candidate_direction": ai_result.get("candidate_direction") or ai_result.get("direction"),
        "final_direction": ai_result.get("candidate_direction") or ai_result.get("direction"),
        "inverted": False,
        "decision": ai_result.get("decision"),
        "win_prob": None,
        "confidence_requested": False,
        "edge_score": state.get("last_edge", 0.0),
        "edge_threshold": get_edge_threshold(),
        "source": ai_result.get("source", "AI"),
        "comment": (ai_result.get("comment") or "")[:2000],
        "reason": _compose_ai_history_reason(ai_result) or (ai_result.get("reason") or "")[:500],
        "ai_error": ai_result.get("ai_error", False),
        "error_type": ai_result.get("error_type"),
        "error_detail": (ai_result.get("error_detail") or "")[:500],
        "final_outcome": state.get("execution_outcome", "PENDING"),
        "long_score": ai_result.get("long_score", factors.get("long_score", 0)),
        "short_score": ai_result.get("short_score", factors.get("short_score", 0)),
        "score_gap": abs(
            int(ai_result.get("long_score", factors.get("long_score", 0)) or 0)
            - int(ai_result.get("short_score", factors.get("short_score", 0)) or 0)
        ),
        "deepseek_model": ai_result.get("deepseek_model"),
        "deepseek_thinking_mode": ai_result.get("deepseek_thinking_mode"),
        "deepseek_served_model": ai_result.get("deepseek_served_model"),
        "deepseek_system_fingerprint": ai_result.get("deepseek_system_fingerprint"),
        "research_lane": RESEARCH_LANE_AI_SCAN,
        "research_model": "Shared Direction Call",
        "lane_verdicts": copy.deepcopy(ai_result.get("lane_verdicts") or {}),
    }
    inserted = False
    with state_lock:
        existing = next(
            (
                item
                for item in reversed(state.get("ai_history") or [])
                if str(item.get("shared_ai_call_id") or item.get("trade_id") or "") == call_id
            ),
            None,
        )
        if existing is None:
            state["ai_history"].append(row)
            inserted = True
        else:
            existing.setdefault("lane_verdicts", {}).update(row["lane_verdicts"])
        hist_limit = 50
        state["ai_history"] = state["ai_history"][-hist_limit:]
        state["ai_history_updated"] = time.time()
    if inserted:
        _relay_mirror(
            "AI_DECISION",
            {
                "trade_id": ai_result.get("trade_id"),
                "shared_ai_call_id": call_id,
                "decision": ai_result.get("decision"),
                "win_prob": None,
                "direction": ai_result.get("direction"),
                "final_direction": ai_result.get("direction"),
                "comment": ai_result.get("comment"),
            },
            source_ts=time.time(),
        )

def _sync_ai_dashboard_debug(ai_result: dict, trade_id: str = None) -> None:
    """Align top AI card + debug panel after every DeepSeek evaluation (approve or reject)."""
    tid = trade_id or ai_result.get("trade_id")
    with state_lock:
        state["last_ai_ts"] = time.time()
        state["debug_state"]["last_ai_call"] = utc_iso()
        state["debug_state"]["last_ai_score"] = None
        state["last_ai"]["win_prob"] = None
        state["last_ai"]["confidence_requested"] = False
        state["last_ai"]["direction"] = ai_result.get("direction")
        state["last_ai"]["raw_direction"] = ai_result.get("raw_direction")
        state["last_ai"]["candidate_direction"] = ai_result.get("candidate_direction") or ai_result.get("direction")
        state["last_ai"]["long_score"] = ai_result.get("long_score")
        state["last_ai"]["short_score"] = ai_result.get("short_score")
        state["last_ai"]["decision"] = ai_result.get("decision")
        state["last_ai"]["trade_id"] = tid
        state["last_ai"]["comment"] = (ai_result.get("comment") or "")[:500]
        state["last_ai"]["source"] = ai_result.get("source", "FRESH")
        state["last_ai"]["ai_error"] = ai_result.get("ai_error", False)
        state["last_ai"]["error_type"] = ai_result.get("error_type")
        state["last_ai"]["error_detail"] = (ai_result.get("error_detail") or "")[:500]
        if ai_result.get("decision") == "AI_ERROR":
            state["last_ai"]["reason"] = f"AI_ERROR:{ai_result.get('error_type', 'unknown')}"
        else:
            state["last_ai"]["reason"] = (ai_result.get("comment") or "")[:500]
        state["last_ai"]["research_lane"] = ai_result.get("research_lane")
        state["last_ai"]["research_model"] = ai_result.get("research_model") or research_lane_label(ai_result.get("research_lane"))
        state["ai_outcome"] = ai_result.get("decision")
        state["ai_decision"] = ai_result.get("decision")


def _emit_genome_ai_events(ai_result: dict) -> None:
    """Trading Genome v1 — emit AI_SCAN + decision events (bot flight recorder only)."""
    bridge = get_genome_bridge()
    if not bridge:
        return
    try:
        # A shared AI result feeds multiple research lanes. Its source scan and
        # decision are one event; every downstream lane carries this lineage.
        if ai_result.get("genome_market_id") and ai_result.get("genome_decision_id"):
            return
        with state_lock:
            ema = state.get("ema_status") or {}
            market_context = state.get("market_context") or {}
            trend_strength = market_context.get("trend_strength") or {}
            market_structure = market_context.get("market_structure") or {}
            feature_snapshot = state.get("feature_snapshot") or {}
            adx = trend_strength.get("adx")
            if adx is None:
                adx = feature_snapshot.get("adx")
            atr = feature_snapshot.get("volatility_atr")
            factors = ai_result.get("factors") or {}
            long_score = ai_result.get("long_score")
            if long_score is None:
                long_score = factors.get("long_score")
            short_score = ai_result.get("short_score")
            if short_score is None:
                short_score = factors.get("short_score")
            bull_score = ai_result.get("bull_score")
            if bull_score is None:
                bull_score = factors.get("bull_score")
            bear_score = ai_result.get("bear_score")
            if bear_score is None:
                bear_score = factors.get("bear_score")
            has_momentum_source = any(
                feature_snapshot.get(key) is not None for key in ("ret_1m", "ret_5m", "velocity")
            )
            direction = str(ai_result.get("direction") or ai_result.get("final_direction") or "")
            spread = None
            if any(value is not None for value in (long_score, short_score, bull_score, bear_score)):
                spread = compute_directional_spread(direction, ai_result)
            market = {
                "price": state.get("price"),
                "adx": adx,
                "adx_source": (
                    "market_context.trend_strength.adx"
                    if trend_strength.get("adx") is not None
                    else feature_snapshot.get("adx_source") or "missing"
                ),
                "atr": atr,
                "atr_source": feature_snapshot.get("volatility_source") or "missing",
                "indicator_normalization_version": feature_snapshot.get("indicator_normalization_version"),
                "regime": state.get("regime"),
                "bull_score": bull_score,
                "bear_score": bear_score,
                "long_score": long_score,
                "short_score": short_score,
                "spread": spread,
                "directional_spread": spread,
                "score_source": "shared_ai_result",
                "ema_fast": ema.get("ema_fast"),
                "ema_slow": ema.get("ema_slow"),
                "ema_slope": ema.get("ema_spread"),
                "volatility_percentile": feature_snapshot.get("volatility_percentile"),
                "volatility_percentile_source": (
                    "feature_snapshot.volatility_percentile"
                    if feature_snapshot.get("volatility_percentile") is not None else "missing"
                ),
                "volume_percentile": feature_snapshot.get("volume_percentile"),
                "volume_percentile_source": (
                    "feature_snapshot.volume_percentile"
                    if feature_snapshot.get("volume_percentile") is not None else "missing"
                ),
                "funding_rate": state.get("funding_rate"),
                "vwap_distance": state.get("vwap_distance"),
                "delta": state.get("delta"),
                "momentum": _compute_momentum_metric(feature_snapshot) if has_momentum_source else None,
                "momentum_source": "feature_snapshot.ret_1m|ret_5m|velocity" if has_momentum_source else "missing",
                "structure": market_structure.get("structure_score"),
                "structure_source": (
                    "market_context.market_structure.structure_score"
                    if market_structure.get("structure_score") is not None else "missing"
                ),
            }
        genome_ids = bridge.on_ai_scan_complete(market)
        decision = str(ai_result.get("decision") or "").upper()
        approved = decision == "APPROVE" or bool(ai_result.get("approved"))
        confidence_requested = bool(ai_result.get("confidence_requested", False))
        confidence = ai_result.get("win_prob") if confidence_requested else None
        decision_id = bridge.on_ai_decision(
            approved,
            trade_id=str(ai_result.get("trade_id") or ""),
            ai_confidence=int(confidence) if confidence is not None else None,
            direction=direction,
            block_reason="" if approved else str(ai_result.get("comment") or decision or "REJECT"),
            research_lane=str(ai_result.get("research_lane") or RESEARCH_LANE_AI_SCAN),
            extra={
                "confidence_requested": confidence_requested,
                "prompt_id": ai_result.get("prompt_id") or SHARED_DIRECTION_PROMPT_ID,
                "bot_version": EXECUTION_FIX_VERSION,
                "analyzer_sync_id": ANALYZER_SYNC_ID,
            },
        )
        ai_result["genome_environment_id"] = genome_ids.get("environment_id")
        ai_result["genome_market_id"] = genome_ids.get("market_genome_id")
        ai_result["genome_decision_id"] = decision_id
        ai_result["genome_source_trade_id"] = str(ai_result.get("trade_id") or "") or None
    except Exception as exc:
        logger.warning(f"[GENOME] ai scan events failed: {exc}")


def _emit_genome_execution_event(event_name: str, payload: dict) -> None:
    bridge = get_genome_bridge()
    if not bridge:
        return
    try:
        body = dict(payload or {})
        trade_id = str(body.get("trade_id") or "")
        references = []
        trade_ref = trades_map.get(trade_id) if trade_id else None
        if isinstance(trade_ref, dict):
            references.extend([trade_ref.get("ai") or {}, trade_ref.get("signal_ref") or {}])
        for collection in (open_positions, pending_orders):
            match = next((item for item in collection if str(item.get("trade_id") or "") == trade_id), None)
            if match:
                references.append(match)
        lineage_keys = (
            ("environment_id", "genome_environment_id"),
            ("market_genome_id", "genome_market_id"),
            ("decision_id", "genome_decision_id"),
        )
        for event_key, stored_key in lineage_keys:
            if body.get(event_key) is None:
                body[event_key] = next((ref.get(stored_key) for ref in references if ref.get(stored_key)), None)
        body.setdefault(
            "genome_source_trade_id",
            next((ref.get("genome_source_trade_id") for ref in references if ref.get("genome_source_trade_id")), None)
            or body.get("source_trade_id")
            or trade_id
            or None,
        )
        bridge.on_execution_event(event_name, body)
    except Exception as exc:
        logger.warning(f"[GENOME] execution event {event_name} failed: {exc}")


def _deepseek_api_key():
    """Read key each call so .env / env changes apply without full process restart."""
    _load_local_dotenv()
    return (os.getenv("DEEPSEEK_API_KEY") or "").strip() or None


def _deepseek_config_receipt() -> tuple:
    """Return configured values without validation so failures remain journalable."""
    _load_local_dotenv()
    model = (os.getenv("DEEPSEEK_MODEL") or DEEPSEEK_DEFAULT_MODEL).strip().lower()
    model = DEEPSEEK_RETIRED_MODEL_ALIASES.get(model, model)
    mode = (
        os.getenv("DEEPSEEK_THINKING_MODE") or DEEPSEEK_DEFAULT_THINKING_MODE
    ).strip().lower()
    return model, mode


def _deepseek_model() -> str:
    """Resolve an explicit supported model; never fall back from a bad value silently."""
    model, _ = _deepseek_config_receipt()
    if model not in DEEPSEEK_SUPPORTED_MODELS:
        supported = ", ".join(sorted(DEEPSEEK_SUPPORTED_MODELS))
        raise RuntimeError(f"INVALID_DEEPSEEK_MODEL:{model}:supported={supported}")
    return model


def _deepseek_thinking_mode() -> str:
    """Resolve V4 thinking mode independently so it can be shadow-tested safely."""
    _, mode = _deepseek_config_receipt()
    if mode not in DEEPSEEK_SUPPORTED_THINKING_MODES:
        supported = ", ".join(sorted(DEEPSEEK_SUPPORTED_THINKING_MODES))
        raise RuntimeError(f"INVALID_DEEPSEEK_THINKING_MODE:{mode}:supported={supported}")
    return mode


def _csv_row_to_ai_history(row: dict) -> dict:
    try:
        wp = float(row.get("win_prob") or 0)
    except (TypeError, ValueError):
        wp = 0
    dec = (row.get("decision") or "").strip().upper()
    if not dec and str(row.get("approved", "")).lower() in ("true", "1", "yes"):
        dec = "APPROVE"
    if not dec and str(row.get("approved", "")).lower() in ("false", "0", "no"):
        dec = "REJECT"
    comment = (row.get("comment") or row.get("full_comment") or "")
    if not dec or dec == "AI_ERROR":
        m = re.search(r"Decision:\s*(APPROVE|REJECT)", comment, re.IGNORECASE)
        if m:
            dec = m.group(1).upper()
    raw_time = row.get("shared_ai_call_ts") or row.get("ts") or row.get("time") or "-"
    call_id = row.get("shared_ai_call_id") or row.get("trade_id")
    long_score = row.get("long_score") or row.get("bull_score") or 0
    short_score = row.get("short_score") or row.get("bear_score") or 0
    try:
        long_score = int(float(long_score))
    except (TypeError, ValueError):
        long_score = 0
    try:
        short_score = int(float(short_score))
    except (TypeError, ValueError):
        short_score = 0
    return {
        "time": raw_time,
        "melbourne_time": _format_melbourne_hm(raw_time),
        "session_ts": bot_start_time,
        "trade_id": row.get("trade_id"),
        "shared_ai_call_id": call_id,
        "ai_direction_raw": row.get("ai_direction_raw") or row.get("dir"),
        "candidate_direction": row.get("candidate_direction") or row.get("ai_direction_raw") or row.get("dir"),
        "final_direction": row.get("final_direction") or row.get("dir"),
        "inverted": str(row.get("inverted", "")).lower() in ("true", "1", "yes"),
        "decision": dec or "UNKNOWN",
        "win_prob": wp,
        "comment": comment[:2000],
        "source": row.get("source", "CSV"),
        "ai_error": str(row.get("ai_error", "")).lower() in ("true", "1", "yes") or dec == "AI_ERROR",
        "error_type": row.get("error_type"),
        "error_detail": (row.get("error_detail") or "")[:500],
        "latency_ms": row.get("latency_ms"),
        "http_status": row.get("http_status"),
        "edge_score": row.get("edge_score"),
        "long_score": long_score,
        "short_score": short_score,
        "score_gap": abs(long_score - short_score),
        "deepseek_model": row.get("deepseek_model"),
        "deepseek_thinking_mode": row.get("deepseek_thinking_mode"),
        "research_lane": row.get("research_lane"),
        "research_model": row.get("research_model") or research_lane_label(row.get("research_lane")),
        "lane_verdicts": {},
        "verdict_provenance": "RESTORED_PRE_RESTART_NO_LANE_METADATA",
    }

def _load_recent_ai_history_from_csv(limit: int = 5) -> list:
    """Hydrate dashboard from Final Bots + legacy %USERPROFILE% logs."""
    bot_root = os.path.dirname(os.path.abspath(__file__))
    paths = [
        os.path.join(bot_root, CSV_AI_TRANCHE),
        os.path.join(os.path.expanduser("~"), CSV_AI_TRANCHE),
        CSV_AI_TRANCHE,
    ]
    seen_paths = set()
    rows = []
    for path in paths:
        canonical_path = os.path.normcase(os.path.abspath(path))
        if canonical_path in seen_paths or not os.path.isfile(canonical_path):
            continue
        seen_paths.add(canonical_path)
        for enc in ("utf-8", "utf-8-sig", "cp1252", "latin-1"):
            try:
                with open(canonical_path, newline="", encoding=enc) as f:
                    rows.extend(list(csv.DictReader(f)))
                break
            except UnicodeDecodeError:
                continue
            except Exception as e:
                logger.debug(f"[AI HISTORY CSV] read failed {canonical_path}: {e}")
                break
    if not rows:
        return []
    rows.sort(key=lambda r: r.get("ts") or r.get("time") or "")
    out = [_csv_row_to_ai_history(r) for r in rows[-max(limit * 3, limit):]]
    return out[-limit:]


def _restore_session_ai_history_from_csv(limit: int = 50) -> list:
    """Restore current-session AI rows from the crash-safe CSV journal."""
    csv_rows = _load_recent_ai_history_from_csv(max(limit * 4, limit))
    session_rows = _session_ai_history(csv_rows, max(limit * 2, limit))
    by_call = {}
    for row in session_rows:
        call_id = str(row.get("shared_ai_call_id") or row.get("trade_id") or "")
        if not call_id:
            continue
        previous = by_call.get(call_id)
        if previous is None or (row.get("time") or "") >= (previous.get("time") or ""):
            by_call[call_id] = row
    restored = sorted(by_call.values(), key=lambda row: row.get("time") or "")[-limit:]
    with state_lock:
        state["ai_history"] = restored
        state["ai_history_updated"] = time.time() if restored else 0.0
    logger.info(
        f"[AI HISTORY] restored={len(restored)} current-session rows from journal "
        f"[PIPELINE ENFORCEMENT]"
    )
    return restored


def _restore_shared_ai_lane_verdicts_from_journal() -> dict:
    """Current four-tile verdicts are rebuilt by new AI cycles after restart."""
    return {"restored_rows": 0, "unique_verdicts": 0, "lanes": {}}


def _merged_ai_history(in_memory: list, limit: int = 5) -> list:
    if RESEARCH_AI_SOLE_AUTHORITY or is_research_data_collection():
        return _session_ai_history(in_memory, limit)
    csv_rows = _load_recent_ai_history_from_csv(limit * 2)
    combined = (in_memory or []) + csv_rows
    by_trade = {}
    for row in combined:
        tid = row.get("trade_id") or ""
        prev = by_trade.get(tid)
        if not prev or (row.get("time") or "") >= (prev.get("time") or ""):
            by_trade[tid] = row
    deduped = sorted(by_trade.values(), key=lambda r: r.get("time") or "")
    return deduped[-limit:]

def _pick_dashboard_last_ai(snapshot: dict, ai_history: list) -> dict:
    """Prefer latest non-error AI row (fixes dashboard stuck on MISSING_API_KEY from an old cycle)."""
    la = copy.deepcopy(snapshot.get("last_ai") or {})
    if la.get("decision") and la.get("decision") != "AI_ERROR" and not la.get("ai_error"):
        return la
    for row in reversed(ai_history or []):
        dec = row.get("decision")
        if dec and dec != "AI_ERROR" and not row.get("ai_error"):
            return {
                "win_prob": row.get("win_prob"),
                "direction": row.get("ai_direction_raw") or row.get("dir"),
                "final_direction": row.get("final_direction"),
                "decision": dec,
                "trade_id": row.get("trade_id"),
                "comment": row.get("comment"),
                "source": row.get("source", "CSV"),
                "inverted": row.get("inverted"),
                "ai_error": False,
                "from_csv_history": True,
            }
    return la

_last_pipeline_event_log = {"key": None, "ts": 0.0}

def _call_deepseek_api_unrecorded(
    messages,
    temperature=0.4,
    *,
    purpose: str,
    max_tokens=None,
    response_format=None,
    timeout=None,
):
    if manual_admin_pause_active():
        raise RuntimeError("ADMIN_MANUAL_PAUSE")
    if TRADING_AI_ONLY and purpose not in TRADING_AI_ALLOWED_PURPOSES:
        raise RuntimeError(f"AI_PURPOSE_BLOCKED:{purpose or 'missing'}")
    api_key = _deepseek_api_key()
    if not api_key:
        raise RuntimeError("MISSING_API_KEY")
    model = _deepseek_model()
    thinking_mode = _deepseek_thinking_mode()
    request_payload = {
        "model": model,
        "messages": messages,
        "temperature": temperature,
        "thinking": {"type": thinking_mode},
    }
    if max_tokens:
        request_payload["max_tokens"] = int(max_tokens)
    if response_format:
        request_payload["response_format"] = response_format
    t0 = time.time()
    try:
        status_code, body_text = _deepseek_post_with_deadline(
            DEEPSEEK_URL,
            headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
            json_payload=request_payload,
            idle_timeout=timeout or AI_TIMEOUT_SEC,
            deadline_sec=min(float(timeout or AI_CALL_DEADLINE_SEC), AI_CALL_DEADLINE_SEC),
        )
    except requests.RequestException as e:
        raise RuntimeError(f"HTTP_ERROR:{e}") from e
    latency_ms = int((time.time() - t0) * 1000)
    if status_code >= 400:
        if status_code == 429:
            _RATE_LIMITS.hit("deepseek", purpose)
        body = (body_text or "")[:500]
        err = RuntimeError(f"HTTP_{status_code}:{body}")
        err.http_status = status_code  # type: ignore[attr-defined]
        err.latency_ms = latency_ms  # type: ignore[attr-defined]
        raise err
    try:
        payload = json.loads(body_text)
    except json.JSONDecodeError as e:
        raise RuntimeError(f"JSON_DECODE:{e}:{(body_text or '')[:200]}") from e
    if payload.get("error"):
        err_obj = payload["error"]
        msg = err_obj.get("message", err_obj) if isinstance(err_obj, dict) else str(err_obj)
        raise RuntimeError(f"API_ERROR:{msg}")
    choices = payload.get("choices") or []
    if not choices:
        raise RuntimeError(f"NO_CHOICES:{str(payload)[:300]}")
    text = (choices[0].get("message") or {}).get("content")
    if not text:
        raise RuntimeError("EMPTY_CONTENT")
    usage = payload.get("usage") or {}
    prompt_tokens = int(usage.get("prompt_tokens") or 0)
    completion_tokens = int(usage.get("completion_tokens") or 0)
    tokens_estimated = prompt_tokens <= 0 and completion_tokens <= 0
    if tokens_estimated:
        prompt_text = "\n".join(
            (m.get("content") or "") for m in messages if isinstance(m, dict)
        )
        prompt_tokens = _estimate_token_count(prompt_text)
        completion_tokens = _estimate_token_count(text)
    try:
        _AI_COST_LEDGER.record(
            model,
            {"prompt_tokens": prompt_tokens, "completion_tokens": completion_tokens}
            if tokens_estimated else usage,
            purpose=purpose, estimated=tokens_estimated,
        )
    except Exception as exc:
        logger.warning(f"[AI COST] cost accounting failed: {type(exc).__name__}: {exc}")
    _report_showcase_inference_usage(prompt_tokens, completion_tokens, model=model)
    return text, latency_ms, {
        "requested_model": model,
        "served_model": str(payload.get("model") or "")[:64] or None,
        "system_fingerprint": str(payload.get("system_fingerprint") or "")[:96] or None,
    }


_ai_deadline_lock = threading.Lock()
_ai_deadline_state = {"abandoned_in_flight": 0, "deadline_exceeded_total": 0}


def _deepseek_post_with_deadline(url, *, headers, json_payload, idle_timeout, deadline_sec):
    """POST with a total wall-clock deadline; returns (status_code, body_text).

    The request runs on a daemon worker so the caller returns at the deadline
    even while DeepSeek trickles keep-alive bytes.  On expiry the worker is
    told to stop and its socket is shut down; it can never deliver a late
    verdict into a later cycle.
    """
    deadline_sec = max(1.0, float(deadline_sec))
    with _ai_deadline_lock:
        if _ai_deadline_state["abandoned_in_flight"] >= AI_DEADLINE_MAX_ABANDONED:
            raise RuntimeError(
                f"AI_DEADLINE_EXCEEDED:backlog={_ai_deadline_state['abandoned_in_flight']}"
            )
    deadline = time.monotonic() + deadline_sec
    cancelled = threading.Event()
    finished = threading.Event()
    box = {"response": None, "status": None, "body": None, "error": None, "abandoned": False}

    def worker():
        try:
            response = requests.post(
                url, headers=headers, json=json_payload, stream=True,
                timeout=(min(10.0, deadline_sec), min(float(idle_timeout), deadline_sec)),
            )
            box["response"] = response
            chunks = []
            if hasattr(response, "iter_content"):
                for chunk in response.iter_content(chunk_size=16384):
                    if cancelled.is_set() or time.monotonic() > deadline:
                        raise TimeoutError("AI_DEADLINE_EXCEEDED")
                    if chunk:
                        chunks.append(chunk)
                body = b"".join(chunks).decode("utf-8", errors="replace")
            else:
                body = response.text or ""
            box["status"], box["body"] = int(response.status_code), body
        except BaseException as exc:  # noqa: BLE001 - re-raised on the caller thread
            box["error"] = exc
        finally:
            with _ai_deadline_lock:
                if box["abandoned"]:
                    _ai_deadline_state["abandoned_in_flight"] -= 1
                finished.set()
            try:
                if box["response"] is not None:
                    box["response"].close()
            except Exception:
                pass

    threading.Thread(target=worker, name="deepseek-call", daemon=True).start()
    finished.wait(max(0.0, deadline - time.monotonic()))
    with _ai_deadline_lock:
        timed_out = not finished.is_set()
        if timed_out:
            box["abandoned"] = True
            _ai_deadline_state["abandoned_in_flight"] += 1
            _ai_deadline_state["deadline_exceeded_total"] += 1
    if timed_out:
        cancelled.set()
        _abort_streaming_response(box["response"])
        err = RuntimeError(f"AI_DEADLINE_EXCEEDED:{deadline_sec:.0f}s")
        err.latency_ms = int(deadline_sec * 1000)  # type: ignore[attr-defined]
        raise err
    if box["error"] is not None:
        # The worker's read timeout is clamped to deadline_sec, so its own
        # timeout can win the race against finished.wait() (coarse Windows
        # timers); a timeout at the deadline is still a deadline expiry.
        worker_hit_deadline = (
            isinstance(box["error"], TimeoutError) and str(box["error"]) == "AI_DEADLINE_EXCEEDED"
        ) or (
            isinstance(box["error"], requests.exceptions.Timeout)
            and time.monotonic() >= deadline - 0.05
        )
        if worker_hit_deadline:
            with _ai_deadline_lock:
                _ai_deadline_state["deadline_exceeded_total"] += 1
            err = RuntimeError(f"AI_DEADLINE_EXCEEDED:{deadline_sec:.0f}s")
            err.latency_ms = int(deadline_sec * 1000)  # type: ignore[attr-defined]
            raise err
        raise box["error"]
    return box["status"], box["body"]


def _abort_streaming_response(response) -> None:
    """Best-effort socket shutdown so a blocked read on the worker returns now."""
    if response is None:
        return
    try:
        sock = response.raw._fp.fp.raw._sock  # urllib3 -> http.client -> socket
        sock.shutdown(socket.SHUT_RDWR)
    except Exception:
        pass
    try:
        response.close()
    except Exception:
        pass


def call_deepseek_api_with_meta(
    messages,
    temperature=0.4,
    *,
    purpose: str,
    max_tokens=None,
    response_format=None,
    timeout=None,
):
    """HTTP + JSON guard for DeepSeek; returns (text, latency_ms, served-model meta)."""
    try:
        text, latency_ms, meta = _call_deepseek_api_unrecorded(
            messages,
            temperature,
            purpose=purpose,
            max_tokens=max_tokens,
            response_format=response_format,
            timeout=timeout,
        )
    except Exception as exc:
        if not str(exc).startswith(AI_PROVIDER_NOT_ATTEMPTED_PREFIXES):
            record_ai_provider_outcome(purpose, ok=False, error=exc)
        raise
    meta = dict(meta or {})
    record_ai_provider_outcome(
        purpose, ok=True, latency_ms=latency_ms,
        model_echo=meta.get("served_model"),
        system_fingerprint=meta.get("system_fingerprint"),
        requested_model=meta.get("requested_model"),
    )
    return text, latency_ms, meta


def call_deepseek_api(messages, temperature=0.4, *, purpose: str, max_tokens=None,
                      response_format=None, timeout=None):
    """HTTP + JSON guard for DeepSeek; raises RuntimeError with a short code prefix."""
    text, latency_ms, _meta = call_deepseek_api_with_meta(
        messages, temperature, purpose=purpose, max_tokens=max_tokens,
        response_format=response_format, timeout=timeout,
    )
    return text, latency_ms


# Local gates that refuse before any provider egress are not provider failures.
AI_PROVIDER_NOT_ATTEMPTED_PREFIXES = ("ADMIN_MANUAL_PAUSE", "AI_PURPOSE_BLOCKED")


def classify_ai_provider_error(exc) -> str:
    """Bounded error class only; provider bodies never reach health payloads."""
    text = str(exc or "")
    status = getattr(exc, "http_status", None)
    if text.startswith("AI_DEADLINE_EXCEEDED"):
        return "DEADLINE"
    if text.startswith("HTTP_ERROR:"):
        lowered = text.lower()
        if "timed out" in lowered or "timeout" in lowered:
            return "TIMEOUT"
        if "name or service" in lowered or "resolve" in lowered or "getaddrinfo" in lowered:
            return "DNS"
        return "CONNECTION"
    if status in (401, 403):
        return "AUTH"
    if status == 402:
        return "INSUFFICIENT_BALANCE"
    if status == 429:
        return "RATE_LIMIT"
    if isinstance(status, int) and status >= 500:
        return "PROVIDER_5XX"
    if isinstance(status, int) and status >= 400:
        return "HTTP_4XX"
    if text.startswith("MISSING_API_KEY"):
        return "MISSING_API_KEY"
    if text.startswith(("INVALID_DEEPSEEK_MODEL", "INVALID_DEEPSEEK_THINKING_MODE")):
        return "MODEL_CONFIG"
    if text.startswith(("JSON_DECODE", "API_ERROR", "NO_CHOICES", "EMPTY_CONTENT")):
        return "BAD_RESPONSE"
    return type(exc).__name__ if exc is not None else "UNKNOWN"


def record_ai_provider_outcome(
    purpose, *, ok, now=None, latency_ms=None, model_echo=None, error=None,
    system_fingerprint=None, requested_model=None,
):
    if purpose not in AI_PROVIDER_HEALTH_PURPOSES:
        return
    now = float(now or time.time())
    ai_window = globals().get("_AI_CALL_WINDOW")  # read-only monitor telemetry; never raises
    if ai_window is not None:
        ai_window.observe(ok=bool(ok), latency_ms=latency_ms, now=now,
                          error_class=None if ok else classify_ai_provider_error(error))
    with _ai_provider_health_lock:
        health = _ai_provider_health
        health["last_attempt_ts"] = now
        if ok:
            previous = health.get("last_model_echo")
            if model_echo and previous and model_echo != previous:
                changes = list(health.get("served_model_changes") or [])
                changes.append({"from": previous, "to": model_echo, "at": _epoch_iso(now)})
                health["served_model_changes"] = changes[-10:]
            health.update({
                "last_success_ts": now,
                "failing_since_ts": 0.0,
                "consecutive_failures": 0,
                "last_latency_ms": latency_ms,
                "last_model_echo": model_echo or previous,
                "last_system_fingerprint": system_fingerprint,
                "last_requested_model": requested_model,
            })
            health["successes_since_boot"] += 1
            return
        if not health["consecutive_failures"]:
            health["failing_since_ts"] = now
        health["consecutive_failures"] += 1
        health["failures_since_boot"] += 1
        health["last_failure_ts"] = now
        health["last_error_class"] = classify_ai_provider_error(error)


def _epoch_iso(ts):
    if not ts:
        return None
    return datetime.fromtimestamp(float(ts), tz=timezone.utc).isoformat()


def ai_provider_health_snapshot(now=None) -> dict:
    """Successful model responses, not attempts, are the AI liveness truth."""
    now = float(now or time.time())
    with _ai_provider_health_lock:
        health = dict(_ai_provider_health)
    success_ts = float(health["last_success_ts"] or 0)
    failures = int(health["consecutive_failures"] or 0)
    reference_ts = success_ts or float(health["failing_since_ts"] or 0)
    no_success_sec = max(0.0, now - reference_ts) if failures and reference_ts else 0.0
    alert = bool(failures and no_success_sec > AI_NO_SUCCESS_ALERT_SEC)
    configured_model, _ = _deepseek_config_receipt()
    served = health.get("last_model_echo")
    with _ai_deadline_lock:
        deadline_state = dict(_ai_deadline_state)
    return {
        "schema": "ai_provider_health_v1",
        "purpose": "trading_direction",
        "last_ai_success_at": _epoch_iso(success_ts),
        "last_ai_success_ts": success_ts,
        "ai_success_age_sec": max(0.0, now - success_ts) if success_ts else None,
        "last_ai_attempt_at": _epoch_iso(health["last_attempt_ts"]),
        "last_ai_failure_at": _epoch_iso(health["last_failure_ts"]),
        "failing_since_at": _epoch_iso(health["failing_since_ts"]),
        "consecutive_failures": failures,
        "no_success_while_failing_sec": no_success_sec,
        "last_error_class": health["last_error_class"],
        "last_latency_ms": health["last_latency_ms"],
        "last_model_echo": served,
        "last_system_fingerprint": health.get("last_system_fingerprint"),
        "configured_model": configured_model,
        "served_model_matches_configured": (served == configured_model) if served else None,
        "served_model_changes": list(health.get("served_model_changes") or []),
        "call_deadline_sec": AI_CALL_DEADLINE_SEC,
        "deadline_exceeded_total": int(deadline_state["deadline_exceeded_total"]),
        "abandoned_calls_in_flight": int(deadline_state["abandoned_in_flight"]),
        "successes_since_boot": int(health["successes_since_boot"]),
        "failures_since_boot": int(health["failures_since_boot"]),
        "alert_after_sec": AI_NO_SUCCESS_ALERT_SEC,
        "alert": "AI_NO_SUCCESS_10M" if alert else None,
        "deepseek_balance": deepseek_balance_snapshot(now),
        **_ai_call_cost_fields(now),
    }


def _ai_call_cost_fields(now: float) -> dict:
    try:
        cost = _AI_COST_LEDGER.snapshot(now)
    except Exception as exc:
        return {"call_cost": {"status": "UNKNOWN", "error": type(exc).__name__}}
    return {
        "last_call_cost_usd": cost["last_call_cost_usd"],
        "cost_usd_24h": cost["cost_usd_24h"],
        "calls_24h": cost["calls_24h"],
        "call_cost": cost,
    }


DEEPSEEK_BALANCE_REFRESH_SEC = 10 * 60.0
_deepseek_balance_lock = threading.Lock()
_deepseek_balance = {"checked_ts": 0.0, "refreshing": False, "result": None}


def _parse_deepseek_balance(payload) -> dict:
    """Bounded USD summary of GET /user/balance; provider text never leaves."""
    if not isinstance(payload, dict):
        return {"error": "BAD_RESPONSE"}
    infos = payload.get("balance_infos") or []
    usd = next((i for i in infos if isinstance(i, dict) and str(i.get("currency")).upper() == "USD"), None)
    try:
        total = float(usd["total_balance"]) if usd else None
    except (KeyError, TypeError, ValueError):
        total = None
    if total is None:
        return {"error": "NO_USD_BALANCE"}
    status = "RED" if total < 1.0 or not payload.get("is_available") else "AMBER" if total < 5.0 else "OK"
    return {"total_usd": total, "is_available": bool(payload.get("is_available")), "status": status}


def _refresh_deepseek_balance() -> None:
    result = {"error": "MISSING_API_KEY"}
    try:
        api_key = _deepseek_api_key()
        if api_key:
            res = requests.get(DEEPSEEK_BALANCE_URL, timeout=15,
                               headers={"Authorization": f"Bearer {api_key}", "Accept": "application/json"})
            result = (_parse_deepseek_balance(res.json()) if res.status_code < 400
                      else {"error": f"HTTP_{res.status_code}"})
    except Exception as exc:
        result = {"error": type(exc).__name__}
    now = time.time()
    with _deepseek_balance_lock:
        _deepseek_balance.update({"checked_ts": now, "refreshing": False,
                                  "result": {**result, "checked_at": _epoch_iso(now)}})


def deepseek_balance_snapshot(now=None) -> dict:
    """Cached read-only balance; refreshes off the request thread every 10 min."""
    now = float(now or time.time())
    with _deepseek_balance_lock:
        cached = dict(_deepseek_balance["result"] or {"status": "UNKNOWN", "checked_at": None})
        due = (not _deepseek_balance["refreshing"]
               and now - float(_deepseek_balance["checked_ts"] or 0) >= DEEPSEEK_BALANCE_REFRESH_SEC)
        if due:
            _deepseek_balance["refreshing"] = True
    if due:
        threading.Thread(target=_refresh_deepseek_balance, name="deepseek-balance", daemon=True).start()
    return cached


def build_ai_error_result(exc, trade_id=None, latency_ms=None, http_status=None):
    err_type = type(exc).__name__
    detail = str(exc)[:1500]
    configured_model, configured_thinking_mode = _deepseek_config_receipt()
    if getattr(exc, "http_status", None):
        http_status = exc.http_status
    if latency_ms is None and getattr(exc, "latency_ms", None):
        latency_ms = exc.latency_ms
    return {
        "win_prob": 0,
        "direction": "NO_TRADE",
        "decision": "AI_ERROR",
        "override": False,
        "comment": f"AI_CRASH_FAILSAFE: {detail}",
        "ai_error": True,
        "error_type": err_type,
        "error_detail": detail,
        "latency_ms": latency_ms,
        "http_status": http_status,
        "factors": {},
        "source": "ERROR",
        "approved": False,
        "trade_id": trade_id,
        "deepseek_model": configured_model,
        "deepseek_thinking_mode": configured_thinking_mode,
        "deepseek_served_model": None,
        "deepseek_system_fingerprint": None,
        "ai_failure_class": classify_ai_provider_error(exc),
    }

def log_pipeline_event(stage, outcome, reason="", trade_id=None, edge=None, extra=None, force=False):
    """Structured gate trace for edge/AI/post-AI diagnosis (deduped per 2s by default)."""
    global _last_pipeline_event_log
    try:
        key = f"{stage}|{outcome}|{reason}|{round(float(edge if edge is not None else state.get('last_edge', 0) or 0), 1)}"
        now = time.time()
        if not force and _last_pipeline_event_log.get("key") == key and now - _last_pipeline_event_log.get("ts", 0) < PIPELINE_EVENT_DEDUPE_SEC:
            return
        _last_pipeline_event_log = {"key": key, "ts": now}
        dbg = state.get("debug_state") or {}
        mc = state.get("market_context") or {}
        mtf = (mc.get("multi_tf") or {}).get("trends") or {}
        ec = dbg.get("edge_components") or {}
        row = {
            "ts": utc_iso(),
            "stage": stage,
            "outcome": outcome,
            "reason": reason,
            "trade_id": trade_id or "",
            "edge_score": edge if edge is not None else dbg.get("last_edge_score"),
            "edge_threshold": get_edge_threshold(),
            "effective_threshold": get_effective_edge_threshold(),
            "edge_trigger": dbg.get("pipeline_event_trigger"),
            "edge_trigger_reason": dbg.get("edge_trigger_reason"),
            "price": state.get("price"),
            "regime": state.get("regime"),
            "mtf_15m": mtf.get("15m"),
            "mtf_1h": mtf.get("1h"),
            "mtf_4h": mtf.get("4h"),
            "structure_bias": (mc.get("market_structure") or {}).get("structure_bias"),
            "adx": (mc.get("trend_strength") or {}).get("adx"),
            "ai_gate_called": (dbg.get("ai_gate") or {}).get("called"),
            "pipeline_outcome": state.get("pipeline_outcome"),
            "momentum_pts": ec.get("momentum"),
            "orderflow_pts": ec.get("orderflow"),
            **csv_research_meta(),
        }
        if extra:
            for k, v in extra.items():
                row[f"x_{k}"] = v
        dynamic_csv_writer(CSV_PIPELINE_EVENTS, row)
    except Exception as e:
        logger.debug(f"[PIPELINE EVENT] skip log: {e}")

