def log_no_signal_with_context(signal=None, reason="NO_SETUP_DETECTED", skip_stage="PRE_PIPELINE"):
    trade_id = str(uuid.uuid4()) if not signal or not signal.get("trade_id") else signal.get("trade_id")
    edge_score = state.get("last_edge", state.get("debug_state", {}).get("last_edge_score", 0.0))
    eff_thr = get_effective_edge_threshold()
    stub = {
        "trade_id": trade_id,
        "edge_score_at_entry": round(float(edge_score or 0.0), 1),
        "effective_threshold_at_entry": eff_thr,
        "features": state.get("debug_state", {}).get("last_features", {}),
    }
    enforce_log(stub, "NO_SIGNAL", reason, skip_stage=skip_stage)
    log_pipeline_event("PIPELINE", "NO_SIGNAL", reason, trade_id, edge_score, force=True)
    logger.info(f"[PIPELINE] No signal - skipping cycle | trade_id={trade_id} reason={reason} [PIPELINE ENFORCEMENT]")
    full_pipeline_trace("BLOCKED", reason, trade_id)
    _record_cycle_3m_universe(outcome="SKIPPED", skip_reason=str(reason or "NO_SIGNAL"), trade_id=trade_id)

def compute_structural_sr(candles):
    if len(candles) < 96:
        return None, None
    highs = [c[2] for c in candles[-96:]]
    lows = [c[3] for c in candles[-96:]]
    return max(highs), min(lows)

def sr_context(price, swing_high, swing_low):
    if not price or not swing_high or not swing_low:
        return 0.0, 0.0, False, False
    dist_high = abs((nz(swing_high) - nz(price)) / nz(price))
    dist_low = abs((nz(price) - nz(swing_low)) / nz(price))
    near_res = dist_high <= SR_ZONE_PCT
    near_sup = dist_low <= SR_ZONE_PCT
    return dist_high, dist_low, near_res, near_sup

def classify_sr_state(dist_high, dist_low):
    if dist_high <= SR_ZONE_PCT and dist_low <= SR_ZONE_PCT:
        return "RANGE_COMPRESSION"
    if dist_high <= SR_ZONE_PCT:
        return "NEAR_RESISTANCE"
    if dist_low <= SR_ZONE_PCT:
        return "NEAR_SUPPORT"
    return "FREE_RANGE"

def sr_bias(sr_state, regime):
    if regime == "BULL":
        return "LONG_PREFERRED"
    if regime == "BEAR":
        return "SHORT_PREFERRED"
    if sr_state == "NEAR_RESISTANCE":
        return "SHORT_PREFERRED"
    if sr_state == "NEAR_SUPPORT":
        return "LONG_PREFERRED"
    if sr_state == "RANGE_COMPRESSION":
        return "NO_TRADE"
    return "BOTH_ALLOWED"

def validate_pipeline_completion(signal: dict):
    if not signal or not signal.get("trade_id"):
        logger.error("[PIPELINE VALIDATION] CRITICAL - Missing trade_id at completion [PIPELINE ENFORCEMENT]")
        return False
    VALID_FINAL_STATES = [
        "ACTIVE", "ORDERED", "REJECTED", "BLOCKED", "EXPIRED", "COMPLETE",
        SIGNAL_STATUS_AWAITING_MIN_AGE, SIGNAL_STATUS_AWAITING_MICRO, SIGNAL_STATUS_AWAITING_5M,
        SIGNAL_STATUS_AWAITING_CHASE_3PLUS, SIGNAL_STATUS_AWAITING_DASHBOARD_CHASE,
    ]
    if signal.get("status") not in VALID_FINAL_STATES:
        logger.warning(f"[PIPELINE WARNING] Non-terminal state: {signal.get('status')} trade_id={signal.get('trade_id')} [PIPELINE ENFORCEMENT]")
        enforce_log(signal, "PIPELINE_WARNING")
        full_pipeline_trace("BLOCKED", "PIPELINE_WARNING", signal.get('trade_id'))
        return False
    logger.info(f"[PIPELINE VALIDATION] COMPLETE trade_id={signal.get('trade_id')} status={signal.get('status')} [PIPELINE ENFORCEMENT]")
    return True

def _force_paper_mode_active() -> bool:
    return (os.getenv("FORCE_PAPER_MODE") or "").strip().lower() in (
        "1", "true", "yes", "on",
    )


def _paper_skips_entry_risk_pauses() -> bool:
    """True when DAILY_DRAWDOWN / LOSS_STREAK must not pause new entries.

    Paper Showcase exists to collect trades. There is no point in a daily
    loss cap or a 2h streak pause on that runtime — both starve the dataset.
    Live copy keeps the gates: FORCE_PAPER_MODE off, and not unarmed RESEARCH.
    """
    if _force_paper_mode_active():
        return True
    return state.get("strategy_mode") == "RESEARCH" and not state.get("live_armed")


def _paper_natural_cycle_exits() -> bool:
    """Paper Showcase closes only on Scenario C ladder or thesis cut/loss.

    Hard STOP_LOSS must not skip that cycle. POST_FILL_GRACE_SEC is not a
    hold for the hard stop and is not applied here.
    """
    return _force_paper_mode_active()


def _genuine_ws_transport_ready(now: float = None) -> bool:
    """True only after a connected WS and fresh exact-symbol market update."""
    now = float(now or time.time())
    with state_lock:
        ws_tick = float(state.get("ws_last_tick") or 0)
        ws_age = (now - ws_tick) if ws_tick else float("inf")
        return bool(
            state.get("ws_transport_connected")
            and state.get("ws_ready", False)
            and ws_tick
            and 0 <= ws_age <= WS_ENTRY_FRESH_SEC
        )


def _fresh_rest_entry_quote_ready(now: float = None) -> bool:
    """Require a recent, internally consistent Bitfinex REST bid/ask snapshot.

    This is an additional entry condition, never a substitute for the genuine
    WebSocket trade-tick requirement above.
    """
    now = float(now or time.time())
    with state_lock:
        bid = float(state.get("bid") or 0)
        ask = float(state.get("ask") or 0)
        last = float(state.get("rest_price") or state.get("last_trade_price") or 0)
        quote_ts = float(
            state.get("rest_price_ts")
            or state.get("rest_last_tick")
            or state.get("bbo_ts")
            or 0
        )
    quote_age = (now - quote_ts) if quote_ts else float("inf")
    return bool(
        bid > 0
        and ask > 0
        and ask >= bid
        and last > 0
        and ((ask - bid) / bid) <= 0.02
        and 0 <= quote_age <= REST_ENTRY_FRESH_SEC
    )


def ensure_fresh_rest_entry_quote(now: float = None) -> bool:
    """Recover a stale REST entry quote without weakening the dual-feed gate.

    `refresh_bbo_state()` normally rate-limits by its last successful request.
    A stale in-memory receipt must never make that throttle suppress recovery
    indefinitely.  Force one bounded retry when the actual quote fails the
    freshness contract, then re-evaluate the same strict predicate.
    """
    global _last_rest_entry_recovery_attempt_ts
    now = float(now or time.time())
    if _fresh_rest_entry_quote_ready(now):
        return True
    if (now - float(_last_rest_entry_recovery_attempt_ts or 0)) >= REST_ENTRY_RECOVERY_SEC:
        _last_rest_entry_recovery_attempt_ts = now
        refresh_bbo_state(force=True)
    return _fresh_rest_entry_quote_ready(time.time())


def _runtime_readiness_components(now: float = None) -> dict:
    """One non-mutating definition of strategy readiness."""
    now = float(now or time.time())
    with state_lock:
        price_ok = bool(
            state.get("price") is not None
            and float(state.get("price") or 0) > 0
        )
        ohlcv_flag = bool(state.get("ohlcv_ready", False))
        ema_status = dict(state.get("ema_status") or {})
        pathway_ok = not bool(state.get("pathway_safety_block"))
        last_ready_ts = float(state.get("last_ready_ts") or 0)
        paused = bool(state.get("execution_paused", False))
        manual_paused = bool(state.get("manual_admin_pause", False))
        rest_quote_ts = float(
            state.get("rest_price_ts")
            or state.get("rest_last_tick")
            or state.get("bbo_ts")
            or 0
        )
    ws_ok = _genuine_ws_transport_ready(now)
    rest_entry_quote_ok = _fresh_rest_entry_quote_ready(now)
    ohlcv_age = (
        now - float(last_ohlcv_fetch or 0)
        if last_ohlcv_fetch
        else float("inf")
    )
    ohlcv_fresh = bool(
        last_ohlcv_fetch
        and 0 <= ohlcv_age <= max(CANDLE_STALE_SEC, OHLCV_FETCH_INTERVAL * 3)
    )
    ohlcv_ok = bool(ohlcv_flag and ohlcv_fresh)
    ema_ok = all(
        ema_status.get(name) is not None
        for name in ("ema9", "ema21", "ema200")
    )
    candle_ok = bool(len(latest_candles) >= MIN_CANDLES and ohlcv_fresh)
    buffer_ready = bool(
        len(volume_buffer) >= WINDOW_SIZE
        and len(price_buffer) >= WINDOW_SIZE
        and len(delta_buffer) >= WINDOW_SIZE
    )
    structural_prerequisites_ready = bool(
        price_ok
        and ws_ok
        and ohlcv_ok
        and ema_ok
        and candle_ok
        and buffer_ready
        and pathway_ok
    )
    # REST BBO freshness is an ephemeral entry prerequisite. It remains a
    # strict fail-closed gate, but losing it must not erase the five-second
    # stability proof already earned by the structural market-data pipeline.
    prerequisites_ready = bool(
        structural_prerequisites_ready and rest_entry_quote_ok
    )
    stable_for_sec = max(0.0, now - last_ready_ts) if last_ready_ts else 0.0
    structural_stable = bool(
        structural_prerequisites_ready
        and last_ready_ts
        and stable_for_sec >= READY_STABLE_SEC
    )
    system_ready = bool(structural_stable and rest_entry_quote_ok)
    signal_generation_ready = bool(
        system_ready
        and rest_entry_quote_ok
        and not paused
        and not manual_paused
    )
    reasons = []
    if not price_ok:
        reasons.append("NO_PRICE")
    if not ws_ok:
        reasons.append("WS_NOT_READY")
    if not rest_entry_quote_ok:
        reasons.append("REST_ENTRY_QUOTE_NOT_READY")
    if not ohlcv_ok:
        reasons.append("OHLCV_NOT_READY")
    if not ema_ok:
        reasons.append("EMA_NOT_READY")
    if not candle_ok:
        reasons.append("CANDLE_STALE")
    if not buffer_ready:
        reasons.append("BUFFERS_NOT_READY")
    if not pathway_ok:
        reasons.append("PATHWAY_SAFETY_BLOCK")
    if structural_prerequisites_ready and not structural_stable:
        reasons.append("READINESS_STABILIZING")
    if manual_paused:
        reasons.append("ADMIN_MANUAL_PAUSE")
    elif paused:
        reasons.append("EXECUTION_PAUSED")
    return {
        "price_ready": price_ok,
        "ws_transport_ready": ws_ok,
        "rest_entry_quote_ready": rest_entry_quote_ok,
        "rest_quote_age_sec": (
            max(0.0, now - rest_quote_ts) if rest_quote_ts else None
        ),
        "ohlcv_ready": ohlcv_ok,
        "ohlcv_age_sec": ohlcv_age if math.isfinite(ohlcv_age) else None,
        "ema_ready": ema_ok,
        "candle_ready": candle_ok,
        "buffers_ready": buffer_ready,
        "pathway_ready": pathway_ok,
        "prerequisites_ready": prerequisites_ready,
        "structural_prerequisites_ready": structural_prerequisites_ready,
        "structural_stable": structural_stable,
        "stable_for_sec": stable_for_sec,
        "system_ready": system_ready,
        "signal_generation_ready": signal_generation_ready,
        "readiness_reasons": reasons,
    }


def _recompute_system_readiness(now: float = None) -> dict:
    """Update the single stable readiness latch from genuine market state."""
    now = float(now or time.time())
    components = _runtime_readiness_components(now)
    with state_lock:
        if components["structural_prerequisites_ready"]:
            if not state.get("last_ready_ts"):
                state["last_ready_ts"] = now
        else:
            state["last_ready_ts"] = 0
        # Re-read after initializing/resetting the stability epoch.
        ready_since = float(state.get("last_ready_ts") or 0)
        stable_for = max(0.0, now - ready_since) if ready_since else 0.0
        structural_stable = bool(
            components["structural_prerequisites_ready"]
            and ready_since
            and stable_for >= READY_STABLE_SEC
        )
        system_ready = bool(
            structural_stable and components["rest_entry_quote_ready"]
        )
        state["system_ready"] = system_ready
        # A transient REST quote miss blocks readiness and all entries without
        # falsely returning the structurally warmed runtime to startup mode.
        state["warmup_mode"] = not structural_stable
        state["allow_rest_price"] = not components["ws_transport_ready"]
        execution_paused = bool(state.get("execution_paused", False))
        manual_admin_pause = bool(state.get("manual_admin_pause", False))
        rest_quote_was_stale = bool(state.get("rest_quote_stale", True))
        rest_quote_is_stale = not bool(components["rest_entry_quote_ready"])
        if rest_quote_is_stale and not rest_quote_was_stale:
            state["rest_quote_stale"] = True
            state["rest_quote_stale_count"] = int(
                state.get("rest_quote_stale_count") or 0
            ) + 1
            state["rest_quote_last_stale_ts"] = now
            state["rest_quote_last_transition_ts"] = now
            state["rest_quote_last_transition_reason"] = (
                "REST_ENTRY_QUOTE_NOT_READY"
            )
        elif not rest_quote_is_stale and rest_quote_was_stale:
            state["rest_quote_stale"] = False
            state["rest_quote_last_recovered_ts"] = now
            state["rest_quote_last_transition_ts"] = now
            state["rest_quote_last_transition_reason"] = (
                "REST_ENTRY_QUOTE_RECOVERED"
            )
    components["stable_for_sec"] = stable_for
    components["structural_stable"] = structural_stable
    components["system_ready"] = system_ready
    components["signal_generation_ready"] = bool(
        system_ready
        and components["rest_entry_quote_ready"]
        and not execution_paused
        and not manual_admin_pause
    )
    components["readiness_reasons"] = [
        reason
        for reason in components["readiness_reasons"]
        if reason != "READINESS_STABILIZING"
    ]
    if components["structural_prerequisites_ready"] and not structural_stable:
        components["readiness_reasons"].append("READINESS_STABILIZING")
    return components


def can_progress_new_entry(now: float = None) -> tuple:
    """Central gate for signal generation and every local entry transition."""
    runtime = _recompute_system_readiness(now)
    with _strategy_progress_incident_lock:
        progress_stalled = bool(_strategy_progress_incident["active"])
        progress_reasons = list(_strategy_progress_incident["reasons"])
    if progress_stalled:
        runtime["strategy_progress_incident"] = _strategy_progress_incident_snapshot(now)
        return False, (
            progress_reasons[0] if progress_reasons else "STRATEGY_PROGRESS_STALLED"
        ), runtime
    if not runtime["signal_generation_ready"]:
        reason = (
            runtime["readiness_reasons"][0]
            if runtime["readiness_reasons"]
            else "NEW_ENTRY_NOT_READY"
        )
        return False, reason, runtime
    return True, "READY", runtime


def can_run_ai_recovery_observation(now: float = None) -> tuple:
    """Allow one data-only AI observation to break an AI-only watchdog latch.

    This never authorizes an entry transition.  It is intentionally limited to
    the paper-only, live-disarmed research runtime when every readiness
    prerequisite other than the stale AI timestamp is healthy.
    """
    runtime = _recompute_system_readiness(now)
    with _strategy_progress_incident_lock:
        active = bool(_strategy_progress_incident["active"])
        reasons = set(_strategy_progress_incident["reasons"])
    with state_lock:
        paused = bool(state.get("execution_paused", False))
        manual_pause = bool(state.get("manual_admin_pause", False))
        live_armed = bool(state.get("live_armed", False))
    allowed = bool(
        active
        and reasons == {"AI_CADENCE_STALLED"}
        and runtime.get("system_ready")
        and not paused
        and not manual_pause
        and _force_paper_mode_active()
        and not live_armed
        and _sole_ai_research_mode()
    )
    reason = "AI_RECOVERY_OBSERVATION_ONLY" if allowed else (
        next(iter(sorted(reasons)), "AI_RECOVERY_NOT_ALLOWED")
    )
    return allowed, reason, runtime


def is_system_ready():
    # Preserve the historical fail-closed execution meaning of this helper.
    # The separate structural latch retains its five-second epoch across an
    # ephemeral REST quote miss, while exported system readiness remains strict
    # about quote freshness. Execution pauses are checked by its callers.
    return bool(_recompute_system_readiness()["system_ready"])

def pipeline_guard(stage: str, signal: dict) -> bool:
    if not signal or not signal.get("trade_id"):
        logger.error(f"[PIPELINE GUARD] Missing signal at stage {stage} [PIPELINE ENFORCEMENT]")
        full_pipeline_trace("[GUARD]", f"FAIL_{stage}", None)
        return False
    if not signal.get("trade_id"):
        logger.error(f"[PIPELINE GUARD] INVALID SIGNAL - no id at stage {stage} [PIPELINE ENFORCEMENT]")
        return False
    return True

def update_signal_pull_metrics(price):
    return

def is_data_stale():
    return not _genuine_ws_transport_ready()

def is_data_consistent():
    return (len(latest_candles) >= MIN_CANDLES and state.get("price") is not None and not is_data_stale())


def can_open_live_entry(
    *,
    require_armed: bool = True,
    now: float = None,
) -> tuple:
    """Central fail-closed gate for every direct private Bitfinex entry."""
    if _force_paper_mode_active():
        return False, "FORCE_PAPER_MODE", _runtime_readiness_components(now)
    if not _private_api_keys_ok():
        return False, "PRIVATE_API_KEYS_MISSING", _runtime_readiness_components(now)
    audit = _exchange_exposure_audit_snapshot(now)
    if not audit.get("authoritative") or not audit.get("fresh"):
        return False, "EXCHANGE_AUDIT_NOT_FRESH", _runtime_readiness_components(now)
    # Flatness is a pre-arm invariant. Once armed, managed live exposure may
    # legitimately exist; fresh synchronization and zero foreign/orphan
    # exposure remain mandatory for subsequent entries.
    if not require_armed and not audit.get("flat"):
        return False, "EXCHANGE_NOT_FLAT", _runtime_readiness_components(now)
    if audit.get("orphan_order_ids") or audit.get("orphan_position_ids"):
        return False, "EXCHANGE_ORPHAN_EXPOSURE", _runtime_readiness_components(now)
    runtime = _recompute_system_readiness(now)
    if not runtime["ws_transport_ready"]:
        return False, "WS_NOT_READY", runtime
    if not runtime["rest_entry_quote_ready"]:
        return False, "REST_ENTRY_QUOTE_NOT_READY", runtime
    if not runtime["system_ready"]:
        reason = (
            runtime["readiness_reasons"][0]
            if runtime["readiness_reasons"]
            else "SYSTEM_NOT_READY"
        )
        return False, reason, runtime
    with state_lock:
        if state.get("manual_admin_pause"):
            return False, "ADMIN_MANUAL_PAUSE", runtime
        if state.get("execution_paused"):
            return False, str(state.get("execution_reason") or "EXECUTION_PAUSED"), runtime
        if require_armed and not (
            state.get("live_armed")
            and state.get("bitfinex_live_enabled")
        ):
            return False, "LIVE_NOT_ARMED", runtime
    return True, "READY", runtime


def _strict_json_boolean(data: dict, key: str):
    if not isinstance(data, dict) or key not in data or not isinstance(data.get(key), bool):
        return None
    return data[key]

def is_engine_halted():
    return state.get("execution_paused", False) and state.get("execution_reason") == "STALE_DATA_HARD_STOP"

def should_run_pipeline() -> bool:
    entry_ok, entry_reason, _runtime = can_progress_new_entry()
    if not entry_ok:
        logger.warning(
            f"[SYSTEM BLOCK] New-entry pipeline not ready: {entry_reason} "
            "[PIPELINE ENFORCEMENT]"
        )
        return False
    if len(latest_candles) < MIN_CANDLES:
        logger.warning("[WARMUP BLOCK] Not enough candles [PIPELINE ENFORCEMENT]")
        return False
    if state.get("pathway_safety_block"):
        logger.warning(
            f"[PATHWAY SAFETY BLOCK] {state.get('pathway_safety_reason', 'integrity')} "
            f"[PIPELINE ENFORCEMENT]"
        )
        return False
    if state.get("data_quality", 0.0) < 0.6:
        logger.warning("[DATA BLOCK] Quality below threshold [PIPELINE ENFORCEMENT]")
        return False
    if is_data_stale():
        logger.critical("[STALE BLOCK] Hard stop [PIPELINE ENFORCEMENT]")
        set_execution_paused("STALE_DATA_HARD_STOP")
        return False
    now = time.time()
    if now - last_pipeline_run < MIN_PIPELINE_INTERVAL:
        return False
    return True

def detect_event_light():
    try:
        features = build_full_feature_snapshot()
        if features is None:
            return {"event_trigger": False, "edge_score": 0.1, "price": 0, "timestamp": utc_iso(), "features": {}}
        edge_score = compute_edge_score(features)
        price = nz(state.get("price"))
        if price <= 0:
            return {"event_trigger": False, "edge_score": 0.1, "price": 0, "timestamp": utc_iso(), "features": features}

        global last_event_trigger
        now = time.time()

        if now - last_event_trigger < 0.5:
            return {"event_trigger": False, "edge_score": edge_score, "price": price, "timestamp": utc_iso(), "features": features}

        if not shared_research_ai_observation_enabled():
            event_trigger, trigger_reason = False, "RESEARCH_OBSERVATION_DISABLED"
        else:
            cd_rem = ai_cooldown_remaining_sec(RESEARCH_LANE_AI_SCAN)
            if cd_rem == 0:
                event_trigger, trigger_reason = True, "PERIODIC_RESEARCH_AI"
            else:
                event_trigger, trigger_reason = False, f"AI_COOLDOWN_{cd_rem}s"

        last_event_trigger = now

        logger.info(
            f"[EVENT LIGHT] descriptive_edge={edge_score:.1f} trigger={event_trigger} "
            f"reason={trigger_reason} "
            f"[PIPELINE ENFORCEMENT]"
        )

        with state_lock:
            ds = state["debug_state"]
            ds["last_edge_score"] = edge_score
            ds["pipeline_event_trigger"] = event_trigger
            ds["edge_trigger_reason"] = trigger_reason
            ds["edge_above_threshold"] = None
            ag = dict(ds.get("ai_gate") or {"called": False, "reason": "", "edge": 0.0, "threshold": 0.0})
            if not ag.get("called"):
                ag["reason"] = trigger_reason
                ag["edge"] = edge_score
                ag["threshold"] = None
                ds["ai_gate"] = ag
            ds["pipeline_idle_reason"] = trigger_reason if not event_trigger else None
            if not event_trigger:
                ds["skip_reason"] = trigger_reason
                idle_only = (
                    str(trigger_reason).startswith("AI_COOLDOWN")
                )
                if not (idle_only and _ai_gate_was_called(ds)):
                    ds["last_block_reason"] = trigger_reason
            elif _is_misleading_ai_skip_label(ds.get("skip_reason")):
                ds["skip_reason"] = None
                if not _ai_gate_was_called(ds):
                    ds["last_block_reason"] = None

        update_debug_state_always(
            "EVENT_DETECTED",
            {"edge": edge_score, "pipeline_event_trigger": event_trigger, "edge_trigger_reason": trigger_reason},
        )
        log_pipeline_event(
            "PERIODIC_AI", "TRIGGER" if event_trigger else "WAIT",
            trigger_reason, None, edge_score,
            {"edge_observer_only": True},
        )

        return {
            "event_trigger": event_trigger,
            "edge_trigger_reason": trigger_reason,
            "edge_score": round(edge_score, 1),
            "components": {
                "momentum": 0,
                "orderflow": 0,
                "volume": 0,
                "breakout": 0,
                "liquidity": 0
            },
            "price": price,
            "timestamp": utc_iso(),
            "features": features
        }

    except Exception as e:
        logger.error(f"[EVENT ERROR V2] {e} [PIPELINE ENFORCEMENT]")
        return {"event_trigger": False, "edge_score": 0.1, "price": 0, "timestamp": utc_iso(), "features": {}}

