def _refresh_order_and_signal_ttl() -> None:
    """Run TTL expiry and stale-signal reconciliation without capacity eviction."""
    cleanup_expired_orders()
    reconcile_stale_signals()

def _is_at_signal_capacity(max_slots: int = None, lane: str = None) -> bool:
    _refresh_order_and_signal_ttl()
    with state_lock:
        max_active = max_slots or state.get("max_active_signals") or MAX_CONCURRENT_POSITIONS_DEFAULT
    return get_active_signal_count(lane) >= max_active

def ensure_signal_capacity() -> bool:
    """Return True if a new signal slot is available (TTL-only cleanup, no capacity eviction)."""
    max_active = get_effective_max_active_signals()
    return not _is_at_signal_capacity(max_active)

def apply_research_instant_fill(signal: dict):
    """Research data collection: market-fill at signal price instead of waiting on micro/EMA limits."""
    if not (is_research_data_collection() and RESEARCH_INSTANT_FILL):
        return
    signal["pullback_pct"] = 0.0
    signal["await_micro_confirm"] = False
    signal.pop("await_confirm", None)
    logger.info(
        f"[RESEARCH FILL] instant market fill trade_id={signal.get('trade_id')} "
        f"mode={signal.get('entry_mode')} [PIPELINE ENFORCEMENT]"
    )


def _resolve_awaiting_micro_limit(signal: dict) -> tuple:
    """Return (limit_price, entry_mode, confirmed) for a deferred micro-confirm entry."""
    direction = str(signal.get("final_direction") or "").upper()
    price = float(state.get("price") or signal.get("signal_price") or 0)
    limit_price, entry_mode = resolve_entry_limit_price(signal)
    ms = build_micro_sr_levels()
    micro = evaluate_micro_structure_confirm(direction, price, limit_price, ms)
    if not micro.get("confirmed"):
        return limit_price, entry_mode, False
    if entry_mode in (ENTRY_MODE_MICRO_SR, ENTRY_MODE_EMA_HYBRID):
        if direction == "LONG" and ms.get("micro_support"):
            limit_price = float(ms["micro_support"]) + MICRO_SR_ENTRY_BUFFER_USD
        elif direction == "SHORT" and ms.get("micro_resistance"):
            limit_price = float(ms["micro_resistance"]) - MICRO_SR_ENTRY_BUFFER_USD
    return limit_price, entry_mode, True


def _resolve_awaiting_5m_limit(signal: dict) -> tuple:
    """Return (limit_price, entry_mode, confirmed) for a deferred 5m HL/LH entry."""
    direction = str(signal.get("final_direction") or "").upper()
    price = float(state.get("price") or signal.get("signal_price") or 0)
    ms_5m = build_micro_sr_levels_5m()
    eval_5m = evaluate_5m_structure_confirm(direction, price, ms_5m)
    if not eval_5m.get("confirmed"):
        signal["5m_structure_eval"] = eval_5m
        signal["5m_higher_low"] = bool(ms_5m.get("higher_low"))
        signal["5m_lower_high"] = bool(ms_5m.get("lower_high"))
        return None, ENTRY_MODE_5M_TRIGGER, False
    limit_price = None
    if direction == "LONG" and ms_5m.get("micro_support"):
        limit_price = float(ms_5m["micro_support"]) + MICRO_SR_ENTRY_BUFFER_USD
    elif direction == "SHORT" and ms_5m.get("micro_resistance"):
        limit_price = float(ms_5m["micro_resistance"]) - MICRO_SR_ENTRY_BUFFER_USD
    if limit_price is None:
        return None, ENTRY_MODE_5M_TRIGGER, False
    signal["5m_micro_support"] = ms_5m.get("micro_support")
    signal["5m_micro_resistance"] = ms_5m.get("micro_resistance")
    signal["5m_higher_low"] = bool(ms_5m.get("higher_low"))
    signal["5m_lower_high"] = bool(ms_5m.get("lower_high"))
    signal["5m_structure_eval"] = eval_5m
    signal["micro_sr_limit"] = limit_price
    return limit_price, ENTRY_MODE_5M_TRIGGER, True


def _lane_duplicate_tolerance(lane: str = None) -> float:
    lane = str(lane or "").upper()
    return float(_LANE_DUPLICATE_TOL_USD.get(lane, _LANE_DUPLICATE_TOL_USD.get(LEGACY_ADOPTION_LANE, 15.0)))


def _apply_lane_limit_offset(limit: float, lane: str, direction: str) -> float:
    direction = str(direction or "").upper()
    offset = float(_LANE_LIMIT_OFFSET_USD.get(str(lane or "").upper(), 0.0))
    if direction == "LONG":
        return round(float(limit) + offset, 2)
    if direction == "SHORT":
        return round(float(limit) - offset, 2)
    return round(float(limit), 2)


def _limit_prices_near(a: float, b: float, lane: str = None, tolerance: float = None) -> bool:
    if a is None or b is None:
        return False
    try:
        fa, fb = float(a), float(b)
    except (TypeError, ValueError):
        return False
    if fa <= 0 or fb <= 0:
        return False
    tol = float(tolerance) if tolerance is not None else _lane_duplicate_tolerance(lane)
    if abs(fa - fb) <= tol:
        return True
    ref = max(fa, fb, 1.0)
    return abs(fa - fb) / ref < CLUSTER_MIN_DIST_PCT


def _signal_direction(sig: dict) -> str:
    return str(sig.get("final_direction") or sig.get("direction") or sig.get("signal_dir") or "").upper()


def _signal_planned_limit(sig: dict) -> float:
    for key in (
        "planned_limit_price", "limit_price", "micro_sr_limit", "ai_direct_limit",
        "ai_planner_limit", "ema_hybrid_limit", "planned_pullback_limit",
    ):
        v = sig.get(key)
        if v is not None:
            try:
                px = float(v)
            except (TypeError, ValueError):
                continue
            if px > 0:
                return px
    return 0.0


def _canonical_duplicate_intent(
    incoming: dict,
    existing: dict,
    *,
    incoming_limit: float,
    existing_limit: float,
) -> dict:
    """Return auditable evidence only when two records are the same live intent.

    Price proximity alone is intentionally not evidence of duplication.  Two
    independent approved signals may legitimately be close in price and must
    be governed by capacity/risk controls rather than silently suppressed.
    """
    incoming_id = str(incoming.get("trade_id") or "")
    existing_id = str(existing.get("trade_id") or "")
    if not incoming_id or not existing_id or incoming_id == existing_id:
        return {}
    incoming_call = str(incoming.get("shared_ai_call_id") or incoming.get("source_trade_id") or "")
    existing_call = str(existing.get("shared_ai_call_id") or existing.get("source_trade_id") or "")
    if not incoming_call or incoming_call != existing_call:
        return {}
    try:
        incoming_created = float(
            incoming.get("created_ts_ts") or incoming.get("signal_created_ts") or incoming.get("created_ts") or 0
        )
        existing_created = float(
            existing.get("created_ts_ts") or existing.get("signal_created_ts") or existing.get("created_ts") or 0
        )
        lifecycle_distance = abs(incoming_created - existing_created)
    except (TypeError, ValueError):
        return {}
    if lifecycle_distance > CANONICAL_DUPLICATE_LIFECYCLE_WINDOW_SEC:
        return {}
    try:
        price_distance = abs(float(incoming_limit) - float(existing_limit))
    except (TypeError, ValueError):
        return {}
    if price_distance > 0.01:
        return {}
    return {
        "shared_ai_call_id": incoming_call,
        "lifecycle_distance_sec": round(lifecycle_distance, 3),
        "price_distance_usd": round(price_distance, 4),
    }


def _find_duplicate_limit_exposure(signal: dict, direction: str, limit_price: float, lane: str = None) -> dict:
    """Return evidence for a replay of the same canonical live intent only."""
    direction = str(direction or "").upper()
    if direction not in ("LONG", "SHORT") or limit_price <= 0:
        return {}
    lane = str(lane or "").upper() or None
    same_lane_only = research_lanes_independent() and bool(lane)
    now = time.time()
    with trade_lock:
        for o in pending_orders:
            if o.get("status") != "PENDING":
                continue
            tid = o.get("trade_id")
            if not tid:
                continue
            odir = _normalize_order_side_to_dir(o.get("signal_dir") or o.get("side"))
            if odir != direction:
                continue
            o_lane = str(o.get("research_lane") or "").upper() or None
            if same_lane_only and o_lane and o_lane != lane:
                continue
            ref = o.get("planned_limit_price") or o.get("limit_price")
            if str(tid) == str(signal.get("trade_id") or ""):
                return {
                    "trade_id": tid,
                    "source": "pending_order",
                    "limit_price": ref,
                    "research_lane": o.get("research_lane"),
                    "status": "PENDING",
                    "same_trade_replay": True,
                    "shared_ai_call_id": o.get("shared_ai_call_id") or o.get("source_trade_id"),
                    "price_distance_usd": 0.0,
                    "lifecycle_distance_sec": 0.0,
                }
            intent = _canonical_duplicate_intent(signal, o, incoming_limit=limit_price, existing_limit=ref)
            if intent:
                return {
                    "trade_id": tid,
                    "source": "pending_order",
                    "limit_price": ref,
                    "research_lane": o.get("research_lane"),
                    "status": "PENDING",
                    **intent,
                }
        for p in open_positions:
            tid = p.get("trade_id")
            if not tid:
                continue
            if p.get("dir") != direction:
                continue
            p_lane = str(p.get("research_lane") or "").upper() or None
            if same_lane_only and p_lane and p_lane != lane:
                continue
            ref = p.get("entry") or 0
            if str(tid) == str(signal.get("trade_id") or ""):
                return {
                    "trade_id": tid,
                    "source": "open_position",
                    "limit_price": ref,
                    "research_lane": p.get("research_lane"),
                    "status": "FILLED",
                    "same_trade_replay": True,
                    "shared_ai_call_id": p.get("shared_ai_call_id") or p.get("source_trade_id"),
                    "price_distance_usd": 0.0,
                    "lifecycle_distance_sec": 0.0,
                }
            intent = _canonical_duplicate_intent(signal, p, incoming_limit=limit_price, existing_limit=ref)
            if intent:
                return {
                    "trade_id": tid,
                    "source": "open_position",
                    "limit_price": ref,
                    "research_lane": p.get("research_lane"),
                    "status": "FILLED",
                    **intent,
                }
        for entry in trades_map.values():
            sig = entry.get("signal_ref") or {}
            if not isinstance(sig, dict):
                continue
            tid = sig.get("trade_id")
            if not tid:
                continue
            if is_terminal_signal(sig):
                continue
            st = sig.get("status")
            if st == "ORDERED":
                if not sig.get("order_placed"):
                    continue
            elif st not in DUPLICATE_LIMIT_ACTIVE_STATUSES:
                continue
            expires_ts = sig.get("expires_ts") or (sig.get("created_ts_ts", 0) + SIGNAL_TTL_SEC)
            if expires_ts and now > expires_ts:
                continue
            if _signal_direction(sig) != direction:
                continue
            sig_lane = str(sig.get("research_lane") or "").upper() or None
            if same_lane_only and sig_lane and sig_lane != lane:
                continue
            ref = _signal_planned_limit(sig)
            if ref <= 0:
                continue
            if str(tid) == str(signal.get("trade_id") or ""):
                return {
                    "trade_id": tid,
                    "source": "signal",
                    "limit_price": ref,
                    "research_lane": sig.get("research_lane"),
                    "status": st,
                    "same_trade_replay": True,
                    "shared_ai_call_id": sig.get("shared_ai_call_id") or sig.get("source_trade_id"),
                    "price_distance_usd": 0.0,
                    "lifecycle_distance_sec": 0.0,
                }
            intent = _canonical_duplicate_intent(signal, sig, incoming_limit=limit_price, existing_limit=ref)
            if not intent:
                continue
            return {
                "trade_id": tid,
                "source": "signal",
                "limit_price": ref,
                "research_lane": sig.get("research_lane"),
                "status": st,
                **intent,
            }
    return {}


def _nearest_same_direction_exposure(signal: dict, direction: str, limit_price: float, lane: str = None) -> dict:
    """Return the nearest live same-direction intent for research only.

    This never decides whether to suppress an order.  It gives the research
    stream a complete denominator: genuinely independent nearby orders need
    to be compared with canonical replays, rather than disappearing behind a
    price-only "duplicate" label.
    """
    direction = str(direction or "").upper()
    if direction not in ("LONG", "SHORT") or limit_price <= 0:
        return {}
    incoming_id = str(signal.get("trade_id") or "")
    lane = str(lane or "").upper() or None
    same_lane_only = research_lanes_independent() and bool(lane)
    candidates = []

    def add_candidate(record: dict, source: str, status: str, price) -> None:
        try:
            price = float(price)
        except (TypeError, ValueError):
            return
        if price <= 0:
            return
        trade_id = str(record.get("trade_id") or "")
        if not trade_id or trade_id == incoming_id:
            return
        if _normalize_order_side_to_dir(
            record.get("signal_dir") or record.get("side") or record.get("final_direction") or record.get("dir")
        ) != direction:
            return
        record_lane = str(record.get("research_lane") or "").upper() or None
        if same_lane_only and record_lane and record_lane != lane:
            return
        candidates.append({
            "trade_id": trade_id,
            "source": source,
            "status": status,
            "limit_price": price,
            "research_lane": record_lane,
            "shared_ai_call_id": record.get("shared_ai_call_id") or record.get("source_trade_id"),
            "created_ts": record.get("created_ts_ts") or record.get("signal_created_ts") or record.get("created_ts"),
        })

    now = time.time()
    with trade_lock:
        for order in pending_orders:
            if order.get("status") == "PENDING":
                add_candidate(order, "pending_order", "PENDING", order.get("planned_limit_price") or order.get("limit_price"))
        for position in open_positions:
            add_candidate(position, "open_position", "FILLED", position.get("entry"))
        for entry in trades_map.values():
            record = entry.get("signal_ref") or {}
            if not isinstance(record, dict) or is_terminal_signal(record):
                continue
            expires_ts = record.get("expires_ts") or (record.get("created_ts_ts", 0) + SIGNAL_TTL_SEC)
            if expires_ts and now > expires_ts:
                continue
            add_candidate(record, "signal", str(record.get("status") or "UNKNOWN"), _signal_planned_limit(record))
    if not candidates:
        return {}
    nearest = min(candidates, key=lambda item: abs(limit_price - item["limit_price"]))
    try:
        incoming_created = float(signal.get("created_ts_ts") or signal.get("signal_created_ts") or signal.get("created_ts") or 0)
        existing_created = float(nearest.get("created_ts") or 0)
        lifecycle_distance = abs(incoming_created - existing_created) if incoming_created and existing_created else None
    except (TypeError, ValueError):
        lifecycle_distance = None
    nearest["price_distance_usd"] = round(abs(limit_price - nearest["limit_price"]), 4)
    nearest["same_shared_ai_call"] = bool(
        signal.get("shared_ai_call_id")
        and signal.get("shared_ai_call_id") == nearest.get("shared_ai_call_id")
    )
    nearest["lifecycle_distance_sec"] = round(lifecycle_distance, 3) if lifecycle_distance is not None else None
    return nearest


def _record_duplicate_intent_audit(signal: dict, direction: str, limit_price: float, decision: str, nearest: dict = None) -> None:
    """Persist the evidence needed to evaluate duplicate suppression safely."""
    nearest = nearest or {}
    with trade_lock:
        pending_count = sum(1 for order in pending_orders if order.get("status") == "PENDING")
        open_count = len(open_positions)
    row = {
        "schema": "duplicate_intent_audit_v1",
        "ts": utc_iso(),
        "decision": decision,
        "trade_id": signal.get("trade_id"),
        "shared_ai_call_id": signal.get("shared_ai_call_id") or signal.get("source_trade_id"),
        "created_ts": signal.get("created_ts_ts") or signal.get("signal_created_ts") or signal.get("created_ts"),
        "direction": direction,
        "limit_price": limit_price,
        "research_lane": signal.get("research_lane"),
        "nearest_trade_id": nearest.get("trade_id"),
        "nearest_source": nearest.get("source"),
        "nearest_status": nearest.get("status"),
        "nearest_limit_price": nearest.get("limit_price"),
        "nearest_shared_ai_call_id": nearest.get("shared_ai_call_id"),
        "price_distance_usd": nearest.get("price_distance_usd"),
        "same_shared_ai_call": nearest.get("same_shared_ai_call"),
        "lifecycle_distance_sec": nearest.get("lifecycle_distance_sec"),
        "pending_count": pending_count,
        "open_count": open_count,
        "max_pending_orders": MAX_PENDING_ORDERS,
        "bot_version": EXECUTION_FIX_VERSION,
    }
    deferrable = globals().get("_preentry_evidence_deferrable")
    if decision == "ALLOW_DISTINCT" and callable(deferrable) and deferrable(signal.get("research_lane")):
        if _enqueue_preentry_evidence(
            "DUPLICATE_INTENT_AUDIT", _preentry_evidence_keys(signal), {"row": row},
            lane=signal.get("research_lane"),
        ):
            return
    _safe_append_jsonl(DUPLICATE_INTENT_AUDIT_FILE, row, label="DUPLICATE_INTENT_AUDIT")


def _reject_duplicate_limit_order(signal: dict, limit_price: float, entry_mode: str) -> bool:
    """Expire incoming signal when same direction+limit already active. Returns True if rejected."""
    if not duplicate_limit_block_enabled():
        return False
    direction = _signal_direction(signal)
    tid = signal.get("trade_id")
    nearest = _nearest_same_direction_exposure(signal, direction, limit_price, lane=signal.get("research_lane"))
    dup = _find_duplicate_limit_exposure(signal, direction, limit_price, lane=signal.get("research_lane"))
    if not dup:
        _record_duplicate_intent_audit(signal, direction, limit_price, "ALLOW_DISTINCT", nearest)
        return False
    if dup.get("same_trade_replay"):
        _record_duplicate_intent_audit(signal, direction, limit_price, "NO_OP_SAME_TRADE_REPLAY", dup)
        logger.info(
            f"[SIM] CANONICAL_SIGNAL_REPLAY no-op trade_id={tid} dir={direction} "
            f"limit={fmt(limit_price)} source={dup.get('source')} "
            f"shared_ai_call_id={dup.get('shared_ai_call_id')} [PIPELINE ENFORCEMENT]"
        )
        return True
    _record_duplicate_intent_audit(signal, direction, limit_price, "SUPPRESS_CANONICAL_INTENT", dup)
    reason = "DUPLICATE_LIMIT_PRICE"
    with trade_lock:
        master = trades_map.get(tid, {}).get("signal_ref", signal)
        master["status"] = "EXPIRED"
        master["outcome"] = reason
        master["exit_reason"] = reason
        master["duplicate_of_trade_id"] = dup.get("trade_id")
        master["duplicate_limit_price"] = limit_price
        master["duplicate_existing_limit"] = dup.get("limit_price")
        master["duplicate_existing_lane"] = dup.get("research_lane")
        master["duplicate_existing_status"] = dup.get("status")
        master["duplicate_existing_source"] = dup.get("source")
        master["duplicate_shared_ai_call_id"] = dup.get("shared_ai_call_id")
        master["duplicate_price_distance_usd"] = dup.get("price_distance_usd")
        master["duplicate_lifecycle_distance_sec"] = dup.get("lifecycle_distance_sec")
        master["order_placed"] = False
        master["await_micro_confirm"] = False
        master["await_5m_confirm"] = False
    signal.update({
        "status": "EXPIRED",
        "outcome": reason,
        "exit_reason": reason,
        "order_placed": False,
        "await_micro_confirm": False,
        "await_5m_confirm": False,
        "duplicate_of_trade_id": dup.get("trade_id"),
        "duplicate_existing_limit": dup.get("limit_price"),
        "duplicate_existing_source": dup.get("source"),
        "duplicate_shared_ai_call_id": dup.get("shared_ai_call_id"),
        "duplicate_price_distance_usd": dup.get("price_distance_usd"),
        "duplicate_lifecycle_distance_sec": dup.get("lifecycle_distance_sec"),
    })
    _record_expired_order(signal, reason)
    _funnel_signal_expired(signal, reason)
    logger.info(
        f"[SIM] DUPLICATE_LIMIT skip trade_id={tid} dir={direction} limit={fmt(limit_price)} "
        f"entry_mode={entry_mode} lane={signal.get('research_lane')} "
        f"existing_trade_id={dup.get('trade_id')} existing_limit={fmt(dup.get('limit_price'))} "
        f"existing_lane={dup.get('research_lane')} existing_status={dup.get('status')} "
        f"source={dup.get('source')} shared_ai_call_id={dup.get('shared_ai_call_id')} "
        f"distance_usd={dup.get('price_distance_usd')} lifecycle_sec={dup.get('lifecycle_distance_sec')} "
        f"reason={reason} [PIPELINE ENFORCEMENT]"
    )
    pipeline_state_sync()
    return True


def _prepare_initial_pending_order_evidence(order: dict, signal_snapshot: dict) -> None:
    """Complete potentially slow ORDER_PLACED enrichment before PREPARE."""
    initialize_research_order_schedule(
        order, signal_snapshot,
        now=float(order.get("created_ts") or time.time()), registered=True,
    )
    order.update(copy.deepcopy(paper_policy_identity_for_sources(
        _collector_v22_epoch_id(), order, signal_snapshot,
    )))
    captured = _capture_runtime_quantity_constraints(requested_qty=order.get("qty"))
    order["signed_quantity_constraints"] = copy.deepcopy(captured.get("receipt"))
    order["quantity_constraints_status"] = copy.deepcopy(captured)
    receipt = captured.get("receipt")
    order["market_microstructure_symbol"] = (
        BITFINEX_WS_SYMBOL
        or (receipt.get("symbol") if isinstance(receipt, dict) else None)
    )
    registered_ts = time.time()
    dispatch_ts = float(order.pop("_initial_dispatch_start_ts", registered_ts))
    _append_paper_action_receipt(
        order, signal_snapshot, action_generation=0,
        action_type="INITIAL_SUBMIT",
        policy_due_ts=float(order.get("created_ts") or dispatch_ts),
        eligibility_ts=float(order.get("created_ts") or dispatch_ts),
        dispatch_start_ts=dispatch_ts, acknowledgement_ts=registered_ts,
    )


def _place_simulated_limit_order(signal: dict, limit_price: float, entry_mode: str, smart_meta: dict = None) -> bool:
    """Create a pending limit order after micro structure is confirmed."""
    if _manual_pause_block_entry(signal, "SIM_LIMIT_CREATE"):
        return False
    entry_ok, entry_reason, _runtime = can_progress_new_entry()
    if not entry_ok:
        signal["block_reason"] = entry_reason
        signal["exit_reason"] = entry_reason
        logger.warning(
            f"[WS ENTRY FREEZE] refusing new simulated limit trade_id={signal.get('trade_id')} "
            f"until a genuine WS tick is fresh [PIPELINE ENFORCEMENT]"
        )
        return False
    smart_meta = smart_meta or {}
    if refuse_non_registry_order(signal, "SIM_LIMIT_CREATE"):
        return False
    lane = str(signal["research_lane"]).upper()
    meta = trades_map.get(signal.get("trade_id"), {})
    ai = meta.get("ai") or signal.get("ai") or {}
    allowed, reason, defer = evaluate_dashboard_execution_gate(signal, ai, stage="submit")
    if defer:
        return _defer_dashboard_virtual_chase(signal)
    if not allowed:
        logger.info(
            f"[DASHBOARD GATE] limit blocked trade_id={signal.get('trade_id')} "
            f"reason={reason} virtual_chase={_signal_virtual_chase_count(signal)} "
            f"[PIPELINE ENFORCEMENT]"
        )
        signal["status"] = "BLOCKED"
        signal["outcome"] = reason
        signal["exit_reason"] = reason
        return False
    if not lane_orders_allowed(lane):
        logger.info(
            f"[SIM] BLOCK limit lane={lane} toggle OFF trade_id={signal.get('trade_id')} "
            f"[PIPELINE ENFORCEMENT]"
        )
        return False
    registered_offset_policy = is_patient_chase_lane(lane)
    _spread_blocked, _spread_bucket = (
        (False, None) if registered_offset_policy else _spread_gate_blocks_signal(signal)
    )
    if _spread_blocked:
        logger.info(
            f"[SPREAD GATE] bucket={_spread_bucket} disabled -> skipping limit order "
            f"for trade_id={signal.get('trade_id')} lane={lane} "
            f"directional_spread={signal.get('directional_spread')} "
            f"conviction_spread={signal.get('conviction_spread')} "
            f"[PIPELINE ENFORCEMENT]"
        )
        signal["status"] = "BLOCKED"
        signal["outcome"] = f"SPREAD_GATE_BUCKET_{_spread_bucket}"
        signal["exit_reason"] = f"SPREAD_GATE_BUCKET_{_spread_bucket}"
        signal["order_placed"] = False
        return False
    if _reject_duplicate_limit_order(signal, limit_price, entry_mode):
        return False
    direction = signal.get("final_direction") or _signal_direction(signal)
    if not registered_offset_policy:
        limit_price = _apply_lane_limit_offset(limit_price, lane, direction)
    original_limit_price = limit_price
    if smart_meta.get("preserve_original_limit"):
        try:
            preserved_original = float(smart_meta.get("original_planned") or 0)
        except (TypeError, ValueError):
            preserved_original = 0.0
        if preserved_original > 0:
            original_limit_price = preserved_original
    price = state.get("price")
    if not price or price <= 0:
        return False
    promotion_claim = signal.get("_promotion_claim_context")
    if promotion_claim and not _signal_promotion_claim_valid(signal, promotion_claim):
        logger.warning(
            f"[PROMOTION CLAIM] stale/duplicate promotion refused immediately before create "
            f"trade_id={signal.get('trade_id')} generation={promotion_claim.get('generation')} "
            "[PIPELINE ENFORCEMENT]"
        )
        return False
    pullback_pct = signal.get("pullback_pct", state.get("pullback_threshold", 0.001))
    signal_price = signal.get("signal_price", price)
    raw_margin_usdt = signal.get("margin_usdt")
    margin_usdt = float(FIXED_MARGIN_USDT if raw_margin_usdt is None else raw_margin_usdt)
    if margin_usdt <= 0 or margin_usdt > SIGNED_SHOWCASE_MAX_MARGIN_USDT:
        signal["status"] = "BLOCKED"
        signal["outcome"] = "SIZING_FAIL_CLOSED"
        signal["exit_reason"] = "SIZING_FAIL_CLOSED"
        signal["order_placed"] = False
        logger.warning(
            f"[SIZING] blocked non-positive explicit margin trade_id={signal.get('trade_id')} "
            f"margin_usdt={margin_usdt} [PIPELINE ENFORCEMENT]"
        )
        return False
    lev = state.get("leverage", DEFAULT_RESEARCH_LEVERAGE)
    # The signed relay copies this exact resting limit and quantity.  Size at
    # that exact limit so the requested collateral remains a hard ceiling after
    # the 0.29% anchor is applied (especially for SHORT limits above market).
    qty = margin_usdt * lev / limit_price
    order_created_ts = time.time()
    # Every order created through this path has passed the dashboard's exact
    # chase selector. The selected activation bucket must rest for a complete
    # chase interval before it is allowed to advance; otherwise a chase-3
    # activation can silently become chase 4 during the same function call.
    dashboard_exact_chase_managed = not registered_offset_policy
    relay_eligible = lane in PLATFORM_RELAY_ELIGIBLE_LANES
    requested_margin_usd = signal.get("requested_margin_usd")
    requested_notional_usd = signal.get("requested_notional_usd")
    order = {
        "trade_id": signal["trade_id"],
        "research_lane": lane,
        "research_model": signal.get("research_model") or research_lane_label(lane),
        "side": map_signal_to_exchange_side(signal["final_direction"]),
        "signal_dir": signal["final_direction"],
        "limit_price": limit_price,
        "planned_limit_price": limit_price,
        "entry_mode": entry_mode,
        "entry_path": signal.get("entry_path"),
        "entry_reason": signal.get("entry_reason"),
        "entry_limit_policy": signal.get("entry_limit_policy"),
        "qty": qty,
        "margin_usdt": margin_usdt,
        "requested_margin_usd": (
            margin_usdt if requested_margin_usd is None
            else requested_margin_usd
        ),
        "requested_notional_usd": (
            round(margin_usdt * float(lev), 4)
            if requested_notional_usd is None
            else requested_notional_usd
        ),
        "accepted_margin_usd": None,
        "accepted_notional_usd": None,
        "status": "PENDING",
        "created_ts": order_created_ts,
        "signal_created_ts": signal.get("created_ts_ts") or (signal.get("timing") or {}).get("signal_ts"),
        # Preserve canonical-intent identity through the pending/open lifecycle
        # so a callback replay can be distinguished from a nearby new signal.
        "shared_ai_call_id": signal.get("shared_ai_call_id") or signal.get("source_trade_id"),
        "shared_ai_call_ts": signal.get("shared_ai_call_ts"),
        "entry_type": "SIM_LIMIT",
        "signal_price": signal.get("signal_price"),
        "fee_type": "MAKER",
        "micro_structure_confirmed": True,
        "original_limit_price": original_limit_price,
        "limit_chase_count": (
            int(signal.get("limit_chase_count") or 0)
            if is_virtual_chase_entry_lane(lane)
            else _signal_virtual_chase_count(signal)
        ),
        "last_chase_ts": order_created_ts,
        "dashboard_exact_chase_managed": dashboard_exact_chase_managed,
        "dashboard_chase_activation_count": signal.get("dashboard_chase_activation_count"),
        "raw_policy_id": signal.get("raw_policy_id"),
        "policy_id": signal.get("policy_id"),
        "paper_only": bool(signal.get("paper_only")),
        "relay_eligible": relay_eligible,
        "chase_start_sec": signal.get("chase_start_sec"),
        "chase_end_sec": signal.get("chase_end_sec"),
        "chase_interval_sec": signal.get("chase_interval_sec"),
        "chase_remaining_gap_step": signal.get("chase_remaining_gap_step"),
        "entry_expires_ts": order_created_ts + float(
            signal.get("entry_ttl_sec") or LIMIT_ORDER_MAX_AGE_SEC
        ),
    }
    features = signal.get("features") or {}
    order["entry_velocity"] = float(features.get("velocity") or 0)
    if smart_meta.get("immediate_chase"):
        order["immediate_chase"] = True
        order["chase_start_sec"] = 0
    elif fills_first_continuous_enabled(signal):
        order["immediate_chase"] = True
        order["chase_start_sec"] = 0
    order["fill_model"] = _resolve_fill_model(signal, order)
    target_signal = copy.deepcopy(signal)
    target_signal["limit_price"] = limit_price
    target_signal["planned_limit_price"] = limit_price
    target_signal["original_limit_price"] = original_limit_price
    if is_virtual_chase_entry_lane(lane):
        lc = int(target_signal.get("limit_chase_count") or 0)
        target_signal["limit_chase_count"] = lc
        order["limit_chase_count"] = lc
        if lc == 0:
            target_signal["visible_chase_since_ts"] = time.time()
            target_signal["fill_phase"] = "CHASE0"
        elif lc >= 3:
            target_signal["fill_phase"] = _virtual_chase_fill_phase(lc)
        target_signal.pop("virtual_chase_state", None)
    else:
        target_signal["limit_chase_count"] = _signal_virtual_chase_count(target_signal)
    target_signal["last_chase_ts"] = order_created_ts
    target_signal["dashboard_exact_chase_managed"] = dashboard_exact_chase_managed
    if smart_meta.get("immediate_chase") or fills_first_continuous_enabled(signal):
        target_signal["immediate_chase"] = True
        target_signal["chase_start_sec"] = 0
    if smart_meta.get("reanchored"):
        target_signal["smart_submit_reanchored"] = True
        target_signal["smart_submit_original_planned"] = smart_meta.get("original_planned")
    target_signal.update({
        "entry_mode": entry_mode, "qty": qty,
        "order_created_ts": order_created_ts, "status": "ORDERED",
        "order_placed": True, "await_micro_confirm": False,
        "await_5m_confirm": False,
    })
    target_signal.pop("awaiting_micro_since", None)
    target_signal.pop("awaiting_5m_since", None)
    target_signal.pop("awaiting_min_age_since", None)
    order["_initial_dispatch_start_ts"] = time.time()
    coordination_blocked, coordination_reason, coordination_state = executable_live_copy_entries_blocked()
    if coordination_blocked and str(lane or "").upper() == "CONTINUOUS" and not order.get("coordination_shadow"):
        signal["block_reason"] = coordination_reason
        logger.warning(
            f"[LIVE-COPY-COORD] blocking new CONTINUOUS pending trade={order.get('trade_id')} "
            f"state={coordination_state} reason={coordination_reason} [PIPELINE ENFORCEMENT]"
        )
        return False
    # Schedule, policy identity and venue constraints may perform filesystem or
    # venue reads.  Finish them before taking the transition/state locks.
    _prepare_initial_pending_order_evidence(order, target_signal)

    def target_mutator(target):
        trade_id = str(order.get("trade_id") or "")
        if any(str(row.get("trade_id") or "") == trade_id for row in target.get("pending_orders") or []):
            raise RuntimeError("pending-order target already exists")
        if any(str(row.get("trade_id") or "") == trade_id for row in target.get("positions") or []):
            raise RuntimeError("pending-order target conflicts with open position")
        target.setdefault("pending_orders", []).append(
            _canonicalize_paper_lifecycle_identity(copy.deepcopy(order))
        )
        target["awaiting_signals"] = [
            row for row in (target.get("awaiting_signals") or [])
            if str(row.get("trade_id") or "") != str(order.get("trade_id") or "")
        ]

    def live_mutator():
        trade_id = str(order.get("trade_id") or "")
        if any(str(row.get("trade_id") or "") == trade_id for row in pending_orders):
            raise RuntimeError("pending-order live identity already exists")
        if any(str(row.get("trade_id") or "") == trade_id and row.get("status") != "CLOSED" for row in open_positions):
            raise RuntimeError("pending-order live identity is already open")
        signal.clear()
        signal.update(copy.deepcopy(target_signal))
        pending_orders.append(order)
        lane_rows = lane_pending_orders[_ensure_lane_bucket(order)]
        if order not in lane_rows:
            lane_rows.append(order)

    relay_extra = {
        "schema": "dcf-showcase-intent-v1", "event_seq": int(order.get("limit_chase_count") or 0),
        "intent_source": "live" if bool(state.get("live_armed")) else "paper",
        "direction": signal.get("final_direction"), "signal_price": signal_price,
        "limit_price": limit_price, "qty": qty, "margin_usdt": margin_usdt,
        "leverage": int(lev), "win_prob": ai.get("win_prob"),
        "edge_score": signal.get("edge_score_at_entry"),
        "effective_threshold": signal.get("effective_threshold_at_entry"),
        "research_lane": lane, "entry_limit_policy": signal.get("entry_limit_policy"),
        "entry_reason": signal.get("entry_reason"), "executable": True,
        "bot_version": EXECUTION_FIX_VERSION,
        "strategy_mode": str(state.get("strategy_mode") or "RESEARCH").upper(),
    }
    _commit_paper_lifecycle_transition(
        "ORDER_PLACED", signal.get("trade_id"), relay_extra,
        target_mutator=target_mutator, live_mutator=live_mutator,
    )
    # Derived ledgers and asynchronous enrichment happen only after the
    # canonical state/event generation is durable.
    _sync_canonical_source_pending_order(
        _canonical_source_order_market_evidence, order,
        chase_acked=False, observed_ts=order.get("last_chase_ts") or order.get("created_ts"),
    )
    _get_pending_order_evidence_worker().submit(
        f"pending-order:{order.get('trade_id')}",
        {"order": copy.deepcopy(order), "signal": copy.deepcopy(target_signal), "is_paper_entry": True},
        source_ts=float(order.get("created_ts") or time.time()),
    )
    _account_registered_order_submission(signal, ai, publish_relay=False)
    logger.info(
        f"[SIM] ORDER CREATED trade_id={signal.get('trade_id')} signal_price={fmt(signal_price)} "
        f"limit_price={fmt(limit_price)} entry_mode={entry_mode} "
        f"entry_policy={signal.get('entry_limit_policy') or 'LEGACY_NON_STRUCTURAL'} "
        f"activation_chase={order.get('limit_chase_count')} "
        f"final_direction={signal.get('final_direction')} [PIPELINE ENFORCEMENT]"
    )
    if relay_publishes_approve_outcome(lane):
        _relay_mirror(
            "ORDER_PLACED",
            {
                "trade_id": signal.get("trade_id"),
                "direction": signal.get("final_direction"),
                "signal_dir": signal.get("final_direction"),
                "side": order.get("side"),
                "qty": order.get("qty"),
                "limit_price": limit_price,
                "signal_price": signal_price,
                "entry_mode": entry_mode,
                "entry_reason": signal.get("entry_reason"),
                "entry_limit_policy": signal.get("entry_limit_policy"),
                "dashboard_chase_activation_count": order.get("limit_chase_count"),
                "research_lane": signal.get("research_lane"),
                "conf": signal.get("ai_win_prob"),
                "ai_win_prob": signal.get("ai_win_prob"),
            },
            source_ts=float(signal.get("order_created_ts") or time.time()),
        )
    if not registered_offset_policy:
        _maybe_bitfinex_limit_entry(order, signal)
    defer_instant_fill = False
    research_instant = is_research_data_collection() and RESEARCH_INSTANT_FILL
    features = signal.get("features") or state.get("feature_snapshot") or {}
    direction = signal.get("final_direction")
    if not research_instant and _tape_bounce_against(direction, features):
        defer_instant_fill = True
        logger.info(f"[SIM] Bounce vs {direction} - using pullback limit instead of instant fill [PIPELINE ENFORCEMENT]")
    setup_type = signal.get("setup_type") or classify_setup(features)
    if not research_instant and setup_type == "WEAK_SETUP":
        defer_instant_fill = True
        logger.info("[SIM] WEAK_SETUP - using pullback limit instead of instant fill [PIPELINE ENFORCEMENT]")
    can_instant = (
        pullback_pct <= 0.0
        and not defer_instant_fill
        and entry_mode not in (ENTRY_MODE_AI_DIRECT, ENTRY_MODE_5M_TRIGGER)
        and (
            research_instant
            or entry_mode in (ENTRY_MODE_MICRO_SR, ENTRY_MODE_AI_PLANNER)
            or entry_mode != ENTRY_MODE_EMA_HYBRID
        )
    )
    if can_instant and entry_mode in (ENTRY_MODE_MICRO_SR, ENTRY_MODE_AI_PLANNER):
        order["limit_price"] = price
        order["entry_type"] = "SIM_MARKET"
        order["fee_type"] = "TAKER"
        try:
            fill_order(order)
        finally:
            _release_unfilled_fill_handoff(order)
        logger.info(f"[SIM] Instant fill micro-SR at {fmt(price)} trade_id={signal.get('trade_id')} [PIPELINE ENFORCEMENT]")
    elif can_instant:
        order["limit_price"] = price
        order["entry_type"] = "SIM_MARKET"
        order["fee_type"] = "TAKER"
        try:
            fill_order(order)
        finally:
            _release_unfilled_fill_handoff(order)
        logger.info(f"[SIM] Instant fill (pullback=0%) at {fmt(price)} trade_id={signal.get('trade_id')} [PIPELINE ENFORCEMENT]")
    elif (
        defer_instant_fill
        and entry_mode not in (ENTRY_MODE_EMA_HYBRID, ENTRY_MODE_MICRO_SR, ENTRY_MODE_AI_PLANNER)
    ):
        order["await_confirm"] = True
        logger.info(f"[SIM] Pullback limit pending confirm trade_id={signal.get('trade_id')} limit={fmt(limit_price)} [PIPELINE ENFORCEMENT]")
    order["max_price_since_order"] = float(price)
    order["min_price_since_order"] = float(price)
    try:
        from execution_funnel import funnel_on_order
        funnel_on_order(signal, order)
    except Exception as _fe:
        _FUNNEL_HOOK_FAILURES.failure("order", _fe)
        logger.debug(f"[FUNNEL] order log failed: {_fe}")
    if order.get("status") == "PENDING" and order.get("entry_type") == "SIM_LIMIT":
        _try_immediate_first_chase(order, signal)
    if not registered_offset_policy:
        _log_shadow_vs_live_entry(signal, limit_price, entry_mode)
    pipeline_state_sync()
    return True


def _try_immediate_first_chase(order: dict, signal: dict) -> bool:
    """Research chase #0 — re-anchor limit once at order creation before 60s cycle."""
    if is_patient_chase_lane(order.get("research_lane") or (signal or {}).get("research_lane")):
        return False
    if order.get("dashboard_exact_chase_managed") or (signal or {}).get("dashboard_exact_chase_managed"):
        return False
    if is_virtual_chase_entry_lane(order.get("research_lane") or (signal or {}).get("research_lane")):
        return False
    if not is_research_data_collection() or not limit_chase_enabled():
        return False
    if order.get("status") != "PENDING" or order.get("entry_type") != "SIM_LIMIT":
        return False
    price = state.get("price")
    if price is None or float(price) <= 0:
        return False
    now = time.time()
    if not _limit_chase_eligible_order(order, float(price), now):
        return False
    if _apply_limit_chase(order, signal, float(price), now):
        logger.info(
            f"[SIM] IMMEDIATE_CHASE trade_id={order.get('trade_id')} "
            f"chase_count={order.get('limit_chase_count')} limit={fmt(order.get('limit_price'))} "
            f"[PIPELINE ENFORCEMENT]"
        )
        return True
    return False


def process_awaiting_micro_entries():
    """Promote AWAITING_MICRO signals to real pending limit orders once micro confirms."""
    price = state.get("price")
    if price is None or price <= 0:
        return
    now = time.time()
    with trade_lock:
        awaiting = [
            (entry.get("signal_ref") or {})
            for entry in trades_map.values()
            if isinstance(entry.get("signal_ref"), dict)
            and entry["signal_ref"].get("status") == SIGNAL_STATUS_AWAITING_MICRO
            and not is_terminal_signal(entry["signal_ref"])
        ]
    for signal in awaiting:
        tid = signal.get("trade_id")
        if not tid:
            continue
        if not lane_orders_allowed(signal.get("research_lane")):
            continue
        expires_ts = signal.get("expires_ts") or (signal.get("created_ts_ts", 0) + SIGNAL_TTL_SEC)
        if expires_ts and now > expires_ts:
            with trade_lock:
                master = trades_map.get(tid, {}).get("signal_ref", signal)
                master["status"] = "EXPIRED"
                master["outcome"] = "SIGNAL_TTL_EXPIRED"
                master["exit_reason"] = "SIGNAL_TTL_EXPIRED"
            _record_expired_order(signal, "SIGNAL_TTL_EXPIRED")
            _funnel_signal_expired(signal, "SIGNAL_EXPIRED")
            logger.info(f"[SIM] awaiting_micro expired trade_id={tid} [PIPELINE ENFORCEMENT]")
            continue
        if not ensure_signal_capacity():
            continue
        limit_price, entry_mode, confirmed = _resolve_awaiting_micro_limit(signal)
        if not confirmed:
            continue
        logger.info(
            f"[SIM] micro_structure confirmed trade_id={tid} dir={signal.get('final_direction')} "
            f"limit={fmt(limit_price)} entry_mode={entry_mode} - placing limit order [PIPELINE ENFORCEMENT]"
        )
        market = float(price)
        smart_meta = {"reanchored": False, "immediate_chase": False, "original_planned": limit_price}
        if smart_submit_enabled() and market > 0:
            limit_price, entry_mode, smart_meta = _apply_smart_submit_limit(
                signal, limit_price, entry_mode, market
            )
        _place_simulated_limit_order(signal, limit_price, entry_mode, smart_meta=smart_meta)


