def _promote_signal_to_limit_order(signal: dict, skip_virtual_defer: bool = False) -> bool:
    """Resolve limit at submit time (smart submit), then place or defer to micro/5m."""
    promotion_claim = None
    if skip_virtual_defer:
        promotion_claim = _claim_signal_promotion(signal)
        if promotion_claim is None:
            return False
        signal["_promotion_claim_context"] = promotion_claim
    try:
        return _promote_signal_to_limit_order_claimed(
            signal,
            skip_virtual_defer=skip_virtual_defer,
        )
    finally:
        signal.pop("_promotion_claim_context", None)
        if promotion_claim is not None:
            _release_signal_promotion_claim(signal, promotion_claim)


def _promote_signal_to_limit_order_claimed(signal: dict, skip_virtual_defer: bool = False) -> bool:
    """Promotion implementation executed under a generation-bound claim when required."""
    if _manual_pause_block_entry(signal, "SIGNAL_PROMOTE"):
        return False
    price = state.get("price")
    if not price or price <= 0:
        return False
    meta = trades_map.get(signal.get("trade_id"), {})
    ai = meta.get("ai") or signal.get("ai") or {}
    if not skip_virtual_defer:
        allowed, reason, defer = evaluate_dashboard_execution_gate(signal, ai, stage="promote")
        if defer:
            return _defer_dashboard_virtual_chase(signal)
        if not allowed:
            signal["status"] = "BLOCKED"
            signal["outcome"] = reason
            signal["exit_reason"] = reason
            logger.info(
                f"[DASHBOARD GATE] promote blocked trade_id={signal.get('trade_id')} "
                f"reason={reason} [PIPELINE ENFORCEMENT]"
            )
            return False
    if fills_first_continuous_enabled(signal):
        signal["await_micro_confirm"] = False
        signal["await_5m_confirm"] = False
    selected_virtual = (
        _resolve_selected_virtual_submit_limit(signal)
        if skip_virtual_defer
        else None
    )
    if selected_virtual is not None:
        limit_price, entry_mode, smart_meta = selected_virtual
        _planned = limit_price
        logger.info(
            f"[DASHBOARD GATE] preserving selected virtual limit "
            f"trade_id={signal.get('trade_id')} "
            f"virtual_chase={_signal_virtual_chase_count(signal)} "
            f"limit={fmt(limit_price)} original={fmt(smart_meta.get('original_planned'))} "
            "[PIPELINE ENFORCEMENT]"
        )
    else:
        limit_price, entry_mode, smart_meta, _planned = _resolve_submit_limit_price(signal)
    signal["entry_mode"] = entry_mode
    if fills_first_continuous_enabled(signal):
        smart_meta = dict(smart_meta or {})
        smart_meta.setdefault("immediate_chase", True)
        smart_meta["chase_start_sec"] = 0
    if _reject_duplicate_limit_order(signal, limit_price, entry_mode):
        return True
    if signal.get("await_5m_confirm") and not fills_first_continuous_enabled(signal):
        signal["limit_price"] = limit_price
        signal["planned_limit_price"] = limit_price
        signal["status"] = SIGNAL_STATUS_AWAITING_5M
        signal["awaiting_5m_since"] = time.time()
        signal["order_placed"] = False
        raw_margin_usdt = signal.get("margin_usdt")
        margin_usdt = float(FIXED_MARGIN_USDT if raw_margin_usdt is None else raw_margin_usdt)
        lev = state.get("leverage", DEFAULT_RESEARCH_LEVERAGE)
        signal["qty"] = margin_usdt * lev / price
        logger.info(
            f"[SIM] awaiting_5m_confirm trade_id={signal.get('trade_id')} "
            f"entry_mode={entry_mode} target_limit={fmt(limit_price)} "
            f"(no pending order until 5m HL/LH confirms) [PIPELINE ENFORCEMENT]"
        )
        pipeline_state_sync()
        return True
    if signal.get("await_micro_confirm") and not fills_first_continuous_enabled(signal):
        signal["limit_price"] = limit_price
        signal["planned_limit_price"] = limit_price
        signal["status"] = SIGNAL_STATUS_AWAITING_MICRO
        signal["awaiting_micro_since"] = time.time()
        signal["order_placed"] = False
        raw_margin_usdt = signal.get("margin_usdt")
        margin_usdt = float(FIXED_MARGIN_USDT if raw_margin_usdt is None else raw_margin_usdt)
        lev = state.get("leverage", DEFAULT_RESEARCH_LEVERAGE)
        signal["qty"] = margin_usdt * lev / price
        logger.info(
            f"[SIM] awaiting_micro_confirm trade_id={signal.get('trade_id')} "
            f"entry_mode={entry_mode} target_limit={fmt(limit_price)} "
            f"(no pending order until micro confirms) [PIPELINE ENFORCEMENT]"
        )
        pipeline_state_sync()
        return True
    return _place_simulated_limit_order(signal, limit_price, entry_mode, smart_meta=smart_meta)


def _account_registered_order_submission(
    signal: dict, ai: dict = None, *, publish_relay: bool = True
) -> bool:
    """Publish ORDER_SUBMITTED/ORDER_PLACED exactly once, after a local order exists."""
    if not isinstance(signal, dict):
        return False
    tid = str(signal.get("trade_id") or "")
    if not tid:
        return False
    with trade_lock:
        submitted_order = next((
            order for order in pending_orders
            if isinstance(order, dict)
            and str(order.get("trade_id") or "") == tid
            and str(order.get("status") or "").upper() == "PENDING"
        ), None)
        if submitted_order is None or signal.get("_order_submission_accounted"):
            return False
        # Preserve exact proof on the canonical signal before later cleanup
        # removes the pending-order object and stamps the signal EXPIRED.
        # Entry mode (for example AI_DIRECT_LIMIT) is a strategy label, not an
        # order type, so expiry must not try to reconstruct submission from it.
        signal["submitted_order_trade_id"] = tid
        signal["submitted_order_entry_type"] = submitted_order.get("entry_type")
        signal["submitted_order_created_ts"] = submitted_order.get("created_ts")
        signal["submitted_order_event_seq"] = int(
            submitted_order.get("limit_chase_count") or 0
        )
        signal["submitted_order_limit_price"] = submitted_order.get("limit_price")
        signal["_order_submission_accounted"] = True
    lane = signal.get("research_lane")
    _xvl_latency_mark_order(lane, signal, "submit_ts", submitted_order.get("created_ts"))
    edge = signal.get("edge_score_at_entry")
    increment_pipeline_funnel("ORDER_SUBMITTED")
    log_lane_opportunity_event(
        lane,
        "ORDER_SUBMITTED",
        tid,
        signal.get("final_direction"),
        (ai or {}).get("win_prob"),
        edge,
    )
    if relay_publishes_approve_outcome(lane):
        record_approve_outcome(
            "EXECUTED",
            "ORDER_PLACED",
            signal.get("effective_threshold_at_entry"),
            tid,
            edge,
            ai or signal.get("ai") or {},
            signal,
            publish_relay=publish_relay,
        )
    return True


