def _ai_shadow_leader_features(decision_ts: float) -> dict:
    try:
        ts_list, rows = _AI_SHADOW_TAPE.snapshot()

        def bfx_mid_at(sec):
            return _ai_shadow.mid_at(ts_list, rows, sec, max_lag=0)

        return _cvt.leader_features(_cross_venue_live(max_age_sec=0.0), decision_ts, bfx_mid_at)
    except Exception as exc:
        logger.warning(f"[AI SHADOW] leader features unavailable: {exc} [PIPELINE ENFORCEMENT]")
        return {"side": _ai_shadow.NONE, "reason": "ERROR", "error": type(exc).__name__}


def _ai_shadow_tape_features(now: float = None) -> dict:
    try:
        return _ai_shadow.tape_features(_AI_SHADOW_TAPE, float(now or time.time()))
    except Exception as exc:
        logger.warning(f"[AI SHADOW] tape features unavailable: {exc} [PIPELINE ENFORCEMENT]")
        return {"source": "UNAVAILABLE", "error": type(exc).__name__}


def _ai_shadow_observe_prompt(call_id, prompt_context: dict) -> dict:
    try:
        report = _AI_INPUT_DEAD_DETECTOR.observe(prompt_context or {})
        with _AI_SHADOW_LOCK:
            _AI_SHADOW_PROMPT_PAYLOADS[str(call_id or "")] = copy.deepcopy(prompt_context or {})
            while len(_AI_SHADOW_PROMPT_PAYLOADS) > 16:
                _AI_SHADOW_PROMPT_PAYLOADS.pop(next(iter(_AI_SHADOW_PROMPT_PAYLOADS)))
    except Exception as exc:
        logger.warning(f"[AI SHADOW] input health observe failed: {exc} [PIPELINE ENFORCEMENT]")
        return {"status": "UNAVAILABLE", "dead_fields": []}
    if report.get("status") == "DEAD_INPUT":
        logger.warning(
            "[AI INPUT DEAD FIELD] %s [PIPELINE ENFORCEMENT]",
            ", ".join(f"{d['path']}={d['kind']}x{d['calls']}" for d in report["dead_fields"][:8]),
        )
    return report


def ai_input_health_snapshot() -> dict:
    report = _AI_INPUT_DEAD_DETECTOR.report()
    report["prompt_id"] = SHARED_DIRECTION_PROMPT_ID
    report["prompt_schema"] = SHARED_DIRECTION_PROMPT_SCHEMA
    report["dead_fields"] = report["dead_fields"][:20]
    return report


def _ai_shadow_decision_ts(ai_result: dict) -> float:
    raw = (ai_result or {}).get("shared_ai_call_ts")
    try:
        return datetime.fromisoformat(str(raw).replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        return time.time()


def _ai_shadow_run_compact(ctx: dict, tape: dict, call_id: str, now_ts: float) -> dict:
    funding = (ctx or {}).get("funding") or {}
    facts = _ai_shadow.build_compact_facts(
        ctx or {}, tape or {}, now_ts=now_ts, as_of_utc=utc_iso(),
        oi_change_1h_pct=_AI_SHADOW_OI.observe(now_ts, funding.get("open_interest")),
    )
    row = {
        "schema": _ai_shadow.COMPACT_PROMPT_SCHEMA,
        "row_kind": "COMPACT_PROMPT",
        "shared_ai_call_id": call_id,
        "prompt_id": _ai_shadow.COMPACT_PROMPT_ID,
        "observed_at_utc": utc_iso(),
        "epoch_id": _collector_v22_epoch_id(),
        "git_rev": _runtime_git_rev(),
        "temperature": 0.0,
        "max_tokens": AI_SHADOW_COMPACT_MAX_TOKENS,
        "geometry": dict(_ai_shadow.COMPACT_GEOMETRY),
        "facts": facts,
        "facts_sha256": hashlib.sha256(
            json.dumps(facts, sort_keys=True, default=str).encode("utf-8")
        ).hexdigest(),
        "gates_orders": False,
        "call_state": None,
        "parsed": None,
        "side": _ai_shadow.NONE,
    }
    if not AI_SHADOW_COMPACT_PROMPT_ENABLED:
        row["call_state"] = "DISABLED"
        return row
    if os.environ.get("DEMO_MODE_ENABLED", "").lower() == "true":
        row["call_state"] = "SKIPPED_DEMO_MODE"
        return row
    allowed, reason = _AI_SHADOW_BUDGET.acquire(now_ts)
    if not allowed:
        row["call_state"] = f"SKIPPED_{reason}"
        with _AI_SHADOW_LOCK:
            _ai_shadow_status["compact_skipped"] += 1
        return row
    try:
        text, latency_ms, call_meta = call_deepseek_api_with_meta(
            _ai_shadow.render_compact_messages(facts),
            temperature=0.0,
            purpose="trading_direction_shadow",
            max_tokens=AI_SHADOW_COMPACT_MAX_TOKENS,
            response_format={"type": "json_object"},
            timeout=AI_SHADOW_COMPACT_TIMEOUT_SEC,
        )
        parsed = _ai_shadow.parse_compact_response(text)
        row.update({
            "call_state": "CALLED",
            "model": call_meta.get("requested_model") or _deepseek_model(),
            "served_model": call_meta.get("served_model"),
            "system_fingerprint": call_meta.get("system_fingerprint"),
            "latency_ms": latency_ms,
            "raw_response": str(text)[:600],
            "parsed": parsed,
            "side": _ai_shadow.compact_side(parsed),
        })
        with _AI_SHADOW_LOCK:
            _ai_shadow_status["compact_ok"] += int(parsed.get("parse_status") == "OK")
            _ai_shadow_status["compact_errors"] += int(parsed.get("parse_status") != "OK")
    except Exception as exc:
        row.update({"call_state": "ERROR", "error": str(exc)[:300]})
        with _AI_SHADOW_LOCK:
            _ai_shadow_status["compact_errors"] += 1
            _ai_shadow_status["last_compact_error"] = str(exc)[:160]
    return row


def _ai_shadow_premium_facts() -> dict:
    evaluator = next((e for e in list(_XVL_EVALUATORS.values()) if hasattr(e, "latest_features")), None)
    if evaluator is None:
        return {"status": "UNAVAILABLE"}
    try:
        return evaluator.latest_features()
    except Exception as exc:
        return {"status": "UNAVAILABLE", "error": type(exc).__name__}


AI_SHADOW_HOOK_BUDGET_SEC = POST_AI_EVIDENCE_HANDLER_TIMEOUT_SEC - 6.0
AI_SHADOW_REGIME_MIN_TIMEOUT_SEC = 5.0


def _ai_shadow_run_regime(compact_facts: dict, premium: dict, call_id: str, now_ts: float,
                          timeout_sec: float = AI_SHADOW_COMPACT_TIMEOUT_SEC) -> dict:
    facts = _ai_regime.build_regime_facts(compact_facts or {}, premium)
    row = {
        "schema": _ai_regime.REGIME_PROMPT_SCHEMA,
        "row_kind": "REGIME_PROMPT",
        "shared_ai_call_id": call_id,
        "prompt_id": _ai_regime.REGIME_PROMPT_ID,
        "hypothesis_id": _ai_regime.HYPOTHESIS_ID,
        "observed_at_utc": utc_iso(),
        "decision_ts": now_ts,
        "epoch_id": _collector_v22_epoch_id(),
        "git_rev": _runtime_git_rev(),
        "temperature": 0.0,
        "max_tokens": _ai_regime.MAX_TOKENS,
        "facts": facts,
        "stat_rule": _ai_regime.stat_rule(facts),
        "gates_orders": False,
        "call_state": None,
        "parsed": None,
    }
    if not AI_SHADOW_REGIME_PROMPT_ENABLED:
        row["call_state"] = "DISABLED"
        return row
    if os.environ.get("DEMO_MODE_ENABLED", "").lower() == "true":
        row["call_state"] = "SKIPPED_DEMO_MODE"
        return row
    if timeout_sec < AI_SHADOW_REGIME_MIN_TIMEOUT_SEC:
        row["call_state"] = "SKIPPED_HOOK_DEADLINE"
        with _AI_SHADOW_LOCK:
            _ai_shadow_status["regime_skipped"] += 1
        return row
    allowed, reason = _AI_REGIME_BUDGET.acquire(now_ts)
    if not allowed:
        row["call_state"] = f"SKIPPED_{reason}"
        with _AI_SHADOW_LOCK:
            _ai_shadow_status["regime_skipped"] += 1
        return row
    try:
        text, latency_ms, call_meta = call_deepseek_api_with_meta(
            _ai_regime.render_regime_messages(facts),
            temperature=0.0,
            purpose="trading_direction_shadow",
            max_tokens=_ai_regime.MAX_TOKENS,
            response_format={"type": "json_object"},
            timeout=min(AI_SHADOW_COMPACT_TIMEOUT_SEC, timeout_sec),
        )
        parsed = _ai_regime.parse_regime_response(text)
        row.update({
            "call_state": "CALLED",
            "model": call_meta.get("requested_model") or _deepseek_model(),
            "served_model": call_meta.get("served_model"),
            "system_fingerprint": call_meta.get("system_fingerprint"),
            "latency_ms": latency_ms,
            "raw_response": str(text)[:400],
            "parsed": parsed,
        })
        with _AI_SHADOW_LOCK:
            _ai_shadow_status["regime_ok"] += int(parsed.get("parse_status") == "OK")
            _ai_shadow_status["regime_errors"] += int(parsed.get("parse_status") != "OK")
    except Exception as exc:
        row.update({"call_state": "ERROR", "error": str(exc)[:300]})
        with _AI_SHADOW_LOCK:
            _ai_shadow_status["regime_errors"] += 1
            _ai_shadow_status["last_regime_error"] = str(exc)[:160]
    return row


def _log_decision_feature_snapshot(*, call_id, decision_ts, ctx, ai_result, tape, leader,
                                   premium, compact_row, regime_row) -> None:
    try:
        snapshot = _dfs.build_snapshot(
            call_id=call_id, decision_ts=decision_ts, decision_price=ctx.get("price"),
            ai_result=ai_result, tape=tape, leader=leader, premium=premium,
            compact_facts=compact_row.get("facts"),
            regime={"call_state": regime_row.get("call_state"), "parsed": regime_row.get("parsed")},
            tile_toggles=research_lane_enabled_map(),
            meta={"epoch_id": _collector_v22_epoch_id(), "git_rev": _runtime_git_rev(),
                  "decision_utc": ai_result.get("shared_ai_call_ts")},
        )
    except Exception as exc:
        logger.warning(f"[DECISION SNAPSHOT] build failed: {exc} [PIPELINE ENFORCEMENT]")
        return
    if _safe_append_jsonl(DECISION_FEATURE_SNAPSHOT_FILE, snapshot, label="DECISION_FEATURE_SNAPSHOT"):
        _DFS_BOOK.register(snapshot)
        with _AI_SHADOW_LOCK:
            _ai_shadow_status["snapshots_logged"] += 1


def _ai_shadow_win_prob(ai_result: dict, challengers: dict) -> dict:
    """Evidence win probability: the compact model's success probability for the score-led side.

    The shared direction prompt does not request a win probability, so its
    parsed ``win_prob`` is a placeholder 0; it is reported as null with its
    status instead of as a real 0 % forecast.
    """
    main_status = ai_result.get("win_prob_status") or "NOT_REQUESTED_BY_PROMPT"
    out = {
        "main_ai_win_prob_status": main_status,
        "main_ai_win_prob": ai_result.get("win_prob") if main_status == "EMITTED" else None,
        "win_prob": None,
        "win_prob_status": main_status if main_status == "EMITTED" else "UNAVAILABLE",
        "win_prob_source": "MAIN_AI_PROMPT" if main_status == "EMITTED" else None,
    }
    if main_status == "EMITTED":
        out["win_prob"] = ai_result.get("win_prob")
        return out
    side = (challengers.get("sides") or {}).get("llm_score_led")
    compact = challengers.get("compact") or {}
    p = {"LONG": compact.get("p_long_success"), "SHORT": compact.get("p_short_success")}.get(side)
    if compact.get("parse_status") == "OK" and p is not None:
        out.update(win_prob=round(float(p) * 100.0, 2),
                   win_prob_status="COMPACT_SHADOW_P_SUCCESS_SCORE_LED_SIDE",
                   win_prob_source=_ai_shadow.COMPACT_PROMPT_ID)
    return out


def _run_ai_shadow_challengers(ctx: dict, ai_result: dict) -> None:
    """Log every challenger's side for one shared call; never touches orders."""
    ctx = ctx or {}
    ai_result = ai_result or {}
    if ai_result.get("shadow_only"):
        return
    call_id = str(ai_result.get("shared_ai_call_id") or ai_result.get("trade_id") or ctx.get("trade_id") or "")
    if not call_id:
        return
    hook_started = time.time()
    decision_ts = _ai_shadow_decision_ts(ai_result)
    tape = ctx.get("tape_features")
    if not isinstance(tape, dict) or tape.get("source") == "UNAVAILABLE":
        tape = _ai_shadow_tape_features(decision_ts)
    leader = _ai_shadow_leader_features(decision_ts)
    compact_row = _ai_shadow_run_compact(ctx, tape, call_id, time.time())
    premium = _ai_shadow_premium_facts()
    regime_row = _ai_shadow_run_regime(
        compact_row.get("facts"), premium, call_id, decision_ts,
        timeout_sec=AI_SHADOW_HOOK_BUDGET_SEC - (time.time() - hook_started),
    )
    challengers = _ai_shadow.compute_challenger_sides(
        ctx, ai_result, tape, call_id, compact=compact_row.get("parsed"), leader=leader,
    )
    funding = ctx.get("funding") if isinstance(ctx.get("funding"), dict) else {}
    live = _cross_venue_live()
    cycle = ctx.get("cycle_3m_universe") or ctx.get("exhaustion_3m") or {}
    with state_lock:
        leverage = state.get("leverage", DEFAULT_RESEARCH_LEVERAGE)
    with _AI_SHADOW_LOCK:
        payload = _AI_SHADOW_PROMPT_PAYLOADS.pop(call_id, None)
    call_row = {
        "schema": _ai_shadow.CALL_SCHEMA,
        "row_kind": "CALL",
        "shared_ai_call_id": call_id,
        "decision_ts": decision_ts,
        "decision_utc": ai_result.get("shared_ai_call_ts"),
        "decision_price": ctx.get("price"),
        "atr14_pct_3m": cycle.get("atr14_pct_3m") if isinstance(cycle, dict) else None,
        "epoch_id": _collector_v22_epoch_id(),
        "git_rev": _runtime_git_rev(),
        "prompt_id": ai_result.get("prompt_id") or SHARED_DIRECTION_PROMPT_ID,
        "prompt_schema": SHARED_DIRECTION_PROMPT_SCHEMA,
        "prompt_input_revision": ai_result.get("prompt_input_revision") or AI_PROMPT_INPUT_REVISION,
        "deepseek_model": ai_result.get("deepseek_model"),
        "deepseek_served_model": ai_result.get("deepseek_served_model"),
        "deepseek_system_fingerprint": ai_result.get("deepseek_system_fingerprint"),
        **_ai_shadow_win_prob(ai_result, challengers),
        **challengers,
        "score_led_admission_side": challengers["sides"]["llm_score_led"],
        "admission_note": (
            "llm_score_led is the score-led admission side; each tile may add its own gates "
            "(the tile ledgers are the truth for orders). This log never changes admission."
        ),
        "tape_features": tape,
        "leader_features": leader,
        "derivatives": {
            "bitfinex": {
                "funding_rate": funding.get("rate"),
                "mark": funding.get("mark_price"),
                "index": funding.get("index_price"),
                "open_interest": funding.get("open_interest"),
                "next_funding_ts": funding.get("next_time"),
                "updated_ts": funding.get("updated_ts"),
            },
            "leaders": (live or {}).get("derivatives") if isinstance(live, dict) else None,
        },
        "compact_prompt_state": compact_row.get("call_state"),
        "geometry_model": _ai_shadow.GEOMETRY_MODEL,
        "geometry_specs": (
            _ai_shadow.tile_geometry_specs(active_tile_lifecycle_manifest(), leverage)
            + [_ai_shadow.compact_question_spec()]
        ),
        "prompt_payload": payload,
        "gates_orders": False,
    }
    _safe_append_jsonl(AI_SHADOW_CHALLENGER_FILE, call_row, label="AI_SHADOW_CHALLENGER")
    _safe_append_jsonl(AI_SHADOW_COMPACT_PROMPT_FILE, compact_row, label="AI_SHADOW_COMPACT_PROMPT")
    _safe_append_jsonl(AI_SHADOW_REGIME_PROMPT_FILE, regime_row, label="AI_SHADOW_REGIME_PROMPT")
    _log_decision_feature_snapshot(
        call_id=call_id, decision_ts=decision_ts, ctx=ctx, ai_result=ai_result, tape=tape,
        leader=leader, premium=premium, compact_row=compact_row, regime_row=regime_row,
    )
    _AI_SHADOW_BOOK.register(call_row)
    with _AI_SHADOW_LOCK:
        _ai_shadow_status["calls_logged"] += 1
        _ai_shadow_status["last_call_ts"] = time.time()
        _ai_shadow_status["recent"].append({
            "call_id": call_id,
            "sides": dict(challengers["sides"]),
            "markouts": {},
        })


def _ai_shadow_note_matured(row: dict) -> None:
    if row.get("row_kind") != "MARKOUT" or not row.get("tape_ok"):
        return
    with _AI_SHADOW_LOCK:
        for entry in _ai_shadow_status["recent"]:
            if entry["call_id"] == row.get("shared_ai_call_id"):
                entry["markouts"][int(row["horizon_sec"])] = (
                    float(row["mid_ret_bp"]),
                    float(row.get("spread_in_bp") or 0.0) / 2.0 + float(row.get("spread_out_bp") or 0.0) / 2.0,
                )
                break


def _read_jsonl_tail(path: str, max_bytes: int) -> list:
    rows = []
    try:
        with open(path, "rb") as handle:
            handle.seek(0, os.SEEK_END)
            size = handle.tell()
            handle.seek(max(0, size - max_bytes))
            chunk = handle.read()
    except OSError:
        return rows
    lines = chunk.split(b"\n")
    if len(chunk) >= max_bytes and lines:
        lines = lines[1:]
    for line in lines:
        try:
            row = json.loads(line)
        except (ValueError, UnicodeDecodeError):
            continue
        if isinstance(row, dict):
            rows.append(row)
    return rows


def _ai_shadow_boot_recover() -> None:
    history = _read_jsonl_tail(MICROSTRUCTURE_TAPE_FILE, 12 * 1024 * 1024)
    hydrated = _AI_SHADOW_TAPE.merge_history(history)
    pending = _ai_shadow.pending_calls_from_rows(
        _read_jsonl_tail(AI_SHADOW_CHALLENGER_FILE, 8 * 1024 * 1024), time.time(),
    )
    recovered = sum(1 for row in pending if _AI_SHADOW_BOOK.register(row))
    snapshots = _dfs.pending_from_rows(
        _read_jsonl_tail(DECISION_FEATURE_SNAPSHOT_FILE, 4 * 1024 * 1024), time.time(),
    )
    recovered += sum(1 for snap, done in snapshots if _DFS_BOOK.register(snap, done))
    with _AI_SHADOW_LOCK:
        _ai_shadow_status["boot_hydrated_seconds"] = hydrated
        _ai_shadow_status["boot_recovered_calls"] = recovered
    logger.info(
        f"[AI SHADOW] boot tape_seconds={hydrated} recovered_pending_calls={recovered} "
        f"[PIPELINE ENFORCEMENT]"
    )


def ai_shadow_maturation_loop():
    """Mature challenger markouts from the tape ring; research evidence only."""
    try:
        _ai_shadow_boot_recover()
    except Exception as exc:
        logger.warning(f"[AI SHADOW] boot recovery failed: {exc} [PIPELINE ENFORCEMENT]")
    while not shutdown_event.is_set():
        if shutdown_event.wait(5.0):
            break
        try:
            for row in _AI_SHADOW_BOOK.mature(_AI_SHADOW_TAPE, time.time()):
                _safe_append_jsonl(AI_SHADOW_CHALLENGER_FILE, row, label="AI_SHADOW_CHALLENGER")
                _ai_shadow_note_matured(row)
            labels = _DFS_BOOK.mature(_AI_SHADOW_TAPE, time.time())
            for row in labels:
                _safe_append_jsonl(DECISION_FEATURE_SNAPSHOT_FILE, row, label="DECISION_FEATURE_SNAPSHOT")
            if labels:
                with _AI_SHADOW_LOCK:
                    _ai_shadow_status["labels_logged"] += len(labels)
        except Exception as exc:
            logger.warning(f"[AI SHADOW] maturation failed: {exc} [PIPELINE ENFORCEMENT]")


def ai_shadow_dashboard_snapshot() -> dict:
    """Descriptive since-boot challenger markouts for the main dashboard."""
    horizons = (60, 300, 900, 3600)
    with _AI_SHADOW_LOCK:
        recent = [
            {"sides": dict(e["sides"]), "markouts": dict(e["markouts"])}
            for e in _ai_shadow_status["recent"]
        ]
        status = {k: v for k, v in _ai_shadow_status.items() if k != "recent"}
    rows = []
    for name in _ai_shadow.CHALLENGERS:
        cells = {}
        for h in horizons:
            gross, net = [], []
            for entry in recent:
                sign = _ai_shadow.side_sign(entry["sides"].get(name))
                mark = entry["markouts"].get(h)
                if sign and mark:
                    gross.append(sign * mark[0])
                    net.append(sign * mark[0] - mark[1])
            cells[str(h)] = {
                "n": len(gross),
                "mean_bp": round(sum(gross) / len(gross), 3) if gross else None,
                "mean_net_bp": round(sum(net) / len(net), 3) if net else None,
            }
        rows.append({"challenger": name, "horizons": cells})
    return {
        "schema": "ai_shadow_dashboard_v1",
        "mode": "SHADOW_ONLY_NO_ORDERS",
        "note": (
            "Descriptive since process start over at most the last 480 calls. No confidence "
            "intervals or multiple-testing correction here; the analyzer AI challenger report "
            "carries both. Tile admission is unchanged by this log."
        ),
        "prompt_id": SHARED_DIRECTION_PROMPT_ID,
        "compact_prompt_id": _ai_shadow.COMPACT_PROMPT_ID,
        "compact_enabled": AI_SHADOW_COMPACT_PROMPT_ENABLED,
        "compact_budget": _AI_SHADOW_BUDGET.snapshot(),
        "regime_prompt_id": _ai_regime.REGIME_PROMPT_ID,
        "regime_enabled": AI_SHADOW_REGIME_PROMPT_ENABLED,
        "decision_snapshot_version": _dfs.FEATURE_SET_VERSION,
        "decision_label_pending": _DFS_BOOK.pending_count(),
        "pending_calls": _AI_SHADOW_BOOK.pending_count(),
        "book": dict(_AI_SHADOW_BOOK.stats),
        "tape_ring_seconds": len(_AI_SHADOW_TAPE),
        "win_prob_status": "NOT_REQUESTED_BY_PROMPT (ai_threshold has no effect)",
        "input_health": ai_input_health_snapshot(),
        "cross_venue": cross_venue_health_snapshot(),
        "status": status,
        "horizons_sec": list(horizons),
        "rows": rows,
    }

