app = Flask("3factor_bot")
_DASHBOARD_BOOTSTRAP_COMPLETE = False

# ============================================================================
# EMERGENCY HARDENING — AI-key drain protection (2026-07-03)
# ----------------------------------------------------------------------------
# The bot is a separate Flask app on the canonical Fly :7002 runtime with its own
# DEEPSEEK_API_KEY. It is NOT behind the apps/api rate limiter. Unauthenticated
# POSTs to AI-influencing endpoints (toggle_research_lane, set_threshold,
# toggle_continuous_ai_direct, ...) let an attacker crank the trading loop into
# calling DeepSeek every cycle, draining the key. This block adds:
#   1. Per-IP in-memory rate limiting on all /api/* requests
#   2. Tight per-IP cap on AI-influencing POST endpoints (10/hour/IP)
#   3. Fail-closed admin-token gate (env BOT_ADMIN_TOKEN): all remote
#      state-mutating POST/PUT/DELETE /api/* endpoints require the token via
#      cookie or X-Bot-Admin-Token header. Direct loopback remains available
#      only for the narrow desktop recovery path. The Fly wrapper refuses to
#      boot if the token is missing.
# This does NOT touch trading logic — only the HTTP ingress policy.
# ============================================================================
from collections import defaultdict as _dd
from time import time as _now

_BOT_ADMIN_TOKEN = (os.getenv("BOT_ADMIN_TOKEN") or "").strip()
_API_RATE_LOG = _dd(deque)          # ip -> deque[timestamps] for general /api/
_AI_RATE_LOG = _dd(deque)           # ip -> deque[timestamps] for AI-influencing POSTs
_API_RATE_WINDOW_S = 60             # 1 minute
_API_RATE_MAX_PER_IP = 60           # 60 general /api/ calls per minute per IP
_AI_RATE_WINDOW_S = 3600            # 1 hour
_AI_RATE_MAX_PER_IP = 60            # remote/untrusted cap on AI-drain POSTs per hour per IP
_AI_RATE_LOCK = threading.Lock()

# Endpoints whose mutation can increase DeepSeek call frequency (thresholds, AI
# toggles, live arm). Execution-only dashboard saves (pullback, max concurrent,
# chase buckets, AI bands) are NOT capped here — they do not drain the AI key.
_AI_DRAIN_POST_PATHS = {
    "/api/toggle_continuous_ai_direct",
    "/api/toggle_research_lane",
    "/api/set_threshold",
    "/api/live_arm",
    "/api/bitfinex_live",
    "/api/reset",
}

# Read-only GET endpoints that never mutate state and never trigger AI — safe to
# leave open (still rate-limited) so the public dashboard / health checks work.
_READ_ONLY_GET_PATHS = {
    "/", "/health", "/status", "/api/ping", "/api/status", "/api/state",
    "/api/ready", "/api/build", "/api/relay-state", "/api/relay-execution-state", "/api/analyzer/summary",
    "/api/system-health", "/api/system-health/alerts", "/alerts",
    "/api/analyzer/genome", "/api/download_debug_config",
    "/api/monitor/summary", "/api/monitor/lanes", "/static/dashboard.js",
    "/api/shadow_exits/summary",
}
# Authenticated by its own handler with MONITOR_READ_TOKEN only (404 when unset);
# that token is never accepted by _admin_authed() or any other route.
_MONITOR_DIGEST_PATH = "/api/monitor/digest"
# Admin token OR the read-only MONITOR_READ_TOKEN bearer; authenticated in the handler.
_MONITOR_INTEGRITY_PATH = "/api/monitor/integrity"
_MONITOR_READ_TOKEN = monitor_api.configured_monitor_token(os.getenv("MONITOR_READ_TOKEN"), _BOT_ADMIN_TOKEN)

# Owner warehouse dumps: public internet needs the admin cookie/header.
# Loopback still allowed so the local Flask test client and home operator
# can export without stuffing BOT_ADMIN_TOKEN into the URL.
_OWNER_RESEARCH_EXPORT_PATHS = {
    "/api/export_csv",
    "/api/export.csv",
    "/api/export_debug",
}


def _client_ip() -> str:
    xff = request.headers.get("x-forwarded-for", "")
    if xff:
        return xff.split(",")[0].strip()[:64]
    return (request.remote_addr or "unknown")[:64]


def _is_local_operator(ip: str) -> bool:
    """Home dashboard on :7002 — operator at the keyboard, not a remote attacker."""
    if not ip or ip == "unknown":
        return False
    if ip in ("127.0.0.1", "::1", "localhost"):
        return True
    if ip.startswith("127.") or ip.startswith("::ffff:127."):
        return True
    return False


def _trusted_dashboard_operator(ip: str) -> bool:
    """Local operator or request carrying a valid BOT_ADMIN_TOKEN cookie/header."""
    if _is_local_operator(ip):
        return True
    if _BOT_ADMIN_TOKEN and _admin_authed():
        return True
    return False


def _is_direct_local_control(ip: str) -> bool:
    """Trust a direct loopback control call, never a proxied tunnel call."""
    if not _is_local_operator(ip):
        return False
    forwarded_headers = (
        "X-Forwarded-For",
        "CF-Connecting-IP",
        "True-Client-IP",
        "Forwarded",
    )
    return not any((request.headers.get(name) or "").strip() for name in forwarded_headers)


def _rate_check(log: dict, key: str, window_s: int, limit: int) -> bool:
    """Sliding-window per-key rate check. True = allowed, False = over limit."""
    now = _now()
    with _AI_RATE_LOCK:
        q = log[key]
        while q and q[0] < now - window_s:
            q.popleft()
        if len(q) >= limit:
            return False
        q.append(now)
        return True


def _admin_authed() -> bool:
    """True if the request carries the admin token (cookie or header)."""
    if not _BOT_ADMIN_TOKEN:
        # Never turn a missing production secret into an open remote control
        # surface. Local tests/recovery may still use a direct, unproxied
        # loopback request; the canonical Fly wrapper requires the secret.
        return _is_direct_local_control(_client_ip())
    if request.headers.get("X-Bot-Admin-Token") == _BOT_ADMIN_TOKEN:
        return True
    if request.cookies.get("bot_admin_token") == _BOT_ADMIN_TOKEN:
        return True
    return False


def _admin_authed_strict() -> bool:
    """Strict admin check for IP-sensitive endpoints.

    Unlike `_admin_authed`, this FAILS CLOSED when no BOT_ADMIN_TOKEN is
    configured — strategy internals are scrubbed unless a valid token is
    presented. Used by /api/state and /debug_state to decide whether to
    return the full state or the sanitized public view.

    Local operator on :7002 (127.0.0.1 / ::1) is always trusted — the home
    showcase dashboard must render Pathway Lab tiles and controls without
    requiring a token cookie on every refresh.
    """
    if _is_local_operator(_client_ip()):
        return True
    if not _BOT_ADMIN_TOKEN:
        return False
    if request.headers.get("X-Bot-Admin-Token") == _BOT_ADMIN_TOKEN:
        return True
    if request.cookies.get("bot_admin_token") == _BOT_ADMIN_TOKEN:
        return True
    return False


def _analyzer_view_cookie_value() -> str:
    """Return an opaque, revocable session value for the read-only analyzer.

    The browser never receives BOT_ADMIN_TOKEN as a cookie on this path.  A
    token rotation invalidates this derived value automatically, while the
    cookie cannot authorize any trading or settings endpoint.
    """
    if not _BOT_ADMIN_TOKEN:
        return ""
    return hmac.new(
        _BOT_ADMIN_TOKEN.encode("utf-8"),
        b"doxxed-analyzer-view-v1",
        hashlib.sha256,
    ).hexdigest()


def _analyzer_view_authed() -> bool:
    """Accept full admin auth or the narrower analyzer-only browser session."""
    if _admin_authed_strict():
        return True
    expected = _analyzer_view_cookie_value()
    presented = request.cookies.get("analyzer_view_session", "")
    return bool(expected and presented and hmac.compare_digest(presented, expected))


_dashboard_handler_lock = threading.Lock()
_dashboard_active_handlers = {}
_dashboard_overload_rejections = {}


def _record_overload_rejection(cap_name, reason, now=None):
    cap = str(cap_name or "unclassified")[:24]
    why = str(reason or "unknown")[:32]
    ts = time.time() if now is None else float(now)
    with _dashboard_handler_lock:
        bucket = _dashboard_overload_rejections.setdefault(cap, {"total": 0, "by_reason": {}, "last_ts": None})
        bucket["total"] += 1
        if why in bucket["by_reason"] or len(bucket["by_reason"]) < 16:
            bucket["by_reason"][why] = bucket["by_reason"].get(why, 0) + 1
        bucket["last_ts"] = ts
_DASHBOARD_TELEMETRY_STATIC_ROUTES = frozenset({
    "/api/data-sync/manifest", "/api/data-sync/sqlite-snapshot",
    "/api/data-sync/file", "/api/data-sync/ack", "/api/data-sync/lifecycle-ack",
    "/api/data-sync/analyzer-report", "/api/data-sync/platform-relay-evidence",
    "/api/ping", "/api/pause", "/api/resume", "/health", "/ready",
    "/api/ready", "/api/status", "/status", "/api/relay-state",
    "/api/relay-execution-state",
})


def _dashboard_routed_label():
    """Return a fixed, query-free label after Flask has matched the route."""
    rule = getattr(getattr(request, "url_rule", None), "rule", None)
    if rule in _DASHBOARD_TELEMETRY_STATIC_ROUTES:
        return rule
    if not rule:
        return "UNMATCHED"
    if "<" in str(rule):
        return "DYNAMIC_ROUTE"
    return "API_OTHER" if str(rule).startswith("/api/") else "PAGE_OTHER"


def _dashboard_handler_update_routed_label():
    ident = threading.get_ident()
    with _dashboard_handler_lock:
        active = _dashboard_active_handlers.get(ident)
        if active is not None:
            active["routed_label"] = _dashboard_routed_label()


def _dashboard_handler_snapshot(now=None):
    """Return bounded handler counts/ages without request or client data."""
    now = float(now if now is not None else time.monotonic())
    with _dashboard_handler_lock:
        rows = [dict(row) for row in _dashboard_active_handlers.values()]
        rejected = {
            cap: {"total": row["total"], "by_reason": dict(row["by_reason"]), "last_ts": row["last_ts"]}
            for cap, row in list(_dashboard_overload_rejections.items())[:32]
        }
    by_cap = {}
    for row in rows[:32]:
        cap = str(row.get("cap_name") or "unclassified")[:24]
        age_ms = int(max(0.0, now - float(row.get("started") or now)) * 1000)
        bucket = by_cap.setdefault(cap, {"active": 0, "oldest_ms": 0, "routes": {}})
        bucket["active"] += 1
        bucket["oldest_ms"] = max(bucket["oldest_ms"], age_ms)
        route = str(row.get("routed_label") or row.get("pre_label") or "UNCLASSIFIED")
        if route not in _DASHBOARD_TELEMETRY_STATIC_ROUTES and route not in {
            "GENERAL", "UNCLASSIFIED", "UNMATCHED", "DYNAMIC_ROUTE", "API_OTHER", "PAGE_OTHER"
        }:
            route = "UNCLASSIFIED"
        bucket["routes"][route] = bucket["routes"].get(route, 0) + 1
    return {
        "active_total": len(rows[:32]),
        "by_cap": by_cap,
        "rejected_total": sum(row["total"] for row in rejected.values()),
        "rejected_by_cap": rejected,
    }


@app.before_request
def _emergency_api_guard():
    _dashboard_handler_update_routed_label()
    path = request.path or ""
    method = (request.method or "GET").upper()

    # Bind the bounded Flask server at the start of main() so /api/ping stays
    # responsive while persistent paper state is restored. Never expose a
    # partially restored relay/dashboard snapshot during that handoff. The
    # regular /health and dashboard handlers acquire state_lock; allowing them
    # through while main() is restoring state can consume every bounded worker
    # and starve /api/ping. Return a minimal boot response here instead.
    if not _DASHBOARD_BOOTSTRAP_COMPLETE:
        if path in ("/", "/health", "/status", "/api/status"):
            return jsonify(
                {
                    "ok": True,
                    "status": "starting",
                    "boot": "starting",
                    "bot_pid": os.getpid(),
                    **_dashboard_owner_metadata(),
                    "bot_version": EXECUTION_FIX_VERSION,
                    "server_ts": utc_iso(),
                }
            ), 200
        if path in ("/api/ping", "/api/build"):
            return None
        response = jsonify(
            {
                "ok": False,
                "boot": "starting",
                "error": "dashboard state is restoring",
            }
        )
        response.status_code = 503
        response.headers["Retry-After"] = "1"
        return response

    # Only police /api/* (plus /debug_state and /). Static assets untouched.
    is_api = path.startswith("/api/") or path in ("/debug_state",)
    if not is_api and path != "/":
        return None

    ip = _client_ip()

    # General per-IP rate limit on every /api/* hit (read + write).
    # Local operator (127.0.0.1 / ::1) is exempt — demo harness + dashboard
    # polls would otherwise trip the 60/min cap and fail bot_ping/state checks.
    # The authenticated incremental mirror can legitimately request hundreds
    # of checksum-verified chunks during first sync/recovery. Counting those
    # private requests against the public 60/minute bucket made every large
    # mirror fail with 429 before it could acknowledge rotations. The admin
    # token already gates this narrow namespace; unauthorized callers remain
    # subject to the normal limiter and then fail authentication below.
    is_authenticated_data_sync = (
        path.startswith("/api/data-sync/")
        and bool(_BOT_ADMIN_TOKEN)
        and _admin_authed()
    )
    if (
        path.startswith("/api/")
        and not _is_local_operator(ip)
        and not is_authenticated_data_sync
    ):
        if not _rate_check(_API_RATE_LOG, ip, _API_RATE_WINDOW_S, _API_RATE_MAX_PER_IP):
            resp = jsonify({"error": "rate limit exceeded", "retry_after_s": _API_RATE_WINDOW_S})
            resp.status_code = 429
            resp.headers["Retry-After"] = str(_API_RATE_WINDOW_S)
            return resp

    # Read-only GETs are allowed without a token (still rate-limited above).
    if method == "GET" and path in _READ_ONLY_GET_PATHS:
        return None
    if method == "GET" and path in (_MONITOR_DIGEST_PATH, _MONITOR_INTEGRITY_PATH):
        return None
    if method == "GET" and path in _OWNER_RESEARCH_EXPORT_PATHS:
        if _admin_authed_strict():
            return None
        resp = jsonify({"error": "unauthorized — owner token required for research export"})
        resp.status_code = 401
        return resp
    if method == "OPTIONS":
        return None  # CORS preflight — let route handlers respond

    # The home bridge is a direct 127.0.0.1 caller. Allow only its narrow
    # pause/resume path during secret rotation. Remote/proxy requests carry
    # forwarding headers and therefore remain protected by BOT_ADMIN_TOKEN.
    if (
        method == "POST"
        and path in ("/api/pause", "/api/resume")
        and _is_direct_local_control(ip)
    ):
        return None

    # Everything else (POST/PUT/DELETE, or GETs not in the safe list) requires
    # the admin token remotely and fails closed if the secret is missing.
    if not _admin_authed():
        resp = jsonify({"error": "unauthorized — admin token required"})
        resp.status_code = 401
        return resp

    # Tighter cap on AI-drain POSTs for untrusted remote callers only.
    if method == "POST" and path in _AI_DRAIN_POST_PATHS and not _trusted_dashboard_operator(ip):
        if not _rate_check(_AI_RATE_LOG, ip, _AI_RATE_WINDOW_S, _AI_RATE_MAX_PER_IP):
            resp = jsonify({
                "error": "AI-influencing endpoint rate limit exceeded",
                "limit": f"{_AI_RATE_MAX_PER_IP} per hour per IP",
                "retry_after_s": _AI_RATE_WINDOW_S,
            })
            resp.status_code = 429
            resp.headers["Retry-After"] = str(_AI_RATE_WINDOW_S)
            return resp

    return None

def _fast_state_copy(value):
    """Deep-copy plain runtime state in one C-level pass.

    ``copy.deepcopy`` walks nested position/order dictionaries in Python and
    was the dominant ``trade_lock`` hold on the shared-CPU Fly VM. A pickle
    round-trip produces an equivalent independent structure for builtin data.
    A concurrent size change still raises ``RuntimeError`` so callers' bounded
    retry semantics are unchanged; unpicklable values fall back to deepcopy.
    """
    try:
        return pickle.loads(pickle.dumps(value, protocol=pickle.HIGHEST_PROTOCOL))
    except RecursionError:
        return copy.deepcopy(value)
    except (pickle.PicklingError, TypeError, AttributeError):
        return copy.deepcopy(value)


TRADE_LOCK_HOLD_BUDGET_MS = max(
    50.0,
    float(os.getenv("TRADE_LOCK_HOLD_BUDGET_MS", "500")),
)
# A blocked acquirer (fill, exit, cancel, reprice) waiting longer than this is
# counted as an over-budget wait; it is the trading-latency cost of contention.
TRADE_LOCK_WAIT_BUDGET_MS = max(
    10.0,
    float(os.getenv("TRADE_LOCK_WAIT_BUDGET_MS", "100")),
)
_TRACKED_LOCK_SITE_MAX = 128


class _TrackedRLock:
    """RLock with bounded owner diagnostics for production stall evidence."""

    def __init__(self, name: str, hold_budget_ms: float = TRADE_LOCK_HOLD_BUDGET_MS,
                 wait_budget_ms: float | None = None):
        self._lock = threading.RLock()
        self._name = name
        self._meta_lock = threading.Lock()
        self._owner_ident = None
        self._owner_name = None
        self._acquired_at = 0.0
        self._depth = 0
        self._acquire_sequence = 0
        self._timeout_count = 0
        self._last_timeout_at = 0.0
        self._last_timeout_thread = None
        self._owner_at_last_timeout = None
        self._owner_ident_at_last_timeout = None
        self._owner_transition_since = 0.0
        self._acquired_mono = 0.0
        self._acquire_site = None
        self._hold_budget_ms = float(hold_budget_ms)
        self._hold_count = 0
        self._hold_over_budget = 0
        self._hold_max_ms = 0.0
        self._hold_max_site = None
        self._hold_sites = {}
        # ``timeout_count`` stays the total of failed acquires.  Zero-wait
        # probes (/ready, /api/status) that merely observe a busy lock are not
        # waits that gave up, so they are split out from bounded-wait timeouts.
        self._probe_busy_count = 0
        self._timed_timeout_count = 0
        self._timeout_sites = {}
        self._wait_budget_ms = float(
            wait_budget_ms if wait_budget_ms is not None
            else globals().get("TRADE_LOCK_WAIT_BUDGET_MS", 100.0)
        )
        self._wait_count = 0
        self._wait_total_ms = 0.0
        self._wait_max_ms = 0.0
        self._wait_over_budget = 0
        self._wait_sites = {}
        self._interval_hold_max_ms = 0.0
        self._interval_hold_max_site = None
        self._interval_wait_max_ms = 0.0
        self._interval_wait_max_site = None

    @staticmethod
    def _caller_site():
        frame = sys._getframe(2)
        while frame is not None and frame.f_code in _TRACKED_LOCK_INTERNAL_CODES:
            frame = frame.f_back
        if frame is None:
            return "unknown"
        return f"{frame.f_code.co_name}:{frame.f_lineno}"

    def _record_hold_locked(self, site, held_ms):
        self._hold_count += 1
        over = held_ms > self._hold_budget_ms
        if over:
            self._hold_over_budget += 1
        if held_ms > self._hold_max_ms:
            self._hold_max_ms = held_ms
            self._hold_max_site = site
        if held_ms > self._interval_hold_max_ms:
            self._interval_hold_max_ms = held_ms
            self._interval_hold_max_site = site
        key = site or "unknown"
        stats = self._hold_sites.get(key)
        if stats is None:
            if len(self._hold_sites) >= _TRACKED_LOCK_SITE_MAX:
                key = "OTHER"
                stats = self._hold_sites.get(key)
            if stats is None:
                stats = {"count": 0, "total_ms": 0.0, "max_ms": 0.0,
                         "over_budget": 0, "last_over_budget_at": None}
                self._hold_sites[key] = stats
        stats["count"] += 1
        stats["total_ms"] += held_ms
        if held_ms > stats["max_ms"]:
            stats["max_ms"] = held_ms
        if over:
            stats["over_budget"] += 1
            stats["last_over_budget_at"] = time.time()

    def hold_stats(self, top: int = 8) -> dict:
        with self._meta_lock:
            sites = [
                {
                    "site": site,
                    "count": row["count"],
                    "max_ms": round(row["max_ms"], 1),
                    "mean_ms": round(row["total_ms"] / row["count"], 2) if row["count"] else 0.0,
                    "over_budget": row["over_budget"],
                    "last_over_budget_at": row["last_over_budget_at"],
                }
                for site, row in self._hold_sites.items()
            ]
            summary = {
                "name": self._name,
                "budget_ms": self._hold_budget_ms,
                "holds": self._hold_count,
                "over_budget": self._hold_over_budget,
                "max_ms": round(self._hold_max_ms, 1),
                "max_site": self._hold_max_site,
            }
        sites.sort(key=lambda row: (row["over_budget"], row["max_ms"]), reverse=True)
        summary["top_sites"] = sites[:max(0, int(top))]
        return summary

    def telemetry_counters(self, top: int = 5, reset_interval: bool = False) -> dict:
        """Cumulative counters plus per-interval maxima for runtime telemetry.

        Only the single telemetry sampler may pass ``reset_interval=True``.
        """
        with self._meta_lock:
            wait_sites = sorted(
                (
                    {"site": site, "count": row["count"],
                     "total_ms": round(row.get("total_ms", 0.0), 1),
                     "max_ms": round(row["max_ms"], 1)}
                    for site, row in self._wait_sites.items()
                ),
                key=lambda row: row["total_ms"], reverse=True,
            )[:max(0, int(top))]
            timeout_sites = sorted(
                (
                    {"site": site, "count": row["count"]}
                    for site, row in self._timeout_sites.items()
                ),
                key=lambda row: row["count"], reverse=True,
            )[:max(0, int(top))]
            out = {
                "name": self._name,
                "hold_budget_ms": self._hold_budget_ms,
                "wait_budget_ms": self._wait_budget_ms,
                "holds": self._hold_count,
                "hold_over_budget": self._hold_over_budget,
                "timeout_count": self._timeout_count,
                "probe_busy_count": self._probe_busy_count,
                "timed_timeout_count": self._timed_timeout_count,
                "waits": self._wait_count,
                "wait_total_ms": round(self._wait_total_ms, 1),
                "wait_over_budget": self._wait_over_budget,
                "interval_hold_max_ms": round(self._interval_hold_max_ms, 1),
                "interval_hold_max_site": self._interval_hold_max_site,
                "interval_wait_max_ms": round(self._interval_wait_max_ms, 1),
                "interval_wait_max_site": self._interval_wait_max_site,
                "top_wait_sites": wait_sites,
                "top_timeout_sites": timeout_sites,
            }
            if reset_interval:
                self._interval_hold_max_ms = 0.0
                self._interval_hold_max_site = None
                self._interval_wait_max_ms = 0.0
                self._interval_wait_max_site = None
        return out

    @staticmethod
    def _bump_site_locked(table, site, field, value=1.0, max_value=None):
        key = site or "unknown"
        row = table.get(key)
        if row is None:
            if len(table) >= _TRACKED_LOCK_SITE_MAX:
                key = "OTHER"
                row = table.get(key)
            if row is None:
                row = {"count": 0, field: 0.0, "max_ms": 0.0}
                table[key] = row
        row["count"] += 1
        row[field] = row.get(field, 0.0) + value
        if max_value is not None and max_value > row["max_ms"]:
            row["max_ms"] = max_value

    def acquire(self, blocking=True, timeout=-1):
        probe = (not blocking) or timeout == 0
        waited_ms = None
        wait_site = None
        if probe:
            acquired = self._lock.acquire(False)
        else:
            # Uncontended path costs one extra non-blocking attempt; only a
            # contended acquire pays for timing and caller-site resolution.
            acquired = self._lock.acquire(False)
            if not acquired:
                wait_site = self._caller_site()
                started = time.monotonic()
                acquired = self._lock.acquire(True, timeout)
                waited_ms = max(0.0, (time.monotonic() - started) * 1000.0)
        if waited_ms is not None:
            with self._meta_lock:
                self._wait_count += 1
                self._wait_total_ms += waited_ms
                if waited_ms > self._wait_max_ms:
                    self._wait_max_ms = waited_ms
                if waited_ms > self._interval_wait_max_ms:
                    self._interval_wait_max_ms = waited_ms
                    self._interval_wait_max_site = wait_site
                if waited_ms > self._wait_budget_ms:
                    self._wait_over_budget += 1
                self._bump_site_locked(
                    self._wait_sites, wait_site, "total_ms", waited_ms, waited_ms
                )
        if acquired:
            ident = threading.get_ident()
            with self._meta_lock:
                if self._owner_ident == ident:
                    self._depth += 1
                else:
                    self._owner_ident = ident
                    self._owner_name = threading.current_thread().name
                    self._acquired_at = time.time()
                    self._acquired_mono = time.monotonic()
                    self._acquire_site = self._caller_site()
                    self._depth = 1
                    self._acquire_sequence += 1
                self._owner_transition_since = 0.0
        else:
            timeout_site = wait_site or self._caller_site()
            with self._meta_lock:
                self._timeout_count += 1
                if probe:
                    self._probe_busy_count += 1
                else:
                    self._timed_timeout_count += 1
                self._bump_site_locked(
                    self._timeout_sites,
                    f"{'probe' if probe else 'timed'}:{timeout_site}",
                    "total",
                )
                self._last_timeout_at = time.time()
                self._last_timeout_thread = threading.current_thread().name
                self._owner_at_last_timeout = (
                    self._owner_name or "OWNER_TRANSITION_PENDING"
                )
                self._owner_ident_at_last_timeout = self._owner_ident
                if self._owner_ident is None and self._depth == 0:
                    if self._owner_transition_since <= 0.0:
                        self._owner_transition_since = self._last_timeout_at
                else:
                    self._owner_transition_since = 0.0
        return acquired

    def release(self):
        ident = threading.get_ident()
        with self._meta_lock:
            if self._owner_ident != ident or self._depth <= 0:
                raise RuntimeError(f"cannot release un-owned {self._name}")
            self._depth -= 1
            # Keep metadata and the underlying ownership transition atomic to
            # diagnostics. Clearing metadata before RLock.release() created a
            # real window where a failed probe reported depth=0/owner=None even
            # though another thread still could not acquire the lock.
            self._lock.release()
            if self._depth == 0:
                held_ms = max(0.0, (time.monotonic() - self._acquired_mono) * 1000.0)
                self._record_hold_locked(self._acquire_site, held_ms)
                self._owner_ident = None
                self._owner_name = None
                self._acquired_at = 0.0
                self._acquired_mono = 0.0
                self._acquire_site = None

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc_value, tb):
        self.release()
        return False

    def _is_owned(self):
        return self._lock._is_owned()

    def diagnostics(self, now=None):
        with self._meta_lock:
            owner_ident = self._owner_ident
            owner_name = self._owner_name
            acquired_at = self._acquired_at
            depth = self._depth
            acquire_sequence = self._acquire_sequence
            timeout_count = self._timeout_count
            probe_busy_count = self._probe_busy_count
            timed_timeout_count = self._timed_timeout_count
            last_timeout_at = self._last_timeout_at
            last_timeout_thread = self._last_timeout_thread
            owner_at_last_timeout = self._owner_at_last_timeout
            owner_ident_at_last_timeout = self._owner_ident_at_last_timeout
            owner_transition_since = self._owner_transition_since
            acquire_site = self._acquire_site
        held_sec = max(0.0, float(now or time.time()) - acquired_at) if acquired_at else 0.0
        transition_age_sec = (
            max(0.0, float(now or time.time()) - owner_transition_since)
            if owner_transition_since else None
        )
        stack_tail = []
        owner_active = False
        if owner_ident is not None:
            frame = sys._current_frames().get(owner_ident)
            if frame is not None:
                owner_active = True
                stack_tail = [
                    f"{Path(item.filename).name}:{item.lineno}:{item.name}"
                    for item in traceback.extract_stack(frame)[-8:]
                ]
        return {
            "name": self._name,
            "owner_thread": owner_name,
            "owner_ident": owner_ident,
            "owner_active": owner_active,
            "held_seconds": round(held_sec, 3),
            "depth": depth,
            "acquire_sequence": acquire_sequence,
            "timeout_count": timeout_count,
            "probe_busy_count": probe_busy_count,
            "timed_timeout_count": timed_timeout_count,
            "last_timeout_at": last_timeout_at or None,
            "last_timeout_thread": last_timeout_thread,
            "owner_at_last_timeout": owner_at_last_timeout,
            "owner_ident_at_last_timeout": owner_ident_at_last_timeout,
            "owner_transition_age_sec": (
                round(transition_age_sec, 3)
                if transition_age_sec is not None else None
            ),
            "stack_tail": stack_tail,
            "acquire_site": acquire_site,
        }


_TRACKED_LOCK_INTERNAL_CODES = frozenset({
    _TrackedRLock.acquire.__code__,
    _TrackedRLock.__enter__.__code__,
})

state_lock = _TrackedRLock("state_lock")
trade_lock = _TrackedRLock("trade_lock")
position_close_lock = threading.RLock()
position_evaluation_lock = threading.Lock()
