def all_research_wipe_paths(
    include_validation_artifacts: bool = True,
    include_legacy_logs: bool = False,
) -> list:
    paths = set(research_wipe_file_paths())
    paths |= set(_research_wipe_rotated_jsonl_paths())
    paths |= set(_analyzer_output_wipe_globs())
    paths |= set(_wipe_reports_recursive())
    if include_validation_artifacts:
        paths |= set(_pathway_validation_artifact_paths())
    if include_legacy_logs:
        paths |= set(_legacy_redundant_log_paths())
    return sorted(paths)

def _delete_paths(paths) -> tuple:
    deleted = []
    errors = []
    seen = set()
    for path in paths:
        if not path or path in seen:
            continue
        seen.add(path)
        try:
            if os.path.exists(path):
                os.remove(path)
                deleted.append(path)
        except PermissionError as e:
            errors.append(f"{path}: locked — {e}")
        except Exception as e:
            errors.append(f"{path}: {e}")
    return deleted, errors

def _reset_runtime_log_handlers():
    """Truncate the rotating runtime log without restarting the process."""
    for h in logger.handlers:
        if not isinstance(h, RotatingFileHandler):
            continue
        try:
            with h.lock:
                if h.stream:
                    h.stream.close()
                    h.stream = None
                for i in range(LOG_BACKUP_COUNT + 5, -1, -1):
                    path = h.baseFilename if i == 0 else f"{h.baseFilename}.{i}"
                    if os.path.exists(path):
                        os.remove(path)
                h.stream = h._open()
        except Exception as e:
            logger.error(f"[FRESH COLLECTION] Log handler reset failed: {e} [PIPELINE ENFORCEMENT]")

def reset_all_research_files(*, archive_path: str = None) -> dict:
    """Delete live epoch research files AND permanently purge quarantine trees.

    Infected fills must not be recoverable. Previous resets only moved files
    into research_epoch_quarantine; this path deletes both the live epoch
    JSONL/logs and every quarantine archive under the runtime root.
    """
    from research.epoch_quarantine import purge_quarantine_archives
    if not archive_path:
        return {
            "wipe_aborted": True, "deleted": [],
            "errors": ["verified archive_path is required before research deletion"],
        }
    live_paths = all_research_wipe_paths(include_validation_artifacts=True, include_legacy_logs=True)
    inventory = _load_verified_archive_inventory(archive_path) if archive_path else []
    if archive_path:
        inventoried = {os.path.abspath(str(row["path"])) for row in inventory}
        actual = {os.path.abspath(path) for path in live_paths if path and os.path.isfile(path)}
        if inventoried != actual:
            return {
                "wipe_aborted": True, "deleted": [], "errors": [
                    f"planned deletion set changed expected={len(inventoried)} actual={len(actual)}"
                ],
            }
    deleted, errors = _delete_paths(live_paths)
    # Fly runs from data/runtime while research/ is a sibling volume path
    # reached through a link. Use their verified common data root so the purge
    # guard accepts only that volume instead of falsely treating the canonical
    # genome quarantine as outside the runtime boundary.
    runtime_root = os.path.commonpath([
        str(Path(os.getcwd()).resolve()),
        str(Path("research/genome/epoch_quarantine").resolve()),
    ])
    purge = purge_quarantine_archives(runtime_root, preserve_research_archive=True)
    errors.extend(purge.get("errors") or [])
    deletion_receipt = None
    if archive_path and not errors:
        deletion_receipt = _finalize_archive_deletion_receipt(archive_path, inventory, deleted)
    return {
        "epoch_id": None,
        "path": None,
        "cutoff_utc": utc_iso(),
        "moved": [],
        "deleted": deleted,
        "purged_quarantine": purge.get("deleted_trees") or [],
        "purged_files": int(purge.get("deleted_files") or 0),
        "errors": errors,
        "deletion_receipt": deletion_receipt,
        "wipe_aborted": bool(errors),
    }

