def _pathway_shared_execution_spec() -> dict:
    """Frozen execution defaults shown on every Pathway Lab tile."""
    try:
        chase_step = get_limit_chase_step_pct()
    except Exception:
        chase_step = LIMIT_CHASE_STEP_PCT_DEFAULT
    cd = int(RESEARCH_AI_COOLDOWN_SEC)
    cd_min = max(1, round(cd / 60))
    return {
        "ai_scan_cadence_sec": cd,
        "ai_scan_cadence_label": f"~{cd}s (~{cd_min} min) AI_SCAN periodic DeepSeek",
        "limit_chase_enabled": limit_chase_enabled(),
        "limit_chase_step_pct": chase_step,
        "limit_chase_label": f"25% limit chase (step={chase_step * 100:.0f}% of distance)",
        "margin_usd": float(FIXED_MARGIN_USDT),
        "signal_ttl_min": max(1, int(SIGNAL_TTL_SEC // 60)),
        "post_ai_gates": "log-only telemetry (sole-AI research — gates do not block tiles)",
        "independence": "Per-tile lock · toggle · orders · CSV · tick replay",
    }


def _strategy_detail_lines(entry: dict, exit: dict, extra: list = None) -> list:
    """Human-readable strategy block for dashboard tiles (architecture frozen)."""
    shared = _pathway_shared_execution_spec()
    lines = [
        str(entry.get("spawn") or entry.get("trigger") or entry.get("ai_path") or "—"),
        f"Entry: {entry.get('execution') or entry.get('entry_path') or '—'}",
        f"Chase: {entry.get('chase_detail') or shared['limit_chase_label']}",
        f"AI cadence: {entry.get('ai_cadence') or shared['ai_scan_cadence_label']}",
        f"Exit: {exit.get('profile')} · ladder {exit.get('ladder')}",
        f"Thesis stop: {exit.get('thesis_stop_margin_pct')}% margin unreal",
        f"Final hard stop: {exit.get('hard_stop_margin_pct')}% margin unreal",
        f"MFE protect: peak ≥{exit.get('mfe_protect_margin_pct')}% margin → skip fast thesis cut",
        f"Thesis pause above: +{exit.get('thesis_pause_above_margin_pct')}% unreal",
        f"Time cap: {exit.get('fixed_time_exit')}",
        f"Margin: ${entry.get('margin_usd', shared['margin_usd']):.2f} · signal TTL {shared['signal_ttl_min']}m",
        f"Post-AI: {entry.get('post_ai_gates') or shared['post_ai_gates']}",
    ]
    if extra:
        lines.extend(extra)
    return lines


def _annotate_lanes_with_exec_mode(lanes: list) -> list:
    """Pt 5 (toggle contract): tag each lane spec with its current execution
    mode + human-readable banner text so the dashboard never lies about what
    a tile is actually allowed to do.

    Replaces hardcoded 'paper-only' / 'never Bitfinex live' strings with
    dynamic per-mode wording driven by execution_mode_for_lane().
    """
    out = []
    for spec in lanes or []:
        try:
            spec = dict(spec)  # shallow copy so we don't mutate caller's dict
            lane_id = str(spec.get("lane") or "").upper()
            mode = execution_mode_for_lane(lane_id)
            block = lane_execution_block_reason(lane_id)
            spec["exec_mode"] = mode
            spec["exec_block_reason"] = block
            spec["exec_banner"] = _exec_mode_banner_text(mode, block, lane_id)
            selected = [
                chase_count_bucket(n).replace("_chases", "").replace("_chase", "")
                for n in range(0, CHASE_WINDOW_MAX_INDEX + 1)
                if chase_bucket_allowed(n)
            ]
            policy_module = TILE_POLICY_MODULES.get(lane_id)
            template = list(getattr(getattr(policy_module, "SPEC", None), "chase_windows", ()))
            spec["chase_timing"] = {
                "global_submit_buckets": selected,
                "global_submit_label": ", ".join(selected) if selected else "none",
                "template_reprice_buckets": template,
                "template_reprice_label": ", ".join(str(n) for n in template) if template else "continuous/global",
                "contract": (
                    "A paper order may first appear only inside a globally selected bucket. "
                    "The tile Reprice template label is its post-submit schedule, not permission "
                    "to bypass the global selector."
                ),
            }
            spec["platform_relay_eligible"] = (
                lane_id in PLATFORM_RELAY_ELIGIBLE_LANES
            )
            spec["platform_relay_configured"] = (
                lane_id in PLATFORM_RELAY_CONFIGURED_LANES
            )
            spec["platform_relay_blocker"] = PLATFORM_RELAY_BLOCKERS.get(lane_id)
            spec["platform_relay_gate"] = (
                "Tile ON + platform relay ON"
                if spec["platform_relay_eligible"]
                else (
                    f"Configured but blocked: {spec['platform_relay_blocker']}"
                    if spec["platform_relay_configured"] else "Not relay eligible"
                )
            )
            out.append(spec)
        except Exception:
            out.append(spec)
    return out


def _exec_mode_banner_text(mode: str, block: str | None, lane_id: str) -> str:
    """Truthful short banner for the tile. Drives the green/blue/yellow/red strip."""
    if mode == EXEC_MODE_LIVE:
        return "LIVE BITFINEX LIMIT ORDERS ENABLED"
    if mode == EXEC_MODE_PAPER:
        if lane_id in PLATFORM_RELAY_ELIGIBLE_LANES:
            return "LOCAL PAPER ORDERS ENABLED — live copy requires platform relay ON"
        if lane_id in PLATFORM_RELAY_CONFIGURED_LANES:
            capability = str(
                (COMBO_LANE_SPECS.get(lane_id) or {}).get("relay_capability") or ""
            ).upper()
            blocker_text = {
                "BLOCKED_UNQUALIFIED": "strategy is not qualified",
                "BLOCKED_PARTIAL_REDUCTION_UNPROVEN": (
                    "partial-close relay support is not verified"
                ),
                "BLOCKED_INITIAL_STOP_SWEEP_REQUIRED": (
                    "initial-stop evidence is still required"
                ),
            }.get(capability, "relay capability is not proven")
            return f"LOCAL PAPER ORDERS ENABLED — live copy blocked: {blocker_text}"
        return "PAPER ORDERS ENABLED — not eligible for live copy"
    if mode == EXEC_MODE_EXIT_ONLY:
        return "OFF — no new entries; existing positions still managed"
    # LAB_SHADOW
    if block == "LANE_RETIRED":
        return "RETIRED — research data only"
    if block == "SHADOW_ONLY_LANE":
        return "LAB SHADOW — no new orders (shadow-collecting lane)"
    return "LAB SHADOW — no new orders"


def _shared_lane_gate_runtime_summary(lane: str) -> str:
    """Compact live acceptance funnel for the tile transparency block."""
    with state_lock:
        bucket = copy.deepcopy(
            (state.get("shared_ai_lane_counters") or {}).get(lane) or {}
        )
    evaluated = int(bucket.get("evaluated") or 0)
    accepted = int(bucket.get("accepted") or 0)
    rejected = int(bucket.get("rejected") or 0)
    reasons = bucket.get("reasons") if isinstance(bucket.get("reasons"), dict) else {}
    top_reason = "none yet"
    if reasons:
        reason, count = max(reasons.items(), key=lambda item: int(item[1] or 0))
        top_reason = f"{reason} ({int(count or 0)})"
    return (
        f"Live gate funnel: evaluated {evaluated}; accepted {accepted}; "
        f"rejected {rejected}; top result {top_reason}"
    )


