def global_exception_handler(exc_type, exc_value, exc_traceback):
    from crash_exception_receipt import emit_original_exception_receipt
    emit_original_exception_receipt(exc_type, exc_value, exc_traceback)
    logger.critical("=== GLOBAL CRASH DETECTED ===")
    logger.critical("Type: %s", exc_type)
    logger.critical("Value: %s", exc_value)
    logger.critical("Traceback:\n%s", "".join(traceback.format_tb(exc_traceback)))
    dump_system_state()

sys.excepthook = global_exception_handler

def safe_thread(fn):
    name = getattr(fn, "__name__", "thread")

    def wrapper(*args, **kwargs):
        _THREAD_HEALTH.bind(name)
        while not shutdown_event.is_set():
            try:
                fn(*args, **kwargs)
            except Exception as e:
                logger.exception(f"[THREAD CRASH] {fn.__name__}: {e}")
                _THREAD_HEALTH.restart(name, e)
                dump_system_state()
                set_execution_paused("THREAD_CRASH")
                time.sleep(2)
            else:
                if not shutdown_event.is_set():
                    _THREAD_HEALTH.restart(name, "RETURNED")
    return wrapper


# (interval_sec, min_stale_sec): stale when last progress is older than
# max(3 x interval, min_stale_sec); the floor covers legitimately slow passes.
THREAD_HEALTH_MONITORED = {
    "tick_execution_engine": (FAST_MONITOR_INTERVAL_SEC, 30.0),
    "position_manager": (POSITION_MONITOR_INTERVAL_SEC, 60.0),
    "ws_tick_lifecycle_worker": (0.5, 30.0),
    "analytics_loop": (float(ANALYTICS_INTERVAL_SEC), 0.0),
    "main_supervisor_loop": (60.0, 0.0),
    "api_state_cache_refresher": (_API_STATE_REFRESH_INTERVAL_SEC, 300.0),
    "dashboard_http_watchdog_loop": (DASHBOARD_HTTP_WATCHDOG_INTERVAL_SEC, 120.0),
    "bitfinex_live_reconcile_loop": (30.0, 300.0),
}
for _thread_name, (_interval, _min_stale) in THREAD_HEALTH_MONITORED.items():
    _THREAD_HEALTH.register(_thread_name, _interval, min_stale_sec=_min_stale)


def _bounded_process_pressure_snapshot() -> dict:
    """Return numeric-only process/host pressure evidence using the stdlib."""
    def finite_round(value, digits=3):
        try:
            number = float(value)
        except (TypeError, ValueError, OverflowError):
            return None
        return round(number, digits) if math.isfinite(number) else None

    cpu_count = max(1, int(os.cpu_count() or 1))
    times = os.times()
    process_cpu_sec = finite_round(times.user + times.system)
    load_1m = load_5m = load_15m = None
    try:
        load_1m, load_5m, load_15m = (
            finite_round(item) for item in os.getloadavg()
        )
    except (AttributeError, OSError):
        pass

    rss_bytes = None
    try:
        statm = Path("/proc/self/statm").read_text(encoding="ascii").split()
        if len(statm) >= 2:
            rss_bytes = int(statm[1]) * int(os.sysconf("SC_PAGE_SIZE"))
    except (OSError, ValueError, IndexError, AttributeError):
        try:
            import resource
            peak_rss = int(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)
            rss_bytes = peak_rss if sys.platform == "darwin" else peak_rss * 1024
        except (ImportError, OSError, ValueError, AttributeError):
            pass

    disk_total = disk_used = disk_free = None
    disk_used_pct = None
    try:
        # Fly persists evidence under BOT_DATA_DIR; measuring only the image
        # filesystem can hide the exact volume pressure involved in a crash.
        # The path itself is never emitted in the secret-free receipt.
        disk_probe = Path((os.getenv("BOT_DATA_DIR") or "").strip() or Path.cwd())
        usage = shutil.disk_usage(disk_probe)
        disk_total = int(usage.total)
        disk_used = int(usage.used)
        disk_free = int(usage.free)
        disk_used_pct = finite_round(
            (100.0 * disk_used / disk_total) if disk_total > 0 else None
        )
    except OSError:
        pass

    return {
        "schema": "process_pressure_v1",
        "cpu_count": cpu_count,
        "process_cpu_sec": process_cpu_sec,
        "load_1m": load_1m,
        "load_5m": load_5m,
        "load_15m": load_15m,
        "load_1m_per_cpu": finite_round(
            load_1m / cpu_count if load_1m is not None else None
        ),
        "rss_bytes": int(rss_bytes) if rss_bytes is not None else None,
        "disk_total_bytes": disk_total,
        "disk_used_bytes": disk_used,
        "disk_free_bytes": disk_free,
        "disk_used_pct": disk_used_pct,
    }


def _watchdog_crash_context(progress=None, incident=None, *, trigger="UNSPECIFIED", restart_allowed=False):
    """Return a bounded, secret-free watchdog receipt from existing snapshots."""
    def bounded_stack(value):
        frames = []
        for raw in list(value or [])[-12:]:
            parts = str(raw).rsplit(":", 2)
            if len(parts) != 3:
                continue
            filename, line, function = parts
            frames.append(f"{Path(filename).name}:{line}:{function}")
        return frames

    def bounded_reasons(value):
        return [str(item)[:96] for item in list(value or [])[:16]]

    progress = progress if isinstance(progress, dict) else {}
    incident = incident if isinstance(incident, dict) else {}
    cycle = progress.get("scheduled_ai_cycle")
    cycle = cycle if isinstance(cycle, dict) else {}
    lock = progress.get("trade_lock_diagnostics")
    lock = lock if isinstance(lock, dict) else {}
    state_lock_detail = getattr(
        state_lock, "diagnostics", lambda _now=None: {}
    )(time.time())
    state_lock_detail = (
        state_lock_detail if isinstance(state_lock_detail, dict) else {}
    )
    context = {
        "schema": "watchdog_crash_context_v1",
        "trigger": str(trigger)[:64],
        "restart_allowed": bool(restart_allowed),
        "exit_code": 75 if restart_allowed else None,
        "source_revision": _runtime_git_rev_exact(),
        "bot_instance_id": str(BOT_INSTANCE_ID or ""),
        "incident": {
            "active": bool(incident.get("active")),
            "age_sec": incident.get("age_sec"),
            "reasons": bounded_reasons(incident.get("reasons")),
            "consecutive_failures": incident.get("consecutive_failures"),
            "consecutive_successes": incident.get("consecutive_successes"),
        },
        "progress": {
            "ok": progress.get("ok"),
            "reasons": bounded_reasons(progress.get("reasons")),
            "recovery_probe_ok": progress.get("recovery_probe_ok"),
            "force_paper_mode": _force_paper_mode_active(),
            "live_armed": progress.get("live_armed"),
            "open_positions": progress.get("open_positions"),
            "pending_orders": progress.get("pending_orders"),
            "ai_expected": progress.get("ai_expected"),
            "ai_age_sec": progress.get("ai_age_sec"),
            "ai_stale_after_sec": progress.get("ai_stale_after_sec"),
            "evaluation_age_sec": progress.get("evaluation_age_sec"),
            "evaluation_progressing": progress.get("evaluation_progressing"),
            "ai_stall_latched": progress.get("ai_stall_latched"),
            "ws_age_sec": progress.get("ws_age_sec"),
            "ws_heartbeat_age_sec": progress.get("ws_heartbeat_age_sec"),
            "ws_progressing": progress.get("ws_progressing"),
            "trade_lock_available": progress.get("trade_lock_available"),
            "trade_lock_busy_transient": progress.get("trade_lock_busy_transient"),
            "trade_lock_progressing": progress.get("trade_lock_progressing"),
        },
        "scheduled_ai_cycle": {
            key: cycle.get(key)
            for key in (
                "stage", "stage_age_sec", "cycle_age_sec", "watchdog_bound_sec",
                "within_watchdog_bound", "owner", "owner_active",
            )
            if key in cycle
        },
        "trade_lock": {
            key: lock.get(key)
            for key in (
                "owner_thread", "owner_active", "held_seconds", "depth",
                "acquire_sequence", "timeout_count", "owner_transition_age_sec",
            )
            if key in lock
        },
        "state_lock": {
            key: state_lock_detail.get(key)
            for key in (
                "owner_thread", "owner_active", "held_seconds", "depth",
                "acquire_sequence", "timeout_count", "owner_transition_age_sec",
            )
            if key in state_lock_detail
        },
        "pressure": _bounded_process_pressure_snapshot(),
        "http_handlers": _dashboard_handler_snapshot(),
    }
    context["scheduled_ai_cycle"]["stack_tail"] = bounded_stack(cycle.get("stack_tail"))
    context["trade_lock"]["stack_tail"] = bounded_stack(lock.get("stack_tail"))
    context["state_lock"]["stack_tail"] = bounded_stack(
        state_lock_detail.get("stack_tail")
    )
    return context


def dump_system_state(*, trigger="UNSPECIFIED", progress=None, incident=None, restart_allowed=False):
    try:
        price_ts = state.get("price_ts")
        snapshot = {
            "time": utc_iso(),
            "edge_score": state.get("last_edge", 0.0),
            "edge_threshold": state.get("edge_threshold"),
            "last_pipeline_stage": state.get("last_pipeline_stage"),
            # Crash collection must not reconcile ledgers or acquire business
            # locks. These unlocked observations are advisory, not exposure proof.
            "active_signals": None,
            "active_signals_status": "UNAVAILABLE_NONMUTATING_CRASH_SNAPSHOT",
            "snapshot_consistency": "ADVISORY_UNLOCKED",
            "open_positions": len(open_positions),
            "pending_orders": len(pending_orders),
            "last_ai_call_ts": state.get("last_ai_call_ts", 0),
            "data_quality": state.get("data_quality", 0.0),
            "ws_last_tick": state.get("ws_last_tick", 0),
            "price": state.get("price"),
            "execution_paused": state.get("execution_paused", False),
            "execution_reason": state.get("execution_reason", ""),
            "last_event_ts": state.get("last_event_ts", 0),
            "ws_age": (time.time() - price_ts) if price_ts else None,
            "candles": len(latest_candles)
        }
        if progress is not None or incident is not None or trigger != "UNSPECIFIED":
            snapshot["watchdog"] = _watchdog_crash_context(
                progress,
                incident,
                trigger=trigger,
                restart_allowed=restart_allowed,
            )
        from crash_journal_writer import append_crash_snapshot
        append_crash_snapshot("crash_dump.json", snapshot)
        logger.critical("[CRASH DUMP] Written to crash_dump.json")
    except Exception as e:
        logger.error(f"[CRASH DUMP FAILED] {e}")

def _trade_lock_probe_status(
    lock_available: bool,
    lock_diagnostics: dict,
    trade_lock_timeout_sec: float | None,
    busy_grace_sec: float | None = None,
) -> tuple[bool, bool]:
    """Classify zero-wait contention without hiding a genuinely stuck lock."""
    busy_bound = (
        WATCHDOG_TRADE_LOCK_TIMEOUT_SEC
        if busy_grace_sec is None
        else max(float(WATCHDOG_TRADE_LOCK_TIMEOUT_SEC), float(busy_grace_sec))
    )
    held_seconds = lock_diagnostics.get("held_seconds")
    valid_held_seconds = bool(
        isinstance(held_seconds, (int, float))
        and math.isfinite(float(held_seconds))
        and float(held_seconds) >= 0.0
    )
    busy_transient = bool(
        not lock_available
        and trade_lock_timeout_sec is not None
        and float(trade_lock_timeout_sec) <= 0.0
        and lock_diagnostics.get("owner_ident") is not None
        and lock_diagnostics.get("owner_active") is True
        and valid_held_seconds
        and float(held_seconds) <= busy_bound
    )
    # ``RLock.acquire()`` succeeds before Python can publish the new owner
    # metadata.  A zero-wait readiness probe can lose in that tiny handoff and
    # truthfully observe depth=0/owner=None even though the new owner already
    # holds the underlying lock.  Grant only a watchdog-bounded grace using a
    # monotonic transition receipt recorded by _TrackedRLock; if publication
    # never completes, the unchanged receipt ages out and readiness fails
    # closed instead of hiding a stuck acquisition.
    transition_age = lock_diagnostics.get("owner_transition_age_sec")
    valid_transition_age = bool(
        isinstance(transition_age, (int, float))
        and math.isfinite(float(transition_age))
        and float(transition_age) >= 0.0
    )
    owner_transition_transient = bool(
        not lock_available
        and trade_lock_timeout_sec is not None
        and float(trade_lock_timeout_sec) <= 0.0
        and lock_diagnostics.get("owner_ident") is None
        and int(lock_diagnostics.get("depth") or 0) == 0
        and lock_diagnostics.get("owner_at_last_timeout")
        == "OWNER_TRANSITION_PENDING"
        and valid_transition_age
        and float(transition_age) <= WATCHDOG_TRADE_LOCK_TIMEOUT_SEC
    )
    busy_transient = bool(busy_transient or owner_transition_transient)
    return busy_transient, bool(lock_available or busy_transient)


def _strategy_progress_health_snapshot(
    now: float = None,
    *,
    trade_lock_timeout_sec: float | None = None,
) -> dict:
    """Prove the strategy loop can progress; a heartbeat thread is insufficient."""
    now = float(now or time.time())
    with state_lock:
        ws_ts = float(state.get("ws_last_tick") or 0)
        ws_hb_ts = float(state.get("ws_last_hb_ts") or 0)
        ws_connected = bool(state.get("ws_transport_connected", False))
        ai_ts = float(state.get("last_ai_call_ts") or 0)
        paused = bool(state.get("execution_paused", False))
        manual = bool(state.get("manual_admin_pause", False))
        live_armed = bool(state.get("live_armed", False))
    ws_age = max(0.0, now - ws_ts) if ws_ts else None
    ws_hb_age = max(0.0, now - ws_hb_ts) if ws_hb_ts else None
    ai_age = max(0.0, now - ai_ts) if ai_ts else None
    startup_age = max(0.0, now - float(process_boot_time or now))
    ai_stale_sec = max(300.0, float(get_effective_ai_cooldown_sec()) + 120.0)
    # A completed market-assessment cycle may truthfully stop before provider
    # egress (for example CTX_FAIL / invalid support-resistance input).  That
    # is healthy decision progress, not a missing-AI stall.  The coordinator
    # records ``last_pipeline_run`` when it begins each bounded assessment;
    # treat a recent assessment as cadence evidence while retaining the same
    # hard stale bound if the coordinator actually wedges.
    evaluation_ts = float(globals().get("last_pipeline_run") or 0)
    evaluation_age = max(0.0, now - evaluation_ts) if evaluation_ts else None
    evaluation_progressing = bool(
        evaluation_ts and evaluation_age <= ai_stale_sec
    )
    scheduled_snapshot = copy.deepcopy(scheduled_ai_cycle_state)
    scheduled_poll_ts = float(scheduled_snapshot.get("last_poll_ts") or 0)
    scheduled_poll_age = (
        max(0.0, now - scheduled_poll_ts) if scheduled_poll_ts else None
    )
    scheduler_proves_entry_blocked = bool(
        scheduled_poll_ts
        # The scheduler poll interval is clamped to at most 30 seconds. Three
        # missed polls is a bounded fence and cannot mask a wedged owner.
        and scheduled_poll_age <= 90.0
        and scheduled_snapshot.get("last_poll_entry_eligible") is False
    )
    scheduled_completed_ts = float(scheduled_snapshot.get("completed_ts") or 0)
    scheduled_completed_age = (
        max(0.0, now - scheduled_completed_ts) if scheduled_completed_ts else None
    )
    evaluation_progressing = bool(
        evaluation_progressing
        or (
            scheduled_completed_ts
            and scheduled_completed_age <= ai_stale_sec
        )
    )
    scheduled_started = float(scheduled_snapshot.get("started_ts") or 0)
    scheduled_owner_ident = scheduled_snapshot.get("owner_ident")
    scheduled_owner_frame = (
        sys._current_frames().get(scheduled_owner_ident)
        if scheduled_owner_ident else None
    )
    scheduled_cycle_age = (
        max(0.0, now - scheduled_started) if scheduled_started else 0.0
    )
    scheduled_owner_active = bool(
        scheduled_snapshot.get("owner")
        and scheduled_owner_ident
        and scheduled_owner_frame is not None
        and scheduled_started
    )
    scheduled_cycle_within_bound = bool(
        scheduled_owner_active
        and scheduled_cycle_age <= WATCHDOG_SCHEDULED_AI_CYCLE_MAX_SEC
    )
    ai_expected = bool(
        not paused
        and not manual
        and (os.getenv("DEEPSEEK_API_KEY") or "").strip()
        and startup_age >= ai_stale_sec
        and not evaluation_progressing
        and not scheduler_proves_entry_blocked
        and not scheduled_cycle_within_bound
    )

    lock_probe_timeout = (
        WATCHDOG_TRADE_LOCK_TIMEOUT_SEC
        if trade_lock_timeout_sec is None
        else max(0.0, float(trade_lock_timeout_sec))
    )
    lock_available = trade_lock.acquire(timeout=lock_probe_timeout)
    if lock_available:
        trade_lock.release()
    lock_diagnostics = (
        {}
        if lock_available
        else getattr(trade_lock, "diagnostics", lambda _now=None: {})(now)
    )
    # A zero-wait HTTP probe can legitimately race the active strategy owner.
    # Treat a known, recently-acquired owner as progressing, while preserving
    # the strict bounded acquire used by the watchdog and failing closed once
    # the same ownership exceeds its watchdog allowance.  Without this grace,
    # ordinary cancel/reprice work produced intermittent /ready 503 responses.
    # Readiness probes (zero-wait) tolerate a live, identified owner for the
    # longer READY grace; the watchdog's strict bounded acquire is unchanged.
    lock_busy_grace_sec = (
        READY_TRADE_LOCK_BUSY_GRACE_SEC
        if trade_lock_timeout_sec is not None and float(trade_lock_timeout_sec) <= 0.0
        else WATCHDOG_TRADE_LOCK_TIMEOUT_SEC
    )
    lock_busy_transient, lock_progressing = _trade_lock_probe_status(
        lock_available,
        lock_diagnostics,
        trade_lock_timeout_sec,
        busy_grace_sec=lock_busy_grace_sec,
    )

    transport_progressing = bool(
        ws_connected
        and (
            (ws_ts and ws_age <= WATCHDOG_WS_STALE_SEC)
            or (ws_hb_ts and ws_hb_age <= WATCHDOG_WS_STALE_SEC)
        )
    )
    trade_stream_progressing = bool(
        ws_ts and ws_age <= WATCHDOG_WS_TRADE_STALE_SEC
    )
    ws_progressing = bool(transport_progressing and trade_stream_progressing)
    # Keep the raw observation separate from the entry-suppression latch.  The
    # watchdog needs this independent signal to prove that a recovery AI call
    # really completed; otherwise the latch forces ``ai_progressing`` false and
    # can never accumulate the successful probes required to clear itself.
    # Attempts keep the scheduler cadence honest; only successful provider
    # responses prove AI progress.  The failure stays under AI_CADENCE_STALLED
    # so the AI-only recovery observation path can still clear the latch.
    ai_provider = ai_provider_health_snapshot(now)
    ai_provider_failing = ai_provider["alert"] is not None
    ai_observed_progressing = bool(
        (not ai_expected or (ai_ts and ai_age <= ai_stale_sec))
        and not ai_provider_failing
    )
    ai_progressing = ai_observed_progressing
    with _strategy_progress_incident_lock:
        ai_stall_latched = bool(
            _strategy_progress_incident.get("active")
            and "AI_CADENCE_STALLED" in _strategy_progress_incident.get("reasons", [])
        )
    # Pausing after a detected stall must not turn a half-alive process green.
    # The incident clears only after real successful cycles following recovery.
    if ai_stall_latched:
        ai_progressing = False
    reasons = []
    if not lock_progressing:
        reasons.append("TRADE_LOCK_UNAVAILABLE")
    if not transport_progressing:
        reasons.append("WS_TRANSPORT_STALLED")
    elif not trade_stream_progressing:
        reasons.append("WS_TRADE_STREAM_STALLED")
    if not ai_progressing:
        reasons.append("AI_CADENCE_STALLED")
    owner_frame = scheduled_owner_frame
    scheduled_snapshot["stack_tail"] = (
        [
            f"{Path(item.filename).name}:{item.lineno}:{item.name}"
            for item in traceback.extract_stack(owner_frame)[-12:]
        ]
        if owner_frame is not None else []
    )
    stage_started = float(scheduled_snapshot.get("stage_started_ts") or 0)
    scheduled_snapshot["stage_age_sec"] = (
        max(0.0, now - stage_started) if stage_started else 0.0
    )
    scheduled_snapshot["cycle_age_sec"] = scheduled_cycle_age
    scheduled_snapshot["within_watchdog_bound"] = scheduled_cycle_within_bound
    scheduled_snapshot["watchdog_bound_sec"] = WATCHDOG_SCHEDULED_AI_CYCLE_MAX_SEC
    replay_available = replay_lock.acquire(timeout=0.05)
    if replay_available:
        replay_lock.release()
    replay_diagnostics = (
        {"name": "replay_lock", "available": True}
        if replay_available
        else {**replay_lock.diagnostics(now), "available": False}
    )
    combo_health_builder = globals().get("combo_lane_execution_health_snapshot")
    combo_lane_health = (
        combo_health_builder()
        if callable(combo_health_builder)
        else {
            "ok": True,
            "available": False,
            "reason": "COMBO_LANE_EXECUTION_HEALTH_NOT_LOADED",
        }
    )
    return {
        "ok": bool(lock_progressing and ws_progressing and ai_progressing),
        "reasons": reasons,
        "trade_lock_available": bool(lock_available),
        "trade_lock_busy_transient": lock_busy_transient,
        "trade_lock_progressing": lock_progressing,
        "trade_lock_diagnostics": lock_diagnostics,
        "trade_lock_busy_grace_sec": lock_busy_grace_sec,
        "trade_lock_hold_stats": getattr(trade_lock, "hold_stats", lambda top=5: {})(top=5),
        "ws_progressing": ws_progressing,
        "ws_age_sec": ws_age,
        "ws_heartbeat_age_sec": ws_hb_age,
        "ai_expected": ai_expected,
        "ai_progressing": ai_progressing,
        "recovery_probe_ok": bool(
            lock_progressing and ws_progressing and ai_observed_progressing
        ),
        "ai_age_sec": ai_provider["ai_success_age_sec"],
        "ai_attempt_age_sec": ai_age,
        "last_ai_success_at": ai_provider["last_ai_success_at"],
        "ai_consecutive_failures": ai_provider["consecutive_failures"],
        "ai_provider": ai_provider,
        "evaluation_age_sec": evaluation_age,
        "evaluation_progressing": evaluation_progressing,
        "ai_stale_after_sec": ai_stale_sec,
        "process_startup_age_sec": startup_age,
        "ai_stall_latched": ai_stall_latched,
        "scheduled_ai_cycle": scheduled_snapshot,
        "replay_lock_diagnostics": replay_diagnostics,
        "post_ai_evidence": post_ai_evidence_health_snapshot(),
        "combo_lane_execution": combo_lane_health,
        "open_positions": len(open_positions),
        "pending_orders": len(pending_orders),
        "live_armed": live_armed,
    }


def _compact_strategy_progress_health_snapshot(progress: dict) -> dict:
    """Bound public liveness payloads without discarding diagnostic evidence."""
    compact = dict(progress or {})
    scheduled = dict(compact.get("scheduled_ai_cycle") or {})
    scheduled.pop("stack_tail", None)
    compact["scheduled_ai_cycle"] = scheduled
    evidence = dict(compact.get("post_ai_evidence") or {})
    workers = {}
    for hook, raw in (evidence.get("workers") or {}).items():
        worker = dict(raw or {})
        dead_letters = list(worker.pop("dead_letters", []) or [])
        bounded = {
            key: worker.get(key)
            for key in (
                "accepting", "active", "completed", "queued", "unfinished",
                "timed_out_handler_alive",
            )
            if key in worker
        }
        bounded["dead_letter_count"] = len(dead_letters)
        if dead_letters:
            latest = dead_letters[-1] if isinstance(dead_letters[-1], dict) else {}
            bounded["latest_dead_letter"] = {
                key: latest.get(key)
                for key in ("hook", "reason", "key", "error_type", "ts")
                if latest.get(key) not in (None, "")
            }
        workers[str(hook)] = bounded
    evidence["workers"] = workers
    last_gap = evidence.get("last_gap")
    if isinstance(last_gap, dict):
        evidence["last_gap"] = {
            key: last_gap.get(key)
            for key in ("schema", "hook", "reason", "key", "ts")
            if last_gap.get(key) not in (None, "")
        }
    compact["post_ai_evidence"] = evidence
    return compact


def _strategy_progress_incident_snapshot(now: float = None) -> dict:
    now = float(now or time.time())
    with _strategy_progress_incident_lock:
        snapshot = dict(_strategy_progress_incident)
        snapshot["reasons"] = list(_strategy_progress_incident["reasons"])
    started = float(snapshot.get("started_ts") or 0)
    snapshot["age_sec"] = max(0.0, now - started) if started else 0.0
    snapshot["new_entries_suppressed"] = bool(snapshot["active"])
    return snapshot


def _update_strategy_progress_incident(progress: dict, now: float = None) -> dict:
    """Latch a stall; clear only after consecutive, independently healthy probes."""
    now = float(now or time.time())
    with _strategy_progress_incident_lock:
        incident = _strategy_progress_incident
        incident_is_ai_only = bool(
            incident["active"]
            and set(incident.get("reasons") or []) == {"AI_CADENCE_STALLED"}
        )
        healthy_probe = bool(
            progress.get("ok")
            or (
                incident_is_ai_only
                and progress.get("recovery_probe_ok")
            )
        )
        if healthy_probe:
            incident["consecutive_failures"] = 0
            incident["consecutive_successes"] += 1
            if (
                incident["active"]
                and incident["consecutive_successes"]
                >= WATCHDOG_PROGRESS_SUCCESSES_BEFORE_CLEAR
            ):
                incident.update({
                    "active": False,
                    "started_ts": 0.0,
                    "last_failure_ts": 0.0,
                    "reasons": [],
                    "consecutive_successes": 0,
                })
        else:
            incident["consecutive_successes"] = 0
            incident["consecutive_failures"] += 1
            incident["last_failure_ts"] = now
            incident["reasons"] = list(progress.get("reasons") or ["STRATEGY_PROGRESS_STALLED"])
            if (
                not incident["active"]
                and incident["consecutive_failures"]
                >= WATCHDOG_PROGRESS_FAILURES_BEFORE_RECOVERY
            ):
                incident["active"] = True
                incident["started_ts"] = now
        snapshot = dict(incident)
        snapshot["reasons"] = list(incident["reasons"])
    started = float(snapshot.get("started_ts") or 0)
    snapshot["age_sec"] = max(0.0, now - started) if started else 0.0
    snapshot["new_entries_suppressed"] = bool(snapshot["active"])
    return snapshot


def _strategy_progress_hard_restart(progress: dict, incident: dict) -> bool:
    """Lock and websocket stalls may exit 75.

    Paper-flat, support-resistance skip, and AI-age stalls stay latched.
    Restarting those forever is a crash loop, not recovery.
    """
    hard_exit_reasons = {
        "TRADE_LOCK_UNAVAILABLE",
        "WS_TRANSPORT_STALLED",
        "WS_TRADE_STREAM_STALLED",
    }
    reasons = set((incident or {}).get("reasons") or [])
    reasons.update((progress or {}).get("reasons") or [])
    return bool(reasons.intersection(hard_exit_reasons))


def watchdog_loop():
    last_progress_dump_ts = 0.0
    pending_restart_block_alerted = False
    while not shutdown_event.is_set():
        with state_lock:
            hb_ts = state.get("last_heartbeat") or last_heartbeat
            ws_ts = state.get("ws_last_tick") or 0
        hb_age = time.time() - hb_ts
        ws_age = time.time() - ws_ts
        if hb_age > WATCHDOG_HEARTBEAT_STALE_SEC and ws_age > WATCHDOG_WS_STALE_SEC:
            logger.critical(
                f"[WATCHDOG] Pipeline stale {hb_age:.0f}s (WS {ws_age:.0f}s) - dumping state [PIPELINE ENFORCEMENT]"
            )
            dump_system_state()
            dump_threads()
        progress = _strategy_progress_health_snapshot()
        incident = _update_strategy_progress_incident(progress)
        if not progress["ok"]:
            logger.error(
                "[WATCHDOG] strategy progress failed %s/%s lock=%s ws_age=%s "
                "ai_age=%s ai_expected=%s positions=%s pending=%s",
                incident["consecutive_failures"],
                WATCHDOG_PROGRESS_FAILURES_BEFORE_RECOVERY,
                progress["trade_lock_available"],
                progress["ws_age_sec"],
                progress["ai_age_sec"],
                progress["ai_expected"],
                progress["open_positions"],
                progress["pending_orders"],
            )
            if incident["active"]:
                # Keep the incident latched without producing a multi-GB dump
                # storm while a position-bearing paper process awaits repair.
                now = time.time()
                if now - last_progress_dump_ts >= 300.0:
                    dump_system_state(
                        trigger="STRATEGY_PROGRESS_INCIDENT",
                        progress=progress,
                        incident=incident,
                    )
                    dump_threads()
                    last_progress_dump_ts = now
                # A paper-only, disarmed, position-flat process may be restarted
                # by Fly to clear a wedged lock. Never self-restart a live or
                # position-bearing risk manager.
                flat_paper = bool(
                    _force_paper_mode_active()
                    and not progress["live_armed"]
                    and progress["open_positions"] == 0
                    and progress["pending_orders"] == 0
                )
                if flat_paper and _strategy_progress_hard_restart(progress, incident):
                    dump_system_state(
                        trigger="STRATEGY_PROGRESS_EXIT_75",
                        progress=progress,
                        incident=incident,
                        restart_allowed=True,
                    )
                    logger.critical(
                        "[WATCHDOG] paper strategy stalled while flat; exiting 75 "
                        "for supervisor recovery"
                    )
                    os._exit(75)
                pending_blocks_restart = bool(
                    _force_paper_mode_active()
                    and not progress["live_armed"]
                    and progress["open_positions"] == 0
                    and progress["pending_orders"] != 0
                    and _strategy_progress_hard_restart(progress, incident)
                )
                if pending_blocks_restart and not pending_restart_block_alerted:
                    # Receipt only. Pending orders stay in place and the process
                    # does not exit, wipe state, or clear them.
                    dump_system_state(
                        trigger="PENDING_ORDERS_BLOCK_RESTART",
                        progress=progress,
                        incident=incident,
                        restart_allowed=False,
                    )
                    logger.critical(
                        "[WATCHDOG] pending orders block restart pending=%s; "
                        "alert only, orders kept",
                        progress["pending_orders"],
                    )
                    pending_restart_block_alerted = True
                elif not pending_blocks_restart:
                    pending_restart_block_alerted = False
                if flat_paper:
                    logger.error(
                        "[WATCHDOG] paper flat stall fail-soft reasons=%s; "
                        "not exiting 75",
                        list(incident.get("reasons") or progress.get("reasons") or []),
                    )
        time.sleep(5)


def _probe_local_dashboard_control(timeout_sec: float = None) -> tuple[bool, str]:
    """Probe the dashboard without sharing its HTTP client or worker pools."""
    timeout = max(
        0.05,
        float(timeout_sec or DASHBOARD_HTTP_WATCHDOG_TIMEOUT_SEC),
    )
    try:
        with socket.create_connection(("127.0.0.1", DASHBOARD_PORT), timeout) as sock:
            sock.settimeout(timeout)
            sock.sendall(
                b"GET /api/ping HTTP/1.1\r\n"
                b"Host: 127.0.0.1\r\n"
                b"Connection: close\r\n\r\n"
            )
            first_line = b""
            while b"\r\n" not in first_line and len(first_line) < 128:
                chunk = sock.recv(128 - len(first_line))
                if not chunk:
                    break
                first_line += chunk
        status_line = first_line.split(b"\r\n", 1)[0]
        fields = status_line.split(b" ")
        if len(fields) >= 2 and fields[1] == b"200":
            return True, "HTTP_200"
        return False, status_line.decode("ascii", errors="replace") or "EMPTY_RESPONSE"
    except (OSError, TimeoutError) as exc:
        return False, f"{type(exc).__name__}:{exc}"


def _dashboard_http_restart_allowed(lock_timeout_sec: float = 0.25) -> bool:
    """Fail-safe recovery gate: paper-forced, disarmed, and exposure-free only."""
    if not _force_paper_mode_active():
        return False
    acquired = trade_lock.acquire(timeout=max(0.0, float(lock_timeout_sec)))
    if not acquired:
        return False
    try:
        return bool(
            not state.get("live_armed", False)
            and len(open_positions) == 0
            and len(pending_orders) == 0
        )
    finally:
        trade_lock.release()


def dashboard_http_watchdog_loop():
    """Let Fly recover a wedged dashboard only when no execution risk exists."""
    consecutive_failures = 0
    while not shutdown_event.is_set():
        startup_age = max(0.0, time.time() - float(process_boot_time or time.time()))
        if (
            not _DASHBOARD_BOOTSTRAP_COMPLETE
            or startup_age < DASHBOARD_HTTP_WATCHDOG_STARTUP_GRACE_SEC
        ):
            consecutive_failures = 0
        else:
            healthy, detail = _probe_local_dashboard_control()
            if healthy:
                consecutive_failures = 0
            else:
                consecutive_failures += 1
                _THREAD_HEALTH.error(
                    "dashboard_http_watchdog_loop", f"probe failed {consecutive_failures}: {detail}"
                )
                logger.error(
                    "[HTTP WATCHDOG] localhost control probe failed %s/%s: %s",
                    consecutive_failures,
                    DASHBOARD_HTTP_WATCHDOG_FAILURES_BEFORE_EXIT,
                    detail,
                )
                if (
                    consecutive_failures
                    >= DASHBOARD_HTTP_WATCHDOG_FAILURES_BEFORE_EXIT
                ):
                    if _dashboard_http_restart_allowed():
                        logger.critical(
                            "[HTTP WATCHDOG] dashboard control plane remained wedged "
                            "while force-paper, disarmed, and flat; exiting 75 for "
                            "supervisor recovery"
                        )
                        dump_system_state()
                        dump_threads()
                        os._exit(75)
                    logger.critical(
                        "[HTTP WATCHDOG] restart refused: live arm, exposure, "
                        "non-force-paper mode, or unprovable trade-lock state"
                    )
        _THREAD_HEALTH.beat("dashboard_http_watchdog_loop")
        shutdown_event.wait(DASHBOARD_HTTP_WATCHDOG_INTERVAL_SEC)

def dump_threads():
    for thread in threading.enumerate():
        logger.debug(f"[THREAD] {thread.name} alive={thread.is_alive()}")

def pipeline_heartbeat():
    global last_pipeline_run, last_heartbeat
    now = time.time()
    with state_lock:
        state["last_heartbeat"] = now
    last_heartbeat = now
    logger.debug("[HEARTBEAT] Pipeline alive")

def log_event_rejection(event):
    logger.info(f"[PIPELINE BLOCKED] edge={event.get('edge',0)} < threshold={event.get('threshold',2.9)} [PIPELINE ENFORCEMENT]")
    try:
        row = {"ts": utc_iso(), "type": "REJECTED_SIGNAL", "edge": event.get("edge",0), "threshold": event.get("threshold",2.9), "reason": "EDGE_BELOW_THRESHOLD"}
        dynamic_csv_writer(CSV_BLOCKS, row)
        persist_rejected_opportunity(
            {
                "trade_id": event.get("trade_id") or f"edge-{int(time.time())}",
                "price": event.get("price") or state.get("price"),
                "signal_price": event.get("price") or state.get("price"),
                "final_direction": event.get("direction") or event.get("dir"),
                "edge_score_at_entry": event.get("edge"),
                "created_ts_ts": time.time(),
            },
            {"decision": "REJECT"},
            "EDGE_BELOW_THRESHOLD",
        )
    except:
        pass

