_RUNTIME_UPTIME = {"tracker": None}
_RUNTIME_UPTIME_INTERVAL_SEC = 15.0


def _runtime_uptime_problem(now: float) -> dict | None:
    with state_lock:
        paused = bool(state.get("execution_paused") or state.get("manual_admin_pause"))
        owner = _pause_owner_locked()
        reason = str(state.get("execution_reason") or "")
        enabled = dict(state.get("research_lane_enabled") or {})
    lanes = [str(lane) for lane in ACTIVE_TILE_ORDER]
    last_ok = float(_ai_provider_health.get("last_success_ts") or 0.0)
    return runtime_uptime.problem_from(
        paused=paused, pause_owner=owner, pause_reason=reason,
        tiles_on=sum(1 for lane in lanes if enabled.get(lane) is True), tiles_total=len(lanes),
        ai_success_age_sec=max(0.0, now - last_ok) if last_ok > 0 else None,
        ai_consecutive_failures=int(_ai_provider_health.get("consecutive_failures") or 0),
        process_age_sec=max(0.0, now - float(process_boot_time or now)),
    )


def runtime_uptime_loop():
    """Observe interruptions for the uptime strip; started once boot has restored state."""
    tracker = runtime_uptime.UptimeTracker(_data_sync_volume_root() / runtime_uptime.STATE_FILE)
    opened = tracker.boot(float(process_boot_time or time.time()), _runtime_git_rev())
    _RUNTIME_UPTIME["tracker"] = tracker
    logger.info("[UPTIME] boot recorded: %s", opened.get("text"))
    while not shutdown_event.is_set():
        now = time.time()
        try:
            tracker.observe(now, _runtime_uptime_problem(now))
        except Exception as exc:
            logger.warning("[UPTIME] observation failed: %s", type(exc).__name__)
        if shutdown_event.wait(_RUNTIME_UPTIME_INTERVAL_SEC):
            break


def _runtime_uptime_summary(now: float | None = None) -> dict:
    tracker = _RUNTIME_UPTIME["tracker"]
    if tracker is None:
        return {"schema": runtime_uptime.SCHEMA, "available": False, "state": "STARTING", "colour": "amber",
                "uninterrupted_label": "Starting: uptime tracking begins once boot completes",
                "definition": runtime_uptime.DEFINITION}
    return tracker.summary(now)


_SYSTEM_HEALTH_REPORT = {"report": None, "received_at": None, "proof": None}
_SYSTEM_HEALTH_LOCK = threading.Lock()
# Bounded (system_health_alerts.RETAIN_DAYS / RETAIN_EVENTS) and persisted on the
# volume (system_health_alerts.STATE_FILE) so a restart or deploy keeps the alert
# history and the last monitor digest; restored lazily on first use. The watcher
# still re-sends its alarm log when it sees the history shrink.
_SYSTEM_HEALTH_ALARMS = {"events": [], "statuses": {}, "statuses_at": None}
_MONITOR_DIGEST = {"digest": None, "received_ts": None}
_SYSTEM_HEALTH_RESTORED = {"done": False}


def _system_health_state_path():
    return _data_sync_volume_root() / system_health_alerts.STATE_FILE


def _restore_system_health_state() -> None:
    """Load the persisted alarm history/digest once (callers hold _SYSTEM_HEALTH_LOCK)."""
    if _SYSTEM_HEALTH_RESTORED["done"]:
        return
    _SYSTEM_HEALTH_RESTORED["done"] = True
    try:
        saved = system_health_alerts.load_state(_system_health_state_path())
    except Exception as exc:  # noqa: BLE001 - restore is best-effort
        logger.warning(f"[SYSTEM HEALTH] alert state not restored: {exc}")
        return
    if saved["events"]:
        _SYSTEM_HEALTH_ALARMS["events"] = system_health_alerts.merge_events(saved["events"], _SYSTEM_HEALTH_ALARMS["events"])
    if saved["statuses"] and not _SYSTEM_HEALTH_ALARMS["statuses"]:
        _SYSTEM_HEALTH_ALARMS["statuses"] = saved["statuses"]
        _SYSTEM_HEALTH_ALARMS["statuses_at"] = saved["statuses_at"]
    digest = monitor_api.sanitize_digest(saved["digest"]) if saved["digest"] is not None else None
    if digest is not None and _MONITOR_DIGEST["digest"] is None:
        _MONITOR_DIGEST.update(digest=digest, received_ts=saved["digest_ts"])


def _persist_system_health_state() -> None:
    with _SYSTEM_HEALTH_LOCK:
        snapshot = {"events": list(_SYSTEM_HEALTH_ALARMS["events"]), "statuses": dict(_SYSTEM_HEALTH_ALARMS["statuses"]),
                    "statuses_at": _SYSTEM_HEALTH_ALARMS["statuses_at"], "digest": _MONITOR_DIGEST["digest"],
                    "digest_ts": _MONITOR_DIGEST["received_ts"]}
    if not system_health_alerts.save_state(_system_health_state_path(), **snapshot):
        logger.warning("[SYSTEM HEALTH] alert state not persisted (next watcher push refills it)")


def _system_health_fly_self_checks(now: float | None = None) -> list:
    """Cheap Fly-side facts that stay truthful even when the laptop report is stale."""
    now = float(now or time.time())
    with state_lock:
        ws_ts = float(state.get("ws_last_tick") or 0)
        paused = bool(state.get("execution_paused", False))
        live_armed = bool(state.get("live_armed", False))
    ws_age = max(0.0, now - ws_ts) if ws_ts else None
    checks = [
        {
            "id": "fly.ws_ticks",
            "status": "GREEN" if ws_age is not None and ws_age <= 120 else "RED",
            "observed": "never" if ws_age is None else f"{int(ws_age)}s",
            "threshold": "<=120s",
        },
        {
            "id": "fly.paused",
            "status": "AMBER" if paused else "GREEN",
            "observed": "paused" if paused else "running",
            "threshold": "running",
        },
        {
            "id": "fly.live_armed",
            "status": "RED" if live_armed else "GREEN",
            "observed": "armed" if live_armed else "disarmed",
            "threshold": "disarmed",
        },
    ]
    provider = globals().get("_ai_provider_health")
    if isinstance(provider, dict):
        last_ok = provider.get("last_success_ts")
        failures = int(provider.get("consecutive_failures") or 0)
        age = max(0.0, now - float(last_ok)) if isinstance(last_ok, (int, float)) and last_ok else None
        checks.append({
            "id": "fly.ai_success",
            "status": "RED" if age is None or age > 720 or failures >= 3
            else ("AMBER" if age > 360 else "GREEN"),
            "observed": ("no success" if age is None else f"last success {int(age // 60)}m ago")
            + f", {failures} consecutive failures",
            "threshold": "<12m, <3 failures",
        })
    return checks


@app.route('/api/system-health/report', methods=['POST'])
def system_health_report():
    if (request.content_length or 0) > system_health_banner.MAX_REPORT_BYTES:
        return jsonify({"ok": False, "error": "report too large"}), 413
    raw = request.get_json(silent=True)
    report = system_health_banner.sanitize_report(raw)
    if report is None:
        return jsonify({"ok": False, "error": "invalid system_health_v1 report"}), 400
    statuses = system_health_alerts.check_statuses(raw)
    digest = monitor_api.sanitize_digest(raw.get("monitor_digest"))
    with _SYSTEM_HEALTH_LOCK:
        _restore_system_health_state()
        if digest is not None:
            _MONITOR_DIGEST.update(digest=digest, received_ts=time.time())
        _SYSTEM_HEALTH_REPORT["report"] = report
        _SYSTEM_HEALTH_REPORT["received_at"] = system_health_banner.utc_now_iso()
        _SYSTEM_HEALTH_REPORT["proof"] = runtime_uptime.sanitize_proof(raw.get("proof"))
        events = system_health_alerts.merge_events(_SYSTEM_HEALTH_ALARMS["events"], raw.get("alarm_events"))
        _SYSTEM_HEALTH_ALARMS["events"] = events
        if statuses:
            _SYSTEM_HEALTH_ALARMS["statuses"] = statuses
            _SYSTEM_HEALTH_ALARMS["statuses_at"] = time.time()
    _persist_system_health_state()
    return jsonify({"ok": True, "verdict": report["verdict"], "alarm_history": {
        "count": len(events), "through": events[-1]["at"] if events else None,
        "through_ts": events[-1]["ts"] if events else None}})


def _system_health_alert_history() -> dict:
    with _SYSTEM_HEALTH_LOCK:
        _restore_system_health_state()
        events = list(_SYSTEM_HEALTH_ALARMS["events"])
        statuses = dict(_SYSTEM_HEALTH_ALARMS["statuses"])
        statuses_at = _SYSTEM_HEALTH_ALARMS["statuses_at"]
    if statuses_at is None or time.time() - statuses_at > system_health_banner.STALE_AFTER_SEC:
        statuses = {}
    history = system_health_alerts.build_history(events, statuses=statuses, statuses_at=statuses_at)
    history["source"] = "laptop watcher push (POST /api/system-health/report)"
    return history if _admin_authed_strict() else system_health_alerts.public_view(history)


@app.route('/api/system-health/alerts')
def system_health_alerts_view():
    response = jsonify(_system_health_alert_history())
    response.headers["Cache-Control"] = "no-store"
    return response


@app.route('/alerts')
def alerts_page():
    page = system_health_alerts.render_alerts_html(
        _system_health_alert_history(), title="Alerts - Fly trading bot",
        nav_links=(("Dashboard", "/"), ("Alerts JSON", "/api/system-health/alerts")),
        source_note="Source: the laptop health watcher pushes its alarm log here; history refills within one "
                    "watcher tick after a Fly restart.")
    response = make_response(page)
    response.headers["Cache-Control"] = "no-store"
    return response


@app.route('/api/system-health')
def system_health_view():
    with _SYSTEM_HEALTH_LOCK:
        report = _SYSTEM_HEALTH_REPORT["report"]
        received_at = _SYSTEM_HEALTH_REPORT["received_at"]
        proof = _SYSTEM_HEALTH_REPORT["proof"]
    out = system_health_banner.with_staleness(report)
    out["received_at"] = received_at
    out["uptime"] = dict(_runtime_uptime_summary(), proof=None if out.get("stale") else proof)
    self_checks = _system_health_fly_self_checks()
    out["fly_self_checks"] = self_checks
    bad = [c for c in self_checks if c["status"] != "GREEN"]
    if bad:
        out["failing"] = list(out.get("failing") or []) + bad
        rank = {"GREEN": 0, "SKIP": 0, "AMBER": 1, "RED": 2}
        worst = max(bad, key=lambda c: rank[c["status"]])["status"]
        if rank[worst] > rank.get(out.get("verdict"), 0):
            out["verdict"] = worst
    if not _admin_authed_strict():
        out["failing"] = [
            {k: c.get(k) for k in ("id", "status", "observed", "threshold")}
            for c in out.get("failing") or []
        ]
    response = jsonify(out)
    response.headers["Cache-Control"] = "no-store"
    return response


_MONITOR_CACHE_SEC = 15.0
_MONITOR_CACHE = {}
_MONITOR_CACHE_LOCK = threading.Lock()


def _monitor_response(payload: dict, max_bytes: int, status: int = 200):
    response = jsonify(monitor_api.fit_to_budget(payload, max_bytes))
    response.status_code = status
    response.headers["Cache-Control"] = "no-store"
    return response


def _monitor_cached(key: str, build) -> dict:
    """Bound load from several pollers: rebuild a monitor payload at most every 15 s."""
    now = time.time()
    with _MONITOR_CACHE_LOCK:
        hit = _MONITOR_CACHE.get(key)
        if hit and 0.0 <= now - hit[0] < _MONITOR_CACHE_SEC:
            return copy.deepcopy(hit[1])
    payload = build(now)
    with _MONITOR_CACHE_LOCK:
        _MONITOR_CACHE[key] = (now, payload)
    return copy.deepcopy(payload)


def _monitor_part(build):
    try:
        return build()
    except Exception as exc:
        return {"error": type(exc).__name__}


def _monitor_lane_rows(lanes) -> tuple[dict, float]:
    """Booked closes of the active lanes in the dashboard's trade session (same rows as lane_pnl_ledger)."""
    session_start = _showcase_trade_session_start()
    rows = {lane: [] for lane in lanes}
    if not trade_lock.acquire(timeout=_RELAY_EXECUTION_LOCK_TIMEOUT_SEC):
        raise TimeoutError("monitor lanes timed out waiting for trade_lock")
    try:
        for row in trades:
            if not isinstance(row, dict):
                continue
            bucket = rows.get(_normalize_lane_key(row.get("research_lane") or ""))
            if bucket is None or (session_start and not _trade_row_in_session(row, session_start)):
                continue
            bucket.append((row.get("ts"), row.get("net_pnl_usd"), row.get("margin_usdt"), row.get("leverage"),
                           row.get("dir") or row.get("final_direction"), row.get("book_slippage_usd_total"),
                           row.get("pnl")))
    finally:
        trade_lock.release()
    shaped = {}
    for lane, raw in rows.items():
        shaped[lane] = []
        for ts, net, margin, leverage, direction, slippage, pnl_margin_pct in raw:
            try:
                notional = float(margin or 0.0) * float(leverage or 0.0)
            except (TypeError, ValueError):
                notional = 0.0
            shaped[lane].append({"close_ts": parse_ts(ts or "") or None, "net_pnl_usd": net,
                                 "notional_usd": notional, "direction": direction,
                                 "book_slippage_usd": slippage,
                                 # Precise per-trade bp source (net_pnl_usd is cent-rounded).
                                 "pnl_margin_pct": pnl_margin_pct, "leverage": leverage})
    return shaped, session_start


def _monitor_lanes_payload(now: float) -> dict:
    manifest = active_tile_lifecycle_manifest()
    lanes = [tile["lane"] for tile in manifest]
    enabled = research_lane_enabled_map()
    rows, session_start = _monitor_lane_rows(lanes)
    xvl_lanes = _monitor_part(lambda: xvl_evaluator_snapshot().get("lanes") or {})
    return {
        "schema": monitor_api.LANES_SCHEMA,
        "boot_id": BOT_INSTANCE_ID,
        "generated_at": monitor_api.utc_iso(now),
        "git_rev": _runtime_git_rev(),
        "tile_registry_signature": active_tile_registry_signature(),
        "scope": {
            "active_lanes_only": True,
            "session_start_at": monitor_api.utc_iso(session_start) if session_start else None,
            "pnl": "booked net_pnl_usd under the bot's conservative fill model; never recomputed",
            "drawdown": "peak-to-trough of cumulative booked net from 0, in close order",
            "mean_bp": "sum(net) / sum(margin x leverage) x 1e4",
        },
        "lanes": [
            {
                "lane": tile["lane"],
                "label": tile["label"],
                "display_order": tile["display_order"],
                "on": enabled.get(tile["lane"]),
                **monitor_api.lane_stats(rows.get(tile["lane"]) or []),
                "latency": monitor_api.latency_brief(
                    ((xvl_lanes.get(tile["lane"]) or {}) if "error" not in xvl_lanes else {}).get("latency")
                ),
            }
            for tile in manifest
        ],
    }


def _monitor_relay_known(now: float, statuses: dict, failing: list) -> dict:
    guard = _relay_delivery_guard.status(now)
    railway = next((c for c in failing if c.get("id") == "railway.relay"), None)
    return {
        "fly_arming_block_reason": guard.get("arming_block_reason"),
        "fly_outbox_pending_total": guard.get("pending_total"),
        "fly_outbox_stale_owner_pending": guard.get("stale_owner_pending"),
        "fly_outbox_retired_pre_epoch_total": guard.get("retired_pre_epoch_total"),
        "laptop_railway_relay_check": statuses.get("railway.relay"),
        "laptop_bitfinex_exposure_check": statuses.get("bitfinex.exposure"),
        "laptop_railway_relay_observed": (railway or {}).get("observed"),
        "source": "Fly relay outbox guard + laptop watcher checks railway.relay / bitfinex.exposure",
    }


def _monitor_summary_payload(now: float) -> dict:
    hb = state.get("last_heartbeat", last_heartbeat)
    progress = _strategy_progress_health_snapshot(now, trade_lock_timeout_sec=0.0)
    provider = progress.get("ai_provider") or {}
    scheduled = progress.get("scheduled_ai_cycle") or {}
    evidence = progress.get("post_ai_evidence") or {}
    armable, arm_block_reason, _ = can_open_live_entry(require_armed=False, now=now)
    relay_gate_block = _relay_delivery_guard.arming_block_reason(now)
    if armable and relay_gate_block:
        armable, arm_block_reason = False, relay_gate_block
    xvl = _monitor_part(xvl_evaluator_snapshot)
    cross_venue = _monitor_part(cross_venue_health_snapshot)
    market_context = _monitor_part(market_context_health_snapshot)
    indicator_engine = _monitor_part(indicator_engine_health_snapshot)
    collection = _monitor_part(lambda: research_collection_health(now))
    transfer = _monitor_part(lambda: _volume_health_snapshot(now).get("transfer") or {})
    epoch = _monitor_part(_data_epoch_public)
    with _SYSTEM_HEALTH_LOCK:
        _restore_system_health_state()
        report = copy.deepcopy(_SYSTEM_HEALTH_REPORT["report"])
        statuses = dict(_SYSTEM_HEALTH_ALARMS["statuses"])
        statuses_at = _SYSTEM_HEALTH_ALARMS["statuses_at"]
    if statuses_at is None or now - statuses_at > system_health_banner.STALE_AFTER_SEC:
        statuses = {}
    watcher = system_health_banner.with_staleness(report, now)
    lanes = _monitor_part(lambda: _monitor_cached("lanes", _monitor_lanes_payload))
    completed_ts = float(scheduled.get("completed_ts") or 0.0)
    return {
        "schema": monitor_api.SUMMARY_SCHEMA,
        "boot_id": BOT_INSTANCE_ID,
        "generated_at": monitor_api.utc_iso(now),
        "git_rev": _runtime_git_rev(),
        "bot_version": EXECUTION_FIX_VERSION,
        "tile_registry_signature": active_tile_registry_signature(),
        "epoch": {
            "data_epoch_id": epoch.get("epoch_id"),
            "data_epoch_declared": epoch.get("declared"),
            "data_epoch_started_at": epoch.get("started_at_utc"),
            "collection_epoch_id": _monitor_part(_bound_collection_epoch_id),
            "canonical_epoch_id": _monitor_part(_canonical_epoch_public).get("canonical_epoch_id"),
        },
        "safety": {
            "force_paper_mode": _force_paper_mode_active(),
            "live_armed": bool(state.get("live_armed", False)),
            "bitfinex_live_enabled": bool(state.get("bitfinex_live_enabled", False)),
            "live_entry_armable": armable,
            "live_entry_arm_block_reason": None if armable else arm_block_reason,
            "relay": _monitor_part(lambda: _monitor_relay_known(now, statuses, watcher.get("failing") or [])),
        },
        "pause": {
            "execution_paused": bool(state.get("execution_paused", False)),
            "pause_owner": _pause_owner_locked(),
            "execution_reason": state.get("execution_reason", ""),
        },
        "ages_sec": {
            "heartbeat": round(max(0.0, now - float(hb or 0)), 1),
            "process_startup": progress.get("process_startup_age_sec"),
            "ws": progress.get("ws_age_sec"),
            "ai_success": progress.get("ai_age_sec"),
            "ai_attempt": progress.get("ai_attempt_age_sec"),
            "evaluation": progress.get("evaluation_age_sec"),
            "cycle_completed": round(now - completed_ts, 1) if completed_ts else None,
            "xvl_tick": xvl.get("tick_age_s"),
            "cross_venue_collector": cross_venue.get("collector_age_s"),
            "indicator_engine_last_bar_close": indicator_engine.get("last_bar_close_age_sec"),
            "tape_latest_bucket": (collection.get("tape_source") or {}).get("latest_bucket_age_sec"),
        },
        "progress": {
            "strategy_ok": progress.get("ok"),
            "reasons": progress.get("reasons"),
            "xvl_status": xvl.get("status"),
            "cross_venue_status": cross_venue.get("status"),
            "market_context_status": market_context.get("status"),
            "market_context_stale_feeds": market_context.get("stale_feeds"),
            "indicator_engine_status": indicator_engine.get("status"),
            "research_collection_status": collection.get("status"),
        },
        "counters_since_boot": {
            "ai_successes": provider.get("successes_since_boot"),
            "ai_failures": provider.get("failures_since_boot"),
            "cycles_completed": scheduled.get("completed_since_boot"),
            "post_ai_evidence_submitted": evidence.get("submitted"),
            "post_ai_evidence_completed": evidence.get("completed"),
            "post_ai_evidence_rejected": evidence.get("rejected"),
            "xvl_ticks": xvl.get("ticks"),
            "xvl_rows_written": xvl.get("rows_written"),
            "cross_venue_rows_written": (cross_venue.get("stats") or {}).get("rows_written"),
            "multiverse_written": (collection.get("multiverse") or {}).get("written_since_boot"),
            "tape_rows_ingested": (collection.get("tape_source") or {}).get("rows_ingested"),
        },
        "custody": {
            key: transfer.get(key)
            for key in ("shipped_seq", "laptop_acked_seq", "custody_through_seq", "pruned_through_seq",
                        "last_segment_at", "last_error")
        },
        "tiles": [
            {
                "lane": row.get("lane"),
                "on": row.get("on"),
                "closes": row.get("closes"),
                "net_usd": row.get("net_usd"),
                "latency_p50_s": (row.get("latency") or {}).get("signal_to_fill_p50_s"),
                "latency_n": (row.get("latency") or {}).get("n"),
            }
            for row in lanes.get("lanes") or []
        ],
        "laptop_watcher": {
            "verdict": watcher.get("verdict"),
            "age_sec": watcher.get("age_sec"),
            "stale": watcher.get("stale"),
            "counts": watcher.get("counts"),
        },
        "open_alarms": [
            {"id": alarm.get("id"), "first_seen": alarm.get("since")}
            for alarm in (watcher.get("open_alarms") or [])
        ],
        "detail": {"lanes": "/api/monitor/lanes", "readiness": "/api/ready", "health": "/health"},
    }


@app.route('/api/monitor/summary')
def monitor_summary():
    return _monitor_response(_monitor_cached("summary", _monitor_summary_payload), monitor_api.MAX_SUMMARY_BYTES)


@app.route('/api/monitor/lanes')
def monitor_lanes():
    try:
        payload = _monitor_cached("lanes", _monitor_lanes_payload)
    except TimeoutError:
        response = _monitor_response({"schema": monitor_api.LANES_SCHEMA, "boot_id": BOT_INSTANCE_ID,
                                      "error": "TRADE_LOCK_BUSY"}, monitor_api.MAX_LANES_BYTES, status=503)
        response.headers["Retry-After"] = "5"
        return response
    return _monitor_response(payload, monitor_api.MAX_LANES_BYTES)


@app.route('/api/monitor/digest')
def monitor_digest():
    if not _MONITOR_READ_TOKEN:
        return _monitor_response({"error": "not found"}, 256, status=404)
    if not monitor_api.bearer_matches(request.headers.get("Authorization"), _MONITOR_READ_TOKEN):
        return _monitor_response({"error": "unauthorized"}, 256, status=401)
    with _SYSTEM_HEALTH_LOCK:
        _restore_system_health_state()
        stored = copy.deepcopy(_MONITOR_DIGEST)
    return _monitor_response(monitor_api.digest_view(stored, time.time(), BOT_INSTANCE_ID),
                             monitor_api.MAX_DIGEST_BYTES + 1024)


@app.route('/api/monitor/integrity')
def monitor_integrity():
    """Read-only: 1 s tape continuity, AI call window, fill markouts, process identity (monitor_integrity.py).

    Auth: X-Bot-Admin-Token (or admin cookie) or ``Authorization: Bearer <MONITOR_READ_TOKEN>``.
    No state lock, no trade lock, no file I/O on the request path.
    """
    if not monitor_integrity_authorized():
        return _monitor_response({"error": "unauthorized"}, 256, status=401)
    if _monitor_integrity is None or _TAPE_CONTINUITY is None or _AI_CALL_WINDOW is None:
        return _monitor_response({"schema": "monitor_integrity_v1", "error": "MODULE_UNAVAILABLE"}, 256, status=503)
    now = time.time()
    extras = {}
    freeze_public = globals().get("_research_freeze_public")
    if callable(freeze_public):
        extras["research_freeze"] = freeze_public
    payload = _monitor_integrity.build_payload(
        now=now, tape=_TAPE_CONTINUITY, ai=_AI_CALL_WINDOW, fills=globals().get("_FILL_MARKOUT_AGG"),
        identity=_monitor_integrity.process_identity(
            pid=os.getpid(), git_rev=_runtime_git_rev(), boot_id=BOT_INSTANCE_ID,
            process_started_ts=globals().get("process_boot_time")),
        extras=extras, fit=monitor_api.fit_to_budget)
    payload["boot_id"] = BOT_INSTANCE_ID
    return _monitor_response(payload, _monitor_integrity.MAX_BYTES + 1024)


def monitor_integrity_authorized() -> bool:
    return _monitor_integrity is not None and _monitor_integrity.is_authorized(
        admin_ok=_admin_authed(), authorization=request.headers.get("Authorization"),
        monitor_token=_MONITOR_READ_TOKEN, bearer_matches=monitor_api.bearer_matches)


