def _data_sync_runtime_root() -> Path:
    volume_raw = (os.getenv("BOT_DATA_DIR") or "").strip()
    if volume_raw:
        return (Path(volume_raw) / "runtime").resolve()
    return Path.cwd().resolve()


def _data_sync_volume_root() -> Path:
    raw = (os.getenv("BOT_DATA_DIR") or "").strip()
    if raw:
        return Path(raw).resolve()
    return _data_sync_runtime_root()


_LIFECYCLE_PIPELINE_RUNTIME = None
_LIFECYCLE_PIPELINE_LAST_STATUS = None


def _lifecycle_pipeline_pressure_probe() -> dict:
    """Project existing collector pressure without inventing a new threshold."""
    try:
        used_fraction = float(
            disk_usage_fraction(str(_data_sync_runtime_root()))
        )
        return {
            "pressure": bool(used_fraction >= STORAGE_PRESSURE_THRESHOLD),
            "emergency": used_fraction >= 0.90,
            "used_fraction": used_fraction,
        }
    except Exception as exc:
        raise RuntimeError(type(exc).__name__) from exc


def _lifecycle_pipeline_overlap_probe():
    """Avoid competing with physical inventory or SQLite snapshot generation."""
    active = []
    with _data_sync_inventory_cache_condition:
        if _data_sync_inventory_cache.get("refreshing"):
            active.append("SYNC_INVENTORY_CACHE_REFRESH")
        if _data_sync_async_inventory.get("worker_active"):
            active.append("SYNC_ASYNC_INVENTORY_REFRESH")
    # Let the optional lifecycle indexer yield while the bounded snapshot
    # worker is BUILDING. SQLite online backup remains valid while the WAL
    # advances, but avoiding another writer reduces one-vCPU and I/O pressure.
    with _data_sync_sqlite_snapshot_condition:
        if any(
            state.get("status") == "BUILDING"
            for state in _data_sync_sqlite_snapshot_states.values()
        ):
            active.append("SQLITE_SNAPSHOT_BUILDING")
    if mirror_generation_lease_held(_data_sync_volume_root()):
        active.append("ANALYZER_GENERATION_LEASE")
    return active


def _start_lifecycle_pipeline_runtime() -> bool:
    """Start optional evidence processing; never alter trading availability."""
    global _LIFECYCLE_PIPELINE_RUNTIME, _LIFECYCLE_PIPELINE_LAST_STATUS
    revision = str(_runtime_git_rev_exact() or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{40}", revision):
        logger.warning(
            "[LIFECYCLE PIPELINE] not started: exact 40-character source revision "
            "is unavailable; trading remains unchanged"
        )
        return False
    try:
        runtime_module = importlib.import_module("lifecycle_pipeline_runtime")
        # Explicit incident recovery only; never infer reset authority from a
        # truncated ledger. Run before the lifecycle owner exists.
        from lifecycle_reset_recovery_startup import initialize_reset_recovery
        initialize_reset_recovery(
            root=_data_sync_runtime_root(),
            operation_path=os.getenv("LIFECYCLE_RESET_OPERATION_PATH") or None,
            operation_sha256=os.getenv("LIFECYCLE_RESET_OPERATION_SHA256") or None,
            trigger=os.getenv("LIFECYCLE_RESET_RECOVERY_TRIGGER") or None,
            epoch_provider=_collector_v22_epoch_id,
            reset_lock=_fresh_collection_lock,
            owner_quiescent=lambda: _LIFECYCLE_PIPELINE_RUNTIME is None,
        )
        os_module = globals().get("os")
        rotation_enabled_raw = (
            os_module.getenv("V3_PRODUCTION_ROTATION_ENABLED", "")
            if os_module is not None else ""
        )
        rotation_target_raw = (
            os_module.getenv(
                "V3_PRODUCTION_ROTATION_TARGET_BYTES", str(64 * 1024 * 1024)
            ) if os_module is not None else str(64 * 1024 * 1024)
        )
        epoch_provider = globals().get("_collector_v22_epoch_id")
        epoch_id = epoch_provider() if callable(epoch_provider) else None
        started = runtime_module.start(
            _data_sync_runtime_root(),
            source_revision=revision,
            epoch_id=epoch_id,
            pressure_probe=_lifecycle_pipeline_pressure_probe,
            overlap_probe=_lifecycle_pipeline_overlap_probe,
            rotation_enabled=str(rotation_enabled_raw).strip().lower()
            in {"1", "true", "yes", "on"},
            rotation_target_bytes=int(rotation_target_raw),
        )
        logger.info(
            "[LIFECYCLE PIPELINE] optional owner started=%s cleanup_authorized=false",
            started,
        )
        if started:
            _LIFECYCLE_PIPELINE_RUNTIME = runtime_module
        _LIFECYCLE_PIPELINE_LAST_STATUS = runtime_module.status()
        return bool(started)
    except BaseException as exc:
        logger.error(
            "[LIFECYCLE PIPELINE] optional owner start failed closed: %s; "
            "trading remains unchanged",
            type(exc).__name__,
        )
        return False


def _stop_lifecycle_pipeline_runtime(timeout: float = 5.0) -> bool:
    global _LIFECYCLE_PIPELINE_RUNTIME, _LIFECYCLE_PIPELINE_LAST_STATUS
    runtime_module = _LIFECYCLE_PIPELINE_RUNTIME
    if runtime_module is None:
        return True
    try:
        stopped = bool(runtime_module.stop(timeout=timeout))
        _LIFECYCLE_PIPELINE_LAST_STATUS = runtime_module.status()
        if stopped:
            _LIFECYCLE_PIPELINE_RUNTIME = None
        return stopped
    except BaseException as exc:
        logger.error(
            "[LIFECYCLE PIPELINE] optional owner stop failed: %s",
            type(exc).__name__,
        )
        return False


def _collection_epoch_parity(lifecycle_public) -> dict:
    """Compare every epoch identity against the single bound session epoch."""
    session_epoch = _bound_collection_epoch_id() or None
    with _data_sync_identity_cache_lock:
        cache_epoch = _data_sync_identity_epoch_cache.get("collection_epoch_id") or None
    wal = (lifecycle_public or {}).get("emergency_wal") if isinstance(lifecycle_public, dict) else None
    wal_epoch = ((wal or {}).get("identity") or {}).get("epoch_id") if isinstance(wal, dict) else None
    identities = {
        "session_epoch": session_epoch,
        "identity_cache_epoch": cache_epoch,
        "lifecycle_wal_epoch": wal_epoch or None,
    }
    if not session_epoch:
        verdict = "UNBOUND"
    elif all(value == session_epoch for value in identities.values() if value is not None) and cache_epoch:
        verdict = "MATCH"
    else:
        verdict = "MISMATCH"
    return {**identities, "status": verdict, "match": verdict == "MATCH"}


def _lifecycle_pipeline_runtime_status() -> dict:
    runtime_module = _LIFECYCLE_PIPELINE_RUNTIME
    if runtime_module is None:
        if isinstance(_LIFECYCLE_PIPELINE_LAST_STATUS, dict):
            return copy.deepcopy(_LIFECYCLE_PIPELINE_LAST_STATUS)
        return {
            "schema": "lifecycle_pipeline_runtime_status_v1",
            "running": False,
            "owner": False,
            "active": False,
            "last_outcome": "NOT_STARTED",
            "source_revision": None,
            "source_cleanup_authorized": False,
        }
    try:
        return runtime_module.status()
    except BaseException as exc:
        return {
            "schema": "lifecycle_pipeline_runtime_status_v1",
            "available": False,
            "running": None,
            "owner": None,
            "active": None,
            "last_outcome": "STATUS_UNAVAILABLE",
            "last_error": type(exc).__name__,
            "source_revision": None,
            "source_cleanup_authorized": False,
        }


def _lifecycle_artifact_counts(now: float, maximum_entries: int = 4096) -> dict:
    """Count lifecycle artifacts with fixed traversal and no content reads."""
    root = _data_sync_runtime_root() / "v3"
    specifications = {
        "transfer_bundles": (root / "lifecycle_transfer_bundles", "transfer-", True),
        "completion_bundles": (root / "lifecycle_bundles", "lifecycle-", True),
        "acks": (_data_sync_volume_root() / "v3" / "lifecycle_cleanup_acks", "lifecycle-", False),
    }
    result = {}
    for label, (parent, prefix, nested) in specifications.items():
        count = 0
        newest = 0.0
        inspected = 0
        truncated = False
        try:
            containers = []
            if parent.is_dir():
                with os.scandir(parent) as entries:
                    for index, entry in enumerate(entries):
                        if index >= 256:
                            truncated = True
                            break
                        containers.append(Path(entry.path))
            candidates = (
                (item for bucket in containers if bucket.is_dir() for item in bucket.iterdir())
                if nested else iter(containers)
            )
            for item in candidates:
                inspected += 1
                if inspected > maximum_entries:
                    truncated = True
                    break
                name = item.name
                valid = (
                    item.is_dir() and name.startswith(prefix)
                    if nested else item.is_file() and name.startswith(prefix) and name.endswith(".json")
                )
                if not valid:
                    continue
                count += 1
                newest = max(newest, float(item.stat().st_mtime))
        except OSError:
            truncated = True
        result[label] = {
            "count": count,
            "newest_age_sec": max(0.0, now - newest) if newest else None,
            "scan_truncated": truncated,
        }
    return result


def _lifecycle_pipeline_public_status(now: float | None = None) -> dict:
    """Return bounded lifecycle telemetry without identifiers or proof material."""
    def _public_wal_alarm_details(raw_details, public_alarms) -> list:
        """Project WAL alarm explanations using only catalogued text and timestamps."""
        try:
            from emergency_evidence_wal import explain_alarm
        except Exception:
            return []
        by_code = {
            str(detail.get("code")): detail
            for detail in list(raw_details or [])[:32]
            if isinstance(detail, dict)
        }
        def ts(value):
            return (
                float(value)
                if isinstance(value, (int, float)) and not isinstance(value, bool)
                else None
            )
        out = []
        for code in public_alarms:
            detail = by_code.get(code) or {}
            explained = explain_alarm(code)
            out.append({
                "code": code,
                "reason": explained["reason"],
                "clears_when": explained["clears_when"],
                "clear_path": explained["clear_path"],
                "auto_clear": explained["auto_clear"],
                "first_seen_unix": ts(detail.get("first_seen")),
                "last_seen_unix": ts(detail.get("last_seen")),
            })
        return out

    current = float(now or time.time())
    internal = _lifecycle_pipeline_runtime_status()
    last = internal.get("last_result") if isinstance(internal.get("last_result"), dict) else {}
    bootstrap = (
        internal.get("receipt_bootstrap")
        if isinstance(internal.get("receipt_bootstrap"), dict) else {}
    )
    failure = internal.get("last_worker_failure") if isinstance(internal.get("last_worker_failure"), dict) else {}
    next_run = internal.get("next_run_unix")
    last_success = internal.get("last_success_unix")
    last_failure = internal.get("last_worker_failure_unix")
    runtime_revision = str(internal.get("source_revision") or "")
    exact_revision = str(_runtime_git_rev_exact() or "")
    overlap_raw = str(internal.get("overlap_code") or "")[:160]
    overlap_code = (
        overlap_raw
        if re.fullmatch(r"[A-Z0-9_:,.-]{1,160}", overlap_raw)
        else "OVERLAP_ACTIVE_REDACTED" if overlap_raw else None
    )
    failure_class_raw = str(failure.get("error_class") or "")
    failure_code_raw = str(failure.get("error_code") or "")
    failure_class = (
        failure_class_raw[:80]
        if re.fullmatch(r"[A-Za-z0-9_.]{1,80}", failure_class_raw)
        else "FAILURE_CLASS_REDACTED" if failure_class_raw else None
    )
    failure_code = (
        failure_code_raw[:80]
        if re.fullmatch(r"[A-Z0-9_.:-]{1,80}", failure_code_raw)
        else "FAILURE_CODE_REDACTED" if failure_code_raw else None
    )
    failure_ledger_raw = failure.get("ledger")
    failure_ledger = (
        failure_ledger_raw
        if failure_ledger_raw in (
            "opportunity", "pre_entry_features", "evidence_failure", "decision",
            "order_intent", "execution", "market_segment", "lifecycle",
        ) else None
    )
    failure_offset_raw = failure.get("byte_offset")
    failure_offset = (
        failure_offset_raw
        if isinstance(failure_offset_raw, int)
        and not isinstance(failure_offset_raw, bool)
        and failure_offset_raw >= 0 else None
    )
    current_error_raw = str(internal.get("last_error_code") or "")
    current_error_code = (
        current_error_raw[:80]
        if re.fullmatch(r"[A-Z0-9_.:-]{1,80}", current_error_raw)
        else "ERROR_CODE_REDACTED" if current_error_raw else None
    )
    safe_counts = lambda value: {
        str(key)[:96]: max(0, int(count))
        for key, count in list((value or {}).items())[:32]
        if re.fullmatch(r"[A-Z0-9_:.-]{1,96}", str(key))
        and isinstance(count, int) and not isinstance(count, bool)
    }
    def bounded_nonnegative(value, maximum=None):
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            return 0
        return min(value, maximum) if maximum is not None else value
    bootstrap_status = str(bootstrap.get("status") or "PENDING").upper()
    if bootstrap_status not in {"PENDING", "COMPLETE", "BLOCKED", "NOT_REQUIRED"}:
        bootstrap_status = "PENDING"
    bootstrap_ledger = bootstrap.get("ledger")
    if bootstrap_ledger not in (
        "opportunity", "pre_entry_features", "evidence_failure", "decision",
        "order_intent", "execution", "market_segment", "lifecycle",
    ):
        bootstrap_ledger = None
    bootstrap_public = {
        "required": bootstrap.get("required") is True,
        "status": bootstrap_status,
        "complete": bootstrap.get("complete") is True,
        "blocked": bootstrap.get("blocked") is True,
        "ledger": bootstrap_ledger,
        "ledgers_checked": bounded_nonnegative(bootstrap.get("ledgers_checked"), 8),
        "records_indexed": bounded_nonnegative(bootstrap.get("records_indexed")),
        "bytes_indexed": bounded_nonnegative(bootstrap.get("bytes_indexed")),
        "cursor": (
            bootstrap.get("cursor")
            if isinstance(bootstrap.get("cursor"), int)
            and not isinstance(bootstrap.get("cursor"), bool)
            and bootstrap.get("cursor") >= 0
            else None
        ),
    }
    wal = last.get("emergency_wal") if isinstance(last.get("emergency_wal"), dict) else {}
    wal_identity = wal.get("identity") if isinstance(wal.get("identity"), dict) else {}
    wal_action = wal.get("last_action") if isinstance(wal.get("last_action"), dict) else {}
    wal_observed = wal.get("observed_unix")
    exact_identity = {
        "epoch_id": str(wal_identity.get("epoch_id") or "")[:128],
        "source_revision": str(wal_identity.get("source_revision") or "")[:64],
        "deployed_revision": str(wal_identity.get("deployed_revision") or "")[:64],
        "tile_config_signature": str(wal_identity.get("tile_config_signature") or "")[:64],
    }
    wal_identity_valid = bool(
        re.fullmatch(r"epoch-[A-Za-z0-9._-]+", exact_identity["epoch_id"])
        and re.fullmatch(r"[0-9a-f]{7,64}", exact_identity["source_revision"])
        and re.fullmatch(r"[0-9a-f]{7,64}", exact_identity["deployed_revision"])
        and re.fullmatch(r"[0-9a-f]{64}", exact_identity["tile_config_signature"])
    )
    wal_identity_sha = hashlib.sha256(json.dumps(
        exact_identity, separators=(",", ":"), sort_keys=True,
    ).encode("utf-8")).hexdigest() if wal_identity_valid else ""
    wal_observed_age = (
        current - float(wal_observed)
        if isinstance(wal_observed, (int, float)) and not isinstance(wal_observed, bool)
        else None
    )
    wal_binding_valid = bool(
        wal_identity_valid
        and wal_identity_sha == str(wal.get("identity_sha256") or "")
        and exact_identity["source_revision"] == exact_revision
        and exact_identity["deployed_revision"] == exact_revision
    )
    wal_public = None
    if wal:
        state_counts = wal.get("state_counts") if isinstance(wal.get("state_counts"), dict) else {}
        event_counts = wal.get("event_counts") if isinstance(wal.get("event_counts"), dict) else {}
        alarms = [
            str(value)[:128] for value in list(wal.get("alarms") or [])[:32]
            if re.fullmatch(r"[A-Z0-9_.:-]{1,128}", str(value))
        ]
        incident_alarms = [
            str(value)[:128] for value in list(wal.get("incident_alarms") or [])[:32]
            if re.fullmatch(r"[A-Z0-9_.:-]{1,128}", str(value))
        ]
        generation = str(wal.get("oldest_generation") or "")
        action_generation = str(wal_action.get("generation") or "")
        action_reason = str(wal_action.get("reason") or "")
        numeric_values = tuple(wal.get(key) for key in (
            "capacity_extents", "free_extents", "retained_count", "retained_bytes",
        ))
        numeric_valid = all(
            isinstance(value, int) and not isinstance(value, bool) and value >= 0
            for value in numeric_values
        )
        capacity, free, retained, retained_bytes = numeric_values if numeric_valid else (0, 0, 0, 0)
        projected_states = {
            key: max(0, int(state_counts.get(key) or 0))
            if isinstance(state_counts.get(key, 0), int) and not isinstance(state_counts.get(key, 0), bool)
            else 0
            for key in ("PREPARED", "DEFERRED", "REPLAYED")
        }
        structurally_valid = bool(
            numeric_valid and 1 <= capacity <= 64 and free <= capacity
            and retained + free == capacity
            and sum(projected_states.values()) == retained
            and retained_bytes <= retained * 8 * 1024 * 1024
            and bool(generation) == bool(retained)
        )
        fresh = wal_observed_age is not None and -5.0 <= wal_observed_age <= 300.0
        reserve_ready = bool(wal_binding_valid and structurally_valid and fresh and not alarms)
        wal_public = {
            "status": (
                "CURRENT" if reserve_ready
                else "ALARM" if wal_binding_valid and structurally_valid and fresh and alarms
                else "STALE" if wal_binding_valid and structurally_valid and wal_observed_age is not None and wal_observed_age > 300.0
                else "INVALID"
            ),
            "reserve_ready": reserve_ready,
            "observed_age_sec": max(0.0, wal_observed_age) if wal_observed_age is not None else None,
            "identity": exact_identity if wal_binding_valid else None,
            "identity_sha256": wal_identity_sha if wal_binding_valid else None,
            "capacity_extents": capacity,
            "free_extents": free,
            "retained_count": retained,
            "retained_bytes": retained_bytes,
            "state_counts": projected_states,
            "event_counts_since_runtime_start": {
                key: max(0, int(event_counts.get(key) or 0))
                if isinstance(event_counts.get(key, 0), int) and not isinstance(event_counts.get(key, 0), bool)
                else 0
                for key in ("replayed", "released")
            },
            "oldest_generation": generation if re.fullmatch(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", generation) else None,
            "oldest_state": wal.get("oldest_state") if wal.get("oldest_state") in ("PREPARED", "DEFERRED", "REPLAYED") else None,
            "alarms": alarms,
            "incident_alarms": incident_alarms,
            "alarm_details": _public_wal_alarm_details(wal.get("alarm_details"), alarms),
            "last_action": {
                "replayed": wal_action.get("replayed") is True,
                "released": wal_action.get("released") is True,
                "blocked": wal_action.get("blocked") is True,
                "empty": wal_action.get("empty") is True,
                "reason": action_reason if re.fullmatch(r"[A-Z0-9_.:-]{1,80}", action_reason) else None,
                "generation": action_generation if re.fullmatch(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", action_generation) else None,
                "state": wal_action.get("state") if wal_action.get("state") in ("PREPARED", "DEFERRED", "REPLAYED") else None,
            },
        }
    return {
        "schema": "lifecycle_pipeline_public_status_v1",
        "available": internal.get("available") is not False,
        "owner": bool(internal.get("owner")) if internal.get("available") is not False else None,
        "running": bool(internal.get("running")) if internal.get("available") is not False else None,
        "active": bool(internal.get("active")) if internal.get("available") is not False else None,
        "source_revision_match": bool(
            runtime_revision and exact_revision and runtime_revision == exact_revision
        ),
        "last_outcome": str(internal.get("last_outcome") or "UNKNOWN")[:80],
        "last_error_code": current_error_code or failure_code or failure_class,
        "last_failure_class": failure_class,
        "last_failure_code": failure_code,
        "last_failure_ledger": failure_ledger,
        "last_failure_byte_offset": failure_offset,
        "last_failure_age_sec": (
            max(0.0, current - float(last_failure)) if last_failure else None
        ),
        "failure_count": max(0, int(internal.get("failure_count") or 0)),
        "backoff_sec": max(0.0, float(internal.get("backoff_sec") or 0.0)),
        "next_run_in_sec": max(0.0, float(next_run) - current) if next_run else None,
        "pressure": bool(internal.get("pressure")),
        "emergency": bool(internal.get("emergency")),
        "overlap_code": overlap_code,
        "last_success_age_sec": max(0.0, current - float(last_success)) if last_success else None,
        "progress": {
            key: max(0, int(last.get(key) or 0))
            for key in (
                "rows_scanned", "bytes_indexed", "pending_dirty_lifecycles",
                "promoted_qualification_retries", "candidate_count",
                "transfer_ready_count", "transfer_bundle_count",
                "completion_appended_count", "bundle_count",
            )
        } | {"caught_up": bool(last.get("caught_up"))},
        "stage_counts": safe_counts(last.get("stage_counts")),
        "blocker_counts": safe_counts(last.get("blocker_counts")),
        "receipt_bootstrap": bootstrap_public,
        "artifacts": _lifecycle_artifact_counts(current),
        "emergency_wal": wal_public,
    }


def _data_sync_inventory_snapshot_path() -> Path:
    return _data_sync_volume_root() / _DATA_SYNC_INVENTORY_SNAPSHOT_NAME


def _data_sync_invalidate_reset_inventory(new_epoch: str, *, expected_current_epoch=None) -> dict:
    """Reset-only invalidation under the already-held quiescent inventory gate.

    Replace only the acceleration pointer with a durable non-authoritative
    tombstone. Raw pages, research and ACK/recovery receipts are not deleted.
    The normal loader cannot restore this schema as a retained generation.
    """
    with _data_sync_inventory_cache_condition:
        if (_data_sync_inventory_cache.get("refreshing")
                or _data_sync_async_inventory.get("refreshing")
                or _data_sync_async_inventory.get("worker_active")):
            raise RuntimeError("RESET_INVENTORY_OWNER_ACTIVE")
        if not new_epoch or _collector_v22_epoch_id() not in {new_epoch, expected_current_epoch}:
            raise RuntimeError("RESET_INVENTORY_EPOCH_MISMATCH")
        marker = {
            "schema": "fly_runtime_inventory_invalidated_v1",
            "status": "EMPTY",
            "collection_epoch_id": new_epoch,
            "previous_generation_id": _data_sync_async_inventory.get("generation_id"),
            "invalidated_at": utc_iso(),
            "ack_eligible": False,
        }
        # Revoke first. Any subsequent persistence error must leave authority
        # revoked, never preserve old CURRENT metadata after partial deletion.
        _data_sync_inventory_cache.clear()
        _data_sync_inventory_cache.update(
            rows=None, expires_at=0.0, refreshed_at=0.0, refreshing=False)
        _data_sync_async_inventory.clear()
        _data_sync_async_inventory.update(
            status="EMPTY", rows=None, generation=None, generation_id=None,
            generated_at=None, expires_at=0.0, served_since_refresh=False,
            refreshing=False, worker_active=False, active_refresh_nonce=None,
            completed_refresh_nonce=None, error=None, worker_failure_code=None)
        _data_sync_inventory_cache_condition.notify_all()
        target = _data_sync_inventory_snapshot_path()
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.is_symlink():
            raise RuntimeError("RESET_INVENTORY_POINTER_LINKED")
        temporary = target.with_name(f"{target.name}.{uuid.uuid4().hex}.tmp")
        try:
            with temporary.open("w", encoding="utf-8") as handle:
                json.dump(marker, handle, sort_keys=True, separators=(",", ":"))
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, target)
            try:
                directory_fd = os.open(str(target.parent), os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            except OSError:
                # Windows may not permit a directory descriptor. On Fly/Linux
                # failure is fatal; memory remains revoked and reset stops.
                if os.name != "nt":
                    raise
        finally:
            temporary.unlink(missing_ok=True)
        return marker


def _data_sync_inventory_work_root() -> Path:
    """Return a real, non-linked work directory contained by the Fly volume."""
    volume = _data_sync_volume_root().resolve(strict=True)
    candidate = volume / ".data-sync-snapshots"
    if candidate.exists():
        lexical = Path(os.path.abspath(candidate))
        resolved = candidate.resolve(strict=True)
        resolved.relative_to(volume)
        if not resolved.is_dir():
            raise ValueError("data-sync work root is not a directory")
        if candidate.is_symlink() or resolved != lexical:
            raise ValueError("data-sync work root must not be linked")
    else:
        resolved = candidate.resolve()
        resolved.relative_to(volume)
        candidate.mkdir(parents=True, exist_ok=False)
        resolved = candidate.resolve(strict=True)
        resolved.relative_to(volume)
    return resolved


def _data_sync_lifecycle_ack_path(bundle_id: object) -> Path:
    """Resolve one immutable ACK target under the persistent Fly volume."""
    value = str(bundle_id or "").strip().lower()
    if not re.fullmatch(r"lifecycle-[0-9a-f]{64}", value):
        raise ValueError("invalid lifecycle bundle identity")
    root = (_data_sync_volume_root() / "v3" / "lifecycle_cleanup_acks").resolve()
    root.relative_to(_data_sync_volume_root().resolve())
    root.mkdir(parents=True, exist_ok=True)
    target = (root / f"{value}.json").resolve()
    target.relative_to(root)
    return target


def _data_sync_lifecycle_ack_index_path(lifecycle_id: object) -> Path:
    value = str(lifecycle_id or "")
    if not value or len(value.encode("utf-8")) > 4096:
        raise ValueError("invalid lifecycle acknowledgement index identity")
    lexical_root = _data_sync_volume_root() / "v3" / "lifecycle_cleanup_ack_index"
    if lexical_root.is_symlink():
        raise ValueError("lifecycle acknowledgement index root must not be linked")
    root = lexical_root.resolve()
    root.relative_to(_data_sync_volume_root().resolve())
    root.mkdir(parents=True, exist_ok=True)
    lexical_target = root / f"{hashlib.sha256(value.encode('utf-8')).hexdigest()}.json"
    if lexical_target.is_symlink():
        raise ValueError("lifecycle acknowledgement index must not be linked")
    target = lexical_target.resolve()
    target.relative_to(root)
    return target


def _data_sync_resolve_lifecycle_ack_index(lifecycle_id: object) -> tuple[Path, dict]:
    """Resolve and self-validate exactly one immutable ACK without directory scans."""
    target = _data_sync_lifecycle_ack_index_path(lifecycle_id)
    raw = target.read_bytes()
    row = json.loads(raw.decode("utf-8"))
    supplied = str(row.get("binding_sha256") or "")
    material = dict(row); material.pop("binding_sha256", None)
    expected = hashlib.sha256(json.dumps(
        material, separators=(",", ":"), sort_keys=True,
    ).encode("utf-8")).hexdigest()
    if (
        row.get("schema") != "lifecycle_bundle_ack_index_v1"
        or row.get("lifecycle_id") != str(lifecycle_id or "")
        or not hmac.compare_digest(supplied, expected)
        or not re.fullmatch(r"[0-9a-f]{64}", str(row.get("ack_sha256") or ""))
    ):
        raise ValueError("lifecycle acknowledgement index invalid")
    relative_ack = str(row.get("ack_path") or "").replace("\\", "/").strip("/")
    if not relative_ack or relative_ack.startswith(".") or ".." in relative_ack.split("/"):
        raise ValueError("lifecycle acknowledgement index path invalid")
    ack = (_data_sync_volume_root() / relative_ack).resolve(strict=True)
    ack.relative_to((_data_sync_volume_root() / "v3" / "lifecycle_cleanup_acks").resolve())
    expected_ack = _data_sync_lifecycle_ack_path(row.get("bundle_id"))
    if ack != expected_ack or not hmac.compare_digest(
        hashlib.sha256(ack.read_bytes()).hexdigest(), row["ack_sha256"],
    ):
        raise ValueError("lifecycle acknowledgement index binding mismatch")
    persisted = json.loads(ack.read_text(encoding="utf-8"))
    receipt = persisted.get("receipt") if isinstance(persisted, dict) else None
    if not isinstance(receipt, dict) or receipt.get("lifecycle_id") != str(lifecycle_id or ""):
        raise ValueError("lifecycle acknowledgement index receipt mismatch")
    return ack, receipt


# Inbound uploads, not generation transfer; every other /api/data-sync/ route
# belongs to the retired whole-generation path (research ships as segments).
_DATA_SYNC_INBOUND_ROUTES = frozenset({
    "/api/data-sync/platform-relay-evidence", "/api/data-sync/analyzer-report",
})


@app.before_request
def _legacy_data_sync_retired_guard():
    path = request.path or ""
    if path.startswith("/api/data-sync/") and path not in _DATA_SYNC_INBOUND_ROUTES:
        return jsonify({"ok": False, "errorCode": "LEGACY_DATA_SYNC_RETIRED",
                        "replacement": "/api/research-segments/"}), 410
    return None


_data_sync_identity_cache_lock = threading.Lock()
_data_sync_identity_epoch_cache = {
    "collection_epoch_id": None,
    "fresh_collection_signal_ts": 0.0,
}


_EPOCH_CACHE_UNCHANGED = object()


def _update_data_sync_identity_epoch_cache(
    *, collection_epoch_id=_EPOCH_CACHE_UNCHANGED, fresh_collection_signal_ts=None,
):
    """Publish already-observed epoch identity without request-path I/O.

    An explicit falsy epoch clears the cache so an unbound session can never
    keep advertising a stale epoch; a new value rebinds it.
    """
    with _data_sync_identity_cache_lock:
        if collection_epoch_id is not _EPOCH_CACHE_UNCHANGED:
            _data_sync_identity_epoch_cache["collection_epoch_id"] = (
                str(collection_epoch_id).strip() or None
                if collection_epoch_id else None
            )
        if fresh_collection_signal_ts is not None:
            _data_sync_identity_epoch_cache["fresh_collection_signal_ts"] = float(
                fresh_collection_signal_ts or 0.0
            )


def _prime_data_sync_identity_epoch_cache() -> None:
    """Read durable epoch identity at startup and after every session write."""
    session = _load_research_session_meta() or {}
    epoch_id = _bound_collection_epoch_id()
    try:
        signal_ts = float(
            state.get("fresh_collection_signal_ts")
            or session.get("fresh_collection_start_time")
            or 0.0
        )
    except (TypeError, ValueError):
        signal_ts = 0.0
    _update_data_sync_identity_epoch_cache(
        collection_epoch_id=epoch_id or None,
        fresh_collection_signal_ts=signal_ts,
    )


def _data_sync_lifecycle_cleanup_current_identity() -> dict:
    """Bind cleanup to the exact running revision, epoch, registry and config."""
    revision = _runtime_git_rev()
    config_material = {
        key: state.get(key)
        for key in sorted(_persistent_config_keys())
        if key in state
    }
    return {
        "source_git_rev": revision,
        "deployed_git_rev": revision,
        "collection_epoch_id": _bound_collection_epoch_id(),
        "tile_registry_signature": active_tile_registry_signature(),
        "config_signature": hashlib.sha256(json.dumps(
            config_material, separators=(",", ":"), sort_keys=True,
        ).encode("utf-8")).hexdigest(),
    }


def _data_sync_lifecycle_cleanup_active_references() -> dict:
    """Snapshot every known runtime/transfer/analyzer owner fail-closed."""
    runtime = []
    with trade_lock:
        runtime.extend(
            str(row.get("trade_id") or row.get("order_id") or "UNKNOWN")
            for row in pending_orders
            if isinstance(row, dict) and row.get("status") == "PENDING"
        )
        runtime.extend(
            str(row.get("trade_id") or row.get("position_id") or "UNKNOWN")
            for row in open_positions if isinstance(row, dict)
        )
    sync = []
    with _data_sync_inventory_cache_condition:
        if _data_sync_inventory_cache.get("refreshing"):
            sync.append("SYNC_INVENTORY_CACHE_REFRESH")
        if _data_sync_async_inventory.get("refreshing"):
            sync.append("SYNC_ASYNC_INVENTORY_REFRESH")
    with _data_sync_sqlite_snapshot_condition:
        if any(
            state.get("status") == "BUILDING"
            for state in _data_sync_sqlite_snapshot_states.values()
        ):
            sync.append("SQLITE_SNAPSHOT_BUILDING")
    analyzer = []
    if mirror_generation_lease_held(_data_sync_volume_root()):
        analyzer.append(".fly-mirror-generation.lease")
    lifecycle_worker = []
    worker = _LIFECYCLE_PIPELINE_RUNTIME
    if worker is not None:
        try:
            if worker.status().get("active"):
                lifecycle_worker.append("LIFECYCLE_PIPELINE_RUNTIME")
        except BaseException:
            lifecycle_worker.append("LIFECYCLE_PIPELINE_STATUS_UNKNOWN")
    return {
        "runtime": runtime, "sync": sync, "analyzer": analyzer,
        "lifecycle_worker": lifecycle_worker,
    }


def _data_sync_release_one_replayed_wal_extent(
    receipt: dict, proof: dict, cleanup_result: dict,
    lease_snapshot_before: dict, lease_snapshot_after: dict,
) -> dict:
    """Bind one replayed reserve row to a committed lifecycle transfer proof."""
    empty = {"runtime": [], "sync": [], "analyzer": [], "lifecycle_worker": []}
    if (
        cleanup_result.get("source_cleanup_authorized") is not True
        or lease_snapshot_before != empty or lease_snapshot_after != empty
    ):
        raise ValueError("emergency WAL release lease or cleanup authorization missing")
    volume = _data_sync_volume_root().resolve()
    current = _data_sync_lifecycle_cleanup_current_identity()
    identity = {
        "epoch_id": current["collection_epoch_id"],
        "source_revision": str(receipt.get("source_git_rev") or ""),
        "deployed_revision": str(receipt.get("deployed_git_rev") or ""),
        "tile_config_signature": current["tile_registry_signature"],
    }
    wal = EmergencyEvidenceWal(
        volume / "v3" / "emergency_evidence_wal_v2", identity=identity,
    )
    record = wal.oldest_record()
    if record is None or record.get("state") != "REPLAYED":
        raise ValueError("no oldest replayed emergency WAL row")
    lifecycle_id = "|".join(str(value or "") for value in (
        json.loads(record["payload"].decode("utf-8")).get("episode_id"),
        json.loads(record["payload"].decode("utf-8")).get("policy_signature"),
        json.loads(record["payload"].decode("utf-8")).get("research_lane"),
    ))
    if lifecycle_id != str(receipt.get("lifecycle_id") or ""):
        raise ValueError("emergency WAL lifecycle acknowledgement mismatch")
    quarantine = (volume / str(cleanup_result.get("quarantine") or "")).resolve(strict=True)
    quarantine.relative_to((volume / "v3" / "lifecycle_cleanup_quarantine").resolve())
    events = quarantine / "events.jsonl"
    matched, scanned = False, 0
    with events.open("rb") as handle:
        while scanned <= 64 * 1024 * 1024:
            line = handle.readline(8 * 1024 * 1024 + 1)
            if not line: break
            scanned += len(line)
            if len(line) > 8 * 1024 * 1024 or not line.endswith(b"\n"):
                raise ValueError("emergency WAL acknowledged bundle row invalid")
            if hashlib.sha256(line).hexdigest() == record["row_sha256"]:
                matched = True; break
    if not matched:
        raise ValueError("emergency WAL row absent from acknowledged lifecycle bundle")
    tx_dir = volume / "v3" / "lifecycle_cleanup_transactions" / hashlib.sha256(
        str(receipt["bundle_id"]).encode("utf-8")
    ).hexdigest()[:24]
    committed = tx_dir / "COMMITTED.json"
    committed_raw = committed.read_bytes()
    committed_row = json.loads(committed_raw.decode("utf-8"))
    if committed_row.get("state") != "COMMITTED" or committed_row.get("bundle_id") != receipt.get("bundle_id"):
        raise ValueError("emergency WAL cleanup transaction is not committed")
    persisted_lifecycle_ack = _data_sync_lifecycle_ack_path(receipt["bundle_id"]).read_bytes()
    material = {
        "schema": "emergency_wal_lifecycle_release_ack_v1",
        "source_cleanup_authorized": True,
        "generation": record["generation"], "identity": identity,
        "ledger": record["ledger"], "record_id": record["record_id"],
        "row_sha256": record["row_sha256"],
        "replay_receipt_sha256": record["replay_receipt_sha256"],
        "manifest_sha256": str(receipt.get("manifest_sha256") or ""),
        "cleanup_transaction_sha256": hashlib.sha256(committed_raw).hexdigest(),
        "lifecycle_ack_sha256": hashlib.sha256(persisted_lifecycle_ack).hexdigest(),
        "config_signature": current["config_signature"],
        "bundle_id": receipt["bundle_id"],
        "lifecycle_id": receipt["lifecycle_id"],
        "lease_snapshot_before": lease_snapshot_before,
        "lease_snapshot_after": lease_snapshot_after,
    }
    material["binding_sha256"] = hashlib.sha256(json.dumps(
        material, separators=(",", ":"), sort_keys=True,
    ).encode("utf-8")).hexdigest()
    ack_root = volume / "v3" / "emergency_wal_release_acks"; ack_root.mkdir(parents=True, exist_ok=True)
    target = ack_root / f'{record["generation"]}.json'
    encoded = json.dumps(material, separators=(",", ":"), sort_keys=True).encode("utf-8") + b"\n"
    temporary = target.with_name(f".{target.name}.{uuid.uuid4().hex}.tmp")
    try:
        with temporary.open("xb") as handle:
            handle.write(encoded); handle.flush(); os.fsync(handle.fileno())
        os.link(temporary, target)
        if os.name != "nt":
            directory_fd = os.open(str(target.parent), os.O_RDONLY)
            try: os.fsync(directory_fd)
            finally: os.close(directory_fd)
    except FileExistsError:
        if target.read_bytes() != encoded: raise ValueError("conflicting emergency WAL release acknowledgement")
    finally:
        temporary.unlink(missing_ok=True)
    return wal.acknowledge(record["generation"], {})


def _reconcile_lifecycle_cleanup_transactions() -> list:
    """Finalize only already-quarantined transactions after restart."""
    transaction = CleanupTransaction(
        _data_sync_volume_root(),
        enabled=os.getenv("LIFECYCLE_CLEANUP_ENABLED", "false").lower() == "true",
    )
    results = transaction.reconcile()
    wal_recovery = _reconcile_one_emergency_wal_release()
    if wal_recovery is not None:
        results.append(wal_recovery)
    if results:
        logger.warning("lifecycle cleanup restart reconciliation results=%s", results)
    return results


def _reconcile_one_emergency_wal_release() -> dict | None:
    """Recover the commit-to-release-ACK crash window for the oldest row."""
    volume = _data_sync_volume_root().resolve()
    wal_root = volume / "v3" / "emergency_evidence_wal_v2"
    if not wal_root.exists(): return None
    current = _data_sync_lifecycle_cleanup_current_identity()
    identity = {
        "epoch_id": current["collection_epoch_id"],
        "source_revision": current["source_git_rev"],
        "deployed_revision": current["deployed_git_rev"],
        "tile_config_signature": current["tile_registry_signature"],
    }
    try:
        wal = EmergencyEvidenceWal(wal_root, identity=identity)
        record = wal.oldest_record()
        if record is None or record.get("state") != "REPLAYED": return None
        existing = wal.release_oldest_if_acknowledged()
        if existing.get("released") is True:
            return {"status": "EMERGENCY_WAL_RELEASE_ACK_RECOVERED", **existing}
        row = json.loads(record["payload"].decode("utf-8"))
        lifecycle_id = "|".join(str(row.get(key) or "") for key in (
            "episode_id", "policy_signature", "research_lane",
        ))
        _ack_path, receipt = _data_sync_resolve_lifecycle_ack_index(lifecycle_id)
        bundle_id = str(receipt.get("bundle_id") or "")
        quarantine = volume / "v3" / "lifecycle_cleanup_quarantine" / bundle_id
        tx = volume / "v3" / "lifecycle_cleanup_transactions" / hashlib.sha256(
            bundle_id.encode("utf-8")
        ).hexdigest()[:24] / "COMMITTED.json"
        if not quarantine.is_dir() or not tx.is_file():
            return {"status": "EMERGENCY_WAL_RELEASE_ACK_PENDING", "released": False}
        key_id = str((receipt.get("laptop_attestation") or {}).get("key_id") or "")
        secret = os.getenv("LIFECYCLE_LAPTOP_ATTESTATION_KEY", "").encode("utf-8")
        keys = {key_id: secret} if key_id and secret else {}
        before = _data_sync_lifecycle_cleanup_active_references()
        proof = verify_lifecycle_cleanup_bundle(
            quarantine, receipt, current_identity=current,
            active_references=before, attestation_keys=keys,
        )
        after = _data_sync_lifecycle_cleanup_active_references()
        released = _data_sync_release_one_replayed_wal_extent(
            receipt, proof,
            {"source_cleanup_authorized": True, "quarantine": quarantine.relative_to(volume).as_posix()},
            before, after,
        )
        return {"status": "EMERGENCY_WAL_COMMIT_WINDOW_RECOVERED", **released}
    except (OSError, TypeError, ValueError, RuntimeError, json.JSONDecodeError) as exc:
        return {"status": "EMERGENCY_WAL_RELEASE_RECOVERY_BLOCKED", "released": False, "reason": str(exc)[:240]}


def _audit_lifecycle_purge_recovery() -> list:
    """Report interrupted purge state at startup; never delete automatically."""
    root = _data_sync_volume_root() / "v3" / "lifecycle_purge_transactions"
    if not root.is_dir():
        return []
    rows = []
    from itertools import islice
    sampled = list(islice(root.iterdir(), 129))
    if len(sampled) > 128:
        rows.append({"status": "RECOVERY_AUDIT_INCOMPLETE", "limit": 128})
    for transaction_dir in sampled[:128]:
        if not transaction_dir.is_dir():
            continue
        if (transaction_dir / "PREPARED.json").is_file() and not (
            transaction_dir / "PURGED.json"
        ).is_file():
            rows.append({
                "transaction": transaction_dir.name,
                "status": "PREPARED_REQUIRES_EXPLICIT_REPLAY",
            })
    if rows:
        logger.warning(
            "lifecycle purge recovery requires explicit admin replay count=%s", len(rows)
        )
    return rows


_RAW_GENERATION_GATE_LOCAL = threading.local()


def _raw_generation_cleanup_identity() -> dict:
    current = _data_sync_lifecycle_cleanup_current_identity()
    return {
        "source_revision": current["source_git_rev"],
        "deployed_revision": current["deployed_git_rev"],
        "collection_epoch_id": current["collection_epoch_id"],
        "tile_registry_signature": current["tile_registry_signature"],
        "config_signature": current["config_signature"],
    }


def _raw_generation_cleanup_leases(_generation_id: str) -> dict:
    """Conservatively translate all known owners into generation leases."""
    active = _data_sync_lifecycle_cleanup_active_references()
    return {
        "reader": list(active.get("runtime") or []) + list(active.get("lifecycle_worker") or []),
        "sync": list(active.get("sync") or []),
        "analyzer": [] if getattr(_RAW_GENERATION_GATE_LOCAL, "mirror", None) else list(active.get("analyzer") or []),
    }


def _raw_generation_cleanup_gate_acquire() -> bool:
    runtime = _LIFECYCLE_PIPELINE_RUNTIME
    if runtime is not None and not runtime.acquire_cleanup_lease(timeout=0.0):
        return False
    try:
        mirror = MirrorGenerationLease(_data_sync_volume_root(), owner="raw-generation-cleanup")
        mirror.acquire(timeout_seconds=0.0)
        _RAW_GENERATION_GATE_LOCAL.runtime = runtime
        _RAW_GENERATION_GATE_LOCAL.mirror = mirror
        return True
    except (OSError, MirrorGenerationLeaseTimeout):
        if runtime is not None: runtime.release_cleanup_lease()
        return False


def _raw_generation_cleanup_gate_release() -> None:
    mirror = getattr(_RAW_GENERATION_GATE_LOCAL, "mirror", None)
    runtime = getattr(_RAW_GENERATION_GATE_LOCAL, "runtime", None)
    if mirror is not None: mirror.release()
    if runtime is not None: runtime.release_cleanup_lease()
    for name in ("mirror", "runtime"):
        if hasattr(_RAW_GENERATION_GATE_LOCAL, name): delattr(_RAW_GENERATION_GATE_LOCAL, name)


def _raw_generation_cleanup_owner(*, purge: bool = False) -> RawGenerationCleanupOwner:
    enabled = os.getenv("RAW_GENERATION_CLEANUP_ENABLED", "false").lower() == "true"
    if purge:
        enabled = enabled and os.getenv("RAW_GENERATION_PURGE_ENABLED", "false").lower() == "true"
    return RawGenerationCleanupOwner(
        _data_sync_volume_root(), enabled=enabled,
        identity=_raw_generation_cleanup_identity,
        leases=_raw_generation_cleanup_leases,
        gate_acquire=_raw_generation_cleanup_gate_acquire,
        gate_release=_raw_generation_cleanup_gate_release,
    )


def _audit_raw_generation_cleanup_recovery() -> list:
    """Startup visibility only: never move or delete interrupted generations."""
    try:
        rows = _raw_generation_cleanup_owner().audit_recovery()
    except (OSError, TypeError, ValueError, json.JSONDecodeError) as exc:
        rows = [{"status": "RAW_GENERATION_RECOVERY_AUDIT_FAILED", "reason": str(exc)[:240]}]
    if rows: logger.warning("raw generation cleanup requires explicit replay states=%s", rows)
    return rows


_PLATFORM_RELAY_EVIDENCE_MAX_BYTES = 25 * 1024 * 1024
_PLATFORM_RELAY_EVIDENCE_WORKER_TIMEOUT_SEC = max(
    1.0, float(os.getenv("PLATFORM_RELAY_EVIDENCE_WORKER_TIMEOUT_SEC", "90"))
)
_PLATFORM_RELAY_EVIDENCE_WORKER_REQUEST_SCHEMA = "platform_relay_evidence_worker_request_v1"
_PLATFORM_RELAY_EVIDENCE_WORKER_RESULT_SCHEMA = "platform_relay_evidence_worker_result_v1"
_PLATFORM_RELAY_EVIDENCE_INSTALL_LOCK = threading.RLock()
_PLATFORM_RELAY_EVIDENCE_RECEIPT_SCHEMA = "platform_relay_evidence_install_receipt_v1"


def _platform_relay_evidence_receipt_path(destination: Path) -> Path:
    return destination.with_name(f"{destination.name}.receipt.json")


def _platform_relay_evidence_duplicate_receipt(
    destination: Path, digest: str, size: int
) -> dict | None:
    """Return trusted ACK metadata only for an intact prior installation."""
    receipt_path = _platform_relay_evidence_receipt_path(destination)
    try:
        receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
        if not (
            receipt.get("schema") == _PLATFORM_RELAY_EVIDENCE_RECEIPT_SCHEMA
            and hmac.compare_digest(str(receipt.get("sha256") or ""), digest)
            and int(receipt.get("size") or -1) == int(size)
            and destination.is_file()
            and destination.stat().st_size == int(receipt.get("size") or -1)
            and receipt.get("payload_schema") == "relay_lifecycle_evidence_v1"
            and isinstance(receipt.get("records"), int)
            and receipt["records"] >= 0
            and bool(receipt.get("generating_revision"))
        ):
            return None
        installed_digest = hashlib.sha256()
        with destination.open("rb") as handle:
            for block in iter(lambda: handle.read(1024 * 1024), b""):
                installed_digest.update(block)
        if not hmac.compare_digest(installed_digest.hexdigest(), str(receipt.get("sha256") or "")):
            return None
        return receipt
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return None


def _write_platform_relay_evidence_receipt(
    destination: Path, digest: str, semantic_digest: str, size: int, result: dict
) -> None:
    receipt_path = _platform_relay_evidence_receipt_path(destination)
    receipt = {
        "schema": _PLATFORM_RELAY_EVIDENCE_RECEIPT_SCHEMA,
        "sha256": digest,
        "semantic_sha256": semantic_digest,
        "size": int(size),
        "payload_schema": result["payload_schema"],
        "records": int(result["records"]),
        "generating_revision": result["generating_revision"],
    }
    temp = receipt_path.with_name(f"{receipt_path.name}.{uuid.uuid4().hex}.tmp")
    try:
        temp.write_text(json.dumps(receipt, separators=(",", ":"), sort_keys=True), encoding="utf-8")
        os.replace(temp, receipt_path)
    finally:
        temp.unlink(missing_ok=True)


def _validate_platform_relay_evidence_payload(payload: dict) -> tuple[bool, str]:
    return _pure_validate_platform_relay_evidence_payload(payload)


def _validate_platform_relay_evidence_in_worker(staged: Path, digest: str, size: int) -> dict:
    """Validate a staged upload without holding the trading interpreter's GIL."""
    nonce = uuid.uuid4().hex
    work_root = _data_sync_inventory_work_root()
    request_path = work_root / f"relay-request-{nonce}.json"
    result_path = work_root / f"relay-result-{nonce}.json"
    worker_input = work_root / f"relay-input-{nonce}.json"
    keep_worker_input = False
    launched_unix = time.time()
    if staged.resolve(strict=True).parent != work_root.resolve(strict=True):
        raise ValueError("relay evidence staging escaped confined work root")
    os.replace(staged, worker_input)
    request_payload = {
        "schema": _PLATFORM_RELAY_EVIDENCE_WORKER_REQUEST_SCHEMA,
        "nonce": nonce,
        "input_path": str(worker_input),
        "expected_sha256": digest,
        "expected_size": int(size),
        "launched_unix": launched_unix,
    }
    request_tmp = request_path.with_name(f"{request_path.name}.tmp")
    request_tmp.write_text(json.dumps(request_payload, separators=(",", ":"), sort_keys=True), encoding="utf-8")
    os.replace(request_tmp, request_path)
    worker_env = {
        key: os.environ[key]
        for key in ("SYSTEMROOT", "WINDIR", "COMSPEC", "TEMP", "TMP", "TMPDIR", "PATH", "LANG", "LC_ALL")
        if key in os.environ
    }
    worker_env.update({
        "PYTHONNOUSERSITE": "1", "PYTHONHASHSEED": "0",
        "OPENBLAS_NUM_THREADS": "1", "OMP_NUM_THREADS": "1", "MKL_NUM_THREADS": "1",
    })
    try:
        completed = subprocess.run(
            [sys.executable, str(Path(__file__).resolve().with_name("platform_relay_evidence_worker.py")),
             "--request", str(request_path), "--result", str(result_path), "--nonce", nonce],
            stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            timeout=_PLATFORM_RELAY_EVIDENCE_WORKER_TIMEOUT_SEC, check=False, env=worker_env,
        )
        if completed.returncode != 0:
            raise RuntimeError("relay evidence validator subprocess failed")
        result = json.loads(result_path.read_text(encoding="utf-8"))
        if not (
            result.get("schema") == _PLATFORM_RELAY_EVIDENCE_WORKER_RESULT_SCHEMA
            and hmac.compare_digest(str(result.get("nonce") or ""), nonce)
            and hmac.compare_digest(str(result.get("request_sha256") or ""), digest)
            and hmac.compare_digest(str(result.get("input_sha256") or ""), digest)
            and int(result.get("input_size") or -1) == int(size)
            and float(result.get("generated_unix") or 0.0) >= launched_unix
            and isinstance(result.get("valid"), bool)
        ):
            raise RuntimeError("relay evidence validator result validation failed")
        if result["valid"] and not (
            result.get("error_code") == "OK"
            and result.get("payload_schema") == "relay_lifecycle_evidence_v1"
            and isinstance(result.get("records"), int)
            and result["records"] >= 0
            and bool(result.get("generating_revision"))
        ):
            raise RuntimeError("relay evidence validator success metadata invalid")
        result["staged_path"] = worker_input
        keep_worker_input = True
        return result
    finally:
        for transient in (
            request_path, result_path, request_tmp,
            None if keep_worker_input else worker_input,
        ):
            if transient is None:
                continue
            try:
                transient.unlink(missing_ok=True)
            except OSError:
                pass


@app.route('/api/data-sync/platform-relay-evidence', methods=['POST'])
def api_data_sync_platform_relay_evidence():
    """Install a validated Neon/Bitfinex evidence snapshot for the bot's
    append-derived counterfactual join. The data-sync namespace is protected by
    the strict admin-token middleware; no trading state is mutated here."""
    declared_size = request.content_length
    if declared_size is not None and (declared_size <= 0 or declared_size > _PLATFORM_RELAY_EVIDENCE_MAX_BYTES):
        return jsonify({"ok": False, "errorCode": "SIZE_INVALID"}), 413
    destination = Path(PLATFORM_RELAY_EVIDENCE_FILE)
    if not destination.is_absolute():
        destination = _data_sync_volume_root() / destination.name
    destination.parent.mkdir(parents=True, exist_ok=True)
    digest_builder = hashlib.sha256()
    declared_digest = str(request.headers.get("X-Content-SHA256") or "").strip().lower()
    semantic_digest = str(request.headers.get("X-Relay-Semantic-SHA256") or "").strip().lower()
    if declared_digest and not re.fullmatch(r"[0-9a-f]{64}", declared_digest):
        return jsonify({"ok": False, "errorCode": "CHECKSUM_INVALID"}), 400
    if not re.fullmatch(r"[0-9a-f]{64}", semantic_digest):
        return jsonify({"ok": False, "errorCode": "SEMANTIC_CHECKSUM_INVALID"}), 400
    received_size = 0
    work_root = _data_sync_inventory_work_root()
    temp = work_root / f"relay-input-stage-{uuid.uuid4().hex}.json"
    staged = None
    try:
        with temp.open("wb") as handle:
            while True:
                block = request.stream.read(1024 * 1024)
                if not block:
                    break
                received_size += len(block)
                if received_size > _PLATFORM_RELAY_EVIDENCE_MAX_BYTES:
                    return jsonify({"ok": False, "errorCode": "SIZE_INVALID"}), 413
                digest_builder.update(block)
                handle.write(block)
            handle.flush()
            os.fsync(handle.fileno())
        if received_size <= 0 or (declared_size is not None and received_size != declared_size):
            return jsonify({"ok": False, "errorCode": "SIZE_INVALID"}), 413
        digest = digest_builder.hexdigest()
        if declared_digest and not hmac.compare_digest(declared_digest, digest):
            return jsonify({"ok": False, "errorCode": "CHECKSUM_MISMATCH"}), 400
        # Serialize only installation/validation, not request streaming. A
        # timed-out client may retry while its first validation is still
        # finishing. The retry hashes its own bytes, waits here, then uses the
        # first request's durable receipt instead of launching a second worker.
        with _PLATFORM_RELAY_EVIDENCE_INSTALL_LOCK:
            prior = _platform_relay_evidence_duplicate_receipt(destination, digest, received_size)
            if prior is not None:
                result = {
                    "payload_schema": prior["payload_schema"],
                    "records": prior["records"],
                    "generating_revision": prior["generating_revision"],
                }
                duplicate = True
            else:
                result = _validate_platform_relay_evidence_in_worker(temp, digest, received_size)
                staged = Path(result["staged_path"])
                if not result["valid"]:
                    return jsonify({"ok": False, "errorCode": result["error_code"]}), 400
                os.replace(staged, destination)
                staged = None
                _write_platform_relay_evidence_receipt(
                    destination, digest, semantic_digest, received_size, result
                )
                duplicate = False
    except subprocess.TimeoutExpired:
        return jsonify({"ok": False, "errorCode": "VALIDATION_TIMEOUT"}), 503
    except (OSError, ValueError, RuntimeError, json.JSONDecodeError):
        return jsonify({"ok": False, "errorCode": "VALIDATION_FAILED"}), 500
    finally:
        for transient in (temp, staged):
            if transient is not None:
                try:
                    transient.unlink(missing_ok=True)
                except OSError:
                    pass
    return jsonify({
        "ok": True,
        "schema": result["payload_schema"],
        "sha256": digest,
        "semanticSha256": semantic_digest,
        "records": result["records"],
        "generatingRevision": result["generating_revision"],
        "duplicate": duplicate,
    })


def _analyzer_mirror_dir() -> Path:
    return _data_sync_volume_root() / "analyzer_mirror"


_ANALYZER_BUNDLE_MAX_COMPRESSED_BYTES = 50 * 1024 * 1024
_ANALYZER_BUNDLE_MAX_EXPANDED_BYTES = 150 * 1024 * 1024
_ANALYZER_BUNDLE_MAX_MEMBERS = 256
_ANALYZER_BUNDLE_MAX_MEMBER_BYTES = 50 * 1024 * 1024
_ANALYZER_BUNDLE_MAX_COMPRESSION_RATIO = 1000
_ANALYZER_BUNDLE_ALLOWED_SUFFIXES = frozenset((".html", ".txt", ".json", ".log"))
_ANALYZER_BUNDLE_MANIFEST = "bundle_manifest.json"
_ANALYZER_BUNDLE_SCHEMA = "analyzer_mirror_bundle_v2"
_ANALYZER_INSTALL_LOCK = threading.RLock()
if app.config.get("MAX_CONTENT_LENGTH") is None:
    # Bound multipart spooling before Flask parses request.files. The analyzer
    # ZIP is the largest accepted upload in this service.
    app.config["MAX_CONTENT_LENGTH"] = _ANALYZER_BUNDLE_MAX_COMPRESSED_BYTES + 1024 * 1024


def _analyzer_generations_dir() -> Path:
    return _data_sync_volume_root() / "analyzer_generations"


def _analyzer_current_pointer_path() -> Path:
    return _data_sync_volume_root() / "analyzer_current.json"


def _valid_analyzer_generation(candidate: Path) -> bool:
    """Accept only a complete, hash-bound bundle-v2 generation on disk."""
    try:
        status = json.loads((candidate / "status.json").read_text(encoding="utf-8"))
        manifest = json.loads(
            (candidate / _ANALYZER_BUNDLE_MANIFEST).read_text(encoding="utf-8")
        )
        if not (
            candidate.is_dir()
            and status.get("complete") is True
            and status.get("schema") == _ANALYZER_BUNDLE_SCHEMA
            and manifest.get("schema") == _ANALYZER_BUNDLE_SCHEMA
            and isinstance(manifest.get("files"), list)
        ):
            return False
        declared = {}
        for row in manifest["files"]:
            rel = str((row or {}).get("path") or "").replace("\\", "/")
            rel_path = Path(rel)
            digest = str((row or {}).get("sha256") or "").lower()
            size = int((row or {}).get("size_bytes"))
            if (
                not rel or rel_path.is_absolute() or ".." in rel_path.parts
                or rel != str(rel_path).replace("\\", "/")
                or rel == _ANALYZER_BUNDLE_MANIFEST
                or rel.casefold() in declared
                or rel_path.suffix.lower() not in _ANALYZER_BUNDLE_ALLOWED_SUFFIXES
                or not re.fullmatch(r"[0-9a-f]{64}", digest)
                or size < 0 or size > _ANALYZER_BUNDLE_MAX_MEMBER_BYTES
            ):
                return False
            declared[rel.casefold()] = (rel, digest, size)
        if "analysis_dashboard.html" not in {row[0] for row in declared.values()}:
            return False
        actual = set()
        root = candidate.resolve()
        for path in candidate.rglob("*"):
            if not path.is_file() or path.is_symlink():
                continue
            rel = path.relative_to(candidate).as_posix()
            if rel in ("status.json", _ANALYZER_BUNDLE_MANIFEST):
                continue
            resolved = path.resolve()
            resolved.relative_to(root)
            actual.add(rel.casefold())
            expected = declared.get(rel.casefold())
            if expected is None or path.stat().st_size != expected[2]:
                return False
            if hashlib.sha256(path.read_bytes()).hexdigest() != expected[1]:
                return False
        return actual == set(declared)
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return False


def _recover_latest_analyzer_generation() -> Path | None:
    """Recover from a missing/corrupt pointer without selecting staging data."""
    generations = _analyzer_generations_dir()
    try:
        candidates = sorted(
            (
                path for path in generations.iterdir()
                if path.name.startswith("generation-") and _valid_analyzer_generation(path)
            ),
            key=lambda path: path.stat().st_mtime_ns,
            reverse=True,
        )
    except OSError:
        return None
    return candidates[0] if candidates else None


def _active_analyzer_mirror_dir() -> Path | None:
    """Resolve only a fully validated immutable generation; never serve legacy HTML."""
    pointer = _analyzer_current_pointer_path()
    try:
        row = json.loads(pointer.read_text(encoding="utf-8"))
        generation = str(row.get("generation") or "")
        if not generation or generation != Path(generation).name:
            raise ValueError("invalid analyzer generation pointer")
        root = _analyzer_generations_dir().resolve()
        candidate = (_analyzer_generations_dir() / generation).resolve()
        candidate.relative_to(root)
        if _valid_analyzer_generation(candidate):
            return candidate
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        pass
    recovered = _recover_latest_analyzer_generation()
    if recovered is not None:
        return recovered
    return None


def _prune_analyzer_generations(active_generation: str, keep: int = 3) -> None:
    """Bound immutable snapshot storage while never deleting the active tree."""
    root = _analyzer_generations_dir()
    try:
        generations = sorted(
            (path for path in root.iterdir() if path.name.startswith("generation-") and path.is_dir()),
            key=lambda path: path.stat().st_mtime_ns,
            reverse=True,
        )
    except OSError:
        return
    retained = {path.name for path in generations[:max(1, keep)]}
    retained.add(active_generation)
    for path in generations:
        if path.name not in retained:
            shutil.rmtree(path, ignore_errors=True)


def _safe_analyzer_bundle_members(archive: zipfile.ZipFile) -> list:
    """Validate a complete read-only analyzer bundle before extracting it."""
    members = []
    expanded = 0
    infos = archive.infolist()
    if len(infos) > _ANALYZER_BUNDLE_MAX_MEMBERS:
        raise ValueError("analyzer bundle contains too many members")
    seen = set()
    for info in infos:
        if info.is_dir():
            continue
        raw_name = str(info.filename or "").replace("\\", "/")
        parts = [part for part in raw_name.split("/") if part]
        if (
            not parts
            or raw_name.startswith("/")
            or any(part in (".", "..") for part in parts)
            or ":" in parts[0]
        ):
            raise ValueError("analyzer bundle contains an unsafe path")
        rel = Path(*parts)
        normalized = str(rel).replace("\\", "/")
        collision_key = normalized.casefold()
        if collision_key in seen:
            raise ValueError(f"analyzer bundle contains a duplicate path: {raw_name}")
        seen.add(collision_key)
        if rel.suffix.lower() not in _ANALYZER_BUNDLE_ALLOWED_SUFFIXES:
            raise ValueError(f"analyzer bundle contains an unsupported file: {raw_name}")
        # Unix symlinks are not report files and could escape the mirror root.
        unix_mode = (int(info.external_attr) >> 16) & 0o170000
        if unix_mode == 0o120000:
            raise ValueError("analyzer bundle contains a symbolic link")
        member_size = int(info.file_size or 0)
        compressed_size = int(info.compress_size or 0)
        if member_size > _ANALYZER_BUNDLE_MAX_MEMBER_BYTES:
            raise ValueError(f"analyzer bundle member exceeds 50 MB: {raw_name}")
        if normalized == _ANALYZER_BUNDLE_MANIFEST and member_size > 2 * 1024 * 1024:
            raise ValueError("analyzer bundle manifest exceeds 2 MB")
        if (
            member_size > 1024 * 1024
            and compressed_size > 0
            and member_size / compressed_size > _ANALYZER_BUNDLE_MAX_COMPRESSION_RATIO
        ):
            raise ValueError(f"analyzer bundle member has an unsafe compression ratio: {raw_name}")
        expanded += member_size
        if expanded > _ANALYZER_BUNDLE_MAX_EXPANDED_BYTES:
            raise ValueError("analyzer bundle expands beyond the 150 MB limit")
        members.append((info, rel))
    paths = {str(rel).replace("\\", "/") for _, rel in members}
    if _ANALYZER_BUNDLE_MANIFEST not in paths:
        raise ValueError(f"analyzer bundle is missing {_ANALYZER_BUNDLE_MANIFEST}")
    return members


def _validated_analyzer_bundle_manifest(archive: zipfile.ZipFile, members: list) -> dict:
    """Require an exact, hash-bound set of files from one analyzer run."""
    try:
        manifest = json.loads(archive.read(_ANALYZER_BUNDLE_MANIFEST).decode("utf-8"))
    except (KeyError, UnicodeDecodeError, ValueError, TypeError) as exc:
        raise ValueError(f"invalid analyzer bundle manifest: {exc}") from exc
    if manifest.get("schema") != _ANALYZER_BUNDLE_SCHEMA:
        raise ValueError("unsupported analyzer bundle schema")
    required_text = (
        "snapshot_id", "analyzer_run_id", "analyzer_generated_at",
        "source_data_revision", "analyzer_generation_revision",
        "analyzer_version", "cohort_schema", "data_scope",
        "source_report_manifest_sha256",
    )
    if any(not str(manifest.get(key) or "").strip() for key in required_text):
        raise ValueError("analyzer bundle provenance is incomplete")
    rows = manifest.get("files")
    if not isinstance(rows, list) or not rows:
        raise ValueError("analyzer bundle manifest has no files")
    declared = {}
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("analyzer bundle manifest contains an invalid file row")
        path = str(row.get("path") or "").replace("\\", "/")
        key = path.casefold()
        if not path or key in declared:
            raise ValueError("analyzer bundle manifest contains a duplicate or empty file path")
        digest = str(row.get("sha256") or "").lower()
        if not re.fullmatch(r"[0-9a-f]{64}", digest):
            raise ValueError(f"analyzer bundle manifest has an invalid hash: {path}")
        try:
            size = int(row.get("size_bytes"))
        except (TypeError, ValueError) as exc:
            raise ValueError(f"analyzer bundle manifest has an invalid size: {path}") from exc
        if size < 0 or size > _ANALYZER_BUNDLE_MAX_MEMBER_BYTES:
            raise ValueError(f"analyzer bundle manifest size is out of bounds: {path}")
        declared[key] = {"path": path, "sha256": digest, "size_bytes": size}
    actual = {
        str(rel).replace("\\", "/").casefold()
        for _, rel in members
        if str(rel).replace("\\", "/") != _ANALYZER_BUNDLE_MANIFEST
    }
    if actual != set(declared):
        raise ValueError("analyzer bundle membership does not exactly match its manifest")
    if "analysis_dashboard.html" not in {row["path"] for row in declared.values()}:
        raise ValueError("analyzer bundle is missing analysis_dashboard.html")
    for revision_key in ("source_data_revision", "analyzer_generation_revision"):
        if not re.fullmatch(r"[0-9a-fA-F]{7,64}", str(manifest[revision_key])):
            raise ValueError(f"analyzer bundle has an invalid {revision_key}")
    try:
        datetime.fromisoformat(str(manifest["analyzer_generated_at"]).replace("Z", "+00:00"))
    except ValueError as exc:
        raise ValueError("analyzer bundle has an invalid analyzer_generated_at") from exc
    try:
        report_payload = archive.read("report_manifest.json")
        report_manifest = json.loads(report_payload.decode("utf-8"))
    except (KeyError, UnicodeDecodeError, ValueError, TypeError) as exc:
        raise ValueError(f"invalid source report manifest: {exc}") from exc
    if hashlib.sha256(report_payload).hexdigest() != str(manifest["source_report_manifest_sha256"]).lower():
        raise ValueError("source report manifest hash does not match bundle provenance")
    provenance = report_manifest.get("analysis_provenance") or {}
    comparisons = {
        "analyzer_run_id": report_manifest.get("analyzer_sync_id"),
        "analyzer_version": report_manifest.get("analyzer_version"),
        "analyzer_generated_at": report_manifest.get("generated_at"),
        "data_scope": report_manifest.get("data_scope"),
        "cohort_schema": provenance.get("cohort_schema"),
        "analyzer_generation_revision": provenance.get("generation_revision"),
    }
    if any(str(manifest.get(key)) != str(value) for key, value in comparisons.items()):
        raise ValueError("bundle provenance does not match the source report manifest")
    expected_paths = {"report_manifest.json"}
    for raw_path in report_manifest.get("text_artifacts") or []:
        path = str(raw_path or "")
        if not path or path != Path(path).name:
            raise ValueError("source report manifest contains an unsafe text artifact path")
        expected_paths.add(path)
    reports = report_manifest.get("reports") or []
    try:
        report_count = int(report_manifest.get("report_count"))
    except (TypeError, ValueError) as exc:
        raise ValueError("source report manifest has an invalid report_count") from exc
    if len(reports) != report_count:
        raise ValueError("source report manifest report_count does not match its reports")
    for row in reports:
        path = str((row or {}).get("file") or "")
        if not path or path != Path(path).name:
            raise ValueError("source report manifest contains an unsafe report path")
        expected_paths.add(f"reports/{path}")
    if expected_paths != {row["path"] for row in declared.values()}:
        raise ValueError("bundle files do not exactly match the source report manifest")
    return manifest


def _install_analyzer_bundle(payload: bytes, meta: dict) -> dict:
    """Install an immutable generation, then atomically select it."""
    generations = _analyzer_generations_dir()
    generations.mkdir(parents=True, exist_ok=True)
    nonce = f"{os.getpid()}-{time.time_ns()}"
    staging = generations / f".staging-{nonce}"
    pointer_tmp = _analyzer_current_pointer_path().with_name(f"analyzer_current.{nonce}.tmp")
    with _ANALYZER_INSTALL_LOCK:
        try:
            with zipfile.ZipFile(io.BytesIO(payload), "r") as archive:
                members = _safe_analyzer_bundle_members(archive)
                manifest = _validated_analyzer_bundle_manifest(archive, members)
                staging.mkdir(parents=True, exist_ok=False)
                declared = {
                    str(row["path"]).replace("\\", "/").casefold(): row
                    for row in manifest["files"]
                }
                extracted = 0
                for info, rel in members:
                    rel_text = str(rel).replace("\\", "/")
                    target = staging / rel
                    target.parent.mkdir(parents=True, exist_ok=True)
                    digest = hashlib.sha256()
                    actual_size = 0
                    with archive.open(info, "r") as source, open(target, "wb") as destination:
                        while True:
                            chunk = source.read(1024 * 1024)
                            if not chunk:
                                break
                            actual_size += len(chunk)
                            if actual_size > _ANALYZER_BUNDLE_MAX_MEMBER_BYTES:
                                raise ValueError(f"analyzer bundle member exceeds limit: {rel_text}")
                            digest.update(chunk)
                            destination.write(chunk)
                    if rel_text != _ANALYZER_BUNDLE_MANIFEST:
                        expected = declared[rel_text.casefold()]
                        if (
                            actual_size != int(expected["size_bytes"])
                            or digest.hexdigest() != expected["sha256"]
                        ):
                            raise ValueError(f"analyzer bundle file integrity mismatch: {rel_text}")
                    extracted += 1
            bundle_sha = hashlib.sha256(payload).hexdigest()
            generation = f"generation-{bundle_sha[:20]}-{time.time_ns()}"
            final_dir = generations / generation
            status = {
                **meta,
                **{key: value for key, value in manifest.items() if key != "files"},
                "schema": _ANALYZER_BUNDLE_SCHEMA,
                "complete": True,
                "file_count": extracted - 1,
                "bundle_sha256": bundle_sha,
                "generation": generation,
            }
            (staging / "status.json").write_text(
                json.dumps(status, separators=(",", ":")), encoding="utf-8"
            )
            os.replace(staging, final_dir)
            pointer_tmp.write_text(
                json.dumps(
                    {"schema": "analyzer_current_v1", "generation": generation},
                    separators=(",", ":"),
                ),
                encoding="utf-8",
            )
            os.replace(pointer_tmp, _analyzer_current_pointer_path())
            _prune_analyzer_generations(generation)
            return status
        finally:
            shutil.rmtree(staging, ignore_errors=True)
            try:
                pointer_tmp.unlink()
            except FileNotFoundError:
                pass


@app.route('/api/data-sync/analyzer-report', methods=['POST'])
def api_data_sync_analyzer_report():
    if (
        request.content_length
        and request.content_length > _ANALYZER_BUNDLE_MAX_COMPRESSED_BYTES + 1024 * 1024
    ):
        return jsonify({"error": "analyzer upload request exceeds 51 MB"}), 413
    bundle = request.files.get("bundle")
    if bundle is not None:
        payload = bundle.read(_ANALYZER_BUNDLE_MAX_COMPRESSED_BYTES + 1)
        if len(payload) > _ANALYZER_BUNDLE_MAX_COMPRESSED_BYTES:
            return jsonify({"error": "analyzer bundle exceeds 50 MB"}), 413
        meta = {
            "uploaded_at": utc_iso(),
            "size": len(payload),
        }
        try:
            installed = _install_analyzer_bundle(payload, meta)
        except (OSError, RuntimeError, ValueError, zipfile.BadZipFile) as exc:
            return jsonify({"error": f"invalid analyzer bundle: {exc}"}), 400
        return jsonify({"ok": True, **installed})

    # The retired HTML-only publisher produced dashboards with broken report
    # links. Existing files remain untouched for forensic review, but new
    # legacy publications are rejected and can never become active.
    upload = request.files.get("report")
    if upload is None:
        return jsonify({"error": "multipart field 'report' is required"}), 400
    return jsonify({
        "error": "HTML-only analyzer publication is retired",
        "required_schema": _ANALYZER_BUNDLE_SCHEMA,
        "legacy_data_preserved": True,
    }), 410


@app.route('/api/analyzer-mirror/status')
def api_analyzer_mirror_status():
    active = _active_analyzer_mirror_dir()
    if active is None:
        legacy_preserved = _analyzer_mirror_dir().exists()
        return jsonify({
            "available": False,
            "reason": "no complete validated analyzer bundle is installed",
            "required_schema": _ANALYZER_BUNDLE_SCHEMA,
            "legacy_data_preserved": legacy_preserved,
        }), 404
    try:
        payload = json.loads(
            (active / "status.json").read_text(encoding="utf-8")
        )
        resp = jsonify({"available": True, **payload})
        resp.headers['Cache-Control'] = 'no-store'
        return resp
    except (OSError, ValueError, TypeError):
        return jsonify({"available": False, "reason": "no local analyzer report uploaded yet"}), 404


@app.route('/analysis')
def analyzer_mirror_dashboard():
    if not _analyzer_view_authed():
        resp = make_response('', 303)
        resp.headers['Location'] = '/analysis/login'
        resp.headers['Cache-Control'] = 'no-store'
        return resp
    resp = make_response('', 308)
    resp.headers['Location'] = '/analysis/'
    resp.headers['Cache-Control'] = 'no-store'
    return resp


@app.route('/analysis/')
def analyzer_mirror_dashboard_index():
    if not _analyzer_view_authed():
        resp = make_response('', 303)
        resp.headers['Location'] = '/analysis/login'
        resp.headers['Cache-Control'] = 'no-store'
        return resp
    active = _active_analyzer_mirror_dir()
    if active is None:
        return jsonify({
            "error": "no complete validated analyzer bundle is available",
            "next": "run the bundle-v2 local analyzer publisher while the PC is online",
        }), 503
    report = active / "analysis_dashboard.html"
    if not report.is_file():
        return jsonify({
            "error": "no analyzer mirror is available yet",
            "next": "run the local sync/analyzer publisher while the PC is online",
        }), 404
    resp = make_response(send_file(report, mimetype="text/html"))
    resp.headers['Cache-Control'] = 'no-store'
    resp.headers['X-Content-Type-Options'] = 'nosniff'
    resp.headers['X-Frame-Options'] = 'DENY'
    resp.headers['Referrer-Policy'] = 'no-referrer'
    resp.headers['Content-Security-Policy'] = "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
    return resp


@app.route('/analysis/<path:artifact_path>')
def analyzer_mirror_artifact(artifact_path):
    if not _analyzer_view_authed():
        resp = make_response('', 303)
        resp.headers['Location'] = '/analysis/login'
        resp.headers['Cache-Control'] = 'no-store'
        return resp
    active = _active_analyzer_mirror_dir()
    if active is None:
        return jsonify({
            "error": "no complete validated analyzer bundle is available",
        }), 503
    mirror = active.resolve()
    normalized = str(artifact_path or "").replace("\\", "/")
    target = (mirror / normalized).resolve()
    try:
        target.relative_to(mirror)
    except ValueError:
        return jsonify({"error": "invalid analyzer artifact path"}), 400
    if target.suffix.lower() not in _ANALYZER_BUNDLE_ALLOWED_SUFFIXES or not target.is_file():
        return jsonify({"error": "analyzer artifact not found"}), 404
    mimetype = {
        ".html": "text/html",
        ".txt": "text/plain",
        ".json": "application/json",
        ".log": "text/plain",
    }.get(target.suffix.lower(), "application/octet-stream")
    resp = make_response(send_file(target, mimetype=mimetype))
    resp.headers['Cache-Control'] = 'no-store'
    resp.headers['X-Content-Type-Options'] = 'nosniff'
    resp.headers['X-Frame-Options'] = 'DENY'
    resp.headers['Referrer-Policy'] = 'no-referrer'
    resp.headers['Content-Security-Policy'] = "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
    return resp


@app.route('/analysis/login', methods=['GET', 'POST'])
def analyzer_mirror_login():
    """Mobile-friendly, read-only analyzer authentication.

    The owner token is accepted only in a POST body and exchanged for a
    derived HttpOnly cookie which is deliberately ignored by every mutation
    endpoint.
    """
    if request.method == 'GET':
        return render_template_string("""
<!doctype html>
<html lang="en"><head>
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>BTC Analyzer Access</title>
  <style>
    body{background:#0b0f14;color:#e5e7eb;font-family:system-ui;margin:0;padding:32px 18px}
    main{max-width:420px;margin:12vh auto;background:#111827;padding:24px;border-radius:14px}
    input,button{box-sizing:border-box;width:100%;padding:13px;margin-top:12px;border-radius:8px}
    input{background:#030712;color:#fff;border:1px solid #374151}
    button{background:#2563eb;color:#fff;border:0;font-weight:700}
    p{color:#9ca3af;line-height:1.45}
  </style>
</head><body><main>
  <h2>Read-only analyzer</h2>
  <p>Enter the owner token once. This creates an analyzer-only session; it cannot change trading settings or place orders.</p>
  <form method="post" action="/analysis/login" autocomplete="on">
    <label for="analyzerUsername">Account</label>
    <input id="analyzerUsername" name="username" type="text" value="bot-analyzer" readonly autocomplete="username">
    <label for="analyzerToken">Owner token</label>
    <input id="analyzerToken" name="token" type="password" required autofocus placeholder="Owner token" autocomplete="current-password">
    <button type="submit">Open analyzer</button>
  </form>
</main></body></html>
        """), 200, {'Cache-Control': 'no-store'}

    token = request.form.get('token', '')
    if not _BOT_ADMIN_TOKEN or not hmac.compare_digest(token, _BOT_ADMIN_TOKEN):
        return 'Invalid owner token', 401, {'Cache-Control': 'no-store'}

    resp = make_response('', 303)
    resp.headers['Location'] = '/analysis/'
    forwarded_proto = (request.headers.get('X-Forwarded-Proto') or '').split(',')[0].strip().lower()
    secure = bool(request.is_secure or forwarded_proto == 'https')
    resp.set_cookie(
        'analyzer_view_session', _analyzer_view_cookie_value(),
        httponly=True, samesite='Lax', path='/analysis',
        max_age=60 * 60 * 24 * 30, secure=secure,
    )
    resp.headers['Cache-Control'] = 'no-store'
    return resp


@app.route('/analysis/logout', methods=['POST'])
def analyzer_mirror_logout():
    resp = make_response('', 303)
    resp.headers['Location'] = '/analysis/login'
    forwarded_proto = (request.headers.get('X-Forwarded-Proto') or '').split(',')[0].strip().lower()
    secure = bool(request.is_secure or forwarded_proto == 'https')
    resp.delete_cookie(
        'analyzer_view_session', httponly=True, samesite='Lax',
        path='/analysis', secure=secure,
    )
    resp.headers['Cache-Control'] = 'no-store'
    return resp


def _read_log_tail(path, max_lines=400, max_bytes=262144):
    if not path or not os.path.exists(path):
        return ""
    try:
        # The persistent Fly log is capped at 50 MiB. readlines() used to
        # allocate Python objects for the entire file on every debug export,
        # starving the one-vCPU control plane for tens of seconds. Read only a
        # bounded suffix and discard its first partial line.
        size = os.path.getsize(path)
        start = max(0, size - max(1, int(max_bytes)))
        with open(path, "rb") as f:
            f.seek(start)
            payload = f.read()
        if start and b"\n" in payload:
            payload = payload.split(b"\n", 1)[1]
        lines = payload.splitlines(keepends=True)
        return b"".join(lines[-max(1, int(max_lines)):]).decode(
            "utf-8", errors="replace"
        )
    except Exception:
        return ""

DEBUG_EXPORT_LOG_MAX = 1500

@app.route('/api/export_debug')
def export_debug():
    try:
        buf = io.BytesIO()
        with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as z:
            debug_data = list(DEBUG_LOG_BUFFER)[-DEBUG_EXPORT_LOG_MAX:]

            def _safe_zip_json(arcname, payload):
                try:
                    z.writestr(arcname, json.dumps(payload, default=str, separators=(',', ':')))
                except Exception as ex:
                    logger.warning(f"[EXPORT] skip {arcname}: {ex}")

            _safe_zip_json("debug.json", debug_data)
            errors_only = [e for e in debug_data if e.get("ai_error") or (e.get("data") or {}).get("ai", {}).get("ai_error")]
            _safe_zip_json("debug_ai_errors.json", errors_only)
            with state_lock:
                snap = {
                    "debug_state": dict(state.get("debug_state") or {}),
                    "last_edge": state.get("last_edge"),
                    "pipeline_outcome": state.get("pipeline_outcome"),
                    "ai_call_count": state.get("ai_call_count"),
                    "last_ai": dict(state.get("last_ai") or {}),
                }
            _safe_zip_json("debug_state_snapshot.json", snap)
            try:
                log_tail = _read_log_tail(os.getenv("BOT_LOG_FILE", "bot_runtime.log"))
                if log_tail:
                    z.writestr("bot_runtime_tail.log", log_tail)
            except Exception as ex:
                logger.warning(f"[EXPORT] skip bot_runtime_tail.log: {ex}")
            for csv_name in [CSV_PIPELINE_EVENTS, CSV_AI_ERRORS, CSV_DECISIONS, CSV_AI_TRANCHE]:
                if os.path.exists(csv_name):
                    try:
                        z.write(csv_name, arcname=csv_name)
                    except Exception as ex:
                        logger.warning(f"[EXPORT] skip {csv_name}: {ex}")
        payload = buf.getvalue()
        resp = send_file(
            io.BytesIO(payload),
            mimetype='application/zip',
            as_attachment=True,
            download_name='debug_export.zip',
        )
        resp.headers["Content-Length"] = str(len(payload))
        return resp
    except Exception as e:
        logger.error(f"[EXPORT ERROR] {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500

