_RESEARCH_EXPORT_MAX_ARCHIVE_BYTES = 64 * 1024 * 1024
_RESEARCH_EXPORT_MIN_FREE_BYTES = 256 * 1024 * 1024
_RESEARCH_EXPORT_BUILD_TIMEOUT_SEC = 20.0
_RESEARCH_EXPORT_COPY_CHUNK_BYTES = 256 * 1024
_RESEARCH_EXPORT_BUILD_LOCK = threading.Lock()
_RESEARCH_EXPORT_MANIFEST_NAME = "EXPORT_MANIFEST.json"


class _ResearchExportTooLarge(RuntimeError):
    pass


class _ResearchExportUnavailable(RuntimeError):
    pass


class _BoundedResearchArchiveWriter:
    """File proxy that refuses to let ZipFile grow beyond the export cap."""

    def __init__(self, raw_file, *, max_bytes, deadline):
        self._raw_file = raw_file
        self._max_bytes = int(max_bytes)
        self._deadline = float(deadline)
        self._high_water = 0

    def write(self, data):
        if time.monotonic() > self._deadline:
            raise _ResearchExportUnavailable("archive build deadline exceeded")
        end_position = max(self._high_water, self._raw_file.tell() + len(data))
        if end_position > self._max_bytes:
            raise _ResearchExportTooLarge("archive output exceeds small-export limit")
        written = self._raw_file.write(data)
        self._high_water = max(self._high_water, self._raw_file.tell())
        return written

    def __getattr__(self, name):
        return getattr(self._raw_file, name)


def _research_export_members():
    """Return existing allowlisted files rooted inside the runtime data directory."""
    data_root = Path.cwd().resolve()
    members = []
    omitted_optional = []
    seen_arcnames = {_RESEARCH_EXPORT_MANIFEST_NAME}
    total_source_bytes = 0
    try:
        configured_paths = dict.fromkeys(research_export_files())
    except (TypeError, ValueError) as exc:
        raise _ResearchExportUnavailable("invalid research export allowlist") from exc
    for configured_path in configured_paths:
        try:
            candidate = Path(configured_path)
            source_path = (candidate if candidate.is_absolute() else data_root / candidate).resolve()
            relative_name = source_path.relative_to(data_root).as_posix()
        except (OSError, TypeError, ValueError) as exc:
            raise _ResearchExportUnavailable("unsafe research export member path") from exc
        if not source_path.exists():
            omitted_optional.append(relative_name)
            continue
        if not source_path.is_file():
            raise _ResearchExportUnavailable("research export member is not a regular file")
        arcname = source_path.name
        if arcname in seen_arcnames:
            raise _ResearchExportUnavailable("conflicting research export member names")
        try:
            source_bytes = source_path.stat().st_size
        except OSError as exc:
            raise _ResearchExportUnavailable("research export member cannot be inspected") from exc
        total_source_bytes += source_bytes
        if total_source_bytes > _RESEARCH_EXPORT_MAX_SOURCE_BYTES:
            raise _ResearchExportTooLarge("research export source exceeds small-export limit")
        seen_arcnames.add(arcname)
        members.append((source_path, arcname, source_bytes))
    return members, omitted_optional, total_source_bytes


def _research_export_manifest(members, omitted_optional):
    """Describe this convenience bundle without claiming canonical evidence coverage."""
    return {
        "schema": "bounded_research_export_manifest_v1",
        "scope": "diagnostic_convenience_existing_files_only",
        "canonical_mirror_ack_evidence": False,
        "complete_research_coverage": False,
        "generated_members": [_RESEARCH_EXPORT_MANIFEST_NAME],
        "included_members": [arcname for _, arcname, _ in members],
        "omitted_optional_absent": list(omitted_optional),
    }


def _research_export_error(status_code):
    if status_code == 413:
        payload = {
            "error": "research export exceeds the bounded HTTP download limit",
            "action": "use the verified research sync for large exports",
        }
    else:
        payload = {
            "error": "research export temporarily unavailable",
            "action": "retry later or use the verified research sync",
        }
    response = jsonify(payload)
    response.status_code = status_code
    response.headers["Cache-Control"] = "no-store"
    response.headers["X-Content-Type-Options"] = "nosniff"
    if status_code == 503:
        response.headers["Retry-After"] = "60"
    return response


@app.route('/api/export_csv')
@app.route('/api/export.csv')
def export_csv():
    build_lock_acquired = _RESEARCH_EXPORT_BUILD_LOCK.acquire(blocking=False)
    if not build_lock_acquired:
        return _research_export_error(503)
    zip_buffer = None
    try:
        members, omitted_optional, _ = _research_export_members()
        if not members:
            raise _ResearchExportUnavailable("no research export data files are available")
        temp_root = Path(tempfile.gettempdir())
        try:
            free_bytes = shutil.disk_usage(temp_root).free
        except OSError as exc:
            raise _ResearchExportUnavailable("temporary storage cannot be inspected") from exc
        required_free_bytes = (
            _RESEARCH_EXPORT_MIN_FREE_BYTES + _RESEARCH_EXPORT_MAX_ARCHIVE_BYTES
        )
        if free_bytes < required_free_bytes:
            raise _ResearchExportUnavailable("insufficient temporary storage reserve")

        deadline = time.monotonic() + _RESEARCH_EXPORT_BUILD_TIMEOUT_SEC
        zip_buffer = tempfile.TemporaryFile(mode="w+b", dir=temp_root)
        bounded_writer = _BoundedResearchArchiveWriter(
            zip_buffer,
            max_bytes=_RESEARCH_EXPORT_MAX_ARCHIVE_BYTES,
            deadline=deadline,
        )
        copied_source_bytes = 0
        with zipfile.ZipFile(bounded_writer, "w", zipfile.ZIP_DEFLATED) as zip_file:
            zip_file.writestr(
                _RESEARCH_EXPORT_MANIFEST_NAME,
                json.dumps(
                    _research_export_manifest(members, omitted_optional),
                    sort_keys=True,
                    separators=(",", ":"),
                ),
            )
            # Include both legacy 3-factor files and the authoritative per-lane
            # research lifecycle. The old export omitted these newer files, so a
            # downloaded ZIP could show replay buffers but could not prove whether
            # Current lane filled, expired, closed, or remained counterfactual.
            for source_path, arcname, _ in members:
                try:
                    with source_path.open("rb") as source, zip_file.open(arcname, "w") as target:
                        while True:
                            if time.monotonic() > deadline:
                                raise _ResearchExportUnavailable("archive build deadline exceeded")
                            chunk = source.read(_RESEARCH_EXPORT_COPY_CHUNK_BYTES)
                            if not chunk:
                                break
                            copied_source_bytes += len(chunk)
                            if copied_source_bytes > _RESEARCH_EXPORT_MAX_SOURCE_BYTES:
                                raise _ResearchExportTooLarge(
                                    "research export source exceeds small-export limit"
                                )
                            target.write(chunk)
                except (_ResearchExportTooLarge, _ResearchExportUnavailable):
                    raise
                except OSError as exc:
                    raise _ResearchExportUnavailable(
                        "research export member could not be copied"
                    ) from exc
        content_length = zip_buffer.tell()
        zip_buffer.seek(0)
        _RESEARCH_EXPORT_BUILD_LOCK.release()
        build_lock_acquired = False
        response = send_file(
            zip_buffer,
            mimetype="application/zip",
            as_attachment=True,
            download_name="3factor_logs.zip",
            conditional=False,
        )
        response.headers["Content-Length"] = str(content_length)
        response.headers["Cache-Control"] = "no-store"
        response.headers["X-Content-Type-Options"] = "nosniff"
        response.call_on_close(zip_buffer.close)
        return response
    except _ResearchExportTooLarge:
        if zip_buffer is not None:
            zip_buffer.close()
        if build_lock_acquired:
            _RESEARCH_EXPORT_BUILD_LOCK.release()
        logger.warning("[EXPORT] bounded HTTP research export rejected as too large")
        return _research_export_error(413)
    except _ResearchExportUnavailable:
        if zip_buffer is not None:
            zip_buffer.close()
        if build_lock_acquired:
            _RESEARCH_EXPORT_BUILD_LOCK.release()
        logger.warning("[EXPORT] bounded HTTP research export unavailable", exc_info=True)
        return _research_export_error(503)
    except Exception:
        if zip_buffer is not None:
            zip_buffer.close()
        if build_lock_acquired:
            _RESEARCH_EXPORT_BUILD_LOCK.release()
        logger.error("[EXPORT ERROR] failed to build bounded research archive", exc_info=True)
        return _research_export_error(503)

def _capture_runtime_quantity_constraints(
    *, evidence_symbol=None, source_revision=None, requested_qty=None,
) -> dict:
    """Bitfinex public pair bounds (cached, unauthenticated); never invent or round up."""
    try:
        return capture_public_pair_constraints(
            evidence_symbol=evidence_symbol or BITFINEX_WS_SYMBOL,
            captured_at=utc_iso(),
            source_revision=source_revision or _runtime_git_rev(),
            requested_qty=requested_qty,
        )
    except Exception as exc:
        logger.warning(
            f"[QUANTITY CONSTRAINTS] unsupported capture: {type(exc).__name__} "
            "[PIPELINE ENFORCEMENT]"
        )
        return {
            "supported": False,
            "receipt": None,
            "reasons": ["VENUE_QUANTITY_CONSTRAINT_CAPTURE_FAILED"],
        }


def calc_position_qty(price, leverage, margin_usdt=None):
    try:
        if price is None or price <= 0 or leverage is None:
            logger.error(f"[QTY CALC FAIL] price={price} leverage={leverage}")
            return 0.0
        market = bitfinex_public.market(SYMBOL_CCXT)
        min_qty = market.get("limits", {}).get("amount", {}).get("min", 0.001)
        min_notional = market.get("limits", {}).get("cost", {}).get("min", 5.0)
        fee_buffer = 1 - (MAKER_FEE_PCT + TAKER_FEE_PCT)
        requested_notional = (
            float(FIXED_MARGIN_USDT if margin_usdt is None else margin_usdt)
            * float(leverage or DEFAULT_RESEARCH_LEVERAGE)
            * fee_buffer
        )
        # Live-copy safety contract: never make a requested small test larger
        # merely to satisfy the venue.  The previous helper silently promoted
        # both notional and quantity to Bitfinex minima, contradicting the
        # operator's $0.20-$0.25 / 100x cap.  A venue-incompatible request must
        # fail closed and remain paper/shadow evidence only.
        if requested_notional <= 0 or requested_notional < float(min_notional or 0):
            logger.error(
                "[QTY CALC BLOCK] requested_notional=%.8f below venue_min_notional=%s",
                requested_notional,
                min_notional,
            )
            return 0.0
        raw_qty = requested_notional / float(price)
        if raw_qty < float(min_qty or 0):
            logger.error(
                "[QTY CALC BLOCK] requested_qty=%.12f below venue_min_qty=%s",
                raw_qty,
                min_qty,
            )
            return 0.0
        qty = float(bitfinex_public.amount_to_precision(SYMBOL_CCXT, raw_qty))
        if qty <= 0 or qty < float(min_qty or 0):
            return 0.0
        accepted_notional = qty * float(price)
        if accepted_notional > requested_notional + 1e-8:
            logger.error(
                "[QTY CALC BLOCK] precision increased notional requested=%.8f accepted=%.8f",
                requested_notional,
                accepted_notional,
            )
            return 0.0
        return qty
    except Exception as e:
        logger.error(f"Qty calc failed: {e}")
        return 0.0

def utc_iso(dt=None):
    if dt is None:
        dt = datetime.now(timezone.utc)
    return dt.isoformat()

def shutdown_handler(signum, frame):
    if shutdown_event.is_set():
        return
    logger.warning(f"[SHUTDOWN] Signal received: {signum}")
    shutdown_event.set()
    drained = _shutdown_pending_order_evidence_worker(timeout=5.0)
    logger.warning(f"[SHUTDOWN] Pending-order evidence drained={drained}")
    cancellation_drained = _shutdown_cancellation_evidence_worker(timeout=5.0)
    logger.warning(f"[SHUTDOWN] Cancellation evidence drained={cancellation_drained}")
    fill_evidence_drained = _shutdown_fill_evidence_worker(timeout=5.0)
    logger.warning(f"[SHUTDOWN] Fill evidence drained={fill_evidence_drained}")
    preentry_drained = _shutdown_preentry_evidence_worker(timeout=5.0)
    logger.warning(f"[SHUTDOWN] Pre-entry evidence drained={preentry_drained}")
    post_ai_drained = _shutdown_post_ai_evidence_workers(timeout=2.0)
    logger.warning(f"[SHUTDOWN] Post-AI evidence drained={post_ai_drained}")
    combo_drained = _shutdown_combo_lane_execution_workers(timeout=5.0)
    logger.warning(f"[SHUTDOWN] Combo-lane execution drained={combo_drained}")
    lifecycle_stopped = _stop_lifecycle_pipeline_runtime(timeout=5.0)
    logger.warning(f"[SHUTDOWN] Lifecycle pipeline stopped={lifecycle_stopped}")
    logger.warning("[SHUTDOWN] Controlled shutdown initiated")

signal.signal(signal.SIGINT, shutdown_handler)
signal.signal(signal.SIGTERM, shutdown_handler)

def ema(values, period):
    if len(values) < period:
        return None
    if any(math.isnan(v) for v in values):
        return None
    sma = sum(values[:period]) / period
    k = 2 / (period + 1)
    ema_val = sma
    for v in values[period:]:
        ema_val = v * k + ema_val * (1 - k)
    return ema_val

def fetch_ohlcv():
    global latest_candles, last_candle_ts, last_ohlcv_fetch
    if time.time() - last_ohlcv_fetch < OHLCV_FETCH_INTERVAL:
        return True
    for attempt in range(5):
        try:
            candles = fetch_bitfinex_ohlcv("15m", limit=250)
            if candles and len(candles) >= MIN_CANDLES:
                with state_lock:
                    latest_candles = candles[-250:]
                    last_candle_ts = candles[-1][0] / 1000 if candles else time.time()
                    state["last_data_ts"] = time.time()
                    state["ohlcv_ready"] = True
                    state["data_error"] = None
                populate_candle_buffers_from_candles(latest_candles)
                last_ohlcv_fetch = time.time()
                update_ema()
                trend_info()
                update_market_context(force=True)
                with state_lock:
                    state.update({"last_fetch_success": utc_iso()})
                    state.update({"data_source": "bitfinex_rest"})
                return True
        except Exception as e:
            logger.warning(f"[OHLCV RETRY {attempt+1}/5] {e}")
            time.sleep(2)
    with state_lock:
        state["ohlcv_ready"] = False
        state["data_error"] = "OHLCV_FETCH_FAILED"
    logger.critical("[STARTUP] PRELOAD FAILED - SYSTEM HALTED")
    set_execution_paused("PRELOAD_FAILED")
    raise RuntimeError("No candles available — cannot continue")

def update_ema():
    with state_lock:
        closes = [c[4] for c in latest_candles]
    if len(closes) < EMA_LONG:
        return
    ema9_val = ema(closes, EMA_FAST)
    ema21_val = ema(closes, EMA_SLOW)
    ema200_val = ema(closes, EMA_LONG)
    if ema9_val is None or ema21_val is None or ema200_val is None:
        return
    ema21_prev = ema(closes[:-3], EMA_SLOW) if len(closes) > EMA_SLOW + 3 else ema21_val
    ema9_prev = ema(closes[:-3], EMA_FAST) if len(closes) > EMA_FAST + 3 else ema9_val
    spread = (ema9_val - ema21_val) / ema21_val if ema21_val else 0.0
    with state_lock:
        state["ema_status"] = {
            "ema9": ema9_val,
            "ema21": ema21_val,
            "ema200": ema200_val,
            "ema_spread": round(spread, 6),
            "ema9_slope_pct": _pct_diff(ema9_val, ema9_prev),
            "ema21_slope_pct": _pct_diff(ema21_val, ema21_prev),
            "ema9_above_ema21": ema9_val > ema21_val,
            "ema21_above_ema200": ema21_val > ema200_val,
        }

def update_support_resistance():
    with state_lock:
        candles_snapshot = copy.deepcopy(latest_candles)
    if not candles_snapshot:
        return
    with state_lock:
        price = state.get("price")
    if price is None or price <= 0:
        return
    highs96 = [c[2] for c in candles_snapshot[-96:]]
    lows96 = [c[3] for c in candles_snapshot[-96:]]
    high_struct = max(highs96)
    low_struct = min(lows96)
    close_struct = candles_snapshot[-2][4] if len(candles_snapshot) >= 2 else 0
    pivot_struct = (high_struct + low_struct + close_struct) / 3
    r1_struct = pivot_struct * 2 - low_struct
    s1_struct = pivot_struct * 2 - high_struct
    highs32 = [c[2] for c in candles_snapshot[-32:]]
    lows32 = [c[3] for c in candles_snapshot[-32:]]
    high_active = max(highs32 + [price]) if price > 0 else max(highs32)
    low_active = min(lows32 + [price]) if price > 0 else min(lows32)
    pivot_active = (high_active + low_active + close_struct) / 3

    swing_high, swing_low = compute_structural_sr(candles_snapshot)
    dist_high, dist_low, near_res, near_sup = sr_context(price, swing_high, swing_low)
    sr_state = classify_sr_state(dist_high, dist_low)
    sr_bias_val = sr_bias(sr_state, state.get("regime", "UNKNOWN"))

    with state_lock:
        state["support_resistance"].update({
            "pivot": pivot_struct,
            "r1": r1_struct,
            "s1": s1_struct,
            "swing_high": swing_high,
            "swing_low": swing_low,
            "dist_to_resistance": dist_high,
            "dist_to_support": dist_low,
            "sr_zone_pct": SR_ZONE_PCT,
            "sr_state": sr_state,
            "sr_bias": sr_bias_val,
            "ts": utc_iso()
        })
        state.update({"pivot_structural": pivot_struct})
        state.update({"pivot_active": pivot_active})

def compute_regime_pressure():
    if len(tick_prices) < 10:
        return 0.0
    diffs = [tick_prices[i+1] - tick_prices[i] for i in range(len(tick_prices)-1)]
    up = sum(1 for d in diffs if d > 0)
    down = sum(1 for d in diffs if d < 0)
    persistence = (up - down) / len(diffs) if len(diffs) else 0
    velocity = (tick_prices[-1] - tick_prices[0]) / tick_prices[0] if tick_prices[0] else 0
    return max(-1.0, min(1.0, 0.7 * persistence + 0.3 * velocity))

def validate_market_data():
    """Validate the one central readiness contract without promoting REST to WS."""
    runtime = _recompute_system_readiness()
    if not runtime["system_ready"]:
        reason = ", ".join(runtime["readiness_reasons"]) or "SYSTEM_NOT_READY"
        with state_lock:
            state["last_engine_error"] = f"Market data invalid: {reason}"
        logger.debug(
            f"[SYSTEM] not ready: Market data invalid: {reason} "
            f"[PIPELINE ENFORCEMENT]"
        )
        return False
    with state_lock:
        state["last_engine_error"] = ""
    return True

def trend_info():
    with state_lock:
        ema9 = state["ema_status"].get("ema9")
        ema21 = state["ema_status"].get("ema21")
        ema200 = state["ema_status"].get("ema200")
    if ema9 is None or ema21 is None or ema200 is None:
        return "UNKNOWN"
    if ema9 > ema200 and ema21 > ema200:
        regime = "BULL"
    elif ema9 < ema200 and ema21 < ema200:
        regime = "BEAR"
    else:
        regime = "RANGE"
    with state_lock:
        state.update({"regime": regime})
    return regime

def reset_session_risk_state():
    """Research: each process start forgets prior session PnL and loss-streak pauses."""
    with state_lock:
        manual_admin_pause = bool(state.get("manual_admin_pause", False))
        state["daily_pnl_usd"] = 0.0
        state["consecutive_losses"] = 0
        state["loss_pause_until"] = 0.0
        # Session-risk state is transient, but the operator's manual pause is
        # persistent and must remain authoritative through the full boot order.
        state["execution_paused"] = manual_admin_pause
        state["execution_reason"] = "ADMIN_MANUAL" if manual_admin_pause else ""
        state["_pause_priority"] = PAUSE_PRIORITIES["ADMIN_MANUAL"] if manual_admin_pause else 0
        state["current_trading_day"] = datetime.now(timezone.utc).date()
    logger.info("[STARTUP] Session risk reset - daily PnL and loss streak cleared [PIPELINE ENFORCEMENT]")

