def _atomic_file_replace(path: str, write_fn, file_lock: threading.RLock, label: str = "FILE") -> bool:
    """Atomic write via per-thread temp file + os.replace with WinError 32 retry."""
    tmp = f"{path}.{os.getpid()}.{threading.get_ident()}.tmp"
    last_err = None
    with file_lock:
        for attempt in range(6):
            try:
                with open(tmp, "w", encoding="utf-8") as f:
                    write_fn(f)
                    f.flush()
                    os.fsync(f.fileno())
                os.replace(tmp, path)
                return True
            except OSError as e:
                last_err = e
                if getattr(e, "winerror", None) == 32 or e.errno in (13, 32, 16):
                    time.sleep(min(0.05 * (2 ** attempt), 1.0))
                    continue
                break
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except OSError:
            pass
    if last_err:
        logger.warning(f"[{label}] atomic write failed after retries: {last_err}")
    return False

def load_positions():
    if not os.path.exists(POSITIONS_FILE):
        return
    with positions_file_lock:
        with open(POSITIONS_FILE, 'r', encoding='utf-8') as f:
            persisted = json.load(f)
    if isinstance(persisted, dict):
        persisted = persisted.get("positions") or []
    if not isinstance(persisted, list):
        logger.warning("[POSITIONS] ignored malformed startup snapshot")
        return
    # A process restart must not silently erase an in-flight paper lifecycle.
    # Fresh-data resets explicitly clear this file, so restoring valid OPEN
    # rows in RESEARCH mode is both crash-safe and consistent with an operator
    # requested wipe.  Preserve identity and never duplicate a row if startup
    # recovery is invoked more than once.
    restored = 0
    with trade_lock:
        known = {
            str(pos.get("trade_id"))
            for pos in open_positions
            if isinstance(pos, dict) and pos.get("trade_id")
        }
        for pos in persisted:
            if (
                not isinstance(pos, dict)
                or pos.get("status") != "OPEN"
                or not pos.get("trade_id")
                or float(pos.get("entry") or 0) <= 0
            ):
                continue
            trade_id = str(pos.get("trade_id"))
            if trade_id in known:
                continue
            lane_register_open_position(pos)
            known.add(trade_id)
            restored += 1
    if restored:
        logger.warning(
            f"[POSITIONS] restored {restored} open lifecycle(s) after restart "
            f"mode={state.get('strategy_mode')} [PIPELINE ENFORCEMENT]"
        )


def _paper_lifecycle_row_valid(row: dict, kind: str) -> bool:
    if not isinstance(row, dict) or not row.get("trade_id"):
        return False
    # Retired-tile rows are restored only so the retirement boundary can
    # cancel/flatten them with a terminal event instead of orphaning them.
    if str(row.get("research_lane") or "").upper() not in {
        *COMBO_EXECUTION_LANES,
        LEGACY_ADOPTION_LANE,
        *_retired_tile_boundary_lanes(),
    }:
        return False
    status = str(row.get("status") or "").upper()
    if kind == "position":
        return status == "OPEN" and float(row.get("entry") or 0) > 0
    return status == "PENDING" and float(row.get("limit_price") or 0) > 0


def _stable_paper_lifecycle_copy(row: dict, attempts: int = 3) -> dict:
    """Copy a live lifecycle row without turning a transient writer race into a crash.

    Position metrics are updated by the market/exit workers at tick frequency.  A
    nested mapping can therefore change while ``deepcopy`` is walking it even
    though the top-level lifecycle list is protected by ``trade_lock``.  Retry a
    bounded number of times and let the caller preserve the last good snapshot
    when the row never becomes stable.
    """
    last_error = None
    for attempt in range(max(1, int(attempts))):
        try:
            return _fast_state_copy(row) if isinstance(row, dict) else {}
        except RuntimeError as exc:
            if "changed size during iteration" not in str(exc).lower():
                raise
            last_error = exc
            if attempt + 1 < max(1, int(attempts)):
                time.sleep(0)
    raise RuntimeError("paper lifecycle row remained mutable during snapshot") from last_error


def _canonicalize_paper_position_snapshot(row: dict) -> dict:
    """Persist the protection fields enforced by the position's frozen policy.

    Patient Chase positions still carry generic Scenario-C-shaped ``tp``/``sl``
    fields created by the shared fill path.  Its exit branch does not enforce
    those values: it uses the frozen 3m ATR target and deliberately has no stop
    in the baseline research lane.  Writing the generic values into the crash
    recovery snapshot makes the persisted lifecycle contradict both runtime
    execution and V3.1 policy identity.  Normalize only the copied snapshot so
    the in-memory accounting object remains untouched.
    """
    snapshot = _stable_paper_lifecycle_copy(row)
    lane = str(snapshot.get("research_lane") or "").upper()
    if not is_patient_chase_lane(lane):
        return snapshot
    protection = _position_protection_view(snapshot)
    snapshot["tp"] = protection["tp"]
    snapshot["atr_tp_price"] = protection["tp"]
    snapshot["tp_policy"] = protection["tp_policy"]
    snapshot["sl"] = protection["sl"]
    snapshot["sl_enforced"] = protection["sl_enforced"]
    snapshot["stop_policy"] = protection["stop_policy"]
    _canonicalize_paper_lifecycle_identity(snapshot)
    return snapshot


def _canonicalize_paper_lifecycle_identity(row: dict) -> dict:
    """Make restored paper identity and sizing fail-closed and self-consistent."""
    if not isinstance(row, dict):
        return {}
    lane = _normalize_lane_key(row)
    row["paper_only"] = True
    row["relay_eligible"] = lane in PLATFORM_RELAY_ELIGIBLE_LANES
    return row


def _v3_matching_order_intent_exists(
    signal: dict,
    *,
    order_intent_identities: set[tuple[str, str]] | None = None,
    ledger_readable: bool = True,
) -> bool:
    """Fail closed when an immutable order intent matches an awaiting snapshot."""
    call_id = str(signal.get("shared_ai_call_id") or signal.get("source_trade_id") or "")
    lane = _normalize_lane_key(signal)
    if not call_id or not lane:
        return True
    if order_intent_identities is not None:
        return (not ledger_readable) or (call_id, lane) in order_intent_identities
    path = Path("v3") / "ledgers" / "order_intent.jsonl"
    if not path.exists():
        return False
    try:
        with path.open("r", encoding="utf-8") as handle:
            for line in handle:
                if not line.strip():
                    continue
                row = json.loads(line)
                if (
                    str(row.get("shared_ai_call_id") or "") == call_id
                    and _normalize_lane_key(row) == lane
                ):
                    return True
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        logger.error(
            f"[PAPER_LIFECYCLE] refusing awaiting recovery because V3 order-intent "
            f"ledger is unreadable: {exc} [PIPELINE ENFORCEMENT]"
        )
        return True
    return False


def _load_v3_order_intent_identities() -> tuple[set[tuple[str, str]], bool]:
    """Read the durable order-intent ledger once for restart reconciliation.

    ``load_paper_lifecycle`` may restore many awaiting signals.  Re-scanning the
    complete JSONL ledger for every signal held ``trade_lock`` for minutes on a
    mature volume, starving the API caches and triggering the runtime watchdog.
    Build the immutable identity index before taking ``trade_lock`` instead.
    The boolean is false when the ledger cannot be read so recovery still fails
    closed rather than replaying an uncertain awaiting signal.
    """
    path = Path("v3") / "ledgers" / "order_intent.jsonl"
    if not path.exists():
        return set(), True
    identities: set[tuple[str, str]] = set()
    try:
        with path.open("r", encoding="utf-8") as handle:
            for line in handle:
                if not line.strip():
                    continue
                row = json.loads(line)
                call_id = str(row.get("shared_ai_call_id") or "")
                lane = _normalize_lane_key(row)
                if call_id and lane:
                    identities.add((call_id, lane))
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        logger.error(
            f"[PAPER_LIFECYCLE] refusing awaiting recovery because V3 order-intent "
            f"ledger is unreadable: {exc} [PIPELINE ENFORCEMENT]"
        )
        return set(), False
    return identities, True


def _build_paper_lifecycle_payload(reason: str = "mutation") -> dict:
    """Capture one internally consistent canonical paper-state generation."""
    try:
        with trade_lock:
            positions = [_canonicalize_paper_position_snapshot(row) for row in open_positions
                         if _paper_lifecycle_row_valid(row, "position") and not row.get("bitfinex_position_id")]
            orders = [_canonicalize_paper_lifecycle_identity(_stable_paper_lifecycle_copy(row)) for row in pending_orders
                      if _paper_lifecycle_row_valid(row, "order") and not row.get("bitfinex_order_id")]
            awaiting_signals = [
                _stable_paper_lifecycle_copy(row.get("signal_ref") or {})
                for row in trades_map.values()
                if isinstance(row, dict)
                and isinstance(row.get("signal_ref"), dict)
                and str((row.get("signal_ref") or {}).get("status") or "").upper()
                in {
                    SIGNAL_STATUS_AWAITING_MICRO,
                    SIGNAL_STATUS_AWAITING_5M,
                    SIGNAL_STATUS_AWAITING_MIN_AGE,
                    SIGNAL_STATUS_AWAITING_CHASE_3PLUS,
                    SIGNAL_STATUS_AWAITING_DASHBOARD_CHASE,
                }
                and not is_terminal_signal(row.get("signal_ref") or {})
                and not (row.get("signal_ref") or {}).get("order_placed")
                and not (row.get("signal_ref") or {}).get("bitfinex_order_id")
            ]
    except RuntimeError:
        raise
    return {
        "schema": "paper_lifecycle_v1", "saved_at": utc_iso(),
        "git_rev": _runtime_git_rev_exact(),
        "reason": reason, "paper_only": bool(_force_paper_mode_active()),
        "live_armed": bool(state.get("live_armed")), "positions": positions,
        "pending_orders": orders, "awaiting_signals": awaiting_signals,
    }


def save_paper_lifecycle(reason: str = "mutation") -> bool:
    """Atomically persist paper state plus pending relay transitions."""
    try:
        with paper_lifecycle_file_lock:
            payload = _relay_event_outbox.decorate_lifecycle(
                _build_paper_lifecycle_payload(reason)
            )
            return _atomic_file_replace(PAPER_LIFECYCLE_FILE,
                lambda f: f.write(json.dumps(payload, default=str, sort_keys=True)),
                paper_lifecycle_file_lock, "PAPER_LIFECYCLE")
    except RuntimeError as exc:
        logger.warning(
            f"[PAPER_LIFECYCLE] snapshot deferred reason={reason} error={exc} "
            "[PIPELINE ENFORCEMENT]"
        )
        return False


def load_paper_lifecycle() -> dict:
    """Idempotently restore all paper positions and pending limits by trade ID."""
    result = {"positions": 0, "pending_orders": 0, "awaiting_signals": 0,
              "overdue_reconciled": 0, "intent_conflicts": 0,
              "duplicates": 0, "invalid": 0}
    if not _relay_event_outbox.healthy:
        logger.error(
            "[PAPER_LIFECYCLE] fail-closed corrupt generation: %s",
            _relay_event_outbox.recovery_error,
        )
        result["invalid"] += 1
        result["relay_recovery_error"] = _relay_event_outbox.recovery_error
        return result
    if not os.path.exists(PAPER_LIFECYCLE_FILE):
        return result
    with paper_lifecycle_file_lock:
        with open(PAPER_LIFECYCLE_FILE, "r", encoding="utf-8") as handle:
            payload = json.load(handle)
    if (not isinstance(payload, dict) or payload.get("schema") != "paper_lifecycle_v1"
            or not payload.get("paper_only") or payload.get("live_armed")):
        logger.error("[PAPER_LIFECYCLE] refused invalid, non-paper, or armed restart snapshot")
        result["invalid"] += 1
        return result
    awaiting_snapshot = payload.get("awaiting_signals") or []
    if awaiting_snapshot:
        order_intent_identities, order_intent_ledger_readable = _load_v3_order_intent_identities()
    else:
        # Pending orders and open positions already carry their durable
        # identity.  The 200+ MB order-intent index is needed only to decide
        # whether a pre-order awaiting signal may be restored.
        order_intent_identities, order_intent_ledger_readable = set(), True
    with trade_lock:
        known_positions = {str(x.get("trade_id")) for x in open_positions if isinstance(x, dict)}
        known_orders = {str(x.get("trade_id")) for x in pending_orders if isinstance(x, dict)}
        for row in payload.get("positions") or []:
            if not _paper_lifecycle_row_valid(row, "position"):
                result["invalid"] += 1; continue
            row = _canonicalize_paper_position_snapshot(row)
            tid = str(row["trade_id"])
            if tid in known_positions or tid in known_orders:
                result["duplicates"] += 1; continue
            lane_register_open_position(row)
            known_positions.add(tid); result["positions"] += 1
        now = time.time()
        for row in payload.get("pending_orders") or []:
            if not _paper_lifecycle_row_valid(row, "order"):
                result["invalid"] += 1; continue
            tid = str(row["trade_id"])
            if tid in known_orders or tid in known_positions:
                result["duplicates"] += 1; continue
            expires = float(row.get("entry_expires_ts") or 0)
            if expires and expires <= now:
                continue
            row = _canonicalize_paper_lifecycle_identity(row)
            row["exchange_submission_blocked"] = True
            lane_register_pending_order(row)
            known_orders.add(tid); result["pending_orders"] += 1
        known_signals = {
            str((entry.get("signal_ref") or {}).get("trade_id"))
            for entry in trades_map.values() if isinstance(entry, dict)
        }
        for raw in awaiting_snapshot:
            if not isinstance(raw, dict) or not raw.get("trade_id"):
                result["invalid"] += 1; continue
            row = _stable_paper_lifecycle_copy(raw)
            tid = str(row["trade_id"])
            status = str(row.get("status") or "").upper()
            if status not in VIRTUAL_CHASE_AWAITING_STATUSES | {
                SIGNAL_STATUS_AWAITING_MICRO,
                SIGNAL_STATUS_AWAITING_5M,
                SIGNAL_STATUS_AWAITING_MIN_AGE,
            } or is_terminal_signal(row) or row.get("order_placed"):
                result["invalid"] += 1; continue
            if tid in known_positions or tid in known_orders or tid in known_signals:
                result["duplicates"] += 1; continue
            if _v3_matching_order_intent_exists(
                row,
                order_intent_identities=order_intent_identities,
                ledger_readable=order_intent_ledger_readable,
            ):
                # A durable submit ledger outranks an older pre-submit snapshot.
                result["intent_conflicts"] += 1; continue
            row["_restart_recovery_provenance"] = {
                "schema": "paper_awaiting_restart_provenance_v1",
                "snapshot_file": PAPER_LIFECYCLE_FILE,
                "snapshot_saved_at": payload.get("saved_at"),
                "snapshot_git_rev": payload.get("git_rev"),
                "restored_at": utc_iso(),
                "restored_git_rev": _runtime_git_rev(),
            }
            trades_map[tid] = {"signal_ref": row, "ai": copy.deepcopy(row.get("ai") or {})}
            known_signals.add(tid); result["awaiting_signals"] += 1
            expires = float(row.get("expires_ts") or 0)
            if expires and expires <= now:
                row["status"] = "EXPIRED"
                row["outcome"] = "RUNTIME_RESTART_SIGNAL_TTL_EXPIRED"
                row["exit_reason"] = row["outcome"]
                # Deferred until after trade_lock is released below.
                result.setdefault("_overdue", []).append(row)
    for row in result.pop("_overdue", []):
        if _record_expired_order(row, "RUNTIME_RESTART_SIGNAL_TTL_EXPIRED") is not None:
            result["overdue_reconciled"] += 1
    logger.warning(f"[PAPER_LIFECYCLE] restart restored positions={result['positions']} "
                   f"pending={result['pending_orders']} duplicates={result['duplicates']} "
                   f"invalid={result['invalid']} [PIPELINE ENFORCEMENT]")
    return result


def reconcile_restored_paper_terminal_conflicts() -> dict:
    """Remove only paper exposure whose authoritative lifecycle is terminal.

    A crash can occur after the close ledger/trades_map commit but before the
    older positions.json or paper_lifecycle.json snapshot is replaced.  On the
    next boot those stale OPEN rows previously resurrected a closed trade and
    made the strict-flat endpoint contradictory.  Terminal identity wins, but
    this repair is deliberately limited to paper-only, disarmed rows and never
    mutates any Bitfinex-backed exposure.
    """
    result = {"positions": 0, "pending_orders": 0, "terminal_ids": []}
    if not _force_paper_mode_active() or state.get("live_armed"):
        return result

    terminal_ids = {
        str(row.get("trade_id"))
        for row in trades
        if isinstance(row, dict) and row.get("trade_id")
    }
    for trade_id, entry in list(trades_map.items()):
        signal = (entry or {}).get("signal_ref") if isinstance(entry, dict) else None
        if isinstance(signal, dict) and is_terminal_signal(signal):
            terminal_ids.add(str(trade_id))
    if not terminal_ids:
        return result

    with trade_lock:
        stale_positions = [
            row for row in open_positions
            if isinstance(row, dict)
            and str(row.get("trade_id") or "") in terminal_ids
            and not row.get("bitfinex_position_id")
            and not row.get("bitfinex_live_entry")
        ]
        stale_orders = [
            row for row in pending_orders
            if isinstance(row, dict)
            and str(row.get("trade_id") or "") in terminal_ids
            and not row.get("bitfinex_order_id")
            and not row.get("bitfinex_live_entry")
        ]
        for row in stale_positions:
            if row in open_positions:
                open_positions.remove(row)
            bucket = lane_open_positions.get(_normalize_lane_key(row), [])
            if row in bucket:
                bucket.remove(row)
        for row in stale_orders:
            if row in pending_orders:
                pending_orders.remove(row)
            bucket = lane_pending_orders.get(_normalize_lane_key(row), [])
            if row in bucket:
                bucket.remove(row)

    result.update({
        "positions": len(stale_positions),
        "pending_orders": len(stale_orders),
        "terminal_ids": sorted({
            str(row.get("trade_id")) for row in stale_positions + stale_orders
        }),
    })
    if stale_positions or stale_orders:
        save_positions()
        save_paper_lifecycle(reason="terminal_identity_reconciled")
        logger.error(
            "[PAPER_LIFECYCLE] removed terminal-state resurrection "
            "positions=%s pending=%s ids=%s [PIPELINE ENFORCEMENT]",
            result["positions"], result["pending_orders"], result["terminal_ids"],
        )
    return result


def capture_emergency_paper_lifecycle_snapshot() -> dict:
    """Create a hash-addressed operator snapshot only while paper-only/disarmed."""
    if not _force_paper_mode_active() or state.get("live_armed"):
        raise PermissionError("emergency lifecycle snapshot requires paper-only and disarmed runtime")
    if not save_paper_lifecycle(reason="emergency_snapshot"):
        raise OSError("paper lifecycle persistence failed")
    with paper_lifecycle_file_lock:
        with open(PAPER_LIFECYCLE_FILE, "rb") as handle:
            raw = handle.read()
    digest = hashlib.sha256(raw).hexdigest()
    target = f"paper_lifecycle_emergency_{digest[:16]}.json"
    _atomic_file_replace(target, lambda f: f.write(raw.decode("utf-8")),
                         paper_lifecycle_file_lock, "PAPER_LIFECYCLE_EMERGENCY")
    return {"path": target, "sha256": digest, "bytes": len(raw)}

def save_positions(*, persist_lifecycle: bool = True):
    with state_lock:
        snapshot = _fast_state_copy(open_positions)
    _atomic_file_replace(
        POSITIONS_FILE,
        lambda f: f.write(json.dumps(snapshot)),
        positions_file_lock,
        "POSITIONS",
    )
    if persist_lifecycle:
        save_paper_lifecycle(reason="positions_saved")

def validate_state():
    # prune_signals takes trade_lock — never call it under state_lock (deadlocks with
    # pipeline_state_sync / sync_signal_info_registry: trade_lock -> state_lock).
    prune_signals()
    with state_lock:
        pending_orders[:] = [o for o in pending_orders if isinstance(o, dict) and o.get("created_ts", 0) > 0]
        expired_orders[:] = [o for o in expired_orders if isinstance(o, dict) and o.get("created_ts", 0) > 0]
        open_positions[:] = [p for p in open_positions if isinstance(p, dict) and p.get("entry", 0) > 0]
    return True

def record_ai_decision(trade_id, approved, win_prob, comment, dir_, conf, regime, event_id):
    with state_lock:
        now_iso = utc_iso()
        state["ai_history"].append({
            "ts": now_iso,
            "time": now_iso,
            "melbourne_time": _format_melbourne_hm(now_iso),
            "session_ts": bot_start_time,
            "trade_id": trade_id,
            "dir": dir_,
            "decision": "APPROVE" if approved else "REJECT",
            "approved": approved,
            "win_prob": win_prob,
            "comment": comment,
            "reason": (
                f"{'APPROVE' if approved else 'REJECT'} | {comment}"
                if comment else ("APPROVE" if approved else "REJECT")
            )[:500],
            "event_id": event_id,
        })
        hist_limit = 50
        if len(state["ai_history"]) > hist_limit:
            state["ai_history"] = state["ai_history"][-hist_limit:]
        state["ai_decision"] = "APPROVED" if approved else "REJECTED"
        state["final_decision"] = "APPROVED" if approved else "AI_REJECTED"
        state["last_ai"].update({"win_prob": win_prob,"direction": dir_,"trade_id": trade_id,"comment": comment,"ai_error": None})
        state["last_engine_error"] = "" if approved else "AI rejected"
    bridge = get_genome_bridge()
    if bridge:
        try:
            bridge.on_ai_decision(
                approved,
                trade_id=str(trade_id or ""),
                ai_confidence=int(win_prob or 0),
                direction=str(dir_ or ""),
                block_reason="" if approved else str(comment or "AI_REJECTED"),
            )
        except Exception as exc:
            logger.warning(f"[GENOME] ai decision record failed: {exc}")

REPLAY_TICK_MIN_INTERVAL_SEC = 1.0


def _profit_lock_floor_for_ladder(peak_pct: float, ladder, peak_never_loser_min_peak: float = None, peak_never_loser_floor: float = None):
    if peak_pct is None:
        return None
    min_peak = PEAK_NEVER_LOSER_MIN_PEAK if peak_never_loser_min_peak is None else peak_never_loser_min_peak
    floor_val = PEAK_NEVER_LOSER_FLOOR if peak_never_loser_floor is None else peak_never_loser_floor
    pnl_only = peak_pct < ladder[0][0]
    if pnl_only and peak_pct < min_peak:
        return None
    floor = None
    if not pnl_only:
        for trigger, lock in ladder:
            if peak_pct >= trigger:
                floor = lock
    if peak_pct >= min_peak:
        floor = max(floor or 0, floor_val)
    return floor


def _margin_pct_to_usd(margin_pct: float, margin_usdt: float) -> float:
    try:
        return float(margin_pct) / 100.0 * float(margin_usdt)
    except (TypeError, ValueError):
        return 0.0


def patch_signal_snapshot_outcome(
    trade_id: str,
    executed: bool = None,
    block_reason: str = None,
    fill_price: float = None,
    post_block_research: dict = None,
    fill_dynamics: dict = None,
):
    """Merge execution outcome into signal_snapshot.jsonl for analyzer cohort joins."""
    if not trade_id or not os.path.exists(SIGNAL_SNAPSHOT_FILE):
        return
    try:
        # Serialize the entire read/modify/replace cycle with new-row appends.
        with _jsonl_path_lock(SIGNAL_SNAPSHOT_FILE), signal_snapshot_lock:
            lines = []
            updated = False
            with open(SIGNAL_SNAPSHOT_FILE, "r", encoding="utf-8") as f:
                for line in f:
                    raw = line.strip()
                    if not raw:
                        continue
                    try:
                        row = json.loads(raw)
                    except json.JSONDecodeError:
                        logger.warning("[SIGNAL_SNAPSHOT] skip corrupt line during patch")
                        continue
                    if row.get("trade_id") == trade_id:
                        if executed is not None:
                            row["executed"] = bool(executed)
                        if block_reason is not None:
                            row["block_reason"] = block_reason
                        outcome = row.get("outcome") or {}
                        if fill_price is not None:
                            outcome["fill_price"] = float(fill_price)
                        if fill_dynamics:
                            outcome["fill_dynamics"] = fill_dynamics
                        if post_block_research:
                            row["post_block_research"] = post_block_research
                            horizon = post_block_research.get("horizon_outcomes")
                            if horizon:
                                outcome["horizon_outcomes"] = horizon
                                outcome["mfe_pct"] = horizon.get("mfe_pct")
                                outcome["mae_pct"] = horizon.get("mae_pct")
                        outcome["patched_ts"] = time.time()
                        row["outcome"] = outcome
                        updated = True
                    lines.append(json.dumps(row))
            if updated:
                content = "\n".join(lines) + "\n"
                _atomic_file_replace(
                    SIGNAL_SNAPSHOT_FILE,
                    lambda f, c=content: f.write(c),
                    signal_snapshot_lock,
                    "SIGNAL_SNAPSHOT",
                )
    except Exception as e:
        logger.error(f"[SIGNAL_SNAPSHOT] patch failed trade_id={trade_id}: {e}")


def _snapshot_shared_ai_call_id(trade_id, signal: dict, ai: dict):
    """The shared AI call that caused this signal; a scan trade id is that call's id."""
    explicit = (signal or {}).get("shared_ai_call_id") or (ai or {}).get("shared_ai_call_id")
    if explicit:
        return str(explicit)
    return str(trade_id) if str(trade_id or "").startswith("scan-") else None


def counterfactual_join_fields(trade_id, snapshot: dict, replay: dict) -> dict:
    """Timestamps and causal join keys every counterfactual row must carry.

    Rows written before signal snapshots recorded these keys fall back to the
    deterministic scan-call identity; anything still unknown stays null and is
    listed in ``join_keys_missing`` instead of being guessed.
    """
    snapshot = snapshot if isinstance(snapshot, dict) else {}
    replay = replay if isinstance(replay, dict) else {}
    def _num(value):
        try:
            number = float(value)
        except (TypeError, ValueError):
            try:
                number = datetime.fromisoformat(str(value).replace("Z", "+00:00")).timestamp()
            except (TypeError, ValueError):
                return None
        return number if math.isfinite(number) and number > 0 else None
    signal_ts = _num(snapshot.get("approve_ts"))
    if signal_ts is None:
        signal_ts = _num(replay.get("start_ts"))
    shared = (snapshot.get("shared_ai_call_id") or replay.get("shared_ai_call_id")
              or _snapshot_shared_ai_call_id(trade_id, {}, snapshot.get("ai") or {}))
    epoch = (snapshot.get("epoch_id") or snapshot.get("collection_epoch_id")
             or replay.get("epoch_id") or replay.get("collection_epoch_id"))
    now = time.time()
    out = {
        "ts": utc_iso(),
        "written_ts": round(now, 3),
        "signal_ts": signal_ts,
        "signal_utc": snapshot.get("ts") or (
            datetime.fromtimestamp(signal_ts, timezone.utc).isoformat() if signal_ts else None),
        "shared_ai_call_id": shared,
        "epoch_id": epoch,
        "research_lane": snapshot.get("research_lane") or replay.get("research_lane"),
    }
    out["join_keys_missing"] = [k for k in ("signal_ts", "shared_ai_call_id", "epoch_id") if not out.get(k)]
    return out


def _counterfactual_snapshot_with_join_keys(trade_id, snapshot: dict, replay: dict) -> dict:
    joined = counterfactual_join_fields(trade_id, snapshot, replay)
    enriched = dict(snapshot or {})
    for key in ("shared_ai_call_id", "epoch_id"):
        if not enriched.get(key) and joined.get(key):
            enriched[key] = joined[key]
    return enriched


