def begin_approve_research(signal: dict, ai: dict, pipeline_eff_thr: float):
    """Start replay + snapshot at AI APPROVE (before post-AI execution gates)."""
    if ai.get("decision") != "APPROVE":
        return
    if str(signal.get("research_lane") or "").upper() in COMBO_EXECUTION_LANES:
        # Offset outcomes are sourced exclusively from its genuine paper order
        # and position lifecycle. Generic replay uses Scenario C and is invalid.
        return
    trade_id = signal.get("trade_id")
    price = float(signal.get("signal_price") or state.get("price") or 0)
    if not trade_id or price <= 0:
        return
    log_signal_snapshot(signal, ai, pipeline_eff_thr)
    lev = int(state.get("leverage", DEFAULT_RESEARCH_LEVERAGE))
    margin_usdt = float(signal.get("margin_usdt") or FIXED_MARGIN_USDT)
    start_replay_buffer(
        trade_id,
        price,
        lane="shadow",
        direction=signal.get("final_direction"),
        leverage=lev,
        margin_usdt=margin_usdt,
        pullback_pct=float(signal.get("pullback_pct", state.get("pullback_threshold", 0.001))),
        early_fail_enabled=bool(state.get("early_fail_enabled", True)),
        exit_config=get_exit_config_snapshot(signal.get("research_lane")),
        ai_win_prob=ai.get("win_prob"),
        edge_score=signal.get("edge_score_at_entry"),
        research_lane=signal.get("research_lane"),
        source_trade_id=(ai or {}).get("shared_ai_call_id") or signal.get("shared_ai_call_id"),
        shared_ai_call_id=(ai or {}).get("shared_ai_call_id") or signal.get("shared_ai_call_id"),
        shared_ai_call_ts=(ai or {}).get("shared_ai_call_ts") or signal.get("shared_ai_call_ts"),
        collection_mode=signal.get("collection_mode") or "ACTIVE_RESEARCH",
        paused_shadow=bool(signal.get("paused_shadow")),
        invert_on=_coerce_invert_on(signal),
        prompt_id=ai.get("prompt_id") or signal.get("prompt_id") or SHARED_DIRECTION_PROMPT_ID,
        adx_at_signal=(
            ((((signal.get("context") or {}).get("market_context") or {}).get("trend_strength") or {}).get("adx"))
            or (signal.get("features") or {}).get("adx_normalized")
            or (signal.get("features") or {}).get("adx")
        ),
    )
    append_replay_tick(trade_id, price, None)


def mark_approve_research_executed(trade_id: str, fill_price: float):
    if not trade_id or not fill_price or fill_price <= 0:
        return
    fill_dynamics = _mark_fill_replay_buffer_executed(trade_id, fill_price)
    patch_signal_snapshot_outcome(
        trade_id, executed=True, block_reason=None, fill_price=fill_price, fill_dynamics=fill_dynamics,
    )


def _mark_fill_replay_buffer_executed(trade_id: str, fill_price: float):
    """In-memory replay-buffer promotion; returns fill dynamics for evidence."""
    if not trade_id or not fill_price or fill_price <= 0:
        return None
    fill_dynamics = None
    fill_stamps = _fill_replay_3m_stamps()
    with replay_lock:
        buf = replay_buffers.get(trade_id)
        if not buf:
            start_replay_buffer(trade_id, fill_price, lane="executed")
            buf = replay_buffers.get(trade_id)
        if buf:
            buf["lane"] = "executed"
            buf["block_reason"] = None
            buf["virtual_entry"] = float(fill_price)
            buf.update(fill_stamps)
            fill_t = time.time() - _buf_float(buf.get("start_ts"), time.time())
            buf["virtual_fill_t"] = fill_t
            start_price = _buf_float(buf.get("start_price"), fill_price)
            direction = str(buf.get("direction") or "LONG").upper()
            dir_factor = 1 if direction == "LONG" else -1
            leverage = _buf_int(buf.get("leverage"), _replay_leverage_default())
            pre_fill_mae = 0.0
            for tick in sorted(buf.get("ticks", []), key=lambda x: x.get("seq", 0)):
                t = _buf_float(tick.get("t"), 0)
                if t >= fill_t:
                    break
                p = _buf_float(tick.get("price"), 0)
                if p > 0 and start_price > 0:
                    unreal = ((p - start_price) / start_price) * dir_factor * leverage * 100
                    pre_fill_mae = min(pre_fill_mae, unreal)
            fill_dynamics = {
                "fill_delay_sec": round(fill_t, 3),
                "pre_fill_mae_margin_pct": round(pre_fill_mae, 4),
                "achieved_pullback_pct": round(abs(fill_price - start_price) / start_price, 6) if start_price > 0 else None,
            }
    return fill_dynamics


def _shadow_unreal_pct(buf: dict, price: float) -> float:
    entry = _buf_float(buf.get("virtual_entry"), 0)
    if entry <= 0 or price <= 0:
        return 0.0
    direction = buf.get("direction") or "LONG"
    leverage = _buf_int(buf.get("leverage"), _replay_leverage_default())
    dir_factor = 1 if direction == "LONG" else -1
    return ((price - entry) / entry) * dir_factor * leverage * 100


def _try_shadow_limit_fill(buf: dict, price: float, t_rel: float):
    if buf.get("virtual_entry"):
        return
    start_price = _buf_float(buf.get("start_price"), 0)
    direction = buf.get("direction") or "LONG"
    pullback_pct = _buf_float(buf.get("pullback_pct"), 0)
    if start_price <= 0:
        return
    # STATIC resting limit: fill AT exact limit when price touches/crosses — never slide.
    if buf.get("fill_at_limit") or str(buf.get("chase_mode") or "").upper() == "STATIC":
        lim = _buf_float(buf.get("limit_price"), 0)
        if lim <= 0:
            # Derive limit from start_price + pullback if limit_price missing.
            if pullback_pct > 0:
                lim = (
                    start_price * (1 - pullback_pct)
                    if str(direction).upper() == "LONG"
                    else start_price * (1 + pullback_pct)
                )
            else:
                lim = start_price
        if lim <= 0:
            return
        if str(direction).upper() == "LONG" and price <= lim:
            buf["virtual_entry"] = float(lim)
            buf["virtual_fill_t"] = t_rel
            buf["fill_reason"] = "STATIC_LIMIT"
            buf["limit_chase_count"] = 0
            return
        if str(direction).upper() == "SHORT" and price >= lim:
            buf["virtual_entry"] = float(lim)
            buf["virtual_fill_t"] = t_rel
            buf["fill_reason"] = "STATIC_LIMIT"
            buf["limit_chase_count"] = 0
            return
        return
    if pullback_pct <= 0.0:
        buf["virtual_entry"] = float(price)
        buf["virtual_fill_t"] = t_rel
        return
    if direction == "LONG" and price <= start_price * (1 - pullback_pct):
        buf["virtual_entry"] = float(price)
        buf["virtual_fill_t"] = t_rel
    elif direction == "SHORT" and price >= start_price * (1 + pullback_pct):
        buf["virtual_entry"] = float(price)
        buf["virtual_fill_t"] = t_rel


def tick_all_replay_buffers(price: float):
    if price is None or price <= 0:
        return
    now = time.time()
    with state_lock:
        depth = replay_tick_depth({
            key: state.get(key) for key in ("bid", "ask", "bid_qty", "ask_qty", "bbo_ts")
        }, now=now)
    with replay_lock:
        items = list(replay_buffers.items())
    for trade_id, buf in items:
        try:
            if buf.get("closed") or buf.get("lane") == "executed":
                continue
            t_rel = now - _buf_float(buf.get("start_ts"), now)
            _try_shadow_limit_fill(buf, price, t_rel)
            unreal = _shadow_unreal_pct(buf, price) if buf.get("virtual_entry") else None
            append_replay_tick(trade_id, price, unreal, depth=depth)
        except Exception as e:
            logger.error(
                f"[REPLAY_TICK] trade_id={trade_id} lane={buf.get('lane')} failed: {e} "
                f"[PIPELINE ENFORCEMENT]"
            )


def simulate_replay_outcome(buf: dict) -> dict:
    """Walk replay ticks with bot exit rules — used for blocked APPROVE shadow PnL."""
    ticks = sorted(buf.get("ticks", []), key=lambda x: x.get("seq", 0))
    direction = str(buf.get("direction") or "LONG").upper()
    leverage = _buf_int(buf.get("leverage"), _replay_leverage_default())
    margin_usdt = _buf_float(buf.get("margin_usdt"), FIXED_MARGIN_USDT)
    pullback_pct = _buf_float(buf.get("pullback_pct"), 0)
    start_price = _buf_float(buf.get("start_price"), 0)
    exit_config = buf.get("exit_config") or get_exit_config_snapshot()
    trail_ladder = exit_config.get("trail_ladder", TRAIL_LADDER)
    fast_cut = _buf_float(exit_config.get("thesis_fast_exit_unreal_pct"), THESIS_FAST_EXIT_UNREAL_PCT)
    thesis_above = _buf_float(exit_config.get("thesis_exit_if_above_unreal_pct"), THESIS_EXIT_IF_ABOVE_UNREAL_PCT)
    early_fail = bool(buf.get("early_fail_enabled", True))
    sl_pct = sl_price_pct(leverage)
    dir_factor = 1 if direction == "LONG" else -1

    entry = buf.get("virtual_entry")
    fill_t = buf.get("virtual_fill_t")
    fill_at_limit = bool(buf.get("fill_at_limit") or str(buf.get("chase_mode") or "").upper() == "STATIC")
    lim = _buf_float(buf.get("limit_price"), 0)
    if entry is None:
        for tick in ticks:
            price = _buf_float(tick.get("price"), 0)
            t = _buf_float(tick.get("t"), 0)
            if price <= 0 or t > REPLAY_TTL_SEC:
                continue
            if fill_at_limit:
                use_lim = lim
                if use_lim <= 0 and pullback_pct > 0 and start_price > 0:
                    use_lim = (
                        start_price * (1 - pullback_pct)
                        if direction == "LONG"
                        else start_price * (1 + pullback_pct)
                    )
                if use_lim <= 0:
                    continue
                if direction == "LONG" and price <= use_lim:
                    entry = use_lim
                    fill_t = t
                    break
                if direction == "SHORT" and price >= use_lim:
                    entry = use_lim
                    fill_t = t
                    break
                continue
            if pullback_pct <= 0.0:
                entry = price
                fill_t = t
                break
            if direction == "LONG" and price <= start_price * (1 - pullback_pct):
                entry = price
                fill_t = t
                break
            if direction == "SHORT" and price >= start_price * (1 + pullback_pct):
                entry = price
                fill_t = t
                break
    if entry is None or fill_t is None:
        outcome_label = "TTL_EXPIRED" if fill_at_limit else "NO_FILL"
        if str(buf.get("exit_outcome") or "").upper() == "CANCELLED":
            outcome_label = "CANCELLED"
        return {
            "filled": False,
            "exit_reason": outcome_label,
            "entry_outcome": outcome_label,
            "net_pnl_usd": None,
            "gross_pnl_margin_pct": None,
            "max_profit_margin_pct": None,
            "max_drawdown_margin_pct": None,
            "not_a_trade": True,
            "avoided_exposure": True,
            "fill_delay_sec": None,
            "chase_mode": buf.get("chase_mode"),
            "limit_chase_count": int(buf.get("limit_chase_count") or 0),
            "limit_price": lim if lim else None,
            "original_limit_price": _buf_float(buf.get("original_limit_price"), 0) or None,
        }

    sl = entry * (1 - dir_factor * sl_pct)
    peak = 0.0
    mae = 0.0
    exit_reason = "MARK_TO_MARKET"
    exit_margin_pct = 0.0
    last_unreal = 0.0
    for tick in ticks:
        t = _buf_float(tick.get("t"), 0)
        if t < fill_t:
            continue
        price = _buf_float(tick.get("price"), 0)
        if price <= 0:
            continue
        unreal = tick.get("unreal_pct")
        if unreal is None:
            unreal = ((price - entry) / entry) * dir_factor * leverage * 100
        else:
            unreal = _buf_float(unreal, 0)
        last_unreal = unreal
        peak = max(peak, unreal)
        mae = min(mae, unreal)
        age_sec = t - fill_t
        # Paper still skips EARLY_FAIL / last-trade price SL. Phase-aware margin
        # stop: thesis -12% in the first 5 minutes (no MFE bypass), hard -30% after.
        if age_sec < THESIS_MIN_AGE_SEC:
            if unreal <= fast_cut:
                exit_reason = "THESIS_FAST_CUT"
                exit_margin_pct = fast_cut
                break
        elif unreal <= -MAX_SL_MARGIN_PCT:
            exit_reason = "STOP_LOSS"
            exit_margin_pct = -MAX_SL_MARGIN_PCT
            break
        lock_floor = _profit_lock_floor_for_ladder(
            peak,
            trail_ladder,
            peak_never_loser_min_peak=_buf_float(exit_config.get("peak_never_loser_min_peak"), PEAK_NEVER_LOSER_MIN_PEAK),
            peak_never_loser_floor=_buf_float(exit_config.get("peak_never_loser_floor"), PEAK_NEVER_LOSER_FLOOR),
        )
        pnl_min_peak = _buf_float(exit_config.get("peak_never_loser_min_peak"), PEAK_NEVER_LOSER_MIN_PEAK)
        peak_above_ladder = peak >= trail_ladder[0][0]
        peak_in_pnl_zone = peak >= pnl_min_peak and pnl_min_peak < trail_ladder[0][0]
        if lock_floor is not None and (peak_above_ladder or peak_in_pnl_zone) and unreal <= lock_floor:
            exit_reason = "PROFIT_LOCK_LADDER"
            exit_margin_pct = lock_floor
            break
        if unreal >= TP_EMERGENCY_MARGIN_PCT:
            exit_reason = "TAKE_PROFIT"
            exit_margin_pct = TP_EMERGENCY_MARGIN_PCT
            break
        # Section 6: genuine two-hour TIME_EXIT. Once filled, a position must
        # continue until a strategy exit fires; MARK_TO_MARKET is reserved for
        # the rare case where the LAB buffer is truncated before any exit
        # could trigger. Without this check, 61 historical outcomes were
        # classified MARK_TO_MARKET (contributing +$27.39) -- those are
        # EXCLUDED from promotion unless reclassified through a truthful
        # strategy exit, which is what this branch now does.
        if FIXED_TIME_EXIT_ENABLED and (t - fill_t) >= MAX_POSITION_AGE_SEC:
            exit_reason = "TIME_EXIT"
            exit_margin_pct = unreal
            break
        exit_margin_pct = unreal
    else:
        exit_margin_pct = _buf_float(last_unreal, 0) if ticks else 0.0
        # Section 6: if the for loop fell through without any exit firing,
        # the position ran out of ticks before MAX_POSITION_AGE_SEC. That is
        # NOT a MARK_TO_MARKET -- it is a buffer truncation. The honest
        # classification is BUFFER_TRUNCATED so the promotion rule can
        # exclude these rows from the reconciled sample.
        if FIXED_TIME_EXIT_ENABLED and exit_reason == "MARK_TO_MARKET":
            exit_reason = "BUFFER_TRUNCATED"

    net_usd = _margin_pct_to_usd(exit_margin_pct, margin_usdt)
    return {
        "filled": True,
        "exit_reason": exit_reason,
        "entry_outcome": "FILLED",
        "net_pnl_usd": round(net_usd, 4),
        "gross_pnl_margin_pct": round(exit_margin_pct, 4),
        "max_profit_margin_pct": round(peak, 4),
        "max_drawdown_margin_pct": round(mae, 4),
        "fill_delay_sec": round(_buf_float(fill_t, 0), 3),
        "entry": entry,
        "fill_price": entry,
        "chase_mode": buf.get("chase_mode"),
        "limit_chase_count": int(buf.get("limit_chase_count") or 0),
        "fill_reason": buf.get("fill_reason") or ("STATIC_LIMIT" if fill_at_limit else None),
        "limit_price": lim if lim else None,
        "original_limit_price": _buf_float(buf.get("original_limit_price"), 0) or None,
        "start_price": start_price if start_price else None,
    }


def compute_post_block_research(buf: dict, gate_outcome: dict) -> dict:
    """Post-block price path + block quality metrics for analyzer."""
    block_t = _buf_float(buf.get("block_t_rel"), 0)
    ticks = sorted(buf.get("ticks", []), key=lambda x: x.get("seq", 0))
    post_ticks = [t for t in ticks if _buf_float(t.get("t"), 0) >= block_t]
    start_price = _buf_float(buf.get("start_price"), 0)
    direction = str(buf.get("direction") or "LONG").upper()
    dir_factor = 1 if direction == "LONG" else -1
    max_fav = 0.0
    max_adv = 0.0
    for tick in post_ticks:
        p = _buf_float(tick.get("price"), 0)
        if p <= 0 or start_price <= 0:
            continue
        move_pct = ((p - start_price) / start_price) * dir_factor * 100
        max_fav = max(max_fav, move_pct)
        max_adv = min(max_adv, move_pct)
    cf_pnl = gate_outcome.get("net_pnl_usd")
    filled = bool(gate_outcome.get("filled"))
    post_end = max((_buf_float(t.get("t"), 0) for t in post_ticks), default=block_t)
    return {
        "block_t_rel_sec": round(block_t, 3),
        "post_block_tick_count": len(post_ticks),
        "post_block_duration_sec": round(max(0.0, post_end - block_t), 3),
        "post_block_max_favorable_pct": round(max_fav, 4),
        "post_block_max_adverse_pct": round(max_adv, 4),
        "counterfactual_pnl_usd": round(float(cf_pnl), 4) if filled and cf_pnl is not None else None,
        "block_was_correct": bool(filled and cf_pnl is not None and cf_pnl < 0),
        "block_cost_usd": round(float(cf_pnl), 4) if filled and cf_pnl and cf_pnl > 0 else 0.0,
        "block_saved_usd": round(-float(cf_pnl), 4) if filled and cf_pnl is not None and cf_pnl < 0 else 0.0,
        "continuation_target_sec": POST_BLOCK_CONTINUATION_SEC,
    }


def log_shadow_outcome_jsonl(
    trade_id: str, block_reason: str, outcome: dict, buf: dict,
    signal: dict = None, ai: dict = None, post_block_research: dict = None,
):
    try:
        if str(buf.get("research_lane") or "").upper() in COMBO_EXECUTION_LANES:
            logger.error(
                "[OFFSET029_CONTRACT] refused forbidden shadow outcome write "
                f"trade_id={trade_id} [PIPELINE ENFORCEMENT]"
            )
            return
        row = {
            "schema": "shadow_outcome_v2",
            "ts": utc_iso(),
            "trade_id": trade_id,
            "executed": False,
            "block_reason": block_reason,
            "direction": buf.get("direction"),
            "research_lane": buf.get("research_lane"),
            "collection_mode": buf.get("collection_mode"),
            "paused_shadow": bool(buf.get("paused_shadow")),
            "prompt_id": buf.get("prompt_id"),
            "shared_ai_call_id": buf.get("shared_ai_call_id") or buf.get("source_trade_id"),
            "shared_ai_call_ts": buf.get("shared_ai_call_ts"),
            "lane_recorded_ts": utc_iso(
                datetime.fromtimestamp(float(buf.get("start_ts") or time.time()), tz=timezone.utc)
            ),
            "adx_at_signal": buf.get("adx_at_signal"),
            "ai_win_prob": buf.get("ai_win_prob") or (ai or {}).get("win_prob"),
            "edge_score": buf.get("edge_score"),
            "pullback_pct": buf.get("pullback_pct"),
            "leverage": buf.get("leverage"),
            "margin_usdt": buf.get("margin_usdt"),
            "start_price": buf.get("start_price"),
            "tick_count": len(buf.get("ticks", [])),
            "origin_t_rel": buf.get("virtual_fill_t"),
            "horizon_receipts": buf.get("horizon_receipts") or {},
            "path_gaps": _path_gap_census(buf.get("ticks")),
            "fill_origin": {"classification": "MISSING"} if outcome.get("filled") is not True else {"classification": "SHADOW_ESTIMATE"},
            "block_t_rel_sec": buf.get("block_t_rel"),
            "post_block_tick_count": (post_block_research or {}).get("post_block_tick_count"),
            "exit_config": buf.get("exit_config") or get_exit_config_snapshot(),
            "post_block_research": post_block_research or {},
            **shadow_row_completeness(buf),
            **outcome,
        }
        _safe_append_jsonl(SHADOW_OUTCOME_FILE, row, label="SHADOW_OUTCOME")
        logger.info(
            f"[SHADOW_OUTCOME] trade_id={trade_id} reason={block_reason} filled={outcome.get('filled')} "
            f"pnl=${outcome.get('net_pnl_usd')} exit={outcome.get('exit_reason')} [PIPELINE ENFORCEMENT]"
        )
        if "SOFT_REJECT" in str(block_reason) or str(block_reason).startswith("AI_"):
            log_ai_confidence_calibration(
                {
                    "trade_id": trade_id,
                    "ai_win_prob": row.get("ai_win_prob"),
                    "exit_reason": outcome.get("exit_reason"),
                    "research_lane": buf.get("research_lane"),
                    "execution_tier": (ai or {}).get("execution_tier"),
                },
                float(outcome.get("net_pnl_usd") or 0),
                source="shadow_reject",
            )
    except Exception as e:
        logger.error(f"[SHADOW_OUTCOME] log failed: {e}")


def defer_shadow_research(trade_id: str, block_reason: str):
    """Keep blocked APPROVE replay alive until SHADOW_REPLAY_TTL_SEC for counterfactual ticks."""
    if not trade_id:
        return
    now = time.time()
    block_t_rel = 0.0
    with replay_lock:
        buf = replay_buffers.get(trade_id)
        if not buf or buf.get("lane") == "executed":
            return
        buf["block_reason"] = block_reason
        buf["block_ts"] = now
        block_t_rel = round(now - buf.get("start_ts", now), 3)
        buf["block_t_rel"] = block_t_rel
        buf["lane"] = "shadow_deferred"
    logger.info(
        f"[SHADOW_DEFER] trade_id={trade_id} reason={block_reason} "
        f"block_t={block_t_rel}s ttl={SHADOW_REPLAY_TTL_SEC}s post_block>={POST_BLOCK_CONTINUATION_SEC}s "
        f"[PIPELINE ENFORCEMENT]"
    )


def finalize_shadow_research(trade_id: str, block_reason: str, signal: dict = None, ai: dict = None):
    """Simulate blocked APPROVE path and persist shadow PnL."""
    if not trade_id:
        return
    with replay_lock:
        buf = replay_buffers.get(trade_id)
        if not buf:
            return
        if buf.get("lane") == "executed":
            return
        buf["block_reason"] = block_reason
        buf["lane"] = "shadow_blocked"
        buf_copy = {
            **buf,
            "ticks": list(buf.get("ticks", [])),
        }
    outcome = simulate_replay_outcome(buf_copy)
    post_block = compute_post_block_research(buf_copy, outcome)
    horizons = compute_horizon_outcomes_from_replay(buf_copy)
    if horizons:
        post_block = {**post_block, **horizons}
        outcome = {**outcome, **horizons}
    log_shadow_outcome_jsonl(
        trade_id, block_reason, outcome, buf_copy, signal=signal, ai=ai, post_block_research=post_block,
    )
    log_golden_stack_rejection_outcome(trade_id, post_block_research=post_block, executed=False)
    patch_signal_snapshot_outcome(trade_id, executed=False, block_reason=block_reason, post_block_research=post_block)
    close_replay_buffer(trade_id)


def start_replay_buffer(trade_id: str, start_price: float, **meta):
    sp = _buf_float(start_price, 0)
    if not trade_id or sp <= 0:
        return False
    lev_default = _replay_leverage_default()
    pullback_default = _buf_float(state.get("pullback_threshold"), 0.001)
    fee_model = meta.get("fee_model") or _canonical_counterfactual_profile(
        "execution_cost_profile_v1", venue=BOT_EXCHANGE,
        configured_profile=EXCHANGE_FEE_PROFILE,
        maker_fee_rate=MAKER_FEE_PCT, taker_fee_rate=TAKER_FEE_PCT,
        funding_simulation_enabled=bool(FUNDING_SIMULATION_ENABLED),
    )
    execution_profile = meta.get("execution_profile") or _canonical_counterfactual_profile(
        "replay_execution_profile_v1", venue=BOT_EXCHANGE,
        instrument=BITFINEX_WS_SYMBOL, lane=str(meta.get("lane") or "executed"),
        entry_order_type="LIMIT", executable_marks="DIRECTIONAL_BBO",
        fill_at_limit=bool(meta.get("fill_at_limit")),
        chase_mode=meta.get("chase_mode") or "NONE",
        protective_exit="REDUCE_ONLY_STOP",
    )
    fill_stamps = _fill_replay_3m_stamps(None, meta.get("entry_features") or meta)
    policy_version = meta.get("policy_version")
    invert_on = bool(meta.get("invert_on", False))
    policy_identity = meta.get("policy_identity")
    if not isinstance(policy_identity, dict) and str(meta.get("lane") or "").startswith("shadow_collect_"):
        policy_identity = _shadow_policy_identity(
            research_lane=meta.get("research_lane"),
            policy_version=policy_version,
            exit_config=meta.get("exit_config"),
            invert_on=invert_on,
        )
    policy_identity = copy.deepcopy(policy_identity or {})
    # A replay study is optional evidence, never an execution prerequisite.
    # Bound acquisition so a busy/corrupt replay service cannot wedge the sole
    # periodic AI scheduler or its isolated evidence worker indefinitely.
    if not replay_lock.acquire(timeout=2.0):
        logger.error(
            "[REPLAY_BUFFER] lock timeout trade_id=%s lane=%s diagnostics=%s "
            "[PIPELINE ENFORCEMENT]",
            trade_id, meta.get("lane"), replay_lock.diagnostics(),
        )
        return False
    try:
        if trade_id in replay_buffers and not replay_buffers[trade_id].get("closed"):
            return True
        replay_buffers[trade_id] = {
            "start_ts": time.time(),
            "start_price": sp,
            "ticks": [],
            "last_update": time.time(),
            "last_tick_ts": 0.0,
            "closed": False,
            "seq": 0,
            "lane": meta.get("lane", "executed"),
            "direction": meta.get("direction") or "LONG",
            "leverage": _buf_int(meta.get("leverage"), lev_default),
            "margin_usdt": _buf_float(meta.get("margin_usdt"), FIXED_MARGIN_USDT),
            "pullback_pct": _buf_float(meta.get("pullback_pct"), pullback_default),
            "early_fail_enabled": meta.get("early_fail_enabled", True),
            "exit_config": meta.get("exit_config"),
            "virtual_entry": _buf_float(meta["virtual_entry"], 0) if meta.get("virtual_entry") is not None else None,
            "virtual_fill_t": _buf_float(meta["virtual_fill_t"], 0) if meta.get("virtual_fill_t") is not None else None,
            "block_reason": meta.get("block_reason"),
            "ai_win_prob": meta.get("ai_win_prob"),
            "edge_score": meta.get("edge_score"),
            "research_lane": meta.get("research_lane"),
            "source_trade_id": meta.get("source_trade_id"),
            "shared_ai_call_id": meta.get("shared_ai_call_id") or meta.get("source_trade_id"),
            "shared_ai_call_ts": meta.get("shared_ai_call_ts"),
            "collection_mode": meta.get("collection_mode"),
            "is_counterfactual": bool(meta.get("is_counterfactual")),
            "policy_version": policy_version,
            "collection_epoch_id": policy_identity.get("collection_epoch_id"),
            "base_policy_id": policy_identity.get("base_policy_id"),
            "control_policy_signature": policy_identity.get("control_policy_signature"),
            "policy_signature": policy_identity.get("policy_signature"),
            "policy_epoch_id": policy_identity.get("policy_epoch_id"),
            "policy_identity": policy_identity,
            "fee_model": fee_model,
            "execution_profile": execution_profile,
            # Immutable comparison identity.  These are captured when the
            # market path begins so offline analysis never has to infer the
            # policy/executor world from mutable current settings.
            "source_git_rev": meta.get("source_git_rev") or _runtime_git_rev(),
            "executor_revision": meta.get("executor_revision") or _runtime_git_rev(),
            "fill_gate_rev": meta.get("fill_gate_rev") or "VENUE_EXECUTABLE_SHOWCASE_FILL_GATE_V2",
            "correlated_cluster_boundary_pct": (
                meta.get("correlated_cluster_boundary_pct")
                if meta.get("correlated_cluster_boundary_pct") is not None
                else CLUSTER_MIN_DIST_PCT
            ),
            "size_mult": meta.get("size_mult"),
            "session_bucket": meta.get("session_bucket"),
            "entry_features": copy.deepcopy(meta.get("entry_features") or {}),
            "ai_snapshot": copy.deepcopy(meta.get("ai_snapshot") or {}),
            # Section 8: stable policy/episode identifiers, threaded from the
            # bracket tick through the LAB spawn into the outcome record.
            "sr_episode_id": meta.get("sr_episode_id"),
            "exit_profile_id": meta.get("exit_profile_id"),
            "v2_min_fill_age_sec": meta.get("v2_min_fill_age_sec"),
            "v2_chase_target_min": meta.get("v2_chase_target_min"),
            "v2_chase_target_max": meta.get("v2_chase_target_max"),
            "prompt_id": meta.get("prompt_id"),
            "adx_at_signal": meta.get("adx_at_signal"),
            "paused_shadow": bool(meta.get("paused_shadow")),
            "v2_checker_accepted": meta.get("v2_checker_accepted"),
            "v2_fail_reasons": meta.get("v2_fail_reasons"),
            "limit_price": _buf_float(meta["limit_price"], 0) if meta.get("limit_price") is not None else None,
            "original_limit_price": (
                _buf_float(meta["original_limit_price"], 0)
                if meta.get("original_limit_price") is not None
                else None
            ),
            "chase_mode": meta.get("chase_mode"),
            "max_chases": meta.get("max_chases"),
            "fill_at_limit": bool(meta.get("fill_at_limit")),
            "limit_chase_count": int(meta.get("limit_chase_count") or 0),
            "exit_outcome": meta.get("exit_outcome"),
            "invert_on": bool(meta.get("invert_on", False)),
            **fill_stamps,
        }
    finally:
        replay_lock.release()
    return True


def append_replay_tick(
    trade_id: str,
    price: float,
    unreal_pct: float = None,
    *,
    best_bid: float = None,
    best_ask: float = None,
    observed_ts: float = None,
    mark_source: str = None,
    depth: dict = None,
):
    if not trade_id or price is None or price <= 0:
        return
    now = _buf_float(observed_ts, 0) or time.time()
    with replay_lock:
        buf = replay_buffers.get(trade_id)
        if not buf or buf.get("closed"):
            return
        if now - _buf_float(buf.get("last_tick_ts"), 0) < REPLAY_TICK_MIN_INTERVAL_SEC:
            return
        buf["seq"] = _buf_int(buf.get("seq"), 0) + 1
        t_rel = round(now - _buf_float(buf.get("start_ts"), now), 3)
        block_ts = _buf_float(buf.get("block_ts"), 0)
        if buf.get("post_exit"):
            phase = "post_exit"
        elif block_ts > 0 and now >= block_ts:
            phase = "post_block"
        else:
            phase = "pre_block"
        ticks = buf.setdefault("ticks", [])
        tick_max = POST_EXIT_REPLAY_TICK_MAX if buf.get("post_exit") else REPLAY_TICK_MAX
        if len(ticks) >= tick_max:
            ticks.pop(0)
        source = mark_source or (
            "bbo" if (best_bid or 0) > 0 or (best_ask or 0) > 0 else "last_trade"
        )
        tick_row = {
            "seq": buf["seq"],
            "t": t_rel,
            "price": float(price),
            "unreal_pct": round(float(unreal_pct), 4) if unreal_pct is not None else None,
            "phase": phase,
            "best_bid": float(best_bid) if best_bid is not None else None,
            "best_ask": float(best_ask) if best_ask is not None else None,
            "observed_ts": now,
            "mark_source": source,
        }
        if isinstance(depth, dict):
            tick_row.update(depth)
        ticks.append(tick_row)
        if unreal_pct is not None:
            prev_mfe = _buf_float(buf.get("peak_mfe_pct"), None)
            prev_mae = _buf_float(buf.get("trough_mae_pct"), None)
            mfe = float(unreal_pct) if prev_mfe is None else max(prev_mfe, float(unreal_pct))
            mae = float(unreal_pct) if prev_mae is None else min(prev_mae, float(unreal_pct))
            buf["peak_mfe_pct"] = mfe
            buf["trough_mae_pct"] = mae
        else:
            mfe = buf.get("peak_mfe_pct")
            mae = buf.get("trough_mae_pct")
        _update_compact_horizon_receipts(buf, tick_row)
        buf["last_update"] = now
        buf["last_tick_ts"] = now
        is_post_exit = bool(buf.get("post_exit"))
        persist_trade_id = trade_id if is_post_exit else None
        path_row = build_path_sample(
            trade_id=trade_id,
            t=t_rel,
            price=float(price),
            unreal_pct=unreal_pct,
            phase=phase,
            direction=buf.get("direction") or "LONG",
            leverage=_buf_int(buf.get("leverage"), _replay_leverage_default()),
            best_bid=best_bid,
            best_ask=best_ask,
            mark_source=source,
            peak_mfe_pct=mfe,
            trough_mae_pct=mae,
            observed_ts=now,
            seq=buf["seq"],
            invert_on=bool(buf.get("invert_on", False)),
        )
    if COLLECTOR_V22_PATH_REPLAY_1S:
        _safe_append_jsonl(PATH_REPLAY_FILE, path_row, label="PATH_REPLAY")
    if persist_trade_id is not None:
        try:
            _safe_append_jsonl(POST_EXIT_REPLAY_FILE, {
                "kind": "tick",
                "trade_id": persist_trade_id,
                "ts": now,
                "price": float(price),
                "unreal_pct": round(float(unreal_pct), 4) if unreal_pct is not None else None,
                "phase": "post_exit",
                "seq": int(buf["seq"]) if is_post_exit else None,
                "t_rel": t_rel,
                "best_bid": float(best_bid) if best_bid is not None else None,
                "best_ask": float(best_ask) if best_ask is not None else None,
                "mark_source": source,
                "schema": PATH_REPLAY_SCHEMA,
                "policy_tag": PATH_REPLAY_POLICY_TAG,
            }, label="POST_EXIT_REPLAY_TICK")
        except Exception as e:
            logger.error(f"[POST_EXIT_REPLAY] tick persist failed tid={persist_trade_id}: {e}")


