def begin_post_exit_replay(trade_id: str, pos: dict, exit_price: float):
    """Keep replay alive for POST_EXIT_REPLAY_SEC after close — horizon recovery data."""
    if not trade_id or exit_price is None or float(exit_price) <= 0:
        close_replay_buffer(trade_id)
        return
    now = time.time()
    with replay_lock:
        missing_buffer = not replay_buffers.get(trade_id)
    if missing_buffer:
        # A long-lived executed replay may have exhausted the pre-exit ring.
        # Recreate a conservative shell so future post-exit ticks are still
        # captured; absent pre-exit horizons remain UNKNOWN.
        entry = float(pos.get("entry") or exit_price)
        start_replay_buffer(
            trade_id,
            entry,
            lane="executed",
            direction=pos.get("dir") or "LONG",
            leverage=pos.get("leverage"),
            margin_usdt=pos.get("margin_usdt"),
            virtual_entry=entry,
            policy_version=pos.get("policy_version"),
            exit_config=copy.deepcopy(pos.get("exit_config") or get_exit_config_snapshot()),
        )
        with replay_lock:
            rebuilt = replay_buffers.get(trade_id)
            if rebuilt and _buf_float(pos.get("entry_ts"), 0) > 0:
                rebuilt["start_ts"] = _buf_float(pos.get("entry_ts"), now)
    with replay_lock:
        buf = replay_buffers.get(trade_id)
        if not buf:
            return
        entry = float(pos.get("entry") or buf.get("virtual_entry") or exit_price)
        exit_t_rel = round(now - _buf_float(buf.get("start_ts"), now), 3)
        buf["post_exit"] = True
        buf["post_exit_started_ts"] = now
        buf["post_exit_deadline_ts"] = now + POST_EXIT_REPLAY_SEC
        buf["exit_t_rel"] = exit_t_rel
        buf["entry_price"] = entry
        buf["virtual_entry"] = buf.get("virtual_entry") or entry
        buf["direction"] = pos.get("dir") or buf.get("direction") or "LONG"
        buf["leverage"] = _buf_int(pos.get("leverage") or buf.get("leverage"), _replay_leverage_default())
        buf["exit_reason"] = pos.get("exit_reason")
        unreal = _shadow_unreal_pct(buf, float(exit_price))
        buf["seq"] = _buf_int(buf.get("seq"), 0) + 1
        ticks = buf.setdefault("ticks", [])
        tick_max = POST_EXIT_REPLAY_TICK_MAX if buf.get("post_exit") else REPLAY_TICK_MAX
        if len(ticks) >= tick_max:
            ticks.pop(0)
        ticks.append({
            "seq": buf["seq"],
            "t": exit_t_rel,
            "price": float(exit_price),
            "unreal_pct": round(float(unreal), 4),
            "phase": "post_exit",
        })
        buf["last_update"] = now
        buf["last_tick_ts"] = now
        # Persist the post-exit trade header to the sidecar so a restart can
        # rebuild this buffer before the deadline elapses.
        try:
            _safe_append_jsonl(POST_EXIT_REPLAY_FILE, {
                "kind": "post_exit_header",
                "trade_id": trade_id,
                "ts": now,
                "post_exit_deadline_ts": buf.get("post_exit_deadline_ts"),
                "post_exit_started_ts": buf.get("post_exit_started_ts"),
                "entry_price": buf.get("entry_price"),
                "virtual_entry": buf.get("virtual_entry"),
                "direction": buf.get("direction"),
                "leverage": buf.get("leverage"),
                "exit_reason": buf.get("exit_reason"),
                "start_ts": buf.get("start_ts"),
                "exit_t_rel": buf.get("exit_t_rel"),
                "virtual_fill_t": buf.get("virtual_fill_t"),
                "margin_usdt": buf.get("margin_usdt"),
                "policy_version": buf.get("policy_version"),
                "exit_config": copy.deepcopy(buf.get("exit_config") or {}),
                "bitfinex_evidence": copy.deepcopy(buf.get("bitfinex_evidence") or {}),
                "fee_model": buf.get("fee_model"),
                "execution_profile": buf.get("execution_profile"),
                "chase_mode": buf.get("chase_mode"),
                "max_chases": buf.get("max_chases"),
                "fill_at_limit": bool(buf.get("fill_at_limit")),
                "collection_epoch_id": buf.get("collection_epoch_id"),
                "source_git_rev": buf.get("source_git_rev"),
                "executor_revision": buf.get("executor_revision"),
                "fill_gate_rev": buf.get("fill_gate_rev"),
                "correlated_cluster_boundary_pct": buf.get("correlated_cluster_boundary_pct"),
            }, label="POST_EXIT_REPLAY_HEADER")
        except Exception as e:
            logger.error(f"[POST_EXIT_REPLAY] header persist failed tid={trade_id}: {e}")
    logger.info(
        f"[POST_EXIT_REPLAY] trade_id={trade_id} exit_t={exit_t_rel}s "
        f"collecting {POST_EXIT_REPLAY_SEC}s for horizon recovery [PIPELINE ENFORCEMENT]"
    )


def service_post_exit_replays():
    """Append mark-price ticks to post-exit replay buffers (no open position required)."""
    with state_lock:
        price = float(state.get("price") or 0)
        book = copy.deepcopy(state.get("order_book") or {})
        ticker_bid = _buf_float(state.get("bid"), 0)
        ticker_ask = _buf_float(state.get("ask"), 0)
    best_bid = _buf_float(book.get("best_bid") or book.get("bid") or ticker_bid, 0)
    best_ask = _buf_float(book.get("best_ask") or book.get("ask") or ticker_ask, 0)
    if price <= 0 and best_bid <= 0 and best_ask <= 0:
        return
    with replay_lock:
        tids = [
            tid for tid, buf in replay_buffers.items()
            if buf.get("post_exit") and not buf.get("closed")
        ]
    for tid in tids:
        with replay_lock:
            buf = replay_buffers.get(tid)
            if not buf or not buf.get("post_exit") or buf.get("closed"):
                continue
            entry = _buf_float(buf.get("entry_price") or buf.get("virtual_entry"), 0)
            if entry <= 0:
                continue
            direction = str(buf.get("direction") or "LONG").upper()
            executable_mark = best_bid if direction == "LONG" else best_ask
            if executable_mark > 0:
                mark_source = "bbo"
            elif price > 0:
                # BBO preferred for 1pp sweeps; last-trade keeps 120m dense when
                # the book is briefly empty. Offline can filter mark_source.
                executable_mark = price
                mark_source = "last_trade"
            else:
                continue
            unreal = _shadow_unreal_pct({**buf, "virtual_entry": entry}, executable_mark)
        append_replay_tick(
            tid,
            executable_mark,
            unreal,
            best_bid=best_bid or None,
            best_ask=best_ask or None,
            mark_source=mark_source,
        )


def _load_post_exit_replays():
    """Rebuild post-exit replay buffers from the sidecar JSONL on startup.

    Only buffers whose ``post_exit_deadline_ts`` has not yet elapsed are
    restored, so the file does not grow unbounded across sessions.  Pre-existing
    in-memory entries are preserved (live in-progress buffers always take
    precedence over the on-disk snapshot).
    """
    active_path = Path(POST_EXIT_REPLAY_FILE)
    rotated_paths = sorted(
        (path for path in active_path.parent.glob(f"{active_path.name}.*")
         if path.name[len(active_path.name) + 1:].isdigit()),
        key=lambda path: int(path.name[len(active_path.name) + 1:]),
        reverse=True,
    )
    replay_paths = rotated_paths + ([active_path] if active_path.exists() else [])
    if not replay_paths:
        return
    now = time.time()
    restored = 0
    headers: Dict[str, dict] = {}
    ticks_by_tid: Dict[str, list] = {}
    # The rotated sidecar holds hundreds of MB of expired tick rows; parsing
    # them all into dicts OOM-killed boot on a 2 GB machine. Stream twice:
    # headers first, then ticks only for buffers still inside their window.
    try:
      for replay_path in replay_paths:
        with open(replay_path, "r", encoding="utf-8-sig") as f:
            for line in f:
                if "post_exit_header" not in line:
                    continue
                try:
                    row = json.loads(line)
                except (TypeError, ValueError):
                    continue
                tid = row.get("trade_id")
                if tid and row.get("kind") == "post_exit_header":
                    headers[tid] = row
      active_tids = {
          tid for tid, header in headers.items()
          if _buf_float(header.get("post_exit_deadline_ts"), 0) > now
      }
      headers = {tid: headers[tid] for tid in active_tids}
      if active_tids:
        for replay_path in replay_paths:
            with open(replay_path, "r", encoding="utf-8-sig") as f:
                for line in f:
                    if '"tick"' not in line or not any(tid in line for tid in active_tids):
                        continue
                    try:
                        row = json.loads(line)
                    except (TypeError, ValueError):
                        continue
                    tid = row.get("trade_id")
                    if row.get("kind") == "tick" and tid in active_tids:
                        ticks_by_tid.setdefault(tid, []).append(row)
    except Exception as e:
        logger.error(f"[POST_EXIT_REPLAY] load failed: {e}")
        return
    with replay_lock:
        for tid, header in headers.items():
            deadline = _buf_float(header.get("post_exit_deadline_ts"), 0)
            if deadline <= 0 or deadline <= now:
                continue
            if tid in replay_buffers and not replay_buffers[tid].get("closed"):
                # Already rebuilt by the live path this session; skip the stale snapshot.
                continue
            start_ts = _buf_float(header.get("start_ts"), now)
            virtual_entry = _buf_float(header.get("virtual_entry"), 0) or _buf_float(header.get("entry_price"), 0)
            replay_buffers[tid] = {
                "start_ts": start_ts,
                "start_price": virtual_entry,
                "ticks": [],
                "last_update": now,
                "last_tick_ts": 0.0,
                "closed": False,
                "seq": 0,
                "lane": "executed",
                "direction": header.get("direction") or "LONG",
                "leverage": _buf_int(header.get("leverage"), _replay_leverage_default()),
                "margin_usdt": _buf_float(header.get("margin_usdt"), FIXED_MARGIN_USDT),
                "virtual_entry": virtual_entry,
                "virtual_fill_t": header.get("virtual_fill_t"),
                "policy_version": header.get("policy_version"),
                "exit_config": copy.deepcopy(header.get("exit_config") or {}),
                "bitfinex_evidence": copy.deepcopy(header.get("bitfinex_evidence") or {}),
                "fee_model": header.get("fee_model"),
                "execution_profile": header.get("execution_profile"),
                "chase_mode": header.get("chase_mode"),
                "max_chases": header.get("max_chases"),
                "fill_at_limit": bool(header.get("fill_at_limit")),
                "collection_epoch_id": header.get("collection_epoch_id"),
                "source_git_rev": header.get("source_git_rev"),
                "executor_revision": header.get("executor_revision"),
                "fill_gate_rev": header.get("fill_gate_rev"),
                "correlated_cluster_boundary_pct": header.get("correlated_cluster_boundary_pct"),
                "post_exit": True,
                "post_exit_started_ts": _buf_float(header.get("post_exit_started_ts"), now),
                "post_exit_deadline_ts": deadline,
                "entry_price": _buf_float(header.get("entry_price"), virtual_entry),
                "exit_reason": header.get("exit_reason"),
                "exit_t_rel": _buf_float(header.get("exit_t_rel"), 0),
            }
            buf = replay_buffers[tid]
            tick_rows = ticks_by_tid.get(tid, [])
            tick_rows.sort(key=lambda r: _buf_float(r.get("ts"), 0))
            for row in tick_rows:
                ts = _buf_float(row.get("ts"), 0)
                if ts <= 0:
                    continue
                seq = _buf_int(buf.get("seq"), 0) + 1
                buf["seq"] = seq
                buf["ticks"].append({
                    "seq": seq,
                    "t": round(ts - start_ts, 3),
                    "price": float(row.get("price") or 0),
                    "unreal_pct": row.get("unreal_pct"),
                    "phase": "post_exit",
                    "best_bid": row.get("best_bid"),
                    "best_ask": row.get("best_ask"),
                    "observed_ts": ts,
                })
            if buf["ticks"]:
                buf["last_update"] = _buf_float(tick_rows[-1].get("ts"), now)
                buf["last_tick_ts"] = _buf_float(tick_rows[-1].get("ts"), 0)
            restored += 1
    if restored:
        logger.info(
            f"[POST_EXIT_REPLAY] restored {restored} post-exit buffer(s) from sidecar "
            f"[PIPELINE ENFORCEMENT]"
        )


_HORIZON_RECEIPT_SECS = (
    ("1m", 60), ("2m", 120), ("3m", 180), ("5m", 300), ("10m", 600),
    ("15m", 900), ("20m", 1200), ("30m", 1800), ("45m", 2700),
    ("60m", 3600), ("90m", 5400), ("120m", 7200),
)
_MAX_PATH_GAP_MS = 15_000


def _update_compact_horizon_receipts(buf, tick):
    """Persist 1/5/15/30/60/120m marks before the ring buffer rotates them away."""
    if not isinstance(buf, dict) or not isinstance(tick, dict):
        return
    origin = _buf_float(buf.get("virtual_fill_t"), 0)
    t_rel = _buf_float(tick.get("t"), -1)
    if t_rel < 0:
        return
    direction = str(buf.get("direction") or "LONG").upper()
    side_key = "best_bid" if direction == "LONG" else "best_ask"
    price = _buf_float(tick.get(side_key), 0) or _buf_float(tick.get("price"), 0)
    receipts = buf.setdefault("horizon_receipts", {"schema": "horizon_receipts_v1", "required": {}})
    required = receipts.setdefault("required", {})
    for label, seconds in _HORIZON_RECEIPT_SECS:
        slot = required.setdefault(label, {"required_sec": seconds, "observed": False})
        if slot.get("observed"):
            continue
        if t_rel >= origin + seconds and price > 0:
            slot.update({
                "observed": True,
                "tick_t_rel": t_rel,
                "price": price,
                "best_bid": tick.get("best_bid"),
                "best_ask": tick.get("best_ask"),
                "observed_ts": tick.get("observed_ts"),
            })
    receipts["complete"] = all((required.get(label) or {}).get("observed") for label, _sec in _HORIZON_RECEIPT_SECS)
    receipts["origin_t_rel"] = origin


def _path_gap_census(ticks, window_sec=7200):
    ordered = [tick for tick in (ticks or []) if isinstance(tick, dict)]
    gaps = []
    prev = None
    stale = []
    for tick in ordered:
        ts = _buf_float(tick.get("observed_ts"), 0)
        t_rel = _buf_float(tick.get("t"), 0)
        age = tick.get("book_age_sec")
        if age is not None:
            try:
                stale.append(float(age))
            except (TypeError, ValueError):
                pass
        key = ts or t_rel
        if prev is not None and key:
            delta_ms = (key - prev) * 1000.0
            if delta_ms > 0:
                gaps.append(delta_ms)
        if key:
            prev = key
    max_gap = max(gaps) if gaps else None
    observed = 0.0
    if len(ordered) >= 2:
        observed = _buf_float(ordered[-1].get("t"), 0) - _buf_float(ordered[0].get("t"), 0)
    censored = bool(max_gap is not None and max_gap > _MAX_PATH_GAP_MS)
    return {
        "schema": "path_gap_v1",
        "tick_count": len(ordered),
        "max_gap_ms": None if max_gap is None else round(max_gap, 3),
        "observed_frac_of_120m": None if not window_sec else round(min(1.0, max(0.0, observed / window_sec)), 6),
        "max_book_stale_sec": None if not stale else round(max(stale), 4),
        "censored": censored,
        "censor_reason": "MAX_GAP_EXCEEDED" if censored else None,
    }


def _compact_market_path_ref(replay, snapshot, extra=None):
    ticks = (replay or {}).get("ticks") or []
    evidence = (snapshot or {}).get("source_order_market_evidence") or {}
    obs = evidence.get("observations") if isinstance(evidence, dict) else []
    obs = obs if isinstance(obs, list) else []
    generations = sorted({
        int(item.get("limit_generation") or 0)
        for item in obs if isinstance(item, dict)
    })
    chase_count = max(generations) if generations else int((snapshot or {}).get("limit_chase_count") or (replay or {}).get("limit_chase_count") or 0)
    payload = {
        "trade_id": (snapshot or {}).get("trade_id") or (replay or {}).get("trade_id"),
        "tick_count": len(ticks),
        "obs_count": len(obs),
        "chase_count": chase_count,
        "t_start": (ticks[0] or {}).get("t") if ticks else None,
        "t_end": (ticks[-1] or {}).get("t") if ticks else None,
    }
    blob = json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
    digest = hashlib.sha256(blob).hexdigest()
    ref = {
        "schema": "content_addressed_evidence_ref_v1",
        "evidence_schema": "market_path_v1",
        "sha256": digest,
        "bytes": len(blob),
        "object_id": f"market_path_v1:{digest[:16]}",
        "tick_count": len(ticks),
        "observation_count": len(obs),
        "start_offset": 0,
        "end_offset": max(0, len(ticks) - 1),
        "time_range": {"start_t": payload["t_start"], "end_t": payload["t_end"]},
        "chase_count": chase_count,
        "limit_generations": generations,
    }
    if extra:
        ref.update(extra)
    return ref


def _compact_source_market_evidence(evidence):
    if not isinstance(evidence, dict):
        return {}
    obs = evidence.get("observations") if isinstance(evidence.get("observations"), list) else []
    compact = {key: value for key, value in evidence.items() if key != "observations"}
    compact["observation_count"] = len(obs)
    compact["observations_elided"] = True
    compact["limit_generation"] = max(
        (int(item.get("limit_generation") or 0) for item in obs if isinstance(item, dict)),
        default=int(evidence.get("limit_generation") or 0),
    )
    return compact


def close_replay_buffer(trade_id):
    buf = None
    with replay_lock:
        buf = replay_buffers.get(trade_id)
        if buf:
            buf["closed"] = True
    if not buf:
        return
    # ``dump_replay`` owns replay_lock. Calling it while holding this
    # non-reentrant lock deadlocked the state-monitor thread and eventually
    # starved the scheduled AI cycle. Keep the close marker atomic, then let
    # the writer take the lock exactly once.
    dump_replay(trade_id)
    with replay_lock:
        if replay_buffers.get(trade_id) is buf:
            replay_buffers.pop(trade_id, None)

def dump_replay(trade_id: str, terminal_reason: Optional[str] = None):
    """Append the buffer's replay row.

    ``terminal_reason`` labels a dump that is not the buffer's natural end
    (e.g. ``CENSORED_PROCESS_SHUTDOWN``) so the analyzer can tell a censored
    path from a genuinely incomplete one and dedupe re-dumps per trade.
    """
    global write_counter
    mv_source = None
    shadow_exit_payload = None
    with replay_lock:
        buf = replay_buffers.get(trade_id)
        if not buf:
            return
        try:
            post_ticks = [t for t in buf.get("ticks", []) if t.get("phase") == "post_block"]
            post_exit_ticks = [t for t in buf.get("ticks", []) if t.get("phase") == "post_exit"]
            now = time.time()
            lane = str(buf.get("lane") or "")
            is_executed = lane == "executed"
            post_exit_deadline = _buf_float(buf.get("post_exit_deadline_ts"), 0)
            exit_t_rel = _buf_float(buf.get("exit_t_rel"), -1)
            executable_key = (
                "best_bid" if str(buf.get("direction") or "LONG").upper() == "LONG"
                else "best_ask"
            )
            required_post_exit_tick = next((
                tick for tick in post_exit_ticks
                if _buf_float(tick.get("t"), -1) >= exit_t_rel + POST_EXIT_REPLAY_SEC
                and _buf_float(tick.get(executable_key), 0) > 0
            ), None)
            post_exit_complete = bool(
                buf.get("post_exit")
                and post_exit_deadline > 0
                and now >= post_exit_deadline
                and exit_t_rel >= 0
                and required_post_exit_tick is not None
            )
            has_fill_origin = buf.get("virtual_fill_t") is not None and buf.get("virtual_entry") is not None
            replay_complete = bool(
                buf.get("closed")
                and buf.get("ticks")
                and has_fill_origin
                and (not is_executed or post_exit_complete)
            )
            buf["dump_seq"] = _buf_int(buf.get("dump_seq"), 0) + 1
            natural_reason = (
                "POST_EXIT_HORIZON_COMPLETE"
                if post_exit_complete
                else "FILL_ORIGIN_BUFFER_CLOSED"
                if replay_complete
                else "INCOMPLETE_EXECUTED_POST_EXIT"
                if is_executed
                else "BUFFER_CLOSED_NO_FILL_ORIGIN"
                if buf.get("closed") and buf.get("ticks") and not has_fill_origin
                else "INCOMPLETE_BUFFER"
            )
            censored = bool(terminal_reason) and not replay_complete
            replay = {
                "schema": "signal_replay_v4",
                "trade_id": trade_id,
                "dumped_ts": round(now, 3),
                "dump_seq": buf["dump_seq"],
                "dump_reason": terminal_reason or ("BUFFER_CLOSED" if buf.get("closed") else "EXPIRED_OR_EVICTED"),
                "censored": censored,
                "start_ts": utc_iso(datetime.fromtimestamp(buf["start_ts"], timezone.utc)),
                "start_price": buf["start_price"],
                "direction": buf.get("direction"),
                "lane": buf.get("lane"),
                "block_reason": buf.get("block_reason"),
                "block_ts": buf.get("block_ts"),
                "block_t_rel": buf.get("block_t_rel"),
                "post_block_tick_count": len(post_ticks),
                "post_exit_tick_count": len(post_exit_ticks),
                "post_exit_sec": round(max(
                    (_buf_float(t.get("t"), exit_t_rel) - exit_t_rel for t in post_exit_ticks),
                    default=0,
                ), 3),
                "post_exit_complete": post_exit_complete,
                "replay_complete": replay_complete,
                "replay_completion_reason": terminal_reason if censored else natural_reason,
                "natural_completion_reason": natural_reason,
                "terminal_provenance": (
                    "SHOWCASE_STRATEGY_EXIT" if is_executed else "COUNTERFACTUAL_ONLY"
                ),
                "exit_t_rel": buf.get("exit_t_rel"),
                "exit_reason": buf.get("exit_reason"),
                "virtual_entry": buf.get("virtual_entry"),
                "virtual_fill_t": buf.get("virtual_fill_t"),
                "origin_t_rel": buf.get("virtual_fill_t"),
                "horizon_receipts": buf.get("horizon_receipts"),
                "path_gaps": _path_gap_census(buf.get("ticks")),
                "entry_price": buf.get("entry_price"),
                "pullback_pct": buf.get("pullback_pct"),
                "leverage": buf.get("leverage"),
                "margin_usdt": buf.get("margin_usdt"),
                "exit_config": copy.deepcopy(buf.get("exit_config") or {}),
                "fee_model": buf.get("fee_model"),
                "execution_profile": buf.get("execution_profile"),
                "chase": {
                    "enabled": bool(buf.get("chase_mode")) and str(buf.get("chase_mode")).upper() != "NONE",
                    "mode": buf.get("chase_mode") or "NONE",
                    "max_chases": buf.get("max_chases"),
                    "fill_at_limit": bool(buf.get("fill_at_limit")),
                },
                "collection_epoch_id": buf.get("collection_epoch_id"),
                "source_git_rev": buf.get("source_git_rev"),
                "executor_revision": buf.get("executor_revision"),
                "fill_gate_rev": buf.get("fill_gate_rev"),
                "correlated_cluster_boundary_pct": buf.get("correlated_cluster_boundary_pct"),
                "ticks": list(buf["ticks"]),
            }
            if _safe_append_jsonl(SIGNAL_REPLAY_FILE, replay, label="SIGNAL_REPLAY"):
                write_counter += 1
            if buf.get("closed") and not terminal_reason:
                policy_identity = buf.get("policy_identity") if isinstance(buf.get("policy_identity"), dict) else {}
                shadow_exit_payload = {"replay": replay, "meta": {
                    "start_ts": buf.get("start_ts"),
                    "research_lane": (buf.get("research_lane") or policy_identity.get("research_lane")
                                      or tile_lane_for_trade_id(trade_id)),
                    "policy_signature": buf.get("policy_signature"),
                    "collection_epoch_id": buf.get("collection_epoch_id"),
                    "limit_price": buf.get("limit_price") or buf.get("original_limit_price"),
                    "atr14_pct_3m": buf.get("atr14_pct_3m"),
                    "adx_at_signal": buf.get("adx_at_signal"),
                    "regime": buf.get("regime") or buf.get("entry_regime"),
                    "entry_features": buf.get("entry_features"),
                }}
            if replay_complete:
                paper_tid = paper_multiverse_trade_id(
                    trade_id,
                    buf.get("source_trade_id"),
                )
                if paper_tid:
                    fill_t = buf.get("virtual_fill_t")
                    start_ts = buf.get("start_ts")
                    live_fill_ts = None
                    if fill_t is not None and start_ts:
                        live_fill_ts = float(start_ts) + float(fill_t)
                    mv_source = {
                        "trade_id": paper_tid,
                        "signal_price": buf.get("start_price") or buf.get("entry_price"),
                        "signal_price_at_approve": buf.get("start_price"),
                        "created_ts_ts": buf.get("start_ts"),
                        "final_direction": buf.get("direction"),
                        "status": "CLOSED" if buf.get("closed") else "FILLED",
                        "ticket_closed": bool(buf.get("closed")),
                        "invert_on": bool(buf.get("invert_on", False)),
                        "live_fill_ts": live_fill_ts,
                        "live_fill_price": buf.get("virtual_entry") or buf.get("entry_price"),
                        "atr14_pct_3m": buf.get("atr14_pct_3m"),
                        "donchian_high_3m": buf.get("donchian_high_3m"),
                        "donchian_low_3m": buf.get("donchian_low_3m"),
                        "support_price": buf.get("support_price"),
                        "resistance_price": buf.get("resistance_price"),
                    }
        except Exception as e:
            logger.error(f"Replay dump failed for {trade_id}: {e}")
    if shadow_exit_payload is not None:
        _submit_shadow_exit_path(shadow_exit_payload)
    if mv_source:
        _sync_order_multiverse(mv_source, path_complete=True)

def load_policy():
    if not os.path.exists(POLICY_FILE):
        logger.info("No policy.json found - using defaults")
        return
    try:
        with open(POLICY_FILE, 'r') as f:
            policy = json.load(f)
        policy_hash = hashlib.sha256(json.dumps(policy.get("rules", {}), sort_keys=True).encode()).hexdigest()
        logger.info(f"Policy loaded: hash {policy_hash}")
        with state_lock:
            state["_policy"] = policy
    except Exception as e:
        logger.error(f"Policy load failed: {e} - using defaults")

def policy_allows_invert(regime: str) -> bool:
    with state_lock:
        p = state.get("_policy", {})
        rules = p.get("rules", {})
        if "invert_signal_only_in" in rules:
            return regime in rules["invert_signal_only_in"]
        return state.get("invert_signal", False)

def policy_allows_early_fail(strategy: str) -> bool:
    with state_lock:
        p = state.get("_policy", {})
        rules = p.get("rules", {})
        if "disable_early_fail_in" in rules:
            return strategy not in rules["disable_early_fail_in"]
        return state.get("early_fail_enabled", True)

def safe_event_put(event):
    try:
        if event_queue.qsize() > MAX_EVENT_QUEUE * 0.7:
            _QUEUE_COUNTERS.dropped("event_queue_throttled")
            logger.warning("Queue pressure high - throttling signals")
            return
        try:
            event_queue.put(event, timeout=0.01)
        except Full:
            logger.error("[QUEUE] Overflow - dropping safely")
            _QUEUE_COUNTERS.dropped("event_queue")
            try:
                event_queue.get_nowait()
                event_queue.put(event)
            except Exception:
                _QUEUE_COUNTERS.dropped("event_queue")
    except Exception as e:
        logger.error(f"safe_event_put failed: {e}")

def drain_stale_events():
    now = time.time()
    drained = 0
    temp = []
    while not event_queue.empty():
        ev = event_queue.get_nowait()
        if now - ev.get("ts", 0) <= 5:
            temp.append(ev)
        else:
            drained += 1
    for ev in temp:
        event_queue.put_nowait(ev)
    if drained > 0:
        _QUEUE_COUNTERS.dropped("event_queue_stale", drained)
        logger.info(f"Drained {drained} stale events")

def reconcile_state():
    with state_lock:
        pending_orders[:] = [o for o in pending_orders if isinstance(o, dict) and o.get("created_ts", 0) > 0]
        expired_orders[:] = [o for o in expired_orders if isinstance(o, dict) and o.get("created_ts", 0) > 0]
        open_positions[:] = [p for p in open_positions if isinstance(p, dict) and p.get("entry", 0) > 0]
    return True

def update_analytics_summary():
    if len(trades) < MIN_ANALYTICS_TRADES:
        return
    wins = [t for t in trades if safe_float(t.get("net_pnl_usd", 0)) > 0]
    losses = [t for t in trades if safe_float(t.get("net_pnl_usd", 0)) < 0]
    win_rate = len(wins) / len(trades) * 100 if trades else 0
    with state_lock:
        state["analytics"] = {"win_rate": round(win_rate, 2),"total_trades": len(trades),"by_strategy": {},"by_regime": {},"exit_reasons": {}}
        state["analytics_ts"] = utc_iso()

def compute_analytics():
    with state_lock:
        trades_snapshot = copy.deepcopy(trades)
    if len(trades_snapshot) < MIN_ANALYTICS_TRADES:
        return
    analytics = {"total_trades": len(trades_snapshot),"wins": 0,"losses": 0,"by_strategy": {},"by_regime": {},"exit_reasons": {},"ai_bands": {}}
    for t in trades_snapshot:
        pnl = safe_float(t.get("net_pnl_usd", 0))
        if pnl > 0:
            analytics["wins"] += 1
        else:
            analytics["losses"] += 1
        reg = t.get("regime", "UNKNOWN")
        strat = t.get("strategy", "SR")
        exit_r = t.get("exit_reason", "UNKNOWN")
        analytics["by_regime"][reg] = analytics["by_regime"].get(reg, 0) + 1
        analytics["by_strategy"][strat] = analytics["by_strategy"].get(strat, 0) + 1
        analytics["exit_reasons"][exit_r] = analytics["exit_reasons"].get(exit_r, 0) + 1
        band = str(t.get("ai_band", "0-5"))
        if band not in analytics["ai_bands"]:
            analytics["ai_bands"][band] = {"trades": 0, "wins": 0, "pnl": 0.0}
        analytics["ai_bands"][band]["trades"] += 1
        analytics["ai_bands"][band]["pnl"] += pnl
        if pnl > 0:
            analytics["ai_bands"][band]["wins"] += 1
    # Keep the aggregate contract complete. The Agent Hub reads this field
    # from authenticated /api/state; previously compute_analytics() replaced
    # update_analytics_summary()'s payload and silently dropped win_rate,
    # causing a missing metric to render as a real-looking 0.0%.
    analytics["win_rate"] = round(
        100.0 * analytics["wins"] / analytics["total_trades"],
        2,
    ) if analytics["total_trades"] else 0.0
    with state_lock:
        state["analytics"] = analytics
        state["analytics_ts"] = utc_iso()

def run_offline_research_sim():
    """Backfill counterfactual.jsonl from snapshots + replays (deduped by trade_id)."""
    global _sim_processed_trade_ids
    try:
        platform_revisions = {
            trade_id: evidence.get("evidence_revision")
            for trade_id, evidence in _platform_relay_evidence_index().items()
        }
        latest_local_revisions = {}
        if os.path.exists(COUNTERFACTUAL_FILE):
            with open(COUNTERFACTUAL_FILE, "r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        row = json.loads(line)
                        tid = row.get("trade_id")
                        if tid:
                            latest_local_revisions[str(tid)] = row.get("platform_evidence_revision")
                        # A changed platform evidence fingerprint produces a new
                        # append-only derived revision; the older row is retained.
                        if tid and (
                            not platform_revisions.get(str(tid))
                            or row.get("platform_evidence_revision") == platform_revisions.get(str(tid))
                        ):
                            _sim_processed_trade_ids.add(tid)
                    except Exception:
                        pass
        for tid, revision in platform_revisions.items():
            if latest_local_revisions.get(tid) != revision:
                _sim_processed_trade_ids.discard(tid)
        # Shadow rows are not a substitute for a compact counterfactual
        # disposition. Every eligible opportunity gets a CF row or an explicit
        # exclusion; missing evidence stays UNKNOWN, never $0.
        offline_simulator()
    except Exception as e:
        logger.error(f"[RESEARCH_SIM] {e}")


def analytics_loop():
    global _cf_catchup_tick_counter
    try:
        while not shutdown_event.is_set():
            try:
                compute_analytics()
                run_offline_research_sim()
                # Change 5: periodic catch-up for APPROVE signals whose replay
                # rotated into a .N shard before the active-file pass saw them.
                # Heavy shard scan — only every CF_CATCHUP_EVERY_N_TICKS ticks,
                # EXCEPT the first tick after boot which fires immediately so a
                # fresh deploy backfills the historical coverage gap without
                # waiting ~100min for the first window.
                _cf_catchup_tick_counter += 1
                if _cf_catchup_tick_counter == 1 or _cf_catchup_tick_counter >= CF_CATCHUP_EVERY_N_TICKS:
                    if _cf_catchup_tick_counter >= CF_CATCHUP_EVERY_N_TICKS:
                        _cf_catchup_tick_counter = 0
                    try:
                        _run_counterfactual_catchup()
                    except Exception as ce:
                        logger.error(f"[CF_CATCHUP] analytics loop error: {ce}")
                try:
                    rep = _refresh_execution_reports_guarded(os.getcwd())
                    fs = rep.get("funnel_summary") or {}
                    logger.info(
                        f"[FUNNEL] approves={fs.get('approve_count')} orders={fs.get('order_submitted_count')} "
                        f"fills={fs.get('filled_count')} approve_to_fill={fs.get('approve_to_fill_rate_pct')}% "
                        f"[PIPELINE ENFORCEMENT]"
                    )
                except Exception as fe:
                    _THREAD_HEALTH.error("analytics_loop", fe)
                    logger.debug(f"[FUNNEL] report refresh failed: {fe}")
                try:
                    refresh_pathway_scorecard_live()
                except Exception as pe:
                    _THREAD_HEALTH.error("analytics_loop", pe)
                    logger.debug(f"[PATHWAY_SCORECARD] analytics refresh failed: {pe}")
                try:
                    rep = refresh_shadow_vs_live_entry_report(os.getcwd())
                    if rep.get("sample_count"):
                        logger.info(
                            f"[SHADOW_VS_LIVE] n={rep['sample_count']} "
                            f"avg_delta=${rep.get('avg_delta_usd')} [PIPELINE ENFORCEMENT]"
                        )
                except Exception as se:
                    _THREAD_HEALTH.error("analytics_loop", se)
                    logger.debug(f"[SHADOW_VS_LIVE] report refresh failed: {se}")
            except Exception as e:
                _THREAD_HEALTH.error("analytics_loop", e)
                logger.error(f"Analytics error: {e}")
            _THREAD_HEALTH.beat("analytics_loop")
            time.sleep(ANALYTICS_INTERVAL_SEC)
    except Exception as e:
        _THREAD_HEALTH.error("analytics_loop", e)
        logger.exception("[CRITICAL] Analytics loop crash")
        set_execution_paused("THREAD_CRASH")


FUTURE_PATH_WORKER_WALL_TIMEOUT_SEC = 30.0


def all_opportunity_future_path_evidence_loop():
    """Mature future tape evidence independently of AI and execution.

    The work is deliberately bounded and runs on its own daemon.  A missing or
    incomplete tape produces an auditable UNKNOWN row; it can never pause the
    bot, alter an AI verdict, submit an order, or delay the periodic AI owner.
    """
    # Let startup, market-data recovery, and the first AI cycle own disk/CPU.
    # Thereafter this low-priority evidence pass runs only every five minutes.
    if shutdown_event.wait(60.0):
        return
    while not shutdown_event.is_set():
        try:
            nonce = uuid.uuid4().hex
            result_path = (
                Path(os.getcwd()) / "v3" / "receipts"
                / f"future-path-worker-{nonce}.json"
            )
            result_path.parent.mkdir(parents=True, exist_ok=True)
            worker_env = {
                key: os.environ[key]
                for key in (
                    "SYSTEMROOT", "WINDIR", "COMSPEC", "TEMP", "TMP",
                    "TMPDIR", "PATH", "LANG", "LC_ALL",
                )
                if key in os.environ
            }
            worker_env.update({
                "PYTHONNOUSERSITE": "1", "PYTHONHASHSEED": "0",
                "OPENBLAS_NUM_THREADS": "1", "OMP_NUM_THREADS": "1",
                "MKL_NUM_THREADS": "1",
            })
            from future_path_attempt_receipt import run_attempt
            invocation_epoch = _collector_v22_epoch_id()
            invocation_now = time.time()
            with state_lock:
                prior = state.get("all_opportunity_future_path_evidence")
                if isinstance(prior, dict):
                    prior.update(is_latest_attempt=False, latest_attempt_status="RUNNING")
            try:
                outcome = run_attempt(
                    receipt_root=result_path.parent, result_path=result_path,
                    epoch_id=invocation_epoch, source_revision=_runtime_git_rev_exact(),
                    expected_now_ts=invocation_now,
                    invoke=lambda: subprocess.run(
                    [
                        sys.executable,
                        str(Path(__file__).resolve().with_name(
                            "research_v3_future_paths_worker.py"
                        )),
                        "--data-dir", os.getcwd(),
                        "--epoch-id", invocation_epoch,
                        "--now-ts", str(invocation_now),
                        "--max-batch", "64",
                        "--result", str(result_path),
                    ],
                    stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    timeout=FUTURE_PATH_WORKER_WALL_TIMEOUT_SEC,
                    check=False,
                    env=worker_env,
                    ),
                )
                receipt = outcome["worker_result"]
                with state_lock:
                    state["all_opportunity_future_path_attempt"] = copy.deepcopy(outcome["attempt"])
                    current_epoch = _collector_v22_epoch_id() == invocation_epoch
                    state["all_opportunity_future_path_attempt"]["is_current_epoch"] = current_epoch
                    if not current_epoch:
                        receipt = None
                    prior = state.get("all_opportunity_future_path_evidence")
                    if receipt is None and isinstance(prior, dict):
                        prior["is_latest_attempt"] = False
                        prior["latest_attempt_status"] = "FAILED"
                if receipt is None:
                    raise RuntimeError(outcome["attempt"]["failure_code"] or "FUTURE_PATH_EPOCH_CHANGED")
            except Exception:
                with state_lock:
                    prior = state.get("all_opportunity_future_path_evidence")
                    if isinstance(prior, dict):
                        prior.update(is_latest_attempt=False, latest_attempt_status="FAILED")
                raise
            finally:
                result_path.unlink(missing_ok=True)
            with state_lock:
                if _collector_v22_epoch_id() != invocation_epoch:
                    state["all_opportunity_future_path_attempt"]["is_current_epoch"] = False
                    prior = state.get("all_opportunity_future_path_evidence")
                    if isinstance(prior, dict):
                        prior.update(is_latest_attempt=False, latest_attempt_status="FAILED")
                    raise RuntimeError("FUTURE_PATH_EPOCH_CHANGED")
                state["all_opportunity_future_path_evidence"] = {
                    key: copy.deepcopy(receipt.get(key))
                    for key in (
                        "schema", "epoch_id", "now_ts", "candidate_count",
                        "pending_count", "mature_selected", "complete_count",
                        "unknown_count", "source_tape_present",
                    )
                }
                state["all_opportunity_future_path_evidence"].update(
                    is_latest_attempt=True, latest_attempt_status="SUCCESS",
                )
            if receipt.get("complete_count") or receipt.get("unknown_count"):
                logger.info(
                    "[COLLECTOR_V3] all-opportunity future paths "
                    f"complete={receipt.get('complete_count')} "
                    f"unknown={receipt.get('unknown_count')} "
                    f"pending={receipt.get('pending_count')} "
                    "[PIPELINE ENFORCEMENT]"
                )
        except Exception as exc:
            logger.error(
                f"[COLLECTOR_V3] future-path evidence pass failed: {exc} "
                "[EVIDENCE ONLY]"
            )
        if shutdown_event.wait(300.0):
            break

