def _declared_serialized_jsonl_targets():
    """Return the stable startup contract for JSONL fixed-prefix downloads.

    Sync consistency mode must not depend on whether a writer happened to run
    between the manifest and file request. Every path routed through the
    serialized writer is therefore declared before the first request.
    """
    values = list(_JSONL_SERIALIZED_APPEND_LITERALS)
    for constant_name in _JSONL_SERIALIZED_APPEND_CONSTANTS:
        value = globals().get(constant_name)
        if isinstance(value, str) and value:
            values.append(value)
    return {os.path.abspath(value) for value in values}


_jsonl_serialized_append_targets = _declared_serialized_jsonl_targets()


def _jsonl_path_lock(path: str):
    key = os.path.abspath(path)
    with _jsonl_append_locks_guard:
        lock = _jsonl_append_locks.get(key)
        if lock is None:
            lock = threading.RLock()
            _jsonl_append_locks[key] = lock
        return lock


def _jsonl_validation_signature(path: str):
    stat = os.stat(path)
    return (
        int(stat.st_dev), int(stat.st_ino), int(stat.st_size), int(stat.st_mtime_ns),
        int(stat.st_ctime_ns),
    )


def _jsonl_validation_tail_sha256(path: str, size_bytes: int) -> str:
    start = max(0, int(size_bytes) - _JSONL_VALIDATION_TAIL_BYTES)
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        handle.seek(start)
        for chunk in iter(lambda: handle.read(64 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _jsonl_validation_receipt_path(path: str) -> str:
    return os.path.abspath(path) + ".validation.json"


def _fsync_jsonl_validation_parent(path: str) -> None:
    if os.name == "nt" or not hasattr(os, "O_DIRECTORY"):
        return
    descriptor = os.open(os.path.dirname(path) or ".", os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def _persist_jsonl_validation_receipt(path: str, signature) -> None:
    key = os.path.abspath(path)
    receipt_path = _jsonl_validation_receipt_path(key)
    receipt = {
        "schema": "jsonl_validation_receipt_v1",
        "complete": True,
        "source_name": os.path.basename(key),
        "device": signature[0],
        "inode": signature[1],
        "size_bytes": signature[2],
        "mtime_ns": signature[3],
        "ctime_ns": signature[4],
        "tail_bytes": min(signature[2], _JSONL_VALIDATION_TAIL_BYTES),
        "tail_sha256": _jsonl_validation_tail_sha256(key, signature[2]),
    }
    temp = receipt_path + ".tmp"
    with open(temp, "w", encoding="utf-8") as handle:
        json.dump(receipt, handle, sort_keys=True)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temp, receipt_path)
    _fsync_jsonl_validation_parent(receipt_path)
    _jsonl_validated_targets[key] = signature


def _jsonl_validation_receipt_matches(path: str, signature) -> bool:
    receipt_path = _jsonl_validation_receipt_path(path)
    try:
        with open(receipt_path, "r", encoding="utf-8") as handle:
            receipt = json.load(handle)
        expected = (
            int(receipt["device"]), int(receipt["inode"]),
            int(receipt["size_bytes"]), int(receipt["mtime_ns"]),
            int(receipt["ctime_ns"]),
        )
        if (
            receipt.get("schema") != "jsonl_validation_receipt_v1"
            or receipt.get("complete") is not True
            or receipt.get("source_name") != os.path.basename(path)
            or expected != signature
        ):
            return False
        return receipt.get("tail_sha256") == _jsonl_validation_tail_sha256(
            path, signature[2]
        )
    except (OSError, UnicodeError, ValueError, KeyError, TypeError, json.JSONDecodeError):
        return False


def _validate_or_quarantine_jsonl(path: str, label: str) -> bool:
    """Preserve a corrupt source file and make the active target writable.

    A durable exact-file receipt avoids reparsing an unchanged historical
    prefix after restart. Every append refreshes the receipt. Any external
    replacement, mutation or truncation invalidates both the in-memory and
    durable signatures and falls back to a full fail-closed parse. Corrupt
    bytes are moved with a SHA-256/line receipt into evidence quarantine.
    """
    key = os.path.abspath(path)
    if not os.path.isfile(path):
        _jsonl_validated_targets[key] = None
        return True
    signature = _jsonl_validation_signature(key)
    if _jsonl_validated_targets.get(key) == signature:
        return True
    if _jsonl_validation_receipt_matches(key, signature):
        _jsonl_validated_targets[key] = signature
        return True
    bad_line = None
    error = None
    try:
        with open(path, "r", encoding="utf-8") as handle:
            for line_number, line in enumerate(handle, 1):
                if not line.strip():
                    continue
                try:
                    json.loads(line)
                except json.JSONDecodeError as exc:
                    bad_line = line_number
                    error = f"{type(exc).__name__}: {exc.msg}"
                    break
    except (OSError, UnicodeError) as exc:
        bad_line = 0
        error = f"{type(exc).__name__}: {exc}"
    if bad_line is None:
        signature = _jsonl_validation_signature(key)
        _persist_jsonl_validation_receipt(key, signature)
        return True

    quarantine_root = os.path.join(
        os.path.dirname(key), "corrupt_evidence_quarantine",
        datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S_%fZ") + "_" + uuid.uuid4().hex[:8],
    )
    os.makedirs(quarantine_root, exist_ok=False)
    target = os.path.join(quarantine_root, os.path.basename(key))
    size_bytes = os.path.getsize(key)
    digest = hashlib.sha256()
    with open(key, "rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    os.replace(key, target)
    validation_receipt = _jsonl_validation_receipt_path(key)
    if os.path.isfile(validation_receipt):
        os.replace(
            validation_receipt,
            os.path.join(quarantine_root, os.path.basename(validation_receipt)),
        )
    receipt = {
        "schema": "corrupt_jsonl_quarantine_v1",
        "complete": True,
        "quarantined_at": utc_iso(),
        "source_name": os.path.basename(key),
        "label": label,
        "bad_line": bad_line,
        "error": error,
        "size_bytes": size_bytes,
        "sha256": digest.hexdigest(),
        "preserved_path": os.path.basename(target),
    }
    receipt_path = os.path.join(quarantine_root, "quarantine_manifest.json")
    temp = receipt_path + ".tmp"
    with open(temp, "w", encoding="utf-8") as handle:
        json.dump(receipt, handle, indent=2, sort_keys=True)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temp, receipt_path)
    _jsonl_validated_targets[key] = None
    logger.error(
        f"[{label}] corrupt JSONL preserved at {quarantine_root}; bad_line={bad_line} "
        "new active file will start [PIPELINE ENFORCEMENT]"
    )
    return False


def _sha256_file(path: str) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _completed_jsonl_repair(
    path: str, expected_sha256: str, invalid_line: int, invalid_line_sha256: str,
):
    """Return an immutable completed repair only while its rebuilt file is active."""
    root = os.path.join(os.path.dirname(os.path.abspath(path)), "corrupt_evidence_quarantine")
    try:
        candidates = sorted(os.scandir(root), key=lambda item: item.name, reverse=True)[:64]
    except OSError:
        return None
    for item in candidates:
        receipt_path = os.path.join(item.path, "repair_receipt.json")
        try:
            with open(receipt_path, "r", encoding="utf-8") as handle:
                receipt = json.load(handle)
            if (
                receipt.get("schema") == "jsonl_corruption_repair_receipt_v1"
                and receipt.get("complete") is True
                and receipt.get("source_sha256") == expected_sha256
                and receipt.get("invalid_line_numbers") == [invalid_line]
                and receipt.get("expected_invalid_line_sha256") == invalid_line_sha256
                and os.path.isfile(path)
                and _sha256_file(path) == receipt.get("rebuilt_sha256")
            ):
                return receipt
        except (OSError, ValueError, TypeError, json.JSONDecodeError):
            continue
    return None


def _repair_execution_funnel_jsonl(
    path: str, *, expected_sha256: str, expected_invalid_line: int,
    expected_invalid_line_sha256: str,
) -> dict:
    """Quarantine exact corrupt bytes and atomically retain every valid raw line.

    The caller must hold the research gate, the bot path lock, and the funnel
    writer lock. Preconditions bind the operator's inspection to the exact
    bytes being repaired, so a concurrent append or different corrupt line
    fails closed without creating artifacts.
    """
    key = os.path.abspath(path)
    expected_sha256 = str(expected_sha256 or "").strip().lower()
    expected_invalid_line_sha256 = str(expected_invalid_line_sha256 or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", expected_sha256):
        raise ValueError("expected_sha256 must be a lowercase SHA-256")
    if not re.fullmatch(r"[0-9a-f]{64}", expected_invalid_line_sha256):
        raise ValueError("expected_invalid_line_sha256 must be a lowercase SHA-256")
    if not isinstance(expected_invalid_line, int) or isinstance(expected_invalid_line, bool) or expected_invalid_line < 1:
        raise ValueError("expected_invalid_line must be a positive integer")
    if os.path.basename(key) != "execution_funnel.jsonl":
        raise ValueError("repair target is restricted to execution_funnel.jsonl")
    if not os.path.isfile(key):
        raise FileNotFoundError("execution_funnel.jsonl is missing")

    current_sha256 = _sha256_file(key)
    if current_sha256 != expected_sha256:
        completed = _completed_jsonl_repair(
            key, expected_sha256, expected_invalid_line, expected_invalid_line_sha256,
        )
        if completed is not None:
            return {**completed, "status": "already_repaired", "idempotent": True}
        raise RuntimeError("SOURCE_SHA256_MISMATCH")

    with open(key, "rb") as handle:
        raw = handle.read()
    raw_lines = raw.splitlines(keepends=True)
    invalid = []
    valid_lines = []
    for line_number, raw_line in enumerate(raw_lines, 1):
        try:
            decoded = raw_line.decode("utf-8")
            if decoded.strip():
                json.loads(decoded)
            valid_lines.append(raw_line)
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            invalid.append({
                "line_number": line_number,
                "raw_sha256": hashlib.sha256(raw_line).hexdigest(),
                "size_bytes": len(raw_line),
                "error_class": type(exc).__name__,
                "classification": "UNKNOWN_CORRUPT_EVIDENCE",
                "ranking_eligible": False,
            })
    invalid_numbers = [row["line_number"] for row in invalid]
    if invalid_numbers != [expected_invalid_line]:
        raise RuntimeError(
            "INVALID_LINE_PRECONDITION_MISMATCH:" + ",".join(map(str, invalid_numbers))
        )
    if invalid[0]["raw_sha256"] != expected_invalid_line_sha256:
        raise RuntimeError("INVALID_LINE_SHA256_MISMATCH")

    quarantine_root = os.path.join(
        os.path.dirname(key), "corrupt_evidence_quarantine",
        datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S_%fZ") + "_repair_" + uuid.uuid4().hex[:8],
    )
    os.makedirs(quarantine_root, exist_ok=False)
    preserved_path = os.path.join(quarantine_root, os.path.basename(key))
    with open(preserved_path, "xb") as handle:
        handle.write(raw)
        handle.flush()
        os.fsync(handle.fileno())
    if _sha256_file(preserved_path) != expected_sha256:
        raise RuntimeError("QUARANTINE_HASH_MISMATCH")

    manifest = {
        "schema": "corrupt_jsonl_quarantine_v2",
        "complete": True,
        "quarantined_at": utc_iso(),
        "source_name": os.path.basename(key),
        "source_sha256": expected_sha256,
        "source_size_bytes": len(raw),
        "preserved_path": os.path.basename(preserved_path),
        "invalid_line_numbers": invalid_numbers,
        "expected_invalid_line_sha256": expected_invalid_line_sha256,
        "valid_line_count": len(valid_lines),
        "excluded_line_count": len(invalid),
    }
    for name, payload in (
        ("quarantine_manifest.json", manifest),
        ("excluded_lines_unknown.json", {
            "schema": "excluded_corrupt_jsonl_lines_v1", "complete": True,
            "qualification": "UNKNOWN", "ranking_eligible": False, "lines": invalid,
        }),
    ):
        target = os.path.join(quarantine_root, name)
        with open(target + ".tmp", "w", encoding="utf-8") as handle:
            json.dump(payload, handle, indent=2, sort_keys=True)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(target + ".tmp", target)

    rebuilt = b"".join(valid_lines)
    rebuilt_sha256 = hashlib.sha256(rebuilt).hexdigest()
    temp_active = key + ".repair.tmp"
    with open(temp_active, "xb") as handle:
        handle.write(rebuilt)
        handle.flush()
        os.fsync(handle.fileno())
    # Recheck the source immediately before the atomic replace. Locks cover all
    # in-process writers; this second hash also refuses external mutations.
    if _sha256_file(key) != expected_sha256:
        os.unlink(temp_active)
        raise RuntimeError("SOURCE_CHANGED_DURING_REPAIR")
    os.replace(temp_active, key)
    _fsync_jsonl_validation_parent(key)
    if _sha256_file(key) != rebuilt_sha256:
        raise RuntimeError("REBUILT_HASH_MISMATCH")
    # Full parse, not merely the durable tail shortcut, proves exact rebuild.
    with open(key, "rb") as handle:
        for line_number, line in enumerate(handle, 1):
            if line.strip():
                json.loads(line.decode("utf-8"))
    signature = _jsonl_validation_signature(key)
    _persist_jsonl_validation_receipt(key, signature)
    receipt = {
        "schema": "jsonl_corruption_repair_receipt_v1",
        "complete": True,
        "status": "repaired",
        "idempotent": False,
        "source_name": os.path.basename(key),
        "source_sha256": expected_sha256,
        "rebuilt_sha256": rebuilt_sha256,
        "source_size_bytes": len(raw),
        "rebuilt_size_bytes": len(rebuilt),
        "valid_line_count": len(valid_lines),
        "excluded_line_count": len(invalid),
        "invalid_line_numbers": invalid_numbers,
        "expected_invalid_line_sha256": expected_invalid_line_sha256,
        "qualification": "UNKNOWN",
        "ranking_eligible": False,
        "validation_receipt": os.path.basename(_jsonl_validation_receipt_path(key)),
        "quarantine_manifest_sha256": _sha256_file(os.path.join(quarantine_root, "quarantine_manifest.json")),
    }
    receipt_path = os.path.join(quarantine_root, "repair_receipt.json")
    with open(receipt_path + ".tmp", "w", encoding="utf-8") as handle:
        json.dump(receipt, handle, indent=2, sort_keys=True)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(receipt_path + ".tmp", receipt_path)
    _fsync_jsonl_validation_parent(receipt_path)
    return receipt


def _safe_append_jsonl(
    path: str, row: dict, label: str = "JSONL", *, fallback_on_error: bool = True,
    outcome: dict | None = None,
):
    """Append one JSONL row with rotation + retries (non-fatal for research logs).

    Existing callers retain the boolean contract. Callers that need telemetry
    classification may supply ``outcome``; admission is still evaluated once.
    """
    terminal_labels = {
        "TRADE_LIFECYCLE", "TRADE_OUTCOME", "FILL_QUALITY", "EXECUTION_SETTINGS",
        "DUPLICATE_INTENT_AUDIT", "COUNTERFACTUAL", "PATH_REPLAY",
        "SIGNAL_REPLAY", "AI_REASON_OUTCOME", "GS_REJECTION_OUTCOME",
    }
    terminal_states = {
        "CLOSED", "CANCELLED", "EXPIRED", "REJECTED", "FULL_FILL", "PARTIAL_FILL",
        "NO_FILL", "NO_TRADE", "REALIZED_PROFIT", "REALIZED_LOSS", "REALIZED_ZERO_PNL",
    }
    row_state = str(
        row.get("outcome_state") or row.get("status") or row.get("event") or ""
    ).upper()
    lifecycle_required = label in terminal_labels or bool(
        row.get("terminal") or row.get("lifecycle_final") or row_state in terminal_states
    )
    lifecycle_existing = False
    trade_id = str(row.get("trade_id") or row.get("order_id") or "")
    try:
        runtime_state = globals().get("state") or {}
        active_rows = [
            *(globals().get("pending_orders") or []),
            *(globals().get("open_positions") or []),
            *(runtime_state.get("pending_orders") or []),
            *(runtime_state.get("positions") or runtime_state.get("open_positions") or []),
        ]
        active_ids = {
            str(item.get("trade_id") or item.get("order_id") or "")
            for item in active_rows if isinstance(item, dict)
        }
        lifecycle_existing = bool((trade_id and trade_id in active_ids) or (
            label == "MARKET_MICROSTRUCTURE_1S" and active_ids
        ))
    except (AttributeError, TypeError):
        lifecycle_existing = False
    admission = emergency_admission(
        data_dir=str(_data_sync_runtime_root()), purpose=f"jsonl:{label}",
        lifecycle_required=lifecycle_required, lifecycle_existing=lifecycle_existing,
    )
    if not admission["allowed"]:
        if outcome is not None:
            outcome["status"] = "ADMISSION_SUPPRESSED"
        logger.warning(
            "[%s] append suppressed: %s used-threshold=%.2f [PIPELINE ENFORCEMENT]",
            label, admission["reason"], admission["threshold"],
        )
        return False
    stamp_epoch = globals().get("_data_epoch_row")
    line = json.dumps(stamp_epoch(path, row) if stamp_epoch else row, default=str) + "\n"
    last_err = None
    # Some contract tests compile this helper in isolation; the path lock still
    # provides their local serialization while production supplies the shared
    # reset barrier.
    research_gate = globals().get("_research_write_gate") or threading.RLock()
    with research_gate, _jsonl_path_lock(path):
        _jsonl_serialized_append_targets.add(os.path.abspath(path))
        for attempt in range(CSV_WRITE_RETRIES):
            try:
                _validate_or_quarantine_jsonl(path, label)
                rotate_log(path)
                with open(path, "a", encoding="utf-8") as f:
                    f.write(line)
                    f.flush()
                    os.fsync(f.fileno())
                try:
                    _persist_jsonl_validation_receipt(
                        path, _jsonl_validation_signature(path)
                    )
                except Exception as receipt_error:
                    # The evidence row is already durable. Never retry it merely
                    # because its acceleration receipt failed; force the next
                    # append through fail-closed historical validation instead.
                    _jsonl_validated_targets.pop(os.path.abspath(path), None)
                    logger.error(
                        f"[{label}] JSONL validation receipt refresh failed ({path}): "
                        f"{receipt_error}; row is durable and will not be retried "
                        "[PIPELINE ENFORCEMENT]"
                    )
                if outcome is not None:
                    outcome["status"] = "WRITTEN"
                return True
            except Exception as e:
                last_err = e
                if attempt < CSV_WRITE_RETRIES - 1 and _transient_csv_lock_error(e):
                    time.sleep(CSV_WRITE_RETRY_BASE_SEC * (attempt + 1))
                    continue
                break
    logger.error(f"[{label}] append failed ({path}): {last_err} [PIPELINE ENFORCEMENT]")
    if fallback_on_error:
        _csv_write_fallback(path, row, last_err)
    if outcome is not None:
        outcome["status"] = "WRITE_FAILED"
    return False


DATA_EPOCH_ID = (os.getenv("DATA_EPOCH_ID") or "").strip() or None
_DATA_EPOCH_MANIFEST: dict | None = None


def _data_epoch_fill_model() -> dict:
    """research/fill_model.py declaration (REALISTIC-FILLS); FILL_MODEL_VERSION env overrides the version."""
    try:
        from research.fill_model import fill_model_declaration
        declaration = dict(fill_model_declaration())
    except Exception:
        declaration = {"fill_model": "unspecified"}
    configured = (os.getenv("FILL_MODEL_VERSION") or "").strip()
    if configured:
        declaration["fill_model"] = configured
    return declaration


def _data_epoch_fingerprint(fill_model: dict) -> dict:
    return _data_epoch.epoch_fingerprint(
        bot_version=EXECUTION_FIX_VERSION, research_stack_version=COMBO_EXECUTION_FIX_VERSION,
        fill_model=fill_model.get("fill_model"), fill_model_fingerprint=fill_model.get("fill_model_fingerprint"),
        collector_fill_model=FILL_MODEL_IDEAL_TOUCH, collector_version=COLLECTOR_VERSION,
        feature_schema_version=FEATURE_SCHEMA_VERSION,
    )


def _open_data_epoch() -> dict | None:
    """Boot hook: open (or keep, across restarts) the clean data epoch named by DATA_EPOCH_ID."""
    global _DATA_EPOCH_MANIFEST
    if not DATA_EPOCH_ID:
        return None
    try:
        fill_model = _data_epoch_fill_model()
        _DATA_EPOCH_MANIFEST = _data_epoch.ensure_runtime_manifest(
            str(_data_sync_runtime_root()), DATA_EPOCH_ID, source_git_rev=_runtime_git_rev(),
            bot_version=EXECUTION_FIX_VERSION,
            segment_prefix=(os.getenv("RESEARCH_SEGMENTS_PREFIX") or "").strip(),
            fill_model=fill_model, fingerprint=_data_epoch_fingerprint(fill_model),
        )
    except (OSError, ValueError) as exc:
        _DATA_EPOCH_MANIFEST = None
        logger.error(f"[DATA EPOCH] cannot open {DATA_EPOCH_ID}: {exc}; rows stay unstamped [PIPELINE ENFORCEMENT]")
        return None
    _data_epoch.activate(_DATA_EPOCH_MANIFEST)
    for _hook_name in ("_archive_pre_epoch_ledgers_on_open", "_bind_epoch_aliases"):
        _hook = globals().get(_hook_name)
        if callable(_hook):
            _hook(_DATA_EPOCH_MANIFEST)
    try:
        import epoch_boundary_rotation
        epoch_boundary_rotation.start_boundary_thread(_data_sync_runtime_root(), _DATA_EPOCH_MANIFEST,
                                                      log=logger.info)
    except Exception as exc:
        logger.error(f"[DATA EPOCH] boundary cutover not started: {exc} [PIPELINE ENFORCEMENT]")
    logger.info(
        f"[DATA EPOCH] {_DATA_EPOCH_MANIFEST['epoch_id']} since {_DATA_EPOCH_MANIFEST['started_at_utc']} "
        "[PIPELINE ENFORCEMENT]"
    )
    return _DATA_EPOCH_MANIFEST


# Boot-time runtime hygiene (moves only; never deletes). Surfaced on /health.
_runtime_hygiene_status: dict = {}
PRE_EPOCH_LEDGER_ARCHIVE_ENABLED = os.getenv("PRE_EPOCH_LEDGER_ARCHIVE", "1").strip().lower() not in {
    "0", "false", "no", "off"}


def _archive_pre_epoch_ledgers_on_open(manifest: dict | None) -> dict | None:
    """Move whole pre-epoch flat ledgers out of the clean epoch before any writer starts.

    Runs synchronously at boot (before restore/load and engine threads). Files
    with any write after the epoch start stay in place for the analyzer guard.
    """
    if not manifest or not PRE_EPOCH_LEDGER_ARCHIVE_ENABLED:
        return None
    try:
        import runtime_hygiene
        doc = runtime_hygiene.archive_pre_epoch_ledgers(_data_sync_runtime_root(), manifest)
    except Exception as exc:
        logger.error(f"[DATA EPOCH] pre-epoch ledger archive failed: {exc} [PIPELINE ENFORCEMENT]")
        _runtime_hygiene_status["pre_epoch_archive"] = {"status": "ERROR", "error": str(exc)[:200]}
        return None
    if doc:
        _runtime_hygiene_status["pre_epoch_archive"] = {
            "epoch_id": doc.get("epoch_id"), "archived": doc.get("archived"),
            "archived_bytes": doc.get("archived_bytes"), "mixed_left_in_place": doc.get("mixed_left_in_place"),
            "archive_dir": doc.get("archive_dir"),
        }
        if doc.get("archived"):
            logger.info(
                f"[DATA EPOCH] archived {len(doc['archived'])} pre-epoch ledgers to {doc.get('archive_dir')} "
                "[PIPELINE ENFORCEMENT]"
            )
    return doc


def _sweep_orphan_runtime_tmp() -> dict | None:
    """Quarantine dead-process atomic-write temp files (provisional/lifecycle/snapshot)."""
    try:
        import runtime_hygiene
        import collector_v22_provisional
        doc = runtime_hygiene.sweep_orphan_tmp(
            _data_sync_runtime_root(), writer_lock=getattr(collector_v22_provisional, "_LOCK", None))
    except Exception as exc:
        logger.warning(f"[RUNTIME HYGIENE] orphan tmp sweep failed: {exc}")
        return None
    _runtime_hygiene_status["orphan_tmp"] = {k: doc.get(k) for k in ("status", "moved_count", "moved_bytes")}
    if doc.get("moved"):
        logger.info(f"[RUNTIME HYGIENE] quarantined {len(doc['moved'])} orphaned temp files")
    return doc


def _compact_evidence_handoff_journals(force: bool = False) -> dict:
    """Archive resolved cancellation/fill handoff rows; unresolved pending rows are kept verbatim."""
    out = {}
    try:
        import runtime_hygiene
    except Exception as exc:
        return {"status": "UNAVAILABLE", "error": str(exc)[:200]}
    terminal = ("APPLIED", "EPOCH_MISMATCH_PRESERVED")
    for kind, path_fn, lock, prefix in (
        ("cancellation", _cancellation_evidence_handoff_path, _cancellation_evidence_handoff_lock,
         "cancellation_evidence_handoff"),
        ("fill", _fill_evidence_handoff_path, _fill_evidence_handoff_lock, "fill_evidence_handoff"),
    ):
        try:
            doc = runtime_hygiene.compact_handoff_journal(
                path_fn(), lock=lock, pending_schema=f"{prefix}_pending_v1",
                result_schema=f"{prefix}_result_v1", terminal_statuses=terminal,
                runtime_root=_data_sync_runtime_root(), force=force,
            )
        except Exception as exc:
            logger.warning(f"[RUNTIME HYGIENE] {kind} handoff compaction failed: {exc}")
            doc = {"status": "ERROR", "error": str(exc)[:200]}
        out[kind] = {k: doc.get(k) for k in ("status", "bytes", "archived_bytes", "unresolved_kept", "archived_to")
                     if doc.get(k) is not None}
        if doc.get("status") == "COMPACTED":
            logger.info(
                f"[RUNTIME HYGIENE] {kind} handoff journal compacted: {doc.get('archived_bytes')} bytes archived, "
                f"{doc.get('unresolved_kept')} unresolved rows kept"
            )
    _runtime_hygiene_status["handoff_compaction"] = out
    return out


def _runtime_hygiene_public() -> dict:
    out = dict(_runtime_hygiene_status)
    stats = globals().get("_cancellation_handoff_seen_stats")
    if isinstance(stats, dict):
        out["cancellation_handoff_duplicates_skipped"] = int(stats.get("duplicates_skipped") or 0)
    return out


def _epoch_alias_ids() -> dict:
    """Derived epoch ids. They are bound into seals/handoff receipts, so they are never rewritten."""
    aliases = {}
    for key, fn in (
        ("collector_v22_epoch_id", lambda: _bound_collection_epoch_id()),
        ("fresh_epoch_id", lambda: _fresh_epoch_identity_from_session()[0]),
    ):
        try:
            aliases[key] = fn() or None
        except Exception:
            aliases[key] = None
    return aliases


def _canonical_epoch_public() -> dict:
    """One canonical epoch id for every consumer: DATA_EPOCH_ID when declared.

    collector_v22_epoch_id (also the research-timing and genome dataset epoch)
    and fresh_epoch_id are aliases, published here and bound in
    data_epoch_boundary/<epoch>.epoch_aliases.json so readers join on one id.
    """
    manifest = globals().get("_DATA_EPOCH_MANIFEST") or {}
    aliases = _epoch_alias_ids()
    canonical, source = manifest.get("epoch_id"), "DATA_EPOCH_ID"
    if not canonical:
        source = "collector_v22_epoch_id" if aliases.get("collector_v22_epoch_id") else (
            "fresh_epoch_id" if aliases.get("fresh_epoch_id") else None)
        canonical = aliases.get(source) if source else None
    return {"canonical_epoch_id": canonical, "source": source,
            "started_at_utc": manifest.get("started_at_utc"), "aliases": aliases}


def _bind_epoch_aliases(manifest: dict | None) -> dict | None:
    """Persist which derived ids belong to the canonical epoch (history kept, never deleted)."""
    if not manifest or not manifest.get("epoch_id"):
        return None
    try:
        path = Path(_data_sync_runtime_root()) / "data_epoch_boundary" / f"{manifest['epoch_id']}.epoch_aliases.json"
        try:
            doc = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            doc = {}
        if not isinstance(doc, dict) or doc.get("canonical_epoch_id") != manifest["epoch_id"]:
            doc = {"schema": "canonical_epoch_aliases_v1", "canonical_epoch_id": manifest["epoch_id"],
                   "started_at_utc": manifest.get("started_at_utc"), "bindings": []}
        aliases = _epoch_alias_ids()
        bindings = doc.setdefault("bindings", [])
        if not bindings or bindings[-1].get("aliases") != aliases:
            bindings.append({"aliases": aliases, "bound_at_ts": time.time(), "boot_id": globals().get("BOT_INSTANCE_ID")})
            _data_epoch.write_json_atomic(path, doc)
        return doc
    except Exception as exc:
        logger.warning(f"[DATA EPOCH] alias binding not written: {exc}")
        return None


def _data_epoch_row(path: str, row):
    manifest = globals().get("_DATA_EPOCH_MANIFEST")
    if not manifest or not isinstance(row, dict):
        return row
    return _data_epoch.stamp(row, manifest["epoch_id"])


def _data_epoch_boundary_status(manifest: dict) -> dict | None:
    if not manifest:
        return None
    try:
        import epoch_boundary_rotation
        root = _data_sync_runtime_root()
        out = {stream: (epoch_boundary_rotation.load_receipt(root, manifest["epoch_id"], stream) or {}).get("status")
               for stream in ("research_events_v22", "v3")}
        plain = epoch_boundary_rotation.load_receipt(root, manifest["epoch_id"], "pre_epoch_archive") or {}
        out["plain_ledgers"] = (f"ARCHIVED_{len(plain.get('archived') or [])}" if plain else None)
        return out
    except Exception:
        return None


def _research_freeze_check(action: str, override=None, lane: str | None = None) -> dict:
    """research_freeze verdict against the live epoch manifest; an override use is logged loudly."""
    verdict = _research_freeze.check(action, globals().get("_DATA_EPOCH_MANIFEST"), time.time(),
                                     override=override, configured_epoch=DATA_EPOCH_ID, lane=lane)
    if verdict.get("override"):
        logger.warning(
            f"[RESEARCH FREEZE] {_research_freeze.FREEZE_ID} override used for {action} lane={lane} "
            f"source={verdict['override']['source']} reason={verdict['override']['reason']!r} [PIPELINE ENFORCEMENT]"
        )
    elif not verdict["allowed"]:
        logger.warning(f"[RESEARCH FREEZE] refused {action} lane={lane} [PIPELINE ENFORCEMENT]")
    return verdict


def _freeze_override_kwargs(data) -> dict:
    """Forward a request-body freeze_override to perform_fresh_collection_reset only when one was sent."""
    override = (data or {}).get("freeze_override") if isinstance(data, dict) else None
    return {"freeze_override": override} if override is not None else {}


def _research_freeze_public() -> dict:
    return _research_freeze.freeze_status(globals().get("_DATA_EPOCH_MANIFEST"), time.time(), DATA_EPOCH_ID)


def _data_epoch_public() -> dict:
    manifest = _DATA_EPOCH_MANIFEST or {}
    return {"declared": bool(manifest), "configured": DATA_EPOCH_ID, "epoch_id": manifest.get("epoch_id"),
            "started_at_utc": manifest.get("started_at_utc"), "stamp_field": _data_epoch.STAMP_FIELD,
            "segment_prefix": manifest.get("segment_prefix"), "fingerprint": manifest.get("fingerprint"),
            "boundary": _data_epoch_boundary_status(manifest),
            "fingerprint_changes": len(manifest.get("fingerprint_changes") or [])}


def _validate_research_ledgers_on_startup():
    """Quarantine known active research corruption before mirror discovery."""
    ledgers = (
        (SHADOW_LANE_OUTCOME_FILE, "SHADOW_LANE_STARTUP"),
        (SIGNAL_REPLAY_FILE, "SIGNAL_REPLAY_STARTUP"),
    )
    for path, label in ledgers:
        with _jsonl_path_lock(path):
            _validate_or_quarantine_jsonl(path, label)

def _port_is_open(host: str, port: int) -> bool:
    import socket
    try:
        with socket.create_connection((host, port), timeout=0.5):
            return True
    except OSError:
        return False

def _ensure_flask_port_available(port: int = None):
    if port is None:
        port = DASHBOARD_PORT
    """Fail fast if another process already serves the dashboard (prevents stale dual-bot state)."""
    if os.name != "nt":
        return
    import sys
    if sys.platform != "win32":
        logger.warning(f"[PORT] {port} appears in use on Linux — continuing (Railway) [PIPELINE ENFORCEMENT]")
        return
    # The process singleton is already held. Avoid a full Windows process/TCP
    # table scan when the socket is plainly free; netstat can take minutes on
    # a busy host and previously turned a successful early-server handoff into
    # a false fatal startup error. If something really answers, retain the
    # fail-closed PID ownership check below.
    if not _port_is_open("127.0.0.1", int(port)):
        return
    try:
        out = subprocess.check_output(
            ["netstat", "-ano"],
            text=True,
            errors="replace",
            timeout=10,
        )
    except Exception as e:
        raise SystemExit(
            f"Port {port} is in use and listener PID could not be resolved ({e}). "
            f"Stop the old bot, then restart from Final Bots."
        ) from e
    me = os.getpid()
    pids = set()
    needle = f":{port}"
    for line in out.splitlines():
        if "LISTENING" not in line or needle not in line:
            continue
        parts = line.split()
        if parts and parts[-1].isdigit():
            pids.add(int(parts[-1]))
    others = sorted(p for p in pids if p != me)
    if others:
        raise SystemExit(
            f"Port {port} already in use by PID(s) {others}. "
            f"Run: taskkill /PID {others[0]} /F  then start one bot from Final Bots."
        )

def _dashboard_request_path_from_head(head: bytes) -> bytes:
    """Extract the origin-form path from one HTTP request-line preview.

    Worker reservation must classify ``/path?query`` exactly like ``/path``.
    Returning an empty path fails safely into the bounded general pool.
    """
    try:
        first_line = bytes(head or b"").split(b"\r\n", 1)[0]
        parts = first_line.split(b" ")
        if len(parts) < 2:
            return b""
        return parts[1].split(b"?", 1)[0]
    except (TypeError, ValueError):
        return b""


def _mount_research_segment_server(flask_app):
    """Serve /api/research-segments/* outside Flask: no hooks, no bot state, no trade lock."""
    try:
        import research_segment_server

        return research_segment_server.mount(flask_app)
    except Exception as exc:
        logger.error(f"[SEGMENTS] segment server not mounted: {type(exc).__name__}: {exc}")
        return flask_app


def _create_dashboard_server():
    """Bind the dashboard socket synchronously so startup fails as one process."""
    _ensure_flask_port_available(DASHBOARD_PORT)
    # Thread-exhaustion OOM prevention: Flask's dev server with threaded=True
    # spawns one uncapped OS thread per request. When /api/state slowed to ~8s,
    # threads piled up to 720+ over ~2h and the bot got hard OOM-killed. We host
    # the app on a bounded werkzeug server instead — at most 8 concurrent request
    # threads (BoundedSemaphore); requests above the cap receive a fast 503 so
    # the accept loop and health endpoint cannot be starved. waitress is NOT
    # available on Python 3.14 here, so we use werkzeug (ships with Flask, no
    # new dependency).
    from werkzeug.serving import ThreadedWSGIServer

    class _BoundedThreadedWSGIServer(ThreadedWSGIServer):
        request_queue_size = 64
        _dispatch_thread_cap = threading.BoundedSemaphore(32)
        _general_thread_cap = threading.BoundedSemaphore(8)
        _canonical_thread_cap = threading.BoundedSemaphore(8)
        _relay_state_thread_cap = threading.BoundedSemaphore(4)
        # The canonical mirror loop and stability supervisor are independent,
        # legitimate readers.  Four reserved workers allow both to overlap
        # with one chunk/ack and one bounded diagnostic without borrowing from
        # presentation traffic or weakening the global dispatch cap.
        _data_sync_thread_cap = threading.BoundedSemaphore(4)
        _data_sync_identity_thread_cap = threading.BoundedSemaphore(2)
        _control_thread_cap = threading.BoundedSemaphore(2)
        # Immutable research-segment files are streamed by a WSGI dispatcher
        # mounted in front of Flask; they never borrow presentation workers.
        _research_segment_thread_cap = threading.BoundedSemaphore(2)
        _research_segment_path_prefix = b"/api/research-segments/"
        _canonical_paths = (
            b"/api/relay-execution-state",
        )
        _relay_state_paths = (
            b"/api/relay-state",
        )
        _data_sync_paths = (
            b"/api/data-sync/manifest",
            b"/api/data-sync/sqlite-snapshot",
            b"/api/data-sync/file",
            b"/api/data-sync/ack",
            b"/api/data-sync/lifecycle-ack",
            b"/api/data-sync/analyzer-report",
            b"/api/data-sync/platform-relay-evidence",
        )
        _data_sync_identity_paths = (
            b"/api/data-sync/identity",
        )
        _control_paths = (
            b"/api/ping",
            b"/api/pause",
            b"/api/resume",
            b"/health",
            b"/ready",
            b"/api/ready",
            b"/api/status",
            b"/status",
        )
        _client_io_timeout_sec = 15.0
        _priority_client_io_timeout_sec = 2.0
        _overload_io_timeout_sec = 0.1
        _slow_request_log_sec = 2.0
        _telemetry_log_interval_sec = 10.0
        _telemetry_log_lock = threading.Lock()
        _telemetry_log_last = {}

        @classmethod
        def _bounded_request_log(
            cls, *, event, path_label, cap_name, reason,
            admission_sec=0.0, handler_sec=0.0,
        ):
            """Rate-limit admission diagnostics without logging URLs or query data."""
            total_sec = max(0.0, admission_sec) + max(0.0, handler_sec)
            if event == "completed" and total_sec < cls._slow_request_log_sec:
                return
            key = (str(event), str(path_label), str(cap_name), str(reason))
            now = time.monotonic()
            with cls._telemetry_log_lock:
                if now - float(cls._telemetry_log_last.get(key) or 0.0) < cls._telemetry_log_interval_sec:
                    return
                cls._telemetry_log_last[key] = now
            logger.warning(
                "[HTTP ADMISSION] event=%s path=%s cap=%s reason=%s "
                "admission_ms=%d handler_ms=%d total_ms=%d",
                event,
                path_label,
                cap_name,
                reason,
                int(max(0.0, admission_sec) * 1000),
                int(max(0.0, handler_sec) * 1000),
                int(total_sec * 1000),
            )

        def _request_cap(self, request):
            """Reserve independent workers for authority and controls.

            Fly, Agent Hub, the relay pusher, and local diagnostics can
            synchronize after a restart. Presentation polls may consume all
            eight general workers and slow tunnel clients may consume relay
            authority workers, but neither may crowd out the operator's safety
            controls.
            """
            try:
                import socket

                request.settimeout(0.05)
                head = request.recv(1024, socket.MSG_PEEK)
                request_path = _dashboard_request_path_from_head(head)
                if request_path in self._control_paths:
                    return self._control_thread_cap, "control", request_path.decode("ascii")
                if request_path in self._canonical_paths:
                    return self._canonical_thread_cap, "canonical", request_path.decode("ascii")
                if request_path in self._relay_state_paths:
                    return self._relay_state_thread_cap, "relay_state", request_path.decode("ascii")
                if request_path in self._data_sync_identity_paths:
                    return self._data_sync_identity_thread_cap, "data_sync_identity", request_path.decode("ascii")
                if request_path in self._data_sync_paths:
                    return self._data_sync_thread_cap, "data_sync", request_path.decode("ascii")
                if request_path.startswith(self._research_segment_path_prefix):
                    return self._research_segment_thread_cap, "research_segments", "RESEARCH_SEGMENTS"
            except (OSError, TimeoutError):
                pass
            # Never log an unrecognized request target: it may contain a token
            # or other operator-supplied path material. Query strings were
            # already stripped above, but GENERAL is the safer bounded label.
            return self._general_thread_cap, "general", "GENERAL"

        def _reject_overload(
            self, request, *, reason, path_label="UNCLASSIFIED",
            cap_name="dispatch", admission_sec=0.0,
        ):
            try:
                _record_overload_rejection(cap_name, reason)
            except Exception:
                pass
            self._bounded_request_log(
                event="rejected",
                path_label=path_label,
                cap_name=cap_name,
                reason=reason,
                admission_sec=admission_sec,
            )
            body = b'{"ok":false,"error":"dashboard_busy","retry_after_sec":1}'
            response = (
                b"HTTP/1.1 503 Service Unavailable\r\n"
                b"Content-Type: application/json; charset=utf-8\r\n"
                + f"Content-Length: {len(body)}\r\n".encode("ascii")
                + b"Connection: close\r\n"
                + b"Retry-After: 1\r\n\r\n"
                + body
            )
            try:
                request.settimeout(self._overload_io_timeout_sec)
                request.sendall(response)
            except (OSError, TimeoutError):
                pass
            finally:
                self.shutdown_request(request)

        def process_request(self, request, client_address):
            # Never inspect client bytes or wait for a destination worker in
            # the single accept loop. Slow tunnel clients previously consumed
            # 50ms here apiece, so a burst delayed even local Pause/relay calls.
            if not self._dispatch_thread_cap.acquire(blocking=False):
                self._reject_overload(request, reason="dispatch_cap_full")
                return
            try:
                t = threading.Thread(
                    target=self._classify_and_process,
                    args=(request, client_address),
                )
                if self.daemon_threads:
                    t.daemon = True
                t.start()
            except Exception:
                self._dispatch_thread_cap.release()
                raise

        def _classify_and_process(self, request, client_address):
            request_cap = None
            request_cap_acquired = False
            cap_name = "unclassified"
            path_label = "UNCLASSIFIED"
            admission_started = time.monotonic()
            handler_started = None
            try:
                request_cap, cap_name, path_label = self._request_cap(request)
                if not request_cap.acquire(blocking=False):
                    self._reject_overload(
                        request,
                        reason="class_cap_full",
                        path_label=path_label,
                        cap_name=cap_name,
                        admission_sec=time.monotonic() - admission_started,
                    )
                    return
                request_cap_acquired = True
                # Bound socket reads/writes. App computation can take longer,
                # but a dead tunnel client cannot retain a worker indefinitely.
                # Segment downloads are multi-megabyte streams to a remote
                # laptop and keep the general per-operation socket timeout.
                is_priority = request_cap not in (
                    self._general_thread_cap, self._research_segment_thread_cap
                )
                request.settimeout(
                    self._priority_client_io_timeout_sec
                    if is_priority
                    else self._client_io_timeout_sec
                )
                handler_started = time.monotonic()
                with _dashboard_handler_lock:
                    _dashboard_active_handlers[threading.get_ident()] = {
                        "started": handler_started,
                        "cap_name": cap_name,
                        "pre_label": path_label,
                        "routed_label": None,
                    }
                self.process_request_thread(request, client_address)
            finally:
                finished = time.monotonic()
                with _dashboard_handler_lock:
                    _dashboard_active_handlers.pop(threading.get_ident(), None)
                if handler_started is not None:
                    self._bounded_request_log(
                        event="completed",
                        path_label=path_label,
                        cap_name=cap_name,
                        reason="slow_handler",
                        admission_sec=handler_started - admission_started,
                        handler_sec=finished - handler_started,
                    )
                if request_cap_acquired:
                    request_cap.release()
                self._dispatch_thread_cap.release()

    try:
        httpd = _BoundedThreadedWSGIServer(
            host=DASHBOARD_BIND_HOST, port=DASHBOARD_PORT,
            app=_mount_research_segment_server(app),
        )
    except Exception as e:
        logger.error(f"[FLASK] failed to bind {DASHBOARD_BIND_HOST}:{DASHBOARD_PORT}: {e}")
        raise SystemExit(1)
    return httpd


def run_flask(httpd):
    logger.info(
        f"[FLASK] Serving dashboard on {DASHBOARD_BIND_HOST}:{DASHBOARD_PORT} "
        f"(bounded werkzeug server, general_threads=8, canonical_threads=8, "
        f"relay_state_threads=4, data_sync_threads=4, control_threads=2, backlog=64) "
        "[PIPELINE ENFORCEMENT]"
    )
    try:
        httpd.serve_forever()
    except Exception as e:
        logger.error(f"[FLASK] server error: {e}")
        raise SystemExit(1)

def ttl_monitor():
    global _last_fresh_maintain_ts, _last_lane_memory_check_ts
    logger.info("[TTL] Independent monitor started")
    while not shutdown_event.is_set():
        try:
            prune_signals()
            cleanup_expired_orders()
            now = time.time()
            if now - _last_lane_memory_check_ts >= LANE_MEMORY_CHECK_INTERVAL_SEC:
                _last_lane_memory_check_ts = now
                lm = validate_lane_memory()
                ri = validate_runtime_pathway_integrity()
                # The dashboard intentionally rejects contract receipts older
                # than one hour. Re-evaluate immutable startup invariants on the
                # same ten-minute cadence so a healthy long-running process does
                # not regress to a stale receipt solely because it stayed up.
                publish_startup_pathway_receipts()
                apply_pathway_safety_block(lm, ri)
            if state.get("fresh_collection_mode"):
                if now - _last_fresh_maintain_ts >= FRESH_COLLECTION_MAINTAIN_INTERVAL_SEC:
                    _last_fresh_maintain_ts = now
                    maintain_fresh_collection_files()
            time.sleep(30)
        except Exception as e:
            logger.error(f"[TTL] ERROR: {e}")
            time.sleep(5)

def system_health_check():
    now = time.time()
    runtime = _recompute_system_readiness(now)
    market_health = _market_data_health_snapshot(now)
    healthy = bool(runtime["system_ready"])
    recover_reason = ""
    should_hard_stop = False
    freshest_observed_age = None
    with state_lock:
        current_reason = str(state.get("execution_reason") or "")
        manual_paused = bool(state.get("manual_admin_pause"))
        observed_ages = [
            age
            for age in (
                market_health.get("ws_age"),
                market_health.get("rest_age"),
                market_health.get("price_age"),
            )
            if age is not None
        ]
        if observed_ages:
            freshest_observed_age = min(observed_ages)
        if (
            market_health["market_data_ready"]
            and not manual_paused
            and current_reason in (
                "WS_STALE",
                "STALE_DATA_HARD_STOP",
                "PRICE_STALE_OR_MISSING",
            )
        ):
            recover_reason = current_reason
        elif (
            not market_health["market_data_ready"]
            and freshest_observed_age is not None
            and freshest_observed_age >= STALE_HARD_SEC
            and not manual_paused
        ):
            should_hard_stop = True
    if recover_reason:
        _clear_execution_pause_if_reason(recover_reason)
        logger.info(
            f"[RECOVERY] market-data path restored via "
            f"{market_health['market_data_mode']}; cleared {recover_reason} "
            f"[PIPELINE ENFORCEMENT]"
        )
    elif should_hard_stop:
        set_execution_paused("STALE_DATA_HARD_STOP")
        logger.error(
            f"[HARD STOP] ALL MARKET DATA STALE "
            f"freshest_age={fmt(freshest_observed_age)}s - new entries paused"
        )
    if not healthy:
        logger.warning(
            f"[HEALTH] NOT READY reasons={runtime['readiness_reasons']} "
            f"ws={runtime['ws_transport_ready']} price={runtime['price_ready']} "
            f"candle={runtime['candle_ready']}"
        )
    else:
        logger.info("[HEALTH] OK")
    return healthy

def startup_hard_fix_ai_threshold():
    with state_lock:
        research = state.get("strategy_mode") == "RESEARCH"
        if "ai_threshold" in state:
            state["ai_threshold"] = _clamp_ai_threshold(state["ai_threshold"])
            return
        default = RESEARCH_AI_THRESHOLD_DEFAULT if research else LIVE_AI_THRESHOLD_FLOOR
        state["ai_threshold"] = default
        save_persistent_config()
        logger.info(
            f"[INIT] AI threshold default {default} "
            f"({'research flexible 0-100' if research else 'live suggested floor'}) "
            f"[PIPELINE ENFORCEMENT]"
        )

