    if time.time() - last_console_update < 10:
        return
    last_console_update = time.time()
    exposure = get_active_signal_count()
    with trade_lock:
        pending_pending = len([o for o in pending_orders if o.get("status") == "PENDING"])
        pending_all = len(pending_orders)
